window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["公安部"] = {"linshijuminshenfenzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国居民身份证法》第十二条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"居住在中华人民共和国境内的中国公民，在申请领取换领、补领居民身份证期间，急需使用居民身份证的，可以申请领取临时居民身份证。"},{"i":3,"n":"第三条","txt":"临时居民身份证具有证明公民身份的法律效力。"},{"i":4,"n":"第四条","txt":"临时居民身份证式样为聚酯薄膜密封的单页卡式，证件采用国际通用标准尺寸，彩虹印刷，正面印有证件名称和长城图案背面登载公民本人黑白照片和身份项目。"},{"i":5,"n":"第五条","txt":"临时居民身份证登记的项目包括：姓名、性别、民族、出生日期、常住户口所在地住址、公民身份号码、本人相片、证件的有效期和签发机关。"},{"i":6,"n":"第六条","txt":"临时居民身份证使用规范汉字和符合国家标准的数字符号填写。 民族自治地方的自治机关根据本地区的实际情况，可以决定同时使用实行区域自治的民族的文字或者选用一种当地通用的文字。"},{"i":7,"n":"第七条","txt":"临时居民身份证的有效期限为三个月，有效期限自签发之日起计算。"},{"i":8,"n":"第八条","txt":"临时居民身份证由县级人民政府公安机关统一制发、管理。"},{"i":9,"n":"第九条","txt":"具备本办法第二条规定条件的公民，可以向常住户口所在地的公安派出所申请领取临时居民身份证。 未满十六周岁的公民，由监护人代为申领临时居民身份证。"},{"i":10,"n":"第十条","txt":"临时居民身份证由公民常住户口所在地的县级人民政府公安机关签发。"},{"i":11,"n":"第十一条","txt":"公民申领临时居民身份证，应当交验居民户口簿、本人近期一寸免冠黑白相片，并在其《居民身份证申领登记表》中加以注明。"},{"i":12,"n":"第十二条","txt":"公民申请领取、换领、补领临时居民身份证时，公安机关应当按照本办法的规定及时办理，并在收到申请后的三日内将临时居民身份证发给申领人。"},{"i":13,"n":"第十三条","txt":"领取了临时居民身份证的公民在领取居民身份证时，应当交回临时居民身份证。"},{"i":14,"n":"第十四条","txt":"公民从事有关活动，需要证明身份的，有权使用临时居民身份证证明身份。有关单位及其工作人员不得拒绝。"},{"i":15,"n":"第十五条","txt":"人民警察依法执行职务，有权依照《中华人民共和国居民身份证法》第十五条的规定，查验公民的临时居民身份证，被查验的公民不得拒绝。"},{"i":16,"n":"第十六条","txt":"违反本规定的，依照《中华人民共和国居民身份证法》第四章的有关规定予以处罚。"},{"i":17,"n":"第十七条","txt":"公民申请领取、换领、补领临时居民身份证，应当缴纳证件工本费。临时居民身份证工本费标准，由公安部会同国务院价格主管部门、财政部门核定。 公安机关收取的临时居民身份证工本费，全部上缴国库。"},{"i":18,"n":"第十八条","txt":"对公民交回和收缴的临时居民身份证，公安机关应当登记后销毁。"},{"i":19,"n":"第十九条","txt":"本办法自2005年10月1日起施行，公安部1989年9月15日发布的《临时身份证管理暂行规定》同时废止。"}],"putonghuzhaohechurujingtongxingzhengqianfaguanliba4c9b49":[{"i":1,"n":"第一条","txt":"为了规范中华人民共和国普通护照和出入境通行证的申请、审批签发和管理，保障中华人民共和国公民申请普通护照和出入境通行证的权利，根据《中华人民共和国护照法》（以下简称护照法）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公民向公安机关出入境管理机构申请普通护照和出入境通行证。"},{"i":3,"n":"第三条","txt":"公安机关出入境管理机构应当参照国际技术标准，逐步推广签发含有电子芯片的普通护照（以下简称电子普通护照），提高护照的防伪性能。 电子芯片存储普通护照的登记项目资料和持证人的面部肖像、指纹信息等。"},{"i":4,"n":"第四条","txt":"公民申请普通护照，应当由本人向其户籍所在地县级以上地方人民政府公安机关出入境管理机构提出，并提交下列真实有效的材料： （一）近期免冠照片一张以及填写完整的《中国公民因私出国（境）申请表》（以下简称申请表）； （二）居民身份证和户口簿及复印件；在居民身份证领取、换领、补领期间，可以提交临时居民身份证和户口簿及复印件； （三）未满十六周岁的公民，应当由其监护人陪同，并提交其监护人出具的同意出境的意见、监护人的居民身份证或者户口簿、护照及复印件； （四）国家工作人员应当按照有关规定，提交本人所属工作单位或者上级主管单位按照人事管理权限审批后出具的同意出境的证明； （五）省级地方人民政府公安机关出入境管理机构报经公安部出入境管理机构批准，要求提交的其他材料。 现役军人申请普通护照，按照管理权限履行报批手续后，由本人向所属部队驻地县级以上地方人民政府公安机关出入境管理机构提出。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，公民可以向其户籍所在地县级以上地方人民政府公安机关出入境管理机构申请加急办理普通护照，并提交相应材料： （一）出国奔丧、探望危重病人的； （二）出国留学的开学日期临近的； （三）前往国入境许可或者签证有效期即将届满的； （四）省级地方人民政府公安机关出入境管理机构认可的其他紧急事由。"},{"i":6,"n":"第六条","txt":"公安机关出入境管理机构受理十六周岁以上公民的电子普通护照申请，应当现场采集申请人的指纹信息。不满十六周岁的公民申请电子普通护照，监护人同意提供申请人指纹信息的，公安机关出入境管理机构可以现场采集。 申请人因指纹缺失、损坏无法按捺指纹的，可以不采集指纹信息。"},{"i":7,"n":"第七条","txt":"公安机关出入境管理机构收到申请材料后，应当询问申请人。对申请材料齐全且符合法定形式的，应当当场受理；对申请材料不齐全或者不符合法定形式的，应当一次告知申请人需要补正的全部内容。"},{"i":8,"n":"第八条","txt":"公安机关出入境管理机构受理普通护照的申请后，应当将申请材料报送具有审批签发权的公安机关出入境管理机构进行审批。对符合签发规定的，以公安部出入境管理机构的名义签发普通护照；对不符合规定不予签发的，应当向申请人书面说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":9,"n":"第九条","txt":"普通护照持有人具有下列情形之一的，可以向其户籍所在地县级以上地方人民政府公安机关出入境管理机构申请变更加注，并提交普通护照及复印件以及需要作变更加注事项的证明材料： （一）有曾用名、繁体汉字姓名、外文姓名或者非标准汉语拼音姓名的； （二）相貌发生较大变化，需要作近期照片加注的； （三）公安部出入境管理机构认可的其他情形。"},{"i":10,"n":"第十条","txt":"具有下列情形之一的，普通护照持有人可以向其户籍所在地县级以上地方人民政府公安机关出入境管理机构申请换发普通护照： （一）签证页即将使用完毕的； （二）有效期不足六个月的，或者有效期在六个月以上但有材料证明该有效期不符合前往国要求的； （三）公安部出入境管理机构认可的其他情形。"},{"i":11,"n":"第十一条","txt":"公民申请换发普通护照，除提交本办法第四条规定的材料外，应当提交原普通护照及复印件。 定居国外的公民短期回国申请换发普通护照的，应当向其暂住地县级以上地方人民政府公安机关出入境管理机构提出，并提交原普通护照、定居国外的证明以及暂住地公安机关出具的暂住证明及复印件。"},{"i":12,"n":"第十二条","txt":"普通护照损毁、遗失、被盗的，公民可以向其户籍所在地县级以上地方人民政府公安机关出入境管理机构申请补发。申请时，除提交本办法第四条规定的材料外，应当提交相关材料： （一）因证件损毁申请补发的，提交损毁的证件及损毁原因说明； （二）因证件遗失或者被盗申请补发的，提交报失证明和遗失或者被盗情况说明。 定居国外的公民短期回国申请补发普通护照，应当向其暂住地县级以上地方人民政府公安机关出入境管理机构提出，除应当按照前款提交相应材料外，应当提交定居国外的证明以及暂住地公安机关出具的暂住证明及复印件。"},{"i":13,"n":"第十三条","txt":"公安机关出入境管理机构为公民换发、补发普通护照时，应当宣布原普通护照作废。换发普通护照时，应当将公民原普通护照右上角裁去；原普通护照上有前往国有效入境许可的，可将封底、封面右上角裁去，退还本人。"},{"i":14,"n":"第十四条","txt":"公民申请普通护照或者申请普通护照变更加注、换发、补发的，公安机关出入境管理机构应当自收到申请材料之日起十五日内签发。有本办法第五条规定情形的，公安机关出入境管理机构应当自收到申请材料之日起五个工作日内签发。 在偏远地区或者交通不便地区或者因特殊情况，不能按期签发普通护照的，经省级地方人民政府公安机关出入境管理机构负责人批准，签发时间可以延长至三十日。偏远地区或者交通不便地区的范围由省级地方人民政府公安机关出入境管理机构确定，报公安部出入境管理机构备案后对外公布。"},{"i":15,"n":"第十五条","txt":"电子普通护照采取加密措施，确保电子芯片存储的指纹信息仅限于普通护照签发机关和出入境边防检查机关在出入境管理时读取、核验和使用。"},{"i":16,"n":"第十六条","txt":"普通护照签发机关、出入境边防检查机关及其工作人员对在出入境管理工作中知悉的公民个人信息，应当予以保密。"},{"i":17,"n":"第十七条","txt":"申请人具有下列情形之一的，公安机关出入境管理机构不予签发普通护照： （一）不具有中华人民共和国国籍的； （二）无法证明身份的； （三）在申请过程中弄虚作假的； （四）被判处刑罚正在服刑的； （五）人民法院通知有未了结的民事案件不能出境的； （六）属于刑事案件被告人或者犯罪嫌疑人的； （七）国务院有关主管部门认为出境后将对国家安全造成危害或者对国家利益造成重大损失的。 公民因妨害国（边）境管理受到刑事处罚或者因非法出境、非法居留、非法就业被遣返回国的，公安机关出入境管理机构自其刑罚执行完毕或者被遣返回国之日起六个月至三年以内不予签发普通护照。"},{"i":18,"n":"第十八条","txt":"公安机关出入境管理机构签发普通护照后，发现持照人具有本办法第十七条规定情形的，可以宣布其所持普通护照作废。"},{"i":19,"n":"第十九条","txt":"宣布公安机关出入境管理机构签发的普通护照作废，由普通护照的审批签发机关或者上级公安机关出入境管理机构作出。"},{"i":20,"n":"第二十条","txt":"公民从事边境贸易、边境旅游服务或者参加经国务院或者国务院主管部门批准的边境旅游线路边境旅游的，可以由本人向边境地区县级以上地方人民政府公安机关出入境管理机构申请出入境通行证，并从公安部规定的口岸出入境。 公民从事边境贸易、边境旅游服务的，可为其签发一年多次出入境有效或者三个月一次出入境有效的出入境通行证；公民参加经国务院或者国务院主管部门批准的边境旅游线路边境旅游的，可为其签发三个月一次出入境有效的出入境通行证。"},{"i":21,"n":"第二十一条","txt":"边境地区公民申请出入境通行证，应当提交本办法第四条规定的材料。 非边境地区公民申请出入境通行证，应当提交本办法第四条第一款第（一）、（三）、（四）、（五）项规定的材料，居民身份证或者户口簿及复印件，以及下列与申请事由相关的证明材料： （一）从事边境贸易的，提交在边境地区工商行政管理部门登记注册的经营者出具的有关证明材料； （二）从事边境旅游服务的，提交所在的经国家旅游局批准的边境旅游组团社出具的证明材料和本人导游证； （三）参加边境旅游的，提交经国家旅游局批准的边境旅游组团社出具的相关材料。"},{"i":22,"n":"第二十二条","txt":"边境地区公安机关出入境管理机构应当对公民提交的出入境通行证申请材料进行审核。对非边境地区公民提交的申请材料有疑问的，应当向其户籍所在地公安机关出入境管理机构或者其所属工作单位核实。"},{"i":23,"n":"第二十三条","txt":"出入境通行证不予变更加注或者换发。除一年多次出入境有效的出入境通行证外，出入境通行证不予补发。"},{"i":24,"n":"第二十四条","txt":"对公民具有本办法第十七条规定情形之一的，公安机关出入境管理机构不予签发出入境通行证。"},{"i":25,"n":"第二十五条","txt":"公民领取普通护照、出入境通行证后，应当在持证人签名栏签署本人姓名。"},{"i":26,"n":"第二十六条","txt":"公民退出中国国籍的，应当将所持普通护照、出入境通行证交还公安机关出入境管理机构或者中华人民共和国驻外使馆、领馆或者外交部委托的其他驻外机构。公民持《前往港澳通行证》赴港澳地区定居的，应当将所持普通护照交还公安机关出入境管理机构。"},{"i":27,"n":"第二十七条","txt":"公民在申请、换发、补发普通护照以及申请变更加注时，提交虚假或者通过非法途径获取的材料的，或者冒用他人身份证件骗取普通护照的，依照护照法第十七条的规定处理。"},{"i":28,"n":"第二十八条","txt":"公安机关出入境管理机构应当将申请普通护照、出入境通行证的依据、条件、程序、时限、收费标准以及需要提交的全部材料的目录和申请表示范文本等在接待场所公布。"},{"i":29,"n":"第二十九条","txt":"出入境通行证的受理和审批签发程序、签发时限、宣布作废、收缴、式样制定和监制，以及对相关违法行为的处罚等参照普通护照的有关规定执行。"},{"i":30,"n":"第三十条","txt":"受理、审批签发普通护照、出入境通行证的公安机关出入境管理机构应当经公安部确定，并向社会公布。对具有下列情形之一的公安机关出入境管理机构，公安部可以暂停或者终止其普通护照、出入境通行证受理、审批签发权，并确定代为行使受理、审批签发权的公安机关出入境管理机构： （一）因情况变化不再具备受理、审批签发普通护照、出入境通行证条件的； （二）违法违规受理、审批签发普通护照、出入境通行证的； （三）公安部规定的其他应当暂停或者终止受理、审批签发权的情形。"},{"i":31,"n":"第三十一条","txt":"当毗邻国家的边境地区发生恐怖活动、瘟疫或者重大自然灾害以及出现公安部规定的其他情形的，公安部可以暂停或者终止边境地区公安机关出入境管理机构为非边境地区公民签发出入境通行证。"},{"i":32,"n":"第三十二条","txt":"公安机关出入境管理机构应当严格按照国务院价格行政部门会同国务院财政部门规定的标准，收取普通护照、出入境通行证的办证费用。"},{"i":33,"n":"第三十三条","txt":"本办法自2012年3月1日起施行。2007年10月25日发布的《中华人民共和国普通护照和出入境通行证签发管理办法》（公安部令第96号）同时废止。本办法施行前公安部制定的有关规定与本办法不一致的，以本办法为准。"}],"bianjingguanliqutongxingzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强边境通行证件的管理，维护边境管理区的 治安秩序，根据国家有关规定，结合我国边防管理的实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"国家在陆地边境地区划定边境管理（含深圳、珠海 经济特区），实行《中华人民共和国边境管理区通行证》（以下简称《边境通行证》）验查管理制度。"},{"i":3,"n":"第三条","txt":"凡进出边境管理区的人员，均适用本办法。"},{"i":4,"n":"第四条","txt":"公安部边防管理局是全国《边境通行证》的主管部 门。各省、自治区、直辖市公安厅、局负责本行政区域内的《边境通行证》管理工作。"},{"i":5,"n":"第五条","txt":"凡常住边境管理区年满16周岁的中国公民，凭《中华人民共和国居民身份证》（以下简称《居民身份证》）在本省、自治区的边境管理区通行；前往其他省、自治区的边境管理区，须持《边境通行证》。"},{"i":6,"n":"第六条","txt":"凡居住在非边境管理区年满16周岁的中国公民，前往边境管理区，须持《边境通行证》。"},{"i":7,"n":"第七条","txt":"凡经由边境管理区出入国（边境）的人员，凭其出入境有效证件通行。 外国人、无国籍人前往未对外国人开放的边境管理区，须持公安机关签发《中华人民共和国外国人旅行证》。 海外华侨、港澳台同胞前往未对外国人开放的边境管理区，须持《边境通行证》。"},{"i":8,"n":"第八条","txt":"中国人民解放军和中国人民武装警察部队官兵进出边境管理区，须分别持《中国人民解放军军人通行证》、《中国人民武装警察通行证》和本人有效证件；驻在边境管理区内的中国人民解放军和中国人民武装警察部队官兵，凭本人有效证件进出边境管理区。"},{"i":9,"n":"第九条","txt":"凡年满16周岁的中国公民前往边境管理区，依照本办法第二章之规定，具有下列情形之一的，应当申领《边境通行证》： （一）参加科技、文化、体育交流或业务培训、会议、从事采访、创作等活动； （二）从事勘探、承包工程、劳务、生产技术合作或者贸易洽谈等活动的； （三）应聘、调动、分配工作或者就医、就学的； （四）探亲、访友、经商、旅游的； （五）有其他正当事由必须前往的。"},{"i":10,"n":"第十条","txt":"申领《边境通行证》应当向常住户口所在地县级以上公安机关或者指定的公安派出所提出申请。有下列情形之一，凭单位证明，可以向非常住户口所在地的县级以上公安机关或指定的公安派出所提出申请： （一）常住户口所在地与工作单位所在地同一城市，但不在同一辖区的人员； （二）中央各部委和省级人民政府的驻外办事处人员； （三）已在非常住户口所在地暂住一年以上的人员； （四）因工作调动，尚未办妥常住或暂住户口的人员； （五）因紧急公务，确需前往边境管理区的国家工作人员。"},{"i":11,"n":"第十一条","txt":"海外华侨、港澳台同胞凭有效证件向有关省、自治区、直辖市公安厅、局，或者县、市公安局申领《边境通行证》。"},{"i":12,"n":"第十二条","txt":"经省级公安、旅游部门批准，旅游公司组织赴边境管理区旅游的人员，应当在出发地的公安机关办理《边境通行证》。"},{"i":13,"n":"第十三条","txt":"申请领取《边境通行证》的人员应当填写《边境通行申请表》；交验本人《居民身份证》或其他有效证件，并履行下列手续： （一）机关、团体、事业单位人员由单位保卫（人事）部门提出审核意见； （二）企业单位设保卫部门的，由保卫部门提出审核意见；未设保卫部门的，由企业法人提出审核意见； （三）其他人员由常住户口所在地的公安派出所或者乡镇人民政府提出审核意见； （四）已在边境管理区务工的人员还应当出具劳动部门的聘用合同和用工单位证明。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，公安机关不予受理： （一）刑事案件的被告人和公安机关、国家安全机关、人民检察院或者人民法院认定有犯罪嫌疑的人员； （二）被判处刑罚正在服刑的人员； （三）公安机关认为不宜前往边境管理区的人员。"},{"i":15,"n":"第十七条","txt":"签发《边境通行证》一律用黑色墨水填写或使用微机填写，字迹工整，项目填写全面，不得涂改，并加盖发证机关的行政印章或者边境通行证专用章。"},{"i":16,"n":"第十八条","txt":"《边境通行证》实行一人一证，并与《居民身份证》同时使用。对不满16周岁的未成年人不单独签发证件，可与持证人偕行，但不得超过二人。"},{"i":17,"n":"第十九条","txt":"《边境通行证》的有效期不得超过三个月，可多次往返使用；对常住或者经常入出边境管理区的人员，其证件有效期最长可到一年。"},{"i":18,"n":"第二十条","txt":"《边境通行证》有效期满后，持证人应当向原发证机关缴销证件。证件存根、缴销的旧证件及《边境通行证申请表》的保存期为两年，销毁时应登记造册。"},{"i":19,"n":"第二十一条","txt":"前往边境管理区的人员须持本办法第二章规定的有效证件，经边防公安检查站、铁路公安部门查验后，才能进入边境管理区。"},{"i":20,"n":"第二十二条","txt":"有下列情形之一的，边防公安检查站、铁路公安部门有权阻止进人边境管理区： （一）未持边境通行证件的； （二）持过期、失效边境通行证件的。 （三）持伪造、涂改的《边境通行证》、冒用他人《边境通行证》或者其他证件的； （四）《边境通行证》未与《居民身份证》同时使用或者与假 《居民身份证》同时使用的。 （五）拒绝接受查验证件的。"},{"i":21,"n":"第二十三条","txt":"对违反本办法规定的处罚由边防公安检查站或者县级以上公安机关执行。"},{"i":22,"n":"第二十四条","txt":"持用伪造、涂改、过期、失效的《边境通行证》 或者冒用他人《边境通行证 》的，除收缴其证件外，应当视情节给予警告或者处以 100 元以下罚款。"},{"i":23,"n":"第二十五条","txt":"对伪造、涂改、盗窃、贩卖《边境通行证》 的，除收缴其证件外，处1000 元以下罚款；情节严重构成犯罪的．依法追究刑事责任。"},{"i":24,"n":"第二十六条","txt":"拒绝、阻碍公安机关检查验证人员依法执行公务，未使用暴力、威胁方法的，依照《中华人民共和国治安管理处罚条例》的规定处罚。"},{"i":25,"n":"第二十七条","txt":"公安机关工作人员在执行本办法时，如有利用职权索取贿赂或者其他违法行为，情节轻微的，由主管部门予以行政处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十八条","txt":"公安机关签发《边境通行证》，必须严格执行收费标准，使用财政部统一印制的证件收费收据。证件收费应当坚持专款专用、收支两条线的规定。"},{"i":27,"n":"第二十九条","txt":"《边境通行证》式样由公安部制定，并统一印制。"},{"i":28,"n":"第三十条","txt":"本办法自发布之日起施行。"}],"linshirujingjidongchehejiashirenguanliguiding":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国道路交通安全法》及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于下列临时进入中华人民共和国境内不超过三个月的机动车和机动车驾驶人： （一）经国家主管部门批准，临时入境参加有组织的旅游、比赛以及其他交往活动的外国机动车和机动车驾驶人； （二）临时入境后仅在边境地区一定范围内行驶的外国机动车和机动车驾驶人； （三）临时入境后需驾驶租赁的中国机动车的外国机动车驾驶人。 与中国签订有双边或者多边过境运输协定的，按照协定办理。国家或者政府之间对机动车牌证和驾驶证有互相认可协议的，按照协议办理。"},{"i":3,"n":"第三条","txt":"外国机动车临时入境行驶，应当向入境地或者始发地所在的直辖市或者设区的市公安机关交通管理部门申领临时入境机动车号牌和行驶证。"},{"i":4,"n":"第四条","txt":"申请临时入境机动车号牌、行驶证的，应当用中文填写《临时入境机动车号牌、行驶证申请表》，交验机动车，并提交以下证明、凭证： （一）境外主管部门核发的机动车登记证明，属于非中文表述的，还应当出具中文翻译文本； （二）中国海关等部门出具的准许机动车入境的凭证； （三）属于有组织的旅游、比赛以及其他交往活动的，还应当提交中国相关主管部门出具的证明； （四）机动车安全技术检验合格证明，属于境外主管部门核发的，还应当出具中文翻译文本； （五）不少于临时入境期限的中国机动车交通事故责任强制保险凭证。 公安机关交通管理部门应当在收到申请材料之日起三日内审查提交的证明、凭证，查验机动车。符合规定的，核发临时入境机动车号牌和行驶证。"},{"i":5,"n":"第五条","txt":"临时入境机动车号牌为纸质号牌，载明允许行驶的区域、线路和有效期。 临时入境机动车号牌背面为临时入境机动车行驶证，签注车辆类型、号牌号码、厂牌型号、行驶区域或者线路、有效期等信息。"},{"i":6,"n":"第六条","txt":"临时入境机动车号牌和行驶证有效期应当与入境批准文件上签注的期限一致，但最长不得超过三个月。临时入境机动车号牌和行驶证有效期不得延期。"},{"i":7,"n":"第七条","txt":"临时入境汽车号牌应当放置在前挡风玻璃内右侧。临时入境摩托车号牌应当随车携带，以备检查。"},{"i":8,"n":"第八条","txt":"临时入境的外国机动车，可以凭入境凭证行驶至本规定第三条规定的临时入境机动车号牌和行驶证核发机关所在地，并于入境后二日内申请临时入境机动车号牌和行驶证。"},{"i":9,"n":"第九条","txt":"临时入境的境外机动车驾驶人，可以驾驶其自带的临时入境的机动车或者租赁的中国机动车。"},{"i":10,"n":"第十条","txt":"临时入境的机动车驾驶人在中国道路上驾驶自带临时入境的机动车，应当向入境地或者始发地所在的直辖市或者设区的市公安机关交通管理部门申领临时机动车驾驶许可。"},{"i":11,"n":"第十一条","txt":"临时入境的机动车驾驶人驾驶租赁的中国机动车，应当向机动车租赁单位所在的直辖市或者设区的市公安机关交通管理部门申领临时机动车驾驶许可。"},{"i":12,"n":"第十二条","txt":"临时机动车驾驶许可的准驾车型应当符合申请人所持境外机动车驾驶证的准驾车型。驾驶自带临时入境机动车的，临时机动车驾驶许可的准驾车型还应当与其自带机动车车型一致。驾驶租赁中国机动车的，临时机动车驾驶许可的准驾车型为小型汽车和小型自动挡汽车。"},{"i":13,"n":"第十三条","txt":"申领临时机动车驾驶许可的，应当用中文填写《临时机动车驾驶许可申请表》，提交下列证明、凭证： （一）入出境身份证件； （二）境外机动车驾驶证，属于非中文表述的，还应当出具中文翻译文本； （三）年龄、身体条件符合中国驾驶许可条件的证明文件； （四）两张一寸彩色照片（近期半身免冠正面白底）； （五）参加有组织的旅游、比赛以及其他交往活动的，还应当提交中国相关主管部门出具的证明。 公安机关交通管理部门应当在收到申请材料之日起三日内进行审查，符合规定的，组织道路交通安全法律、法规学习，核发临时机动车驾驶许可。"},{"i":14,"n":"第十四条","txt":"临时机动车驾驶许可有效期截止日期应当与机动车驾驶人入出境身份证件上签注的准许入境期限的截止日期一致，但有效期最长不超过三个月。临时机动车驾驶许可有效期不得延期。"},{"i":15,"n":"第十五条","txt":"临时机动车驾驶许可应当随身携带，并与所持境外机动车驾驶证及其中文翻译文本同时使用。"},{"i":16,"n":"第十六条","txt":"临时入境的机动车驾驶人，可以凭所持境外机动车驾驶证和入境凭证，驾驶自带机动车行驶至本规定第十条规定的临时机动车驾驶许可核发机关所在地，并于入境后二日内申请临时机动车驾驶许可。"},{"i":17,"n":"第十七条","txt":"公安机关交通管理部门核发临时入境机动车号牌、行驶证和临时机动车驾驶许可时，应当对境外机动车和机动车驾驶人以前的入境记录进行核查，发现有道路交通违法行为和交通事故未处理完毕的，告知其处理完毕后再核发牌证；在中国境内有驾驶机动车交通肇事逃逸记录的，不予核发临时机动车驾驶许可。"},{"i":18,"n":"第十八条","txt":"临时入境的机动车驾驶人应当按照下列规定驾驶机动车： （一）遵守中国的道路交通安全法律、法规及规章； （二）按照临时入境机动车号牌上签注的行驶区域或者路线行驶； （三）遇有交通警察检查的，应当停车接受检查，出示入出境证件、临时机动车驾驶许可和所持境外机动车驾驶证及其中文翻译文本； （四）违反道路交通安全法律、法规的，应当依法接受中国公安机关交通管理部门的处理； （五）发生交通事故的，应当立即停车，保护现场，抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门，依法接受中国公安机关交通管理部门的处理。"},{"i":19,"n":"第十九条","txt":"临时入境的机动车驾驶人有下列行为之一的，公安机关交通管理部门应当按照下列规定处理： （一）未取得临时机动车驾驶许可驾驶机动车，或者临时机动车驾驶许可超过有效期驾驶机动车的，按照《中华人民共和国道路交通安全法》第九十九条处理； （二）驾驶未取得临时入境机动车号牌和行驶证的机动车，或者驾驶临时入境机动车号牌和行驶证超过有效期的机动车的，按照《中华人民共和国道路交通安全法》第九十五条处理； （三）驾驶临时入境的机动车超出行驶区域或者路线的，按照《中华人民共和国道路交通安全法》第九十条处理。"},{"i":20,"n":"第二十条","txt":"边境地区因边贸活动、客货运输、边民往来或借道通行活动等频繁入出境，且入境后仅在边境地区一定范围内行驶的外国机动车和机动车驾驶人，申请临时入境机动车号牌和行驶证、临时机动车驾驶许可时，可以由省级公安机关结合本省实际制定实施意见。 “边境地区一定范围”的界限由省级公安机关确定。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区、澳门特别行政区和台湾地区机动车因参加有组织的旅游、比赛以及其他交往活动的，参照本规定执行。 持香港特别行政区、澳门特别行政区和台湾地区机动车驾驶证的人员临时进入内地需驾驶机动车的，参照本规定执行。"},{"i":22,"n":"第二十二条","txt":"临时入境机动车号牌、行驶证和临时机动车驾驶许可由公安部统一印制。"},{"i":23,"n":"第二十三条","txt":"本规定所称“临时入境的机动车”，是指在国外注册登记，需临时进入中国境内行驶的机动车。“临时入境的机动车驾驶人”，是指持有境外机动车驾驶证，需临时进入中国境内驾驶机动车的境外人员。"},{"i":24,"n":"第二十四条","txt":"本规定所称“始发地”，是指有组织的旅游、比赛以及其他交往活动的出发地。"},{"i":25,"n":"第二十五条","txt":"本规定自 2007年1月1日 起 施行。 1989年5月1日 发布的《临时入境机动车辆与驾驶员管理办法》（公安部令第4号）同时废止。 2007年1月1日 前 公安部发布的其他规定与本规定不一致的，以本规定为准。   附件1：临时入境机动车号牌、行驶证申请表 以下内容由申请人填写 机动车信息 机动车所有人 国籍及境外号牌号码 车辆类型 车身颜色 车辆品牌型号 转向位置 □左 □右 出厂年份 年    月 核定载客数/载质量 车辆识别代号/车架号 发动机号码 是否办理我国机动车交通事故责任强制保险 机动车交通事故责任强制保险有效期 申请内容 申请事由 □旅游 □比赛 □其他交往活动 □公务 □探亲 □借道 □其他 申请行驶区域 申请行驶时间 车辆入境相关情况 入境口岸 入境日期 年   月   日 批准车辆入境的海关 批准文件编号 批准入境的时限、区域 有中方组织或接待单位的，以下内容由中"}],"hulianwanganquanbaohujishucuoshiguiding":[{"i":1,"n":"第一条","txt":"为加强和规范互联网安全技术防范工作，保障互联网网络安全和信息安全，促进互联网健康、有序发展，维护国家安全、社会秩序和公共利益，根据《计算机信息网络国际联网安全保护管理办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称互联网安全保护技术措施，是指保障互联网网络安全和信息安全、防范违法犯罪的技术设施和技术方法。"},{"i":3,"n":"第三条","txt":"互联网服务提供者、联网使用单位负责落实互联网安全保护技术措施，并保障互联网安全保护技术措施功能的正常发挥。"},{"i":4,"n":"第四条","txt":"互联网服务提供者、联网使用单位应当建立相应的管理制度。未经用户同意不得公开、泄露用户注册信息，但法律、法规另有规定的除外。 互联网服务提供者、联网使用单位应当依法使用互联网安全保护技术措施，不得利用互联网安全保护技术措施侵犯用户的通信自由和通信秘密。"},{"i":5,"n":"第五条","txt":"公安机关公共信息网络安全监察部门负责对互联网安全保护技术措施的落实情况依法实施监督管理。"},{"i":6,"n":"第六条","txt":"互联网安全保护技术措施应当符合国家标准。没有国家标准的，应当符合公共安全行业技术标准。"},{"i":7,"n":"第七条","txt":"互联网服务提供者和联网使用单位应当落实以下互联网安全保护技术措施： （一）防范计算机病毒、网络入侵和攻击破坏等危害网络安全事项或者行为的技术措施； （二）重要数据库和系统主要设备的冗灾备份措施； （三）记录并留存用户登录和退出时间、主叫号码、账号、互联网地址或域名、系统维护日志的技术措施； （四）法律、法规和规章规定应当落实的其他安全保护技术措施。"},{"i":8,"n":"第八条","txt":"提供互联网接入服务的单位除落实本规定第七条规定的互联网安全保护技术措施外，还应当落实具有以下功能的安全保护技术措施： （一）记录并留存用户注册信息； （二）使用内部网络地址与互联网网络地址转换方式为用户提供接入服务的，能够记录并留存用户使用的互联网网络地址和内部网络地址对应关系； （三）记录、跟踪网络运行状态，监测、记录网络安全事件等安全审计功能。"},{"i":9,"n":"第九条","txt":"提供互联网信息服务的单位除落实本规定第七条规定的互联网安全保护技术措施外，还应当落实具有以下功能的安全保护技术措施： （一）在公共信息服务中发现、停止传输违法信息，并保留相关记录； （二）提供新闻、出版以及电子公告等服务的，能够记录并留存发布的信息内容及发布时间； （三）开办门户网站、新闻网站、电子商务网站的，能够防范网站、网页被篡改，被篡改后能够自动恢复； （四）开办电子公告服务的，具有用户注册信息和发布信息审计功能； （五）开办电子邮件和网上短信息服务的，能够防范、清除以群发方式发送伪造、隐匿信息发送者真实标记的电子邮件或者短信息。"},{"i":10,"n":"第十条","txt":"提供互联网数据中心服务的单位和联网使用单位除落实本规定第七条规定的互联网安全保护技术措施外，还应当落实具有以下功能的安全保护技术措施： （一）记录并留存用户注册信息； （二）在公共信息服务中发现、停止传输违法信息，并保留相关记录； （三）联网使用单位使用内部网络地址与互联网网络地址转换方式向用户提供接入服务的，能够记录并留存用户使用的互联网网络地址和内部网络地址对应关系。"},{"i":11,"n":"第十一条","txt":"提供互联网上网服务的单位，除落实本规定第七条规定的互联网安全保护技术措施外，还应当安装并运行互联网公共上网服务场所安全管理系统。"},{"i":12,"n":"第十二条","txt":"互联网服务提供者依照本规定采取的互联网安全保护技术措施应当具有符合公共安全行业技术标准的联网接口。"},{"i":13,"n":"第十三条","txt":"互联网服务提供者和联网使用单位依照本规定落实的记录留存技术措施，应当具有至少保存六十天记录备份的功能。"},{"i":14,"n":"第十四条","txt":"互联网服务提供者和联网使用单位不得实施下列破坏互联网安全保护技术措施的行为： （一）擅自停止或者部分停止安全保护技术设施、技术手段运行； （二）故意破坏安全保护技术设施； （三）擅自删除、篡改安全保护技术设施、技术手段运行程序和记录； （四）擅自改变安全保护技术措施的用途和范围； （五）其他故意破坏安全保护技术措施或者妨碍其功能正常发挥的行为。"},{"i":15,"n":"第十五条","txt":"违反本规定第七条至第十四条规定的，由公安机关依照《计算机信息网络国际联网安全保护管理办法》第二十一条的规定予以处罚。"},{"i":16,"n":"第十六条","txt":"公安机关应当依法对辖区内互联网服务提供者和联网使用单位安全保护技术措施的落实情况进行指导、监督和检查。 公安机关在依法监督检查时，互联网服务提供者、联网使用单位应当派人参加。公安机关对监督检查发现的问题，应当提出改进意见，通知互联网服务提供者、联网使用单位及时整改。 公安机关在监督检查时，监督检查人员不得少于二人，并应当出示执法身份证件。"},{"i":17,"n":"第十七条","txt":"公安机关及其工作人员违反本规定，有滥用职权，徇私舞弊行为的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"本规定所称互联网服务提供者，是指向用户提供互联网接入服务、互联网数据中心服务、互联网信息服务和互联网上网服务的单位。 本规定所称联网使用单位，是指为本单位应用需要连接并使用互联网的单位。 本规定所称提供互联网数据中心服务的单位，是指提供主机托管、租赁和虚拟空间租用等服务的单位。"},{"i":19,"n":"第十九条","txt":"本规定自2006年3月1日起施行。"}],"renminjingchazhishifuzhuangjiqibiaozhiguanliguidin13b08b":[{"i":1,"n":"第一条","txt":"为了加强对人民警察制式服装及其标志的管理，保障人民警察制式服装及其标志的专用性和严肃性，预防和制止利用人民警察制式服装及其标志进行违法犯罪活动，依据《中华人民共和国人民警察法》等有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称人民警察制式服装是指人民警察按照规定穿着的统一式样服装，包括常服、值勤服、作训服、多功能服、制式衬衣及警帽、领带、腰带、纽扣等。本规定所称标志是指人民警察按照规定穿着制式服装时佩带的专用标志，包括帽徽、警衔标志、领花、胸徽、警号、臂章等。"},{"i":3,"n":"第三条","txt":"人民警察制式服装及其标志由公安部统一监制并组织实施管理。"},{"i":4,"n":"第四条","txt":"公安机关人民警察制式服装专用标志由公安部统一配发。"},{"i":5,"n":"第五条","txt":"人民警察制式服装及其标志由公安部指定的企业生产。人民警察制式服装及其标志指定生产企业由公安部通过招标等形式确定。"},{"i":6,"n":"第六条","txt":"人民警察制式服装及其标志指定生产企业必须按照生产供应计划生产，不得超计划生产，不得将生产任务转让给其他企业或者个人。"},{"i":7,"n":"第七条","txt":"人民警察制式服装及其标志为人民警察专用，其他任何单位和个人不得持有和使用。"},{"i":8,"n":"第八条","txt":"严禁任何单位和个人非法生产、穿着和佩带人民警察制式服装及其标志。严禁买卖人民警察制式服装及其标志。"},{"i":9,"n":"第九条","txt":"严禁任何单位和个人生产、销售、购买、穿着和佩带与人民警察制式服装及其标志式样、颜色、图案相仿并足以造成混淆的服装和标志。"},{"i":10,"n":"第十条","txt":"任何单位和个人不得用人民警察制式服装及其标志作商业性广告。"},{"i":11,"n":"第十一条","txt":"影视制作单位和文艺团体因拍摄、演出需要，使用人民警察制式服装及其标志的，应当报省级公安机关批准，并严格保管。非拍摄、演出时不得使用。"},{"i":12,"n":"第十二条","txt":"着装单位必须严格按照规定配发人民警察制式服装及其标志，不得擅自扩大着装范围。"},{"i":13,"n":"第十三条","txt":"人民警察应当爱护并妥善保管配发的制式服装及其标志，不得将人民警察制式服装及其标志赠送、出借或者出卖给他人。"},{"i":14,"n":"第十四条","txt":"单位或者个人非法生产、销售人民警察制式服装及其标志的，由县级以上公安机关没收非法生产、销售的人民警察制式服装及其标志；对单位直接负责的主管人员和直接责任人员或者个人处十五日以下拘留，可以并处违法所得五倍以下罚款；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"人民警察制式服装及其标志指定生产企业违反规定，超计划生产或者擅自转让生产任务的，除按照本规定第十四条处罚外，并可由公安部取消其人民警察制式服装及其标志生产资格。"},{"i":16,"n":"第十六条","txt":"单位或者个人非法持有、使用人民警察制式服装及其标志的，由县级以上公安机关没收非法持有、使用的人民警察制式服装及其标志，处一千元以下罚款，并可对单位直接负责的主管人员和直接责任人员或者个人处十日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"生产、销售与人民警察制式服装及其标志相仿并足以造成混淆的服装或者标志的，由县级以上公安机关责令停止非法生产或者销售，处警告或者五千元以上一万元以下罚款。"},{"i":18,"n":"第十八条","txt":"穿着和佩带与人民警察制式服装及其标志相仿并足以造成混淆的服装或者标志的，由县级以上公安机关责令改正，处警告或者一千元以下罚款。"},{"i":19,"n":"第十九条","txt":"着装单位违反规定，擅自扩大着装范围的，由上级主管部门责令改正；拒不改正的，对单位直接负责的主管人员和直接责任人员依法给予行政处分。"},{"i":20,"n":"第二十条","txt":"人民警察违反本规定，擅自赠送、出借或者出卖人民警察制式服装及其标志的，由所在单位责令改正；拒不改正或者造成不良影响的，依法给予行政处分。"},{"i":21,"n":"第二十一条","txt":"被处罚人对公安机关依照本规定作出的行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":22,"n":"第二十二条","txt":"本规定自发布之日起施行。"}],"renminjingchajinghuishiyongguanliguiding":[{"i":1,"n":"第一条","txt":"为了维护人民警察警徽的尊严，正确使用警徽，根据《中华人民共和国人民警察法》，制定本规定。"},{"i":2,"n":"第二条","txt":"警徽图案由国徽、盾牌、长城、松枝和飘带构成。国徽衬地和垂绶为正红色，盾牌衬地为深蓝色，长城、松枝和飘带为金黄色。"},{"i":3,"n":"第三条","txt":"警徽是人民警察的象征和标志。人民警察必须爱护警徽，维护警徽的尊严。"},{"i":4,"n":"第四条","txt":"警徽及其图案的使用范围： （一）授衔、授装、宣誓、阅警等重大仪式； （二）人民警察机关及其事业单位的重要建筑物、会场主席台； （三）人民警察机关颁发的奖状、荣誉章、证书、证件； （四）人民警察报刊、图书及其他出版物； （五）警服、警帽、警用交通工具、标志等物品。 除前款规定的情形外，使用警徽及其图案应当经地（市）级以上人民警察机关批准。"},{"i":5,"n":"第五条","txt":"悬挂警徽，应当置于显著位置。使用警徽及其图案，应当严肃、庄重，严格按照比例放大或者缩小。不得使用破损、污损、褪色或者不合规格、颜色的警徽。"},{"i":6,"n":"第六条","txt":"警徽及其图案不得用于： （一）商标、商业广告； （二）日常生活的陈设布置； （三）私人婚、丧、庆、悼活动； （四）娱乐活动； （五）其他有碍于警徽庄严的场合或者物品。"},{"i":7,"n":"第七条","txt":"警徽为人民警察专用标志，其他单位和个人不得持有、使用、制作、仿造、伪造和买卖警徽，也不得使用与警徽及其图案相类似的标志。"},{"i":8,"n":"第八条","txt":"公安机关、国家安全机关、监狱、劳动教养管理机关的人民警察和人民法院、人民检察院的司法警察应当严格遵守本规定，对违反本规定的，应当进行批评教育并予以纠正；情节严重的，应当给予当事人纪律处分。"},{"i":9,"n":"第九条","txt":"对非法持有、使用、制作、仿造、伪造或者买卖警徽的，依照《中华人民共和国人民警察法》第三十六条的规定予以处罚；构成犯罪的，依照《中华人民共和国刑法》第二百八十一条的规定追究刑事责任。"},{"i":10,"n":"第十条","txt":"警徽由公安部按照《人民警察警徽技术标准》统一监制。"},{"i":11,"n":"第十一条","txt":"县级以上各级人民警察机关对警徽及其图案的使用，实行监督管理。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起施行。"}],"cangkufanghuoanquanguanliguize":[{"i":1,"n":"第一条","txt":"为了加强仓库消防安全管理，保护仓库免受火灾危害。根据《中华人民共和国消防条例》及其实施细则的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"仓库消防安全必须贯彻“预防为主，防消结合”的方针，实行“谁主管，谁负责”的原则。仓库消防安全由本单位及其上级主管部门负责。"},{"i":3,"n":"第三条","txt":"本规则由县级以上公安机关消防监督机构负责监督。"},{"i":4,"n":"第四条","txt":"本规则适用于国家、集体和个体经营的储存物品的各类仓库、堆栈、货场。 储存火药、炸药、火工品和军工物资的仓库，按照国家有关规定执行。"},{"i":5,"n":"第五条","txt":"新建、扩建和改建的仓库建筑设计，要符合国家建筑设计防火规范的有关规定，并经公安消防监督机构审核。仓库竣工时，其主管部门应当会同公安消防监督等有关部门进行验收；验收不合格的，不得交付使用。"},{"i":6,"n":"第六条","txt":"仓库应当确定一名主要领导人为防火负责人，全面负责仓库的消防安全管理工作。"},{"i":7,"n":"第七条","txt":"仓库防火负责人负有下列职责： 一、组织学习贯彻消防法规，完成上级部署的消防工作； 二、组织制定电源、火源、易燃易爆物品的安全管理和值班巡逻等制度，落实逐级防火责任制和岗位防火责任制； 三、组织对职工进行消防宣传、业务培训和考核，提高职工的安全素质， 四、组织开展防火检查，消除火险隐患； 五、领导专职、义务消防队组织和专职、兼职消防人员，制定灭火应急方案，组织扑救火灾； 六、定期总结消防安全工作，实施奖惩。"},{"i":8,"n":"第八条","txt":"国家储备库、专业仓库应当配备专职消防干部；其他仓库可以根据需要配备专职或兼职消防人员。"},{"i":9,"n":"第九条","txt":"国家储备库、专业仓库和火灾危险性大、距公安消防队较远的其他大型仓库，应当按照有关规定建立专职消防队。"},{"i":10,"n":"第十条","txt":"各类仓库都应当建立义务消防组织，定期进行业务培训，开展自防自救工作。"},{"i":11,"n":"第十一条","txt":"仓库防火负责人的确定和变动，应当向当地公安消防监督机构备案；专职消防干部、人员和专职消防队长的配备与更换，应当征求当地公安消防监督机构的意见。"},{"i":12,"n":"第十二条","txt":"仓库保管员应当熟悉储存物品的分类、性质、保管业务知识和防火安全制度，掌握消防器材的操作使用和维护保养方法，做好本岗位的防火工作。"},{"i":13,"n":"第十三条","txt":"对仓库新职工应当进行仓储业务和消防知识的培训，经考试合格，方可上岗作业。"},{"i":14,"n":"第十四条","txt":"仓库严格执行夜间值班、巡逻制度，带班人员应当认真检查，督促落实。"},{"i":15,"n":"第十五条","txt":"依据国家《建筑设计防火规范》的规定，按照仓库储存物品的火灾危险程度分为甲、乙、丙、丁、戊五类（详见附表）。"},{"i":16,"n":"第十六条","txt":"露天存放物品应当分类、分堆、分组和分垛，并留出必要的防火间距。堆场的总储量以及与建筑物等之间的防火距离，必须符合建筑设计防火规范的规定。"},{"i":17,"n":"第十七条","txt":"甲、乙类桶装液体，不宜露天存放。必须露天存放时，在炎热季节必须采取降温措施。"},{"i":18,"n":"第十八条","txt":"库存物品应当分类、分垛储存，每垛占地面积不宜大于一百平方米，垛与垛间距不小于一米，垛与墙间距不小于零点五米，垛与梁、柱间距不小于零点三米，主要通道的宽度不小于二米。"},{"i":19,"n":"第十九条","txt":"甲、乙类物品和一般物品以及容易相互发生化学反应或者灭火方法不同的物品，必须分间、分库储存，并在醒目处标明储存物品的名称、性质和灭火方法。"},{"i":20,"n":"第二十条","txt":"易自燃或者遇水分解的物品，必须在温度较低、通风良好和空气干燥的场所储存，并安装专用仪器定时检测，严格控制湿度与温度。"},{"i":21,"n":"第二十一条","txt":"物品入库前应当有专人负责检查，确定无火种等隐患后，方准入库。"},{"i":22,"n":"第二十二条","txt":"甲、乙类物品的包装容器应当牢固、密封，发现破损、残缺，变形和物品变质、分解等情况时，应当及时进行安全处理，严防跑、冒、滴、漏。"},{"i":23,"n":"第二十三条","txt":"使用过的油棉纱、油手套等沾油纤维物品以及可燃包装，应当存放在安全地点，定期处理。"},{"i":24,"n":"第二十四条","txt":"库房内因物品防冻必须采暖时，应当采用水暖，其散热器、供暖管道与储存物品的距离不小于零点三米。"},{"i":25,"n":"第二十五条","txt":"甲、乙类物品库房内不准设办公室、休息室。其他库房必需设办公室时，可以贴邻库房一角设置无孔洞的一、二级耐火等级的建筑，其门窗直通库外，具体实施，应征得当地公安消防监督机构的同意。"},{"i":26,"n":"第二十六条","txt":"储存甲、乙、丙类物品的库房布局、储存类别不得擅自改变。如确需改变的，应当报经当地公安消防监督机构同意。"},{"i":27,"n":"第二十七条","txt":"进入库区的所有机动车辆，必须安装防火罩。"},{"i":28,"n":"第二十八条","txt":"蒸汽机车驶入库区时，应当关闭灰箱和送风器，并不得在库区清炉。仓库应当派专人负责监护。"},{"i":29,"n":"第二十九条","txt":"汽车、拖拉机不准进入甲、乙、丙类物品库房。"},{"i":30,"n":"第三十条","txt":"进入甲、乙类物品库房的电瓶车、铲车必须是防爆型的；进入丙类物品库房的电瓶车、铲车，必须装有防止火花溅出的安全装置。"},{"i":31,"n":"第三十一条","txt":"各种机动车辆装卸物品后，不准在库区、库房、货场内停放和修理。"},{"i":32,"n":"第三十二条","txt":"库区内不得搭建临时建筑和构筑物。因装卸作业确需搭建时，必须经单位防火负责人批准，装卸作业结束后立即拆除。"},{"i":33,"n":"第三十三条","txt":"装卸甲、乙类物品时，操作人员不得穿戴易产生静电的工作服、帽和使用易产生火花的工具，严防震动、撞击、重压、摩擦和倒置。对易产生静电的装卸设备要采取消除静电的措施。"},{"i":34,"n":"第三十四条","txt":"库房内固定的吊装设备需要维修时，应当采取防火安全措施，经防火负责人批准后，方可进行。"},{"i":35,"n":"第三十五条","txt":"装卸作业结束后，应当对库区、库房进行检查，确认安全后，方可离人。"},{"i":36,"n":"第三十六条","txt":"仓库的电气装置必须符合国家现行的有关电气设计和施工安装验收标准规范的规定。"},{"i":37,"n":"第三十七条","txt":"甲、乙类物品库房和丙类液体库房的电气装置，必须符合国家现行的有关爆炸危险场所的电气安全规定。"},{"i":38,"n":"第三十八条","txt":"储存丙类固体物品的库房，不准使用碘钨灯和超过六十瓦以上的白炽灯等高温照明灯具。当使用日光灯等低温照明灯具和其他防燃型照明灯具时，应当对镇流器采取隔热、散热等防火保护措施，确保安全。"},{"i":39,"n":"第三十九条","txt":"库房内不准设置移动式照明灯具。照明灯具下方不准堆放物品，其垂直下方与储存物品水平间距离不得小于零点五米。"},{"i":40,"n":"第四十条","txt":"库房内敷设的配电线路，需穿金属管或用非燃硬塑料管保护。"},{"i":41,"n":"第四十一条","txt":"库区的每个库房应当在库房外单独安装开关箱，保管人员离库时，必须拉闸断电。 禁止使用不合规格的保险装置。"},{"i":42,"n":"第四十二条","txt":"库房内不准使用电炉、电烙铁、电熨斗等电热器具和电视机、电冰箱等家用电器。"},{"i":43,"n":"第四十三条","txt":"仓库电器设备的周围和架空线路的下方严禁堆放物品。对提升、码垛等机械设备易产生火花的部位，要设置防护罩。"},{"i":44,"n":"第四十四条","txt":"仓库必须按照国家有关防雷设计安装规范的规定，设置防雷装置，并定期检测，保证有效。"},{"i":45,"n":"第四十五条","txt":"仓库的电器设备，必须由持合格证的电工进行安装、检查和维修保养。电工应当严格遵守各项电器操作规程。"},{"i":46,"n":"第四十六条","txt":"仓库应当设置醒目的防火标志。进入甲、乙类物品库区的人员，必须登记，并交出携带的火种。"},{"i":47,"n":"第四十七条","txt":"库房内严禁使用明火。库房外动用明火作业时，必须办理动火证，经仓库或单位防火负责人批准，并采取严格的安全措施。动火证应当注明动火地点、时间、动火人、现场监护人、批准人和防火措施等内容。"},{"i":48,"n":"第四十八条","txt":"库房内不准使用火炉取暖。在库区使用时，应当经防火负责人批准。"},{"i":49,"n":"第四十九条","txt":"防火负责人在审批火炉的使用地点时，必须根据储存物品的分类，按照有关防火间距的规定审批，并制定防火安全管理制度，落实到人。"},{"i":50,"n":"第五十条","txt":"库区以及周围五十米内，严禁燃放烟花爆竹。"},{"i":51,"n":"第五十一条","txt":"仓库内应当按照国家有关消防技术规范，设置、配备消防设施和器材。"},{"i":52,"n":"第五十二条","txt":"消防器材应当设置在明显和便于取用的地点，周围不准堆放物品和杂物。"},{"i":53,"n":"第五十三条","txt":"仓库的消防设施、器材，应当由专人管理，负责检查、维修、保养、更换和添置，保证完好有效，严禁圈占、埋压和挪用。"},{"i":54,"n":"第五十四条","txt":"甲、乙、丙类物品国家储备库、专业性仓库以及其他大型物资仓库，应当按照国家有关技术规范的规定安装相应的报警装置，附近有公安消防队的宜设置与其直通的报警电话。"},{"i":55,"n":"第五十五条","txt":"对消防水池、消火栓、灭火器等消防设施、器材，应当经常进行检查，保持完整好用。地处寒区的仓库，寒冷季节要采取防冻措施。"},{"i":56,"n":"第五十六条","txt":"库区的消防车道和仓库的安全出口、疏散楼梯等消防通道，严禁堆放物品。"},{"i":57,"n":"第五十七条","txt":"仓库消防工作成绩显著的单位和个人，由公安机关、上级主管部门或者本单位给予表彰、奖励。"},{"i":58,"n":"第五十八条","txt":"对违反本规则的单位和人员，国家法现有规定的，应当按照国家法视予以处罚；国家法规没有规定的，可以按照地方有关法规、规章进行处罚； 触犯刑律的，由司法机关追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"储存丁、戊类物品的库房或露天堆栈、货场，执行本规则时，在确保安全并征得当地公安消防监督机构同意的情况下，可以适当放宽。"},{"i":60,"n":"第六十条","txt":"铁路车站、交通港口码头等昼夜作业的中转性仓库，可以按照本规则的原则要求，由铁路、交通等部门自行制定管理办法。"},{"i":61,"n":"第六十一条","txt":"各省、自治区、直辖市和国务院有关部、委根据本规则制订的具体管理办法，应当送公安部备案。"},{"i":62,"n":"第六十二条","txt":"本规则自发布之日起施行。一九八0年八月一日经国务院批准、同年八月十五日公安部公布施行的《仓库防火安全管理规则》即行废止。"}],"baoanpeixunjigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范公安机关对保安培训机构的管理，维护保安培训市场秩序，根据《中华人民共和国行政许可法》和《国务院对确需保留的行政审批项目设定行政许可的决定》等有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立保安培训机构，应当遵守本办法。 本办法所称保安培训机构，是指对正在从事或者准备从事保安服务职业的人员进行保安法律、安全防范等知识、技能培训的组织。"},{"i":3,"n":"第三条","txt":"保安培训应当遵循诚实信用、公平竞争和规范管理、自愿有偿的原则。"},{"i":4,"n":"第四条","txt":"设立保安培训机构，应当具备下列条件： （一）设立保安培训机构的组织应当具有法人资格，设立保安培训机构的个人应当具有完全民事行为能力； （二）具有与培训规模相适应的校园、校舍； （三）具有与培训内容相匹配、满足培训要求的训练场馆、图书馆、阅览室、实验、实习设施和仪器设备； （四）具有与培训内容、培训规模相适应的专兼职师资人员，其中保安专业师资人员必须具有大专以上学历和五年以上治安保卫或者保安工作经历； （五）申请人、投资人、法定代表人、管理人员及师资人员没有故意犯罪记录和精神病史； （六）主要负责人应当具有政法机关、军队或者教育培训的工作经历。"},{"i":5,"n":"第五条","txt":"申请设立保安培训机构，应当填写《保安培训机构设立申请表》，并提供下列资料，报所在地设区的市级人民政府公安机关审查： （一）设立报告，内容包括申请人、培训机构名称、培养目标、培训规模、培训层次、培训内容、培训条件和内部管理制度等； （二）资产来源、资金数额及有效证明文件，并载明产权归属； （三）申请人、法定代表人、管理人员和师资人员的相关资格证明文件。"},{"i":6,"n":"第六条","txt":"设区的市级人民政府公安机关收到上述申请资料后，应当分别依照下列规定处理： （一）对申请材料符合要求的，出具收到申请资料的书面凭证； （二）对申请材料不齐全或者不符合法定形式的，应当当场一次性告知需要补正的全部内容； （三）对申请材料存在错误的，应当允许申请人当场更正。 设区的市级人民政府公安机关应当在收到申请资料七日内审查完毕，将初步审查意见和全部申请材料直接报送省级人民政府公安机关审查。省级人民政府公安机关不得要求申请人重复提供申请材料。"},{"i":7,"n":"第七条","txt":"省级人民政府公安机关收到申请材料和设区的市级人民政府公安机关的审查意见后，应当分别依照下列规定处理： （一）符合申请条件的，应当受理，并出具书面凭证； （二）对不属于本机关职权范围或者本办法规定的许可事项的，应当即时作出不予受理的决定，并出具书面凭证。"},{"i":8,"n":"第八条","txt":"对已经受理的申请，省级人民政府公安机关应当对申请人提交的下列资料进行可行性和真实性审查，并对培训机构的校园、设施建设等情况进行现场考察： （一）保安培训机构设立申请表； （二）保安培训机构设立报告书； （三）校园、校舍、资金等有关证明文件； （四）相关人员的资格证明文件。 省级人民政府公安机关应当自受理申请之日起二十日内，以书面形式作出许可或者不予许可的决定。对许可设立保安培训机构的，应当同时发给《保安培训许可证》，并报公安部备案；对不予许可的，应当出具不予许可的书面凭证，告知申请人并说明理由。"},{"i":9,"n":"第九条","txt":"保安培训机构成立后，需要变更名称、住所、法定代表人、校长（院长）、投资主体或者培训类型的，应当在变更后的二十日内到发放《保安培训许可证》的公安机关办理变更手续。"},{"i":10,"n":"第十条","txt":"《保安培训许可证》的有效期五年。有效期满需要延期的，保安培训机构应当在期满前三个月内到发证机关办理许可证延期手续。发证机关应当按照本办法进行审查，对符合条件的，予以延期；对不符合条件的，不予延期，并说明理由。"},{"i":11,"n":"第十一条","txt":"依法设立的教育、职业培训机构（包括武术学校）开展保安培训的，按照本办法执行。"},{"i":12,"n":"第十二条","txt":"保安培训机构招录的学员必须符合下列条件： （一）十八周岁至五十周岁的中国公民； （二）男性身高不低于一百六十厘米，女性身高不低于一百五十五厘米； （三）身体健康，没有精神病等不能控制自己行为能力的疾病病史； （四）初中以上文化程度； （五）没有故意犯罪记录。"},{"i":13,"n":"第十三条","txt":"保安培训机构应当根据培训内容和培训计划，对学员进行两个月以上且不少于二百六十四课时的培训。"},{"i":14,"n":"第十四条","txt":"保安培训机构学员实习时间不得超过培训时间的三分之一。 保安培训机构不得向社会提供保安服务或者以实习等名义变相提供保安服务。"},{"i":15,"n":"第十五条","txt":"保安培训机构应当根据法律、法规和公安部制定的保安员培训大纲、保安员国家职业标准，制定培训内容和培训计划，并报所在地省级人民政府公安机关备案。 保安培训机构不得传授依法由公安机关、国家安全机关、检察机关专有的侦察技术、手段。枪支使用培训由省级人民政府公安机关指定的培训机构进行。法律、法规对培训内容和学员有其他特殊要求的，按照有关规定执行。"},{"i":16,"n":"第十六条","txt":"保安培训机构对完成培训计划、内容和课时且考核合格的学员，应当颁发结业证书。"},{"i":17,"n":"第十七条","txt":"保安培训机构应当建立健全学员档案管理制度，对学员成绩、考核鉴定等基本信息实行计算机管理。学员文书档案应当保存至学员毕业离校后的第五年年底。 保安培训机构应当将学员、师资人员文书档案及电子文档报所在地设区的市级人民政府公安机关备案。"},{"i":18,"n":"第十八条","txt":"保安培训机构收取培训费标准，由省级人民政府公安机关商同级价格主管部门核准，并向社会公布。"},{"i":19,"n":"第十九条","txt":"保安培训机构应当在学员入学时与学员签订规范的培训合同，明确双方权利义务，如实告知可能存在的就业风险。保安培训合同式样应当报保安培训机构所在地设区的市级人民政府公安机关备案。"},{"i":20,"n":"第二十条","txt":"保安培训机构不得以转包形式开展保安培训业务，不得委托未经公安机关依法许可的保安培训机构或者个人开展保安培训业务。"},{"i":21,"n":"第二十一条","txt":"保安培训机构应当依法发布招生广告，不得夸大事实或者以安排工作等名义诱骗学员入学。"},{"i":22,"n":"第二十二条","txt":"保安培训机构应当按照学员培训费的一定比例，设置学员权益保障金。培训规模在五百人以下的，保障金总额不少于三十万元；培训规模在五百人以上的，保障金总额不少于五十万元。 保障金用于因培训机构欺诈或者不履行合同时的学员权益保障。"},{"i":23,"n":"第二十三条","txt":"保安培训机构应当与机构所在地设区的市级人民政府公安机关签订《委托监管保障金协议》，并按照协议将保障金存入指定银行账户。 保障金及其利息由设区的市级人民政府公安机关按照《委托监管保障金协议》实行监管。"},{"i":24,"n":"第二十四条","txt":"保障金及其利息归保安培训机构所有，但不得用于本办法第二十三条第二款规定以外的用途。保安培训机构解散、破产、合并或者分立时，保障金及其利息作为该培训机构资产的一部分，按照有关法律规定处理。"},{"i":25,"n":"第二十五条","txt":"保安培训机构无力执行仲裁机构裁决或者人民法院的判决，或者无力支付对学员的赔偿时，可以书面形式向委托监管的公安机关提出动用保障金及其利息的申请，但所申请的数额不得超过保障金总额的百分之五十，并应当在六十日内补足保障金。"},{"i":26,"n":"第二十六条","txt":"保安培训机构被撤销《保安培训许可证》或者终止保安培训业务的，应当在公安机关指定的省级新闻媒体上发布公告，如在九十日内未发生针对该机构的投诉或者诉讼，可以凭委托监管的公安机关开具的证明，到开户银行领取保障金及其利息。"},{"i":27,"n":"第二十七条","txt":"设区的市级人民政府公安机关应当建立健全监督制度，加强对保安培训机构从事行政许可事项活动情况的检查、监督，及时纠正、查处保安培训中的违法行为。 设区的市级人民政府公安机关依法对保安培训机构从事行政许可事项的活动进行监督检查时，应当将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档。公众有权查阅监督检查记录。"},{"i":28,"n":"第二十八条","txt":"设区的市级人民政府公安机关实施监督检查，不得妨碍保安培训机构正常的经营活动，不得索取或者收受保安培训机构的财物，不得谋取其他利益。"},{"i":29,"n":"第二十九条","txt":"个人和组织发现保安培训机构违法从事行政许可事项的活动，有权向公安机关举报，设区的市级人民政府公安机关应当及时核实、依法处理。"},{"i":30,"n":"第三十条","txt":"设区的市级人民政府公安机关在监督检查中发现保安培训机构以欺骗、贿赂等不正当手段取得《保安培训许可证》的，应当将核查的有关材料报送作出许可决定的省级人民政府公安机关，并由省级人民政府公安机关撤销《保安培训许可证》。 保安培训机构因采取欺骗、贿赂等不正当手段而被撤销《保安培训许可证》的，其法定代表人和负责人五年内不得从事保安培训工作。"},{"i":31,"n":"第三十一条","txt":"对有下列情形之一的，省级人民政府公安机关应当依法办理《保安培训许可证》的注销手续： （一）《保安培训许可证》有效期届满未延续的； （二）保安培训机构依法终止的； （三）《保安培训许可证》依法被撤销、撤回的。"},{"i":32,"n":"第三十二条","txt":"未经省级人民政府公安机关批准，擅自设立保安培训机构，开展保安培训业务的，由设区的市级人民政府公安机关依照《中华人民共和国治安管理处罚法》第五十四条的规定予以取缔和处罚。 以欺骗、贿赂等不正当手段取得《保安培训许可证》的，由设区的市级人民政府公安机关对该保安培训机构处以一万元以上三万元以下罚款，对其直接负责的主管人员和其他直接责任人员处以二百元以上一千元以下罚款，并由发证的公安机关撤销《保安培训许可证》。"},{"i":33,"n":"第三十三条","txt":"保安培训机构违反本办法第十条、第十五条或者第二十条规定的，由设区的市级人民政府公安机关处以五千元以上三万元以下罚款，并责令限期改正。 保安培训机构违反本办法第二十二条规定的，由设区的市级人民政府公安机关处以五千元以上三万元以下罚款，并责令退还学员全部学费；构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"保安培训机构违反本办法第十三条或者第十六条第一款规定的，由设区的市级人民政府公安机关责令限期改正。 保安培训机构违反本办法第十六条第二款规定的，由设区的市级人民政府公安机关责令保安培训机构取消教员授课资格，并对保安培训机构处以二千元以上一万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"保安培训机构违反本办法第十四条、第十七条、第十八条、第十九条或者第二十一规定的，由设区的市级人民政府公安机关责令保安培训机构限期改正；逾期不改正的，处以二千元以上一万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"保安培训机构因违反本办法被公安机关给予两次罚款处罚后，又违反本办法的，由发证的公安机关依照《中华人民共和国治安管理处罚法》第五十四条的规定吊销《保安培训许可证》。"},{"i":37,"n":"第三十七条","txt":"公民、法人或者其他组织对公安机关不予许可的决定不服的，以及保安培训机构或者个人对公安机关的处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":38,"n":"第三十八条","txt":"公安机关及其人民警察在工作中，有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对不符合设立条件的申请人发放《保安培训许可证》的； （二）对符合设立条件的申请人不予许可或者不按本办法规定的时限作出许可决定的； （三）索取、收受当事人贿赂或者谋取其他利益的； （四）对违反本办法的行为不依法追究法律责任的； （五）违反法律、法规和本办法的规定实施处罚或者收取费用的； （六）其他滥用职权、玩忽职守、徇私舞弊的。"},{"i":39,"n":"第三十九条","txt":"《保安培训许可证》和其他法律文书式样由公安部制定，各省、自治区、直辖市公安厅、局自行印制。"},{"i":40,"n":"第四十条","txt":"本办法自二○○六年三月一日起施行。 附件：1、保安培训许可证（略） 2、保安培训机构设立申请表（略） 3、委托监管保障金协议（略）"}],"gonggongyulechangsuoxiaofanganquanguanliguiding":[{"i":1,"n":"第一条","txt":"为了预防火灾，保障公共安全，依据《中华人民共和国消防法》制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称公共娱乐场所，是指向公众开放的下列室内场所： （一）影剧院、录像厅、礼堂等演出、放映场所； （二）舞厅、卡拉OK厅等歌舞娱乐场所； （三）具有娱乐功能的夜总会、音乐茶座和餐饮场所； （四）游艺、游乐场所； （五）保龄球馆、旱冰场、桑拿浴室等营业性健身、休闲场所。"},{"i":3,"n":"第三条","txt":"公共娱乐场所应当在法定代表人或者主要负责人中确定一名本单位的消防安全责任人。在消防安全责任人确定或者变更时，应当向当地公安消防机构备案。 消防安全责任人应当依照《消防法》第十四条和第十六条规定履行消防安全职责，负责检查和落实本单位防火措施、灭火预案的制定和演练以及建筑消防设施、消防通道、电源和火源管理等。 公共娱乐场所的房产所有者在与其他单位、个人发生租赁、承包等关系后，公共娱乐场所的消防安全由经营者负责。"},{"i":4,"n":"第四条","txt":"新建、改建、扩建公共娱乐场所或者变更公共娱乐场所内部装修的，其消防设计应当符合国家有关建筑消防技术标准的规定。"},{"i":5,"n":"第五条","txt":"新建、改建、扩建公共娱乐场所或者变更公共娱乐场所内部装修的，建设或者经营单位应当依法将消防设计图纸报送当地公安消防机构审核，经审核同意方可施工；工程竣工时，必须经公安消防机构进行消防验收；未经验收或者经验收不合格的，不得投入使用。"},{"i":6,"n":"第六条","txt":"公众聚集的娱乐场所在使用或者开业前，必须具备消防安全条件，依法向当地公安消防机构申报检查，经消防安全检查合格后，发给《消防安全检查意见书》，方可使用或者开业。"},{"i":7,"n":"第七条","txt":"公共娱乐场所宜设置在耐火等级不低于二级的建筑物内；已经核准设置在三级耐火等级建筑内的公共娱乐场所，应当符合特定的防火安全要求。 公共娱乐场所不得设置在文物古建筑和博物馆、图书馆建筑内，不得毗连重要仓库或者危险物品仓库；不得在居民住宅楼内改建公共娱乐场所。 公共娱乐场所与其他建筑相毗连或者附设在其他建筑物内时，应当按照独立的防火分区设置；商住楼内的公共娱乐场所与居民住宅的安全出口应当分开设置。"},{"i":8,"n":"第八条","txt":"公共娱乐场所的内部装修设计和施工，应当符合《建筑内部装修设计防火规范》和有关建筑内部装饰装修防火管理的规定。"},{"i":9,"n":"第九条","txt":"公共娱乐场所的安全出口数目、疏散宽度和距离，应当符合国家有关建筑设计防火规范的规定。 安全出口处不得设置门槛、台阶，疏散门应向外开启，不得采用卷帘门、转门、吊门和侧拉门，门口不得设置门帘、屏风等影响疏散的遮挡物。 公共娱乐场所在营业时必须确保安全出口和疏散通道畅通无阻，严禁将安全出口上锁、阻塞。"},{"i":10,"n":"第十条","txt":"安全出口、疏散通道和楼梯口应当设置符合标准的灯光疏散指示标志。指示标志应当设在门的顶部、疏散通道和转角处距地面一米以下的墙面上。设在走道上的指示标志的间距不得大于二十米。"},{"i":11,"n":"第十一条","txt":"公共娱乐场所内应当设置火灾事故应急照明灯，照明供电时间不得少于二十分钟。"},{"i":12,"n":"第十二条","txt":"公共娱乐场所必须加强电气防火安全管理，及时消除火灾隐患。不得超负荷用电，不得擅自拉接临时电线。"},{"i":13,"n":"第十三条","txt":"在地下建筑内设置公共娱乐场所，除符合本规定其他条款的要求外，还应当符合下列规定： （一）只允许设在地下一层； （二）通往地面的安全出口不应少于二个，安全出口、楼梯和走道的宽度应当符合有关建筑设计防火规范的规定； （三）应当设置机械防烟排烟设施； （四）应当设置火灾自动报警系统和自动喷水灭火系统； （五）严禁使用液化石油气。"},{"i":14,"n":"第十四条","txt":"公共娱乐场所内严禁带入和存放易燃易爆物品。"},{"i":15,"n":"第十五条","txt":"严禁在公共娱乐场所营业时进行设备检修、电气焊、油漆粉刷等施工、维修作业。"},{"i":16,"n":"第十六条","txt":"演出、放映场所的观众厅内禁止吸烟和明火照明。"},{"i":17,"n":"第十七条","txt":"公共娱乐场所在营业时，不得超过额定人数。"},{"i":18,"n":"第十八条","txt":"卡拉OK厅及其包房内，应当设置声音或者视像警报，保证在火灾发生初期，将各卡拉OK房间的画面、音响消除，播送火灾警报，引导人们安全疏散。"},{"i":19,"n":"第十九条","txt":"公共娱乐场所应当制定防火安全管理制度，制定紧急安全疏散方案。在营业时间和营业结束后，应当指定专人进行安全巡视检查。"},{"i":20,"n":"第二十条","txt":"公共娱乐场所应当建立全员防火安全责任制度，全体员工都应当熟知必要的消防安全知识，会报火警，会使用灭火器材，会组织人员疏散。新职工上岗前必须进行消防安全培训。"},{"i":21,"n":"第二十一条","txt":"公共娱乐场所应当按照《建筑灭火器配置设计规范》配置灭火器材，设置报警电话，保证消防设施、设备完好有效。"},{"i":22,"n":"第二十二条","txt":"对违反本规定的行为，依照《中华人民共和国消防法》和地方性消防法规、规章予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。一九九五年一月二十六日公安部发布的《公共娱乐场所消防安全管理规定》同时废止。"}],"gonganjiguanhulianwanganquanjiandujianchaguiding":[{"i":1,"n":"第一条","txt":"为规范公安机关互联网安全监督检查工作，预防网络违法犯罪，维护网络安全，保护公民、法人和其他组织合法权益，根据《中华人民共和国人民警察法》《中华人民共和国网络安全法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于公安机关依法对互联网服务提供者和联网使用单位履行法律、行政法规规定的网络安全义务情况进行的安全监督检查。"},{"i":3,"n":"第三条","txt":"互联网安全监督检查工作由县级以上地方人民政府公安机关网络安全保卫部门组织实施。 上级公安机关应当对下级公安机关开展互联网安全监督检查工作情况进行指导和监督。"},{"i":4,"n":"第四条","txt":"公安机关开展互联网安全监督检查，应当遵循依法科学管理、保障和促进发展的方针，严格遵守法定权限和程序，不断改进执法方式，全面落实执法责任。"},{"i":5,"n":"第五条","txt":"公安机关及其工作人员对履行互联网安全监督检查职责中知悉的个人信息、隐私、商业秘密和国家秘密，应当严格保密，不得泄露、出售或者非法向他人提供。 公安机关及其工作人员在履行互联网安全监督检查职责中获取的信息，只能用于维护网络安全的需要，不得用于其他用途。"},{"i":6,"n":"第六条","txt":"公安机关对互联网安全监督检查工作中发现的可能危害国家安全、公共安全、社会秩序的网络安全风险，应当及时通报有关主管部门和单位。"},{"i":7,"n":"第七条","txt":"公安机关应当建立并落实互联网安全监督检查工作制度，自觉接受检查对象和人民群众的监督。"},{"i":8,"n":"第八条","txt":"互联网安全监督检查由互联网服务提供者的网络服务运营机构和联网使用单位的网络管理机构所在地公安机关实施。互联网服务提供者为个人的，可以由其经常居住地公安机关实施。"},{"i":9,"n":"第九条","txt":"公安机关应当根据网络安全防范需要和网络安全风险隐患的具体情况，对下列互联网服务提供者和联网使用单位开展监督检查： （一）提供互联网接入、互联网数据中心、内容分发、域名服务的； （二）提供互联网信息服务的； （三）提供公共上网服务的； （四）提供其他互联网服务的； 对开展前款规定的服务未满一年的，两年内曾发生过网络安全事件、违法犯罪案件的，或者因未履行法定网络安全义务被公安机关予以行政处罚的，应当开展重点监督检查。"},{"i":10,"n":"第十条","txt":"公安机关应当根据互联网服务提供者和联网使用单位履行法定网络安全义务的实际情况，依照国家有关规定和标准，对下列内容进行监督检查： （一）是否办理联网单位备案手续，并报送接入单位和用户基本信息及其变更情况； （二）是否制定并落实网络安全管理制度和操作规程，确定网络安全负责人； （三）是否依法采取记录并留存用户注册信息和上网日志信息的技术措施； （四）是否采取防范计算机病毒和网络攻击、网络侵入等技术措施； （五）是否在公共信息服务中对法律、行政法规禁止发布或者传输的信息依法采取相关防范措施； （六）是否按照法律规定的要求为公安机关依法维护国家安全、防范调查恐怖活动、侦查犯罪提供技术支持和协助； （七）是否履行法律、行政法规规定的网络安全等级保护等义务。"},{"i":11,"n":"第十一条","txt":"除本规定第十条所列内容外，公安机关还应当根据提供互联网服务的类型，对下列内容进行监督检查： （一）对提供互联网接入服务的，监督检查是否记录并留存网络地址及分配使用情况； （二）对提供互联网数据中心服务的，监督检查是否记录所提供的主机托管、主机租用和虚拟空间租用的用户信息； （三）对提供互联网域名服务的，监督检查是否记录网络域名申请、变动信息，是否对违法域名依法采取处置措施； （四）对提供互联网信息服务的，监督检查是否依法采取用户发布信息管理措施，是否对已发布或者传输的法律、行政法规禁止发布或者传输的信息依法采取处置措施，并保存相关记录； （五）对提供互联网内容分发服务的，监督检查是否记录内容分发网络与内容源网络链接对应情况； （六）对提供互联网公共上网服务的，监督检查是否采取符合国家标准的网络与信息安全保护技术措施。"},{"i":12,"n":"第十二条","txt":"在国家重大网络安全保卫任务期间，对与国家重大网络安全保卫任务相关的互联网服务提供者和联网使用单位，公安机关可以对下列内容开展专项安全监督检查： （一）是否制定重大网络安全保卫任务所要求的工作方案、明确网络安全责任分工并确定网络安全管理人员； （二）是否组织开展网络安全风险评估，并采取相应风险管控措施堵塞网络安全漏洞隐患； （三）是否制定网络安全应急处置预案并组织开展应急演练，应急处置相关设施是否完备有效； （四）是否依法采取重大网络安全保卫任务所需要的其他网络安全防范措施； （五）是否按照要求向公安机关报告网络安全防范措施及落实情况。 对防范恐怖袭击的重点目标的互联网安全监督检查，按照前款规定的内容执行。"},{"i":13,"n":"第十三条","txt":"公安机关开展互联网安全监督检查，可以采取现场监督检查或者远程检测的方式进行。"},{"i":14,"n":"第十四条","txt":"公安机关开展互联网安全现场监督检查时，人民警察不得少于二人，并应当出示人民警察证和县级以上地方人民政府公安机关出具的监督检查通知书。"},{"i":15,"n":"第十五条","txt":"公安机关开展互联网安全现场监督检查可以根据需要采取以下措施： （一）进入营业场所、机房、工作场所； （二）要求监督检查对象的负责人或者网络安全管理人员对监督检查事项作出说明； （三）查阅、复制与互联网安全监督检查事项相关的信息； （四）查看网络与信息安全保护技术措施运行情况。"},{"i":16,"n":"第十六条","txt":"公安机关对互联网服务提供者和联网使用单位是否存在网络安全漏洞，可以开展远程检测。 公安机关开展远程检测，应当事先告知监督检查对象检查时间、检查范围等事项或者公开相关检查事项，不得干扰、破坏监督检查对象网络的正常运行。"},{"i":17,"n":"第十七条","txt":"公安机关开展现场监督检查或者远程检测，可以委托具有相应技术能力的网络安全服务机构提供技术支持。 网络安全服务机构及其工作人员对工作中知悉的个人信息、隐私、商业秘密和国家秘密，应当严格保密，不得泄露、出售或者非法向他人提供。公安机关应当严格监督网络安全服务机构落实网络安全管理与保密责任。"},{"i":18,"n":"第十八条","txt":"公安机关开展现场监督检查，应当制作监督检查记录，并由开展监督检查的人民警察和监督检查对象的负责人或者网络安全管理人员签名。监督检查对象负责人或者网络安全管理人员对监督检查记录有异议的，应当允许其作出说明；拒绝签名的，人民警察应当在监督检查记录中注明。 公安机关开展远程检测，应当制作监督检查记录，并由二名以上开展监督检查的人民警察在监督检查记录上签名。 委托网络安全服务机构提供技术支持的，技术支持人员应当一并在监督检查记录上签名。"},{"i":19,"n":"第十九条","txt":"公安机关在互联网安全监督检查中，发现互联网服务提供者和联网使用单位存在网络安全风险隐患，应当督促指导其采取措施消除风险隐患，并在监督检查记录上注明；发现有违法行为，但情节轻微或者未造成后果的，应当责令其限期整改。 监督检查对象在整改期限届满前认为已经整改完毕的，可以向公安机关书面提出提前复查申请。 公安机关应当自整改期限届满或者收到监督检查对象提前复查申请之日起三个工作日内，对整改情况进行复查，并在复查结束后三个工作日内反馈复查结果。"},{"i":20,"n":"第二十条","txt":"监督检查过程中收集的资料、制作的各类文书等材料，应当按照规定立卷存档。"},{"i":21,"n":"第二十一条","txt":"公安机关在互联网安全监督检查中，发现互联网服务提供者和联网使用单位有下列违法行为的，依法予以行政处罚： （一）未制定并落实网络安全管理制度和操作规程，未确定网络安全负责人的，依照《中华人民共和国网络安全法》第五十九条第一款的规定予以处罚； （二）未采取防范计算机病毒和网络攻击、网络侵入等危害网络安全行为的技术措施的，依照《中华人民共和国网络安全法》第五十九条第一款的规定予以处罚； （三）未采取记录并留存用户注册信息和上网日志信息措施的，依照《中华人民共和国网络安全法》第五十九条第一款的规定予以处罚； （四）在提供互联网信息发布、即时通讯等服务中，未要求用户提供真实身份信息，或者对不提供真实身份信息的用户提供相关服务的，依照《中华人民共和国网络安全法》第六十一条的规定予以处罚； （五）在公共信息服务中对法律、行政法规禁止发布或者传输的信息未依法或者不按照公安机关的要求采取停止传输、消除等"},{"i":22,"n":"第二十二条","txt":"公安机关在互联网安全监督检查中，发现互联网服务提供者和联网使用单位，窃取或者以其他非法方式获取、非法出售或者非法向他人提供个人信息，尚不构成犯罪的，依照《中华人民共和国网络安全法》第六十四条第二款的规定予以处罚。"},{"i":23,"n":"第二十三条","txt":"公安机关在互联网安全监督检查中，发现互联网服务提供者和联网使用单位在提供的互联网服务中设置恶意程序的，依照《中华人民共和国网络安全法》第六十条第一项的规定予以处罚。"},{"i":24,"n":"第二十四条","txt":"互联网服务提供者和联网使用单位拒绝、阻碍公安机关实施互联网安全监督检查的，依照《中华人民共和国网络安全法》第六十九条第二项的规定予以处罚；拒不配合反恐怖主义工作的，依照《中华人民共和国反恐怖主义法》第九十一条或者第九十二条的规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"受公安机关委托提供技术支持的网络安全服务机构及其工作人员，从事非法侵入监督检查对象网络、干扰监督检查对象网络正常功能、窃取网络数据等危害网络安全的活动的，依照《中华人民共和国网络安全法》第六十三条的规定予以处罚；窃取或者以其他非法方式获取、非法出售或者非法向他人提供在工作中获悉的个人信息的，依照《中华人民共和国网络安全法》第六十四条第二款的规定予以处罚，构成犯罪的，依法追究刑事责任。 前款规定的机构及人员侵犯监督检查对象的商业秘密，构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"公安机关及其工作人员在互联网安全监督检查工作中，玩忽职守、滥用职权、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法予以处分；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"互联网服务提供者和联网使用单位违反本规定，构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"对互联网上网服务营业场所的监督检查，按照《互联网上网服务营业场所管理条例》的有关规定执行。"},{"i":29,"n":"第二十九条","txt":"本规定自2018年11月1日起施行。"}],"gonganjiguanrenminjingchaneiwutiaoling":[{"i":1,"n":"第一条","txt":"为了规范公安机关人民警察内务建设，推进新时代公安工作现代化和公安队伍革命化正规化专业化职业化建设，根据《中华人民共和国人民警察法》等法律法规，制定本条令。"},{"i":2,"n":"第二条","txt":"本条令是公安机关内务建设的基本依据，适用于各级公安机关及所属人民警察（以下简称公安民警）。"},{"i":3,"n":"第三条","txt":"内务建设是公安机关进行各项建设的基础，是巩固和提高公安队伍战斗力的重要保证。基本任务是，严格规范工作、学习、生活秩序，铸牢忠诚警魂、培育优良警风、严明纪律规矩、提高职业素养、树立良好形象，着力锻造具有铁一般的理想信念、铁一般的责任担当、铁一般的过硬本领、铁一般的纪律作风的高素质专业化过硬公安队伍，为忠实履行党和人民赋予的新时代使命任务奠定坚实基础。"},{"i":4,"n":"第四条","txt":"公安机关是人民民主专政的重要工具，人民警察是武装性质的国家治安行政力量和刑事司法力量。公安机关必须坚持用习近平新时代中国特色社会主义思想武装头脑、指导实践，确保公安工作沿着正确道路前进；必须坚持党对公安工作的绝对领导，确保公安工作坚定正确政治方向；必须坚持总体国家安全观，把维护以政权安全、制度安全为核心的国家政治安全作为公安工作的根本着眼点和着力点，坚决捍卫中国共产党长期执政地位和中国特色社会主义制度；必须坚持以人民为中心，忠实践行人民公安为人民的初心和使命，不断增强人民群众获得感、幸福感、安全感；必须坚持专项治理和系统治理、依法治理、综合治理、源头治理相结合，创新完善社会治安治理的方式方法，推进社会治理现代化；必须坚持严格规范公正文明执法，提高公安工作法治化水平和执法公信力；必须坚持改革创新，坚定不移走中国特色社会主义强警之路；必须坚持全面从严管党治警，按照对党忠诚、服务人民、执法公"},{"i":5,"n":"第五条","txt":"公安机关内务建设必须坚持政治建警。必须坚决听从党中央命令、服从党中央指挥，贯彻党对公安工作的全方位领导。必须增强“四个意识”、坚定“四个自信”、做到“两个维护”，以党的旗帜为旗帜、以党的方向为方向、以党的意志为意志，始终在思想上政治上行动上同党中央保持高度一致，确保绝对忠诚、绝对纯洁、绝对可靠。"},{"i":6,"n":"第六条","txt":"公安机关内务建设必须坚持改革强警。坚持向改革要动力、要活力，全面深化公安工作和公安队伍管理改革。坚持把抓改革任务落实落地作为重大政治责任，坚决维护党中央改革决策部署的权威性和严肃性。"},{"i":7,"n":"第七条","txt":"公安机关内务建设必须坚持科技兴警。坚持向科技要警力、要战斗力，深化公安大数据智能化建设应用，建设智慧公安。"},{"i":8,"n":"第八条","txt":"公安机关内务建设必须坚持从严治警。落实全面从严管党治警“两个责任”和领导干部“一岗双责”，严明警规警令，严肃警风警纪，严格行为规范。"},{"i":9,"n":"第九条","txt":"公安机关内务建设必须坚持从优待警。坚持严管厚爱结合、激励约束并重，建立人民警察荣誉制度，完善职业保障体系，健全依法履职保护机制。"},{"i":10,"n":"第十条","txt":"公安机关内务建设必须坚持战斗力标准，加强专业化建设，突出实战实用实效，提升公安民警职业素质能力。"},{"i":11,"n":"第十一条","txt":"各级公安机关党委（党组）对本条令的贯彻落实负有主体责任，党委（党组）主要负责同志负有第一责任，各部门、警种和基层所队担负直接责任，政工、纪检监察、督察部门担负监督责任，应当分级负责、各司其职，加强监督检查，认真贯彻落实。"},{"i":12,"n":"第十二条","txt":"县级以上公安机关按照干部管理权限，在公安民警入警、评授警衔、表彰奖励、从警特定年限、退休等职业生涯重要节点，举行相应的荣誉仪式，增强公安民警的职业荣誉感、自豪感和归属感。"},{"i":13,"n":"第十三条","txt":"举行荣誉仪式应当在县级以上公安机关党委（党组）统一领导下，由相关部门具体组织实施。"},{"i":14,"n":"第十四条","txt":"举行荣誉仪式，应当充分体现人民警察职业特点，根据工作需要，做到隆重、庄严、简朴。"},{"i":15,"n":"第十五条","txt":"公安机关下列人员应当进行宪法宣誓： （一）公安机关新任命的领导干部； （二）新入职的公安民警。 各级人民代表大会及县级以上各级人民代表大会常务委员会，以及各级人民政府对公安机关国家工作人员宪法宣誓另有规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"宪法宣誓仪式的基本要求： （一）宪法宣誓仪式由任命机关组织； （二）举行宪法宣誓仪式，应当根据干部管理权限确定监誓人、主持人； （三）宣誓场所应当庄重、严肃，悬挂中华人民共和国国旗或者国徽； （四）监誓人、领誓人、宣誓人和参加宣誓仪式的公安民警，穿着统一制式的人民警察服装（以下简称警服），其他人员穿着正装； （五）举行宪法宣誓仪式，应当奏唱中华人民共和国国歌； （六）宪法宣誓一般采取集体宣誓形式，根据需要，也可以采取单独宣誓的形式。 集体宣誓时，由一人领誓，领誓人面向国旗或者国徽站立，左手抚按《中华人民共和国宪法》，右手举拳，拳心向前，领诵誓词；其他宣誓人在领誓人身后整齐站立，面向国旗或者国徽，右手举拳，拳心向前，跟诵誓词。领誓人由宣誓仪式组织单位指定。 单独宣誓时，宣誓人面向国旗或者国徽站立，左手抚按《中华人民共和国宪法》，右手举拳，拳心向前，诵读誓词。"},{"i":17,"n":"第十七条","txt":"人民警察宣誓是公安民警对所肩负的神圣职责和光荣使命的庄严承诺。公安机关人民警察誓词是： 我是中国人民警察，我宣誓：坚决拥护中国共产党的绝对领导，矢志献身崇高的人民公安事业，对党忠诚、服务人民、执法公正、纪律严明，为捍卫政治安全、维护社会安定、保障人民安宁而英勇奋斗！"},{"i":18,"n":"第十八条","txt":"公安民警新入职时应当进行宣誓，举行荣誉仪式、执行重大任务、参加重大纪念、庆典等活动时，可以组织宣誓。"},{"i":19,"n":"第十九条","txt":"人民警察宣誓仪式的基本要求： （一）宣誓场地应当庄重、严肃，一般应悬挂中华人民共和国国旗和中国人民警察警旗； （二）参加宣誓仪式的公安民警穿着警服，其他人员穿着正装； （三）举行人民警察宣誓仪式，应当奏（唱）中华人民共和国国歌和中国人民警察警歌； （四）宣誓人立正，右手举拳，拳心向前，由预先指定的一名宣誓人担任领誓人，在队列前逐句领诵誓词，其他人跟诵誓词，誓词宣读完毕，宣誓人自报姓名； （五）宣誓仪式可以结合授衔、授装等活动进行。结合授衔、授装进行的，应当先授衔、授装； （六）宣誓仪式可以邀请公安民警家属或者群众代表参加。 新入职的公安民警宣誓仪式由县级以上公安机关政工部门或者委托承训公安院校、训练基地组织，一般在入警训练合格后、上岗工作前进行。宣誓前，应当对宣誓人进行公安机关性质、宗旨、任务、纪律、作风等集体教育。"},{"i":20,"n":"第二十条","txt":"公安民警不论职务高低，在政治上一律平等，相互间是同志关系。"},{"i":21,"n":"第二十一条","txt":"公安民警依据领导职务和警衔，构成上级与下级或者同级关系。领导职务高的是上级，领导职务低的是下级，领导职务相当的是同级；在没有领导职务或者难以确定领导职务高低时，警衔高的是上级，警衔低的是下级，警衔相同的是同级。"},{"i":22,"n":"第二十二条","txt":"上下级之间、同级之间应当互相尊重、互相爱护、互相支持，努力构建团结、友爱、和谐、纯洁的内部关系。"},{"i":23,"n":"第二十三条","txt":"上级对下级应当做到： （一）公道正派，以身作则，率先垂范； （二）严格教育，严格管理，严格监督； （三）关心学习、工作和生活，帮助成长进步； （四）尊重合理意见，维护合法权益，不压制民主，不打击报复； （五）不打骂体罚和侮辱，不收受财物； （六）关爱身心健康，帮助解决实际困难，努力消除后顾之忧。"},{"i":24,"n":"第二十四条","txt":"下级对上级应当做到： （一）服从命令，听从指挥； （二）履职尽责，主动汇报； （三）虚心接受批评，坚决改正错误； （四）尊重上级，维护上级权威； （五）积极建言献策，坚决完成好交办的各项工作任务。"},{"i":25,"n":"第二十五条","txt":"上级（机关）应当对下级（机关）的各项建设和业务工作加强指导、明确要求，及时通报情况、检查督办和抓好落实。下级（机关）应当按照上级（机关）要求进行各项建设、完成业务工作，及时向上级机关汇报情况、报告工作、提出建议。"},{"i":26,"n":"第二十六条","txt":"公安机关之间以及各警种、部门之间，应当按照职责分工，密切配合，互相支持，协调一致开展工作。"},{"i":27,"n":"第二十七条","txt":"上级（机关）有权对下级（机关）下达命令。命令通常逐级下达，情况紧急时，也可以越级下达。越级下达命令时，除特殊情况外，下达命令的上级（机关）应当将所下达命令及时通知受令者的直接上级（机关）。 命令下达后，上级（机关）应当及时检查执行情况；如果情况发生变化，应当及时下达补充命令或者新的命令。"},{"i":28,"n":"第二十八条","txt":"下级（机关）必须坚决执行上级（机关）的命令，并将执行情况及时报告。下级（机关）认为命令有错误的，可以提出意见，上级（机关）应当及时给予答复。在没有明确答复之前，下级（机关）不得中止或者改变命令的执行；提出的意见不被采纳时，必须服从命令。执行命令的后果由作出命令的上级（机关）负责。 执行中如果情况发生重大变化，原命令确实无法继续执行而又来不及或者无法请示报告上级（机关）时，下级（机关）应当根据上级（机关）的精神要求，以高度负责的态度，果断临机处置，事后迅速报告。 下级（机关）对超越法律法规规定的职责范围的命令，有权拒绝执行，并同时向下达命令的上级（机关）报告。"},{"i":29,"n":"第二十九条","txt":"下级（机关）接到越级下达的命令，必须坚决执行。除有明确要求外，在执行的同时，应当向直接上级（机关）报告；因故不能及时报告的，应当在不能报告的情形解除后24小时内补报。"},{"i":30,"n":"第三十条","txt":"不同建制的公安民警在共同执行任务时，应当服从共同上级所指定负责人的领导和指挥。 公安民警处置突发事件或者遇有紧急情况，在建制不明时，依据领导职务和警衔确定领导指挥关系。"},{"i":31,"n":"第三十一条","txt":"公安民警被临时抽调到其他单位工作时，应当接受抽调单位的领导和管理，除有特殊要求外，须定期向原单位报告。"},{"i":32,"n":"第三十二条","txt":"公安民警着装，是指公安机关人民警察按规定穿戴警服和警用标志。 公安民警应当配套穿着警服，佩戴警衔、警号等标志，做到着装整洁庄重、警容严整、规范统一。 未经审批，非人民警察身份人员不得穿着警服，不得佩戴警用标志。"},{"i":33,"n":"第三十三条","txt":"公安民警在规定的工作时间应当按要求着装。遇有下列情形之一的,可以不着装： （一）执行侦查（察）、警卫、外事等特殊工作任务不宜着装的； （二）工作时间非因公外出的； （三）女性民警怀孕期间； （四）其他不宜或者不需要着装的情形。"},{"i":34,"n":"第三十四条","txt":"公安民警因涉嫌违纪违法被留置、停止执行职务、禁闭期间，或者被采取刑事强制措施和其他可能影响人民警察形象声誉的情形，不得着装。"},{"i":35,"n":"第三十五条","txt":"公安民警调离、辞职或者被辞退、开除公职的，应当收回所配发的人民警察证、警服和警衔、警号等警用标志。公安民警退（离）休的，可以保留一套常服和警衔、警号等警用标志作为纪念。 县级以上公安机关负责统一回收警服及警用标志。"},{"i":36,"n":"第三十六条","txt":"公安民警应当根据工作时间和场合需要着装。在工作时间，一般穿着执勤类服装；参加训练时，穿着作训类服装；参加荣誉仪式、宣誓、阅警、重要会议等活动时，穿着常服或者警礼服；参加重大纪念、庆典、外事等活动时，穿着警礼服。主管（主办）单位也可根据工作需要作出规定。 公安民警参加集体活动的统一着装，由活动组织单位确定。 警服的主要品种、穿着规范图示由公安部政治部和警服主管部门另行发布。"},{"i":37,"n":"第三十七条","txt":"公安民警着装时应当严格遵守以下规定： （一）按照规定配套穿着，不同制式警服不得混穿，警服与便服不得混穿，警服内穿着非制式服装时，不得外露； （二）按照规定缀钉、佩戴警衔、警号、胸徽、帽徽、领花、从警章等标志，系扎制式腰带，不同制式警用标志不得混戴。除工作需要外，不得佩戴、系挂与公安民警身份或者执行公务无关的标志、物品； （三）除执行抢险救灾等工作任务外，应当保持警服整洁得体，不得披衣、敞怀、挽袖、卷裤腿等； （四）除工作需要或者其他特殊情形外，应当穿制式皮鞋、作训鞋或者其他黑色皮鞋，穿深色袜子，不得赤脚穿鞋或者赤脚。男性民警鞋跟一般不高于3厘米，女性民警鞋跟一般不高于4厘米； （五）除工作需要或者其他特殊情形外，不得化浓妆，不得留长指甲或者染指甲，不得系扎非制式围巾，不得在外露的腰带上系挂手机、钥匙和饰物等，不得戴耳环、耳钉、项链、戒指、腕饰等。除工作需要外，不得文身，不得穿耳洞（女性"},{"i":38,"n":"第三十八条","txt":"除工作需要外，公安民警不得烫染、蓄留明显夸张的发色、发型。男性民警不得留长发、大鬓角、卷发（自然卷除外）、蓄胡须。除病理等因素外，公安民警不得剃光头。留长发的女性民警着装时应当束发，发辫不得过肩。"},{"i":39,"n":"第三十九条","txt":"公安民警着装时，除在办公区、宿舍或者其他特殊情形外，应当戴警帽。 进入室内时，通常脱帽。立姿可以将警帽用左手托夹于左腋下（帽顶向体外侧，帽徽朝前）；坐姿可以将警帽置于桌（台）前沿左侧或者用左手托放于左侧膝上（帽顶向上，帽徽朝前）。 在办公室和宿舍时，应当将警帽规范放置。"},{"i":40,"n":"第四十条","txt":"公安民警着装需佩戴统一颁发的徽章以及特殊识别标志或者专用臂章时，执行下列规定： （一）佩戴党员、团员徽章时，应当佩戴于警服左胸前警号正上方适当位置； （二）参加授勋授奖、重大纪念、庆典等重要活动时，可以在警服胸前适当位置佩戴勋章、奖章、纪念章； （三）参加重要会议、重大演习和其他重要活动时，可以按照要求佩戴专用识别标志； （四）执行维稳处突、抢险救灾等任务时，可以按照要求佩戴专用臂章； （五）公安院校在校学生可以佩戴院（校）徽章。"},{"i":41,"n":"第四十一条","txt":"在雾霾、有毒、粉尘、辐射、感染、噪声、强光、高温、低温、沙尘等环境下或者根据工作需要，公安民警应当穿戴手套、口罩、面罩、防护服、护目镜等防护装备。"},{"i":42,"n":"第四十二条","txt":"公安民警应当爱护和妥善保管警服及警衔、警号、胸徽、帽徽、领花等标志，不得赠送、转借给非人民警察身份人员。"},{"i":43,"n":"第四十三条","txt":"公安民警季节换装的时间和要求由设区的市级以上公安机关根据需要合理确定。"},{"i":44,"n":"第四十四条","txt":"因工作需要，退（离）休公安民警参加重大纪念、庆典等活动时，可以穿着退（离）休时的制式服装，佩戴工作期间和退（离）休后荣获的勋章、奖章等徽章。 公安院校公安专业学生着装时，参照上述规定执行。"},{"i":45,"n":"第四十五条","txt":"因拍摄、制作影视作品或者演出等需要，使用警服及警用标志的，应当按规定履行审批程序，并严格保管。 批准机关应当按照本条令指导影视制作、文艺演出单位严格遵守公安机关着装要求，不得损害公安机关和公安民警形象。非拍摄、演出时不得使用。"},{"i":46,"n":"第四十六条","txt":"公安民警应当模范遵守法律法规，自觉践行社会主义核心价值观。"},{"i":47,"n":"第四十七条","txt":"公安民警应当精神饱满，仪表端庄，举止文明。"},{"i":48,"n":"第四十八条","txt":"两名以上公安民警着装外出时，一般两人成行、三人成列，行列整齐，威严有序。徒步巡逻执勤可视现场情况采取有效警戒队形行进。"},{"i":49,"n":"第四十九条","txt":"公安民警着装时，不得在公共场所吸烟，不得嬉笑打闹、高声喧哗，不得有背手、袖手、插兜、搭肩、挽臂、揽腰等影响警容形象的行为，不得随意席地坐卧。"},{"i":50,"n":"第五十条","txt":"公安民警参加统一组织的集会、会议或者晚会的，按照规定时间和顺序入场，按照指定位置就座，遵守会场秩序，不得迟到早退。散会时，依次退场。"},{"i":51,"n":"第五十一条","txt":"公安民警外出，应当遵守公共秩序和社会公德，自觉维护人民警察的形象和声誉。与他人发生纠纷时，应当依法处理。"},{"i":52,"n":"第五十二条","txt":"公安民警遇到人民群众生命财产安全受到威胁时，应当积极救助或者寻求支援。"},{"i":53,"n":"第五十三条","txt":"公安民警工作时间不得饮酒，不得携带枪支饮酒，未经批准，不得穿着警服饮酒。"},{"i":54,"n":"第五十四条","txt":"公安民警严禁参与黄、赌、毒活动，严禁参加邪教组织，严禁参与封建迷信活动，除工作需要外，严禁参与宗教活动。工作期间，除工作需要外，不得进入歌舞娱乐场所娱乐；穿着警服进入歌舞娱乐场所的，应当自觉维护人民警察警容风纪。"},{"i":55,"n":"第五十五条","txt":"公安民警不得散布有损宪法权威、中国共产党和国家声誉的言论，不得组织或者参加非法组织，不得组织或者参加旨在反对宪法、中国共产党领导和国家的集会、游行、示威等活动，不得传抄、张贴、私藏非法印刷品，不得组织或者参加罢工、串联上访。未经批准，不得接受采访。"},{"i":56,"n":"第五十六条","txt":"公安民警不得接受对工作有影响的宴请和礼品馈赠，不得从事本职以外的其他职业和有偿中介活动，不得参与以营利为目的的文艺演出、企业形象代言等活动，不得以人民警察的名义和肖像做商业广告。"},{"i":57,"n":"第五十七条","txt":"公安民警使用网络社交媒体不得有下列行为： （一）制作、传播与党的理论、路线、方针、政策相违背的信息和言论； （二）制作、传播诋毁中国共产党、国家和公安机关形象的信息和言论； （三）制作、传播低俗信息、不实信息和不当言论； （四）制作、传播、讨论国家秘密、工作秘密或者内部敏感信息； （五）擅自发布涉及警务工作秘密的文字、图片、音视频； （六）未经批准，以人民警察身份开设微博、微信等网络社交平台公众号，个人微博、微信等网络社交媒体头像使用公安机关标志与符号； （七）利用网络社交工具的支付、红包、转账等功能变相进行权钱交易； （八）利用网络社交媒体进行不正当交往，非工作需要加入有明显不良倾向的微信群、论坛等网络社交群体； （九）利用网络社交媒体从事其他与法律法规、党纪条规和党的优良传统相违背的活动。"},{"i":58,"n":"第五十八条","txt":"公安民警不得擅自处置公安信息网信息。确需删除、更改的，应当严格按规定履行审批手续。"},{"i":59,"n":"第五十九条","txt":"公安机关应当经常开展警容风纪教育，建立健全监督检查制度。"},{"i":60,"n":"第六十条","txt":"县级以上公安机关应当加强对警容风纪的日常监督检查，并且定期组织集中检查，及时发现并纠正问题。 对违反警容风纪的公安民警，由督察部门按规定处理。"},{"i":61,"n":"第六十一条","txt":"公安民警应当注重内部礼节，充分体现公安机关内部的团结友爱和互相尊重。"},{"i":62,"n":"第六十二条","txt":"公安民警敬礼分为举手礼和注目礼。着装时通常行举手礼，正在执行任务或者携带武器装备等不便行举手礼时，可以行注目礼。着便服时，通常行注目礼。"},{"i":63,"n":"第六十三条","txt":"公安民警着装进见或者遇见上级机关领导时，应当主动敬礼。上级机关领导受礼后，应当主动回礼。"},{"i":64,"n":"第六十四条","txt":"列队的公安民警遇有上级检查指导工作，带队 人员应当主动向上级敬礼和报告，其他人员行注目礼。"},{"i":65,"n":"第六十五条","txt":"公安民警进见或者遇见本单位经常接触的领导以及在不便敬礼的场合时，可不行举手礼，应当主动致意，领导应当主动回礼。"},{"i":66,"n":"第六十六条","txt":"公安民警交接岗时，应当互相敬礼；不同单位的公安民警因公接触时，应当互相致意。"},{"i":67,"n":"第六十七条","txt":"公安民警因工作需要与人民群众、党政机关工作人员或者外宾接触时，应当主动致意或者敬礼。"},{"i":68,"n":"第六十八条","txt":"升国旗、警旗时，在场的公安民警应当面向国旗、警旗立正，着装的行举手礼，着便服的行注目礼。"},{"i":69,"n":"第六十九条","txt":"奏（唱）中华人民共和国国歌、中国人民警察警歌时，在场的公安民警应当自行立正，举止庄重，肃立致敬。"},{"i":70,"n":"第七十条","txt":"公安机关应当加强理论武装，强化公安民警政治历练、思想淬炼、实践锻炼、专业训练，建设学习型机关。"},{"i":71,"n":"第七十一条","txt":"学习内容应当根据形势任务和履职需要科学安排，主要包括政治理论、政策法规、公安业务、科技知识、警务技能等。"},{"i":72,"n":"第七十二条","txt":"公安机关应当突出政治理论学习，把习近平新时代中国特色社会主义思想、党中央关于加强新时代公安工作的决策部署作为重点学习内容，确保全警坚定理想信念、筑牢政治忠诚，统一意志、统一行动、步调一致向前进。"},{"i":73,"n":"第七十三条","txt":"公安机关应当定期制订学习计划，统筹安排时间和形式，采取集体学习与个人自学相结合的方式进行，创新学习方法，注重学习效果，检查学习情况。 公安机关应当结合工作需要，每月至少组织一次集中学习。"},{"i":74,"n":"第七十四条","txt":"公安机关应当坚持精简高效、厉行节约、讲求实效的原则，从严控制会议数量、时间和规模、标准。"},{"i":75,"n":"第七十五条","txt":"设区的市级以上公安机关每年应当召开一次年度工作会议，传达学习党中央和上级机关有关精神和决策部署，研究安排本级公安机关重点工作任务。 县级公安机关每年至少召开一次全体大会或者公安民警代表会议，及时总结工作、表彰先进、部署任务。 公安机关召开年度工作会议时，可以根据工作需要邀请人民群众代表和有关部门参加。"},{"i":76,"n":"第七十六条","txt":"基层所队等一线实战单位应当建立工作例会制度，及时梳理情况、总结点评、安排布置工作。"},{"i":77,"n":"第七十七条","txt":"公安机关应当严格按照规定组织会议，严肃会议纪律，不得组织与会议无关的活动，不得超标准用餐、住宿，严禁以任何名义发放礼品、纪念品、土特产，严禁组织高消费娱乐、健身、聚餐、参观景点等活动。"},{"i":78,"n":"第七十八条","txt":"公安机关必须认真落实中国共产党政法工作条例、重大事项请示报告条例等规定，建立严格的请示报告制度，明确请示报告主体、范围、程序和方式等，严明党的政治纪律、组织纪律和工作纪律，确保政令警令畅通。 请示报告工作应当坚持政治导向，严格政治纪律和政治规矩，把讲政治要求贯彻到请示报告工作全过程和各方面；坚持权责明晰，既要及时请示报告，又要负责担当，防止矛盾问题上交；坚持客观真实、实事求是请示报告工作，提出意见建议；坚持规范有序，严格按规定的主体、范围、程序和方式请示报告工作。"},{"i":79,"n":"第七十九条","txt":"下级机关对非本单位职权范围或者本单位无法解决的问题，应当及时请示上级机关。请示报告可以根据事项类型和缓急程度采取口头、书面等方式进行。对于口头请示报告的事项，双方应当及时做好记录。 公安机关主要负责同志是第一责任人，对请示报告事项负总责。 上级机关对下级机关的请示事项，应当认真研究、及时答复。"},{"i":80,"n":"第八十条","txt":"请示报告应当逐级进行。特殊情况下，可以按照有关规定越级请示报告。 接受双重领导的单位，应当根据事项性质和内容向负有主要领导职责的上级机关请示报告，同时抄报另一个上级机关。特殊情况下，可以不抄报。"},{"i":81,"n":"第八十一条","txt":"下级机关一般每半年向上级机关报告公安工作和公安队伍建设的基本情况。 遇有下列情形时，应当在规定时限内及时向上级机关报告，任何单位和个人不得以任何理由瞒报、虚报、迟报或者不报： （一）发生危害国家安全和影响社会稳定的案（事）件； （二）发生重特大刑事案件； （三）发生重特大群体性事件； （四）发生重特大事故灾难； （五）发生恐怖袭击事件； （六）发生重特大涉外突发事件； （七）发生重特大自然灾害、疫情； （八）发生重大涉警舆情； （九）发生公安民警伤亡事件（故）、重大违纪违法、公务用枪案事（件）和执法权威受到侵犯的重大案（事）件。"},{"i":82,"n":"第八十二条","txt":"公安机关主要负责同志离开本地区，应当提前向上级机关主要负责同志请假。因紧急事项临时请假的，应当立即按规定报告。 公安机关主要负责同志、分管日常工作的负责同志（含双正职领导）原则上不能同时离开本地区。 公安机关主要负责同志请假内容包括：请假人员、事由、时间、地点等，主持工作的负责同志及其相关信息。请假期间如行程发生变化的，应当及时补充报告。 公安机关领导干部异地执行任务需离开任务地的，应当及时向所在单位或者任务派出单位有关负责同志请假。"},{"i":83,"n":"第八十三条","txt":"公安民警工作时间非因公外出，应当逐级请假、按时销假，未经批准，不得擅自离岗。因伤、病或者其他原因不能按时上班时，应当及时请假。"},{"i":84,"n":"第八十四条","txt":"公安民警执行特殊或者紧急任务时，非因不可抗拒的原因，不得请假。"},{"i":85,"n":"第八十五条","txt":"请假人员未经批准，不得逾期不归。确有特殊情况的，经批准后可以续假。"},{"i":86,"n":"第八十六条","txt":"对伤、病人员，根据伤、病情况或者医院诊疗建议，按规定审批后准予休息。"},{"i":87,"n":"第八十七条","txt":"请假人员在请假期间应当保持通讯畅通。除特殊情况外，因工作需要召回的，应当立即返回工作岗位。"},{"i":88,"n":"第八十八条","txt":"公安民警在工作变动、退休、辞职或者被辞退、开除公职时，应当将所负责的工作情况和掌管的文件、材料、证件、武器、弹药、器材、数字证书等进行移交，清退涉密载体，并按规定执行脱密期管理和监督。移交工作应当在本人离开工作岗位前完成。 移交前，所在单位领导应当指定接管人。交接时，双方当面清点，必要时由单位领导主持或者请纪检监察等有关部门参加；交接后，双方在交接登记册（表）上签字。"},{"i":89,"n":"第八十九条","txt":"公安机关或者警种、部门主要负责同志和其他负有经济责任的领导干部办理调任、转任、免职、辞职、退休以及调整分工等事项前，审计部门应当按照领导干部经济责任审计有关规定对其任职期间履行经济责任情况进行审计。"},{"i":90,"n":"第九十条","txt":"公安民警因出差出国、学习培训或者休假等短期离开岗位时，应当将负责的工作安排妥当。"},{"i":91,"n":"第九十一条","txt":"公安机关印章（含电子印章）的刻制应当严格按照规定审批，并在指定机构刻制。"},{"i":92,"n":"第九十二条","txt":"新刻制的印章，应当在制发机关留取印模，备案后方可启用。"},{"i":93,"n":"第九十三条","txt":"使用印章（印模）应当按照规定权限，严格履行审批登记手续，严格用印监督管理。严禁利用公章谋私，严禁在空白文件或者信函上加盖印章。"},{"i":94,"n":"第九十四条","txt":"印章（印模）应当专柜存放，专人保管。印章（印模）丢失应当立即上报，及时通报有关单位，并严肃追究责任。"},{"i":95,"n":"第九十五条","txt":"经批准作废的印章，应当登记造册，上交制发机关即行销毁。停止使用的印章，应当上交制发机关处理。"},{"i":96,"n":"第九十六条","txt":"公安民警应当按照规定使用统一的人民警察证。工作期间，一般应当携带人民警察证。"},{"i":97,"n":"第九十七条","txt":"公安机关应当严格人民警察证配发范围，严禁向非人民警察身份人员配发人民警察证。 对丧失配发资格的，应当及时收回、收缴其人民警察证。"},{"i":98,"n":"第九十八条","txt":"人民警察证由公安部按照规定统一监制，实行分级管理。"},{"i":99,"n":"第九十九条","txt":"公安机关应当建立保密工作制度，加强保密宣传教育，强化监督管理，严格保密纪律要求，落实保密工作责任，确保国家秘密和警务工作秘密绝对安全。"},{"i":100,"n":"第一百条","txt":"公安机关应当严格按照国家保密管理规定，准确划定保密要害部门、部位，以及涉密岗位、涉密人员范围。"},{"i":101,"n":"第一百零一条","txt":"公安机关政工部门应当会同保密部门，按照“先审后用、严格把关”的原则，对拟任（聘）用到涉密岗位的人员进行保密审查，并定期对在岗涉密人员组织复审。 涉密人员因公、因私出国（境）的，按照管理权限和规定程序实行严格审批。一般情况下，核心涉密人员因私出国（境）不予批准。"},{"i":102,"n":"第一百零二条","txt":"公安机关应当强化涉密人员日常监督，严格落实保密承诺要求、重大事项报告制度，加强涉密人员离岗离职脱密期管理。"},{"i":103,"n":"第一百零三条","txt":"公安民警在制作、传递、复制、使用、保存和销毁涉密信息或者载体过程中，应当严格执行国家保密管理规定，确保涉密信息或者载体保密安全。 涉密载体是指以文字、数据、符号、图形、图像、声音等方式记载、存储国家秘密信息和警务工作秘密信息的纸介质载体、电磁介质载体、光盘等各类物品。"},{"i":104,"n":"第一百零四条","txt":"需要归档的涉密载体，应当按照要求立卷归档；不需要归档的涉密载体，应当认真履行清点、登记、审批手续后，按规定予以销毁。"},{"i":105,"n":"第一百零五条","txt":"公安民警应当执行下列保密守则： （一）不该说的秘密不说； （二）不该知悉的秘密不问； （三）不该看的秘密不看； （四）不在私人交往或者公开发表的作品中涉及秘密； （五）不在非保密场所阅办、谈论秘密； （六）不在社交媒体发布、传递秘密； （七）不擅自记录、复制、拍摄、摘抄、收藏秘密； （八）不擅自携带涉密载体去公共场所或者探亲访友； （九）不使用无保密措施的通信设备、普通邮政和计算机互联网络传递秘密。"},{"i":106,"n":"第一百零六条","txt":"使用计算机信息系统和信息设备时，应当严格遵守下列规定： （一）涉密计算机严禁连接公安信息网和互联网及其他公共信息网络，公安信息网计算机严禁连接互联网等其他公共信息网络； （二）涉密计算机不得连接市话和公安专线传真机或者具有传真功能的多功能一体机，不得安装无线网卡、无线鼠标、无线键盘等具有无线互联功能的设备，不得安装摄像头、麦克风等音视频采集装置； （三）公安信息网计算机不得安装无线网卡、无线鼠标、无线键盘等具有无线互联功能的设备，在保密要害部门、部位的公安信息网计算机不得安装摄像头、麦克风等音视频采集装置； （四）涉密场所使用的互联网计算机严禁通过无线方式连接互联网，严禁安装摄像头、麦克风等音视频采集装置，严禁安装移动热点； （五）严禁使用互联网计算机和连接互联网的移动警务终端处理、存储、传输、发布国家秘密信息和警务工作秘密信息，连接互联网的移动警务终端不得与涉密信息设备和公安信息网计"},{"i":107,"n":"第一百零七条","txt":"公安机关及定密责任人应当严格按照规定的定密权限和程序准确定密，并完整标注密级和保密期限。"},{"i":108,"n":"第一百零八条","txt":"公安机关信息公开应当坚持“先审查、后公开”和“一事一审”原则，履行保密审查审批程序，严格网站信息发布登记，定期组织开展网站保密检查。"},{"i":109,"n":"第一百零九条","txt":"公安机关使用微信群、QQ群、微博、微信公众号等网络社交媒体开展工作的，应当建立健全保密管理制度。"},{"i":110,"n":"第一百一十条","txt":"发现泄密线索和情况的，应当立即向本单位保密部门报告，及时组织查处，并按规定上报。"},{"i":111,"n":"第一百一十一条","txt":"公安机关应当建立健全档案工作制度，严格规范管理，维护档案的真实、完整、可用和安全。"},{"i":112,"n":"第一百一十二条","txt":"公安机关在工作中形成的属于归档范围的全部档案应当由档案部门集中统一管理。任何部门和个人不得据为己有或者拒绝归档。 干部人事档案按照干部管理权限，由相应机关或者单位组织人事部门负责统一管理。"},{"i":113,"n":"第一百一十三条","txt":"按照“谁形成、谁归档”的原则，及时收集整理列入归档范围的文件材料，严格按规定移交归档。"},{"i":114,"n":"第一百一十四条","txt":"公安机关应当加强对开展专项行动、举办重要会议和活动、处置重大案（事）件、承建重大建设项目等过程中形成文件材料的收集和归档。"},{"i":115,"n":"第一百一十五条","txt":"公安机关应当建立符合国家标准的档案用房，配备档案安全防护设施，定期巡查档案保管情况，确保档案实体和信息的安全保密。"},{"i":116,"n":"第一百一十六条","txt":"公安机关应当加强档案借阅管理，根据档案的特点、密级，确定相应的借阅范围和审批程序。"},{"i":117,"n":"第一百一十七条","txt":"公安民警应当严格遵守档案借阅规定，对借阅的档案负有保管保护责任，不得涂改、拆撕、伪造档案。不得擅自将档案转借他人。"},{"i":118,"n":"第一百一十八条","txt":"公安档案非经鉴定不得销毁。"},{"i":119,"n":"第一百一十九条","txt":"公安机关的内务设置应当有利于工作、学习、生活，因地制宜、整齐划一，符合卫生和安全要求。"},{"i":120,"n":"第一百二十条","txt":"公安机关对同类窗口单位应当设置规格统一、标志明显、便于辨识的标志，并及时进行维护、更新。入驻政府集中办公场所的窗口单位，应当突出公安机关特点，按照有关单位要求合理设置。 根据窗口单位的实际条件，合理划分办公区、服务区、等候区等功能区域，确保各功能区域相对独立、秩序良好。"},{"i":121,"n":"第一百二十一条","txt":"公安派出所等基层所队应当按照规定合理规范设置办公、办案、生活等区域，配备相应的设备设施。 按照建设标准要求，因地制宜建立阅览室、健身房、洗衣房、淋浴室和食堂等，丰富公安民警的文体生活，保障公安民警身心健康。"},{"i":122,"n":"第一百二十二条","txt":"县级以上公安机关应当建立荣誉室，有条件的可以建立史迹陈列馆、纪念馆、警察博物馆等。 有条件的基层所队，可以结合实际建立荣誉室。"},{"i":123,"n":"第一百二十三条","txt":"办公、生活区域环境和各类设备物品摆放，应当保持干净、整洁、有序。"},{"i":124,"n":"第一百二十四条","txt":"公安机关应当加强办公秩序管理，维护正常的工作、学习、生活秩序，保证办公环境整洁，秩序井然。"},{"i":125,"n":"第一百二十五条","txt":"公安民警应当严格遵守工作时间要求，不得无故迟到、早退。工作时间应当保持肃静，不得大声喧哗、闲聊、办私事、因私会客或者从事其他与工作无关的活动。"},{"i":126,"n":"第一百二十六条","txt":"公安机关应当严格办公区管理，建立门卫制度，加强日常值守，强化安全检查。 本单位人员、车辆应当凭有效证件出入办公区。外来人员、车辆需进入办公区的，应当严格登记手续，查验其证件和携带物品，经接待人员允许后方可进入。 严禁将办公用房出租或者无偿提供给外部人员或者其他单位使用。"},{"i":127,"n":"第一百二十七条","txt":"单位内部交通标志应当醒目、齐全，车辆应当按照指定地点停放，按照规定路线、速度行驶，禁止鸣喇叭、急刹车。骑自行车、电动车出入大门应当主动下车或者接受查验。"},{"i":128,"n":"第一百二十八条","txt":"公安民警接待群众应当文明礼貌、态度和蔼、热情周到、耐心细致。"},{"i":129,"n":"第一百二十九条","txt":"公安机关应当简化办事程序，拓宽服务渠道，提高工作效能。在条件允许的情况下，推行一个窗口对外、一站式办结和预约服务、自助受理、网上办理等。"},{"i":130,"n":"第一百三十条","txt":"公安机关应当按规定主动公开公示窗口单位的上下班时间以及报警、咨询、监督电话和工作人员等信息，依法公开工作职责、执法依据、办事程序、法定时限、收费标准、监督方式以及服务承诺等，可以通过报刊、电台、电视台、政府网站和微博、微信公众号及其他信息手段，以及公示栏、牌匾、触摸式查询显示屏或者印发书面材料等形式告知群众，为群众提供方便。"},{"i":131,"n":"第一百三十一条","txt":"公安机关应当结合实际制定工作文明用语和忌语，加强教育培训，严格遵照执行。"},{"i":132,"n":"第一百三十二条","txt":"公安机关窗口单位实行群众报警、求助、咨询和办证、办事首问（接）责任制、接报案登记制和分流移交机制。 除24小时服务窗口外，其他窗口单位可根据实际实行弹性工作制，方便群众办证、办事。"},{"i":133,"n":"第一百三十三条","txt":"公安民警应当在职责范围内，热情为求助群众提供必要帮助，耐心解答群众提出的问题，及时妥善处理群众报警或者报案，并认真做好记录。对不属于公安机关职责范围内的群众报警、报案或者求助，应当告知当事人向其他有关主管机关反映，情况紧急时应当给予协助或者协调处置。"},{"i":134,"n":"第一百三十四条","txt":"除执行重大紧急任务外，公安机关的警车在临时停靠时或者行驶过程中，车上的公安民警应当及时接受群众的现场报警或者紧急求助。"},{"i":135,"n":"第一百三十五条","txt":"公安机关实行24小时值班备勤。由领导干部带班，安排适当警力值班备勤，配备相应警械武器、防护装备和交通、通讯工具，保障随时应对各类警情任务。基层一线处警单位及警用车辆应当配备防弹防刺背心、头盔及绳索、救生圈、急救包等警用装备和救援器材，并做好装备、器材使用培训和维护保养，确保正常使用。"},{"i":136,"n":"第一百三十六条","txt":"看守所、拘留所、派出所和治安、刑警、交警、巡警、网安等警种、部门，应当根据工作需要，设置值班室，建立健全值班备勤制度。"},{"i":137,"n":"第一百三十七条","txt":"值班人员的主要职责是： （一）接待报警、报案、检举、控告、自动投案或者其他原因来访的人员； （二）受理群众遇到危、难、险、困时的求助，以及群众对公安民警违纪违法行为的投诉； （三）向上级报告发生的案件、事故或者其他紧急情况，并按照上级指示或者预案做出应急处理； （四）及时接收处置110警情指令； （五）及时妥善处理公文、电话、电子邮件等； （六）维护本单位工作、学习、生活秩序，承担内部安全保卫工作； （七）完成领导交办的其他任务。"},{"i":138,"n":"第一百三十八条","txt":"值班室应当利用视频监控系统，建立值班影像档案，并保存不少于九十日。值班人员应当认真填写值班记录，详细记录值班期间发生的重要事项及处置情况。值班记录的主要内容包括： （一）问题或者事件事情发生的时间、地点，有关人员的姓名、联系方式和主要情况； （二）向上级报告的时间，接受报告人的姓名和答复的主要内容； （三）对上级指示的传达、办理情况和时间； （四）负责处理的单位和人员姓名； （五）值班领导和值班民警姓名。 值班记录应当采用电子文档或者纸质文书存档，妥善管理。"},{"i":139,"n":"第一百三十九条","txt":"值班人员应当坚守岗位，严格履行职责。因故确需离开值班岗位的，应当及时报告值班领导，并安排其他人员代岗。"},{"i":140,"n":"第一百四十条","txt":"值班人员交接班时，双方应当按照规定的职责内容认真交接工作，履行交接手续。 值班人员交接班时，如果发生突发情况或者群众报警、报案，以交班人员为主进行处置，待处置完毕再交接班。"},{"i":141,"n":"第一百四十一条","txt":"值班备勤人员自值班备勤前12小时至值班备勤结束不得饮酒，值班期间不得从事与工作无关的活动，备勤期间不得从事影响紧急到岗的活动。"},{"i":142,"n":"第一百四十二条","txt":"公安机关应当预先制订各种应急处置预案，定期组织实战演练，不断提高快速反应能力、协调配合能力、现场处置能力、临场组织指挥能力。"},{"i":143,"n":"第一百四十三条","txt":"遇有第八十一条第二款所列情形或者其他紧急任务，县级以上公安机关应当按照应急处置预案，组织人员立即赶赴现场，并根据实际情况，在报告上级机关的同时，迅速通报有关部门及时做好防范、化解和处置突发案（事）件工作。"},{"i":144,"n":"第一百四十四条","txt":"公安民警接到执行紧急任务的命令后，应当迅速到达指定地点，服从统一的指挥调度。发现紧急情况时，应当及时报告并迅速进入现场履行职责。"},{"i":145,"n":"第一百四十五条","txt":"公安机关在处置突发事件时，应当根据突发事件的性质、起因、规模、影响以及现场情势和危害程度，决定是否动用处置性警力及规模，是否采取强制性措施以及采取何种强制性措施，是否使用警械或者武器，既要防止当用不用而使事态失去控制或者致使公安民警伤亡情况发生，也要防止警力和强制性措施使用不当而激化矛盾。公安民警在采取强制性措施前，应当经现场指挥员批准，并向现场人员明示告知。在面临紧急情况下，公安民警可先期处置，并在处置过程中或者处置后及时报告。 情报指挥部门应当及时跟进掌握处置突发事件情况，视情调动警力支援。"},{"i":146,"n":"第一百四十六条","txt":"公安机关在处置突发事件时，应当注意保护党政机关等重点部位及现场人员的安全，同时加强公安民警自身的安全防护，及时获取并固定现场违法犯罪证据。"},{"i":147,"n":"第一百四十七条","txt":"公安民警应当保证通讯畅通，个人通讯方式变更时应当及时报告所在单位，以备发生紧急情况时迅即调集警力。"},{"i":148,"n":"第一百四十八条","txt":"公安机关装备管理应当严格执行有关法律法规规定，遵循整体规划、标准配备、权责相应、规范管理的原则。"},{"i":149,"n":"第一百四十九条","txt":"公安机关应当建立健全装备使用管理、维护保养、存储保管和督察、审计等制度。"},{"i":150,"n":"第一百五十条","txt":"公安机关应当按规定建设装备存储保管场所、完善配套设施，实行分级分类管理。"},{"i":151,"n":"第一百五十一条","txt":"公安机关执法办案管理中心、服务窗口等场所配备的装备品种、数量和方式，应当符合装备使用安全和环境要求。"},{"i":152,"n":"第一百五十二条","txt":"公安机关应当定期开展执法执勤装备检查、校验、测试、标定等工作，确保性能良好。监督检查重点是指挥通信、刑事技术、侦查技术、警械武器、交通工具、防护等装备。"},{"i":153,"n":"第一百五十三条","txt":"公安机关应当加强执法执勤装备使用培训。"},{"i":154,"n":"第一百五十四条","txt":"公安机关应当加强应急装备管理，建立应急装备保障机制，制订应急装备保障预案，按规定开展应急装备管理工作。"},{"i":155,"n":"第一百五十五条","txt":"公安机关发生重大装备事故的，应当迅速开展实地调查，查明事故原因，出具鉴定报告，并及时向上级公安机关报告。"},{"i":156,"n":"第一百五十六条","txt":"任何单位或者个人不得擅自赠送、转借、出租、变卖、私存装备。"},{"i":157,"n":"第一百五十七条","txt":"公安机关应当严格执行国家预算财务管理法律法规有关规定，规范财务行为，科学合理编制预算、决算及相关预算财务报表，提高资金使用效益。"},{"i":158,"n":"第一百五十八条","txt":"公安机关应当建立健全财务管理制度、定期财务分析报告制度和内部控制机制，加强对下级机关财务管理的指导、监督和检查。"},{"i":159,"n":"第一百五十九条","txt":"公安机关应当按照国家统一会计制度开展会计工作，依法设置会计账簿，并保证会计账簿的真实、完整。 审计部门应当按照内部审计工作规定，对财政收支、财务收支以及其他经济活动等财经管理情况组织实施审计。"},{"i":160,"n":"第一百六十条","txt":"公安机关主要负责同志对本单位会计工作和会计资料的真实性、完整性、合法性负责。"},{"i":161,"n":"第一百六十一条","txt":"公安机关应当牢固树立安全意识，加强安全管理工作，并贯穿于公安工作和公安队伍建设的全过程。"},{"i":162,"n":"第一百六十二条","txt":"公安机关应当坚持预防为主的方针，定期分析安全工作形势，查找不安全因素和隐患，制定和改进安全措施，建立健全安全管理制度，加强人防、物防、技防建设，并根据职责分工，压实工作责任，保证各项制度、措施落到实处。"},{"i":163,"n":"第一百六十三条","txt":"公安机关应当加强安全教育，增强公安民警的安全防范意识，及时发现并正确处理队伍内部问题，积极消除安全隐患。强化安全训练，确保公安民警熟练使用警械武器装备，规范使用交通工具，正确处理各类情况和问题，不断提高自我防护、预防安全事故的能力。"},{"i":164,"n":"第一百六十四条","txt":"公安机关应当根据形势任务和环境变化需要，配备安全防护设备设施，加强经常性安全防范工作，开展内部日常安全防范检查，严防发生重大安全事故。"},{"i":165,"n":"第一百六十五条","txt":"发生安全事故应当如实及时上报，查明原因，正确处理，做到实事求是、依法依规。对避重就轻、弄虚作假、不及时报告或者隐瞒不报的，应当依法依规严肃追责问责。"},{"i":166,"n":"第一百六十六条","txt":"县级以上公安机关应当建立维护公安民警执法权威工作委员会，实行党委（党组）统一领导、督察部门牵头协调、职能部门各负其责的工作机制，通过法律、行政、经济、社会、舆论等途径，依法及时查处侵犯公安民警执法权威的行为，为公安民警依法履职创造良好环境。"},{"i":167,"n":"第一百六十七条","txt":"公安机关办公区、办案区应当建设必要的安全技术防范系统，主要出入口、窗口单位服务区应当配备安检和视频监控设备，办案区应当配备同步录音录像设备，并保证设备完好、正常使用。办案区的声像监控资料应当保存不少于九十日，其他区域的声像监控资料应当保存不少于三十日。 对办案区声像监控资料保存期限另有规定的，从其规定。"},{"i":168,"n":"第一百六十八条","txt":"公安机关应当严格在办案区开展办案活动，强化安全意识，落实安全防范措施和责任，防止发生安全事故。"},{"i":169,"n":"第一百六十九条","txt":"公安机关处置暴力恐怖案（事）件或者执行拘留、抓捕等任务时，应当评估安全风险，制订预案方案，周密组织实施，最大限度地避免造成人员伤亡。"},{"i":170,"n":"第一百七十条","txt":"上级对下级布置任务时，应当明确安全要求，并采取安全保障措施。执行任务的公安民警应当提高安全防范意识，严格遵守安全管理制度，保持高度警惕，确保自身和工作对象安全。"},{"i":171,"n":"第一百七十一条","txt":"公安民警执行询问、讯问、押解、看管等任务时，应当严格遵守有关规定，防止发生违法犯罪嫌疑人袭警、脱逃、暴狱和自伤、自残、自杀等案（事）件。"},{"i":172,"n":"第一百七十二条","txt":"公安民警执法执勤时应当按规定携带装备，并规范使用执法记录仪等设备。"},{"i":173,"n":"第一百七十三条","txt":"公安民警开展治安检查、现场勘验等工作时，应当严格遵守法定程序及操作规程，防止发生安全事故（件）。"},{"i":174,"n":"第一百七十四条","txt":"公安民警因工作需要在道路上拦截、检查车辆时，应当选择安全和不妨碍通行的地点进行，设置安全防护设备。必要时，设置减速区、检查区、处置区，并使用阻车装置。"},{"i":175,"n":"第一百七十五条","txt":"公安机关应当建立健全公务用枪管理制度，认真执行安全管理措施，严格落实工作责任。 公安机关应当组建公务用枪管理委员会，明确职责分工，建立定期会商研判机制，加强公务用枪管理工作检查监督。"},{"i":176,"n":"第一百七十六条","txt":"公安机关必须严格公安民警配枪标准条件，规范申报审批程序，加强年度审验把关，实行人员动态管理。"},{"i":177,"n":"第一百七十七条","txt":"公安机关及其所属配枪单位应当按要求设置枪弹库（室、柜），严格落实24小时值守、枪弹分离、双人双锁保管等制度，加强对视频监控等安全防范设施的日常检查，确保公务用枪存放安全。"},{"i":178,"n":"第一百七十八条","txt":"公安机关及其所属配枪单位应当定期对枪支弹药进行检测，严禁使用超寿命、待报废枪支和过期弹药，并加强对枪支弹药的日常维护保养，最大限度降低枪支弹药故障率。"},{"i":179,"n":"第一百七十九条","txt":"公安机关及其所属配枪单位应当建立健全枪弹领取、交还审批、登记等制度，认真查验持枪证、枪证等信息，确保公务用枪交接安全。"},{"i":180,"n":"第一百八十条","txt":"公安机关及所属配枪单位应当加强对枪支管理使用人员的日常教育培训、管理监督和思想、心理状况排查，对出现不适宜配枪情形的公安民警应当及时暂停或者取消其配枪资格，收回持枪证件，确保公务用枪使用安全。"},{"i":181,"n":"第一百八十一条","txt":"公安民警应当严格按照规定管理使用警械武器，确保依法履职尽责，有效维护群众和自身安全，坚决防止警械武器被盗、被抢、丢失、滥用或者发生其他事故。"},{"i":182,"n":"第一百八十二条","txt":"公安民警使用警械武器，应当以有效制止违法犯罪行为、尽量减少人员伤亡和财产损失为原则。"},{"i":183,"n":"第一百八十三条","txt":"公安机关组织公安民警进行实弹射击训练，应当遵守下列安全规定： （一）合理选择和设置射击场地； （二）加强现场安全检查，配备专职安全人员，严密组织射击区域安全警戒和观察； （三）加强枪支弹药的技术检测，防止枪支故障和弹药失效； （四）实弹射击训练时佩戴个人安全防护器材； （五）训练结束后统一组织验枪，彻底清查枪支和剩余弹药，防止枪支、弹药丢失，排查安全隐患。"},{"i":184,"n":"第一百八十四条","txt":"公安民警管理使用枪支的，应当遵守下列安全规定： （一）上班或者执行任务领用枪支后必须严格验枪，下班或者完成任务后必须及时交回并由枪管员验枪收回； （二）工作期间因私外出的，所携带枪支必须交回并由枪管员验枪收回； （三）在依法依规使用枪支的情形下，应当准确判定目标，规范操作动作，防止误判或者误伤他人； （四）严禁私存、私带、私借枪支弹药； （五）严禁持枪打闹或者枪口对人； （六）严禁摆弄枪支或者随意动用他人枪支； （七）严禁持枪打猎、擅自打靶或者安排他人打靶。"},{"i":185,"n":"第一百八十五条","txt":"公安机关应当加强交通安全事故防范和监督管理。除执行紧急任务外，公安民警驾驶车辆时应当遵守道路交通安全法律法规，确保行车安全。"},{"i":186,"n":"第一百八十六条","txt":"公安机关应当对公务车辆定期进行维护和保养，确保车况良好。对达到报废标准的车辆应当及时报废，不得使用已达到强制报废标准的车辆从事警务活动。"},{"i":187,"n":"第一百八十七条","txt":"公安民警驾驶警车时，除工作需要外，应当按照规定穿着警服，持有机动车（电子）行驶证、机动车（电子）驾驶证和人民警察证。驾驶实习期内的公安民警不得驾驶警车。公安民警驾驶或者乘坐警用摩托车时，应当戴警用头盔。"},{"i":188,"n":"第一百八十八条","txt":"公安机关警用车辆乘载，应当遵守下列安全规定： （一）载人不得超过核定的人数； （二）载物应当符合核定的载质量，严禁超载； （三）载物的长、宽、高不得违反装载要求； （四）不得人货混载； （五）不得违反有关安全规定，载运易燃、易爆等危险物品。"},{"i":189,"n":"第一百八十九条","txt":"公安机关应当定期对驾驶警车的公安民警开展培训，加强交通安全教育。"},{"i":190,"n":"第一百九十条","txt":"公安机关应当加强消防安全防范工作，建立消防管理制度，完善消防设施，配齐消防器材，落实消防责任，坚决防止发生火灾事故。"},{"i":191,"n":"第一百九十一条","txt":"公安机关应当严格消防安全检查，及时发现和消除火灾隐患。加强易燃、易爆物资和装备、器材管理，进入易燃、易爆物品存放场所前必须收缴火种。计算机机房、库房、车场、档案室等重要场所严禁烟火。"},{"i":192,"n":"第一百九十二条","txt":"在礼堂、剧院、大型会议场所等重要防火部位组织集体活动的，应当在应急疏散通道安排人员值守引导，维护现场秩序，防止发生意外。"},{"i":193,"n":"第一百九十三条","txt":"重点防火单位和重要防火场所应当制订消防预案，落实消防责任，定期组织有针对性的消防演练。"},{"i":194,"n":"第一百九十四条","txt":"公安机关应当遵守弹药、炸药、油料、燃气、烟花爆竹等易燃、易爆物品的安全管理规定，防止发生爆炸事故。"},{"i":195,"n":"第一百九十五条","txt":"爆炸物品的使用管理单位应当按照性质、类别将爆炸物品分别储存在专用仓库内，由专人管理，建立检查、登记制度。存放数量不得超过安全容量。在库区配备监控、防爆设施，严禁无关人员进入库区。"},{"i":196,"n":"第一百九十六条","txt":"组织爆炸物品运输，应当遵守下列安全规定： （一）正确选择运载工具和装卸载地点与方式； （二）正确选择运输路线，避开交通繁忙路段和人口稠密地区； （三）正确选择通过时机，避开人员、车辆流动高峰期； （四）正确装载爆炸物品，符合安全运输要求； （五）严密警戒，专人押运。"},{"i":197,"n":"第一百九十七条","txt":"组织实施民用爆炸物品、烟花爆竹、废旧炮（炸）弹等爆炸物品销毁，应当科学划定作业区域，设置安全警示标志，维护作业现场秩序，并严格遵守下列安全规定： （一）不得擅自变更计划、方案； （二）不得由非专业机构组织实施； （三）不得让未经培训的人员参与； （四）不得在不符合安全要求的场所或者场地作业； （五）不得在高温、雷雨、大风等不良天气条件下作业； （六）不得违反操作规程冒险作业。"},{"i":198,"n":"第一百九十八条","txt":"公安机关应当加强关爱民警工作，保护民警身心健康。基层公安机关应当根据工作任务和实有警力，执行轮休制度。对长期执行重大安全保卫、抢险救援、侦查监控任务以及长期从事重大专项工作的公安民警，应当合理安排调休；对连续工作超出法定工作时间的，应当安排休息。"},{"i":199,"n":"第一百九十九条","txt":"公安机关应当严格落实带薪年休假制度，领导干部应当带头休假。根据工作情况，充分尊重公安民警本人意愿，统筹安排年休假。公安民警确因工作需要不能安排年休假的，应当在下一年度安排补休；不能补休或者未休满法定年休假的，应当按规定发放年休假工资报酬。 上级机关应当对下级机关带薪休假落实情况进行督导检查，推动年休假常态化，确保公安民警得到必要的休整。"},{"i":200,"n":"第二百条","txt":"公安机关应当提倡全警健身，普及科学健身知识和健身方法，开展群众性体育活动；把体能训练作为公安民警教育训练的基本内容，提升体能素质；因地制宜、分类分年龄段开展公安民警年度体能测试。"},{"i":201,"n":"第二百零一条","txt":"公安机关应当严格落实年度体检制度，建立公安民警健康档案，定期对健康状况进行分析，提出健康保护意见。对体检结果异常的，督促并协助做好复查、就医，强化健康生活方式指导及干预。"},{"i":202,"n":"第二百零二条","txt":"公安机关应当开展职业病危害因素基本情况普查，健全针对性健康干预措施。为公安民警配备医疗急救包，确保突发疾病时能及时得到施救。"},{"i":203,"n":"第二百零三条","txt":"公安机关应当严格落实公安民警因公负伤和患病医疗保障救治制度。对因身体健康状况不适宜在现岗位上工作的公安民警，应当调整工作岗位或者安排适当休整。"},{"i":204,"n":"第二百零四条","txt":"公安机关应当开展预防传染病等卫生健康教育，提高公安民警对传染病的防治意识和应对能力。"},{"i":205,"n":"第二百零五条","txt":"公安机关应当加强对办公、办案、生活等场所区域的日常环境卫生管理，建立卫生管理制度，健全卫生安全保障措施，有效防止发生卫生安全事故。发现传染病病人或者疑似传染病病人时，应当按规定及时向所在地疾病预防控制机构或者医疗机构以及上级机关报告。"},{"i":206,"n":"第二百零六条","txt":"发生传染病疫情时，公安机关应当积极配合当地疾病预防控制机构或者医疗机构，采取有效措施，防止公安民警出现感染或者交叉感染，及时组织对办公、办案、生活等场所区域进行卫生处理。 根据工作需要，公安机关可实行弹性工作制，科学合理安排勤务，确保公安民警保持良好的身心状态。"},{"i":207,"n":"第二百零七条","txt":"发生传染病疫情时，公安机关应当对公安民警确诊受感染或者疑似感染情况，按规定逐级报告上级机关；对密切接触者，按照当地疾病预防控制机构要求，采取必要的预防措施。"},{"i":208,"n":"第二百零八条","txt":"公安机关应当建立平战结合、规范有序、及时高效的常态化心理健康服务工作机制，加强心理健康服务专兼职人才队伍建设，不断提升公安民警心理健康服务工作水平。"},{"i":209,"n":"第二百零九条","txt":"县级以上公安机关和有条件的基层所队应当设立公安民警心理健康服务站，对公安民警开展心理健康咨询，适时进行心理辅导；每年定期开展心理健康讲座、团体辅导和心理咨询等活动，保障公安民警心理健康。"},{"i":210,"n":"第二百一十条","txt":"对执行重大安全保卫任务、处置重大突发案（事）件、暴力恐怖案（事）件或者开枪击毙击伤人员，以及工作、生活发生重大变故的公安民警，应当及时进行心理咨询、危机干预。对出现心理健康问题的，应当及时安排休整、治疗。"},{"i":211,"n":"第二百一十一条","txt":"公安机关应当深入开展健康教育，引导公安民警牢固树立健康生活的理念，积极开展文体活动，陶冶情操，增强体质，丰富业余文化生活。"},{"i":212,"n":"第二百一十二条","txt":"中国人民警察警旗是人民警察队伍的重要标志，是人民警察荣誉、责任和使命的象征，是人民警察忠诚履行新时代使命任务的重要指引。"},{"i":213,"n":"第二百一十三条","txt":"公安民警应当树立警旗意识，尊重和爱护警旗，维护警旗尊严。"},{"i":214,"n":"第二百一十四条","txt":"公安机关及所属单位按规定授予和请领警旗。 授予警旗可以组织授旗仪式。授旗仪式由受旗单位所隶属的公安机关或者上一级公安机关组织实施，通常在单位新组建成立时进行。"},{"i":215,"n":"第二百一十五条","txt":"使用警旗应当报受旗单位主要负责同志批准，不得超出规定的使用范围。 任何组织和个人未经批准不得制造、买卖、持有、使用警旗。"},{"i":216,"n":"第二百一十六条","txt":"中国人民警察警徽是人民警察的象征和标志。公安民警应当爱护警徽，维护警徽尊严。"},{"i":217,"n":"第二百一十七条","txt":"警徽是人民警察专用标志。使用警徽及其图案应当严肃、庄重，严格使用范围。"},{"i":218,"n":"第二百一十八条","txt":"警徽由公安部按照规定统一监制。县级以上公安机关负责监督管理警徽及其图案的使用。"},{"i":219,"n":"第二百一十九条","txt":"中国人民警察警歌是人民警察性质、宗旨和精神的体现。公安民警和公安院校学生应当会唱警歌。"},{"i":220,"n":"第二百二十条","txt":"奏（唱）警歌适用于公安机关重要庆典、集会、会议、检阅以及其他维护、显示人民警察威严的场合。"},{"i":221,"n":"第二百二十一条","txt":"不得在私人婚、丧、庆、悼活动和娱乐、商业活动以及其他不适宜的场合奏（唱）警歌。"},{"i":222,"n":"第二百二十二条","txt":"奏（唱）警歌时，公安民警应当庄重肃立。"},{"i":223,"n":"第二百二十三条","txt":"中国人民警察节是人民警察荣誉制度体系的重要组成部分。公安机关应当在警察节举办相关庆祝活动，作为励警爱警惠警的重要举措。"},{"i":224,"n":"第二百二十四条","txt":"公安机关庆祝警察节活动，可通过升（挂）警旗仪式、组织宣誓、走访慰问、举办书画摄影作品展览、诗歌朗诵会、音乐会等丰富多彩的文体活动形式进行。 举办警察节庆祝活动应当隆重简朴、厉行节约，防止形式主义和铺张浪费。"},{"i":225,"n":"第二百二十五条","txt":"警察节期间，公安机关可结合实际采取警营开放、法制宣讲、便民服务等多种方式，广泛开展社会宣传，大力加强警察公共关系建设，树立公安机关和公安队伍良好形象。"},{"i":226,"n":"第二百二十六条","txt":"阅警是设区的市级以上党政机关主要领导、公安机关主要领导在重大节日、庆典、集会等重要场合对公安队伍的检阅。"},{"i":227,"n":"第二百二十七条","txt":"阅警应当严格审批制度。设区的市级以上公安机关举行阅警，应当报上级公安机关批准；公安院校举行阅警，应当报主管机关批准。"},{"i":228,"n":"第二百二十八条","txt":"阅警的主要程序： （一）阅警指挥员向阅警领导报告； （二）阅警领导宣布阅警开始； （三）组织进行阅警活动； （四）阅警领导讲话； （五）阅警指挥员向阅警领导报告； （六）阅警领导宣布阅警结束。"},{"i":229,"n":"第二百二十九条","txt":"违反本条令，情节轻微的，应当给予谈话提醒、批评教育或者当场予以纠正；情节严重的，应当按照规定采取带离现场、停止执行职务、禁闭措施，给予处分或者限期调离、辞退等处理；构成违法犯罪的，依法追究相应的法律责任。"},{"i":230,"n":"第二百三十条","txt":"公安机关直属事业单位内务建设参照本条令执行。国家移民管理机构可按照本条令制定具体管理规定或者实施办法。 公安机关警务辅助人员的内务建设，由各省级公安机关参照本条令制定具体办法。"},{"i":231,"n":"第二百三十一条","txt":"本条令所称“以上”均含本级。"},{"i":232,"n":"第二百三十二条","txt":"本条令自发布之日起施行。2000年6月公安部颁布实施的《公安机关人民警察内务条令》（公安部令第53号）和2007年6月公安部颁布实施的《公安机关人民警察着装管理规定》（公安部令第92号）同时废止。其他有关内务建设的规定有与本条令不一致的，以本条令为准。"}],"gonganjiguanrenminjingchajianglitiaoling":[{"i":1,"n":"第一条","txt":"为加强和规范公安机关奖励工作，促进公安工作和队伍建设，根据《中华人民共和国公务员法》、《中华人民共和国人民警察法》、《公安机关组织管理条例》、《公务员奖励规定（试行）》等法律、法规和规章，制定本条令。"},{"i":2,"n":"第二条","txt":"公安机关奖励工作应当服从服务公安工作全局和中心任务，及时奖励在各项公安工作中做出突出成绩的集体和个人，充分激发、调动各级公安机关和广大民警的工作积极性、主动性、创造性。"},{"i":3,"n":"第三条","txt":"公安机关奖励工作应当坚持下列原则： （一）实事求是，按绩及时施奖； （二）发扬民主，贯彻群众路线； （三）公开、公平、公正； （四）以基层一线为重点，领导机关、领导干部从严； （五）精神奖励与物质奖励相结合，以精神奖励为主。"},{"i":4,"n":"第四条","txt":"公安机关奖励工作实行统一领导，分级管理，分工负责。公安机关政工部门是奖励工作的主管部门，负责组织、指导、管理奖励工作。公安机关其他部门配合政工部门做好奖励工作。"},{"i":5,"n":"第五条","txt":"公安机关奖励经费应当列入各级公安机关年度预算予以全额保障。"},{"i":6,"n":"第六条","txt":"奖励分为集体奖励和个人奖励。"},{"i":7,"n":"第七条","txt":"集体奖励的对象是各级公安机关建制单位和为完成专项工作临时成立的非建制单位。 个人奖励的对象是各级公安机关在编在职人民警察。因公牺牲或者病故的人民警察，生前有重大贡献或者突出事迹，符合奖励条件的，可以追授奖励。"},{"i":8,"n":"第八条","txt":"集体奖励由低至高依次为：嘉奖，记三等功、二等功、一等功，授予荣誉称号。集体授予荣誉称号的名称，根据受奖集体的事迹特点确定。 个人奖励由低至高依次为：嘉奖，记三等功、二等功、一等功，授予荣誉称号。授予个人的荣誉称号分为全国公安系统二级英雄模范、一级英雄模范称号。"},{"i":9,"n":"第九条","txt":"符合下列条件之一的集体和个人，应当给予奖励： （一）依法打击危害国家安全和公共安全、颠覆国家政权、破坏社会秩序和经济秩序、侵犯公私财产和公民人身权利等违法犯罪活动，维护国家安全和社会稳定，成绩突出的； （二）加强社会治安管理，依法查处和制止扰乱公共秩序、侵犯人身权利、妨害社会管理等违法行为，维护治安稳定和公共安全，成绩突出的； （三）依法妥善处置重大突发事件，积极参加抢险救灾，圆满完成重大活动安全保卫任务，成绩突出的； （四）加强公安基层基础建设，落实各项管理防范措施，有效预防和制止违法犯罪活动，成绩突出的； （五）依法履行行政管理职能，科学、文明、规范管理，提高工作质量和效率，成绩突出的； （六）加强科技强警工作，有发明创造、科技创新成果或者创造典型经验，成绩突出的； （七）密切联系群众，热情为群众服务，成绩突出的； （八）加强思想政治工作，强化教育、管理和监督，推动队伍正规化建设，"},{"i":10,"n":"第十条","txt":"对符合奖励条件的集体和个人，根据其事迹及作用、影响，按照以下标准确定奖励等级： （一）对成绩突出的，给予嘉奖； （二）对成绩突出，有较大贡献的，记三等功； （三）对成绩显著，有重要贡献的，记二等功； （四）对成绩显著，有重大贡献和影响的，记一等功； （五）对成绩卓著，有特殊贡献和重大影响，堪称典范的，可以授予荣誉称号。"},{"i":11,"n":"第十一条","txt":"对集体或者个人的同一事迹只能给予一次奖励。对同一集体或者个人一年内原则上不重复给予同等级及以下等级奖励。"},{"i":12,"n":"第十二条","txt":"集体或者个人因涉嫌违法违纪等问题正在接受组织调查的，应当暂停实施奖励。 集体发生严重违法违纪或者重大失职、失误问题的，原则上一年内不予奖励；情节特别严重、影响特别恶劣的，原则上两年内不予奖励。个人受党纪、政纪处分期间，原则上不予奖励。有重大或特殊贡献的集体或者个人，可以不受上述时限限制。"},{"i":13,"n":"第十三条","txt":"公安部的批准权限： （一）全国公安机关集体和个人授予荣誉称号、记一等功奖励，其中授予全国公安系统一级英雄模范称号，由人力资源社会保障部会同公安部审批； （二）省级公安机关及其领导班子成员嘉奖、记三等功、二等功奖励； （三）公安部机关内设机构及直属单位集体和个人嘉奖、记三等功、二等功奖励。"},{"i":14,"n":"第十四条","txt":"省级公安机关的批准权限： （一）公安部批准权限以外的本地区公安机关集体和个人记二等功； （二）市（地）级公安机关及其领导班子成员嘉奖、记三等功奖励； （三）省级公安机关内设机构及直属单位集体和个人嘉奖、记三等功奖励。"},{"i":15,"n":"第十五条","txt":"市（地）级公安机关批准上级公安机关批准权限以外的本地区公安机关集体和个人嘉奖、记三等功奖励。"},{"i":16,"n":"第十六条","txt":"经公安部批准，省级公安机关领导班子成员以外的个人记一等功，可以由所在省级公安机关办理；经市（地）级公安机关批准，县级公安机关及其领导班子成员以外的集体和个人嘉奖，可以由所在县级公安机关办理。"},{"i":17,"n":"第十七条","txt":"铁路公安局、交通运输部公安局、中国民用航空局公安局、国家林业局森林公安局、海关总署缉私局执行省级公安机关的批准权限，其所属下级公安机关参照执行市（地）级以下公安机关的批准权限。"},{"i":18,"n":"第十八条","txt":"对受组织委派，离开原单位执行临时任务或者借调、挂职的人民警察，时间一年以上，符合奖励条件的，可以由临时所在单位，按照批准权限实施奖励或者申报奖励；时间不足一年，符合奖励条件的，由临时所在单位向原单位介绍情况，由原单位按照批准权限实施奖励或者申报奖励。"},{"i":19,"n":"第十九条","txt":"对集体和个人实施奖励，一般按照下列程序进行： （一）对符合奖励条件的集体和个人，由所在单位民主推荐，集体研究提出奖励申报意见； （二）公安机关政工部门对申报奖励对象事迹进行核实，并在征求相关部门意见后，提出奖励审核意见； （三）公安机关研究确定奖励批准意见，组织进行公示后予以公布。超过本级公安机关批准权限的，报上级公安机关审批。 对在抢险救灾、重大突发事件处置、重大活动安全保卫、重大案件侦破等工作中成绩特别突出的集体和个人，必要时，可以简化程序，由奖励批准机关的政工部门提出奖励建议，奖励批准机关直接批准奖励。"},{"i":20,"n":"第二十条","txt":"奖励申报意见应当在相关集体和个人做出符合奖励条件的成绩后一个月内提出；对下级公安机关的奖励申报意见，奖励审核、批准机关应当分别在收到奖励申报材料两个月内完成审核、审批工作。特殊情况下，应当及时完成奖励申报、审核、审批工作。"},{"i":21,"n":"第二十一条","txt":"对拟实施奖励的集体和个人，奖励申报、审核、批准机关的政工部门应当征求本级公安机关纪检监察、法制和相关业务部门的意见。对拟实施奖励的个人，必要时，应当按照干部管理权限，征得主管机关同意，并征求纪检机关（监察部门）和有关部门意见。"},{"i":22,"n":"第二十二条","txt":"对拟记三等功以上奖励的集体和个人，由奖励批准机关组织考核，或者委托下一级公安机关的政工部门组织考核，受委托的政工部门不得再行委托。"},{"i":23,"n":"第二十三条","txt":"对拟记三等功以上奖励的集体和个人，除涉密等特殊情况外，应当逐级在一定范围内进行公示，公示时间原则上不少于七个工作日。"},{"i":24,"n":"第二十四条","txt":"对集体和个人实施奖励的决定，以奖励批准机关行政首长签署命令的形式下达。行政首长空缺时，以奖励批准机关印发决定的形式下达。 对集体和个人实施奖励的决定应当及时宣布，并举行简约、俭朴的授奖仪式。必要时，可以召开表彰会。"},{"i":25,"n":"第二十五条","txt":"对集体和个人的奖励实施后，奖励命令、审批表和其他有关材料存入公安机关文书档案，个人奖励审批表同时存入本人档案。"},{"i":26,"n":"第二十六条","txt":"年度个人嘉奖和记三等功、二等功、一等功奖励的比例，分别不高于当年实有在编在职人民警察总数的百分之九、百分之三、千分之三、万分之三。根据公务员年度考核结果给予的个人嘉奖、记三等功奖励，不受年度奖励比例限制。 年度集体、个人授予荣誉称号和集体记一等功，不规定具体比例，由公安部根据实际情况审批。年度集体记二等功以下奖励的比例，由省级公安机关根据实际情况规定。"},{"i":27,"n":"第二十七条","txt":"厅、局级以上单位、个人和市（地）级以上公安机关领导班子成员一般不予奖励；处级单位和个人奖励从严控制；基层和一线实战单位及其人民警察奖励数量应当占年度奖励总数的百分之八十五以上。"},{"i":28,"n":"第二十八条","txt":"对执行重大抢险救灾、重大突发事件处置、重大活动安全保卫等专项任务的，经公安部批准，可以适当提高年度奖励比例。"},{"i":29,"n":"第二十九条","txt":"对在执行重大专项工作任务中做出突出成绩的集体和个人，其上级公安机关可以行政首长签署嘉奖令的形式，及时予以鼓励。"},{"i":30,"n":"第三十条","txt":"奖励批准机关对获得奖励的集体颁发奖匾或者奖状；对获得记三等功以上奖励的个人颁发奖章和证书；对获得嘉奖奖励的个人颁发证书。"},{"i":31,"n":"第三十一条","txt":"奖匾、奖状、奖章、证书按照公安部统一规定的式样、质地和规格制作。属于公安部批准权限的由公安部负责制作，属于省级以下公安机关批准权限的由省级公安机关负责制作。"},{"i":32,"n":"第三十二条","txt":"奖匾、奖状、奖章、证书由获得奖励的集体和个人妥善保存。获得奖励的个人在参加重要会议或者重大活动时可以将奖章佩戴在左胸前。"},{"i":33,"n":"第三十三条","txt":"奖匾、奖状、奖章、证书丢失或者毁损的，应当向所在公安机关政工部门报告，并由政工部门核实后按照程序报奖励批准机关予以补发或者更换。"},{"i":34,"n":"第三十四条","txt":"奖励批准机关对获得奖励的集体和个人统一按照下列标准颁发奖金： 集体嘉奖五千元，集体三等功一万元，集体二等功两万元，集体一等功三万元，集体荣誉称号五万元。 个人嘉奖两千元，个人三等功五千元，个人二等功一万元，个人一等功两万元，全国公安系统二级英雄模范五万元，全国公安系统一级英雄模范八万元。 集体奖励的奖金一般作为工作经费由集体使用，原则上不得向个人发放。"},{"i":35,"n":"第三十五条","txt":"获得授予或者追授全国公安系统一级英雄模范、二级英雄模范荣誉称号奖励的个人的子女，符合条件的，可以保送进入普通公安高等院校学习。"},{"i":36,"n":"第三十六条","txt":"获得记一等功以上奖励的个人，可以按照有关规定提前晋升警衔。"},{"i":37,"n":"第三十七条","txt":"获得记三等功以上奖励（含追记、追授的）的个人死亡后，按照国家有关规定增发一次性抚恤金。 获得全国公安系统一级英雄模范、二级英雄模范称号的个人死亡后，按照有关规定进行吊唁。"},{"i":38,"n":"第三十八条","txt":"获得奖励的个人，根据国家有关规定享受其他待遇。"},{"i":39,"n":"第三十九条","txt":"对获得奖励的集体和个人，各级公安机关应当加强教育管理，在政治思想上、工作上和生活上给予关心和爱护，使他们保持荣誉，不断进步。"},{"i":40,"n":"第四十条","txt":"对获得授予荣誉称号的集体和个人，由省级公安机关建立联系制度和管理档案，定期组织进行考察，及时了解掌握情况，并每年报公安部备案。对获得其他奖励的集体和个人，由市（地）级以下公安机关根据实际情况，确定重点对象，建立联系制度和管理档案，定期报上级公安机关备案。"},{"i":41,"n":"第四十一条","txt":"获得授予荣誉称号的集体和个人发生违法违纪问题，或者获得荣誉称号的个人有调离、退休、死亡等情况，其所在公安机关应当按照程序及时报公安部备案。"},{"i":42,"n":"第四十二条","txt":"对获得奖励的个人，应当定期组织开展培训和休养活动。省级以上公安机关应当每年组织功模民警培训和休养；市（地）级以下公安机关功模民警培训和休养结合实际组织开展。"},{"i":43,"n":"第四十三条","txt":"获得奖励的集体或者个人，有下列情形之一的，应当撤销其奖励： （一）伪造事迹或者申报奖励时隐瞒严重问题，骗取奖励的； （二）严重违反规定奖励程序的； （三）获得授予荣誉称号奖励的集体发生违法违纪问题，造成恶劣影响的； （四）获得授予荣誉称号奖励的个人受到开除处分、刑事处罚，或者犯有其他严重错误，丧失模范作用的； （五）法律、法规规定应当撤销奖励的其他情形。"},{"i":44,"n":"第四十四条","txt":"撤销奖励，由原奖励申报机关按照程序报请原奖励批准机关审批。必要时，原奖励批准机关可以直接撤销奖励。"},{"i":45,"n":"第四十五条","txt":"奖励撤销后，由原奖励批准机关收回奖匾、奖状或者奖章、证书，并停止其享受的有关待遇。属于第四十三条第（一）项、第（二）项规定情形的，同时收回奖金。撤销个人奖励的决定存入本人档案。"},{"i":46,"n":"第四十六条","txt":"本条令适用于全国各级公安机关，铁路、交通、民航、森林公安机关和海关缉私部门及其人民警察。 公安机关所属单位及其在编在职人员，公安机关见习期人民警察、离退休人民警察、在编在职工勤人员和公安院校全日制普通学历教育学生参照执行。 公安现役部队奖励工作执行《中国人民解放军纪律条令》。"},{"i":47,"n":"第四十七条","txt":"公安机关开展其他评比表彰活动，按照中共中央办公厅、国务院办公厅印发的《评比达标表彰活动管理办法（试行）》（中办发〔2010〕33号）执行。"},{"i":48,"n":"第四十八条","txt":"本条令所称“以上”、“以下”含本级、本数。"},{"i":49,"n":"第四十九条","txt":"本条令自2016年1月1日起施行。2003年7月24日颁布的《公安机关人民警察奖励条令》（公安部令第66号）同时废止。"}],"gonganjiguanrenminjingchazhifaguocuozerenzhuijiugu8c19be":[{"i":1,"n":"第一条","txt":"为落实执法办案责任制，完善执法过错责任追究机制，保障公安机关及其人民警察依法正确履行职责，保护公民、法人和其他组织的合法权益，根据《中华人民共和国人民警察法》、《行政机关公务员处分条例》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称执法过错是指公安机关人民警察在执法办案中，故意或者过失造成的认定事实错误、适用法律错误、违反法定程序、作出违法处理决定等执法错误。 在事实表述、法条引用、文书制作等方面存在执法瑕疵，不影响案件处理结果的正确性及效力的，不属于本规定所称的执法过错，不予追究执法过错责任，但应当纳入执法质量考评进行监督并予以纠正。"},{"i":3,"n":"第三条","txt":"追究执法过错责任，应当遵循实事求是、有错必纠、过错与处罚相适应、教育与惩处相结合的原则。"},{"i":4,"n":"第四条","txt":"在执法过错责任追究工作中，公安机关纪检监察、督察、人事、法制以及执法办案等部门应当各负其责、互相配合。"},{"i":5,"n":"第五条","txt":"执法办案人、鉴定人、审核人、审批人都有故意或者过失造成执法过错的，应当根据各自对执法过错所起的作用，分别承担责任。"},{"i":6,"n":"第六条","txt":"审批人在审批时改变或者不采纳执法办案人、审核人的正确意见造成执法过错的，由审批人承担责任。"},{"i":7,"n":"第七条","txt":"因执法办案人或者审核人弄虚作假、隐瞒真相，导致审批人错误审批造成执法过错的，由执法办案人或者审核人承担主要责任。"},{"i":8,"n":"第八条","txt":"因鉴定人提供虚假、错误鉴定意见造成执法过错的，由鉴定人承担主要责任。"},{"i":9,"n":"第九条","txt":"违反规定的程序，擅自行使职权造成执法过错的，由直接责任人员承担责任。"},{"i":10,"n":"第十条","txt":"下级公安机关人民警察按照规定向上级请示的案件，因上级的决定、命令错误造成执法过错的，由上级有关责任人员承担责任。因下级故意提供虚假材料或者不如实汇报导致执法过错的，由下级有关责任人员承担责任。 下级对超越法律、法规规定的人民警察职责范围的指令，有权拒绝执行，并同时向上级机关报告。没有报告造成执法过错的，由上级和下级分别承担相应的责任；已经报告的，由上级承担责任。"},{"i":11,"n":"第十一条","txt":"对其他执法过错情形，应当根据公安机关人民警察在执法办案中各自承担的职责，区分不同情况，分别追究有关人员的责任。"},{"i":12,"n":"第十二条","txt":"对执法过错责任人员，应当根据其违法事实、情节、后果和责任程度分别追究刑事责任、行政纪律责任或者作出其他处理。"},{"i":13,"n":"第十三条","txt":"追究行政纪律责任的，由人事部门或者纪检监察部门依照《行政机关公务员处分条例》和《公安机关人民警察纪律条令》等规定依法给予处分；构成犯罪的，依法移送有关司法机关处理。"},{"i":14,"n":"第十四条","txt":"作出其他处理的，由相关部门提出处理意见，经公安机关负责人批准，可以单独或者合并作出以下处理： （一）诫勉谈话； （二）责令作出书面检查； （三）取消评选先进的资格； （四）通报批评； （五）停止执行职务； （六）延期晋级、晋职或者降低警衔； （七）引咎辞职、责令辞职或者免职； （八）限期调离公安机关； （九）辞退或者取消录用。"},{"i":15,"n":"第十五条","txt":"公安机关依法承担国家赔偿责任的案件，除依照本规定追究执法过错责任外，还应当依照《中华人民共和国国家赔偿法》的规定，向有关责任人员追偿部分或者全部赔偿费用。"},{"i":16,"n":"第十六条","txt":"执法过错责任人受到开除处分、刑事处罚或者犯有其他严重错误，应当按照有关规定撤销相关的奖励。"},{"i":17,"n":"第十七条","txt":"发生执法过错案件，影响恶劣、后果严重的，除追究直接责任人员的责任外，还应当依照有关规定追究公安机关领导责任。 年度内发生严重的执法过错或者发生多次执法过错的公安机关和执法办案部门，本年度不得评选为先进集体。"},{"i":18,"n":"第十八条","txt":"对执法过错责任人的处理情况分别记入人事档案、执法档案，作为考核、定级、晋职、晋升等工作的重要依据。"},{"i":19,"n":"第十九条","txt":"具有下列情形之一的，应当从重追究执法过错责任： （一）因贪赃枉法、徇私舞弊、刑讯逼供、伪造证据、通风报信、蓄意报复、陷害等故意造成执法过错的； （二）阻碍追究执法过错责任的； （三）对检举、控告、申诉人打击报复的； （四）多次发生执法过错的； （五）情节恶劣、后果严重的。"},{"i":20,"n":"第二十条","txt":"具有下列情形之一的，可以从轻、减轻或者免予追究执法过错责任： （一）由于轻微过失造成执法过错的； （二）主动承认错误，并及时纠正的； （三）执法过错发生后能够配合有关部门工作，减少损失、挽回影响的； （四）情节轻微、尚未造成严重后果的。"},{"i":21,"n":"第二十一条","txt":"具有下列情形之一的，不予追究执法过错责任： （一）因法律法规、司法解释发生变化，改变案件定性、处理的； （二）因法律规定不明确、有关司法解释不一致，致使案件定性、处理存在争议的； （三）因不能预见或者无法抗拒的原因致使执法过错发生的； （四）对案件基本事实的判断存在争议或者疑问，根据证据规则能够予以合理说明的； （五）因出现新证据而改变原结论的； （六）原结论依据的法律文书被撤销或者变更的； （七）因执法相对人的过错致使执法过错发生的。"},{"i":22,"n":"第二十二条","txt":"追究执法过错责任，由发生执法过错的公安机关负责查处。 上级公安机关发现下级公安机关应当查处而未查处的，应当责成下级公安机关查处；必要时，也可以直接查处。"},{"i":23,"n":"第二十三条","txt":"公安机关纪检监察、督察、审计、法制以及执法办案等部门，应当在各自职责范围内主动、及时检查、纠正和处理执法过错案件。"},{"i":24,"n":"第二十四条","txt":"各有关部门调查后，认为需要法制部门认定执法过错的，可以将案件材料移送法制部门认定。"},{"i":25,"n":"第二十五条","txt":"法制部门认定执法过错案件，可以通过阅卷、组织有关专家讨论、会同有关部门调查核实等方式进行，形成执法过错认定书面意见后，及时送达有关移送部门，由移送部门按照本规定第十三条、第十四条作出处理。"},{"i":26,"n":"第二十六条","txt":"被追究执法过错责任的公安机关人民警察及其所属部门不服执法过错责任追究的，可以在收到执法过错责任追究决定之日起五日内向作出决定的公安机关或者上一级公安机关申诉；接受申诉的公安机关应当认真核实，并在三十日内作出最终决定。法律、法规另有规定的，按照有关规定办理。"},{"i":27,"n":"第二十七条","txt":"因故意或者重大过失造成错案，不受执法过错责任人单位、职务、职级变动或者退休的影响，终身追究执法过错责任。 错案责任人已调至其他公安机关或者其他单位的，应当向其所在单位通报，并提出处理建议；错案责任人在被作出追责决定前，已被开除、辞退且无相关单位的，应当在追责决定中明确其应当承担的责任。"},{"i":28,"n":"第二十八条","txt":"各级公安机关对执法过错案件应当采取有效措施予以整改、纠正，对典型案件应当进行剖析、通报。"},{"i":29,"n":"第二十九条","txt":"各省、自治区、直辖市公安厅局和新疆生产建设兵团公安局可以根据本规定，结合本地实际制定实施细则。"},{"i":30,"n":"第三十条","txt":"本规定自2016年3月1日起施行。1999年6月11日发布的《公安机关人民警察执法过错责任追究规定》（公安部令第41号）同时废止。"}],"gonganjiguanrenminjingchaxunliantiaoling":[{"i":1,"n":"第一条","txt":"为加强和规范公安机关人民警察训练工作，根据《中华人民共和国公务员法》、《中华人民共和国人民警察法》，制定本条令。"},{"i":2,"n":"第二条","txt":"公安机关人民警察训练是提高队伍战斗力的根本途径，在队伍建设中居于先导性、基础性和战略性地位。各级公安机关应当加强人民警察训练工作科学化、规范化、信息化、实战化建设，向训练要素质、要警力、要战斗力。"},{"i":3,"n":"第三条","txt":"公安机关人民警察训练坚持贯彻党和国家的干部教育培训方针、政策，坚持从公安工作和队伍建设实际需要出发，坚持为公安中心工作服务，坚持为公安实战服务。"},{"i":4,"n":"第四条","txt":"公安机关人民警察训练的目的是提高队伍的整体素质和执法水平，增强履行职责的能力，努力打造一支信念坚定、执法为民、敢于担当、清正廉洁的公安队伍。"},{"i":5,"n":"第五条","txt":"公安机关人民警察有接受训练的权利和义务。各级公安机关应当保证人民警察定期接受训练，引导和帮助人民警察自学自练。人民警察应当遵守训练规章制度，完成规定的训练任务。"},{"i":6,"n":"第六条","txt":"公安机关人民警察训练应当发扬理论联系实际的优良学风，坚持厉行节约，反对铺张浪费。"},{"i":7,"n":"第七条","txt":"公安机关人民警察训练包括入警训练、晋升训练、专业训练和发展训练。"},{"i":8,"n":"第八条","txt":"公安机关人民警察训练实行统一领导，分工负责，分级管理，分类实施。"},{"i":9,"n":"第九条","txt":"公安机关人民警察训练实行领导责任制，各级公安机关主要领导是第一责任人。"},{"i":10,"n":"第十条","txt":"公安机关政工部门是训练工作的主管部门，负责规划、组织、指导、管理、实施训练工作。"},{"i":11,"n":"第十一条","txt":"公安机关警种、部门在政工部门的管理、指导下，负责规划、组织、实施本系统专业训练和发展训练。"},{"i":12,"n":"第十二条","txt":"公安机关法制部门负责执法资格等级考试和组织、参与执法培训工作。"},{"i":13,"n":"第十三条","txt":"公安机关装备财务部门负责训练经费、装备保障。"},{"i":14,"n":"第十四条","txt":"公安院校和公安机关训练基地承担公安机关人民警察训练任务。"},{"i":15,"n":"第十五条","txt":"公安部主管全国公安机关人民警察训练工作，负责制定训练规章、规划、标准，组织编发各级各类训练大纲、教材，推进训练信息化建设，指导、监督、检查、协调、评估训练工作，部署、组织全国性的训练和考试考核，并承担以下训练任务： （一）从非公安系统调入的省级公安机关副职以上领导职务、市县两级公安机关正职领导职务人员的入警训练； （二）晋升省级公安机关副职以上领导职务、省级公安机关内设机构正职领导职务、市县两级公安机关正职领导职务人民警察的职务晋升训练，晋升三级警监以上警衔人民警察的警衔晋升训练； （三）省级公安机关副职以上领导职务、省级公安机关内设机构正职领导职务、市级公安机关正职领导职务人民警察和部分业务骨干的专业训练； （四）公安部机关及直属单位人民警察的入警训练、晋升训练、专业训练； （五）适应形势任务需要实施的发展训练。"},{"i":16,"n":"第十六条","txt":"省级公安机关主管本地区公安机关人民警察训练工作，负责制定本地区训练制度、规划、标准，组织编发训练辅助教材，建设网络训练平台，制定本地区训练保障计划，组织、指导训练保障工作，指导、监督、检查、协调、评估本地区训练工作，组织、实施地区性的训练和考试考核，并承担以下训练任务： （一）本地区除公安部负责训练以外人员的入警训练； （二）晋升省级公安机关内设机构副职领导职务、市县两级公安机关副职领导职务、县级公安机关内设和派出机构正职领导职务人民警察的职务晋升训练，晋升三级警督警衔至一级警督警衔人民警察的警衔晋升训练； （三）省级公安机关内设机构副职领导职务，市级公安机关副职领导职务和内设机构正职领导职务，县级公安机关正副职领导职务、内设和派出机构正职领导职务人民警察及部分业务骨干的专业训练； （四）省级公安机关及直属单位除公安部负责训练以外的人民警察的晋升训练、专业训练； （五）适应形势任务需要"},{"i":17,"n":"第十七条","txt":"市级公安机关主管本地区公安机关人民警察训练工作，负责制定本地区训练计划并组织实施训练工作，指导、监督、检查、考核、保障本地区训练工作，并承担以下训练任务： （一）本地区除上级公安机关负责训练以外人民警察的职务晋升训练、晋升一级警员警衔至一级警司警衔人民警察的警衔晋升训练； （二）根据岗位职责要求实施的专业训练； （三）适应形势任务需要实施的发展训练； （四）上级公安机关授权、委托的训练任务。"},{"i":18,"n":"第十八条","txt":"县级公安机关根据上级公安机关的安排和要求，承担本级公安机关除上级公安机关负责训练以外的人民警察的专业训练和适应形势任务需要实施的发展训练。"},{"i":19,"n":"第十九条","txt":"入警训练是对新录用、调入的人员进行的训练。 入警训练时间不少于90天。其中，新录用的非公安院校毕业生，新录用、调入任县处级副职职务以下人员的入警训练时间为180天。实践教学时间不少于总训练时间的30%。 入警训练内容主要包括理想信念教育、警察职业养成教育、基础公安理论、基础法律法规、基础公安业务和基础警务实战技能、体能、心理行为训练等，重点培育人民警察核心价值观和基本职业素养，提高适应公安工作能力。其中，基础警务实战技能和体能训练课程不少于集中训练课程的30%。"},{"i":20,"n":"第二十条","txt":"晋升训练是对晋升职务、晋升警衔的人民警察进行的训练。 晋升训练时间不少于15天。其中，新任市、县级公安机关正职领导职务的训练时间不少于30天。 职务晋升训练内容主要包括党性党风教育、国际国内形势、经济社会发展、公安发展战略、公安法制与执法、科学决策指挥、突发事件应对等，重点培养战略思维和管理素养，提高胜任领导工作能力。 警衔晋升训练内容根据训练对象和工作需要，参照职务晋升训练设定，重点培养专业精神，增强职业荣誉感，提高综合素质和履职能力。 凡已经参加同级或者上级公安机关组织的职务晋升训练或者警衔晋升训练并且训练合格的人民警察，1年内可不再重复参加晋升训练。"},{"i":21,"n":"第二十一条","txt":"专业训练是警种、部门根据人民警察岗位职责要求进行的训练。 专业训练时间由政工部门和警种、部门根据实际确定，保证人民警察每年至少参加一次专业训练，三年累计不少于30天。基层和一线民警每年的实战训练时间累计不少于15天。 专业训练内容主要包括岗位政策法规、业务知识、专业技能和专项警务实战技能、体能、心理行为训练等，重点培养专业素养，强化知识更新，提高工作能力。其中，单警装备使用、枪支基本操作、枪支实弹射击、徒手攻防技能、体能达标训练等课程不少于专业训练课程的30%。"},{"i":22,"n":"第二十二条","txt":"发展训练是公安机关应对新形势、新任务，按照国家关于干部教育培训的有关要求，着眼公安工作长远发展和人民警察健康成长组织的训练。 发展训练主要包括在职领导干部专题训练、后备干部培养训练、专家和业务骨干研修、教官业务提高训练、民警职业拓展训练等。 发展训练的时间、内容根据实际需要和有关规定确定。"},{"i":23,"n":"第二十三条","txt":"公安机关应当紧贴实战需要，推进训练工作信息化建设，利用科技信息手段开展学习、训练、管理、考核。 推行实战案例教学，基层和一线人民警察的案例教学课程不少于总课程的30%。 市县两级公安机关实行“轮训轮值、战训合一”训练模式，提高训练工作效率和效益。"},{"i":24,"n":"第二十四条","txt":"公安机关人民警察应当以提高岗位履职能力和实战本领为目标，通过岗位练兵、在线学习等形式开展自学自练，达到训练考核标准。 基层和一线民警应当根据体育锻炼达标标准，积极参加体育健身锻炼，增强身体素质和体能素质。"},{"i":25,"n":"第二十五条","txt":"部、省、设区的市级公安机关应当在政工部门设立教育训练机构，县级公安机关应当在政工部门设立训练机构或配备专职训练管理人员。省级以上公安机关主要警种、部门应当设立训练机构或配备专职训练管理人员。"},{"i":26,"n":"第二十六条","txt":"省级以上公安机关应当建立或者依托公安院校设立训练基地，设区的市级公安机关和具备条件的县级公安机关应当建立训练基地。"},{"i":27,"n":"第二十七条","txt":"训练基地应当符合《公安机关业务技术用房建设标准》，并具备下列基本条件： （一）健全的组织机构和管理制度； （二）与训练任务相适应的专职、兼职教官和管理人员； （三）与训练任务相适应的训练场所、设施、装备； （四）根据任务需要研发训练课程的能力； （五）稳定的经费保障。"},{"i":28,"n":"第二十八条","txt":"训练基地作为本级公安机关内设机构或直属单位，实行政工部门与训练基地“一体化”领导管理体制，由政工部门领导兼任训练基地主要领导职务。"},{"i":29,"n":"第二十九条","txt":"公安机关应当加强公安院校建设，充分利用其教学科研优势，加强训练理论研究，开展高层次、高水平和综合性的训练工作，在训练中发挥引领和高地作用。"},{"i":30,"n":"第三十条","txt":"公安机关应当加强教官队伍建设，按照素质优良、规模适当、结构合理、专兼结合的原则，建立政治坚定、业务精湛、门类齐全、充满活力的教官队伍。"},{"i":31,"n":"第三十一条","txt":"教官是指从事公安机关人民警察训练教学及研究工作的人民警察。在规定期限内专职从事训练教学及研究工作的，为专职教官；兼职从事训练教学及研究工作的，为兼职教官。"},{"i":32,"n":"第三十二条","txt":"教官应当热爱公安教育训练事业，具有良好的思想政治素质和职业道德修养，具有公安工作实践经验和教学研究能力，能够承担训练教学、课程研发等任务。"},{"i":33,"n":"第三十三条","txt":"教官实行聘任和资格认证制度。教官聘任和资格认证应当遵循统一规划、分级管理、择优选聘、优胜劣汰的原则，采取个人申报、组织推荐、单位初审、专家评审、组织聘任等方式进行。"},{"i":34,"n":"第三十四条","txt":"教官在聘任期内完成年度训练教学任务，享受相应课酬、学习资料费、课程研发费等待遇，并在晋职晋级、评优评先时予以优先考虑。"},{"i":35,"n":"第三十五条","txt":"建立教官知识更新机制。公安机关应当支持并组织教官参加进修学习和教学研究活动，定期安排教官到业务部门进行实践和调研。专职教官实践和调研时间每年不少于30天。"},{"i":36,"n":"第三十六条","txt":"实行领导干部授课和业务骨干推优任教制度，鼓励和选拔符合条件的优秀人员离岗任教。离岗任教经历列为基层工作经历。"},{"i":37,"n":"第三十七条","txt":"公安机关应当充分利用社会资源，选聘专家学者参与人民警察训练工作。"},{"i":38,"n":"第三十八条","txt":"公安机关应当将人民警察训练经费列入年度预算，按照不低于公用经费5%的标准足额保障，单独立项，专款专用。按照“谁调训、谁负责”的原则，切实保障训练经费。"},{"i":39,"n":"第三十九条","txt":"公安机关应当为公安院校和人民警察训练基地配备与训练任务相适应的装备和器材，并将新装备优先免费配备公安院校和训练基地。"},{"i":40,"n":"第四十条","txt":"公安机关人民警察训练实行警务化管理，坚持严格教育、严格训练、严格管理、严格考核。"},{"i":41,"n":"第四十一条","txt":"公安机关应当在晋升训练前，组织人民警察参加基本知识、基本技能和基本体能考试考核。考试考核合格者，方可参加晋升训练。"},{"i":42,"n":"第四十二条","txt":"公安机关应当根据训练大纲、教学计划实施训练，组织参加训练的人民警察进行考试考核。考试考核结果由政工部门予以认定，并通报参训人民警察所在单位。"},{"i":43,"n":"第四十三条","txt":"公安机关人民警察训练考试考核合格后，方可按照有关规定上岗、任职、晋升职务或者授予、晋升警衔。提拔担任领导职务的，确因特殊情况在提任职务前未达到训练要求的，应当在提任后1年内完成训练。 考试考核不合格的，应当在限定时间内进行复训。入警复训不合格的不得上岗，直至取消录用资格；其他复训不合格的，公务员年度考核不得评为优秀等次，并根据有关规定不予晋升职务或者警衔。"},{"i":44,"n":"第四十四条","txt":"公安机关人民警察训练期间违反有关规定和纪律的，视情节轻重，给予批评教育直至纪律处分。"},{"i":45,"n":"第四十五条","txt":"公安机关应当建立训历档案，如实记载人民警察参加训练的情况和考核结果，作为年度考核、任用考察的一项重要内容，建立训练与晋升、育人与用人紧密衔接的工作机制。"},{"i":46,"n":"第四十六条","txt":"公安机关应当定期对训练工作进行绩效考核，对训练基地进行达标评估。训练工作绩效考核不合格的，年度内不得参加评优活动；训练基地评估不达标的，不得承担训练任务。"},{"i":47,"n":"第四十七条","txt":"公安机关对在训练工作中做出突出贡献的单位和个人，应当给予奖励。"},{"i":48,"n":"第四十八条","txt":"各省、自治区、直辖市公安厅、局，新疆生产建设兵团公安局，各行业公安局，根据本条令制定具体办法和实施细则。"},{"i":49,"n":"第四十九条","txt":"本条令所称“以上”、“以下”均含本级。"},{"i":50,"n":"第五十条","txt":"本条令自2015年1月1日起施行，2001年11月26日颁布的《公安机关人民警察训练条令》同时废止。"}],"gonganjiguanrenminjingchazhengshiyongguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强公安队伍正规化建设，规范和保障公安机关人民警察依法履行职责，根据《中华人民共和国人民警察法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于全国各级公安机关，铁路、交通、民航、森林公安机关和海关缉私部门及其人民警察。"},{"i":3,"n":"第三条","txt":"公安机关人民警察使用统一的人民警察证。"},{"i":4,"n":"第四条","txt":"人民警察证是公安机关人民警察身份和依法执行职务的凭证和标志。 公安机关人民警察在依法执行职务时，除法律、法规另有规定外，应当随身携带人民警察证，主动出示并表明人民警察身份。"},{"i":5,"n":"第五条","txt":"人民警察证发放范围为公安机关在编、在职并已经评授警衔的人民警察。 严禁向非发放范围人员发放人民警察证。"},{"i":6,"n":"第六条","txt":"人民警察证由专用皮夹和内卡组成，必须内容齐全且同时使用方可有效。 人民警察证皮夹为竖式黑色皮质，外部正面镂刻警徽图案、“人民警察证”字样，背面镂刻英文“CHINA POLICE”字样；内部上端镶嵌警徽一枚和“公安”两字，下端放置内卡。 人民警察证内卡正面印制持证人照片、姓名、所在县级以上公安机关名称和警号，背面印制持证人姓名、性别、出生日期、职务、警衔、血型、人民警察证有效期限，以及“人民警察证”、“CHINA POLICE”和“中华人民共和国公安部监制”字样。"},{"i":7,"n":"第七条","txt":"人民警察证制作、发放实行分级管理。 公安部负责制定、发布证件式样和技术标准，组织制作、发放证件皮夹。各省、自治区、直辖市公安厅、局和新疆生产建设兵团公安局，铁路、交通、民航、森林公安机关和海关缉私部门有关主管部门组织制作、发放本辖区或者本系统公安机关人民警察证内卡。 公安机关政工部门负责人民警察证的使用管理工作。"},{"i":8,"n":"第八条","txt":"人民警察证列入公安警用装备管理。"},{"i":9,"n":"第九条","txt":"人民警察证内卡记载主要内容发生变动、确需换发的，发证部门应当及时予以换发。"},{"i":10,"n":"第十条","txt":"公安机关人民警察具有下列情形之一的，所在县级以上公安机关应当及时收回其人民警察证并进行备案： （一）离、退休； （二）调离公安机关； （三）辞去公职； （四）因其他原因应当收回的。 公安机关人民警察被辞退、开除公职、判处刑罚或者免予刑事处罚的，所在县级以上公安机关应当及时收缴其人民警察证并进行备案。"},{"i":11,"n":"第十一条","txt":"公安机关人民警察具有下列情形之一的，所在县级以上公安机关应当暂时收回其人民警察证： （一）因涉嫌违法违纪被立案审查，尚未作出结论的； （二）被停止执行职务或者被禁闭的； （三）因其他原因应当暂时收回的。"},{"i":12,"n":"第十二条","txt":"公安机关人民警察应当爱护和妥善保管人民警察证，防止遗失、被盗、被抢或者损坏。 公安机关人民警察发现人民警察证遗失、被盗、被抢或者严重损坏、无法继续使用的，应当及时报告所在县级以上公安机关并申请补办。 人民警察证严重损坏、无法继续使用的，发证机关应当在办理补办手续时收回原证件。"},{"i":13,"n":"第十三条","txt":"公安机关人民警察不得涂改、损坏、复制、转借、抵押、赠送、买卖人民警察证，不得将人民警察证用于非警务活动或者非法活动。 公安机关人民警察违反前款规定的，应当依照有关规定予以纪律处分或者追究法律责任。"},{"i":14,"n":"第十四条","txt":"人民警察证主管部门和管理人员违反本规定，擅自制作、发放人民警察证或者有其他失职、渎职行为的，应当依照有关规定予以纪律处分或者追究法律责任。"},{"i":15,"n":"第十五条","txt":"人民警察证由公安部按照《公安机关人民警察证技术标准》统一监制。"},{"i":16,"n":"第十六条","txt":"各省、自治区、直辖市公安厅、局和新疆生产建设兵团公安局，铁路、交通、民航、森林公安机关和海关缉私部门有关主管部门可以结合实际，根据本规定制定实施细则并报公安部备案。 公安边防、消防、警卫部队人民警察证的使用管理按照本规定执行，并可结合实际制定实施细则报公安部备案。"},{"i":17,"n":"第十七条","txt":"本规定自二〇〇八年二月二十八日起施行。"}],"gonganjiguanneibuzhifajiandugongzuoguiding":[{"i":1,"n":"第一条","txt":"为保障公安机关及其人民警察依法正确履行职责，防止和纠正违法和不当的执法行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国人民警察法》和有关法规，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关内部执法监督，是指上级公安机关对下级公安机关，上级业务部门对下级业务部门，本级公安机关对所属业务部门、派出机构及其人民警察的各项执法活动实施的监督。"},{"i":3,"n":"第三条","txt":"各级公安机关及其业务部门应当建立执法责任制和执法过错责任追究等执法制度，制定、完善执法程序，加强对各项公安执法活动的监督制约。"},{"i":4,"n":"第四条","txt":"执法监督工作必须以事实为根据，以法律为准绳，遵循有错必纠、监督与指导相结合、教育与惩处相结合的原则。"},{"i":5,"n":"第五条","txt":"各级公安机关在加强内部执法监督的同时，必须依法接受人民群众、新闻舆论的监督，接受国家权力机关、人民政府的监督，接受人民检察院的法律监督和人民法院的审判监督。"},{"i":6,"n":"第六条","txt":"执法监督的范围： （一）有关执法工作的规范性文件及制度、措施是否合法； （二）刑事立案、销案，实施侦查措施、刑事强制措施和执行刑罚等刑事执法活动是否合法和适当； （三）有关治安管理、户籍管理、交通管理、消防管理、边防管理、出入境管理等法律法规的实施情况； （四）适用和执行行政拘留、罚款、没收非法财物、吊销许可证、查封、扣押、冻结财物、强制戒毒等行政处罚和行政强制措施是否合法和适当； （五）看守所、拘役所、治安拘留所、强制戒毒所、留置室等限制人身自由场所的执法情况； （六）行政复议、行政诉讼、国家赔偿等法律法规的实施情况； （七）国家赋予公安机关承担的其他执法职责的履行情况。"},{"i":7,"n":"第七条","txt":"执法监督的方式： （一）依照法律、法规和规章规定的执法程序和制度进行的监督； （二）对起草、制订的有关执法工作的规范性文件及制度、措施进行法律审核； （三）对疑难、有分歧、易出问题和各级公安机关决定需要专门监督的案件，进行案件审核； （四）组织执法检查、评议； （五）组织专项、专案调查； （六）依照法律、法规进行听证、复议、复核； （七）进行执法过错责任追究； （八）各级公安机关决定采取的其他方式。"},{"i":8,"n":"第八条","txt":"各级公安机关发现本级或者下级公安机关发布的规范性文件和制度、措施与国家法律、法规和规章相抵触的，应当予以纠正或者通知下级公安机关予以纠正。"},{"i":9,"n":"第九条","txt":"对案件的审核可以采取阅卷审查方式进行，就案件的事实是否清楚，证据是否确凿、充分，定性是否准确，处理意见是否适当，适用法律是否正确，程序是否合法，法律文书是否规范、完备等内容进行审核，保障案件质量。"},{"i":10,"n":"第十条","txt":"对公安行政管理执法行为的审核，可以采取查阅台帐、法律文书、档案等方式，就适用法律是否正确、程序是否合法等内容进行审核，保障公正执法。"},{"i":11,"n":"第十一条","txt":"各级公安机关每年应当定期、不定期地组织对本级和下级公安机关的执法活动进行检查或者评议。 有关公安工作的法律、法规发布实施后，各级公安机关应当在一年内对该项法律、法规的执行情况，组织执法检查，检查结果报上一级公安机关并在本级公安机关予以通报。 各级公安机关对本级和下级公安机关每年的执法工作情况应当进行综合考评。考评结果报上一级公安机关并在本级公安机关予以通报。考评结果与奖惩相结合。"},{"i":12,"n":"第十二条","txt":"对国家权力机关、人民政府或者上级公安机关交办复查的案件，人民群众反映强烈的普遍性、倾向性的公安执法问题，应当组织有关部门进行专项调查或者专案调查。在查明情况后，应当写出调查报告，提出处理意见和纠正措施，报本级公安机关领导批准后组织实施，并将查处结果报告交办机关和上级公安机关。"},{"i":13,"n":"第十三条","txt":"在执法监督过程中，发现本级或者下级公安机关已经办结的案件或者执法活动确有错误、不适当的，主管部门报经主管领导批准后，直接作出纠正的决定，或者责成有关部门或者下级公安机关在规定的时限内依法予以纠正。"},{"i":14,"n":"第十四条","txt":"公安机关办理听证、行政复议、国家赔偿案件工作依照国家法律、法规规定的程序进行。"},{"i":15,"n":"第十五条","txt":"对公安机关及其人民警察违法行使职权或者不依法履行职责，致使办理的案件或者执法行为不合法、不适当的，必须依照有关法律、法规和本规定予以纠正和处理。"},{"i":16,"n":"第十六条","txt":"各级公安机关的行政首长是执法监督的责任人，负责对本级和下级公安机关及其人民警察的执法活动组织实施监督。 公安机关各业务部门的负责人是本部门执法监督的责任人，负责对本部门及其人民警察的执法活动实施监督。"},{"i":17,"n":"第十七条","txt":"各级公安机关法制部门是内部执法监督工作的主管部门，在本级公安机关的领导下，负责组织、实施、协调和指导执法监督工作。"},{"i":18,"n":"第十八条","txt":"公安机关警务督察部门依照《公安机关督察条例》的规定，对公安机关及其人民警察的执法活动进行现场督察。"},{"i":19,"n":"第十九条","txt":"对公安机关及其人民警察不合法、不适当的执法活动，分别作出如下处理： （一）对错误的处理或者决定予以撤销或者变更； （二）对拒不履行法定职责的，责令其在规定的时限内履行法定职责； （三）对拒不执行上级公安机关决定和命令的有关人员，可以停止执行职务； （四）公安机关及其人民警察违法行使职权已经给公民、法人和其他组织造成损害，需要给予国家赔偿的，应当依照《中华人民共和国国家赔偿法》的规定予以国家赔偿； （五）公安机关人民警察在执法活动中因故意或者过失，造成执法过错的，按照《公安机关人民警察执法过错责任追究规定》追究执法过错责任。"},{"i":20,"n":"第二十条","txt":"公安机关的领导和有关责任人员在执法工作中有违法违纪行为需要追究纪律和法律责任的，依照有关规定办理。"},{"i":21,"n":"第二十一条","txt":"对上级公安机关及其主管部门的执法监督决定、命令，有关公安机关及其职能部门必须执行，并报告执行结果。 对执法监督决定有异议的，应当先予执行，然后按照规定提出意见，作出决定的机关应当认真审查，执行后果由作出决定的公安机关负责。"},{"i":22,"n":"第二十二条","txt":"拒绝、阻碍上级机关或本级公安机关及执法监督主管部门的执法监督检查，拒不执行公安机关内部执法监督的有关决定、命令，或者无故拖延执行，对被监督的公安机关或者业务部门的负责人，应当依照有关规定给予纪律处分。"},{"i":23,"n":"第二十三条","txt":"对本级和上级公安机关作出的执法监督决定不服，有关单位和人民警察可以向本级或者上级公安机关提出申诉，有关部门应当认真受理，并作出答复。"},{"i":24,"n":"第二十四条","txt":"各级公安机关的执法监督责任人和执法监督主管部门必须严格依法履行执法监督职责，模范遵守法律，秉公执法，依法办事。对不严格履行执法监督职责或者滥用职权，造成不良影响的，应当给予通报批评；后果严重的，应当依照有关规定给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"各省、自治区、直辖市公安厅局可以根据本规定，结合本地实际情况，制定实施办法。"},{"i":26,"n":"第二十六条","txt":"本规定由公安部法制局负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自颁布之日起实施。"}],"gonganjiguanbanlixingshifuyifuheanjianchengxuguidi55f9e3":[{"i":1,"n":"第一条","txt":"为了规范公安机关刑事复议、复核案件的办理程序，依法保护公民、法人和其他组织的合法权益，保障和监督公安机关依法行使职责，根据《中华人民共和国刑事诉讼法》及相关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"刑事案件中的相关人员对公安机关作出的驳回申请回避、没收保证金、对保证人罚款、不予立案决定不服，向公安机关提出刑事复议、复核申请，公安机关受理刑事复议、复核申请，作出刑事复议、复核决定，适用本规定。"},{"i":3,"n":"第三条","txt":"公安机关办理刑事复议、复核案件，应当遵循合法公正、有错必纠的原则，确保国家法律正确实施。"},{"i":4,"n":"第四条","txt":"本规定所称刑事复议、复核机构，是指公安机关法制部门。 公安机关各相关部门应当按照职责分工，配合法制部门共同做好刑事复议、复核工作。"},{"i":5,"n":"第五条","txt":"刑事复议、复核机构办理刑事复议、复核案件所需经费应当在本级公安业务费中列支；办理刑事复议、复核事项所需的设备、工作条件，所属公安机关应当予以保障。"},{"i":6,"n":"第六条","txt":"在办理刑事案件过程中，下列相关人员可以依法向作出决定的公安机关提出刑事复议申请： （一）对驳回申请回避决定不服的，当事人及其法定代理人、诉讼代理人、辩护律师可以提出； （二）对没收保证金决定不服的，被取保候审人或者其法定代理人可以提出； （三）保证人对罚款决定不服的，其本人可以提出； （四）对不予立案决定不服的，控告人可以提出； （五）移送案件的行政机关对不予立案决定不服的，该行政机关可以提出。"},{"i":7,"n":"第七条","txt":"刑事复议申请人对公安机关就本规定第六条第二至四项决定作出的刑事复议决定不服的，可以向其上一级公安机关提出刑事复核申请。"},{"i":8,"n":"第八条","txt":"申请刑事复议、复核应当在《公安机关办理刑事案件程序规定》规定的期限内提出，因不可抗力或者其他正当理由不能在法定期限内提出的，应当在障碍消除后五个工作日以内提交相应证明材料。经刑事复议、复核机构认定的，耽误的时间不计算在法定申请期限内。 前款规定中的“其他正当理由”包括： （一）因严重疾病不能在法定申请期限内申请刑事复议、复核的； （二）无行为能力人或者限制行为能力人的法定代理人在法定申请期限内不能确定的； （三）法人或者其他组织合并、分立或者终止，承受其权利的法人或者其他组织在法定申请期限内不能确定的； （四）刑事复议、复核机构认定的其他正当理由。"},{"i":9,"n":"第九条","txt":"申请刑事复议，应当书面申请，但情况紧急或者申请人不便提出书面申请的，可以口头申请。 申请刑事复核，应当书面申请。"},{"i":10,"n":"第十条","txt":"书面申请刑事复议、复核的，应当向刑事复议、复核机构提交刑事复议、复核申请书，载明下列内容： （一）申请人及其代理人的姓名、性别、出生年月日、工作单位、住所、联系方式；法人或者其他组织的名称、地址、法定代表人或者主要负责人的姓名、职务、住所、联系方式； （二）作出决定或者复议决定的公安机关名称； （三）刑事复议、复核请求； （四）申请刑事复议、复核的事实和理由； （五）申请刑事复议、复核的日期。 刑事复议、复核申请书应当由申请人签名或者捺指印。"},{"i":11,"n":"第十一条","txt":"申请人口头申请刑事复议的，刑事复议机构工作人员应当按照本规定第十条规定的事项，当场制作刑事复议申请记录，经申请人核对或者向申请人宣读并确认无误后，由申请人签名或者捺指印。"},{"i":12,"n":"第十二条","txt":"申请刑事复议、复核时，申请人应当提交下列材料： （一）原决定书、通知书的复印件； （二）申请刑事复核的还应当提交复议决定书复印件； （三）申请人的身份证明复印件； （四）诉讼代理人提出申请的，还应当提供当事人的委托书； （五）辩护律师提出申请的，还应当提供律师执业证书复印件、律师事务所证明和委托书或者法律援助公函等材料； （六）申请人自行收集的相关事实、证据材料。"},{"i":13,"n":"第十三条","txt":"刑事复议、复核机构开展下列工作时，办案人员不得少于二人： （一）接受口头刑事复议申请的； （二）向有关组织和人员调查情况的； （三）听取申请人和相关人员意见的。 刑事复议机构参与审核原决定的人员，不得担任刑事复议案件的办案人员。"},{"i":14,"n":"第十四条","txt":"刑事复议、复核机构收到刑事复议、复核申请后，应当对申请是否同时符合下列条件进行初步审查： （一）属于本机关受理； （二）申请人具有法定资格； （三）有明确的刑事复议、复核请求； （四）属于刑事复议、复核的范围； （五）在规定期限内提出； （六）所附材料齐全。"},{"i":15,"n":"第十五条","txt":"刑事复议、复核机构应当自收到刑事复议、复核申请之日起五个工作日以内分别作出下列处理： （一）符合本规定第十四条规定条件的，予以受理； （二）不符合本规定第十四条规定条件的，不予受理。不属于本机关受理的，应当告知申请人向有权受理的公安机关提出； （三）申请材料不齐全的，应当一次性书面通知申请人在五个工作日以内补充相关材料，刑事复议、复核时限自收到申请人的补充材料之日起计算。 公安机关作出刑事复议、复核决定后，相关人员就同一事项再次申请刑事复议、复核的，不予受理。"},{"i":16,"n":"第十六条","txt":"收到控告人对不予立案决定的刑事复议、复核申请后，公安机关应当对控告人是否就同一事项向检察机关提出控告、申诉进行审核。检察机关已经受理控告人对同一事项的控告、申诉的，公安机关应当决定不予受理；公安机关受理后，控告人就同一事项向检察机关提出控告、申诉，检察机关已经受理的，公安机关应当终止刑事复议、复核程序。"},{"i":17,"n":"第十七条","txt":"申请人申请刑事复议、复核时一并提起国家赔偿申请的，刑事复议、复核机构应当告知申请人另行提起国家赔偿申请。"},{"i":18,"n":"第十八条","txt":"公安机关不予受理刑事复议、复核申请或者终止刑事复议、复核程序的，应当在作出决定后三个工作日以内书面告知申请人。"},{"i":19,"n":"第十九条","txt":"对受理的驳回申请回避决定的刑事复议案件，刑事复议机构应当重点审核下列事项： （一）是否具有应当回避的法定事由； （二）适用依据是否正确； （三）是否符合法定程序。"},{"i":20,"n":"第二十条","txt":"对受理的没收保证金决定的刑事复议、复核案件，刑事复议、复核机构应当重点审核下列事项： （一）被取保候审人是否违反在取保候审期间应当遵守的相关规定； （二）适用依据是否正确； （三）是否存在明显不当； （四）是否符合法定程序； （五）是否超越或者滥用职权。"},{"i":21,"n":"第二十一条","txt":"对受理的保证人不服罚款决定的刑事复议、复核案件，刑事复议、复核机构应当重点审核下列事项： （一）被取保候审人是否违反在取保候审期间应当遵守的相关规定； （二）保证人是否未履行保证义务； （三）适用依据是否正确； （四）是否存在明显不当； （五）是否符合法定程序； （六）是否超越或者滥用职权。"},{"i":22,"n":"第二十二条","txt":"对受理的不予立案决定的刑事复议、复核案件，刑事复议、复核机构应当重点审核下列事项： （一）是否符合立案条件； （二）是否有控告行为涉嫌犯罪的证据； （三）适用依据是否正确； （四）是否符合法定程序； （五）是否属于不履行法定职责。 前款第二项规定的“涉嫌犯罪”，不受控告的具体罪名的限制。 办理过程中发现控告行为之外的其他事实，可能涉嫌犯罪的，应当建议办案部门进行调查，但调查结果不作为作出刑事复议、复核决定的依据。"},{"i":23,"n":"第二十三条","txt":"受理刑事复议、复核申请后，刑事复议、复核机构应当及时通知办案部门或者作出刑事复议决定的机关在规定期限内提供作出决定依据的证据以及其他有关材料。 办案部门或者作出刑事复议决定的机关应当在刑事复议、复核机构规定的期限内全面如实提供相关案件材料。"},{"i":24,"n":"第二十四条","txt":"办理刑事复核案件时，刑事复核机构可以征求同级公安机关有关业务部门的意见，有关业务部门应当及时提出意见。"},{"i":25,"n":"第二十五条","txt":"根据申请人提供的材料无法确定案件事实，需要另行调查取证的，经刑事复议、复核机构负责人报公安机关负责人批准，刑事复议、复核机构应当通知办案部门或者作出刑事复议决定的机关调查取证。办案部门或者作出刑事复议决定的机关应当在通知的期限内将调查取证结果反馈给刑事复议、复核机构。"},{"i":26,"n":"第二十六条","txt":"刑事复议、复核决定作出前，申请人要求撤回申请的，应当书面申请并说明理由。刑事复议、复核机构允许申请人撤回申请的，应当终止刑事复议、复核程序。但具有下列情形之一的，不允许申请人撤回申请，并告知申请人： （一）撤回申请可能损害国家利益、公共利益或者他人合法权益的； （二）撤回申请不是出于申请人自愿的； （三）其他不允许撤回申请的情形。 公安机关允许申请人撤回申请后，申请人以同一事实和理由重新提出申请的，不予受理。"},{"i":27,"n":"第二十七条","txt":"当事人及其法定代理人、诉讼代理人、辩护律师对驳回申请回避决定申请刑事复议的，公安机关应当在收到申请后五个工作日以内作出决定并书面告知申请人。"},{"i":28,"n":"第二十八条","txt":"移送案件的行政执法机关对不予立案决定申请刑事复议的，公安机关应当在收到申请后三个工作日以内作出决定并书面告知移送案件的行政执法机关。"},{"i":29,"n":"第二十九条","txt":"对没收保证金决定和对保证人罚款决定申请刑事复议、复核的，公安机关应当在收到申请后七个工作日以内作出决定并书面告知申请人。"},{"i":30,"n":"第三十条","txt":"控告人对不予立案决定申请刑事复议、复核的，公安机关应当在收到申请后三十日以内作出决定并书面告知申请人。 案情重大、复杂的，经刑事复议、复核机构负责人批准，可以延长，但是延长时限不得超过三十日，并书面告知申请人。"},{"i":31,"n":"第三十一条","txt":"刑事复议、复核期间，有下列情形之一的，经刑事复议、复核机构负责人批准，可以中止刑事复议、复核，并书面告知申请人： （一）案件涉及专业问题，需要有关机关或者专业机构作出解释或者确认的； （二）无法找到有关当事人的； （三）需要等待鉴定意见的； （四）其他应当中止复议、复核的情形。 中止事由消失后，刑事复议、复核机构应当及时恢复刑事复议、复核，并书面告知申请人。"},{"i":32,"n":"第三十二条","txt":"原决定或者刑事复议决定认定的事实清楚、证据充分、依据准确、程序合法的，公安机关应当作出维持原决定或者刑事复议决定的复议、复核决定。"},{"i":33,"n":"第三十三条","txt":"原决定或者刑事复议决定认定的主要事实不清、证据不足、依据错误、违反法定程序、超越职权或者滥用职权的，公安机关应当作出撤销、变更原决定或者刑事复议决定的复议、复核决定。 经刑事复议，公安机关撤销原驳回申请回避决定、不予立案决定的，应当重新作出决定；撤销原没收保证金决定、对保证人罚款决定的，应当退还保证金或者罚款；认为没收保证金数额、罚款数额明显不当的，应当作出变更原决定的复议决定，但不得提高没收保证金、罚款的数额。 经刑事复核，上级公安机关撤销刑事复议决定的，作出复议决定的公安机关应当执行；需要重新作出决定的，应当责令作出复议决定的公安机关依法重新作出决定，重新作出的决定不得与原决定相同，不得提高没收保证金、罚款的数额。"},{"i":34,"n":"第三十四条","txt":"铁路、交通、民航、森林公安机关，海关走私犯罪侦查机构办理刑事复议、复核案件，适用本规定。"},{"i":35,"n":"第三十五条","txt":"本规定自2014年11月1日起施行。本规定发布前公安部制定的有关规定与本规定不一致的，以本规定为准。"}],"gonganjiguanbanlixingshianjianchengxuguiding":[{"i":1,"n":"第一条","txt":"为了保障《中华人民共和国刑事诉讼法》的贯彻实施，保证公安机关在刑事诉讼中正确履行职权，规范办案程序，确保办案质量，提高办案效率，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关在刑事诉讼中的任务，是保证准确、及时地查明犯罪事实，正确应用法律，惩罚犯罪分子，保障无罪的人不受刑事追究，教育公民自觉遵守法律，积极同犯罪行为作斗争，维护社会主义法制，尊重和保障人权，保护公民的人身权利、财产权利、民主权利和其他权利，保障社会主义建设事业的顺利进行。"},{"i":3,"n":"第三条","txt":"公安机关在刑事诉讼中的基本职权，是依照法律对刑事案件立案、侦查、预审；决定、执行强制措施；对依法不追究刑事责任的不予立案，已经追究的撤销案件；对侦查终结应当起诉的案件，移送人民检察院审查决定；对不够刑事处罚的犯罪嫌疑人需要行政处理的，依法予以处理或者移送有关部门；对被判处有期徒刑的罪犯，在被交付执行刑罚前，剩余刑期在三个月以下的，代为执行刑罚；执行拘役、剥夺政治权利、驱逐出境。"},{"i":4,"n":"第四条","txt":"公安机关进行刑事诉讼，必须依靠群众，以事实为根据，以法律为准绳。对于一切公民，在适用法律上一律平等，在法律面前，不允许有任何特权。"},{"i":5,"n":"第五条","txt":"公安机关进行刑事诉讼，同人民法院、人民检察院分工负责，互相配合，互相制约，以保证准确有效地执行法律。"},{"i":6,"n":"第六条","txt":"公安机关进行刑事诉讼，依法接受人民检察院的法律监督。"},{"i":7,"n":"第七条","txt":"公安机关进行刑事诉讼，应当建立、完善和严格执行办案责任制度、执法过错责任追究制度等内部执法监督制度。 在刑事诉讼中，上级公安机关发现下级公安机关作出的决定或者办理的案件有错误的，有权予以撤销或者变更，也可以指令下级公安机关予以纠正。 下级公安机关对上级公安机关的决定必须执行，如果认为有错误，可以在执行的同时向上级公安机关报告。"},{"i":8,"n":"第八条","txt":"公安机关办理刑事案件，应当重证据，重调查研究，不轻信口供。严禁刑讯逼供和以威胁、引诱、欺骗以及其他非法方法收集证据，不得强迫任何人证实自己有罪。"},{"i":9,"n":"第九条","txt":"公安机关在刑事诉讼中，应当保障犯罪嫌疑人、被告人和其他诉讼参与人依法享有的辩护权和其他诉讼权利。"},{"i":10,"n":"第十条","txt":"公安机关办理刑事案件，应当向同级人民检察院提请批准逮捕、移送审查起诉。"},{"i":11,"n":"第十一条","txt":"公安机关办理刑事案件，对不通晓当地通用的语言文字的诉讼参与人，应当为他们翻译。 在少数民族聚居或者多民族杂居的地区，应当使用当地通用的语言进行讯问。对外公布的诉讼文书，应当使用当地通用的文字。"},{"i":12,"n":"第十二条","txt":"公安机关办理刑事案件，各地区、各部门之间应当加强协作和配合，依法履行协查、协办职责。 上级公安机关应当加强监督、协调和指导。"},{"i":13,"n":"第十三条","txt":"根据《中华人民共和国引渡法》《中华人民共和国国际刑事司法协助法》，中华人民共和国缔结或者参加的国际条约和公安部签订的双边、多边合作协议，或者按照互惠原则，我国公安机关可以和外国警察机关开展刑事司法协助和警务合作。"},{"i":14,"n":"第十四条","txt":"根据刑事诉讼法的规定，除下列情形外，刑事案件由公安机关管辖： （一）监察机关管辖的职务犯罪案件； （二）人民检察院管辖的在对诉讼活动实行法律监督中发现的司法工作人员利用职权实施的非法拘禁、刑讯逼供、非法搜查等侵犯公民权利、损害司法公正的犯罪，以及经省级以上人民检察院决定立案侦查的公安机关管辖的国家机关工作人员利用职权实施的重大犯罪案件； （三）人民法院管辖的自诉案件。对于人民法院直接受理的被害人有证据证明的轻微刑事案件，因证据不足驳回起诉，人民法院移送公安机关或者被害人向公安机关控告的，公安机关应当受理；被害人直接向公安机关控告的，公安机关应当受理； （四）军队保卫部门管辖的军人违反职责的犯罪和军队内部发生的刑事案件； （五）监狱管辖的罪犯在监狱内犯罪的刑事案件； （六）海警部门管辖的海（岛屿）岸线以外我国管辖海域内发生的刑事案件。对于发生在沿海港岙口、码头、滩涂、台轮停泊点等区域的，"},{"i":15,"n":"第十五条","txt":"刑事案件由犯罪地的公安机关管辖。如果由犯罪嫌疑人居住地的公安机关管辖更为适宜的，可以由犯罪嫌疑人居住地的公安机关管辖。 法律、司法解释或者其他规范性文件对有关犯罪案件的管辖作出特别规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"犯罪地包括犯罪行为发生地和犯罪结果发生地。犯罪行为发生地，包括犯罪行为的实施地以及预备地、开始地、途经地、结束地等与犯罪行为有关的地点；犯罪行为有连续、持续或者继续状态的，犯罪行为连续、持续或者继续实施的地方都属于犯罪行为发生地。犯罪结果发生地，包括犯罪对象被侵害地、犯罪所得的实际取得地、藏匿地、转移地、使用地、销售地。 居住地包括户籍所在地、经常居住地。经常居住地是指公民离开户籍所在地最后连续居住一年以上的地方，但住院就医的除外。单位登记的住所地为其居住地。主要营业地或者主要办事机构所在地与登记的住所地不一致的，主要营业地或者主要办事机构所在地为其居住地。"},{"i":17,"n":"第十七条","txt":"针对或者主要利用计算机网络实施的犯罪，用于实施犯罪行为的网络服务使用的服务器所在地，网络服务提供者所在地，被侵害的网络信息系统及其管理者所在地，以及犯罪过程中犯罪嫌疑人、被害人使用的网络信息系统所在地，被害人被侵害时所在地和被害人财产遭受损失地公安机关可以管辖。"},{"i":18,"n":"第十八条","txt":"行驶中的交通工具上发生的刑事案件，由交通工具最初停靠地公安机关管辖；必要时，交通工具始发地、途经地、目的地公安机关也可以管辖。"},{"i":19,"n":"第十九条","txt":"在中华人民共和国领域外的中国航空器内发生的刑事案件，由该航空器在中国最初降落地的公安机关管辖。"},{"i":20,"n":"第二十条","txt":"中国公民在中国驻外使、领馆内的犯罪，由其主管单位所在地或者原户籍地的公安机关管辖。 中国公民在中华人民共和国领域外的犯罪，由其入境地、离境前居住地或者现居住地的公安机关管辖；被害人是中国公民的，也可由被害人离境前居住地或者现居住地的公安机关管辖。"},{"i":21,"n":"第二十一条","txt":"几个公安机关都有权管辖的刑事案件，由最初受理的公安机关管辖。必要时，可以由主要犯罪地的公安机关管辖。 具有下列情形之一的，公安机关可以在职责范围内并案侦查： （一）一人犯数罪的； （二）共同犯罪的； （三）共同犯罪的犯罪嫌疑人还实施其他犯罪的； （四）多个犯罪嫌疑人实施的犯罪存在关联，并案处理有利于查明犯罪事实的。"},{"i":22,"n":"第二十二条","txt":"对管辖不明确或者有争议的刑事案件，可以由有关公安机关协商。协商不成的，由共同的上级公安机关指定管辖。 对情况特殊的刑事案件，可以由共同的上级公安机关指定管辖。 提请上级公安机关指定管辖时，应当在有关材料中列明犯罪嫌疑人基本情况、涉嫌罪名、案件基本事实、管辖争议情况、协商情况和指定管辖理由，经公安机关负责人批准后，层报有权指定管辖的上级公安机关。"},{"i":23,"n":"第二十三条","txt":"上级公安机关指定管辖的，应当将指定管辖决定书分别送达被指定管辖的公安机关和其他有关的公安机关，并根据办案需要抄送同级人民法院、人民检察院。 原受理案件的公安机关，在收到上级公安机关指定其他公安机关管辖的决定书后，不再行使管辖权，同时应当将犯罪嫌疑人、涉案财物以及案卷材料等移送被指定管辖的公安机关。 对指定管辖的案件，需要逮捕犯罪嫌疑人的，由被指定管辖的公安机关提请同级人民检察院审查批准；需要提起公诉的，由该公安机关移送同级人民检察院审查决定。"},{"i":24,"n":"第二十四条","txt":"县级公安机关负责侦查发生在本辖区内的刑事案件。 设区的市一级以上公安机关负责下列犯罪中重大案件的侦查： （一）危害国家安全犯罪； （二）恐怖活动犯罪； （三）涉外犯罪； （四）经济犯罪； （五）集团犯罪； （六）跨区域犯罪。 上级公安机关认为有必要的，可以侦查下级公安机关管辖的刑事案件；下级公安机关认为案情重大需要上级公安机关侦查的刑事案件，可以请求上一级公安机关管辖。"},{"i":25,"n":"第二十五条","txt":"公安机关内部对刑事案件的管辖，按照刑事侦查机构的设置及其职责分工确定。"},{"i":26,"n":"第二十六条","txt":"铁路公安机关管辖铁路系统的机关、厂、段、院、校、所、队、工区等单位发生的刑事案件，车站工作区域内、列车内发生的刑事案件，铁路沿线发生的盗窃或者破坏铁路、通信、电力线路和其他重要设施的刑事案件，以及内部职工在铁路线上工作时发生的刑事案件。 铁路系统的计算机信息系统延伸到地方涉及铁路业务的网点，其计算机信息系统发生的刑事案件由铁路公安机关管辖。 对倒卖、伪造、变造火车票的刑事案件，由最初受理案件的铁路公安机关或者地方公安机关管辖。必要时，可以移送主要犯罪地的铁路公安机关或者地方公安机关管辖。 在列车上发生的刑事案件，犯罪嫌疑人在列车运行途中被抓获的，由前方停靠站所在地的铁路公安机关管辖；必要时，也可以由列车始发站、终点站所在地的铁路公安机关管辖。犯罪嫌疑人不是在列车运行途中被抓获的，由负责该列车乘务的铁路公安机关管辖；但在列车运行途经的车站被抓获的，也可以由该车站所在地的铁路公安机关管辖。"},{"i":27,"n":"第二十七条","txt":"民航公安机关管辖民航系统的机关、厂、段、院、校、所、队、工区等单位、机场工作区域内、民航飞机内发生的刑事案件。 重大飞行事故刑事案件由犯罪结果发生地机场公安机关管辖。犯罪结果发生地未设机场公安机关或者不在机场公安机关管辖范围内的，由地方公安机关管辖，有关机场公安机关予以协助。"},{"i":28,"n":"第二十八条","txt":"海关走私犯罪侦查机构管辖中华人民共和国海关关境内发生的涉税走私犯罪和发生在海关监管区内的非涉税走私犯罪等刑事案件。"},{"i":29,"n":"第二十九条","txt":"公安机关侦查的刑事案件的犯罪嫌疑人涉及监察机关管辖的案件时，应当及时与同级监察机关协商，一般应当由监察机关为主调查，公安机关予以协助。"},{"i":30,"n":"第三十条","txt":"公安机关侦查的刑事案件涉及人民检察院管辖的案件时，应当将属于人民检察院管辖的刑事案件移送人民检察院。涉嫌主罪属于公安机关管辖的，由公安机关为主侦查；涉嫌主罪属于人民检察院管辖的，公安机关予以配合。 公安机关侦查的刑事案件涉及其他侦查机关管辖的案件时，参照前款规定办理。"},{"i":31,"n":"第三十一条","txt":"公安机关和军队互涉刑事案件的管辖分工按照有关规定办理。 公安机关和武装警察部队互涉刑事案件的管辖分工依照公安机关和军队互涉刑事案件的管辖分工的原则办理。"},{"i":32,"n":"第三十二条","txt":"公安机关负责人、侦查人员有下列情形之一的，应当自行提出回避申请，没有自行提出回避申请的，应当责令其回避，当事人及其法定代理人也有权要求他们回避： （一）是本案的当事人或者是当事人的近亲属的； （二）本人或者他的近亲属和本案有利害关系的； （三）担任过本案的证人、鉴定人、辩护人、诉讼代理人的； （四）与本案当事人有其他关系，可能影响公正处理案件的。"},{"i":33,"n":"第三十三条","txt":"公安机关负责人、侦查人员不得有下列行为： （一）违反规定会见本案当事人及其委托人； （二）索取、接受本案当事人及其委托人的财物或者其他利益； （三）接受本案当事人及其委托人的宴请，或者参加由其支付费用的活动； （四）其他可能影响案件公正办理的不正当行为。 违反前款规定的，应当责令其回避并依法追究法律责任。当事人及其法定代理人有权要求其回避。"},{"i":34,"n":"第三十四条","txt":"公安机关负责人、侦查人员自行提出回避申请的，应当说明回避的理由；口头提出申请的，公安机关应当记录在案。 当事人及其法定代理人要求公安机关负责人、侦查人员回避，应当提出申请，并说明理由；口头提出申请的，公安机关应当记录在案。"},{"i":35,"n":"第三十五条","txt":"侦查人员的回避，由县级以上公安机关负责人决定；县级以上公安机关负责人的回避，由同级人民检察院检察委员会决定。"},{"i":36,"n":"第三十六条","txt":"当事人及其法定代理人对侦查人员提出回避申请的，公安机关应当在收到回避申请后二日以内作出决定并通知申请人；情况复杂的，经县级以上公安机关负责人批准，可以在收到回避申请后五日以内作出决定。 当事人及其法定代理人对县级以上公安机关负责人提出回避申请的，公安机关应当及时将申请移送同级人民检察院。"},{"i":37,"n":"第三十七条","txt":"当事人及其法定代理人对驳回申请回避的决定不服的，可以在收到驳回申请回避决定书后五日以内向作出决定的公安机关申请复议。 公安机关应当在收到复议申请后五日以内作出复议决定并书面通知申请人。"},{"i":38,"n":"第三十八条","txt":"在作出回避决定前，申请或者被申请回避的公安机关负责人、侦查人员不得停止对案件的侦查。 作出回避决定后，申请或者被申请回避的公安机关负责人、侦查人员不得再参与本案的侦查工作。"},{"i":39,"n":"第三十九条","txt":"被决定回避的公安机关负责人、侦查人员在回避决定作出以前所进行的诉讼活动是否有效，由作出决定的机关根据案件情况决定。"},{"i":40,"n":"第四十条","txt":"本章关于回避的规定适用于记录人、翻译人员和鉴定人。 记录人、翻译人员和鉴定人需要回避的，由县级以上公安机关负责人决定。"},{"i":41,"n":"第四十一条","txt":"辩护人、诉讼代理人可以依照本章的规定要求回避、申请复议。"},{"i":42,"n":"第四十二条","txt":"公安机关应当保障辩护律师在侦查阶段依法从事下列执业活动： （一）向公安机关了解犯罪嫌疑人涉嫌的罪名和案件有关情况，提出意见； （二）与犯罪嫌疑人会见和通信，向犯罪嫌疑人了解案件有关情况； （三）为犯罪嫌疑人提供法律帮助、代理申诉、控告； （四）为犯罪嫌疑人申请变更强制措施。"},{"i":43,"n":"第四十三条","txt":"公安机关在第一次讯问犯罪嫌疑人或者对犯罪嫌疑人采取强制措施的时候，应当告知犯罪嫌疑人有权委托律师作为辩护人，并告知其如果因经济困难或者其他原因没有委托辩护律师的，可以向法律援助机构申请法律援助。告知的情形应当记录在案。 对于同案的犯罪嫌疑人委托同一名辩护律师的，或者两名以上未同案处理但实施的犯罪存在关联的犯罪嫌疑人委托同一名辩护律师的，公安机关应当要求其更换辩护律师。"},{"i":44,"n":"第四十四条","txt":"犯罪嫌疑人可以自己委托辩护律师。犯罪嫌疑人在押的，也可以由其监护人、近亲属代为委托辩护律师。 犯罪嫌疑人委托辩护律师的请求可以书面提出，也可以口头提出。口头提出的，公安机关应当制作笔录，由犯罪嫌疑人签名、捺指印。"},{"i":45,"n":"第四十五条","txt":"在押的犯罪嫌疑人向看守所提出委托辩护律师要求的，看守所应当及时将其请求转达给办案部门，办案部门应当及时向犯罪嫌疑人委托的辩护律师或者律师事务所转达该项请求。 在押的犯罪嫌疑人仅提出委托辩护律师的要求，但提不出具体对象的，办案部门应当及时通知犯罪嫌疑人的监护人、近亲属代为委托辩护律师。犯罪嫌疑人无监护人或者近亲属的，办案部门应当及时通知当地律师协会或者司法行政机关为其推荐辩护律师。"},{"i":46,"n":"第四十六条","txt":"符合下列情形之一，犯罪嫌疑人没有委托辩护人的，公安机关应当自发现该情形之日起三日以内通知法律援助机构为犯罪嫌疑人指派辩护律师： （一）犯罪嫌疑人是盲、聋、哑人，或者是尚未完全丧失辨认或者控制自己行为能力的精神病人； （二）犯罪嫌疑人可能被判处无期徒刑、死刑。"},{"i":47,"n":"第四十七条","txt":"公安机关收到在押的犯罪嫌疑人提出的法律援助申请后，应当在二十四小时以内将其申请转交所在地的法律援助机构，并在三日以内通知申请人的法定代理人、近亲属或者其委托的其他人员协助提供有关证件、证明等相关材料。犯罪嫌疑人的法定代理人、近亲属或者其委托的其他人员地址不详无法通知的，应当在转交申请时一并告知法律援助机构。 犯罪嫌疑人拒绝法律援助机构指派的律师作为辩护人或者自行委托辩护人的，公安机关应当在三日以内通知法律援助机构。"},{"i":48,"n":"第四十八条","txt":"辩护律师接受犯罪嫌疑人委托或者法律援助机构的指派后，应当及时告知公安机关并出示律师执业证书、律师事务所证明和委托书或者法律援助公函。"},{"i":49,"n":"第四十九条","txt":"犯罪嫌疑人、被告人入所羁押时没有委托辩护人，法律援助机构也没有指派律师提供辩护的，看守所应当告知其有权约见值班律师，获得法律咨询、程序选择建议、申请变更强制措施、对案件处理提出意见等法律帮助，并为犯罪嫌疑人、被告人约见值班律师提供便利。 没有委托辩护人、法律援助机构没有指派律师提供辩护的犯罪嫌疑人、被告人，向看守所申请由值班律师提供法律帮助的，看守所应当在二十四小时内通知值班律师。"},{"i":50,"n":"第五十条","txt":"辩护律师向公安机关了解案件有关情况的，公安机关应当依法将犯罪嫌疑人涉嫌的罪名以及当时已查明的该罪的主要事实，犯罪嫌疑人被采取、变更、解除强制措施，延长侦查羁押期限等案件有关情况，告知接受委托或者指派的辩护律师，并记录在案。"},{"i":51,"n":"第五十一条","txt":"辩护律师可以同在押或者被监视居住的犯罪嫌疑人会见、通信。"},{"i":52,"n":"第五十二条","txt":"对危害国家安全犯罪案件、恐怖活动犯罪案件，办案部门应当在将犯罪嫌疑人送看守所羁押时书面通知看守所；犯罪嫌疑人被监视居住的，应当在送交执行时书面通知执行机关。 辩护律师在侦查期间要求会见前款规定案件的在押或者被监视居住的犯罪嫌疑人，应当向办案部门提出申请。 对辩护律师提出的会见申请，办案部门应当在收到申请后三日以内，报经县级以上公安机关负责人批准，作出许可或者不许可的决定，书面通知辩护律师，并及时通知看守所或者执行监视居住的部门。除有碍侦查或者可能泄露国家秘密的情形外，应当作出许可的决定。 公安机关不许可会见的，应当说明理由。有碍侦查或者可能泄露国家秘密的情形消失后，公安机关应当许可会见。 有下列情形之一的，属于本条规定的“有碍侦查”： （一）可能毁灭、伪造证据，干扰证人作证或者串供的； （二）可能引起犯罪嫌疑人自残、自杀或者逃跑的； （三）可能引起同案犯逃避、妨碍侦查的； （四）犯罪嫌"},{"i":53,"n":"第五十三条","txt":"辩护律师要求会见在押的犯罪嫌疑人，看守所应当在查验其律师执业证书、律师事务所证明和委托书或者法律援助公函后，在四十八小时以内安排律师会见到犯罪嫌疑人，同时通知办案部门。 侦查期间，辩护律师会见危害国家安全犯罪案件、恐怖活动犯罪案件在押或者被监视居住的犯罪嫌疑人时，看守所或者监视居住执行机关还应当查验侦查机关的许可决定文书。"},{"i":54,"n":"第五十四条","txt":"辩护律师会见在押或者被监视居住的犯罪嫌疑人需要聘请翻译人员的，应当向办案部门提出申请。办案部门应当在收到申请后三日以内，报经县级以上公安机关负责人批准，作出许可或者不许可的决定，书面通知辩护律师。对于具有本规定第三十二条所列情形之一的，作出不予许可的决定，并通知其更换；不具有相关情形的，应当许可。 翻译人员参与会见的，看守所或者监视居住执行机关应当查验公安机关的许可决定文书。"},{"i":55,"n":"第五十五条","txt":"辩护律师会见在押或者被监视居住的犯罪嫌疑人时，看守所或者监视居住执行机关应当采取必要的管理措施，保障会见顺利进行，并告知其遵守会见的有关规定。辩护律师会见犯罪嫌疑人时，公安机关不得监听，不得派员在场。 辩护律师会见在押或者被监视居住的犯罪嫌疑人时，违反法律规定或者会见的规定的，看守所或者监视居住执行机关应当制止。对于严重违反规定或者不听劝阻的，可以决定停止本次会见，并及时通报其所在的律师事务所、所属的律师协会以及司法行政机关。"},{"i":56,"n":"第五十六条","txt":"辩护人或者其他任何人在刑事诉讼中，违反法律规定，实施干扰诉讼活动行为的，应当依法追究法律责任。 辩护人实施干扰诉讼活动行为，涉嫌犯罪，属于公安机关管辖的，应当由办理辩护人所承办案件的公安机关报请上一级公安机关指定其他公安机关立案侦查，或者由上一级公安机关立案侦查。不得指定原承办案件公安机关的下级公安机关立案侦查。辩护人是律师的，立案侦查的公安机关应当及时通知其所在的律师事务所、所属的律师协会以及司法行政机关。"},{"i":57,"n":"第五十七条","txt":"辩护律师对在执业活动中知悉的委托人的有关情况和信息，有权予以保密。但是，辩护律师在执业活动中知悉委托人或者其他人，准备或者正在实施危害国家安全、公共安全以及严重危害他人人身安全的犯罪的，应当及时告知司法机关。"},{"i":58,"n":"第五十八条","txt":"案件侦查终结前，辩护律师提出要求的，公安机关应当听取辩护律师的意见，根据情况进行核实，并记录在案。辩护律师提出书面意见的，应当附卷。 对辩护律师收集的犯罪嫌疑人不在犯罪现场、未达到刑事责任年龄、属于依法不负刑事责任的精神病人的证据，公安机关应当进行核实并将有关情况记录在案，有关证据应当附卷。"},{"i":59,"n":"第五十九条","txt":"可以用于证明案件事实的材料，都是证据。 证据包括： （一）物证； （二）书证； （三）证人证言； （四）被害人陈述； （五）犯罪嫌疑人供述和辩解； （六）鉴定意见； （七）勘验、检查、侦查实验、搜查、查封、扣押、提取、辨认等笔录； （八）视听资料、电子数据。 证据必须经过查证属实，才能作为认定案件事实的根据。"},{"i":60,"n":"第六十条","txt":"公安机关必须依照法定程序，收集、调取能够证实犯罪嫌疑人有罪或者无罪、犯罪情节轻重的各种证据。必须保证一切与案件有关或者了解案情的公民，有客观地充分地提供证据的条件，除特殊情况外，可以吸收他们协助调查。"},{"i":61,"n":"第六十一条","txt":"公安机关向有关单位和个人收集、调取证据时，应当告知其必须如实提供证据。 对涉及国家秘密、商业秘密、个人隐私的证据，应当保密。 对于伪造证据、隐匿证据或者毁灭证据的，应当追究其法律责任。"},{"i":62,"n":"第六十二条","txt":"公安机关向有关单位和个人调取证据，应当经办案部门负责人批准，开具调取证据通知书，明确调取的证据和提供时限。被调取单位及其经办人、持有证据的个人应当在通知书上盖章或者签名，拒绝盖章或者签名的，公安机关应当注明。必要时，应当采用录音录像方式固定证据内容及取证过程。"},{"i":63,"n":"第六十三条","txt":"公安机关接受或者依法调取的行政机关在行政执法和查办案件过程中收集的物证、书证、视听资料、电子数据、鉴定意见、勘验笔录、检查笔录等证据材料，经公安机关审查符合法定要求的，可以作为证据使用。"},{"i":64,"n":"第六十四条","txt":"收集、调取的物证应当是原物。只有在原物不便搬运、不易保存或者依法应当由有关部门保管、处理或者依法应当返还时，才可以拍摄或者制作足以反映原物外形或者内容的照片、录像或者复制品。 物证的照片、录像或者复制品经与原物核实无误或者经鉴定证明为真实的，或者以其他方式确能证明其真实的，可以作为证据使用。原物的照片、录像或者复制品，不能反映原物的外形和特征的，不能作为证据使用。"},{"i":65,"n":"第六十五条","txt":"收集、调取的书证应当是原件。只有在取得原件确有困难时，才可以使用副本或者复制件。 书证的副本、复制件，经与原件核实无误或者经鉴定证明为真实的，或者以其他方式确能证明其真实的，可以作为证据使用。书证有更改或者更改迹象不能作出合理解释的，或者书证的副本、复制件不能反映书证原件及其内容的，不能作为证据使用。"},{"i":66,"n":"第六十六条","txt":"收集、调取电子数据，能够扣押电子数据原始存储介质的，应当扣押原始存储介质，并制作笔录、予以封存。 确因客观原因无法扣押原始存储介质的，可以现场提取或者网络在线提取电子数据。无法扣押原始存储介质，也无法现场提取或者网络在线提取的，可以采取打印、拍照或者录音录像等方式固定相关证据，并在笔录中注明原因。 收集、调取的电子数据，足以保证完整性，无删除、修改、增加等情形的，可以作为证据使用。经审查无法确定真伪，或者制作、取得的时间、地点、方式等有疑问，不能提供必要证明或者作出合理解释的，不能作为证据使用。"},{"i":67,"n":"第六十七条","txt":"物证的照片、录像或者复制品，书证的副本、复制件，视听资料、电子数据的复制件，应当附有关制作过程及原件、原物存放处的文字说明，并由制作人和物品持有人或者物品持有单位有关人员签名。"},{"i":68,"n":"第六十八条","txt":"公安机关提请批准逮捕书、起诉意见书必须忠实于事实真象。故意隐瞒事实真象的，应当依法追究责任。"},{"i":69,"n":"第六十九条","txt":"需要查明的案件事实包括： （一）犯罪行为是否存在； （二）实施犯罪行为的时间、地点、手段、后果以及其他情节； （三）犯罪行为是否为犯罪嫌疑人实施； （四）犯罪嫌疑人的身份； （五）犯罪嫌疑人实施犯罪行为的动机、目的； （六）犯罪嫌疑人的责任以及与其他同案人的关系； （七）犯罪嫌疑人有无法定从重、从轻、减轻处罚以及免除处罚的情节； （八）其他与案件有关的事实。"},{"i":70,"n":"第七十条","txt":"公安机关移送审查起诉的案件，应当做到犯罪事实清楚，证据确实、充分。 证据确实、充分，应当符合以下条件： （一）认定的案件事实都有证据证明； （二）认定案件事实的证据均经法定程序查证属实； （三）综合全案证据，对所认定事实已排除合理怀疑。 对证据的审查，应当结合案件的具体情况，从各证据与待证事实的关联程度、各证据之间的联系等方面进行审查判断。 只有犯罪嫌疑人供述，没有其他证据的，不能认定案件事实；没有犯罪嫌疑人供述，证据确实、充分的，可以认定案件事实。"},{"i":71,"n":"第七十一条","txt":"采用刑讯逼供等非法方法收集的犯罪嫌疑人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除。 收集物证、书证、视听资料、电子数据违反法定程序，可能严重影响司法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除。 在侦查阶段发现有应当排除的证据的，经县级以上公安机关负责人批准，应当依法予以排除，不得作为提请批准逮捕、移送审查起诉的依据。 人民检察院认为可能存在以非法方法收集证据情形，要求公安机关进行说明的，公安机关应当及时进行调查，并向人民检察院作出书面说明。"},{"i":72,"n":"第七十二条","txt":"人民法院认为现有证据材料不能证明证据收集的合法性，通知有关侦查人员或者公安机关其他人员出庭说明情况的，有关侦查人员或者其他人员应当出庭。必要时，有关侦查人员或者其他人员也可以要求出庭说明情况。侦查人员或者其他人员出庭，应当向法庭说明证据收集过程，并就相关情况接受发问。 经人民法院通知，人民警察应当就其执行职务时目击的犯罪情况出庭作证。"},{"i":73,"n":"第七十三条","txt":"凡是知道案件情况的人，都有作证的义务。 生理上、精神上有缺陷或者年幼，不能辨别是非，不能正确表达的人，不能作证人。 对于证人能否辨别是非，能否正确表达，必要时可以进行审查或者鉴别。"},{"i":74,"n":"第七十四条","txt":"公安机关应当保障证人及其近亲属的安全。 对证人及其近亲属进行威胁、侮辱、殴打或者打击报复，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予治安管理处罚。"},{"i":75,"n":"第七十五条","txt":"对危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件，证人、鉴定人、被害人因在侦查过程中作证，本人或者其近亲属的人身安全面临危险的，公安机关应当采取以下一项或者多项保护措施： （一）不公开真实姓名、住址、通讯方式和工作单位等个人信息； （二）禁止特定的人员接触被保护人； （三）对被保护人的人身和住宅采取专门性保护措施； （四）将被保护人带到安全场所保护； （五）变更被保护人的住所和姓名； （六）其他必要的保护措施。 证人、鉴定人、被害人认为因在侦查过程中作证，本人或者其近亲属的人身安全面临危险，向公安机关请求予以保护，公安机关经审查认为符合前款规定的条件，确有必要采取保护措施的，应当采取上述一项或者多项保护措施。 公安机关依法采取保护措施，可以要求有关单位和个人配合。 案件移送审查起诉时，应当将采取保护措施的相关情况一并移交人民检察院。"},{"i":76,"n":"第七十六条","txt":"公安机关依法决定不公开证人、鉴定人、被害人的真实姓名、住址、通讯方式和工作单位等个人信息的，可以在起诉意见书、询问笔录等法律文书、证据材料中使用化名等代替证人、鉴定人、被害人的个人信息。但是，应当另行书面说明使用化名的情况并标明密级，单独成卷。"},{"i":77,"n":"第七十七条","txt":"证人保护工作所必需的人员、经费、装备等，应当予以保障。 证人因履行作证义务而支出的交通、住宿、就餐等费用，应当给予补助。证人作证的补助列入公安机关业务经费。"},{"i":78,"n":"第七十八条","txt":"公安机关根据案件情况对需要拘传的犯罪嫌疑人，或者经过传唤没有正当理由不到案的犯罪嫌疑人，可以拘传到其所在市、县公安机关执法办案场所进行讯问。 需要拘传的，应当填写呈请拘传报告书，并附有关材料，报县级以上公安机关负责人批准。"},{"i":79,"n":"第七十九条","txt":"公安机关拘传犯罪嫌疑人应当出示拘传证，并责令其在拘传证上签名、捺指印。 犯罪嫌疑人到案后，应当责令其在拘传证上填写到案时间；拘传结束后，应当由其在拘传证上填写拘传结束时间。犯罪嫌疑人拒绝填写的，侦查人员应当在拘传证上注明。"},{"i":80,"n":"第八十条","txt":"拘传持续的时间不得超过十二小时；案情特别重大、复杂，需要采取拘留、逮捕措施的，经县级以上公安机关负责人批准，拘传持续的时间不得超过二十四小时。不得以连续拘传的形式变相拘禁犯罪嫌疑人。 拘传期限届满，未作出采取其他强制措施决定的，应当立即结束拘传。"},{"i":81,"n":"第八十一条","txt":"公安机关对具有下列情形之一的犯罪嫌疑人，可以取保候审： （一）可能判处管制、拘役或者独立适用附加刑的； （二）可能判处有期徒刑以上刑罚，采取取保候审不致发生社会危险性的； （三）患有严重疾病、生活不能自理，怀孕或者正在哺乳自己婴儿的妇女，采取取保候审不致发生社会危险性的； （四）羁押期限届满，案件尚未办结，需要继续侦查的。 对拘留的犯罪嫌疑人，证据不符合逮捕条件，以及提请逮捕后，人民检察院不批准逮捕，需要继续侦查，并且符合取保候审条件的，可以依法取保候审。"},{"i":82,"n":"第八十二条","txt":"对累犯，犯罪集团的主犯，以自伤、自残办法逃避侦查的犯罪嫌疑人，严重暴力犯罪以及其他严重犯罪的犯罪嫌疑人不得取保候审，但犯罪嫌疑人具有本规定第八十一条第一款第三项、第四项规定情形的除外。"},{"i":83,"n":"第八十三条","txt":"需要对犯罪嫌疑人取保候审的，应当制作呈请取保候审报告书，说明取保候审的理由、采取的保证方式以及应当遵守的规定，经县级以上公安机关负责人批准，制作取保候审决定书。取保候审决定书应当向犯罪嫌疑人宣读，由犯罪嫌疑人签名、捺指印。"},{"i":84,"n":"第八十四条","txt":"公安机关决定对犯罪嫌疑人取保候审的，应当责令犯罪嫌疑人提出保证人或者交纳保证金。 对同一犯罪嫌疑人，不得同时责令其提出保证人和交纳保证金。对未成年人取保候审，应当优先适用保证人保证。"},{"i":85,"n":"第八十五条","txt":"采取保证人保证的，保证人必须符合以下条件，并经公安机关审查同意： （一）与本案无牵连； （二）有能力履行保证义务； （三）享有政治权利，人身自由未受到限制； （四）有固定的住处和收入。"},{"i":86,"n":"第八十六条","txt":"保证人应当履行以下义务： （一）监督被保证人遵守本规定第八十九条、第九十条的规定； （二）发现被保证人可能发生或者已经发生违反本规定第八十九条、第九十条规定的行为的，应当及时向执行机关报告。 保证人应当填写保证书，并在保证书上签名、捺指印。"},{"i":87,"n":"第八十七条","txt":"犯罪嫌疑人的保证金起点数额为人民币一千元。犯罪嫌疑人为未成年人的，保证金起点数额为人民币五百元。具体数额应当综合考虑保证诉讼活动正常进行的需要、犯罪嫌疑人的社会危险性、案件的性质、情节、可能判处刑罚的轻重以及犯罪嫌疑人的经济状况等情况确定。"},{"i":88,"n":"第八十八条","txt":"县级以上公安机关应当在其指定的银行设立取保候审保证金专门账户，委托银行代为收取和保管保证金。 提供保证金的人，应当一次性将保证金存入取保候审保证金专门账户。保证金应当以人民币交纳。 保证金应当由办案部门以外的部门管理。严禁截留、坐支、挪用或者以其他任何形式侵吞保证金。"},{"i":89,"n":"第八十九条","txt":"公安机关在宣布取保候审决定时，应当告知被取保候审人遵守以下规定： （一）未经执行机关批准不得离开所居住的市、县； （二）住址、工作单位和联系方式发生变动的，在二十四小时以内向执行机关报告； （三）在传讯的时候及时到案； （四）不得以任何形式干扰证人作证； （五）不得毁灭、伪造证据或者串供。"},{"i":90,"n":"第九十条","txt":"公安机关在决定取保候审时，还可以根据案件情况，责令被取保候审人遵守以下一项或者多项规定： （一）不得进入与其犯罪活动等相关联的特定场所； （二）不得与证人、被害人及其近亲属、同案犯以及与案件有关联的其他特定人员会见或者以任何方式通信； （三）不得从事与其犯罪行为等相关联的特定活动； （四）将护照等出入境证件、驾驶证件交执行机关保存。 公安机关应当综合考虑案件的性质、情节、社会影响、犯罪嫌疑人的社会关系等因素，确定特定场所、特定人员和特定活动的范围。"},{"i":91,"n":"第九十一条","txt":"公安机关决定取保候审的，应当及时通知被取保候审人居住地的派出所执行。必要时，办案部门可以协助执行。 采取保证人担保形式的，应当同时送交有关法律文书、被取保候审人基本情况、保证人基本情况等材料。采取保证金担保形式的，应当同时送交有关法律文书、被取保候审人基本情况和保证金交纳情况等材料。"},{"i":92,"n":"第九十二条","txt":"人民法院、人民检察院决定取保候审的，负责执行的县级公安机关应当在收到法律文书和有关材料后二十四小时以内，指定被取保候审人居住地派出所核实情况后执行。"},{"i":93,"n":"第九十三条","txt":"执行取保候审的派出所应当履行下列职责： （一）告知被取保候审人必须遵守的规定，及其违反规定或者在取保候审期间重新犯罪应当承担的法律后果； （二）监督、考察被取保候审人遵守有关规定，及时掌握其活动、住址、工作单位、联系方式及变动情况； （三）监督保证人履行保证义务； （四）被取保候审人违反应当遵守的规定以及保证人未履行保证义务的，应当及时制止、采取紧急措施，同时告知决定机关。"},{"i":94,"n":"第九十四条","txt":"执行取保候审的派出所应当定期了解被取保候审人遵守取保候审规定的有关情况，并制作笔录。"},{"i":95,"n":"第九十五条","txt":"被取保候审人无正当理由不得离开所居住的市、县。有正当理由需要离开所居住的市、县的，应当经负责执行的派出所负责人批准。 人民法院、人民检察院决定取保候审的，负责执行的派出所在批准被取保候审人离开所居住的市、县前，应当征得决定取保候审的机关同意。"},{"i":96,"n":"第九十六条","txt":"被取保候审人在取保候审期间违反本规定第八十九条、第九十条规定，已交纳保证金的，公安机关应当根据其违反规定的情节，决定没收部分或者全部保证金，并且区别情形，责令其具结悔过、重新交纳保证金、提出保证人，变更强制措施或者给予治安管理处罚；需要予以逮捕的，可以对其先行拘留。 人民法院、人民检察院决定取保候审的，被取保候审人违反应当遵守的规定，负责执行的派出所应当及时通知决定取保候审的机关。"},{"i":97,"n":"第九十七条","txt":"需要没收保证金的，应当经过严格审核后，报县级以上公安机关负责人批准，制作没收保证金决定书。 决定没收五万元以上保证金的，应当经设区的市一级以上公安机关负责人批准。"},{"i":98,"n":"第九十八条","txt":"没收保证金的决定，公安机关应当在三日以内向被取保候审人宣读，并责令其在没收保证金决定书上签名、捺指印；被取保候审人在逃或者具有其他情形不能到场的，应当向其成年家属、法定代理人、辩护人或者单位、居住地的居民委员会、村民委员会宣布，由其成年家属、法定代理人、辩护人或者单位、居住地的居民委员会或者村民委员会的负责人在没收保证金决定书上签名。 被取保候审人或者其成年家属、法定代理人、辩护人或者单位、居民委员会、村民委员会负责人拒绝签名的，公安机关应当在没收保证金决定书上注明。"},{"i":99,"n":"第九十九条","txt":"公安机关在宣读没收保证金决定书时，应当告知如果对没收保证金的决定不服，被取保候审人或者其法定代理人可以在五日以内向作出决定的公安机关申请复议。公安机关应当在收到复议申请后七日以内作出决定。 被取保候审人或者其法定代理人对复议决定不服的，可以在收到复议决定书后五日以内向上一级公安机关申请复核一次。上一级公安机关应当在收到复核申请后七日以内作出决定。对上级公安机关撤销或者变更没收保证金决定的，下级公安机关应当执行。"},{"i":100,"n":"第一百条","txt":"没收保证金的决定已过复议期限，或者复议、复核后维持原决定或者变更没收保证金数额的，公安机关应当及时通知指定的银行将没收的保证金按照国家的有关规定上缴国库。人民法院、人民检察院决定取保候审的，还应当在三日以内通知决定取保候审的机关。"},{"i":101,"n":"第一百零一条","txt":"被取保候审人在取保候审期间，没有违反本规定第八十九条、第九十条有关规定，也没有重新故意犯罪的，或者具有本规定第一百八十六条规定的情形之一的，在解除取保候审、变更强制措施的同时，公安机关应当制作退还保证金决定书，通知银行如数退还保证金。 被取保候审人可以凭退还保证金决定书到银行领取退还的保证金。被取保候审人委托他人领取的，应当出具委托书。"},{"i":102,"n":"第一百零二条","txt":"被取保候审人没有违反本规定第八十九条、第九十条规定，但在取保候审期间涉嫌重新故意犯罪被立案侦查的，负责执行的公安机关应当暂扣其交纳的保证金，待人民法院判决生效后，根据有关判决作出处理。"},{"i":103,"n":"第一百零三条","txt":"被保证人违反应当遵守的规定，保证人未履行保证义务的，查证属实后，经县级以上公安机关负责人批准，对保证人处一千元以上二万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":104,"n":"第一百零四条","txt":"决定对保证人罚款的，应当报经县级以上公安机关负责人批准，制作对保证人罚款决定书，在三日以内送达保证人，告知其如果对罚款决定不服，可以在收到决定书之日起五日以内向作出决定的公安机关申请复议。公安机关应当在收到复议申请后七日以内作出决定。 保证人对复议决定不服的，可以在收到复议决定书后五日以内向上一级公安机关申请复核一次。上一级公安机关应当在收到复核申请后七日以内作出决定。对上级公安机关撤销或者变更罚款决定的，下级公安机关应当执行。"},{"i":105,"n":"第一百零五条","txt":"对于保证人罚款的决定已过复议期限，或者复议、复核后维持原决定或者变更罚款数额的，公安机关应当及时通知指定的银行将保证人罚款按照国家的有关规定上缴国库。人民法院、人民检察院决定取保候审的，还应当在三日以内通知决定取保候审的机关。"},{"i":106,"n":"第一百零六条","txt":"对于犯罪嫌疑人采取保证人保证的，如果保证人在取保候审期间情况发生变化，不愿继续担保或者丧失担保条件，公安机关应当责令被取保候审人重新提出保证人或者交纳保证金，或者作出变更强制措施的决定。 人民法院、人民检察院决定取保候审的，负责执行的派出所应当自发现保证人不愿继续担保或者丧失担保条件之日起三日以内通知决定取保候审的机关。"},{"i":107,"n":"第一百零七条","txt":"公安机关在取保候审期间不得中断对案件的侦查，对取保候审的犯罪嫌疑人，根据案情变化，应当及时变更强制措施或者解除取保候审。 取保候审最长不得超过十二个月。"},{"i":108,"n":"第一百零八条","txt":"需要解除取保候审的，应当经县级以上公安机关负责人批准，制作解除取保候审决定书、通知书，并及时通知负责执行的派出所、被取保候审人、保证人和有关单位。 人民法院、人民检察院作出解除取保候审决定的，负责执行的公安机关应当根据决定书及时解除取保候审，并通知被取保候审人、保证人和有关单位。"},{"i":109,"n":"第一百零九条","txt":"公安机关对符合逮捕条件，有下列情形之一的犯罪嫌疑人，可以监视居住： （一）患有严重疾病、生活不能自理的； （二）怀孕或者正在哺乳自己婴儿的妇女； （三）系生活不能自理的人的唯一扶养人； （四）因案件的特殊情况或者办理案件的需要，采取监视居住措施更为适宜的； （五）羁押期限届满，案件尚未办结，需要采取监视居住措施的。 对人民检察院决定不批准逮捕的犯罪嫌疑人，需要继续侦查，并且符合监视居住条件的，可以监视居住。 对于符合取保候审条件，但犯罪嫌疑人不能提出保证人，也不交纳保证金的，可以监视居住。 对于被取保候审人违反本规定第八十九条、第九十条规定的，可以监视居住。"},{"i":110,"n":"第一百一十条","txt":"对犯罪嫌疑人监视居住，应当制作呈请监视居住报告书，说明监视居住的理由、采取监视居住的方式以及应当遵守的规定，经县级以上公安机关负责人批准，制作监视居住决定书。监视居住决定书应当向犯罪嫌疑人宣读，由犯罪嫌疑人签名、捺指印。"},{"i":111,"n":"第一百一十一条","txt":"监视居住应当在犯罪嫌疑人、被告人住处执行；无固定住处的，可以在指定的居所执行。对于涉嫌危害国家安全犯罪、恐怖活动犯罪，在住处执行可能有碍侦查的，经上一级公安机关批准，也可以在指定的居所执行。 有下列情形之一的，属于本条规定的“有碍侦查”： （一）可能毁灭、伪造证据，干扰证人作证或者串供的； （二）可能引起犯罪嫌疑人自残、自杀或者逃跑的； （三）可能引起同案犯逃避、妨碍侦查的； （四）犯罪嫌疑人、被告人在住处执行监视居住有人身危险的； （五）犯罪嫌疑人、被告人的家属或者所在单位人员与犯罪有牵连的。 指定居所监视居住的，不得要求被监视居住人支付费用。"},{"i":112,"n":"第一百一十二条","txt":"固定住处，是指被监视居住人在办案机关所在的市、县内生活的合法住处；指定的居所，是指公安机关根据案件情况，在办案机关所在的市、县内为被监视居住人指定的生活居所。 指定的居所应当符合下列条件： （一）具备正常的生活、休息条件； （二）便于监视、管理； （三）保证安全。 公安机关不得在羁押场所、专门的办案场所或者办公场所执行监视居住。"},{"i":113,"n":"第一百一十三条","txt":"指定居所监视居住的，除无法通知的以外，应当制作监视居住通知书，在执行监视居住后二十四小时以内，由决定机关通知被监视居住人的家属。 有下列情形之一的，属于本条规定的“无法通知”： （一）不讲真实姓名、住址、身份不明的； （二）没有家属的； （三）提供的家属联系方式无法取得联系的； （四）因自然灾害等不可抗力导致无法通知的。 无法通知的情形消失以后，应当立即通知被监视居住人的家属。 无法通知家属的，应当在监视居住通知书中注明原因。"},{"i":114,"n":"第一百一十四条","txt":"被监视居住人委托辩护律师，适用本规定第四十三条、第四十四条、第四十五条规定。"},{"i":115,"n":"第一百一十五条","txt":"公安机关在宣布监视居住决定时，应当告知被监视居住人必须遵守以下规定： （一）未经执行机关批准不得离开执行监视居住的处所； （二）未经执行机关批准不得会见他人或者以任何方式通信； （三）在传讯的时候及时到案； （四）不得以任何形式干扰证人作证； （五）不得毁灭、伪造证据或者串供； （六）将护照等出入境证件、身份证件、驾驶证件交执行机关保存。"},{"i":116,"n":"第一百一十六条","txt":"公安机关对被监视居住人，可以采取电子监控、不定期检查等监视方法对其遵守监视居住规定的情况进行监督；在侦查期间，可以对被监视居住的犯罪嫌疑人的电话、传真、信函、邮件、网络等通信进行监控。"},{"i":117,"n":"第一百一十七条","txt":"公安机关决定监视居住的，由被监视居住人住处或者指定居所所在地的派出所执行，办案部门可以协助执行。必要时，也可以由办案部门负责执行，派出所或者其他部门协助执行。"},{"i":118,"n":"第一百一十八条","txt":"人民法院、人民检察院决定监视居住的，负责执行的县级公安机关应当在收到法律文书和有关材料后二十四小时以内，通知被监视居住人住处或者指定居所所在地的派出所，核实被监视居住人身份、住处或者居所等情况后执行。必要时，可以由人民法院、人民检察院协助执行。 负责执行的派出所应当及时将执行情况通知决定监视居住的机关。"},{"i":119,"n":"第一百一十九条","txt":"负责执行监视居住的派出所或者办案部门应当严格对被监视居住人进行监督考察，确保安全。"},{"i":120,"n":"第一百二十条","txt":"被监视居住人有正当理由要求离开住处或者指定的居所以及要求会见他人或者通信的，应当经负责执行的派出所或者办案部门负责人批准。 人民法院、人民检察院决定监视居住的，负责执行的派出所在批准被监视居住人离开住处或者指定的居所以及与他人会见或者通信前，应当征得决定监视居住的机关同意。"},{"i":121,"n":"第一百二十一条","txt":"被监视居住人违反应当遵守的规定，公安机关应当区分情形责令被监视居住人具结悔过或者给予治安管理处罚。情节严重的，可以予以逮捕；需要予以逮捕的，可以对其先行拘留。 人民法院、人民检察院决定监视居住的，被监视居住人违反应当遵守的规定，负责执行的派出所应当及时通知决定监视居住的机关。"},{"i":122,"n":"第一百二十二条","txt":"在监视居住期间，公安机关不得中断案件的侦查，对被监视居住的犯罪嫌疑人，应当根据案情变化，及时解除监视居住或者变更强制措施。 监视居住最长不得超过六个月。"},{"i":123,"n":"第一百二十三条","txt":"需要解除监视居住的，应当经县级以上公安机关负责人批准，制作解除监视居住决定书，并及时通知负责执行的派出所、被监视居住人和有关单位。 人民法院、人民检察院作出解除、变更监视居住决定的，负责执行的公安机关应当及时解除并通知被监视居住人和有关单位。"},{"i":124,"n":"第一百二十四条","txt":"公安机关对于现行犯或者重大嫌疑分子，有下列情形之一的，可以先行拘留： （一）正在预备犯罪、实行犯罪或者在犯罪后即时被发觉的； （二）被害人或者在场亲眼看见的人指认他犯罪的； （三）在身边或者住处发现有犯罪证据的； （四）犯罪后企图自杀、逃跑或者在逃的； （五）有毁灭、伪造证据或者串供可能的； （六）不讲真实姓名、住址，身份不明的； （七）有流窜作案、多次作案、结伙作案重大嫌疑的。"},{"i":125,"n":"第一百二十五条","txt":"拘留犯罪嫌疑人，应当填写呈请拘留报告书，经县级以上公安机关负责人批准，制作拘留证。执行拘留时，必须出示拘留证，并责令被拘留人在拘留证上签名、捺指印，拒绝签名、捺指印的，侦查人员应当注明。 紧急情况下，对于符合本规定第一百二十四条所列情形之一的，经出示人民警察证，可以将犯罪嫌疑人口头传唤至公安机关后立即审查，办理法律手续。"},{"i":126,"n":"第一百二十六条","txt":"拘留后，应当立即将被拘留人送看守所羁押，至迟不得超过二十四小时。 异地执行拘留，无法及时将犯罪嫌疑人押解回管辖地的，应当在宣布拘留后立即将其送抓获地看守所羁押，至迟不得超过二十四小时。到达管辖地后，应当立即将犯罪嫌疑人送看守所羁押。"},{"i":127,"n":"第一百二十七条","txt":"除无法通知或者涉嫌危害国家安全犯罪、恐怖活动犯罪通知可能有碍侦查的情形以外，应当在拘留后二十四小时以内制作拘留通知书，通知被拘留人的家属。拘留通知书应当写明拘留原因和羁押处所。 本条规定的“无法通知”的情形适用本规定第一百一十三条第二款的规定。 有下列情形之一的，属于本条规定的“有碍侦查”： （一）可能毁灭、伪造证据，干扰证人作证或者串供的； （二）可能引起同案犯逃避、妨碍侦查的； （三）犯罪嫌疑人的家属与犯罪有牵连的。 无法通知、有碍侦查的情形消失以后，应当立即通知被拘留人的家属。 对于没有在二十四小时以内通知家属的，应当在拘留通知书中注明原因。"},{"i":128,"n":"第一百二十八条","txt":"对被拘留的人，应当在拘留后二十四小时以内进行讯问。发现不应当拘留的，应当经县级以上公安机关负责人批准，制作释放通知书，看守所凭释放通知书发给被拘留人释放证明书，将其立即释放。"},{"i":129,"n":"第一百二十九条","txt":"对被拘留的犯罪嫌疑人，经过审查认为需要逮捕的，应当在拘留后的三日以内，提请人民检察院审查批准。在特殊情况下，经县级以上公安机关负责人批准，提请审查批准逮捕的时间可以延长一日至四日。 对流窜作案、多次作案、结伙作案的重大嫌疑分子，经县级以上公安机关负责人批准，提请审查批准逮捕的时间可以延长至三十日。 本条规定的“流窜作案”，是指跨市、县管辖范围连续作案，或者在居住地作案后逃跑到外市、县继续作案；“多次作案”，是指三次以上作案；“结伙作案”，是指二人以上共同作案。"},{"i":130,"n":"第一百三十条","txt":"犯罪嫌疑人不讲真实姓名、住址，身份不明的，应当对其身份进行调查。对符合逮捕条件的犯罪嫌疑人，也可以按其自报的姓名提请批准逮捕。"},{"i":131,"n":"第一百三十一条","txt":"对被拘留的犯罪嫌疑人审查后，根据案件情况报经县级以上公安机关负责人批准，分别作出如下处理： （一）需要逮捕的，在拘留期限内，依法办理提请批准逮捕手续； （二）应当追究刑事责任，但不需要逮捕的，依法直接向人民检察院移送审查起诉，或者依法办理取保候审或者监视居住手续后，向人民检察院移送审查起诉； （三）拘留期限届满，案件尚未办结，需要继续侦查的，依法办理取保候审或者监视居住手续； （四）具有本规定第一百八十六条规定情形之一的，释放被拘留人，发给释放证明书；需要行政处理的，依法予以处理或者移送有关部门。"},{"i":132,"n":"第一百三十二条","txt":"人民检察院决定拘留犯罪嫌疑人的，由县级以上公安机关凭人民检察院送达的决定拘留的法律文书制作拘留证并立即执行。必要时，可以请人民检察院协助。拘留后，应当及时通知人民检察院。 公安机关未能抓获犯罪嫌疑人的，应当将执行情况和未能抓获犯罪嫌疑人的原因通知作出拘留决定的人民检察院。对于犯罪嫌疑人在逃的，在人民检察院撤销拘留决定之前，公安机关应当组织力量继续执行。"},{"i":133,"n":"第一百三十三条","txt":"对有证据证明有犯罪事实，可能判处徒刑以上刑罚的犯罪嫌疑人，采取取保候审尚不足以防止发生下列社会危险性的，应当提请批准逮捕： （一）可能实施新的犯罪的； （二）有危害国家安全、公共安全或者社会秩序的现实危险的； （三）可能毁灭、伪造证据，干扰证人作证或者串供的； （四）可能对被害人、举报人、控告人实施打击报复的； （五）企图自杀或者逃跑的。 对于有证据证明有犯罪事实，可能判处十年有期徒刑以上刑罚的，或者有证据证明有犯罪事实，可能判处徒刑以上刑罚，曾经故意犯罪或者身份不明的，应当提请批准逮捕。 公安机关在根据第一款的规定提请人民检察院审查批准逮捕时，应当对犯罪嫌疑人具有社会危险性说明理由。"},{"i":134,"n":"第一百三十四条","txt":"有证据证明有犯罪事实，是指同时具备下列情形： （一）有证据证明发生了犯罪事实； （二）有证据证明该犯罪事实是犯罪嫌疑人实施的； （三）证明犯罪嫌疑人实施犯罪行为的证据已有查证属实的。 前款规定的“犯罪事实”既可以是单一犯罪行为的事实，也可以是数个犯罪行为中任何一个犯罪行为的事实。"},{"i":135,"n":"第一百三十五条","txt":"被取保候审人违反取保候审规定，具有下列情形之一的，可以提请批准逮捕： （一）涉嫌故意实施新的犯罪行为的； （二）有危害国家安全、公共安全或者社会秩序的现实危险的； （三）实施毁灭、伪造证据或者干扰证人作证、串供行为，足以影响侦查工作正常进行的； （四）对被害人、举报人、控告人实施打击报复的； （五）企图自杀、逃跑，逃避侦查的； （六）未经批准，擅自离开所居住的市、县，情节严重的，或者两次以上未经批准，擅自离开所居住的市、县的； （七）经传讯无正当理由不到案，情节严重的，或者经两次以上传讯不到案的； （八）违反规定进入特定场所、从事特定活动或者与特定人员会见、通信两次以上的。"},{"i":136,"n":"第一百三十六条","txt":"被监视居住人违反监视居住规定，具有下列情形之一的，可以提请批准逮捕： （一）涉嫌故意实施新的犯罪行为的； （二）实施毁灭、伪造证据或者干扰证人作证、串供行为，足以影响侦查工作正常进行的； （三）对被害人、举报人、控告人实施打击报复的； （四）企图自杀、逃跑，逃避侦查的； （五）未经批准，擅自离开执行监视居住的处所，情节严重的，或者两次以上未经批准，擅自离开执行监视居住的处所的； （六）未经批准，擅自会见他人或者通信，情节严重的，或者两次以上未经批准，擅自会见他人或者通信的； （七）经传讯无正当理由不到案，情节严重的，或者经两次以上传讯不到案的。"},{"i":137,"n":"第一百三十七条","txt":"需要提请批准逮捕犯罪嫌疑人的，应当经县级以上公安机关负责人批准，制作提请批准逮捕书，连同案卷材料、证据，一并移送同级人民检察院审查批准。 犯罪嫌疑人自愿认罪认罚的，应当记录在案，并在提请批准逮捕书中写明有关情况。"},{"i":138,"n":"第一百三十八条","txt":"对于人民检察院不批准逮捕并通知补充侦查的，公安机关应当按照人民检察院的补充侦查提纲补充侦查。 公安机关补充侦查完毕，认为符合逮捕条件的，应当重新提请批准逮捕。"},{"i":139,"n":"第一百三十九条","txt":"对于人民检察院不批准逮捕而未说明理由的，公安机关可以要求人民检察院说明理由。"},{"i":140,"n":"第一百四十条","txt":"对于人民检察院决定不批准逮捕的，公安机关在收到不批准逮捕决定书后，如果犯罪嫌疑人已被拘留的，应当立即释放，发给释放证明书，并在执行完毕后三日以内将执行回执送达作出不批准逮捕决定的人民检察院。"},{"i":141,"n":"第一百四十一条","txt":"对人民检察院不批准逮捕的决定，认为有错误需要复议的，应当在收到不批准逮捕决定书后五日以内制作要求复议意见书，报经县级以上公安机关负责人批准后，送交同级人民检察院复议。 如果意见不被接受，认为需要复核的，应当在收到人民检察院的复议决定书后五日以内制作提请复核意见书，报经县级以上公安机关负责人批准后，连同人民检察院的复议决定书，一并提请上一级人民检察院复核。"},{"i":142,"n":"第一百四十二条","txt":"接到人民检察院批准逮捕决定书后，应当由县级以上公安机关负责人签发逮捕证，立即执行，并在执行完毕后三日以内将执行回执送达作出批准逮捕决定的人民检察院。如果未能执行，也应当将回执送达人民检察院，并写明未能执行的原因。"},{"i":143,"n":"第一百四十三条","txt":"执行逮捕时，必须出示逮捕证，并责令被逮捕人在逮捕证上签名、捺指印，拒绝签名、捺指印的，侦查人员应当注明。逮捕后，应当立即将被逮捕人送看守所羁押。 执行逮捕的侦查人员不得少于二人。"},{"i":144,"n":"第一百四十四条","txt":"对被逮捕的人，必须在逮捕后的二十四小时以内进行讯问。发现不应当逮捕的，经县级以上公安机关负责人批准，制作释放通知书，送看守所和原批准逮捕的人民检察院。看守所凭释放通知书立即释放被逮捕人，并发给释放证明书。"},{"i":145,"n":"第一百四十五条","txt":"对犯罪嫌疑人执行逮捕后，除无法通知的情形以外，应当在逮捕后二十四小时以内，制作逮捕通知书，通知被逮捕人的家属。逮捕通知书应当写明逮捕原因和羁押处所。 本条规定的“无法通知”的情形适用本规定第一百一十三条第二款的规定。 无法通知的情形消除后，应当立即通知被逮捕人的家属。 对于没有在二十四小时以内通知家属的，应当在逮捕通知书中注明原因。"},{"i":146,"n":"第一百四十六条","txt":"人民法院、人民检察院决定逮捕犯罪嫌疑人、被告人的，由县级以上公安机关凭人民法院、人民检察院决定逮捕的法律文书制作逮捕证并立即执行。必要时，可以请人民法院、人民检察院协助执行。执行逮捕后，应当及时通知决定机关。 公安机关未能抓获犯罪嫌疑人、被告人的，应当将执行情况和未能抓获的原因通知决定逮捕的人民检察院、人民法院。对于犯罪嫌疑人、被告人在逃的，在人民检察院、人民法院撤销逮捕决定之前，公安机关应当组织力量继续执行。"},{"i":147,"n":"第一百四十七条","txt":"人民检察院在审查批准逮捕工作中发现公安机关的侦查活动存在违法情况，通知公安机关予以纠正的，公安机关应当调查核实，对于发现的违法情况应当及时纠正，并将纠正情况书面通知人民检察院。"},{"i":148,"n":"第一百四十八条","txt":"对犯罪嫌疑人逮捕后的侦查羁押期限不得超过二个月。案情复杂、期限届满不能侦查终结的案件，应当制作提请批准延长侦查羁押期限意见书，经县级以上公安机关负责人批准后，在期限届满七日前送请同级人民检察院转报上一级人民检察院批准延长一个月。"},{"i":149,"n":"第一百四十九条","txt":"下列案件在本规定第一百四十八条规定的期限届满不能侦查终结的，应当制作提请批准延长侦查羁押期限意见书，经县级以上公安机关负责人批准，在期限届满七日前送请同级人民检察院层报省、自治区、直辖市人民检察院批准，延长二个月： （一）交通十分不便的边远地区的重大复杂案件； （二）重大的犯罪集团案件； （三）流窜作案的重大复杂案件； （四）犯罪涉及面广，取证困难的重大复杂案件。"},{"i":150,"n":"第一百五十条","txt":"对犯罪嫌疑人可能判处十年有期徒刑以上刑罚，依照本规定第一百四十九条规定的延长期限届满，仍不能侦查终结的，应当制作提请批准延长侦查羁押期限意见书，经县级以上公安机关负责人批准，在期限届满七日前送请同级人民检察院层报省、自治区、直辖市人民检察院批准，再延长二个月。"},{"i":151,"n":"第一百五十一条","txt":"在侦查期间，发现犯罪嫌疑人另有重要罪行的，应当自发现之日起五日以内报县级以上公安机关负责人批准后，重新计算侦查羁押期限，制作变更羁押期限通知书，送达看守所，并报批准逮捕的人民检察院备案。 前款规定的“另有重要罪行”，是指与逮捕时的罪行不同种的重大犯罪以及同种犯罪并将影响罪名认定、量刑档次的重大犯罪。"},{"i":152,"n":"第一百五十二条","txt":"犯罪嫌疑人不讲真实姓名、住址，身份不明的，应当对其身份进行调查。经县级以上公安机关负责人批准，侦查羁押期限自查清其身份之日起计算，但不得停止对其犯罪行为的侦查取证。 对于犯罪事实清楚，证据确实、充分，确实无法查明其身份的，按其自报的姓名移送人民检察院审查起诉。"},{"i":153,"n":"第一百五十三条","txt":"看守所应当凭公安机关签发的拘留证、逮捕证收押被拘留、逮捕的犯罪嫌疑人、被告人。犯罪嫌疑人、被告人被送至看守所羁押时，看守所应当在拘留证、逮捕证上注明犯罪嫌疑人、被告人到达看守所的时间。 查获被通缉、脱逃的犯罪嫌疑人以及执行追捕、押解任务需要临时寄押的，应当持通缉令或者其他有关法律文书并经寄押地县级以上公安机关负责人批准，送看守所寄押。 临时寄押的犯罪嫌疑人出所时，看守所应当出具羁押该犯罪嫌疑人的证明，载明该犯罪嫌疑人基本情况、羁押原因、入所和出所时间。"},{"i":154,"n":"第一百五十四条","txt":"看守所收押犯罪嫌疑人、被告人和罪犯，应当进行健康和体表检查，并予以记录。"},{"i":155,"n":"第一百五十五条","txt":"看守所收押犯罪嫌疑人、被告人和罪犯，应当对其人身和携带的物品进行安全检查。发现违禁物品、犯罪证据和可疑物品，应当制作笔录，由被羁押人签名、捺指印后，送办案机关处理。 对女性的人身检查，应当由女工作人员进行。"},{"i":156,"n":"第一百五十六条","txt":"继续盘问期间发现需要对犯罪嫌疑人拘留、逮捕、取保候审或者监视居住的，应当立即办理法律手续。"},{"i":157,"n":"第一百五十七条","txt":"对犯罪嫌疑人执行拘传、拘留、逮捕、押解过程中，应当依法使用约束性警械。遇有暴力性对抗或者暴力犯罪行为，可以依法使用制服性警械或者武器。"},{"i":158,"n":"第一百五十八条","txt":"公安机关发现对犯罪嫌疑人采取强制措施不当的，应当及时撤销或者变更。犯罪嫌疑人在押的，应当及时释放。公安机关释放被逮捕的人或者变更逮捕措施的，应当通知批准逮捕的人民检察院。"},{"i":159,"n":"第一百五十九条","txt":"犯罪嫌疑人被逮捕后，人民检察院经审查认为不需要继续羁押，建议予以释放或者变更强制措施的，公安机关应当予以调查核实。认为不需要继续羁押的，应当予以释放或者变更强制措施；认为需要继续羁押的，应当说明理由。 公安机关应当在十日以内将处理情况通知人民检察院。"},{"i":160,"n":"第一百六十条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人有权申请变更强制措施。公安机关应当在收到申请后三日以内作出决定；不同意变更强制措施的，应当告知申请人，并说明理由。"},{"i":161,"n":"第一百六十一条","txt":"公安机关对被采取强制措施法定期限届满的犯罪嫌疑人，应当予以释放，解除取保候审、监视居住或者依法变更强制措施。 犯罪嫌疑人及其法定代理人、近亲属或者辩护人对于公安机关采取强制措施法定期限届满的，有权要求公安机关解除强制措施。公安机关应当进行审查，对于情况属实的，应当立即解除或者变更强制措施。 对于犯罪嫌疑人、被告人羁押期限即将届满的，看守所应当立即通知办案机关。"},{"i":162,"n":"第一百六十二条","txt":"取保候审变更为监视居住的，取保候审、监视居住变更为拘留、逮捕的，对原强制措施不再办理解除法律手续。"},{"i":163,"n":"第一百六十三条","txt":"案件在取保候审、监视居住期间移送审查起诉后，人民检察院决定重新取保候审、监视居住或者变更强制措施的，对原强制措施不再办理解除法律手续。"},{"i":164,"n":"第一百六十四条","txt":"公安机关依法对县级以上各级人民代表大会代表拘传、取保候审、监视居住、拘留或者提请批准逮捕的，应当书面报请该代表所属的人民代表大会主席团或者常务委员会许可。"},{"i":165,"n":"第一百六十五条","txt":"公安机关对现行犯拘留的时候，发现其是县级以上人民代表大会代表的，应当立即向其所属的人民代表大会主席团或者常务委员会报告。 公安机关在依法执行拘传、取保候审、监视居住、拘留或者逮捕中，发现被执行人是县级以上人民代表大会代表的，应当暂缓执行，并报告决定或者批准机关。如果在执行后发现被执行人是县级以上人民代表大会代表的，应当立即解除，并报告决定或者批准机关。"},{"i":166,"n":"第一百六十六条","txt":"公安机关依法对乡、民族乡、镇的人民代表大会代表拘传、取保候审、监视居住、拘留或者执行逮捕的，应当在执行后立即报告其所属的人民代表大会。"},{"i":167,"n":"第一百六十七条","txt":"公安机关依法对政治协商委员会委员拘传、取保候审、监视居住的，应当将有关情况通报给该委员所属的政协组织。"},{"i":168,"n":"第一百六十八条","txt":"公安机关依法对政治协商委员会委员执行拘留、逮捕前，应当向该委员所属的政协组织通报情况；情况紧急的，可在执行的同时或者执行以后及时通报。"},{"i":169,"n":"第一百六十九条","txt":"公安机关对于公民扭送、报案、控告、举报或者犯罪嫌疑人自动投案的，都应当立即接受，问明情况，并制作笔录，经核对无误后，由扭送人、报案人、控告人、举报人、投案人签名、捺指印。必要时，应当对接受过程录音录像。"},{"i":170,"n":"第一百七十条","txt":"公安机关对扭送人、报案人、控告人、举报人、投案人提供的有关证据材料等应当登记，制作接受证据材料清单，由扭送人、报案人、控告人、举报人、投案人签名，并妥善保管。必要时，应当拍照或者录音录像。"},{"i":171,"n":"第一百七十一条","txt":"公安机关接受案件时，应当制作受案登记表和受案回执，并将受案回执交扭送人、报案人、控告人、举报人。扭送人、报案人、控告人、举报人无法取得联系或者拒绝接受回执的，应当在回执中注明。"},{"i":172,"n":"第一百七十二条","txt":"公安机关接受控告、举报的工作人员，应当向控告人、举报人说明诬告应负的法律责任。但是，只要不是捏造事实、伪造证据，即使控告、举报的事实有出入，甚至是错告的，也要和诬告严格加以区别。"},{"i":173,"n":"第一百七十三条","txt":"公安机关应当保障扭送人、报案人、控告人、举报人及其近亲属的安全。 扭送人、报案人、控告人、举报人如果不愿意公开自己的身份，应当为其保守秘密，并在材料中注明。"},{"i":174,"n":"第一百七十四条","txt":"对接受的案件，或者发现的犯罪线索，公安机关应当迅速进行审查。发现案件事实或者线索不明的，必要时，经办案部门负责人批准，可以进行调查核实。 调查核实过程中，公安机关可以依照有关法律和规定采取询问、查询、勘验、鉴定和调取证据材料等不限制被调查对象人身、财产权利的措施。但是，不得对被调查对象采取强制措施，不得查封、扣押、冻结被调查对象的财产，不得采取技术侦查措施。"},{"i":175,"n":"第一百七十五条","txt":"经过审查，认为有犯罪事实，但不属于自己管辖的案件，应当立即报经县级以上公安机关负责人批准，制作移送案件通知书，在二十四小时以内移送有管辖权的机关处理，并告知扭送人、报案人、控告人、举报人。对于不属于自己管辖而又必须采取紧急措施的，应当先采取紧急措施，然后办理手续，移送主管机关。 对不属于公安机关职责范围的事项，在接报案时能够当场判断的，应当立即口头告知扭送人、报案人、控告人、举报人向其他主管机关报案。 对于重复报案、案件正在办理或者已经办结的，应当向扭送人、报案人、控告人、举报人作出解释，不再登记，但有新的事实或者证据的除外。"},{"i":176,"n":"第一百七十六条","txt":"经过审查，对告诉才处理的案件，公安机关应当告知当事人向人民法院起诉。 对被害人有证据证明的轻微刑事案件，公安机关应当告知被害人可以向人民法院起诉；被害人要求公安机关处理的，公安机关应当依法受理。 人民法院审理自诉案件，依法调取公安机关已经收集的案件材料和有关证据的，公安机关应当及时移交。"},{"i":177,"n":"第一百七十七条","txt":"经过审查，对于不够刑事处罚需要给予行政处理的，依法予以处理或者移送有关部门。"},{"i":178,"n":"第一百七十八条","txt":"公安机关接受案件后，经审查，认为有犯罪事实需要追究刑事责任，且属于自己管辖的，经县级以上公安机关负责人批准，予以立案；认为没有犯罪事实，或者犯罪事实显著轻微不需要追究刑事责任，或者具有其他依法不追究刑事责任情形的，经县级以上公安机关负责人批准，不予立案。 对有控告人的案件，决定不予立案的，公安机关应当制作不予立案通知书，并在三日以内送达控告人。 决定不予立案后又发现新的事实或者证据，或者发现原认定事实错误，需要追究刑事责任的，应当及时立案处理。"},{"i":179,"n":"第一百七十九条","txt":"控告人对不予立案决定不服的，可以在收到不予立案通知书后七日以内向作出决定的公安机关申请复议；公安机关应当在收到复议申请后三十日以内作出决定，并将决定书送达控告人。 控告人对不予立案的复议决定不服的，可以在收到复议决定书后七日以内向上一级公安机关申请复核；上一级公安机关应当在收到复核申请后三十日以内作出决定。对上级公安机关撤销不予立案决定的，下级公安机关应当执行。 案情重大、复杂的，公安机关可以延长复议、复核时限，但是延长时限不得超过三十日，并书面告知申请人。"},{"i":180,"n":"第一百八十条","txt":"对行政执法机关移送的案件，公安机关应当自接受案件之日起三日以内进行审查，认为有犯罪事实，需要追究刑事责任，依法决定立案的，应当书面通知移送案件的行政执法机关；认为没有犯罪事实，或者犯罪事实显著轻微，不需要追究刑事责任，依法不予立案的，应当说明理由，并将不予立案通知书送达移送案件的行政执法机关，相应退回案件材料。 公安机关认为行政执法机关移送的案件材料不全的，应当在接受案件后二十四小时以内通知移送案件的行政执法机关在三日以内补正，但不得以材料不全为由不接受移送案件。 公安机关认为行政执法机关移送的案件不属于公安机关职责范围的，应当书面通知移送案件的行政执法机关向其他主管机关移送案件，并说明理由。"},{"i":181,"n":"第一百八十一条","txt":"移送案件的行政执法机关对不予立案决定不服的，可以在收到不予立案通知书后三日以内向作出决定的公安机关申请复议；公安机关应当在收到行政执法机关的复议申请后三日以内作出决定，并书面通知移送案件的行政执法机关。"},{"i":182,"n":"第一百八十二条","txt":"对人民检察院要求说明不立案理由的案件，公安机关应当在收到通知书后七日以内，对不立案的情况、依据和理由作出书面说明，回复人民检察院。公安机关作出立案决定的，应当将立案决定书复印件送达人民检察院。 人民检察院通知公安机关立案的，公安机关应当在收到通知书后十五日以内立案，并将立案决定书复印件送达人民检察院。"},{"i":183,"n":"第一百八十三条","txt":"人民检察院认为公安机关不应当立案而立案，提出纠正意见的，公安机关应当进行调查核实，并将有关情况回复人民检察院。"},{"i":184,"n":"第一百八十四条","txt":"经立案侦查，认为有犯罪事实需要追究刑事责任，但不属于自己管辖或者需要由其他公安机关并案侦查的案件，经县级以上公安机关负责人批准，制作移送案件通知书，移送有管辖权的机关或者并案侦查的公安机关，并在移送案件后三日以内书面通知扭送人、报案人、控告人、举报人或者移送案件的行政执法机关；犯罪嫌疑人已经到案的，应当依照本规定的有关规定通知其家属。"},{"i":185,"n":"第一百八十五条","txt":"案件变更管辖或者移送其他公安机关并案侦查时，与案件有关的法律文书、证据、财物及其孳息等应当随案移交。 移交时，由接收人、移交人当面查点清楚，并在交接单据上共同签名。"},{"i":186,"n":"第一百八十六条","txt":"经过侦查，发现具有下列情形之一的，应当撤销案件： （一）没有犯罪事实的； （二）情节显著轻微、危害不大，不认为是犯罪的； （三）犯罪已过追诉时效期限的； （四）经特赦令免除刑罚的； （五）犯罪嫌疑人死亡的； （六）其他依法不追究刑事责任的。 对于经过侦查，发现有犯罪事实需要追究刑事责任，但不是被立案侦查的犯罪嫌疑人实施的，或者共同犯罪案件中部分犯罪嫌疑人不够刑事处罚的，应当对有关犯罪嫌疑人终止侦查，并对该案件继续侦查。"},{"i":187,"n":"第一百八十七条","txt":"需要撤销案件或者对犯罪嫌疑人终止侦查的，办案部门应当制作撤销案件或者终止侦查报告书，报县级以上公安机关负责人批准。 公安机关决定撤销案件或者对犯罪嫌疑人终止侦查时，原犯罪嫌疑人在押的，应当立即释放，发给释放证明书。原犯罪嫌疑人被逮捕的，应当通知原批准逮捕的人民检察院。对原犯罪嫌疑人采取其他强制措施的，应当立即解除强制措施；需要行政处理的，依法予以处理或者移交有关部门。 对查封、扣押的财物及其孳息、文件，或者冻结的财产，除按照法律和有关规定另行处理的以外，应当解除查封、扣押、冻结，并及时返还或者通知当事人。"},{"i":188,"n":"第一百八十八条","txt":"犯罪嫌疑人自愿如实供述涉嫌犯罪的事实，有重大立功或者案件涉及国家重大利益，需要撤销案件的，应当层报公安部，由公安部商请最高人民检察院核准后撤销案件。报请撤销案件的公安机关应当同时将相关情况通报同级人民检察院。 公安机关根据前款规定撤销案件的，应当对查封、扣押、冻结的财物及其孳息作出处理。"},{"i":189,"n":"第一百八十九条","txt":"公安机关作出撤销案件决定后，应当在三日以内告知原犯罪嫌疑人、被害人或者其近亲属、法定代理人以及案件移送机关。 公安机关作出终止侦查决定后，应当在三日以内告知原犯罪嫌疑人。"},{"i":190,"n":"第一百九十条","txt":"公安机关撤销案件以后又发现新的事实或者证据，或者发现原认定事实错误，认为有犯罪事实需要追究刑事责任的，应当重新立案侦查。 对犯罪嫌疑人终止侦查后又发现新的事实或者证据，或者发现原认定事实错误，需要对其追究刑事责任的，应当继续侦查。"},{"i":191,"n":"第一百九十一条","txt":"公安机关对已经立案的刑事案件，应当及时进行侦查，全面、客观地收集、调取犯罪嫌疑人有罪或者无罪、罪轻或者罪重的证据材料。"},{"i":192,"n":"第一百九十二条","txt":"公安机关经过侦查，对有证据证明有犯罪事实的案件，应当进行预审，对收集、调取的证据材料的真实性、合法性、关联性及证明力予以审查、核实。"},{"i":193,"n":"第一百九十三条","txt":"公安机关侦查犯罪，应当严格依照法律规定的条件和程序采取强制措施和侦查措施，严禁在没有证据的情况下，仅凭怀疑就对犯罪嫌疑人采取强制措施和侦查措施。"},{"i":194,"n":"第一百九十四条","txt":"公安机关开展勘验、检查、搜查、辨认、查封、扣押等侦查活动，应当邀请有关公民作为见证人。 下列人员不得担任侦查活动的见证人： （一）生理上、精神上有缺陷或者年幼，不具有相应辨别能力或者不能正确表达的人； （二）与案件有利害关系，可能影响案件公正处理的人； （三）公安机关的工作人员或者其聘用的人员。 确因客观原因无法由符合条件的人员担任见证人的，应当对有关侦查活动进行全程录音录像，并在笔录中注明有关情况。"},{"i":195,"n":"第一百九十五条","txt":"公安机关侦查犯罪，涉及国家秘密、商业秘密、个人隐私的，应当保密。"},{"i":196,"n":"第一百九十六条","txt":"当事人和辩护人、诉讼代理人、利害关系人对于公安机关及其侦查人员有下列行为之一的，有权向该机关申诉或者控告： （一）采取强制措施法定期限届满，不予以释放、解除或者变更的； （二）应当退还取保候审保证金不退还的； （三）对与案件无关的财物采取查封、扣押、冻结措施的； （四）应当解除查封、扣押、冻结不解除的； （五）贪污、挪用、私分、调换、违反规定使用查封、扣押、冻结的财物的。 受理申诉或者控告的公安机关应当及时进行调查核实，并在收到申诉、控告之日起三十日以内作出处理决定，书面回复申诉人、控告人。发现公安机关及其侦查人员有上述行为之一的，应当立即纠正。"},{"i":197,"n":"第一百九十七条","txt":"上级公安机关发现下级公安机关存在本规定第一百九十六条第一款规定的违法行为或者对申诉、控告事项不按照规定处理的，应当责令下级公安机关限期纠正，下级公安机关应当立即执行。必要时，上级公安机关可以就申诉、控告事项直接作出处理决定。"},{"i":198,"n":"第一百九十八条","txt":"讯问犯罪嫌疑人，除下列情形以外，应当在公安机关执法办案场所的讯问室进行： （一）紧急情况下在现场进行讯问的； （二）对有严重伤病或者残疾、行动不便的，以及正在怀孕的犯罪嫌疑人，在其住处或者就诊的医疗机构进行讯问的。 对于已送交看守所羁押的犯罪嫌疑人，应当在看守所讯问室进行讯问。 对于正在被执行行政拘留、强制隔离戒毒的人员以及正在监狱服刑的罪犯，可以在其执行场所进行讯问。 对于不需要拘留、逮捕的犯罪嫌疑人，经办案部门负责人批准，可以传唤到犯罪嫌疑人所在市、县公安机关执法办案场所或者到他的住处进行讯问。"},{"i":199,"n":"第一百九十九条","txt":"传唤犯罪嫌疑人时，应当出示传唤证和侦查人员的人民警察证，并责令其在传唤证上签名、捺指印。 犯罪嫌疑人到案后，应当由其在传唤证上填写到案时间。传唤结束时，应当由其在传唤证上填写传唤结束时间。犯罪嫌疑人拒绝填写的，侦查人员应当在传唤证上注明。 对在现场发现的犯罪嫌疑人，侦查人员经出示人民警察证，可以口头传唤，并将传唤的原因和依据告知被传唤人。在讯问笔录中应当注明犯罪嫌疑人到案方式，并由犯罪嫌疑人注明到案时间和传唤结束时间。 对自动投案或者群众扭送到公安机关的犯罪嫌疑人，可以依法传唤。"},{"i":200,"n":"第二百条","txt":"传唤持续的时间不得超过十二小时。案情特别重大、复杂，需要采取拘留、逮捕措施的，经办案部门负责人批准，传唤持续的时间不得超过二十四小时。不得以连续传唤的形式变相拘禁犯罪嫌疑人。 传唤期限届满，未作出采取其他强制措施决定的，应当立即结束传唤。"},{"i":201,"n":"第二百零一条","txt":"传唤、拘传、讯问犯罪嫌疑人，应当保证犯罪嫌疑人的饮食和必要的休息时间，并记录在案。"},{"i":202,"n":"第二百零二条","txt":"讯问犯罪嫌疑人，必须由侦查人员进行。讯问的时候，侦查人员不得少于二人。 讯问同案的犯罪嫌疑人，应当个别进行。"},{"i":203,"n":"第二百零三条","txt":"侦查人员讯问犯罪嫌疑人时，应当首先讯问犯罪嫌疑人是否有犯罪行为，并告知犯罪嫌疑人享有的诉讼权利，如实供述自己罪行可以从宽处理以及认罪认罚的法律规定，让他陈述有罪的情节或者无罪的辩解，然后向他提出问题。 犯罪嫌疑人对侦查人员的提问，应当如实回答。但是对与本案无关的问题，有拒绝回答的权利。 第一次讯问，应当问明犯罪嫌疑人的姓名、别名、曾用名、出生年月日、户籍所在地、现住地、籍贯、出生地、民族、职业、文化程度、政治面貌、工作单位、家庭情况、社会经历，是否属于人大代表、政协委员，是否受过刑事处罚或者行政处理等情况。"},{"i":204,"n":"第二百零四条","txt":"讯问聋、哑的犯罪嫌疑人，应当有通晓聋、哑手势的人参加，并在讯问笔录上注明犯罪嫌疑人的聋、哑情况，以及翻译人员的姓名、工作单位和职业。 讯问不通晓当地语言文字的犯罪嫌疑人，应当配备翻译人员。"},{"i":205,"n":"第二百零五条","txt":"侦查人员应当将问话和犯罪嫌疑人的供述或者辩解如实地记录清楚。制作讯问笔录应当使用能够长期保持字迹的材料。"},{"i":206,"n":"第二百零六条","txt":"讯问笔录应当交犯罪嫌疑人核对；对于没有阅读能力的，应当向他宣读。如果记录有遗漏或者差错，应当允许犯罪嫌疑人补充或者更正，并捺指印。笔录经犯罪嫌疑人核对无误后，应当由其在笔录上逐页签名、捺指印，并在末页写明“以上笔录我看过（或向我宣读过），和我说的相符”。拒绝签名、捺指印的，侦查人员应当在笔录上注明。 讯问笔录上所列项目，应当按照规定填写齐全。侦查人员、翻译人员应当在讯问笔录上签名。"},{"i":207,"n":"第二百零七条","txt":"犯罪嫌疑人请求自行书写供述的，应当准许；必要时，侦查人员也可以要求犯罪嫌疑人亲笔书写供词。犯罪嫌疑人应当在亲笔供词上逐页签名、捺指印。侦查人员收到后，应当在首页右上方写明“于某年某月某日收到”，并签名。"},{"i":208,"n":"第二百零八条","txt":"讯问犯罪嫌疑人，在文字记录的同时，可以对讯问过程进行录音录像。对于可能判处无期徒刑、死刑的案件或者其他重大犯罪案件，应当对讯问过程进行录音录像。 前款规定的“可能判处无期徒刑、死刑的案件”，是指应当适用的法定刑或者量刑档次包含无期徒刑、死刑的案件。“其他重大犯罪案件”，是指致人重伤、死亡的严重危害公共安全犯罪、严重侵犯公民人身权利犯罪，以及黑社会性质组织犯罪、严重毒品犯罪等重大故意犯罪案件。 对讯问过程录音录像的，应当对每一次讯问全程不间断进行，保持完整性。不得选择性地录制，不得剪接、删改。"},{"i":209,"n":"第二百零九条","txt":"对犯罪嫌疑人供述的犯罪事实、无罪或者罪轻的事实、申辩和反证，以及犯罪嫌疑人提供的证明自己无罪、罪轻的证据，公安机关应当认真核查；对有关证据，无论是否采信，都应当如实记录、妥善保管，并连同核查情况附卷。"},{"i":210,"n":"第二百一十条","txt":"询问证人、被害人，可以在现场进行，也可以到证人、被害人所在单位、住处或者证人、被害人提出的地点进行。在必要的时候，可以书面、电话或者当场通知证人、被害人到公安机关提供证言。 询问证人、被害人应当个别进行。 在现场询问证人、被害人，侦查人员应当出示人民警察证。到证人、被害人所在单位、住处或者证人、被害人提出的地点询问证人、被害人，应当经办案部门负责人批准，制作询问通知书。询问前，侦查人员应当出示询问通知书和人民警察证。"},{"i":211,"n":"第二百一十一条","txt":"询问前，应当了解证人、被害人的身份，证人、被害人、犯罪嫌疑人之间的关系。询问时，应当告知证人、被害人必须如实地提供证据、证言和有意作伪证或者隐匿罪证应负的法律责任。 侦查人员不得向证人、被害人泄露案情或者表示对案件的看法，严禁采用暴力、威胁等非法方法询问证人、被害人。"},{"i":212,"n":"第二百一十二条","txt":"本规定第二百零六条、第二百零七条的规定，也适用于询问证人、被害人。"},{"i":213,"n":"第二百一十三条","txt":"侦查人员对于与犯罪有关的场所、物品、人身、尸体应当进行勘验或者检查，及时提取、采集与案件有关的痕迹、物证、生物样本等。在必要的时候，可以指派或者聘请具有专门知识的人，在侦查人员的主持下进行勘验、检查。"},{"i":214,"n":"第二百一十四条","txt":"发案地派出所、巡警等部门应当妥善保护犯罪现场和证据，控制犯罪嫌疑人，并立即报告公安机关主管部门。 执行勘查的侦查人员接到通知后，应当立即赶赴现场；勘查现场，应当持有刑事犯罪现场勘查证。"},{"i":215,"n":"第二百一十五条","txt":"公安机关对案件现场进行勘查，侦查人员不得少于二人。"},{"i":216,"n":"第二百一十六条","txt":"勘查现场，应当拍摄现场照片、绘制现场图，制作笔录，由参加勘查的人和见证人签名。对重大案件的现场勘查，应当录音录像。"},{"i":217,"n":"第二百一十七条","txt":"为了确定被害人、犯罪嫌疑人的某些特征、伤害情况或者生理状态，可以对人身进行检查，依法提取、采集肖像、指纹等人体生物识别信息，采集血液、尿液等生物样本。被害人死亡的，应当通过被害人近亲属辨认、提取生物样本鉴定等方式确定被害人身份。 犯罪嫌疑人拒绝检查、提取、采集的，侦查人员认为必要的时候，经办案部门负责人批准，可以强制检查、提取、采集。 检查妇女的身体，应当由女工作人员或者医师进行。 检查的情况应当制作笔录，由参加检查的侦查人员、检查人员、被检查人员和见证人签名。被检查人员拒绝签名的，侦查人员应当在笔录中注明。"},{"i":218,"n":"第二百一十八条","txt":"为了确定死因，经县级以上公安机关负责人批准，可以解剖尸体，并且通知死者家属到场，让其在解剖尸体通知书上签名。 死者家属无正当理由拒不到场或者拒绝签名的，侦查人员应当在解剖尸体通知书上注明。对身份不明的尸体，无法通知死者家属的，应当在笔录中注明。"},{"i":219,"n":"第二百一十九条","txt":"对已查明死因，没有继续保存必要的尸体，应当通知家属领回处理，对于无法通知或者通知后家属拒绝领回的，经县级以上公安机关负责人批准，可以及时处理。"},{"i":220,"n":"第二百二十条","txt":"公安机关进行勘验、检查后，人民检察院要求复验、复查的，公安机关应当进行复验、复查，并可以通知人民检察院派员参加。"},{"i":221,"n":"第二百二十一条","txt":"为了查明案情，在必要的时候，经县级以上公安机关负责人批准，可以进行侦查实验。 进行侦查实验，应当全程录音录像，并制作侦查实验笔录，由参加实验的人签名。 进行侦查实验，禁止一切足以造成危险、侮辱人格或者有伤风化的行为。"},{"i":222,"n":"第二百二十二条","txt":"为了收集犯罪证据、查获犯罪人，经县级以上公安机关负责人批准，侦查人员可以对犯罪嫌疑人以及可能隐藏罪犯或者犯罪证据的人的身体、物品、住处和其他有关的地方进行搜查。"},{"i":223,"n":"第二百二十三条","txt":"进行搜查，必须向被搜查人出示搜查证，执行搜查的侦查人员不得少于二人。"},{"i":224,"n":"第二百二十四条","txt":"执行拘留、逮捕的时候，遇有下列紧急情况之一的，不用搜查证也可以进行搜查： （一）可能随身携带凶器的； （二）可能隐藏爆炸、剧毒等危险物品的； （三）可能隐匿、毁弃、转移犯罪证据的； （四）可能隐匿其他犯罪嫌疑人的； （五）其他突然发生的紧急情况。"},{"i":225,"n":"第二百二十五条","txt":"进行搜查时，应当有被搜查人或者他的家属、邻居或者其他见证人在场。 公安机关可以要求有关单位和个人交出可以证明犯罪嫌疑人有罪或者无罪的物证、书证、视听资料等证据。遇到阻碍搜查的，侦查人员可以强制搜查。 搜查妇女的身体，应当由女工作人员进行。"},{"i":226,"n":"第二百二十六条","txt":"搜查的情况应当制作笔录，由侦查人员和被搜查人或者他的家属，邻居或者其他见证人签名。 如果被搜查人拒绝签名，或者被搜查人在逃，他的家属拒绝签名或者不在场的，侦查人员应当在笔录中注明。"},{"i":227,"n":"第二百二十七条","txt":"在侦查活动中发现的可用以证明犯罪嫌疑人有罪或者无罪的各种财物、文件，应当查封、扣押；但与案件无关的财物、文件，不得查封、扣押。 持有人拒绝交出应当查封、扣押的财物、文件的，公安机关可以强制查封、扣押。"},{"i":228,"n":"第二百二十八条","txt":"在侦查过程中需要扣押财物、文件的，应当经办案部门负责人批准，制作扣押决定书；在现场勘查或者搜查中需要扣押财物、文件的，由现场指挥人员决定；但扣押财物、文件价值较高或者可能严重影响正常生产经营的，应当经县级以上公安机关负责人批准，制作扣押决定书。 在侦查过程中需要查封土地、房屋等不动产，或者船舶、航空器以及其他不宜移动的大型机器、设备等特定动产的，应当经县级以上公安机关负责人批准并制作查封决定书。"},{"i":229,"n":"第二百二十九条","txt":"执行查封、扣押的侦查人员不得少于二人，并出示本规定第二百二十八条规定的有关法律文书。 查封、扣押的情况应当制作笔录，由侦查人员、持有人和见证人签名。对于无法确定持有人或者持有人拒绝签名的，侦查人员应当在笔录中注明。"},{"i":230,"n":"第二百三十条","txt":"对查封、扣押的财物和文件，应当会同在场见证人和被查封、扣押财物、文件的持有人查点清楚，当场开列查封、扣押清单一式三份，写明财物或者文件的名称、编号、数量、特征及其来源等，由侦查人员、持有人和见证人签名，一份交给持有人，一份交给公安机关保管人员，一份附卷备查。 对于财物、文件的持有人无法确定，以及持有人不在现场或者拒绝签名的，侦查人员应当在清单中注明。 依法扣押文物、贵金属、珠宝、字画等贵重财物的，应当拍照或者录音录像，并及时鉴定、估价。 执行查封、扣押时，应当为犯罪嫌疑人及其所扶养的亲属保留必需的生活费用和物品。能够保证侦查活动正常进行的，可以允许有关当事人继续合理使用有关涉案财物，但应当采取必要的保值、保管措施。"},{"i":231,"n":"第二百三十一条","txt":"对作为犯罪证据但不便提取或者没有必要提取的财物、文件，经登记、拍照或者录音录像、估价后，可以交财物、文件持有人保管或者封存，并且开具登记保存清单一式两份，由侦查人员、持有人和见证人签名，一份交给财物、文件持有人，另一份连同照片或者录音录像资料附卷备查。财物、文件持有人应当妥善保管，不得转移、变卖、毁损。"},{"i":232,"n":"第二百三十二条","txt":"扣押犯罪嫌疑人的邮件、电子邮件、电报，应当经县级以上公安机关负责人批准，制作扣押邮件、电报通知书，通知邮电部门或者网络服务单位检交扣押。 不需要继续扣押的时候，应当经县级以上公安机关负责人批准，制作解除扣押邮件、电报通知书，立即通知邮电部门或者网络服务单位。"},{"i":233,"n":"第二百三十三条","txt":"对查封、扣押的财物、文件、邮件、电子邮件、电报，经查明确实与案件无关的，应当在三日以内解除查封、扣押，退还原主或者原邮电部门、网络服务单位；原主不明确的，应当采取公告方式告知原主认领。在通知原主或者公告后六个月以内，无人认领的，按照无主财物处理，登记后上缴国库。"},{"i":234,"n":"第二百三十四条","txt":"有关犯罪事实查证属实后，对于有证据证明权属明确且无争议的被害人合法财产及其孳息，且返还不损害其他被害人或者利害关系人的利益，不影响案件正常办理的，应当在登记、拍照或者录音录像和估价后，报经县级以上公安机关负责人批准，开具发还清单返还，并在案卷材料中注明返还的理由，将原物照片、发还清单和被害人的领取手续存卷备查。 领取人应当是涉案财物的合法权利人或者其委托的人；委托他人领取的，应当出具委托书。侦查人员或者公安机关其他工作人员不得代为领取。 查找不到被害人，或者通知被害人后，无人领取的，应当将有关财产及其孳息随案移送。"},{"i":235,"n":"第二百三十五条","txt":"对查封、扣押的财物及其孳息、文件，公安机关应当妥善保管，以供核查。任何单位和个人不得违规使用、调换、损毁或者自行处理。 县级以上公安机关应当指定一个内设部门作为涉案财物管理部门，负责对涉案财物实行统一管理，并设立或者指定专门保管场所，对涉案财物进行集中保管。 对价值较低、易于保管，或者需要作为证据继续使用，以及需要先行返还被害人的涉案财物，可以由办案部门设置专门的场所进行保管。办案部门应当指定不承担办案工作的民警负责本部门涉案财物的接收、保管、移交等管理工作；严禁由侦查人员自行保管涉案财物。"},{"i":236,"n":"第二百三十六条","txt":"在侦查期间，对于易损毁、灭失、腐烂、变质而不宜长期保存，或者难以保管的物品，经县级以上公安机关主要负责人批准，可以在拍照或者录音录像后委托有关部门变卖、拍卖，变卖、拍卖的价款暂予保存，待诉讼终结后一并处理。 对于违禁品，应当依照国家有关规定处理；需要作为证据使用的，应当在诉讼终结后处理。"},{"i":237,"n":"第二百三十七条","txt":"公安机关根据侦查犯罪的需要，可以依照规定查询、冻结犯罪嫌疑人的存款、汇款、证券交易结算资金、期货保证金等资金，债券、股票、基金份额和其他证券，以及股权、保单权益和其他投资权益等财产，并可以要求有关单位和个人配合。 对于前款规定的财产，不得划转、转账或者以其他方式变相扣押。"},{"i":238,"n":"第二百三十八条","txt":"向金融机构等单位查询犯罪嫌疑人的存款、汇款、证券交易结算资金、期货保证金等资金，债券、股票、基金份额和其他证券，以及股权、保单权益和其他投资权益等财产，应当经县级以上公安机关负责人批准，制作协助查询财产通知书，通知金融机构等单位协助办理。"},{"i":239,"n":"第二百三十九条","txt":"需要冻结犯罪嫌疑人财产的，应当经县级以上公安机关负责人批准，制作协助冻结财产通知书，明确冻结财产的账户名称、账户号码、冻结数额、冻结期限、冻结范围以及是否及于孳息等事项，通知金融机构等单位协助办理。 冻结股权、保单权益的，应当经设区的市一级以上公安机关负责人批准。 冻结上市公司股权的，应当经省级以上公安机关负责人批准。"},{"i":240,"n":"第二百四十条","txt":"需要延长冻结期限的，应当按照原批准权限和程序，在冻结期限届满前办理继续冻结手续。逾期不办理继续冻结手续的，视为自动解除冻结。"},{"i":241,"n":"第二百四十一条","txt":"不需要继续冻结犯罪嫌疑人财产时，应当经原批准冻结的公安机关负责人批准，制作协助解除冻结财产通知书，通知金融机构等单位协助办理。"},{"i":242,"n":"第二百四十二条","txt":"犯罪嫌疑人的财产已被冻结的，不得重复冻结，但可以轮候冻结。"},{"i":243,"n":"第二百四十三条","txt":"冻结存款、汇款、证券交易结算资金、期货保证金等财产的期限为六个月。每次续冻期限最长不得超过六个月。 对于重大、复杂案件，经设区的市一级以上公安机关负责人批准，冻结存款、汇款、证券交易结算资金、期货保证金等财产的期限可以为一年。每次续冻期限最长不得超过一年。"},{"i":244,"n":"第二百四十四条","txt":"冻结债券、股票、基金份额等证券的期限为二年。每次续冻期限最长不得超过二年。"},{"i":245,"n":"第二百四十五条","txt":"冻结股权、保单权益或者投资权益的期限为六个月。每次续冻期限最长不得超过六个月。"},{"i":246,"n":"第二百四十六条","txt":"对冻结的债券、股票、基金份额等财产，应当告知当事人或者其法定代理人、委托代理人有权申请出售。 权利人书面申请出售被冻结的债券、股票、基金份额等财产，不损害国家利益、被害人、其他权利人利益，不影响诉讼正常进行的，以及冻结的汇票、本票、支票的有效期即将届满的，经县级以上公安机关负责人批准，可以依法出售或者变现，所得价款应当继续冻结在其对应的银行账户中；没有对应的银行账户的，所得价款由公安机关在银行指定专门账户保管，并及时告知当事人或者其近亲属。"},{"i":247,"n":"第二百四十七条","txt":"对冻结的财产，经查明确实与案件无关的，应当在三日以内通知金融机构等单位解除冻结，并通知被冻结财产的所有人。"},{"i":248,"n":"第二百四十八条","txt":"为了查明案情，解决案件中某些专门性问题，应当指派、聘请有专门知识的人进行鉴定。 需要聘请有专门知识的人进行鉴定，应当经县级以上公安机关负责人批准后，制作鉴定聘请书。"},{"i":249,"n":"第二百四十九条","txt":"公安机关应当为鉴定人进行鉴定提供必要的条件，及时向鉴定人送交有关检材和对比样本等原始材料，介绍与鉴定有关的情况，并且明确提出要求鉴定解决的问题。 禁止暗示或者强迫鉴定人作出某种鉴定意见。"},{"i":250,"n":"第二百五十条","txt":"侦查人员应当做好检材的保管和送检工作，并注明检材送检环节的责任人，确保检材在流转环节中的同一性和不被污染。"},{"i":251,"n":"第二百五十一条","txt":"鉴定人应当按照鉴定规则，运用科学方法独立进行鉴定。鉴定后，应当出具鉴定意见，并在鉴定意见书上签名，同时附上鉴定机构和鉴定人的资质证明或者其他证明文件。 多人参加鉴定，鉴定人有不同意见的，应当注明。"},{"i":252,"n":"第二百五十二条","txt":"对鉴定意见，侦查人员应当进行审查。 对经审查作为证据使用的鉴定意见，公安机关应当及时告知犯罪嫌疑人、被害人或者其法定代理人。"},{"i":253,"n":"第二百五十三条","txt":"犯罪嫌疑人、被害人对鉴定意见有异议提出申请，以及办案部门或者侦查人员对鉴定意见有疑义的，可以将鉴定意见送交其他有专门知识的人员提出意见。必要时，询问鉴定人并制作笔录附卷。"},{"i":254,"n":"第二百五十四条","txt":"经审查，发现有下列情形之一的，经县级以上公安机关负责人批准，应当补充鉴定： （一）鉴定内容有明显遗漏的； （二）发现新的有鉴定意义的证物的； （三）对鉴定证物有新的鉴定要求的； （四）鉴定意见不完整，委托事项无法确定的； （五）其他需要补充鉴定的情形。 经审查，不符合上述情形的，经县级以上公安机关负责人批准，作出不准予补充鉴定的决定，并在作出决定后三日以内书面通知申请人。"},{"i":255,"n":"第二百五十五条","txt":"经审查，发现有下列情形之一的，经县级以上公安机关负责人批准，应当重新鉴定： （一）鉴定程序违法或者违反相关专业技术要求的； （二）鉴定机构、鉴定人不具备鉴定资质和条件的; （三）鉴定人故意作虚假鉴定或者违反回避规定的； （四）鉴定意见依据明显不足的； （五）检材虚假或者被损坏的； （六）其他应当重新鉴定的情形。 重新鉴定，应当另行指派或者聘请鉴定人。 经审查，不符合上述情形的，经县级以上公安机关负责人批准，作出不准予重新鉴定的决定，并在作出决定后三日以内书面通知申请人。"},{"i":256,"n":"第二百五十六条","txt":"公诉人、当事人或者辩护人、诉讼代理人对鉴定意见有异议，经人民法院依法通知的，公安机关鉴定人应当出庭作证。 鉴定人故意作虚假鉴定的，应当依法追究其法律责任。"},{"i":257,"n":"第二百五十七条","txt":"对犯罪嫌疑人作精神病鉴定的时间不计入办案期限，其他鉴定时间都应当计入办案期限。"},{"i":258,"n":"第二百五十八条","txt":"为了查明案情，在必要的时候，侦查人员可以让被害人、证人或者犯罪嫌疑人对与犯罪有关的物品、文件、尸体、场所或者犯罪嫌疑人进行辨认。"},{"i":259,"n":"第二百五十九条","txt":"辨认应当在侦查人员的主持下进行。主持辨认的侦查人员不得少于二人。 几名辨认人对同一辨认对象进行辨认时，应当由辨认人个别进行。"},{"i":260,"n":"第二百六十条","txt":"辨认时，应当将辨认对象混杂在特征相类似的其他对象中，不得在辨认前向辨认人展示辨认对象及其影像资料，不得给辨认人任何暗示。 辨认犯罪嫌疑人时，被辨认的人数不得少于七人；对犯罪嫌疑人照片进行辨认的，不得少于十人的照片。 辨认物品时，混杂的同类物品不得少于五件；对物品的照片进行辨认的，不得少于十个物品的照片。 对场所、尸体等特定辨认对象进行辨认，或者辨认人能够准确描述物品独有特征的，陪衬物不受数量的限制。"},{"i":261,"n":"第二百六十一条","txt":"对犯罪嫌疑人的辨认，辨认人不愿意公开进行时，可以在不暴露辨认人的情况下进行，并应当为其保守秘密。"},{"i":262,"n":"第二百六十二条","txt":"对辨认经过和结果，应当制作辨认笔录，由侦查人员、辨认人、见证人签名。必要时，应当对辨认过程进行录音录像。"},{"i":263,"n":"第二百六十三条","txt":"公安机关在立案后，根据侦查犯罪的需要，可以对下列严重危害社会的犯罪案件采取技术侦查措施： （一）危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、重大毒品犯罪案件； （二）故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、绑架、放火、爆炸、投放危险物质等严重暴力犯罪案件； （三）集团性、系列性、跨区域性重大犯罪案件; （四）利用电信、计算机网络、寄递渠道等实施的重大犯罪案件，以及针对计算机网络实施的重大犯罪案件； （五）其他严重危害社会的犯罪案件，依法可能判处七年以上有期徒刑的。 公安机关追捕被通缉或者批准、决定逮捕的在逃的犯罪嫌疑人、被告人，可以采取追捕所必需的技术侦查措施。"},{"i":264,"n":"第二百六十四条","txt":"技术侦查措施是指由设区的市一级以上公安机关负责技术侦查的部门实施的记录监控、行踪监控、通信监控、场所监控等措施。 技术侦查措施的适用对象是犯罪嫌疑人、被告人以及与犯罪活动直接关联的人员。"},{"i":265,"n":"第二百六十五条","txt":"需要采取技术侦查措施的，应当制作呈请采取技术侦查措施报告书，报设区的市一级以上公安机关负责人批准，制作采取技术侦查措施决定书。 人民检察院等部门决定采取技术侦查措施，交公安机关执行的，由设区的市一级以上公安机关按照规定办理相关手续后，交负责技术侦查的部门执行，并将执行情况通知人民检察院等部门。"},{"i":266,"n":"第二百六十六条","txt":"批准采取技术侦查措施的决定自签发之日起三个月以内有效。 在有效期限内，对不需要继续采取技术侦查措施的，办案部门应当立即书面通知负责技术侦查的部门解除技术侦查措施；负责技术侦查的部门认为需要解除技术侦查措施的，报批准机关负责人批准，制作解除技术侦查措施决定书，并及时通知办案部门。 对复杂、疑难案件，采取技术侦查措施的有效期限届满仍需要继续采取技术侦查措施的，经负责技术侦查的部门审核后，报批准机关负责人批准，制作延长技术侦查措施期限决定书。批准延长期限，每次不得超过三个月。 有效期限届满，负责技术侦查的部门应当立即解除技术侦查措施。"},{"i":267,"n":"第二百六十七条","txt":"采取技术侦查措施，必须严格按照批准的措施种类、适用对象和期限执行。 在有效期限内，需要变更技术侦查措施种类或者适用对象的，应当按照本规定第二百六十五条规定重新办理批准手续。"},{"i":268,"n":"第二百六十八条","txt":"采取技术侦查措施收集的材料在刑事诉讼中可以作为证据使用。使用技术侦查措施收集的材料作为证据时，可能危及有关人员的人身安全，或者可能产生其他严重后果的，应当采取不暴露有关人员身份和使用的技术设备、侦查方法等保护措施。 采取技术侦查措施收集的材料作为证据使用的，采取技术侦查措施决定书应当附卷。"},{"i":269,"n":"第二百六十九条","txt":"采取技术侦查措施收集的材料，应当严格依照有关规定存放，只能用于对犯罪的侦查、起诉和审判，不得用于其他用途。 采取技术侦查措施收集的与案件无关的材料，必须及时销毁，并制作销毁记录。"},{"i":270,"n":"第二百七十条","txt":"侦查人员对采取技术侦查措施过程中知悉的国家秘密、商业秘密和个人隐私，应当保密。 公安机关依法采取技术侦查措施，有关单位和个人应当配合，并对有关情况予以保密。"},{"i":271,"n":"第二百七十一条","txt":"为了查明案情，在必要的时候，经县级以上公安机关负责人决定，可以由侦查人员或者公安机关指定的其他人员隐匿身份实施侦查。 隐匿身份实施侦查时，不得使用促使他人产生犯罪意图的方法诱使他人犯罪，不得采用可能危害公共安全或者发生重大人身危险的方法。"},{"i":272,"n":"第二百七十二条","txt":"对涉及给付毒品等违禁品或者财物的犯罪活动，为查明参与该项犯罪的人员和犯罪事实，根据侦查需要，经县级以上公安机关负责人决定，可以实施控制下交付。"},{"i":273,"n":"第二百七十三条","txt":"公安机关依照本节规定实施隐匿身份侦查和控制下交付收集的材料在刑事诉讼中可以作为证据使用。 使用隐匿身份侦查和控制下交付收集的材料作为证据时，可能危及隐匿身份人员的人身安全，或者可能产生其他严重后果的，应当采取不暴露有关人员身份等保护措施。"},{"i":274,"n":"第二百七十四条","txt":"应当逮捕的犯罪嫌疑人在逃的，经县级以上公安机关负责人批准，可以发布通缉令，采取有效措施，追捕归案。 县级以上公安机关在自己管辖的地区内，可以直接发布通缉令；超出自己管辖的地区，应当报请有权决定的上级公安机关发布。 通缉令的发送范围，由签发通缉令的公安机关负责人决定。"},{"i":275,"n":"第二百七十五条","txt":"通缉令中应当尽可能写明被通缉人的姓名、别名、曾用名、绰号、性别、年龄、民族、籍贯、出生地、户籍所在地、居住地、职业、身份证号码、衣着和体貌特征、口音、行为习惯，并附被通缉人近期照片，可以附指纹及其他物证的照片。除了必须保密的事项以外，应当写明发案的时间、地点和简要案情。"},{"i":276,"n":"第二百七十六条","txt":"通缉令发出后，如果发现新的重要情况可以补发通报。通报必须注明原通缉令的编号和日期。"},{"i":277,"n":"第二百七十七条","txt":"公安机关接到通缉令后，应当及时布置查缉。抓获犯罪嫌疑人后，报经县级以上公安机关负责人批准，凭通缉令或者相关法律文书羁押，并通知通缉令发布机关进行核实，办理交接手续。"},{"i":278,"n":"第二百七十八条","txt":"需要对犯罪嫌疑人在口岸采取边控措施的，应当按照有关规定制作边控对象通知书，并附有关法律文书，经县级以上公安机关负责人审核后，层报省级公安机关批准，办理全国范围内的边控措施。需要限制犯罪嫌疑人人身自由的，应当附有关限制人身自由的法律文书。 紧急情况下，需要采取边控措施的，县级以上公安机关可以出具公函，先向有关口岸所在地出入境边防检查机关交控，但应当在七日以内按照规定程序办理全国范围内的边控措施。"},{"i":279,"n":"第二百七十九条","txt":"为发现重大犯罪线索，追缴涉案财物、证据，查获犯罪嫌疑人，必要时，经县级以上公安机关负责人批准，可以发布悬赏通告。 悬赏通告应当写明悬赏对象的基本情况和赏金的具体数额。"},{"i":280,"n":"第二百八十条","txt":"通缉令、悬赏通告应当广泛张贴，并可以通过广播、电视、报刊、计算机网络等方式发布。"},{"i":281,"n":"第二百八十一条","txt":"经核实，犯罪嫌疑人已经自动投案、被击毙或者被抓获，以及发现有其他不需要采取通缉、边控、悬赏通告的情形的，发布机关应当在原通缉、通知、通告范围内，撤销通缉令、边控通知、悬赏通告。"},{"i":282,"n":"第二百八十二条","txt":"通缉越狱逃跑的犯罪嫌疑人、被告人或者罪犯，适用本节的有关规定。"},{"i":283,"n":"第二百八十三条","txt":"侦查终结的案件，应当同时符合以下条件： （一）案件事实清楚； （二）证据确实、充分； （三）犯罪性质和罪名认定正确； （四）法律手续完备； （五）依法应当追究刑事责任。"},{"i":284,"n":"第二百八十四条","txt":"对侦查终结的案件，公安机关应当全面审查证明证据收集合法性的证据材料，依法排除非法证据。排除非法证据后证据不足的，不得移送审查起诉。 公安机关发现侦查人员非法取证的，应当依法作出处理，并可另行指派侦查人员重新调查取证。"},{"i":285,"n":"第二百八十五条","txt":"侦查终结的案件，侦查人员应当制作结案报告。 结案报告应当包括以下内容： （一）犯罪嫌疑人的基本情况； （二）是否采取了强制措施及其理由； （三）案件的事实和证据； （四）法律依据和处理意见。"},{"i":286,"n":"第二百八十六条","txt":"侦查终结案件的处理，由县级以上公安机关负责人批准；重大、复杂、疑难的案件应当经过集体讨论。"},{"i":287,"n":"第二百八十七条","txt":"侦查终结后，应当将全部案卷材料按照要求装订立卷。 向人民检察院移送案件时，只移送诉讼卷，侦查卷由公安机关存档备查。"},{"i":288,"n":"第二百八十八条","txt":"对查封、扣押的犯罪嫌疑人的财物及其孳息、文件或者冻结的财产，作为证据使用的，应当随案移送，并制作随案移送清单一式两份，一份留存，一份交人民检察院。制作清单时，应当根据已经查明的案情，写明对涉案财物的处理建议。 对于实物不宜移送的，应当将其清单、照片或者其他证明文件随案移送。待人民法院作出生效判决后，按照人民法院送达的生效判决书、裁定书依法作出处理，并向人民法院送交回执。人民法院在判决、裁定中未对涉案财物作出处理的，公安机关应当征求人民法院意见，并根据人民法院的决定依法作出处理。"},{"i":289,"n":"第二百八十九条","txt":"对侦查终结的案件，应当制作起诉意见书，经县级以上公安机关负责人批准后，连同全部案卷材料、证据，以及辩护律师提出的意见，一并移送同级人民检察院审查决定；同时将案件移送情况告知犯罪嫌疑人及其辩护律师。 犯罪嫌疑人自愿认罪的，应当记录在案，随案移送，并在起诉意见书中写明有关情况；认为案件符合速裁程序适用条件的，可以向人民检察院提出适用速裁程序的建议。"},{"i":290,"n":"第二百九十条","txt":"对于犯罪嫌疑人在境外，需要及时进行审判的严重危害国家安全犯罪、恐怖活动犯罪案件，应当在侦查终结后层报公安部批准，移送同级人民检察院审查起诉。 在审查起诉或者缺席审理过程中，犯罪嫌疑人、被告人向公安机关自动投案或者被公安机关抓获的，公安机关应当立即通知人民检察院、人民法院。"},{"i":291,"n":"第二百九十一条","txt":"共同犯罪案件的起诉意见书，应当写明每个犯罪嫌疑人在共同犯罪中的地位、作用、具体罪责和认罪态度，并分别提出处理意见。"},{"i":292,"n":"第二百九十二条","txt":"被害人提出附带民事诉讼的，应当记录在案；移送审查起诉时，应当在起诉意见书末页注明。"},{"i":293,"n":"第二百九十三条","txt":"人民检察院作出不起诉决定的，如果被不起诉人在押，公安机关应当立即办理释放手续。除依法转为行政案件办理外，应当根据人民检察院解除查封、扣押、冻结财物的书面通知，及时解除查封、扣押、冻结。 人民检察院提出对被不起诉人给予行政处罚、处分或者没收其违法所得的检察意见，移送公安机关处理的，公安机关应当将处理结果及时通知人民检察院。"},{"i":294,"n":"第二百九十四条","txt":"认为人民检察院作出的不起诉决定有错误的，应当在收到不起诉决定书后七日以内制作要求复议意见书，经县级以上公安机关负责人批准后，移送人民检察院复议。 要求复议的意见不被接受的，可以在收到人民检察院的复议决定书后七日以内制作提请复核意见书，经县级以上公安机关负责人批准后，连同人民检察院的复议决定书，一并提请上一级人民检察院复核。"},{"i":295,"n":"第二百九十五条","txt":"侦查终结，移送人民检察院审查起诉的案件，人民检察院退回公安机关补充侦查的，公安机关接到人民检察院退回补充侦查的法律文书后，应当按照补充侦查提纲在一个月以内补充侦查完毕。 补充侦查以二次为限。"},{"i":296,"n":"第二百九十六条","txt":"对人民检察院退回补充侦查的案件，根据不同情况，报县级以上公安机关负责人批准，分别作如下处理： （一）原认定犯罪事实不清或者证据不够充分的，应当在查清事实、补充证据后，制作补充侦查报告书，移送人民检察院审查；对确实无法查明的事项或者无法补充的证据，应当书面向人民检察院说明情况； （二）在补充侦查过程中，发现新的同案犯或者新的罪行，需要追究刑事责任的，应当重新制作起诉意见书，移送人民检察院审查； （三）发现原认定的犯罪事实有重大变化，不应当追究刑事责任的，应当撤销案件或者对犯罪嫌疑人终止侦查，并将有关情况通知退查的人民检察院； （四）原认定犯罪事实清楚，证据确实、充分，人民检察院退回补充侦查不当的，应当说明理由，移送人民检察院审查。"},{"i":297,"n":"第二百九十七条","txt":"对于人民检察院在审查起诉过程中以及在人民法院作出生效判决前，要求公安机关提供法庭审判所必需的证据材料的，应当及时收集和提供。"},{"i":298,"n":"第二百九十八条","txt":"对被依法判处刑罚的罪犯，如果罪犯已被采取强制措施的，公安机关应当依据人民法院生效的判决书、裁定书以及执行通知书，将罪犯交付执行。 对人民法院作出无罪或者免除刑事处罚的判决，如果被告人在押，公安机关在收到相应的法律文书后应当立即办理释放手续；对人民法院建议给予行政处理的，应当依照有关规定处理或者移送有关部门。"},{"i":299,"n":"第二百九十九条","txt":"对被判处死刑的罪犯，公安机关应当依据人民法院执行死刑的命令，将罪犯交由人民法院执行。"},{"i":300,"n":"第三百条","txt":"公安机关接到人民法院生效的判处死刑缓期二年执行、无期徒刑、有期徒刑的判决书、裁定书以及执行通知书后，应当在一个月以内将罪犯送交监狱执行。 对未成年犯应当送交未成年犯管教所执行刑罚。"},{"i":301,"n":"第三百零一条","txt":"对被判处有期徒刑的罪犯，在被交付执行刑罚前，剩余刑期在三个月以下的，由看守所根据人民法院的判决代为执行。 对被判处拘役的罪犯，由看守所执行。"},{"i":302,"n":"第三百零二条","txt":"对被判处管制、宣告缓刑、假释或者暂予监外执行的罪犯，已被羁押的，由看守所将其交付社区矫正机构执行。 对被判处剥夺政治权利的罪犯，由罪犯居住地的派出所负责执行。"},{"i":303,"n":"第三百零三条","txt":"对被判处有期徒刑由看守所代为执行和被判处拘役的罪犯，执行期间如果没有再犯新罪，执行期满，看守所应当发给刑满释放证明书。"},{"i":304,"n":"第三百零四条","txt":"公安机关在执行刑罚中，如果认为判决有错误或者罪犯提出申诉，应当转请人民检察院或者原判人民法院处理。"},{"i":305,"n":"第三百零五条","txt":"对依法留看守所执行刑罚的罪犯，符合减刑条件的，由看守所制作减刑建议书，经设区的市一级以上公安机关审查同意后，报请所在地中级以上人民法院审核裁定。"},{"i":306,"n":"第三百零六条","txt":"对依法留看守所执行刑罚的罪犯，符合假释条件的，由看守所制作假释建议书，经设区的市一级以上公安机关审查同意后，报请所在地中级以上人民法院审核裁定。"},{"i":307,"n":"第三百零七条","txt":"对依法留所执行刑罚的罪犯，有下列情形之一的，可以暂予监外执行： （一）有严重疾病需要保外就医的； （二）怀孕或者正在哺乳自己婴儿的妇女； （三）生活不能自理，适用暂予监外执行不致危害社会的。 对罪犯暂予监外执行的，看守所应当提出书面意见，报设区的市一级以上公安机关批准，同时将书面意见抄送同级人民检察院。 对适用保外就医可能有社会危险性的罪犯，或者自伤自残的罪犯，不得保外就医。 对罪犯确有严重疾病，必须保外就医的，由省级人民政府指定的医院诊断并开具证明文件。"},{"i":308,"n":"第三百零八条","txt":"公安机关决定对罪犯暂予监外执行的，应当将暂予监外执行决定书交被暂予监外执行的罪犯和负责监外执行的社区矫正机构，同时抄送同级人民检察院。"},{"i":309,"n":"第三百零九条","txt":"批准暂予监外执行的公安机关接到人民检察院认为暂予监外执行不当的意见后，应当立即对暂予监外执行的决定进行重新核查。"},{"i":310,"n":"第三百一十条","txt":"对暂予监外执行的罪犯，有下列情形之一的，批准暂予监外执行的公安机关应当作出收监执行决定： （一）发现不符合暂予监外执行条件的； （二）严重违反有关暂予监外执行监督管理规定的； （三）暂予监外执行的情形消失后，罪犯刑期未满的。 对暂予监外执行的罪犯决定收监执行的，由暂予监外执行地看守所将罪犯收监执行。 不符合暂予监外执行条件的罪犯通过贿赂等非法手段被暂予监外执行的，或者罪犯在暂予监外执行期间脱逃的，罪犯被收监执行后，所在看守所应当提出不计入执行刑期的建议，经设区的市一级以上公安机关审查同意后，报请所在地中级以上人民法院审核裁定。"},{"i":311,"n":"第三百一十一条","txt":"负责执行剥夺政治权利的派出所应当按照人民法院的判决，向罪犯及其所在单位、居住地基层组织宣布其犯罪事实、被剥夺政治权利的期限，以及罪犯在执行期间应当遵守的规定。"},{"i":312,"n":"第三百一十二条","txt":"被剥夺政治权利的罪犯在执行期间应当遵守下列规定： （一）遵守国家法律、行政法规和公安部制定的有关规定，服从监督管理； （二）不得享有选举权和被选举权； （三）不得组织或者参加集会、游行、示威、结社活动； （四）不得出版、制作、发行书籍、音像制品； （五）不得接受采访，发表演说； （六）不得在境内外发表有损国家荣誉、利益或者其他具有社会危害性的言论； （七）不得担任国家机关职务； （八）不得担任国有公司、企业、事业单位和人民团体的领导职务。"},{"i":313,"n":"第三百一十三条","txt":"被剥夺政治权利的罪犯违反本规定第三百一十二条的规定，尚未构成新的犯罪的，公安机关依法可以给予治安管理处罚。"},{"i":314,"n":"第三百一十四条","txt":"被剥夺政治权利的罪犯，执行期满，公安机关应当书面通知本人及其所在单位、居住地基层组织。"},{"i":315,"n":"第三百一十五条","txt":"对留看守所执行刑罚的罪犯，在暂予监外执行期间又犯新罪的，由犯罪地公安机关立案侦查，并通知批准机关。批准机关作出收监执行决定后，应当根据侦查、审判需要，由犯罪地看守所或者暂予监外执行地看守所收监执行。"},{"i":316,"n":"第三百一十六条","txt":"被剥夺政治权利、管制、宣告缓刑和假释的罪犯在执行期间又犯新罪的，由犯罪地公安机关立案侦查。 对留看守所执行刑罚的罪犯，因犯新罪被撤销假释的，应当根据侦查、审判需要，由犯罪地看守所或者原执行看守所收监执行。"},{"i":317,"n":"第三百一十七条","txt":"公安机关办理未成年人刑事案件，实行教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则。"},{"i":318,"n":"第三百一十八条","txt":"公安机关办理未成年人刑事案件，应当保障未成年人行使其诉讼权利并得到法律帮助，依法保护未成年人的名誉和隐私，尊重其人格尊严。"},{"i":319,"n":"第三百一十九条","txt":"公安机关应当设置专门机构或者配备专职人员办理未成年人刑事案件。 未成年人刑事案件应当由熟悉未成年人身心特点，善于做未成年人思想教育工作，具有一定办案经验的人员办理。"},{"i":320,"n":"第三百二十条","txt":"未成年犯罪嫌疑人没有委托辩护人的，公安机关应当通知法律援助机构指派律师为其提供辩护。"},{"i":321,"n":"第三百二十一条","txt":"公安机关办理未成年人刑事案件时，应当重点查清未成年犯罪嫌疑人实施犯罪行为时是否已满十四周岁、十六周岁、十八周岁的临界年龄。"},{"i":322,"n":"第三百二十二条","txt":"公安机关办理未成年人刑事案件，根据情况可以对未成年犯罪嫌疑人的成长经历、犯罪原因、监护教育等情况进行调查并制作调查报告。 作出调查报告的，在提请批准逮捕、移送审查起诉时，应当结合案情综合考虑，并将调查报告与案卷材料一并移送人民检察院。"},{"i":323,"n":"第三百二十三条","txt":"讯问未成年犯罪嫌疑人，应当通知未成年犯罪嫌疑人的法定代理人到场。无法通知、法定代理人不能到场或者法定代理人是共犯的，也可以通知未成年犯罪嫌疑人的其他成年亲属，所在学校、单位、居住地或者办案单位所在地基层组织或者未成年人保护组织的代表到场，并将有关情况记录在案。到场的法定代理人可以代为行使未成年犯罪嫌疑人的诉讼权利。 到场的法定代理人或者其他人员提出侦查人员在讯问中侵犯未成年人合法权益的，公安机关应当认真核查，依法处理。"},{"i":324,"n":"第三百二十四条","txt":"讯问未成年犯罪嫌疑人应当采取适合未成年人的方式，耐心细致地听取其供述或者辩解，认真审核、查证与案件有关的证据和线索，并针对其思想顾虑、恐惧心理、抵触情绪进行疏导和教育。 讯问女性未成年犯罪嫌疑人，应当有女工作人员在场。"},{"i":325,"n":"第三百二十五条","txt":"讯问笔录应当交未成年犯罪嫌疑人、到场的法定代理人或者其他人员阅读或者向其宣读；对笔录内容有异议的，应当核实清楚，准予更正或者补充。"},{"i":326,"n":"第三百二十六条","txt":"询问未成年被害人、证人，适用本规定第三百二十三条、第三百二十四条、第三百二十五条的规定。 询问未成年被害人、证人，应当以适当的方式进行，注意保护其隐私和名誉，尽可能减少询问频次，避免造成二次伤害。必要时，可以聘请熟悉未成年人身心特点的专业人员协助。"},{"i":327,"n":"第三百二十七条","txt":"对未成年犯罪嫌疑人应当严格限制和尽量减少使用逮捕措施。 未成年犯罪嫌疑人被拘留、逮捕后服从管理、依法变更强制措施不致发生社会危险性，能够保证诉讼正常进行的，公安机关应当依法及时变更强制措施；人民检察院批准逮捕的案件，公安机关应当将变更强制措施情况及时通知人民检察院。"},{"i":328,"n":"第三百二十八条","txt":"对被羁押的未成年人应当与成年人分别关押、分别管理、分别教育，并根据其生理和心理特点在生活和学习方面给予照顾。"},{"i":329,"n":"第三百二十九条","txt":"人民检察院在对未成年人作出附条件不起诉的决定前，听取公安机关意见时，公安机关应当提出书面意见，经县级以上公安机关负责人批准，移送同级人民检察院。"},{"i":330,"n":"第三百三十条","txt":"认为人民检察院作出的附条件不起诉决定有错误的，应当在收到不起诉决定书后七日以内制作要求复议意见书，经县级以上公安机关负责人批准，移送同级人民检察院复议。 要求复议的意见不被接受的，可以在收到人民检察院的复议决定书后七日以内制作提请复核意见书，经县级以上公安机关负责人批准后，连同人民检察院的复议决定书，一并提请上一级人民检察院复核。"},{"i":331,"n":"第三百三十一条","txt":"未成年人犯罪的时候不满十八周岁，被判处五年有期徒刑以下刑罚的，公安机关应当依据人民法院已经生效的判决书，将该未成年人的犯罪记录予以封存。 犯罪记录被封存的，除司法机关为办案需要或者有关单位根据国家规定进行查询外，公安机关不得向其他任何单位和个人提供。 被封存犯罪记录的未成年人，如果发现漏罪，合并被判处五年有期徒刑以上刑罚的，应当对其犯罪记录解除封存。"},{"i":332,"n":"第三百三十二条","txt":"办理未成年人刑事案件，除本节已有规定的以外，按照本规定的其他规定进行。"},{"i":333,"n":"第三百三十三条","txt":"下列公诉案件，犯罪嫌疑人真诚悔罪，通过向被害人赔偿损失、赔礼道歉等方式获得被害人谅解，被害人自愿和解的，经县级以上公安机关负责人批准，可以依法作为当事人和解的公诉案件办理： （一）因民间纠纷引起，涉嫌刑法分则第四章、第五章规定的犯罪案件，可能判处三年有期徒刑以下刑罚的； （二）除渎职犯罪以外的可能判处七年有期徒刑以下刑罚的过失犯罪案件。 犯罪嫌疑人在五年以内曾经故意犯罪的，不得作为当事人和解的公诉案件办理。"},{"i":334,"n":"第三百三十四条","txt":"有下列情形之一的，不属于因民间纠纷引起的犯罪案件： （一）雇凶伤害他人的； （二）涉及黑社会性质组织犯罪的； （三）涉及寻衅滋事的； （四）涉及聚众斗殴的； （五）多次故意伤害他人身体的； （六）其他不宜和解的。"},{"i":335,"n":"第三百三十五条","txt":"双方当事人和解的，公安机关应当审查案件事实是否清楚，被害人是否自愿和解，是否符合规定的条件。 公安机关审查时，应当听取双方当事人的意见，并记录在案；必要时，可以听取双方当事人亲属、当地居民委员会或者村民委员会人员以及其他了解案件情况的相关人员的意见。"},{"i":336,"n":"第三百三十六条","txt":"达成和解的，公安机关应当主持制作和解协议书，并由双方当事人及其他参加人员签名。 当事人中有未成年人的，未成年当事人的法定代理人或者其他成年亲属应当在场。"},{"i":337,"n":"第三百三十七条","txt":"和解协议书应当包括以下内容： （一）案件的基本事实和主要证据； （二）犯罪嫌疑人承认自己所犯罪行，对指控的犯罪事实没有异议，真诚悔罪； （三）犯罪嫌疑人通过向被害人赔礼道歉、赔偿损失等方式获得被害人谅解；涉及赔偿损失的，应当写明赔偿的数额、方式等；提起附带民事诉讼的，由附带民事诉讼原告人撤回附带民事诉讼； （四）被害人自愿和解，请求或者同意对犯罪嫌疑人依法从宽处罚。 和解协议应当及时履行。"},{"i":338,"n":"第三百三十八条","txt":"对达成和解协议的案件，经县级以上公安机关负责人批准，公安机关将案件移送人民检察院审查起诉时，可以提出从宽处理的建议。"},{"i":339,"n":"第三百三十九条","txt":"有下列情形之一，依照刑法规定应当追缴其违法所得及其他涉案财产的，经县级以上公安机关负责人批准，公安机关应当写出没收违法所得意见书，连同相关证据材料一并移送同级人民检察院： （一）恐怖活动犯罪等重大犯罪案件，犯罪嫌疑人逃匿，在通缉一年后不能到案的； （二）犯罪嫌疑人死亡的。 犯罪嫌疑人死亡，现有证据证明其存在违法所得及其他涉案财产应当予以没收的，公安机关可以进行调查。公安机关进行调查，可以依法进行查封、扣押、查询、冻结。"},{"i":340,"n":"第三百四十条","txt":"没收违法所得意见书应当包括以下内容： （一）犯罪嫌疑人的基本情况； （二）犯罪事实和相关的证据材料； （三）犯罪嫌疑人逃匿、被通缉或者死亡的情况； （四）犯罪嫌疑人的违法所得及其他涉案财产的种类、数量、所在地； （五）查封、扣押、冻结的情况等。"},{"i":341,"n":"第三百四十一条","txt":"公安机关将没收违法所得意见书移送人民检察院后，在逃的犯罪嫌疑人自动投案或者被抓获的，公安机关应当及时通知同级人民检察院。"},{"i":342,"n":"第三百四十二条","txt":"公安机关发现实施暴力行为，危害公共安全或者严重危害公民人身安全的犯罪嫌疑人，可能属于依法不负刑事责任的精神病人的，应当对其进行精神病鉴定。"},{"i":343,"n":"第三百四十三条","txt":"对经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能，符合强制医疗条件的，公安机关应当在七日以内写出强制医疗意见书，经县级以上公安机关负责人批准，连同相关证据材料和鉴定意见一并移送同级人民检察院。"},{"i":344,"n":"第三百四十四条","txt":"对实施暴力行为的精神病人，在人民法院决定强制医疗前，经县级以上公安机关负责人批准，公安机关可以采取临时的保护性约束措施。必要时，可以将其送精神病医院接受治疗。"},{"i":345,"n":"第三百四十五条","txt":"采取临时的保护性约束措施时，应当对精神病人严加看管，并注意约束的方式、方法和力度，以避免和防止危害他人和精神病人的自身安全为限度。 对于精神病人已没有继续危害社会可能，解除约束后不致发生社会危险性的，公安机关应当及时解除保护性约束措施。"},{"i":346,"n":"第三百四十六条","txt":"公安机关在异地执行传唤、拘传、拘留、逮捕，开展勘验、检查、搜查、查封、扣押、冻结、讯问等侦查活动，应当向当地公安机关提出办案协作请求，并在当地公安机关协助下进行，或者委托当地公安机关代为执行。 开展查询、询问、辨认等侦查活动或者送达法律文书的，也可以向当地公安机关提出办案协作请求，并按照有关规定进行通报。"},{"i":347,"n":"第三百四十七条","txt":"需要异地公安机关协助的，办案地公安机关应当制作办案协作函件，连同有关法律文书和人民警察证复印件一并提供给协作地公安机关。必要时，可以将前述法律手续传真或者通过公安机关有关信息系统传输至协作地公安机关。 请求协助执行传唤、拘传、拘留、逮捕的，应当提供传唤证、拘传证、拘留证、逮捕证；请求协助开展搜查、查封、扣押、查询、冻结等侦查活动的，应当提供搜查证、查封决定书、扣押决定书、协助查询财产通知书、协助冻结财产通知书；请求协助开展勘验、检查、讯问、询问等侦查活动的，应当提供立案决定书。"},{"i":348,"n":"第三百四十八条","txt":"公安机关应当指定一个部门归口接收协作请求，并进行审核。对符合本规定第三百四十七条规定的协作请求，应当及时交主管业务部门办理。 异地公安机关提出协作请求的，只要法律手续完备，协作地公安机关就应当及时无条件予以配合，不得收取任何形式的费用或者设置其他条件。"},{"i":349,"n":"第三百四十九条","txt":"对协作过程中获取的犯罪线索，不属于自己管辖的，应当及时移交有管辖权的公安机关或者其他有关部门。"},{"i":350,"n":"第三百五十条","txt":"异地执行传唤、拘传的，协作地公安机关应当协助将犯罪嫌疑人传唤、拘传到本市、县公安机关执法办案场所或者到他的住处进行讯问。 异地执行拘留、逮捕的，协作地公安机关应当派员协助执行。"},{"i":351,"n":"第三百五十一条","txt":"已被决定拘留、逮捕的犯罪嫌疑人在逃的，可以通过网上工作平台发布犯罪嫌疑人相关信息、拘留证或者逮捕证。各地公安机关发现网上逃犯的，应当立即组织抓捕。 协作地公安机关抓获犯罪嫌疑人后，应当立即通知办案地公安机关。办案地公安机关应当立即携带法律文书及时提解，提解的侦查人员不得少于二人。 办案地公安机关不能及时到达协作地的，应当委托协作地公安机关在拘留、逮捕后二十四小时以内进行讯问。"},{"i":352,"n":"第三百五十二条","txt":"办案地公安机关请求代为讯问、询问、辨认的，协作地公安机关应当制作讯问、询问、辨认笔录，交被讯问、询问人和辨认人签名、捺指印后，提供给办案地公安机关。 办案地公安机关可以委托协作地公安机关协助进行远程视频讯问、询问，讯问、询问过程应当全程录音录像。"},{"i":353,"n":"第三百五十三条","txt":"办案地公安机关请求协查犯罪嫌疑人的身份、年龄、违法犯罪经历等情况的，协作地公安机关应当在接到请求后七日以内将协查结果通知办案地公安机关；交通十分不便的边远地区，应当在十五日以内将协查结果通知办案地公安机关。 办案地公安机关请求协助调查取证或者查询犯罪信息、资料的，协作地公安机关应当及时协查并反馈。"},{"i":354,"n":"第三百五十四条","txt":"对不履行办案协作程序或者协作职责造成严重后果的，对直接负责的主管人员和其他直接责任人员，应当给予处分；构成犯罪的，依法追究刑事责任。"},{"i":355,"n":"第三百五十五条","txt":"协作地公安机关依照办案地公安机关的协作请求履行办案协作职责所产生的法律责任，由办案地公安机关承担。但是，协作行为超出协作请求范围，造成执法过错的，由协作地公安机关承担相应法律责任。"},{"i":356,"n":"第三百五十六条","txt":"办案地和协作地公安机关对于案件管辖、定性处理等发生争议的，可以进行协商。协商不成的，提请共同的上级公安机关决定。"},{"i":357,"n":"第三百五十七条","txt":"办理外国人犯罪案件，应当严格依照我国法律、法规、规章，维护国家主权和利益，并在对等互惠原则的基础上，履行我国所承担的国际条约义务。"},{"i":358,"n":"第三百五十八条","txt":"外国籍犯罪嫌疑人在刑事诉讼中，享有我国法律规定的诉讼权利，并承担相应的义务。"},{"i":359,"n":"第三百五十九条","txt":"外国籍犯罪嫌疑人的国籍，以其在入境时持用的有效证件予以确认；国籍不明的，由出入境管理部门协助予以查明。国籍确实无法查明的，以无国籍人对待。"},{"i":360,"n":"第三百六十条","txt":"确认外国籍犯罪嫌疑人身份，可以依照有关国际条约或者通过国际刑事警察组织、警务合作渠道办理。确实无法查明的，可以按其自报的姓名移送人民检察院审查起诉。"},{"i":361,"n":"第三百六十一条","txt":"犯罪嫌疑人为享有外交或者领事特权和豁免权的外国人的，应当层报公安部，同时通报同级人民政府外事办公室，由公安部商请外交部通过外交途径办理。"},{"i":362,"n":"第三百六十二条","txt":"公安机关办理外国人犯罪案件，使用中华人民共和国通用的语言文字。犯罪嫌疑人不通晓我国语言文字的，公安机关应当为他翻译；犯罪嫌疑人通晓我国语言文字，不需要他人翻译的，应当出具书面声明。"},{"i":363,"n":"第三百六十三条","txt":"外国人犯罪案件，由犯罪地的县级以上公安机关立案侦查。"},{"i":364,"n":"第三百六十四条","txt":"外国人犯中华人民共和国缔结或者参加的国际条约规定的罪行后进入我国领域内的，由该外国人被抓获地的设区的市一级以上公安机关立案侦查。"},{"i":365,"n":"第三百六十五条","txt":"外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，应当受刑罚处罚的，由该外国人入境地或者入境后居住地的县级以上公安机关立案侦查；该外国人未入境的，由被害人居住地的县级以上公安机关立案侦查；没有被害人或者是对中华人民共和国国家犯罪的，由公安部指定管辖。"},{"i":366,"n":"第三百六十六条","txt":"发生重大或者可能引起外交交涉的外国人犯罪案件的，有关省级公安机关应当及时将案件办理情况报告公安部，同时通报同级人民政府外事办公室。必要时，由公安部商外交部将案件情况通知我国驻外使馆、领事馆。"},{"i":367,"n":"第三百六十七条","txt":"对外国籍犯罪嫌疑人依法作出取保候审、监视居住决定或者执行拘留、逮捕后，应当在四十八小时以内层报省级公安机关，同时通报同级人民政府外事办公室。 重大涉外案件应当在四十八小时以内层报公安部，同时通报同级人民政府外事办公室。"},{"i":368,"n":"第三百六十八条","txt":"对外国籍犯罪嫌疑人依法作出取保候审、监视居住决定或者执行拘留、逮捕后，由省级公安机关根据有关规定，将其姓名、性别、入境时间、护照或者证件号码、案件发生的时间、地点，涉嫌犯罪的主要事实，已采取的强制措施及其法律依据等，通知该外国人所属国家的驻华使馆、领事馆，同时报告公安部。经省级公安机关批准，领事通报任务较重的副省级城市公安局可以直接行使领事通报职能。 外国人在公安机关侦查或者执行刑罚期间死亡的，有关省级公安机关应当通知该外国人国籍国的驻华使馆、领事馆，同时报告公安部。 未在华设立使馆、领事馆的国家，可以通知其代管国家的驻华使馆、领事馆；无代管国家或者代管国家不明的，可以不予通知。"},{"i":369,"n":"第三百六十九条","txt":"外国籍犯罪嫌疑人委托辩护人的，应当委托在中华人民共和国的律师事务所执业的律师。"},{"i":370,"n":"第三百七十条","txt":"公安机关侦查终结前，外国驻华外交、领事官员要求探视被监视居住、拘留、逮捕或者正在看守所服刑的本国公民的，应当及时安排有关探视事宜。犯罪嫌疑人拒绝其国籍国驻华外交、领事官员探视的，公安机关可以不予安排，但应当由其本人提出书面声明。 在公安机关侦查羁押期间，经公安机关批准，外国籍犯罪嫌疑人可以与其近亲属、监护人会见、与外界通信。"},{"i":371,"n":"第三百七十一条","txt":"对判处独立适用驱逐出境刑罚的外国人，省级公安机关在收到人民法院的刑事判决书、执行通知书的副本后，应当指定该外国人所在地的设区的市一级公安机关执行。 被判处徒刑的外国人，主刑执行期满后应当执行驱逐出境附加刑的，省级公安机关在收到执行监狱的上级主管部门转交的刑事判决书、执行通知书副本或者复印件后，应当通知该外国人所在地的设区的市一级公安机关或者指定有关公安机关执行。 我国政府已按照国际条约或者《中华人民共和国外交特权与豁免条例》的规定，对实施犯罪，但享有外交或者领事特权和豁免权的外国人宣布为不受欢迎的人，或者不可接受并拒绝承认其外交或者领事人员身份，责令限期出境的人，无正当理由逾期不自动出境的，由公安部凭外交部公文指定该外国人所在地的省级公安机关负责执行或者监督执行。"},{"i":372,"n":"第三百七十二条","txt":"办理外国人犯罪案件，本章未规定的，适用本规定其他各章的有关规定。"},{"i":373,"n":"第三百七十三条","txt":"办理无国籍人犯罪案件，适用本章的规定。"},{"i":374,"n":"第三百七十四条","txt":"公安部是公安机关进行刑事司法协助和警务合作的中央主管机关，通过有关法律、国际条约、协议规定的联系途径、外交途径或者国际刑事警察组织渠道，接收或者向外国提出刑事司法协助或者警务合作请求。 地方各级公安机关依照职责权限办理刑事司法协助事务和警务合作事务。 其他司法机关在办理刑事案件中，需要外国警方协助的，由其中央主管机关与公安部联系办理。"},{"i":375,"n":"第三百七十五条","txt":"公安机关进行刑事司法协助和警务合作的范围，主要包括犯罪情报信息的交流与合作，调查取证，安排证人作证或者协助调查，查封、扣押、冻结涉案财物，没收、返还违法所得及其他涉案财物，送达刑事诉讼文书，引渡、缉捕和递解犯罪嫌疑人、被告人或者罪犯，以及国际条约、协议规定的其他刑事司法协助和警务合作事宜。"},{"i":376,"n":"第三百七十六条","txt":"在不违背我国法律和有关国际条约、协议的前提下，我国边境地区设区的市一级公安机关和县级公安机关与相邻国家的警察机关，可以按照惯例相互开展执法会晤、人员往来、边境管控、情报信息交流等警务合作，但应当报省级公安机关批准，并报公安部备案；开展其他警务合作的，应当报公安部批准。"},{"i":377,"n":"第三百七十七条","txt":"公安部收到外国的刑事司法协助或者警务合作请求后，应当依据我国法律和国际条约、协议的规定进行审查。对于符合规定的，交有关省级公安机关办理，或者移交其他有关中央主管机关；对于不符合条约或者协议规定的，通过接收请求的途径退回请求方。 对于请求书的签署机关、请求书及所附材料的语言文字、有关办理期限和具体程序等事项，在不违反我国法律基本原则的情况下，可以按照刑事司法协助条约、警务合作协议规定或者双方协商办理。"},{"i":378,"n":"第三百七十八条","txt":"负责执行刑事司法协助或者警务合作的公安机关收到请求书和所附材料后，应当按照我国法律和有关国际条约、协议的规定安排执行，并将执行结果及其有关材料报经省级公安机关审核后报送公安部。 在执行过程中，需要采取查询、查封、扣押、冻结等措施或者返还涉案财物，且符合法律规定的条件的，可以根据我国有关法律和公安部的执行通知办理有关法律手续。 请求书提供的信息不准确或者材料不齐全难以执行的，应当立即通过省级公安机关报请公安部要求请求方补充材料；因其他原因无法执行或者具有应当拒绝协助、合作的情形等不能执行的，应当将请求书和所附材料，连同不能执行的理由通过省级公安机关报送公安部。"},{"i":379,"n":"第三百七十九条","txt":"执行刑事司法协助和警务合作，请求书中附有办理期限的，应当按期完成。未附办理期限的，调查取证应当在三个月以内完成；送达刑事诉讼文书，应当在十日以内完成。不能按期完成的，应当说明情况和理由，层报公安部。"},{"i":380,"n":"第三百八十条","txt":"需要请求外国警方提供刑事司法协助或者警务合作的，应当按照我国有关法律、国际条约、协议的规定提出刑事司法协助或者警务合作请求书，所附文件及相应译文，经省级公安机关审核后报送公安部。"},{"i":381,"n":"第三百八十一条","txt":"需要通过国际刑事警察组织查找或者缉捕犯罪嫌疑人、被告人或者罪犯，查询资料、调查取证的，应当提出申请层报国际刑事警察组织中国国家中心局。"},{"i":382,"n":"第三百八十二条","txt":"公安机关需要外国协助安排证人、鉴定人来中华人民共和国作证或者通过视频、音频作证，或者协助调查的，应当制作刑事司法协助请求书并附相关材料，经公安部审核同意后，由对外联系机关及时向外国提出请求。 来中华人民共和国作证或者协助调查的证人、鉴定人离境前，公安机关不得就其入境前实施的犯罪进行追究；除因入境后实施违法犯罪而被采取强制措施的以外，其人身自由不受限制。 证人、鉴定人在条约规定的期限内或者被通知无需继续停留后十五日内没有离境的，前款规定不再适用，但是由于不可抗力或者其他特殊原因未能离境的除外。"},{"i":383,"n":"第三百八十三条","txt":"公安机关提供或者请求外国提供刑事司法协助或者警务合作，应当收取或者支付费用的，根据有关国际条约、协议的规定，或者按照对等互惠的原则协商办理。"},{"i":384,"n":"第三百八十四条","txt":"办理引渡案件，依照《中华人民共和国引渡法》等法律规定和有关条约执行。"},{"i":385,"n":"第三百八十五条","txt":"本规定所称“危害国家安全犯罪”，包括刑法分则第一章规定的危害国家安全罪以及危害国家安全的其他犯罪；“恐怖活动犯罪”，包括以制造社会恐慌、危害公共安全或者胁迫国家机关、国际组织为目的，采取暴力、破坏、恐吓等手段，造成或者意图造成人员伤亡、重大财产损失、公共设施损坏、社会秩序混乱等严重社会危害的犯罪，以及煽动、资助或者以其他方式协助实施上述活动的犯罪。"},{"i":386,"n":"第三百八十六条","txt":"当事人及其法定代理人、诉讼代理人、辩护律师提出的复议复核请求，由公安机关法制部门办理。 办理刑事复议、复核案件的具体程序，适用《公安机关办理刑事复议复核案件程序规定》。"},{"i":387,"n":"第三百八十七条","txt":"公安机关可以使用电子签名、电子指纹捺印技术制作电子笔录等材料，可以使用电子印章制作法律文书。对案件当事人进行电子签名、电子指纹捺印的过程，公安机关应当同步录音录像。"},{"i":388,"n":"第三百八十八条","txt":"本规定自2013年1月1日起施行。1998年5月14日发布的《公安机关办理刑事案件程序规定》（公安部令第35号）和2007年10月25日发布的《公安机关办理刑事案件程序规定修正案》（公安部令第95号）同时废止。"}],"gonganjiguanbanliguojiapeichanganjianchengxuguidinb83652":[{"i":1,"n":"第一条","txt":"为了规范公安机关办理国家赔偿案件程序，促进公安机关在办理国家赔偿案件中正确履行职责，保障公民、法人和其他组织享有依法取得国家赔偿的权利，根据《中华人民共和国国家赔偿法》（以下简称《国家赔偿法》）和《国家赔偿费用管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国家赔偿案件，是指行政赔偿案件、刑事赔偿案件和刑事赔偿复议案件。"},{"i":3,"n":"第三条","txt":"公安机关办理国家赔偿案件应当坚持实事求是、依法公正、规范高效、有错必纠的原则。"},{"i":4,"n":"第四条","txt":"公安机关法制部门是办理国家赔偿案件的主管部门，依法履行下列职责： （一）接收赔偿申请，审查赔偿请求和事实理由，履行相关法律手续； （二）接收刑事赔偿复议申请，审查复议请求和事实理由，履行相关法律手续； （三）接收并审查支付赔偿费用申请，接收并审查对支付赔偿费用申请不予受理决定的复核申请； （四）参加人民法院审理赔偿案件活动； （五）提出追偿赔偿费用意见，接收并审查对追偿赔偿费用不服的申诉； （六）其他应当履行的职责。"},{"i":5,"n":"第五条","txt":"公安机关相关部门应当按照职责分工，配合法制部门共同做好国家赔偿案件办理工作。 执法办案部门负责提供赔偿请求所涉职权行为的情况及相关材料，与法制部门共同研究案情，共同参加人民法院审理赔偿案件活动。 装备财务（警务保障）部门负责向财政部门申请支付赔偿费用，向赔偿请求人支付赔偿费用，将追偿的赔偿费用上缴财政部门。"},{"i":6,"n":"第六条","txt":"赔偿请求人申请赔偿，应当向赔偿义务机关提出。 公安机关及其工作人员行使职权侵犯公民、法人或者其他组织合法权益，造成损害的，该公安机关为赔偿义务机关。 公安机关内设机构和派出机构及其工作人员有前款情形的，所属公安机关为赔偿义务机关。 看守所、拘留所、强制隔离戒毒所等羁押监管场所及其工作人员有第二款情形的，主管公安机关为赔偿义务机关。"},{"i":7,"n":"第七条","txt":"申请赔偿应当提交赔偿申请书，载明受害人的基本情况、赔偿请求、事实根据和理由、申请日期，并由赔偿请求人签名、盖章或者捺指印。 赔偿请求人书写确有困难的，可以口头申请。赔偿义务机关法制部门应当制作笔录，经赔偿请求人确认无误后签名、盖章或者捺指印。"},{"i":8,"n":"第八条","txt":"申请赔偿除提交赔偿申请书外，还应当提交下列材料： （一）赔偿请求人的身份证明材料。赔偿请求人不是受害人本人的，提供与受害人关系的证明。赔偿请求人委托他人代理赔偿请求事项的，提交授权委托书，以及代理人的身份证明；代理人为律师的，同时提交律师执业证明及律师事务所证明； （二）赔偿请求所涉职权行为的法律文书或者其他证明材料； （三）赔偿请求所涉职权行为造成损害及其程度的证明材料。 不能提交前款第二项、第三项所列材料的，赔偿请求人应当书面说明情况和理由。"},{"i":9,"n":"第九条","txt":"赔偿义务机关法制部门收到当面递交赔偿申请的，应当当场出具接收凭证。 赔偿义务机关其他部门遇有赔偿请求人当面递交或者口头提出赔偿申请的，应当当场联系法制部门接收；收到以邮寄或者其他方式递交的赔偿申请，应当自收到之日起二个工作日内转送法制部门。"},{"i":10,"n":"第十条","txt":"赔偿义务机关法制部门收到赔偿申请后，应当在五个工作日内予以审查，并分别作出下列处理： （一）申请材料不齐全或者表述不清楚的，经本部门负责人批准，一次性书面告知赔偿请求人需要补正的全部事项和合理的补正期限； （二）不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人； （三）除第一项、第二项情形外，自赔偿义务机关法制部门收到申请之日起即为受理。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，赔偿申请不符合申请条件： （一）本机关不是赔偿义务机关的； （二）赔偿请求人不适格的； （三）赔偿请求事项不属于国家赔偿范围的； （四）超过请求时效且无正当理由的； （五）基于同一事实的赔偿请求已经通过申请行政复议或者提起行政诉讼提出，正在审理或者已经作出予以赔偿、不予赔偿结论的； （六）赔偿申请应当在终止追究刑事责任后提出，有证据证明尚未终止追究刑事责任的。 赔偿申请受理后，发现有前款情形之一的，赔偿义务机关应当在受理之日起两个月内，经本机关负责人批准，驳回赔偿申请。 对于第一款第六项情形，决定不予受理或者驳回申请的，同时告知赔偿请求人在终止追究刑事责任后重新申请。"},{"i":12,"n":"第十二条","txt":"赔偿请求人在补正期限内对赔偿申请予以补正的，赔偿义务机关法制部门应当自收到之日起五个工作日内予以审查。不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人。未书面告知不予受理的，自赔偿义务机关法制部门收到补正材料之日起即为受理。 赔偿义务机关法制部门在补正期限届满后第十个工作日仍未收到补正材料的，应当自该日起五个工作日内，对已经提交的赔偿申请予以审查。不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人。未书面告知不予受理的，自补正期限届满后第十个工作日起即为受理。"},{"i":13,"n":"第十三条","txt":"赔偿义务机关对赔偿请求已作出处理，赔偿请求人无正当理由基于同一事实再次申请赔偿的，不再处理。"},{"i":14,"n":"第十四条","txt":"赔偿义务机关法制部门应当自赔偿申请受理之日起五个工作日内，将申请材料副本送赔偿请求所涉执法办案部门。执法办案部门应当自收到之日起十个工作日内向法制部门作出书面答复，并提供赔偿请求所涉职权行为的证据、依据和其他材料。"},{"i":15,"n":"第十五条","txt":"赔偿义务机关应当全面审查赔偿请求的事实、证据和理由。重点查明下列事项： （一）赔偿请求所涉职权行为的合法性； （二）侵害事实、损害后果及因果关系； （三）是否具有国家不承担赔偿责任的法定情形。 除前款所列查明事项外，赔偿义务机关还应当按照本规定第十六条至第十九条的规定，分别重点审查有关事项。"},{"i":16,"n":"第十六条","txt":"赔偿请求人主张人身自由权赔偿的，重点审查赔偿请求所涉限制人身自由的起止时间。"},{"i":17,"n":"第十七条","txt":"赔偿请求人主张生命健康权赔偿的，重点审查下列事项： （一）诊断证明、医疗费用凭据，以及护理、康复、后续治疗的证明； （二）死亡证明书，伤残、部分或者全部丧失劳动能力的鉴定意见。 赔偿请求提出因误工减少收入的，还应当审查收入证明、误工证明等。受害人死亡或者全部丧失劳动能力的，还应当审查其是否扶养未成年人或者其他无劳动能力人，以及所承担的扶养义务。"},{"i":18,"n":"第十八条","txt":"赔偿请求人主张财产权赔偿的，重点审查下列事项： （一）查封、扣押、冻结、收缴、追缴、没收的财物不能恢复原状或者灭失的，财物损失发生时的市场价格；查封、扣押、冻结、收缴、追缴、没收的财物被拍卖或者变卖的，拍卖或者变卖及其价格的证明材料，以及变卖时的市场价格； （二）停产停业期间必要经常性开支的证明材料。"},{"i":19,"n":"第十九条","txt":"赔偿请求人主张精神损害赔偿的，重点审查下列事项： （一）是否存在《国家赔偿法》第三条或者第十七条规定的侵犯人身权行为； （二）精神损害事实及后果； （三）侵犯人身权行为与精神损害事实及后果的因果关系。"},{"i":20,"n":"第二十条","txt":"赔偿审查期间，赔偿请求人可以变更赔偿请求。赔偿义务机关认为赔偿请求人提出的赔偿请求事项不全或者不准确的，可以告知赔偿请求人在审查期限届满前变更赔偿请求。"},{"i":21,"n":"第二十一条","txt":"赔偿审查期间，赔偿义务机关法制部门可以调查核实情况，收集有关证据。有关单位和人员应当予以配合。"},{"i":22,"n":"第二十二条","txt":"对赔偿请求所涉职权行为，有权机关已经作出生效法律结论，该结论所采信的证据可以作为赔偿审查的证据。"},{"i":23,"n":"第二十三条","txt":"赔偿审查期间，有下列情形之一的，经赔偿义务机关负责人批准，中止审查并书面告知有关当事人： （一）作为赔偿请求人的公民丧失行为能力，尚未确定法定代理人的； （二）作为赔偿请求人的公民下落不明或者被宣告失踪的； （三）作为赔偿请求人的公民死亡，其继承人和其他有扶养关系的亲属尚未确定是否参加赔偿审查的； （四）作为赔偿请求人的法人或者其他组织终止，尚未确定权利义务承受人，或者权利义务承受人尚未确定是否参加赔偿审查的； （五）赔偿请求人因不可抗力不能参加赔偿审查的； （六）赔偿审查涉及法律适用问题，需要有权机关作出解释或者确认的； （七）赔偿审查需要以其他尚未办结案件的结果为依据的； （八）其他需要中止审查的情形。 中止审查的情形消除后，应当在二个工作日内恢复审查，并书面告知有关当事人。 中止审查不符合第一款规定的，应当立即恢复审查。不恢复审查的，上一级公安机关应当责令恢复审查。"},{"i":24,"n":"第二十四条","txt":"赔偿审查期间，有下列情形之一的，经赔偿义务机关负责人批准，终结审查并书面告知有关当事人： （一）作为赔偿请求人的公民死亡，没有继承人和其他有扶养关系的亲属，或者继承人和其他有扶养关系的亲属放弃要求赔偿权利的； （二）作为赔偿请求人的法人或者其他组织终止，没有权利义务承受人，或者权利义务承受人放弃要求赔偿权利的； （三）赔偿请求人自愿撤回赔偿申请的。 前款第一项中的继承人和其他有扶养关系的亲属、第二项中的权利义务承受人、第三项中的赔偿请求人为数人，非经全体同意放弃要求赔偿权利或者撤回赔偿申请的，不得终结审查。"},{"i":25,"n":"第二十五条","txt":"对受理的赔偿申请，赔偿义务机关应当自受理之日起两个月内，经本机关负责人批准，分别作出下列决定： （一）违法行使职权造成侵权的事实清楚，应当予以赔偿的，作出予以赔偿的决定，并载明赔偿方式、项目和数额； （二）违法行使职权造成侵权的事实不成立，或者具有国家不承担赔偿责任法定情形的，作出不予赔偿的决定。 按照前款第一项作出决定，不限于赔偿请求人主张的赔偿方式、项目和数额。"},{"i":26,"n":"第二十六条","txt":"在查清事实的基础上，对应当予以赔偿的，赔偿义务机关应当充分听取赔偿请求人的意见，可以就赔偿方式、项目和数额在法定范围内进行协商。 协商应当遵循自愿、合法原则。协商达成一致的，赔偿义务机关应当按照协商结果作出赔偿决定；赔偿请求人不同意协商，或者协商未达成一致，或者赔偿请求人在赔偿决定作出前反悔的，赔偿义务机关应当依法作出赔偿决定。"},{"i":27,"n":"第二十七条","txt":"侵犯公民人身自由的每日赔偿金，按照作出决定时的国家上年度职工日平均工资计算。 作出决定时国家上年度职工日平均工资尚未公布的，以公布的最近年度职工日平均工资为准。"},{"i":28,"n":"第二十八条","txt":"执行行政拘留或者采取刑事拘留措施被决定赔偿的，计算赔偿金的天数按照实际羁押的天数计算。羁押时间不足一日的，按照一日计算。"},{"i":29,"n":"第二十九条","txt":"依法应当予以赔偿但赔偿请求人所受损害的程度因客观原因无法确定的，赔偿数额应当结合赔偿请求人的主张和在案证据，运用逻辑推理和生活经验、生活常识等酌情确定。"},{"i":30,"n":"第三十条","txt":"赔偿请求人主张精神损害赔偿的，作出决定应当载明是否存在精神损害并承担赔偿责任。承担精神损害赔偿责任的，应当载明消除影响、恢复名誉、赔礼道歉等承担方式；支付精神损害抚慰金的，应当载明具体数额。 精神损害抚慰金数额的确定，可以参照人民法院审理国家赔偿案件适用精神损害赔偿的规定，综合考虑精神损害事实和严重后果，侵权手段、方式等具体情节，纠错环节及过程，赔偿请求人住所地或者经常居住地平均生活水平，赔偿义务机关所在地平均生活水平等因素。法律法规对精神损害抚慰金的数额作出规定的，从其规定。"},{"i":31,"n":"第三十一条","txt":"赔偿义务机关对行政赔偿请求作出不予受理、驳回申请、终结审查、予以赔偿、不予赔偿决定，或者逾期未作决定，赔偿请求人不服的，可以依照《国家赔偿法》第十四条规定提起行政赔偿诉讼。 赔偿义务机关对刑事赔偿请求作出不予受理、驳回申请、终结审查、予以赔偿、不予赔偿决定，或者逾期未作决定，赔偿请求人不服的，可以依照《国家赔偿法》第二十四条规定申请刑事赔偿复议。"},{"i":32,"n":"第三十二条","txt":"赔偿请求人申请刑事赔偿复议，应当向赔偿义务机关的上一级公安机关提出。赔偿义务机关是公安部的，向公安部提出。"},{"i":33,"n":"第三十三条","txt":"申请刑事赔偿复议应当提交复议申请书，载明受害人的基本情况、复议请求、事实根据和理由、申请日期，并由赔偿请求人签名、盖章或者捺指印。 赔偿请求人书写确有困难的，可以口头申请。复议机关法制部门应当制作笔录，经赔偿请求人确认无误后签名、盖章或者捺指印。"},{"i":34,"n":"第三十四条","txt":"申请刑事赔偿复议除提交复议申请书外，还应当提交下列材料： （一）赔偿请求人的身份证明材料。赔偿请求人不是受害人本人的，提供与受害人关系的证明。赔偿请求人委托他人代理复议事项的，提交授权委托书，以及代理人的身份证明。代理人为律师的，同时提交律师执业证明及律师事务所证明； （二）向赔偿义务机关提交的赔偿申请材料及申请赔偿的证明材料； （三）赔偿义务机关就赔偿申请作出的决定书。赔偿义务机关逾期未作决定的除外。"},{"i":35,"n":"第三十五条","txt":"复议机关法制部门收到当面递交复议申请的，应当当场出具接收凭证。 复议机关其他部门遇有赔偿请求人当面递交或者口头提出复议申请的，应当当场联系法制部门接收；收到以其他方式递交复议申请的，应当自收到之日起二个工作日内转送法制部门。"},{"i":36,"n":"第三十六条","txt":"复议机关法制部门收到复议申请后，应当在五个工作日内予以审查，并分别作出下列处理： （一）申请材料不齐全或者表述不清楚的，经本部门负责人批准，一次性书面告知赔偿请求人需要补正的全部事项和合理的补正期限； （二）不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人； （三）除第一项、第二项情形外，自复议机关法制部门收到申请之日起即为受理。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，复议申请不符合申请条件： （一）本机关不是复议机关的； （二）赔偿请求人申请复议不适格的； （三）不属于复议范围的; （四）超过申请复议法定期限且无正当理由的； （五）申请复议前未向赔偿义务机关申请赔偿的； （六）赔偿义务机关对赔偿申请未作出决定但审查期限尚未届满的。 复议申请受理后，发现有前款情形之一的，复议机关应当在受理之日起两个月内，经本机关负责人批准，驳回复议申请。"},{"i":38,"n":"第三十八条","txt":"赔偿请求人在补正期限内对复议申请予以补正的，复议机关法制部门应当自收到之日起五个工作日内予以审查。不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人。未书面告知不予受理的，自复议机关法制部门收到补正材料之日起即为受理。 复议机关法制部门在补正期限届满后第十个工作日仍未收到补正材料的，应当自该日起五个工作日内，对已经提交的复议申请予以审查。不符合申请条件的，经本机关负责人批准，决定不予受理并书面告知赔偿请求人。未书面告知不予受理的，自补正期限届满后第十个工作日之日起即为受理。"},{"i":39,"n":"第三十九条","txt":"复议机关对复议申请已作出处理，赔偿请求人无正当理由基于同一事实再次申请复议的，不再处理。"},{"i":40,"n":"第四十条","txt":"复议机关法制部门应当自复议申请受理之日起五个工作日内，将申请材料副本送赔偿义务机关。赔偿义务机关应当自收到之日起十个工作日内向复议机关作出书面答复，并提供相关证据、依据和其他材料。"},{"i":41,"n":"第四十一条","txt":"复议机关应当全面审查赔偿义务机关是否按照本规定第二章的规定对赔偿申请作出处理。"},{"i":42,"n":"第四十二条","txt":"赔偿请求人申请复议时变更向赔偿义务机关提出的赔偿请求，或者在复议审查期间变更复议请求的，复议机关应当予以审查。 复议机关认为赔偿请求人提出的复议请求事项不全或者不准确的，可以告知赔偿请求人在审查期限届满前变更复议请求。"},{"i":43,"n":"第四十三条","txt":"赔偿请求人和赔偿义务机关对自己的主张负有举证责任。没有证据或者证据不足以证明事实主张的，由负有举证责任的一方承担不利后果。 赔偿义务机关对其职权行为的合法性，以及《国家赔偿法》第二十六条第二款规定的情形负有举证责任。赔偿请求人可以提供证明赔偿义务机关职权行为违法的证据，但不因此免除赔偿义务机关的举证责任。"},{"i":44,"n":"第四十四条","txt":"复议审查期间，复议机关法制部门可以调查核实情况，收集有关证据。有关单位和人员应当予以配合。"},{"i":45,"n":"第四十五条","txt":"复议审查期间，有下列情形之一的，经复议机关负责人批准，中止审查并书面告知有关当事人： （一）作为赔偿请求人的公民丧失行为能力，尚未确定法定代理人的； （二）作为赔偿请求人的公民下落不明或者被宣告失踪的； （三）作为赔偿请求人的公民死亡，其继承人和其他有扶养关系的亲属尚未确定是否参加复议审查的； （四）作为赔偿请求人的法人或者其他组织终止，尚未确定权利义务承受人，或者权利义务承受人尚未确定是否参加复议审查的； （五）赔偿请求人因不可抗力不能参加复议审查的； （六）复议审查涉及法律适用问题，需要有权机关作出解释或者确认的； （七）复议审查需要以其他尚未办结案件的结果为依据的； （八）其他需要中止审查的情形。 中止审查的情形消除后，应当在二个工作日内恢复审查，并书面告知有关当事人。 中止审查不符合第一款规定的，应当立即恢复审查。不恢复审查的，上一级公安机关应当责令恢复审查。"},{"i":46,"n":"第四十六条","txt":"复议审查期间，有下列情形之一的，经复议机关负责人批准，终结审查并书面告知有关当事人： （一）作为赔偿请求人的公民死亡，没有继承人和其他有扶养关系的亲属，或者继承人和其他有扶养关系的亲属放弃复议权利的； （二）作为赔偿请求人的法人或者其他组织终止，没有权利义务承受人，或者权利义务承受人放弃复议权利的； （三）赔偿请求人自愿撤回复议申请的。 前款第一项中的继承人和其他有扶养关系的亲属、第二项中的权利义务承受人、第三项中的赔偿请求人为数人，非经全体同意放弃复议权利或者撤回复议申请的，不得终结审查。"},{"i":47,"n":"第四十七条","txt":"对受理的复议申请，复议机关应当自受理之日起两个月内，经本机关负责人批准作出决定。"},{"i":48,"n":"第四十八条","txt":"复议机关可以组织赔偿义务机关与赔偿请求人就赔偿方式、项目和数额在法定范围内进行调解。 调解应当遵循自愿、合法的原则。经调解达成一致的，复议机关应当按照调解结果作出复议决定。赔偿请求人或者赔偿义务机关不同意调解，或者调解未达成一致，或者一方在复议决定作出前反悔的，复议机关应当依法作出复议决定。"},{"i":49,"n":"第四十九条","txt":"对赔偿义务机关作出的予以赔偿或者不予赔偿决定，分别作出下列决定： （一）认定事实清楚，适用法律正确，符合法定程序的，予以维持； （二）认定事实清楚，适用法律正确，但违反法定程序的，维持决定结论并确认程序违法； （三）认定事实不清、适用法律错误或者据以作出决定的法定事由发生变化的，依法重新作出决定或者责令限期重作。"},{"i":50,"n":"第五十条","txt":"对赔偿义务机关作出的不予受理、驳回申请、终结审查决定，分别作出下列决定： （一）符合规定情形和程序的，予以维持； （二）符合规定情形，但违反规定程序的，维持决定结论并确认程序违法； （三）不符合规定情形，或者据以作出决定的法定事由发生变化的，责令继续审查或者依法重新作出决定。"},{"i":51,"n":"第五十一条","txt":"赔偿义务机关逾期未作出决定的，责令限期作出决定或者依法作出决定。"},{"i":52,"n":"第五十二条","txt":"复议机关作出不予受理、驳回申请、终结审查、复议决定，或者逾期未作决定，赔偿请求人不服的，可以依照《国家赔偿法》第二十五条规定，向复议机关所在地的同级人民法院赔偿委员会申请作出赔偿决定。"},{"i":53,"n":"第五十三条","txt":"赔偿义务机关必须执行生效赔偿决定、复议决定、判决和调解。"},{"i":54,"n":"第五十四条","txt":"生效赔偿决定、复议决定、判决和调解按照下列方式执行： （一）要求返还财物或者恢复原状的，赔偿请求所涉赔偿义务机关执法办案部门应当在三十日内办结。情况复杂的，经本机关负责人批准，可以延长三十日。 （二）要求支付赔偿金的，赔偿义务机关法制部门应当依照《国家赔偿费用管理条例》的规定，将生效的赔偿决定书、复议决定书、判决书和调解书等有关材料提供给装备财务（警务保障）部门，装备财务（警务保障）部门报经本机关负责人批准后，依照预算管理权限向财政部门提出书面支付申请并提供有关材料。 （三）要求为赔偿请求人消除影响、恢复名誉、赔礼道歉的，赔偿义务机关或者其负责人应当及时执行。"},{"i":55,"n":"第五十五条","txt":"财政部门告知赔偿义务机关补正申请材料的，赔偿义务机关装备财务（警务保障）部门应当会同法制部门自收到告知之日起五个工作日内按照要求补正材料并提交财政部门。"},{"i":56,"n":"第五十六条","txt":"财政部门向赔偿义务机关支付赔偿金的，赔偿义务机关装备财务（警务保障）部门应当及时向赔偿请求人足额支付赔偿金，不得拖延、截留。"},{"i":57,"n":"第五十七条","txt":"赔偿义务机关支付赔偿金后，应当依照《国家赔偿法》第十六条第一款、第三十一条第一款的规定，向责任人员追偿部分或者全部赔偿费用。"},{"i":58,"n":"第五十八条","txt":"追偿赔偿费用由赔偿义务机关法制部门会同赔偿请求所涉执法办案部门等有关部门提出追偿意见，经本机关主要负责人批准，由装备财务（警务保障）部门书面通知有预算管理权限的财政部门，并责令被追偿人缴纳追偿赔偿费用。 追偿数额的确定，应当综合考虑赔偿数额，以及被追偿人过错程度、损害后果等因素确定，并为被追偿人及其扶养的家属保留必需的生活费用。"},{"i":59,"n":"第五十九条","txt":"被追偿人对追偿赔偿费用不服的，可以向赔偿义务机关或者其上一级公安机关申诉。"},{"i":60,"n":"第六十条","txt":"赔偿义务机关装备财务（警务保障）部门应当依照相关规定，将追偿的赔偿费用上缴有预算管理权限的财政部门。"},{"i":61,"n":"第六十一条","txt":"有下列情形之一的，对直接负责的主管人员或者其他直接责任人员，依照有关规定给予行政纪律处分或者作出其他处理： （一）未按照本规定对赔偿申请、复议申请作出处理的； （二）不配合或者阻挠国家赔偿办案人员调查取证，不提供有关情况和证明材料，或者提供虚假材料的； （三）未按照本规定执行生效赔偿决定、复议决定、判决和调解的； （四）未按照本规定上缴追偿赔偿费用的； （五）办理国家赔偿案件的其他渎职、失职行为。"},{"i":62,"n":"第六十二条","txt":"公安机关工作人员在办理国家赔偿案件中，徇私舞弊，打击报复赔偿请求人的，依照有关规定给予行政纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"下列情形所需时间，不计入国家赔偿审查期限： （一）向赔偿请求人调取证据材料的； （二）涉及专门事项委托鉴定、评估的。 赔偿请求人在国家赔偿审查期间变更请求的，审查期限从公安机关收到之日起重新计算。"},{"i":64,"n":"第六十四条","txt":"公安机关按照本规定制作的法律文书，应当加盖本机关印章或者国家赔偿专用章。中止审查、终结审查、驳回申请、赔偿决定、复议决定的法律文书，应当自作出之日起十日内送达。"},{"i":65,"n":"第六十五条","txt":"本规定自2018年10月1日起施行。2014年6月1日施行的《公安机关办理国家赔偿案件程序规定》同时废止。"}],"gonganjiguanbanlixingzhenganjianchengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范公安机关办理行政案件程序，保障公安机关在办理行政案件中正确履行职责，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国行政强制法》《中华人民共和国治安管理处罚法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称行政案件，是指公安机关依照法律、法规和规章的规定对违法行为人决定行政处罚以及强制隔离戒毒等处理措施的案件。 本规定所称公安机关，是指县级以上公安机关、公安派出所、依法具有独立执法主体资格的公安机关业务部门以及出入境边防检查站。"},{"i":3,"n":"第三条","txt":"办理行政案件应当以事实为根据，以法律为准绳。"},{"i":4,"n":"第四条","txt":"办理行政案件应当遵循合法、公正、公开、及时的原则，尊重和保障人权，保护公民的人格尊严。"},{"i":5,"n":"第五条","txt":"办理行政案件应当坚持教育与处罚相结合的原则，教育公民、法人和其他组织自觉守法。"},{"i":6,"n":"第六条","txt":"办理未成年人的行政案件，应当根据未成年人的身心特点，保障其合法权益。"},{"i":7,"n":"第七条","txt":"办理行政案件，在少数民族聚居或者多民族共同居住的地区，应当使用当地通用的语言进行询问。对不通晓当地通用语言文字的当事人，应当为他们提供翻译。"},{"i":8,"n":"第八条","txt":"公安机关及其人民警察在办理行政案件时，对涉及的国家秘密、商业秘密或者个人隐私，应当保密。"},{"i":9,"n":"第九条","txt":"公安机关人民警察在办案中玩忽职守、徇私舞弊、滥用职权、索取或者收受他人财物的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"行政案件由违法行为地的公安机关管辖。由违法行为人居住地公安机关管辖更为适宜的，可以由违法行为人居住地公安机关管辖，但是涉及卖淫、嫖娼、赌博、毒品的案件除外。 违法行为地包括违法行为发生地和违法结果发生地。违法行为发生地，包括违法行为的实施地以及开始地、途经地、结束地等与违法行为有关的地点；违法行为有连续、持续或者继续状态的，违法行为连续、持续或者继续实施的地方都属于违法行为发生地。违法结果发生地，包括违法对象被侵害地、违法所得的实际取得地、藏匿地、转移地、使用地、销售地。 居住地包括户籍所在地、经常居住地。经常居住地是指公民离开户籍所在地最后连续居住一年以上的地方，但在医院住院就医的除外。 移交违法行为人居住地公安机关管辖的行政案件，违法行为地公安机关在移交前应当及时收集证据，并配合违法行为人居住地公安机关开展调查取证工作。"},{"i":11,"n":"第十一条","txt":"针对或者利用网络实施的违法行为，用于实施违法行为的网站服务器所在地、网络接入地以及网站建立者或者管理者所在地，被侵害的网络及其运营者所在地，违法过程中违法行为人、被侵害人使用的网络及其运营者所在地，被侵害人被侵害时所在地，以及被侵害人财产遭受损失地公安机关可以管辖。"},{"i":12,"n":"第十二条","txt":"行驶中的客车上发生的行政案件，由案发后客车最初停靠地公安机关管辖；必要时，始发地、途经地、到达地公安机关也可以管辖。"},{"i":13,"n":"第十三条","txt":"行政案件由县级公安机关及其公安派出所、依法具有独立执法主体资格的公安机关业务部门以及出入境边防检查站按照法律、行政法规、规章授权和管辖分工办理，但法律、行政法规、规章规定由设区的市级以上公安机关办理的除外。"},{"i":14,"n":"第十四条","txt":"几个公安机关都有权管辖的行政案件，由最初受理的公安机关管辖。必要时，可以由主要违法行为地公安机关管辖。"},{"i":15,"n":"第十五条","txt":"对管辖权发生争议的，报请共同的上级公安机关指定管辖。 对于重大、复杂的案件，上级公安机关可以直接办理或者指定管辖。 上级公安机关直接办理或者指定管辖的，应当书面通知被指定管辖的公安机关和其他有关的公安机关。 原受理案件的公安机关自收到上级公安机关书面通知之日起不再行使管辖权，并立即将案卷材料移送被指定管辖的公安机关或者办理的上级公安机关，及时书面通知当事人。"},{"i":16,"n":"第十六条","txt":"铁路公安机关管辖列车上，火车站工作区域内，铁路系统的机关、厂、段、所、队等单位内发生的行政案件，以及在铁路线上放置障碍物或者损毁、移动铁路设施等可能影响铁路运输安全、盗窃铁路设施的行政案件。对倒卖、伪造、变造火车票案件，由最初受理的铁路或者地方公安机关管辖。必要时，可以移送主要违法行为发生地的铁路或者地方公安机关管辖。 交通公安机关管辖港航管理机构管理的轮船上、港口、码头工作区域内和港航系统的机关、厂、所、队等单位内发生的行政案件。 民航公安机关管辖民航管理机构管理的机场工作区域以及民航系统的机关、厂、所、队等单位内和民航飞机上发生的行政案件。 国有林区的森林公安机关管辖林区内发生的行政案件。 海关缉私机构管辖阻碍海关缉私警察依法执行职务的治安案件。"},{"i":17,"n":"第十七条","txt":"公安机关负责人、办案人民警察有下列情形之一的，应当自行提出回避申请，案件当事人及其法定代理人有权要求他们回避： （一）是本案的当事人或者当事人近亲属的； （二）本人或者其近亲属与本案有利害关系的； （三）与本案当事人有其他关系，可能影响案件公正处理的。"},{"i":18,"n":"第十八条","txt":"公安机关负责人、办案人民警察提出回避申请的，应当说明理由。"},{"i":19,"n":"第十九条","txt":"办案人民警察的回避，由其所属的公安机关决定；公安机关负责人的回避，由上一级公安机关决定。"},{"i":20,"n":"第二十条","txt":"当事人及其法定代理人要求公安机关负责人、办案人民警察回避的，应当提出申请，并说明理由。口头提出申请的，公安机关应当记录在案。"},{"i":21,"n":"第二十一条","txt":"对当事人及其法定代理人提出的回避申请，公安机关应当在收到申请之日起二日内作出决定并通知申请人。"},{"i":22,"n":"第二十二条","txt":"公安机关负责人、办案人民警察具有应当回避的情形之一，本人没有申请回避，当事人及其法定代理人也没有申请其回避的，有权决定其回避的公安机关可以指令其回避。"},{"i":23,"n":"第二十三条","txt":"在行政案件调查过程中，鉴定人和翻译人员需要回避的，适用本章的规定。 鉴定人、翻译人员的回避，由指派或者聘请的公安机关决定。"},{"i":24,"n":"第二十四条","txt":"在公安机关作出回避决定前，办案人民警察不得停止对行政案件的调查。 作出回避决定后，公安机关负责人、办案人民警察不得再参与该行政案件的调查和审核、审批工作。"},{"i":25,"n":"第二十五条","txt":"被决定回避的公安机关负责人、办案人民警察、鉴定人和翻译人员，在回避决定作出前所进行的与案件有关的活动是否有效，由作出回避决定的公安机关根据是否影响案件依法公正处理等情况决定。"},{"i":26,"n":"第二十六条","txt":"可以用于证明案件事实的材料，都是证据。公安机关办理行政案件的证据包括： （一）物证； （二）书证； （三）被侵害人陈述和其他证人证言； （四）违法嫌疑人的陈述和申辩； （五）鉴定意见； （六）勘验、检查、辨认笔录，现场笔录； （七）视听资料、电子数据。 证据必须经过查证属实，才能作为定案的根据。"},{"i":27,"n":"第二十七条","txt":"公安机关必须依照法定程序，收集能够证实违法嫌疑人是否违法、违法情节轻重的证据。 严禁刑讯逼供和以威胁、欺骗等非法方法收集证据。采用刑讯逼供等非法方法收集的违法嫌疑人的陈述和申辩以及采用暴力、威胁等非法方法收集的被侵害人陈述、其他证人证言，不能作为定案的根据。收集物证、书证不符合法定程序，可能严重影响执法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，不能作为定案的根据。"},{"i":28,"n":"第二十八条","txt":"公安机关向有关单位和个人收集、调取证据时，应当告知其必须如实提供证据，并告知其伪造、隐匿、毁灭证据，提供虚假证词应当承担的法律责任。 需要向有关单位和个人调取证据的，经公安机关办案部门负责人批准，开具调取证据通知书，明确调取的证据和提供时限。被调取人应当在通知书上盖章或者签名，被调取人拒绝的，公安机关应当注明。必要时，公安机关应当采用录音、录像等方式固定证据内容及取证过程。 需要向有关单位紧急调取证据的，公安机关可以在电话告知人民警察身份的同时，将调取证据通知书连同办案人民警察的人民警察证复印件通过传真、互联网通讯工具等方式送达有关单位。"},{"i":29,"n":"第二十九条","txt":"收集调取的物证应当是原物。在原物不便搬运、不易保存或者依法应当由有关部门保管、处理或者依法应当返还时，可以拍摄或者制作足以反映原物外形或者内容的照片、录像。 物证的照片、录像，经与原物核实无误或者经鉴定证明为真实的，可以作为证据使用。"},{"i":30,"n":"第三十条","txt":"收集、调取的书证应当是原件。在取得原件确有困难时，可以使用副本或者复制件。 书证的副本、复制件，经与原件核实无误或者经鉴定证明为真实的，可以作为证据使用。书证有更改或者更改迹象不能作出合理解释的，或者书证的副本、复制件不能反映书证原件及其内容的，不能作为证据使用。"},{"i":31,"n":"第三十一条","txt":"物证的照片、录像，书证的副本、复制件，视听资料的复制件，应当附有关制作过程及原件、原物存放处的文字说明，并由制作人和物品持有人或者持有单位有关人员签名。"},{"i":32,"n":"第三十二条","txt":"收集电子数据，能够扣押电子数据原始存储介质的，应当扣押。 无法扣押原始存储介质的，可以提取电子数据。提取电子数据，应当制作笔录，并附电子数据清单，由办案人民警察、电子数据持有人签名。持有人无法或者拒绝签名的，应当在笔录中注明。 由于客观原因无法或者不宜依照前两款规定收集电子数据的，可以采取打印、拍照或者录像等方式固定相关证据，并附有关原因、过程等情况的文字说明，由办案人民警察、电子数据持有人签名。持有人无法或者拒绝签名的，应当注明情况。"},{"i":33,"n":"第三十三条","txt":"刑事案件转为行政案件办理的，刑事案件办理过程中收集的证据材料，可以作为行政案件的证据使用。"},{"i":34,"n":"第三十四条","txt":"凡知道案件情况的人，都有作证的义务。 生理上、精神上有缺陷或者年幼，不能辨别是非、不能正确表达的人，不能作为证人。"},{"i":35,"n":"第三十五条","txt":"期间以时、日、月、年计算，期间开始之时或者日不计算在内。法律文书送达的期间不包括路途上的时间。期间的最后一日是节假日的，以节假日后的第一日为期满日期，但违法行为人被限制人身自由的期间，应当至期满之日为止，不得因节假日而延长。"},{"i":36,"n":"第三十六条","txt":"送达法律文书，应当遵守下列规定： （一）依照简易程序作出当场处罚决定的，应当将决定书当场交付被处罚人，并由被处罚人在备案的决定书上签名或者捺指印；被处罚人拒绝的，由办案人民警察在备案的决定书上注明； （二）除本款第一项规定外，作出行政处罚决定和其他行政处理决定，应当在宣告后将决定书当场交付被处理人，并由被处理人在附卷的决定书上签名或者捺指印，即为送达；被处理人拒绝的，由办案人民警察在附卷的决定书上注明；被处理人不在场的，公安机关应当在作出决定的七日内将决定书送达被处理人，治安管理处罚决定应当在二日内送达。 送达法律文书应当首先采取直接送达方式，交给受送达人本人；受送达人不在的，可以交付其成年家属、所在单位的负责人员或者其居住地居（村）民委员会代收。受送达人本人或者代收人拒绝接收或者拒绝签名和捺指印的，送达人可以邀请其邻居或者其他见证人到场，说明情况，也可以对拒收情况进行录音录像，把文书"},{"i":37,"n":"第三十七条","txt":"违法事实确凿，且具有下列情形之一的，人民警察可以当场作出处罚决定，有违禁品的，可以当场收缴： （一）对违反治安管理行为人或者道路交通违法行为人处二百元以下罚款或者警告的； （二）出入境边防检查机关对违反出境入境管理行为人处五百元以下罚款或者警告的； （三）对有其他违法行为的个人处五十元以下罚款或者警告、对单位处一千元以下罚款或者警告的； （四）法律规定可以当场处罚的其他情形。 涉及卖淫、嫖娼、赌博、毒品的案件，不适用当场处罚。"},{"i":38,"n":"第三十八条","txt":"当场处罚，应当按照下列程序实施： （一）向违法行为人表明执法身份； （二）收集证据； （三）口头告知违法行为人拟作出行政处罚决定的事实、理由和依据，并告知违法行为人依法享有的陈述权和申辩权； （四）充分听取违法行为人的陈述和申辩。违法行为人提出的事实、理由或者证据成立的，应当采纳； （五）填写当场处罚决定书并当场交付被处罚人； （六）当场收缴罚款的，同时填写罚款收据，交付被处罚人；未当场收缴罚款的，应当告知被处罚人在规定期限内到指定的银行缴纳罚款。"},{"i":39,"n":"第三十九条","txt":"适用简易程序处罚的，可以由人民警察一人作出行政处罚决定。 人民警察当场作出行政处罚决定的，应当于作出决定后的二十四小时内将当场处罚决定书报所属公安机关备案，交通警察应当于作出决定后的二日内报所属公安机关交通管理部门备案。在旅客列车、民航飞机、水上作出行政处罚决定的，应当在返回后的二十四小时内报所属公安机关备案。"},{"i":40,"n":"第四十条","txt":"对不适用简易程序，但事实清楚，违法嫌疑人自愿认错认罚，且对违法事实和法律适用没有异议的行政案件，公安机关可以通过简化取证方式和审核审批手续等措施快速办理。"},{"i":41,"n":"第四十一条","txt":"行政案件具有下列情形之一的，不适用快速办理： （一）违法嫌疑人系盲、聋、哑人，未成年人或者疑似精神病人的； （二）依法应当适用听证程序的； （三）可能作出十日以上行政拘留处罚的； （四）其他不宜快速办理的。"},{"i":42,"n":"第四十二条","txt":"快速办理行政案件前，公安机关应当书面告知违法嫌疑人快速办理的相关规定，征得其同意，并由其签名确认。"},{"i":43,"n":"第四十三条","txt":"对符合快速办理条件的行政案件，违法嫌疑人在自行书写材料或者询问笔录中承认违法事实、认错认罚，并有视音频记录、电子数据、检查笔录等关键证据能够相互印证的，公安机关可以不再开展其他调查取证工作。"},{"i":44,"n":"第四十四条","txt":"对适用快速办理的行政案件，可以由专兼职法制员或者办案部门负责人审核后，报公安机关负责人审批。"},{"i":45,"n":"第四十五条","txt":"对快速办理的行政案件，公安机关可以根据不同案件类型，使用简明扼要的格式询问笔录，尽量减少需要文字记录的内容。 被询问人自行书写材料的，办案单位可以提供样式供其参考。 使用执法记录仪等设备对询问过程录音录像的，可以替代书面询问笔录，必要时，对视听资料的关键内容和相应时间段等作文字说明。"},{"i":46,"n":"第四十六条","txt":"对快速办理的行政案件，公安机关可以根据违法行为人认错悔改、纠正违法行为、赔偿损失以及被侵害人谅解情况等情节，依法对违法行为人从轻、减轻处罚或者不予行政处罚。 对快速办理的行政案件，公安机关可以采用口头方式履行处罚前告知程序，由办案人民警察在案卷材料中注明告知情况，并由被告知人签名确认。"},{"i":47,"n":"第四十七条","txt":"对快速办理的行政案件，公安机关应当在违法嫌疑人到案后四十八小时内作出处理决定。"},{"i":48,"n":"第四十八条","txt":"公安机关快速办理行政案件时，发现不适宜快速办理的，转为一般案件办理。快速办理阶段依法收集的证据，可以作为定案的根据。"},{"i":49,"n":"第四十九条","txt":"对行政案件进行调查时，应当合法、及时、客观、全面地收集、调取证据材料，并予以审查、核实。"},{"i":50,"n":"第五十条","txt":"需要调查的案件事实包括： （一）违法嫌疑人的基本情况； （二）违法行为是否存在； （三）违法行为是否为违法嫌疑人实施； （四）实施违法行为的时间、地点、手段、后果以及其他情节； （五）违法嫌疑人有无法定从重、从轻、减轻以及不予行政处罚的情形； （六）与案件有关的其他事实。"},{"i":51,"n":"第五十一条","txt":"公安机关调查取证时，应当防止泄露工作秘密。"},{"i":52,"n":"第五十二条","txt":"公安机关进行询问、辨认、检查、勘验，实施行政强制措施等调查取证工作时，人民警察不得少于二人，并表明执法身份。 接报案、受案登记、接受证据、信息采集、调解、送达文书等工作，可以由一名人民警察带领警务辅助人员进行，但应当全程录音录像。"},{"i":53,"n":"第五十三条","txt":"对查获或者到案的违法嫌疑人应当进行安全检查，发现违禁品或者管制器具、武器、易燃易爆等危险品以及与案件有关的需要作为证据的物品的，应当立即扣押；对违法嫌疑人随身携带的与案件无关的物品，应当按照有关规定予以登记、保管、退还。安全检查不需要开具检查证。 前款规定的扣押适用本规定第五十五条和第五十六条以及本章第七节的规定。"},{"i":54,"n":"第五十四条","txt":"办理行政案件时，可以依法采取下列行政强制措施： （一）对物品、设施、场所采取扣押、扣留、查封、先行登记保存、抽样取证、封存文件资料等强制措施，对恐怖活动嫌疑人的存款、汇款、债券、股票、基金份额等财产还可以采取冻结措施； （二）对违法嫌疑人采取保护性约束措施、继续盘问、强制传唤、强制检测、拘留审查、限制活动范围，对恐怖活动嫌疑人采取约束措施等强制措施。"},{"i":55,"n":"第五十五条","txt":"实施行政强制措施应当遵守下列规定： （一）实施前须依法向公安机关负责人报告并经批准； （二）通知当事人到场，当场告知当事人采取行政强制措施的理由、依据以及当事人依法享有的权利、救济途径。当事人不到场的，邀请见证人到场，并在现场笔录中注明； （三）听取当事人的陈述和申辩； （四）制作现场笔录，由当事人和办案人民警察签名或者盖章，当事人拒绝的，在笔录中注明。当事人不在场的，由见证人和办案人民警察在笔录上签名或者盖章； （五）实施限制公民人身自由的行政强制措施的，应当当场告知当事人家属实施强制措施的公安机关、理由、地点和期限；无法当场告知的，应当在实施强制措施后立即通过电话、短信、传真等方式通知；身份不明、拒不提供家属联系方式或者因自然灾害等不可抗力导致无法通知的，可以不予通知。告知、通知家属情况或者无法通知家属的原因应当在询问笔录中注明。 （六）法律、法规规定的其他程序。 勘验、检查时实施"},{"i":56,"n":"第五十六条","txt":"情况紧急，当场实施行政强制措施的，办案人民警察应当在二十四小时内依法向其所属的公安机关负责人报告，并补办批准手续。当场实施限制公民人身自由的行政强制措施的，办案人民警察应当在返回单位后立即报告，并补办批准手续。公安机关负责人认为不应当采取行政强制措施的，应当立即解除。"},{"i":57,"n":"第五十七条","txt":"为维护社会秩序，人民警察对有违法嫌疑的人员，经表明执法身份后，可以当场盘问、检查。对当场盘问、检查后，不能排除其违法嫌疑，依法可以适用继续盘问的，可以将其带至公安机关，经公安派出所负责人批准，对其继续盘问。对违反出境入境管理的嫌疑人依法适用继续盘问的，应当经县级以上公安机关或者出入境边防检查机关负责人批准。 继续盘问的时限一般为十二小时；对在十二小时以内确实难以证实或者排除其违法犯罪嫌疑的，可以延长至二十四小时；对不讲真实姓名、住址、身份，且在二十四小时以内仍不能证实或者排除其违法犯罪嫌疑的，可以延长至四十八小时。"},{"i":58,"n":"第五十八条","txt":"违法嫌疑人在醉酒状态中，对本人有危险或者对他人的人身、财产或者公共安全有威胁的，可以对其采取保护性措施约束至酒醒，也可以通知其家属、亲友或者所属单位将其领回看管，必要时，应当送医院醒酒。对行为举止失控的醉酒人，可以使用约束带或者警绳等进行约束，但是不得使用手铐、脚镣等警械。 约束过程中，应当指定专人严加看护。确认醉酒人酒醒后，应当立即解除约束，并进行询问。约束时间不计算在询问查证时间内。"},{"i":59,"n":"第五十九条","txt":"对恐怖活动嫌疑人实施约束措施，应当遵守下列规定： （一）实施前须经县级以上公安机关负责人批准； （二）告知嫌疑人采取约束措施的理由、依据以及其依法享有的权利、救济途径； （三）听取嫌疑人的陈述和申辩； （四）出具决定书。 公安机关可以采取电子监控、不定期检查等方式对被约束人遵守约束措施的情况进行监督。 约束措施的期限不得超过三个月。对不需要继续采取约束措施的，应当及时解除并通知被约束人。"},{"i":60,"n":"第六十条","txt":"县级公安机关及其公安派出所、依法具有独立执法主体资格的公安机关业务部门以及出入境边防检查站对报案、控告、举报、群众扭送或者违法嫌疑人投案，以及其他国家机关移送的案件，应当及时受理并按照规定进行网上接报案登记。对重复报案、案件正在办理或者已经办结的，应当向报案人、控告人、举报人、扭送人、投案人作出解释，不再登记。"},{"i":61,"n":"第六十一条","txt":"公安机关应当对报案、控告、举报、群众扭送或者违法嫌疑人投案分别作出下列处理，并将处理情况在接报案登记中注明： （一）对属于本单位管辖范围内的案件，应当立即调查处理，制作受案登记表和受案回执，并将受案回执交报案人、控告人、举报人、扭送人； （二）对属于公安机关职责范围，但不属于本单位管辖的，应当在二十四小时内移送有管辖权的单位处理，并告知报案人、控告人、举报人、扭送人、投案人； （三）对不属于公安机关职责范围的事项，在接报案时能够当场判断的，应当立即口头告知报案人、控告人、举报人、扭送人、投案人向其他主管机关报案或者投案，报案人、控告人、举报人、扭送人、投案人对口头告知内容有异议或者不能当场判断的，应当书面告知，但因没有联系方式、身份不明等客观原因无法书面告知的除外。 在日常执法执勤中发现的违法行为，适用前款规定。"},{"i":62,"n":"第六十二条","txt":"属于公安机关职责范围但不属于本单位管辖的案件，具有下列情形之一的，受理案件或者发现案件的公安机关及其人民警察应当依法先行采取必要的强制措施或者其他处置措施，再移送有管辖权的单位处理： （一）违法嫌疑人正在实施危害行为的； （二）正在实施违法行为或者违法后即时被发现的现行犯被扭送至公安机关的； （三）在逃的违法嫌疑人已被抓获或者被发现的； （四）有人员伤亡，需要立即采取救治措施的； （五）其他应当采取紧急措施的情形。 行政案件移送管辖的，询问查证时间和扣押等措施的期限重新计算。"},{"i":63,"n":"第六十三条","txt":"报案人不愿意公开自己的姓名和报案行为的，公安机关应当在受案登记时注明，并为其保密。"},{"i":64,"n":"第六十四条","txt":"对报案人、控告人、举报人、扭送人、投案人提供的有关证据材料、物品等应当登记，出具接受证据清单，并妥善保管。必要时，应当拍照、录音、录像。移送案件时，应当将有关证据材料和物品一并移交。"},{"i":65,"n":"第六十五条","txt":"对发现或者受理的案件暂时无法确定为刑事案件或者行政案件的，可以按照行政案件的程序办理。在办理过程中，认为涉嫌构成犯罪的，应当按照《公安机关办理刑事案件程序规定》办理。"},{"i":66,"n":"第六十六条","txt":"询问违法嫌疑人，可以到违法嫌疑人住处或者单位进行，也可以将违法嫌疑人传唤到其所在市、县内的指定地点进行。"},{"i":67,"n":"第六十七条","txt":"需要传唤违法嫌疑人接受调查的，经公安派出所、县级以上公安机关办案部门或者出入境边防检查机关负责人批准，使用传唤证传唤。对现场发现的违法嫌疑人，人民警察经出示人民警察证，可以口头传唤，并在询问笔录中注明违法嫌疑人到案经过、到案时间和离开时间。 单位违反公安行政管理规定，需要传唤其直接负责的主管人员和其他直接责任人员的，适用前款规定。 对无正当理由不接受传唤或者逃避传唤的违反治安管理、出境入境管理的嫌疑人以及法律规定可以强制传唤的其他违法嫌疑人，经公安派出所、县级以上公安机关办案部门或者出入境边防检查机关负责人批准，可以强制传唤。强制传唤时，可以依法使用手铐、警绳等约束性警械。 公安机关应当将传唤的原因和依据告知被传唤人，并通知其家属。公安机关通知被传唤人家属适用本规定第五十五条第一款第五项的规定。"},{"i":68,"n":"第六十八条","txt":"使用传唤证传唤的，违法嫌疑人被传唤到案后和询问查证结束后，应当由其在传唤证上填写到案和离开时间并签名。拒绝填写或者签名的，办案人民警察应当在传唤证上注明。"},{"i":69,"n":"第六十九条","txt":"对被传唤的违法嫌疑人，应当及时询问查证，询问查证的时间不得超过八小时；案情复杂，违法行为依法可能适用行政拘留处罚的，询问查证的时间不得超过二十四小时。 不得以连续传唤的形式变相拘禁违法嫌疑人。"},{"i":70,"n":"第七十条","txt":"对于投案自首或者群众扭送的违法嫌疑人，公安机关应当立即进行询问查证，并在询问笔录中记明违法嫌疑人到案经过、到案和离开时间。询问查证时间适用本规定第六十九条第一款的规定。 对于投案自首或者群众扭送的违法嫌疑人，公安机关应当适用本规定第五十五条第一款第五项的规定通知其家属。"},{"i":71,"n":"第七十一条","txt":"在公安机关询问违法嫌疑人，应当在办案场所进行。 询问查证期间应当保证违法嫌疑人的饮食和必要的休息时间，并在询问笔录中注明。 在询问查证的间隙期间，可以将违法嫌疑人送入候问室，并按照候问室的管理规定执行。"},{"i":72,"n":"第七十二条","txt":"询问违法嫌疑人、被侵害人或者其他证人，应当个别进行。"},{"i":73,"n":"第七十三条","txt":"首次询问违法嫌疑人时，应当问明违法嫌疑人的姓名、出生日期、户籍所在地、现住址、身份证件种类及号码，是否为各级人民代表大会代表，是否受过刑事处罚或者行政拘留、强制隔离戒毒、社区戒毒、收容教养等情况。必要时，还应当问明其家庭主要成员、工作单位、文化程度、民族、身体状况等情况。 违法嫌疑人为外国人的，首次询问时还应当问明其国籍、出入境证件种类及号码、签证种类、入境时间、入境事由等情况。必要时，还应当问明其在华关系人等情况。"},{"i":74,"n":"第七十四条","txt":"询问时，应当告知被询问人必须如实提供证据、证言和故意作伪证或者隐匿证据应负的法律责任，对与本案无关的问题有拒绝回答的权利。"},{"i":75,"n":"第七十五条","txt":"询问未成年人时，应当通知其父母或者其他监护人到场，其父母或者其他监护人不能到场的，也可以通知未成年人的其他成年亲属，所在学校、单位、居住地基层组织或者未成年人保护组织的代表到场，并将有关情况记录在案。确实无法通知或者通知后未到场的，应当在询问笔录中注明。"},{"i":76,"n":"第七十六条","txt":"询问聋哑人，应当有通晓手语的人提供帮助，并在询问笔录中注明被询问人的聋哑情况以及翻译人员的姓名、住址、工作单位和联系方式。 对不通晓当地通用的语言文字的被询问人，应当为其配备翻译人员，并在询问笔录中注明翻译人员的姓名、住址、工作单位和联系方式。"},{"i":77,"n":"第七十七条","txt":"询问笔录应当交被询问人核对，对没有阅读能力的，应当向其宣读。记录有误或者遗漏的，应当允许被询问人更正或者补充，并要求其在修改处捺指印。被询问人确认笔录无误后，应当在询问笔录上逐页签名或者捺指印。拒绝签名和捺指印的，办案人民警察应当在询问笔录中注明。 办案人民警察应当在询问笔录上签名，翻译人员应当在询问笔录的结尾处签名。 询问时，可以全程录音、录像，并保持录音、录像资料的完整性。"},{"i":78,"n":"第七十八条","txt":"询问违法嫌疑人时，应当听取违法嫌疑人的陈述和申辩。对违法嫌疑人的陈述和申辩，应当核查。"},{"i":79,"n":"第七十九条","txt":"询问被侵害人或者其他证人，可以在现场进行，也可以到其单位、学校、住所、其居住地居（村）民委员会或者其提出的地点进行。必要时，也可以书面、电话或者当场通知其到公安机关提供证言。 在现场询问的，办案人民警察应当出示人民警察证。 询问前，应当了解被询问人的身份以及其与被侵害人、其他证人、违法嫌疑人之间的关系。"},{"i":80,"n":"第八十条","txt":"违法嫌疑人、被侵害人或者其他证人请求自行提供书面材料的，应当准许。必要时，办案人民警察也可以要求违法嫌疑人、被侵害人或者其他证人自行书写。违法嫌疑人、被侵害人或者其他证人应当在其提供的书面材料的结尾处签名或者捺指印。对打印的书面材料，违法嫌疑人、被侵害人或者其他证人应当逐页签名或者捺指印。办案人民警察收到书面材料后，应当在首页注明收到日期，并签名。"},{"i":81,"n":"第八十一条","txt":"对于违法行为案发现场，必要时应当进行勘验，提取与案件有关的证据材料，判断案件性质，确定调查方向和范围。 现场勘验参照刑事案件现场勘验的有关规定执行。"},{"i":82,"n":"第八十二条","txt":"对与违法行为有关的场所、物品、人身可以进行检查。检查时，人民警察不得少于二人，并应当出示人民警察证和县级以上公安机关开具的检查证。对确有必要立即进行检查的，人民警察经出示人民警察证，可以当场检查；但检查公民住所的，必须有证据表明或者有群众报警公民住所内正在发生危害公共安全或者公民人身安全的案（事）件，或者违法存放危险物质，不立即检查可能会对公共安全或者公民人身、财产安全造成重大危害。 对机关、团体、企业、事业单位或者公共场所进行日常执法监督检查，依照有关法律、法规和规章执行，不适用前款规定。"},{"i":83,"n":"第八十三条","txt":"对违法嫌疑人，可以依法提取或者采集肖像、指纹等人体生物识别信息；涉嫌酒后驾驶机动车、吸毒、从事恐怖活动等违法行为的，可以依照《中华人民共和国道路交通安全法》《中华人民共和国禁毒法》《中华人民共和国反恐怖主义法》等规定提取或者采集血液、尿液、毛发、脱落细胞等生物样本。人身安全检查和当场检查时已经提取、采集的信息，不再提取、采集。"},{"i":84,"n":"第八十四条","txt":"对违法嫌疑人进行检查时，应当尊重被检查人的人格尊严，不得以有损人格尊严的方式进行检查。 检查妇女的身体，应当由女性工作人员进行。 依法对卖淫、嫖娼人员进行性病检查，应当由医生进行。"},{"i":85,"n":"第八十五条","txt":"检查场所或者物品时，应当注意避免对物品造成不必要的损坏。 检查场所时，应当有被检查人或者见证人在场。"},{"i":86,"n":"第八十六条","txt":"检查情况应当制作检查笔录。检查笔录由检查人员、被检查人或者见证人签名；被检查人不在场或者拒绝签名的，办案人民警察应当在检查笔录中注明。 检查时的全程录音录像可以替代书面检查笔录，但应当对视听资料的关键内容和相应时间段等作文字说明。"},{"i":87,"n":"第八十七条","txt":"为了查明案情，需要对专门性技术问题进行鉴定的，应当指派或者聘请具有专门知识的人员进行。 需要聘请本公安机关以外的人进行鉴定的，应当经公安机关办案部门负责人批准后，制作鉴定聘请书。"},{"i":88,"n":"第八十八条","txt":"公安机关应当为鉴定提供必要的条件，及时送交有关检材和比对样本等原始材料，介绍与鉴定有关的情况，并且明确提出要求鉴定解决的问题。 办案人民警察应当做好检材的保管和送检工作，并注明检材送检环节的责任人，确保检材在流转环节中的同一性和不被污染。 禁止强迫或者暗示鉴定人作出某种鉴定意见。"},{"i":89,"n":"第八十九条","txt":"对人身伤害的鉴定由法医进行。 卫生行政主管部门许可的医疗机构具有执业资格的医生出具的诊断证明，可以作为公安机关认定人身伤害程度的依据，但具有本规定第九十条规定情形的除外。 对精神病的鉴定，由有精神病鉴定资格的鉴定机构进行。"},{"i":90,"n":"第九十条","txt":"人身伤害案件具有下列情形之一的，公安机关应当进行伤情鉴定： （一）受伤程度较重，可能构成轻伤以上伤害程度的； （二）被侵害人要求作伤情鉴定的； （三）违法嫌疑人、被侵害人对伤害程度有争议的。"},{"i":91,"n":"第九十一条","txt":"对需要进行伤情鉴定的案件，被侵害人拒绝提供诊断证明或者拒绝进行伤情鉴定的，公安机关应当将有关情况记录在案，并可以根据已认定的事实作出处理决定。 经公安机关通知，被侵害人无正当理由未在公安机关确定的时间内作伤情鉴定的，视为拒绝鉴定。"},{"i":92,"n":"第九十二条","txt":"对电子数据涉及的专门性问题难以确定的，由司法鉴定机构出具鉴定意见，或者由公安部指定的机构出具报告。"},{"i":93,"n":"第九十三条","txt":"涉案物品价值不明或者难以确定的，公安机关应当委托价格鉴证机构估价。 根据当事人提供的购买发票等票据能够认定价值的涉案物品，或者价值明显不够刑事立案标准的涉案物品，公安机关可以不进行价格鉴证。"},{"i":94,"n":"第九十四条","txt":"对涉嫌吸毒的人员，应当进行吸毒检测，被检测人员应当配合；对拒绝接受检测的，经县级以上公安机关或者其派出机构负责人批准，可以强制检测。采集女性被检测人检测样本，应当由女性工作人员进行。 对涉嫌服用国家管制的精神药品、麻醉药品驾驶机动车的人员，可以对其进行体内国家管制的精神药品、麻醉药品含量检验。"},{"i":95,"n":"第九十五条","txt":"对有酒后驾驶机动车嫌疑的人，应当对其进行呼气酒精测试，对具有下列情形之一的，应当立即提取血样，检验血液酒精含量： （一）当事人对呼气酒精测试结果有异议的； （二）当事人拒绝配合呼气酒精测试的； （三）涉嫌醉酒驾驶机动车的； （四）涉嫌饮酒后驾驶机动车发生交通事故的。 当事人对呼气酒精测试结果无异议的，应当签字确认。事后提出异议的，不予采纳。"},{"i":96,"n":"第九十六条","txt":"鉴定人鉴定后，应当出具鉴定意见。鉴定意见应当载明委托人、委托鉴定的事项、提交鉴定的相关材料、鉴定的时间、依据和结论性意见等内容，并由鉴定人签名或者盖章。通过分析得出鉴定意见的，应当有分析过程的说明。鉴定意见应当附有鉴定机构和鉴定人的资质证明或者其他证明文件。 鉴定人对鉴定意见负责，不受任何机关、团体、企业、事业单位和个人的干涉。多人参加鉴定，对鉴定意见有不同意见的，应当注明。 鉴定人故意作虚假鉴定的，应当承担法律责任。"},{"i":97,"n":"第九十七条","txt":"办案人民警察应当对鉴定意见进行审查。 对经审查作为证据使用的鉴定意见，公安机关应当在收到鉴定意见之日起五日内将鉴定意见复印件送达违法嫌疑人和被侵害人。 医疗机构出具的诊断证明作为公安机关认定人身伤害程度的依据的，应当将诊断证明结论书面告知违法嫌疑人和被侵害人。 违法嫌疑人或者被侵害人对鉴定意见有异议的，可以在收到鉴定意见复印件之日起三日内提出重新鉴定的申请，经县级以上公安机关批准后，进行重新鉴定。同一行政案件的同一事项重新鉴定以一次为限。 当事人是否申请重新鉴定，不影响案件的正常办理。 公安机关认为必要时，也可以直接决定重新鉴定。"},{"i":98,"n":"第九十八条","txt":"具有下列情形之一的，应当进行重新鉴定： （一）鉴定程序违法或者违反相关专业技术要求，可能影响鉴定意见正确性的； （二）鉴定机构、鉴定人不具备鉴定资质和条件的; （三）鉴定意见明显依据不足的； （四）鉴定人故意作虚假鉴定的； （五）鉴定人应当回避而没有回避的； （六）检材虚假或者被损坏的； （七）其他应当重新鉴定的。 不符合前款规定情形的，经县级以上公安机关负责人批准，作出不准予重新鉴定的决定，并在作出决定之日起的三日以内书面通知申请人。"},{"i":99,"n":"第九十九条","txt":"重新鉴定，公安机关应当另行指派或者聘请鉴定人。"},{"i":100,"n":"第一百条","txt":"鉴定费用由公安机关承担，但当事人自行鉴定的除外。"},{"i":101,"n":"第一百零一条","txt":"为了查明案情，办案人民警察可以让违法嫌疑人、被侵害人或者其他证人对与违法行为有关的物品、场所或者违法嫌疑人进行辨认。"},{"i":102,"n":"第一百零二条","txt":"辨认由二名以上办案人民警察主持。 组织辨认前，应当向辨认人详细询问辨认对象的具体特征，并避免辨认人见到辨认对象。"},{"i":103,"n":"第一百零三条","txt":"多名辨认人对同一辨认对象或者一名辨认人对多名辨认对象进行辨认时，应当个别进行。"},{"i":104,"n":"第一百零四条","txt":"辨认时，应当将辨认对象混杂在特征相类似的其他对象中，不得给辨认人任何暗示。 辨认违法嫌疑人时，被辨认的人数不得少于七人；对违法嫌疑人照片进行辨认的，不得少于十人的照片。 辨认每一件物品时，混杂的同类物品不得少于五件。 同一辨认人对与同一案件有关的辨认对象进行多组辨认的，不得重复使用陪衬照片或者陪衬人。"},{"i":105,"n":"第一百零五条","txt":"辨认人不愿意暴露身份的，对违法嫌疑人的辨认可以在不暴露辨认人的情况下进行，公安机关及其人民警察应当为其保守秘密。"},{"i":106,"n":"第一百零六条","txt":"辨认经过和结果，应当制作辨认笔录，由办案人民警察和辨认人签名或者捺指印。必要时，应当对辨认过程进行录音、录像。"},{"i":107,"n":"第一百零七条","txt":"对下列物品，经公安机关负责人批准，可以依法扣押或者扣留： （一）与治安案件、违反出境入境管理的案件有关的需要作为证据的物品； （二）道路交通安全法律、法规规定适用扣留的车辆、机动车驾驶证； （三）《中华人民共和国反恐怖主义法》等法律、法规规定适用扣押或者扣留的物品。 对下列物品，不得扣押或者扣留： （一）与案件无关的物品； （二）公民个人及其所扶养家属的生活必需品； （三）被侵害人或者善意第三人合法占有的财产。 对具有本条第二款第二项、第三项情形的，应当予以登记，写明登记财物的名称、规格、数量、特征，并由占有人签名或者捺指印。必要时，可以进行拍照。但是，与案件有关必须鉴定的，可以依法扣押，结束后应当立即解除。"},{"i":108,"n":"第一百零八条","txt":"办理下列行政案件时，对专门用于从事无证经营活动的场所、设施、物品，经公安机关负责人批准，可以依法查封。但对与违法行为无关的场所、设施，公民个人及其扶养家属的生活必需品不得查封： （一）擅自经营按照国家规定需要由公安机关许可的行业的； （二）依照《娱乐场所管理条例》可以由公安机关采取取缔措施的； （三）《中华人民共和国反恐怖主义法》等法律、法规规定适用查封的其他公安行政案件。 场所、设施、物品已被其他国家机关依法查封的，不得重复查封。"},{"i":109,"n":"第一百零九条","txt":"收集证据时，经公安机关办案部门负责人批准，可以采取抽样取证的方法。 抽样取证应当采取随机的方式，抽取样品的数量以能够认定本品的品质特征为限。 抽样取证时，应当对抽样取证的现场、被抽样物品及被抽取的样品进行拍照或者对抽样过程进行录像。 对抽取的样品应当及时进行检验。经检验，能够作为证据使用的，应当依法扣押、先行登记保存或者登记；不属于证据的，应当及时返还样品。样品有减损的，应当予以补偿。"},{"i":110,"n":"第一百一十条","txt":"在证据可能灭失或者以后难以取得的情况下，经公安机关办案部门负责人批准，可以先行登记保存。 先行登记保存期间，证据持有人及其他人员不得损毁或者转移证据。 对先行登记保存的证据，应当在七日内作出处理决定。逾期不作出处理决定的，视为自动解除。"},{"i":111,"n":"第一百一十一条","txt":"实施扣押、扣留、查封、抽样取证、先行登记保存等证据保全措施时，应当会同当事人查点清楚，制作并当场交付证据保全决定书。必要时，应当对采取证据保全措施的证据进行拍照或者对采取证据保全的过程进行录像。证据保全决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）抽样取证、先行登记保存、扣押、扣留、查封的理由、依据和期限； （三）申请行政复议或者提起行政诉讼的途径和期限； （四）作出决定的公安机关的名称、印章和日期。 证据保全决定书应当附清单，载明被采取证据保全措施的场所、设施、物品的名称、规格、数量、特征等，由办案人民警察和当事人签名后，一份交当事人，一份附卷。有见证人的，还应当由见证人签名。当事人或者见证人拒绝签名的，办案人民警察应当在证据保全清单上注明。 对可以作为证据使用的录音带、录像带，在扣押时应当予以检查，记明案由、内容以及录取和复制的时间、地点等，并妥为保管。 对扣"},{"i":112,"n":"第一百一十二条","txt":"扣押、扣留、查封期限为三十日，情况复杂的，经县级以上公安机关负责人批准，可以延长三十日；法律、行政法规另有规定的除外。延长扣押、扣留、查封期限的，应当及时书面告知当事人，并说明理由。 对物品需要进行鉴定的，鉴定期间不计入扣押、扣留、查封期间，但应当将鉴定的期间书面告知当事人。"},{"i":113,"n":"第一百一十三条","txt":"公安机关对恐怖活动嫌疑人的存款、汇款、债券、股票、基金份额等财产采取冻结措施的，应当经县级以上公安机关负责人批准，向金融机构交付冻结通知书。 作出冻结决定的公安机关应当在三日内向恐怖活动嫌疑人交付冻结决定书。冻结决定书应当载明下列事项： （一）恐怖活动嫌疑人的姓名或者名称、地址； （二）冻结的理由、依据和期限； （三）冻结的账号和数额； （四）申请行政复议或者提起行政诉讼的途径和期限； （五）公安机关的名称、印章和日期。"},{"i":114,"n":"第一百一十四条","txt":"自被冻结之日起二个月内，公安机关应当作出处理决定或者解除冻结；情况复杂的，经上一级公安机关负责人批准，可以延长一个月。 延长冻结的决定应当及时书面告知恐怖活动嫌疑人，并说明理由。"},{"i":115,"n":"第一百一十五条","txt":"有下列情形之一的，公安机关应当立即退还财物，并由当事人签名确认；不涉及财物退还的，应当书面通知当事人解除证据保全： （一）当事人没有违法行为的； （二）被采取证据保全的场所、设施、物品、财产与违法行为无关的； （三）已经作出处理决定，不再需要采取证据保全措施的； （四）采取证据保全措施的期限已经届满的； （五）其他不再需要采取证据保全措施的。 作出解除冻结决定的，应当及时通知金融机构。"},{"i":116,"n":"第一百一十六条","txt":"行政案件变更管辖时，与案件有关的财物及其孳息应当随案移交，并书面告知当事人。移交时，由接收人、移交人当面查点清楚，并在交接单据上共同签名。"},{"i":117,"n":"第一百一十七条","txt":"办理行政案件需要异地公安机关协作的，应当制作办案协作函件。负责协作的公安机关接到请求协作的函件后，应当办理。"},{"i":118,"n":"第一百一十八条","txt":"需要到异地执行传唤的，办案人民警察应当持传唤证、办案协作函件和人民警察证，与协作地公安机关联系，在协作地公安机关的协作下进行传唤。协作地公安机关应当协助将违法嫌疑人传唤到其所在市、县内的指定地点或者到其住处、单位进行询问。"},{"i":119,"n":"第一百一十九条","txt":"需要异地办理检查、查询，查封、扣押或者冻结与案件有关的财物、文件的，应当持相关的法律文书、办案协作函件和人民警察证，与协作地公安机关联系，协作地公安机关应当协助执行。 在紧急情况下，可以将办案协作函件和相关的法律文书传真或者通过执法办案信息系统发送至协作地公安机关，协作地公安机关应当及时采取措施。办案地公安机关应当立即派员前往协作地办理。"},{"i":120,"n":"第一百二十条","txt":"需要进行远程视频询问、处罚前告知的，应当由协作地公安机关事先核实被询问、告知人的身份。办案地公安机关应当制作询问、告知笔录并传输至协作地公安机关。询问、告知笔录经被询问、告知人确认并逐页签名或者捺指印后，由协作地公安机关协作人员签名或者盖章，并将原件或者电子签名笔录提供给办案地公安机关。办案地公安机关负责询问、告知的人民警察应当在首页注明收到日期，并签名或者盖章。询问、告知过程应当全程录音录像。"},{"i":121,"n":"第一百二十一条","txt":"办案地公安机关可以委托异地公安机关代为询问、向有关单位和个人调取电子数据、接收自行书写材料、进行辨认、履行处罚前告知程序、送达法律文书等工作。 委托代为询问、辨认、处罚前告知的，办案地公安机关应当列出明确具体的询问、辨认、告知提纲，提供被辨认对象的照片和陪衬照片。 委托代为向有关单位和个人调取电子数据的，办案地公安机关应当将办案协作函件和相关法律文书传真或者通过执法办案信息系统发送至协作地公安机关，由协作地公安机关办案部门审核确认后办理。"},{"i":122,"n":"第一百二十二条","txt":"协作地公安机关依照办案地公安机关的要求，依法履行办案协作职责所产生的法律责任，由办案地公安机关承担。"},{"i":123,"n":"第一百二十三条","txt":"在作出下列行政处罚决定之前，应当告知违法嫌疑人有要求举行听证的权利： （一）责令停产停业； （二）吊销许可证或者执照； （三）较大数额罚款； （四）法律、法规和规章规定违法嫌疑人可以要求举行听证的其他情形。 前款第三项所称“较大数额罚款”，是指对个人处以二千元以上罚款，对单位处以一万元以上罚款，对违反边防出境入境管理法律、法规和规章的个人处以六千元以上罚款。对依据地方性法规或者地方政府规章作出的罚款处罚，适用听证的罚款数额按照地方规定执行。"},{"i":124,"n":"第一百二十四条","txt":"听证由公安机关法制部门组织实施。 依法具有独立执法主体资格的公安机关业务部门以及出入境边防检查站依法作出行政处罚决定的，由其非本案调查人员组织听证。"},{"i":125,"n":"第一百二十五条","txt":"公安机关不得因违法嫌疑人提出听证要求而加重处罚。"},{"i":126,"n":"第一百二十六条","txt":"听证人员应当就行政案件的事实、证据、程序、适用法律等方面全面听取当事人陈述和申辩。"},{"i":127,"n":"第一百二十七条","txt":"听证设听证主持人一名，负责组织听证；记录员一名，负责制作听证笔录。必要时，可以设听证员一至二名，协助听证主持人进行听证。 本案调查人员不得担任听证主持人、听证员或者记录员。"},{"i":128,"n":"第一百二十八条","txt":"听证主持人决定或者开展下列事项： （一）举行听证的时间、地点； （二）听证是否公开举行； （三）要求听证参加人到场参加听证，提供或者补充证据； （四）听证的延期、中止或者终止； （五）主持听证，就案件的事实、理由、证据、程序、适用法律等组织质证和辩论； （六）维持听证秩序，对违反听证纪律的行为予以制止； （七）听证员、记录员的回避； （八）其他有关事项。"},{"i":129,"n":"第一百二十九条","txt":"听证参加人包括： （一）当事人及其代理人； （二）本案办案人民警察； （三）证人、鉴定人、翻译人员； （四）其他有关人员。"},{"i":130,"n":"第一百三十条","txt":"当事人在听证活动中享有下列权利： （一）申请回避； （二）委托一至二人代理参加听证； （三）进行陈述、申辩和质证； （四）核对、补正听证笔录； （五）依法享有的其他权利。"},{"i":131,"n":"第一百三十一条","txt":"与听证案件处理结果有直接利害关系的其他公民、法人或者其他组织，作为第三人申请参加听证的，应当允许。为查明案情，必要时，听证主持人也可以通知其参加听证。"},{"i":132,"n":"第一百三十二条","txt":"对适用听证程序的行政案件，办案部门在提出处罚意见后，应当告知违法嫌疑人拟作出的行政处罚和有要求举行听证的权利。"},{"i":133,"n":"第一百三十三条","txt":"违法嫌疑人要求听证的，应当在公安机关告知后三日内提出申请。"},{"i":134,"n":"第一百三十四条","txt":"违法嫌疑人放弃听证或者撤回听证要求后，处罚决定作出前，又提出听证要求的，只要在听证申请有效期限内，应当允许。"},{"i":135,"n":"第一百三十五条","txt":"公安机关收到听证申请后，应当在二日内决定是否受理。认为听证申请人的要求不符合听证条件，决定不予受理的，应当制作不予受理听证通知书，告知听证申请人。逾期不通知听证申请人的，视为受理。"},{"i":136,"n":"第一百三十六条","txt":"公安机关受理听证后，应当在举行听证的七日前将举行听证通知书送达听证申请人，并将举行听证的时间、地点通知其他听证参加人。"},{"i":137,"n":"第一百三十七条","txt":"听证应当在公安机关收到听证申请之日起十日内举行。 除涉及国家秘密、商业秘密、个人隐私的行政案件外，听证应当公开举行。"},{"i":138,"n":"第一百三十八条","txt":"听证申请人不能按期参加听证的，可以申请延期，是否准许，由听证主持人决定。"},{"i":139,"n":"第一百三十九条","txt":"二个以上违法嫌疑人分别对同一行政案件提出听证要求的，可以合并举行。"},{"i":140,"n":"第一百四十条","txt":"同一行政案件中有二个以上违法嫌疑人，其中部分违法嫌疑人提出听证申请的，应当在听证举行后一并作出处理决定。"},{"i":141,"n":"第一百四十一条","txt":"听证开始时，听证主持人核对听证参加人；宣布案由；宣布听证员、记录员和翻译人员名单；告知当事人在听证中的权利和义务；询问当事人是否提出回避申请；对不公开听证的行政案件，宣布不公开听证的理由。"},{"i":142,"n":"第一百四十二条","txt":"听证开始后，首先由办案人民警察提出听证申请人违法的事实、证据和法律依据及行政处罚意见。"},{"i":143,"n":"第一百四十三条","txt":"办案人民警察提出证据时，应当向听证会出示。对证人证言、鉴定意见、勘验笔录和其他作为证据的文书，应当当场宣读。"},{"i":144,"n":"第一百四十四条","txt":"听证申请人可以就办案人民警察提出的违法事实、证据和法律依据以及行政处罚意见进行陈述、申辩和质证，并可以提出新的证据。 第三人可以陈述事实，提出新的证据。"},{"i":145,"n":"第一百四十五条","txt":"听证过程中，当事人及其代理人有权申请通知新的证人到会作证，调取新的证据。对上述申请，听证主持人应当当场作出是否同意的决定；申请重新鉴定的，按照本规定第七章第五节有关规定办理。"},{"i":146,"n":"第一百四十六条","txt":"听证申请人、第三人和办案人民警察可以围绕案件的事实、证据、程序、适用法律、处罚种类和幅度等问题进行辩论。"},{"i":147,"n":"第一百四十七条","txt":"辩论结束后，听证主持人应当听取听证申请人、第三人、办案人民警察各方最后陈述意见。"},{"i":148,"n":"第一百四十八条","txt":"听证过程中，遇有下列情形之一，听证主持人可以中止听证： （一）需要通知新的证人到会、调取新的证据或者需要重新鉴定或者勘验的； （二）因回避致使听证不能继续进行的； （三）其他需要中止听证的。 中止听证的情形消除后，听证主持人应当及时恢复听证。"},{"i":149,"n":"第一百四十九条","txt":"听证过程中，遇有下列情形之一，应当终止听证： （一）听证申请人撤回听证申请的； （二）听证申请人及其代理人无正当理由拒不出席或者未经听证主持人许可中途退出听证的； （三）听证申请人死亡或者作为听证申请人的法人或者其他组织被撤销、解散的； （四）听证过程中，听证申请人或者其代理人扰乱听证秩序，不听劝阻，致使听证无法正常进行的； （五）其他需要终止听证的。"},{"i":150,"n":"第一百五十条","txt":"听证参加人和旁听人员应当遵守听证会场纪律。对违反听证会场纪律的，听证主持人应当警告制止；对不听制止，干扰听证正常进行的旁听人员，责令其退场。"},{"i":151,"n":"第一百五十一条","txt":"记录员应当将举行听证的情况记入听证笔录。听证笔录应当载明下列内容： （一）案由； （二）听证的时间、地点和方式； （三）听证人员和听证参加人的身份情况； （四）办案人民警察陈述的事实、证据和法律依据以及行政处罚意见； （五）听证申请人或者其代理人的陈述和申辩； （六）第三人陈述的事实和理由； （七）办案人民警察、听证申请人或者其代理人、第三人质证、辩论的内容； （八）证人陈述的事实； （九）听证申请人、第三人、办案人民警察的最后陈述意见； （十）其他事项。"},{"i":152,"n":"第一百五十二条","txt":"听证笔录应当交听证申请人阅读或者向其宣读。听证笔录中的证人陈述部分，应当交证人阅读或者向其宣读。听证申请人或者证人认为听证笔录有误的，可以请求补充或者改正。听证申请人或者证人审核无误后签名或者捺指印。听证申请人或者证人拒绝的，由记录员在听证笔录中记明情况。 听证笔录经听证主持人审阅后，由听证主持人、听证员和记录员签名。"},{"i":153,"n":"第一百五十三条","txt":"听证结束后，听证主持人应当写出听证报告书，连同听证笔录一并报送公安机关负责人。 听证报告书应当包括下列内容： （一）案由； （二）听证人员和听证参加人的基本情况； （三）听证的时间、地点和方式； （四）听证会的基本情况； （五）案件事实； （六）处理意见和建议。"},{"i":154,"n":"第一百五十四条","txt":"违反治安管理行为在六个月内没有被公安机关发现，其他违法行为在二年内没有被公安机关发现的，不再给予行政处罚。 前款规定的期限，从违法行为发生之日起计算，违法行为有连续、继续或者持续状态的，从行为终了之日起计算。 被侵害人在违法行为追究时效内向公安机关控告，公安机关应当受理而不受理的，不受本条第一款追究时效的限制。"},{"i":155,"n":"第一百五十五条","txt":"实施行政处罚时，应当责令违法行为人当场或者限期改正违法行为。"},{"i":156,"n":"第一百五十六条","txt":"对违法行为人的同一个违法行为，不得给予两次以上罚款的行政处罚。"},{"i":157,"n":"第一百五十七条","txt":"不满十四周岁的人有违法行为的，不予行政处罚，但是应当责令其监护人严加管教，并在不予行政处罚决定书中载明。已满十四周岁不满十八周岁的人有违法行为的，从轻或者减轻行政处罚。"},{"i":158,"n":"第一百五十八条","txt":"精神病人在不能辨认或者不能控制自己行为时有违法行为的，不予行政处罚，但应当责令其监护人严加看管和治疗，并在不予行政处罚决定书中载明。间歇性精神病人在精神正常时有违法行为的，应当给予行政处罚。尚未完全丧失辨认或者控制自己行为能力的精神病人有违法行为的，应当予以行政处罚，但可以从轻或者减轻行政处罚。"},{"i":159,"n":"第一百五十九条","txt":"违法行为人有下列情形之一的，应当从轻、减轻处罚或者不予行政处罚： （一）主动消除或者减轻违法行为危害后果，并取得被侵害人谅解的； （二）受他人胁迫或者诱骗的； （三）有立功表现的； （四）主动投案，向公安机关如实陈述自己的违法行为的； （五）其他依法应当从轻、减轻或者不予行政处罚的。 违法行为轻微并及时纠正，没有造成危害后果的，不予行政处罚。 盲人或者又聋又哑的人违反治安管理的，可以从轻、减轻或者不予行政处罚；醉酒的人违反治安管理的，应当给予处罚。"},{"i":160,"n":"第一百六十条","txt":"违法行为人有下列情形之一的，应当从重处罚： （一）有较严重后果的； （二）教唆、胁迫、诱骗他人实施违法行为的； （三）对报案人、控告人、举报人、证人等打击报复的； （四）六个月内曾受过治安管理处罚或者一年内因同类违法行为受到两次以上公安行政处罚的； （五）刑罚执行完毕三年内，或者在缓刑期间，违反治安管理的。"},{"i":161,"n":"第一百六十一条","txt":"一人有两种以上违法行为的，分别决定，合并执行，可以制作一份决定书，分别写明对每种违法行为的处理内容和合并执行的内容。 一个案件有多个违法行为人的，分别决定，可以制作一式多份决定书，写明给予每个人的处理决定，分别送达每一个违法行为人。"},{"i":162,"n":"第一百六十二条","txt":"行政拘留处罚合并执行的，最长不超过二十日。 行政拘留处罚执行完毕前，发现违法行为人有其他违法行为，公安机关依法作出行政拘留决定的，与正在执行的行政拘留合并执行。"},{"i":163,"n":"第一百六十三条","txt":"对决定给予行政拘留处罚的人，在处罚前因同一行为已经被采取强制措施限制人身自由的时间应当折抵。限制人身自由一日，折抵执行行政拘留一日。询问查证、继续盘问和采取约束措施的时间不予折抵。 被采取强制措施限制人身自由的时间超过决定的行政拘留期限的，行政拘留决定不再执行。"},{"i":164,"n":"第一百六十四条","txt":"违法行为人具有下列情形之一，依法应当给予行政拘留处罚的，应当作出处罚决定，但不送拘留所执行： （一）已满十四周岁不满十六周岁的； （二）已满十六周岁不满十八周岁，初次违反治安管理或者其他公安行政管理的。但是，曾被收容教养、被行政拘留依法不执行行政拘留或者曾因实施扰乱公共秩序，妨害公共安全，侵犯人身权利、财产权利，妨害社会管理的行为被人民法院判决有罪的除外； （三）七十周岁以上的； （四）孕妇或者正在哺乳自己婴儿的妇女。"},{"i":165,"n":"第一百六十五条","txt":"公安机关办理治安案件的期限，自受理之日起不得超过三十日；案情重大、复杂的，经上一级公安机关批准，可以延长三十日。办理其他行政案件，有法定办案期限的，按照相关法律规定办理。 为了查明案情进行鉴定的期间，不计入办案期限。 对因违反治安管理行为人不明或者逃跑等客观原因造成案件在法定期限内无法作出行政处理决定的，公安机关应当继续进行调查取证，并向被侵害人说明情况，及时依法作出处理决定。"},{"i":166,"n":"第一百六十六条","txt":"违法嫌疑人不讲真实姓名、住址，身份不明，但只要违法事实清楚、证据确实充分的，可以按其自报的姓名并贴附照片作出处理决定，并在相关法律文书中注明。"},{"i":167,"n":"第一百六十七条","txt":"在作出行政处罚决定前，应当告知违法嫌疑人拟作出行政处罚决定的事实、理由及依据，并告知违法嫌疑人依法享有陈述权和申辩权。单位违法的，应当告知其法定代表人、主要负责人或者其授权的人员。 适用一般程序作出行政处罚决定的，采用书面形式或者笔录形式告知。 依照本规定第一百七十二条第一款第三项作出不予行政处罚决定的，可以不履行本条第一款规定的告知程序。"},{"i":168,"n":"第一百六十八条","txt":"对违法行为事实清楚，证据确实充分，依法应当予以行政处罚，因违法行为人逃跑等原因无法履行告知义务的，公安机关可以采取公告方式予以告知。自公告之日起七日内，违法嫌疑人未提出申辩的，可以依法作出行政处罚决定。"},{"i":169,"n":"第一百六十九条","txt":"违法嫌疑人有权进行陈述和申辩。对违法嫌疑人提出的新的事实、理由和证据，公安机关应当进行复核。 公安机关不得因违法嫌疑人申辩而加重处罚。"},{"i":170,"n":"第一百七十条","txt":"对行政案件进行审核、审批时，应当审查下列内容： （一）违法嫌疑人的基本情况； （二）案件事实是否清楚，证据是否确实充分； （三）案件定性是否准确； （四）适用法律、法规和规章是否正确； （五）办案程序是否合法； （六）拟作出的处理决定是否适当。"},{"i":171,"n":"第一百七十一条","txt":"法制员或者办案部门指定的人员、办案部门负责人、法制部门的人员可以作为行政案件审核人员。 初次从事行政处罚决定审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":172,"n":"第一百七十二条","txt":"公安机关根据行政案件的不同情况分别作出下列处理决定： （一）确有违法行为，应当给予行政处罚的，根据其情节和危害后果的轻重，作出行政处罚决定； （二）确有违法行为，但有依法不予行政处罚情形的，作出不予行政处罚决定；有违法所得和非法财物、违禁品、管制器具的，应当予以追缴或者收缴； （三）违法事实不能成立的，作出不予行政处罚决定； （四）对需要给予社区戒毒、强制隔离戒毒、收容教养等处理的，依法作出决定； （五）违法行为涉嫌构成犯罪的，转为刑事案件办理或者移送有权处理的主管机关、部门办理，无需撤销行政案件。公安机关已经作出行政处理决定的，应当附卷； （六）发现违法行为人有其他违法行为的，在依法作出行政处理决定的同时，通知有关行政主管部门处理。 对已经依照前款第三项作出不予行政处罚决定的案件，又发现新的证据的，应当依法及时调查；违法行为能够认定的，依法重新作出处理决定，并撤销原不予行政处罚决定。"},{"i":173,"n":"第一百七十三条","txt":"行政拘留处罚由县级以上公安机关或者出入境边防检查机关决定。依法应当对违法行为人予以行政拘留的，公安派出所、依法具有独立执法主体资格的公安机关业务部门应当报其所属的县级以上公安机关决定。"},{"i":174,"n":"第一百七十四条","txt":"对县级以上的各级人民代表大会代表予以行政拘留的，作出处罚决定前应当经该级人民代表大会主席团或者人民代表大会常务委员会许可。 对乡、民族乡、镇的人民代表大会代表予以行政拘留的，作出决定的公安机关应当立即报告乡、民族乡、镇的人民代表大会。"},{"i":175,"n":"第一百七十五条","txt":"作出行政处罚决定的，应当制作行政处罚决定书。决定书应当载明下列内容： （一）被处罚人的姓名、性别、出生日期、身份证件种类及号码、户籍所在地、现住址、工作单位、违法经历以及被处罚单位的名称、地址和法定代表人； （二）违法事实和证据以及从重、从轻、减轻等情节； （三）处罚的种类、幅度和法律依据； （四）处罚的执行方式和期限； （五）对涉案财物的处理结果及对被处罚人的其他处理情况； （六）对处罚决定不服，申请行政复议、提起行政诉讼的途径和期限； （七）作出决定的公安机关的名称、印章和日期。 作出罚款处罚的，行政处罚决定书应当载明逾期不缴纳罚款依法加处罚款的标准和最高限额；对涉案财物作出处理的，行政处罚决定书应当附没收、收缴、追缴物品清单。"},{"i":176,"n":"第一百七十六条","txt":"作出行政拘留处罚决定的，应当及时将处罚情况和执行场所或者依法不执行的情况通知被处罚人家属。 作出社区戒毒决定的，应当通知被决定人户籍所在地或者现居住地的城市街道办事处、乡镇人民政府。作出强制隔离戒毒、收容教养决定的，应当在法定期限内通知被决定人的家属、所在单位、户籍所在地公安派出所。 被处理人拒不提供家属联系方式或者不讲真实姓名、住址，身份不明的，可以不予通知，但应当在附卷的决定书中注明。"},{"i":177,"n":"第一百七十七条","txt":"公安机关办理的刑事案件，尚不够刑事处罚，依法应当给予公安行政处理的，经县级以上公安机关负责人批准，依照本章规定作出处理决定。"},{"i":178,"n":"第一百七十八条","txt":"对于因民间纠纷引起的殴打他人、故意伤害、侮辱、诽谤、诬告陷害、故意损毁财物、干扰他人正常生活、侵犯隐私、非法侵入住宅等违反治安管理行为，情节较轻，且具有下列情形之一的，可以调解处理： （一）亲友、邻里、同事、在校学生之间因琐事发生纠纷引起的； （二）行为人的侵害行为系由被侵害人事前的过错行为引起的； （三）其他适用调解处理更易化解矛盾的。 对不构成违反治安管理行为的民间纠纷，应当告知当事人向人民法院或者人民调解组织申请处理。 对情节轻微、事实清楚、因果关系明确，不涉及医疗费用、物品损失或者双方当事人对医疗费用和物品损失的赔付无争议，符合治安调解条件，双方当事人同意当场调解并当场履行的治安案件，可以当场调解，并制作调解协议书。当事人基本情况、主要违法事实和协议内容在现场录音录像中明确记录的，不再制作调解协议书。"},{"i":179,"n":"第一百七十九条","txt":"具有下列情形之一的，不适用调解处理： （一）雇凶伤害他人的； （二）结伙斗殴或者其他寻衅滋事的； （三）多次实施违反治安管理行为的； （四）当事人明确表示不愿意调解处理的； （五）当事人在治安调解过程中又针对对方实施违反治安管理行为的； （六）调解过程中，违法嫌疑人逃跑的； （七）其他不宜调解处理的。"},{"i":180,"n":"第一百八十条","txt":"调解处理案件，应当查明事实，收集证据，并遵循合法、公正、自愿、及时的原则，注重教育和疏导，化解矛盾。"},{"i":181,"n":"第一百八十一条","txt":"当事人中有未成年人的，调解时应当通知其父母或者其他监护人到场。但是，当事人为年满十六周岁以上的未成年人，以自己的劳动收入为主要生活来源，本人同意不通知的，可以不通知。 被侵害人委托其他人参加调解的，应当向公安机关提交委托书，并写明委托权限。违法嫌疑人不得委托他人参加调解。"},{"i":182,"n":"第一百八十二条","txt":"对因邻里纠纷引起的治安案件进行调解时，可以邀请当事人居住地的居（村）民委员会的人员或者双方当事人熟悉的人员参加帮助调解。"},{"i":183,"n":"第一百八十三条","txt":"调解一般为一次。对一次调解不成，公安机关认为有必要或者当事人申请的，可以再次调解，并应当在第一次调解后的七个工作日内完成。"},{"i":184,"n":"第一百八十四条","txt":"调解达成协议的，在公安机关主持下制作调解协议书，双方当事人应当在调解协议书上签名，并履行调解协议。 调解协议书应当包括调解机关名称、主持人、双方当事人和其他在场人员的基本情况，案件发生时间、地点、人员、起因、经过、情节、结果等情况、协议内容、履行期限和方式等内容。 对调解达成协议的，应当保存案件证据材料，与其他文书材料和调解协议书一并归入案卷。"},{"i":185,"n":"第一百八十五条","txt":"调解达成协议并履行的，公安机关不再处罚。对调解未达成协议或者达成协议后不履行的，应当对违反治安管理行为人依法予以处罚；对违法行为造成的损害赔偿纠纷，公安机关可以进行调解，调解不成的，应当告知当事人向人民法院提起民事诉讼。 调解案件的办案期限从调解未达成协议或者调解达成协议不履行之日起开始计算。"},{"i":186,"n":"第一百八十六条","txt":"对符合本规定第一百七十八条规定的治安案件，当事人申请人民调解或者自行和解，达成协议并履行后，双方当事人书面申请并经公安机关认可的，公安机关不予治安管理处罚，但公安机关已依法作出处理决定的除外。"},{"i":187,"n":"第一百八十七条","txt":"对于依法扣押、扣留、查封、抽样取证、追缴、收缴的财物以及由公安机关负责保管的先行登记保存的财物，公安机关应当妥善保管，不得使用、挪用、调换或者损毁。造成损失的，应当承担赔偿责任。 涉案财物的保管费用由作出决定的公安机关承担。"},{"i":188,"n":"第一百八十八条","txt":"县级以上公安机关应当指定一个内设部门作为涉案财物管理部门，负责对涉案财物实行统一管理，并设立或者指定专门保管场所，对涉案财物进行集中保管。涉案财物集中保管的范围，由地方公安机关根据本地区实际情况确定。 对价值较低、易于保管，或者需要作为证据继续使用，以及需要先行返还被侵害人的涉案财物，可以由办案部门设置专门的场所进行保管。办案部门应当指定不承担办案工作的民警负责本部门涉案财物的接收、保管、移交等管理工作；严禁由办案人员自行保管涉案财物。 对查封的场所、设施、财物，可以委托第三人保管，第三人不得损毁或者擅自转移、处置。因第三人的原因造成的损失，公安机关先行赔付后，有权向第三人追偿。"},{"i":189,"n":"第一百八十九条","txt":"公安机关涉案财物管理部门和办案部门应当建立电子台账，对涉案财物逐一编号登记，载明案由、来源、保管状态、场所和去向。"},{"i":190,"n":"第一百九十条","txt":"办案人民警察应当在依法提取涉案财物后的二十四小时内将财物移交涉案财物管理人员，并办理移交手续。对查封、冻结、先行登记保存的涉案财物，应当在采取措施后的二十四小时内，将法律文书复印件及涉案财物的情况送交涉案财物管理人员予以登记。 在异地或者在偏远、交通不便地区提取涉案财物的，办案人民警察应当在返回单位后的二十四小时内移交。 对情况紧急，需要在提取涉案财物后的二十四小时内进行鉴定、辨认、检验、检查等工作的，经办案部门负责人批准，可以在完成上述工作后的二十四小时内移交。 在提取涉案财物后的二十四小时内已将涉案财物处理完毕的，不再移交，但应当将处理涉案财物的相关手续附卷保存。 因询问、鉴定、辨认、检验、检查等办案需要，经办案部门负责人批准，办案人民警察可以调用涉案财物，并及时归还。"},{"i":191,"n":"第一百九十一条","txt":"对容易腐烂变质及其他不易保管的物品、危险物品，经公安机关负责人批准，在拍照或者录像后依法变卖或者拍卖，变卖或者拍卖的价款暂予保存，待结案后按有关规定处理。 对易燃、易爆、毒害性、放射性等危险物品应当存放在符合危险物品存放条件的专门场所。 对属于被侵害人或者善意第三人合法占有的财物，应当在登记、拍照或者录像、估价后及时返还，并在案卷中注明返还的理由，将原物照片、清单和领取手续存卷备查。 对不宜入卷的物证，应当拍照入卷，原物在结案后按照有关规定处理。"},{"i":192,"n":"第一百九十二条","txt":"有关违法行为查证属实后，对有证据证明权属明确且无争议的被侵害人合法财物及其孳息，凡返还不损害其他被侵害人或者利害关系人的利益，不影响案件正常办理的，应当在登记、拍照或者录像和估价后，及时发还被侵害人。办案人民警察应当在案卷材料中注明返还的理由，并将原物照片、清单和被侵害人的领取手续附卷。"},{"i":193,"n":"第一百九十三条","txt":"在作出行政处理决定时，应当对涉案财物一并作出处理。"},{"i":194,"n":"第一百九十四条","txt":"对在办理行政案件中查获的下列物品应当依法收缴： （一）毒品、淫秽物品等违禁品； （二）赌具和赌资； （三）吸食、注射毒品的用具； （四）伪造、变造的公文、证件、证明文件、票证、印章等； （五）倒卖的车船票、文艺演出票、体育比赛入场券等有价票证； （六）主要用于实施违法行为的本人所有的工具以及直接用于实施毒品违法行为的资金； （七）法律、法规规定可以收缴的其他非法财物。 前款第六项所列的工具，除非有证据表明属于他人合法所有，可以直接认定为违法行为人本人所有。对明显无价值的，可以不作出收缴决定，但应当在证据保全文书中注明处理情况。 违法所得应当依法予以追缴或者没收。 多名违法行为人共同实施违法行为，违法所得或者非法财物无法分清所有人的，作为共同违法所得或者非法财物予以处理。"},{"i":195,"n":"第一百九十五条","txt":"收缴由县级以上公安机关决定。但是，违禁品，管制器具，吸食、注射毒品的用具以及非法财物价值在五百元以下且当事人对财物价值无异议的，公安派出所可以收缴。 追缴由县级以上公安机关决定。但是，追缴的财物应当退还被侵害人的，公安派出所可以追缴。"},{"i":196,"n":"第一百九十六条","txt":"对收缴和追缴的财物，经原决定机关负责人批准，按照下列规定分别处理： （一）属于被侵害人或者善意第三人的合法财物，应当及时返还； （二）没有被侵害人的，登记造册，按照规定上缴国库或者依法变卖、拍卖后，将所得款项上缴国库； （三）违禁品、没有价值的物品，或者价值轻微，无法变卖、拍卖的物品，统一登记造册后销毁； （四）对无法变卖或者拍卖的危险物品，由县级以上公安机关主管部门组织销毁或者交有关厂家回收。"},{"i":197,"n":"第一百九十七条","txt":"对应当退还原主或者当事人的财物，通知原主或者当事人在六个月内来领取；原主不明确的，应当采取公告方式告知原主认领。在通知原主、当事人或者公告后六个月内，无人认领的，按无主财物处理，登记后上缴国库，或者依法变卖或者拍卖后，将所得款项上缴国库。遇有特殊情况的，可酌情延期处理，延长期限最长不超过三个月。"},{"i":198,"n":"第一百九十八条","txt":"公安机关依法作出行政处理决定后，被处理人应当在行政处理决定的期限内予以履行。逾期不履行的，作出行政处理决定的公安机关可以依法强制执行或者申请人民法院强制执行。"},{"i":199,"n":"第一百九十九条","txt":"被处理人对行政处理决定不服申请行政复议或者提起行政诉讼的，行政处理决定不停止执行，但法律另有规定的除外。"},{"i":200,"n":"第二百条","txt":"公安机关在依法作出强制执行决定或者申请人民法院强制执行前，应当事先催告被处理人履行行政处理决定。催告以书面形式作出，并直接送达被处理人。被处理人拒绝接受或者无法直接送达被处理人的，依照本规定第五章的有关规定送达。 催告书应当载明下列事项： （一）履行行政处理决定的期限和方式； （二）涉及金钱给付的，应当有明确的金额和给付方式； （三）被处理人依法享有的陈述权和申辩权。"},{"i":201,"n":"第二百零一条","txt":"被处理人收到催告书后有权进行陈述和申辩。公安机关应当充分听取并记录、复核。被处理人提出的事实、理由或者证据成立的，公安机关应当采纳。"},{"i":202,"n":"第二百零二条","txt":"经催告，被处理人无正当理由逾期仍不履行行政处理决定，法律规定由公安机关强制执行的，公安机关可以依法作出强制执行决定。 在催告期间，对有证据证明有转移或者隐匿财物迹象的，公安机关可以作出立即强制执行决定。 强制执行决定应当以书面形式作出，并载明下列事项： （一）被处理人的姓名或者名称、地址； （二）强制执行的理由和依据； （三）强制执行的方式和时间； （四）申请行政复议或者提起行政诉讼的途径和期限； （五）作出决定的公安机关名称、印章和日期。"},{"i":203,"n":"第二百零三条","txt":"依法作出要求被处理人履行排除妨碍、恢复原状等义务的行政处理决定，被处理人逾期不履行，经催告仍不履行，其后果已经或者将危害交通安全的，公安机关可以代履行，或者委托没有利害关系的第三人代履行。 代履行应当遵守下列规定： （一）代履行前送达决定书，代履行决定书应当载明当事人的姓名或者名称、地址，代履行的理由和依据、方式和时间、标的、费用预算及代履行人； （二）代履行三日前，催告当事人履行，当事人履行的，停止代履行； （三）代履行时，作出决定的公安机关应当派员到场监督； （四）代履行完毕，公安机关到场监督人员、代履行人和当事人或者见证人应当在执行文书上签名或者盖章。 代履行的费用由当事人承担。但是，法律另有规定的除外。"},{"i":204,"n":"第二百零四条","txt":"需要立即清理道路的障碍物，当事人不能清除的，或者有其他紧急情况需要立即履行的，公安机关可以决定立即实施代履行。当事人不在场的，公安机关应当在事后立即通知当事人，并依法作出处理。"},{"i":205,"n":"第二百零五条","txt":"实施行政强制执行，公安机关可以在不损害公共利益和他人合法权益的情况下，与当事人达成执行协议。执行协议可以约定分阶段履行；当事人采取补救措施的，可以减免加处的罚款。 执行协议应当履行。被处罚人不履行执行协议的，公安机关应当恢复强制执行。"},{"i":206,"n":"第二百零六条","txt":"当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政处理决定的，法律没有规定公安机关强制执行的，作出行政处理决定的公安机关可以自期限届满之日起三个月内，向所在地有管辖权的人民法院申请强制执行。因情况紧急，为保障公共安全，公安机关可以申请人民法院立即执行。 强制执行的费用由被执行人承担。"},{"i":207,"n":"第二百零七条","txt":"申请人民法院强制执行前，公安机关应当催告被处理人履行义务，催告书送达十日后被处理人仍未履行义务的，公安机关可以向人民法院申请强制执行。"},{"i":208,"n":"第二百零八条","txt":"公安机关向人民法院申请强制执行，应当提供下列材料： （一）强制执行申请书； （二）行政处理决定书及作出决定的事实、理由和依据； （三）当事人的意见及公安机关催告情况； （四）申请强制执行标的情况； （五）法律、法规规定的其他材料。 强制执行申请书应当由作出处理决定的公安机关负责人签名，加盖公安机关印章，并注明日期。"},{"i":209,"n":"第二百零九条","txt":"公安机关对人民法院不予受理强制执行申请、不予强制执行的裁定有异议的，可以在十五日内向上一级人民法院申请复议。"},{"i":210,"n":"第二百一十条","txt":"具有下列情形之一的，中止强制执行： （一）当事人暂无履行能力的； （二）第三人对执行标的主张权利，确有理由的； （三）执行可能对他人或者公共利益造成难以弥补的重大损失的； （四）其他需要中止执行的。 中止执行的情形消失后，公安机关应当恢复执行。对没有明显社会危害，当事人确无能力履行，中止执行满三年未恢复执行的，不再执行。"},{"i":211,"n":"第二百一十一条","txt":"具有下列情形之一的，终结强制执行： （一）公民死亡，无遗产可供执行，又无义务承受人的； （二）法人或者其他组织终止，无财产可供执行，又无义务承受人的； （三）执行标的灭失的； （四）据以执行的行政处理决定被撤销的； （五）其他需要终结执行的。"},{"i":212,"n":"第二百一十二条","txt":"在执行中或者执行完毕后，据以执行的行政处理决定被撤销、变更，或者执行错误，应当恢复原状或者退还财物；不能恢复原状或者退还财物的，依法给予赔偿。"},{"i":213,"n":"第二百一十三条","txt":"除依法应当销毁的物品外，公安机关依法没收或者收缴、追缴的违法所得和非法财物，必须按照国家有关规定处理或者上缴国库。 罚款、没收或者收缴的违法所得和非法财物拍卖或者变卖的款项和没收的保证金，必须全部上缴国库，不得以任何形式截留、私分或者变相私分。"},{"i":214,"n":"第二百一十四条","txt":"公安机关作出罚款决定，被处罚人应当自收到行政处罚决定书之日起十五日内，到指定的银行缴纳罚款。具有下列情形之一的，公安机关及其办案人民警察可以当场收缴罚款，法律另有规定的，从其规定： （一）对违反治安管理行为人处五十元以下罚款和对违反交通管理的行人、乘车人和非机动车驾驶人处罚款，被处罚人没有异议的； （二）对违反治安管理、交通管理以外的违法行为人当场处二十元以下罚款的； （三）在边远、水上、交通不便地区、旅客列车上或者口岸，被处罚人向指定银行缴纳罚款确有困难，经被处罚人提出的； （四）被处罚人在当地没有固定住所，不当场收缴事后难以执行的。 对具有前款第一项和第三项情形之一的，办案人民警察应当要求被处罚人签名确认。"},{"i":215,"n":"第二百一十五条","txt":"公安机关及其人民警察当场收缴罚款的，应当出具省级或者国家财政部门统一制发的罚款收据。对不出具省级或者国家财政部门统一制发的罚款收据的，被处罚人有权拒绝缴纳罚款。"},{"i":216,"n":"第二百一十六条","txt":"人民警察应当自收缴罚款之日起二日内，将当场收缴的罚款交至其所属公安机关；在水上当场收缴的罚款，应当自抵岸之日起二日内将当场收缴的罚款交至其所属公安机关；在旅客列车上当场收缴的罚款，应当自返回之日起二日内将当场收缴的罚款交至其所属公安机关。 公安机关应当自收到罚款之日起二日内将罚款缴付指定的银行。"},{"i":217,"n":"第二百一十七条","txt":"被处罚人确有经济困难，经被处罚人申请和作出处罚决定的公安机关批准，可以暂缓或者分期缴纳罚款。"},{"i":218,"n":"第二百一十八条","txt":"被处罚人未在本规定第二百一十四条规定的期限内缴纳罚款的，作出行政处罚决定的公安机关可以采取下列措施： （一）将依法查封、扣押的被处罚人的财物拍卖或者变卖抵缴罚款。拍卖或者变卖的价款超过罚款数额的，余额部分应当及时退还被处罚人； （二）不能采取第一项措施的，每日按罚款数额的百分之三加处罚款，加处罚款总额不得超出罚款数额。 拍卖财物，由公安机关委托拍卖机构依法办理。"},{"i":219,"n":"第二百一十九条","txt":"依法加处罚款超过三十日，经催告被处罚人仍不履行的，作出行政处罚决定的公安机关可以按照本规定第二百零六条的规定向所在地有管辖权的人民法院申请强制执行。"},{"i":220,"n":"第二百二十条","txt":"对被决定行政拘留的人，由作出决定的公安机关送达拘留所执行。对抗拒执行的，可以使用约束性警械。 对被决定行政拘留的人，在异地被抓获或者具有其他有必要在异地拘留所执行情形的，经异地拘留所主管公安机关批准，可以在异地执行。"},{"i":221,"n":"第二百二十一条","txt":"对同时被决定行政拘留和社区戒毒或者强制隔离戒毒的人员，应当先执行行政拘留，由拘留所给予必要的戒毒治疗，强制隔离戒毒期限连续计算。 拘留所不具备戒毒治疗条件的，行政拘留决定机关可以直接将被行政拘留人送公安机关管理的强制隔离戒毒所代为执行行政拘留，强制隔离戒毒期限连续计算。"},{"i":222,"n":"第二百二十二条","txt":"被处罚人不服行政拘留处罚决定，申请行政复议或者提起行政诉讼的，可以向作出行政拘留决定的公安机关提出暂缓执行行政拘留的申请；口头提出申请的，公安机关人民警察应当予以记录，并由申请人签名或者捺指印。 被处罚人在行政拘留执行期间，提出暂缓执行行政拘留申请的，拘留所应当立即将申请转交作出行政拘留决定的公安机关。"},{"i":223,"n":"第二百二十三条","txt":"公安机关应当在收到被处罚人提出暂缓执行行政拘留申请之时起二十四小时内作出决定。 公安机关认为暂缓执行行政拘留不致发生社会危险，且被处罚人或者其近亲属提出符合条件的担保人，或者按每日行政拘留二百元的标准交纳保证金的，应当作出暂缓执行行政拘留的决定。 对同一被处罚人，不得同时责令其提出保证人和交纳保证金。 被处罚人已送达拘留所执行的，公安机关应当立即将暂缓执行行政拘留决定送达拘留所，拘留所应当立即释放被处罚人。"},{"i":224,"n":"第二百二十四条","txt":"被处罚人具有下列情形之一的，应当作出不暂缓执行行政拘留的决定，并告知申请人： （一）暂缓执行行政拘留后可能逃跑的； （二）有其他违法犯罪嫌疑，正在被调查或者侦查的； （三）不宜暂缓执行行政拘留的其他情形。"},{"i":225,"n":"第二百二十五条","txt":"行政拘留并处罚款的，罚款不因暂缓执行行政拘留而暂缓执行。"},{"i":226,"n":"第二百二十六条","txt":"在暂缓执行行政拘留期间，被处罚人应当遵守下列规定： （一）未经决定机关批准不得离开所居住的市、县； （二）住址、工作单位和联系方式发生变动的，在二十四小时以内向决定机关报告； （三）在行政复议和行政诉讼中不得干扰证人作证、伪造证据或者串供； （四）不得逃避、拒绝或者阻碍处罚的执行。 在暂缓执行行政拘留期间，公安机关不得妨碍被处罚人依法行使行政复议和行政诉讼权利。"},{"i":227,"n":"第二百二十七条","txt":"暂缓执行行政拘留的担保人应当符合下列条件： （一）与本案无牵连； （二）享有政治权利，人身自由未受到限制或者剥夺； （三）在当地有常住户口和固定住所； （四）有能力履行担保义务。"},{"i":228,"n":"第二百二十八条","txt":"公安机关经过审查认为暂缓执行行政拘留的担保人符合条件的，由担保人出具保证书，并到公安机关将被担保人领回。"},{"i":229,"n":"第二百二十九条","txt":"暂缓执行行政拘留的担保人应当履行下列义务： （一）保证被担保人遵守本规定第二百二十六条  的规定； （二）发现被担保人伪造证据、串供或者逃跑的，及时向公安机关报告。 暂缓执行行政拘留的担保人不履行担保义务，致使被担保人逃避行政拘留处罚执行的，公安机关可以对担保人处以三千元以下罚款，并对被担保人恢复执行行政拘留。 暂缓执行行政拘留的担保人履行了担保义务，但被担保人仍逃避行政拘留处罚执行的，或者被处罚人逃跑后，担保人积极帮助公安机关抓获被处罚人的，可以从轻或者不予行政处罚。"},{"i":230,"n":"第二百三十条","txt":"暂缓执行行政拘留的担保人在暂缓执行行政拘留期间，不愿继续担保或者丧失担保条件的，行政拘留的决定机关应当责令被处罚人重新提出担保人或者交纳保证金。不提出担保人又不交纳保证金的，行政拘留的决定机关应当将被处罚人送拘留所执行。"},{"i":231,"n":"第二百三十一条","txt":"保证金应当由银行代收。在银行非营业时间，公安机关可以先行收取，并在收到保证金后的三日内存入指定的银行账户。 公安机关应当指定办案部门以外的法制、装备财务等部门负责管理保证金。严禁截留、坐支、挪用或者以其他任何形式侵吞保证金。"},{"i":232,"n":"第二百三十二条","txt":"行政拘留处罚被撤销或者开始执行时，公安机关应当将保证金退还交纳人。 被决定行政拘留的人逃避行政拘留处罚执行的，由决定行政拘留的公安机关作出没收或者部分没收保证金的决定，行政拘留的决定机关应当将被处罚人送拘留所执行。"},{"i":233,"n":"第二百三十三条","txt":"被处罚人对公安机关没收保证金的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":234,"n":"第二百三十四条","txt":"作出吊销公安机关发放的许可证或者执照处罚的，应当在被吊销的许可证或者执照上加盖吊销印章后收缴。被处罚人拒不缴销证件的，公安机关可以公告宣布作废。吊销许可证或者执照的机关不是发证机关的，作出决定的机关应当在处罚决定生效后及时通知发证机关。"},{"i":235,"n":"第二百三十五条","txt":"作出取缔决定的，可以采取在经营场所张贴公告等方式予以公告，责令被取缔者立即停止经营活动；有违法所得的，依法予以没收或者追缴。拒不停止经营活动的，公安机关可以依法没收或者收缴其专门用于从事非法经营活动的工具、设备。已经取得营业执照的，公安机关应当通知工商行政管理部门依法撤销其营业执照。"},{"i":236,"n":"第二百三十六条","txt":"对拒不执行公安机关依法作出的责令停产停业决定的，公安机关可以依法强制执行或者申请人民法院强制执行。"},{"i":237,"n":"第二百三十七条","txt":"对被决定强制隔离戒毒、收容教养的人员，由作出决定的公安机关送强制隔离戒毒场所、收容教养场所执行。 对被决定社区戒毒的人员，公安机关应当责令其到户籍所在地接受社区戒毒，在户籍所在地以外的现居住地有固定住所的，可以责令其在现居住地接受社区戒毒。"},{"i":238,"n":"第二百三十八条","txt":"办理涉外行政案件，应当维护国家主权和利益，坚持平等互利原则。"},{"i":239,"n":"第二百三十九条","txt":"对外国人国籍的确认，以其入境时有效证件上所表明的国籍为准；国籍有疑问或者国籍不明的，由公安机关出入境管理部门协助查明。 对无法查明国籍、身份不明的外国人，按照其自报的国籍或者无国籍人对待。"},{"i":240,"n":"第二百四十条","txt":"违法行为人为享有外交特权和豁免权的外国人的，办案公安机关应当将其身份、证件及违法行为等基本情况记录在案，保存有关证据，并尽快将有关情况层报省级公安机关，由省级公安机关商请同级人民政府外事部门通过外交途径处理。 对享有外交特权和豁免权的外国人，不得采取限制人身自由和查封、扣押的强制措施。"},{"i":241,"n":"第二百四十一条","txt":"办理涉外行政案件，应当使用中华人民共和国通用的语言文字。对不通晓我国语言文字的，公安机关应当为其提供翻译；当事人通晓我国语言文字，不需要他人翻译的，应当出具书面声明。 经县级以上公安机关负责人批准，外国籍当事人可以自己聘请翻译，翻译费由其个人承担。"},{"i":242,"n":"第二百四十二条","txt":"外国人具有下列情形之一，经当场盘问或者继续盘问后不能排除嫌疑，需要作进一步调查的，经县级以上公安机关或者出入境边防检查机关负责人批准，可以拘留审查： （一）有非法出境入境嫌疑的； （二）有协助他人非法出境入境嫌疑的； （三）有非法居留、非法就业嫌疑的； （四）有危害国家安全和利益，破坏社会公共秩序或者从事其他违法犯罪活动嫌疑的。 实施拘留审查，应当出示拘留审查决定书，并在二十四小时内进行询问。 拘留审查的期限不得超过三十日，案情复杂的，经上一级公安机关或者出入境边防检查机关批准可以延长至六十日。对国籍、身份不明的，拘留审查期限自查清其国籍、身份之日起计算。"},{"i":243,"n":"第二百四十三条","txt":"具有下列情形之一的，应当解除拘留审查： （一）被决定遣送出境、限期出境或者驱逐出境的； （二）不应当拘留审查的； （三）被采取限制活动范围措施的； （四）案件移交其他部门处理的； （五）其他应当解除拘留审查的。"},{"i":244,"n":"第二百四十四条","txt":"外国人具有下列情形之一的，不适用拘留审查，经县级以上公安机关或者出入境边防检查机关负责人批准，可以限制其活动范围： （一）患有严重疾病的； （二）怀孕或者哺乳自己婴儿的； （三）未满十六周岁或者已满七十周岁的； （四）不宜适用拘留审查的其他情形。 被限制活动范围的外国人，应当按照要求接受审查，未经公安机关批准，不得离开限定的区域。限制活动范围的期限不得超过六十日。对国籍、身份不明的，限制活动范围期限自查清其国籍、身份之日起计算。"},{"i":245,"n":"第二百四十五条","txt":"被限制活动范围的外国人应当遵守下列规定： （一）未经决定机关批准，不得变更生活居所，超出指定的活动区域； （二）在传唤的时候及时到案； （三）不得以任何形式干扰证人作证； （四）不得毁灭、伪造证据或者串供。"},{"i":246,"n":"第二百四十六条","txt":"外国人具有下列情形之一的，经县级以上公安机关或者出入境边防检查机关负责人批准，可以遣送出境： （一）被处限期出境，未在规定期限内离境的； （二）有不准入境情形的； （三）非法居留、非法就业的； （四）违反法律、行政法规需要遣送出境的。 其他境外人员具有前款所列情形之一的，可以依法遣送出境。 被遣送出境的人员，自被遣送出境之日起一至五年内不准入境。"},{"i":247,"n":"第二百四十七条","txt":"被遣送出境的外国人可以被遣送至下列国家或者地区： （一）国籍国； （二）入境前的居住国或者地区； （三）出生地国或者地区； （四）入境前的出境口岸的所属国或者地区； （五）其他允许被遣送出境的外国人入境的国家或者地区。"},{"i":248,"n":"第二百四十八条","txt":"具有下列情形之一的外国人，应当羁押在拘留所或者遣返场所： （一）被拘留审查的； （二）被决定遣送出境或者驱逐出境但因天气、交通运输工具班期、当事人健康状况等客观原因或者国籍、身份不明，不能立即执行的。"},{"i":249,"n":"第二百四十九条","txt":"外国人对继续盘问、拘留审查、限制活动范围、遣送出境措施不服的，可以依法申请行政复议，该行政复议决定为最终决定。 其他境外人员对遣送出境措施不服，申请行政复议的，适用前款规定。"},{"i":250,"n":"第二百五十条","txt":"外国人具有下列情形之一的，经县级以上公安机关或者出入境边防检查机关决定，可以限期出境： （一）违反治安管理的； （二）从事与停留居留事由不相符的活动的； （三）违反中国法律、法规规定，不适宜在中国境内继续停留居留的。 对外国人决定限期出境的，应当规定外国人离境的期限，注销其有效签证或者停留居留证件。限期出境的期限不得超过三十日。"},{"i":251,"n":"第二百五十一条","txt":"外国人违反治安管理或者出境入境管理，情节严重，尚不构成犯罪的，承办的公安机关可以层报公安部处以驱逐出境。公安部作出的驱逐出境决定为最终决定，由承办机关宣布并执行。 被驱逐出境的外国人，自被驱逐出境之日起十年内不准入境。"},{"i":252,"n":"第二百五十二条","txt":"对外国人处以罚款或者行政拘留并处限期出境或者驱逐出境的，应当于罚款或者行政拘留执行完毕后执行限期出境或者驱逐出境。"},{"i":253,"n":"第二百五十三条","txt":"办理涉外行政案件，应当按照国家有关办理涉外案件的规定，严格执行请示报告、内部通报、对外通知等各项制度。"},{"i":254,"n":"第二百五十四条","txt":"对外国人作出行政拘留、拘留审查或者其他限制人身自由以及限制活动范围的决定后，决定机关应当在四十八小时内将外国人的姓名、性别、入境时间、护照或者其他身份证件号码，案件发生的时间、地点及有关情况，违法的主要事实，已采取的措施及其法律依据等情况报告省级公安机关；省级公安机关应当在规定期限内，将有关情况通知该外国人所属国家的驻华使馆、领馆，并通报同级人民政府外事部门。当事人要求不通知使馆、领馆，且我国与当事人国籍国未签署双边协议规定必须通知的，可以不通知，但应当由其本人提出书面请求。"},{"i":255,"n":"第二百五十五条","txt":"外国人在被行政拘留、拘留审查或者其他限制人身自由以及限制活动范围期间死亡的，有关省级公安机关应当通知该外国人所属国家驻华使馆、领馆，同时报告公安部并通报同级人民政府外事部门。"},{"i":256,"n":"第二百五十六条","txt":"外国人在被行政拘留、拘留审查或者其他限制人身自由以及限制活动范围期间，其所属国家驻华外交、领事官员要求探视的，决定机关应当及时安排。该外国人拒绝其所属国家驻华外交、领事官员探视的，公安机关可以不予安排，但应当由其本人出具书面声明。"},{"i":257,"n":"第二百五十七条","txt":"办理涉外行政案件，本章未作规定的，适用其他各章的有关规定。"},{"i":258,"n":"第二百五十八条","txt":"行政案件具有下列情形之一的，应当予以结案： （一）作出不予行政处罚决定的； （二）按照本规定第十章的规定达成调解、和解协议并已履行的； （三）作出行政处罚等处理决定，且已执行的； （四）违法行为涉嫌构成犯罪，转为刑事案件办理的； （五）作出处理决定后，因执行对象灭失、死亡等客观原因导致无法执行或者无需执行的。"},{"i":259,"n":"第二百五十九条","txt":"经过调查，发现行政案件具有下列情形之一的，经公安派出所、县级公安机关办案部门或者出入境边防检查机关以上负责人批准，终止调查： （一）没有违法事实的； （二）违法行为已过追究时效的； （三）违法嫌疑人死亡的； （四）其他需要终止调查的情形。 终止调查时，违法嫌疑人已被采取行政强制措施的，应当立即解除。"},{"i":260,"n":"第二百六十条","txt":"对在办理行政案件过程中形成的文书材料，应当按照一案一卷原则建立案卷，并按照有关规定在结案或者终止案件调查后将案卷移交档案部门保管或者自行保管。"},{"i":261,"n":"第二百六十一条","txt":"行政案件的案卷应当包括下列内容： （一）受案登记表或者其他发现案件的记录； （二）证据材料； （三）决定文书； （四）在办理案件中形成的其他法律文书。"},{"i":262,"n":"第二百六十二条","txt":"行政案件的法律文书及定性依据材料应当齐全完整，不得损毁、伪造。"},{"i":263,"n":"第二百六十三条","txt":"省级公安机关应当建立并不断完善统一的执法办案信息系统。 办案部门应当按照有关规定将行政案件的受理、调查取证、采取强制措施、处理等情况以及相关文书材料录入执法办案信息系统，并进行网上审核审批。 公安机关可以使用电子签名、电子指纹捺印技术制作电子笔录等材料，可以使用电子印章制作法律文书。对案件当事人进行电子签名、电子指纹捺印的过程，公安机关应当同步录音录像。"},{"i":264,"n":"第二百六十四条","txt":"执行本规定所需要的法律文书式样，由公安部制定。公安部没有制定式样，执法工作中需要的其他法律文书，省级公安机关可以制定式样。"},{"i":265,"n":"第二百六十五条","txt":"本规定所称“以上”、“以下”、“内”皆包括本数或者本级。"},{"i":266,"n":"第二百六十六条","txt":"本规定自2013年1月1日起施行，依照《中华人民共和国出境入境管理法》新设定的制度自2013年7月1日起施行。2006年8月24日发布的《公安机关办理行政案件程序规定》同时废止。 公安部其他规章对办理行政案件程序有特别规定的，按照特别规定办理；没有特别规定的，按照本规定办理。"}],"gonganjiguanfanyouzuzhifanzuigongzuoguiding":[{"i":1,"n":"第一条","txt":"为了保障《中华人民共和国反有组织犯罪法》的贯彻实施，保证公安机关依法、规范、高效开展反有组织犯罪工作，保护公民和组织的合法权益，根据有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关反有组织犯罪的职责任务，是收集、研判有组织犯罪相关信息，核查有组织犯罪线索，侦查有组织犯罪案件，实施《中华人民共和国反有组织犯罪法》规定的相关行政处罚，在职权范围内落实有组织犯罪预防和治理工作。"},{"i":3,"n":"第三条","txt":"公安机关开展反有组织犯罪工作，应当坚持专门工作与群众路线相结合，坚持专项治理与系统治理相结合，坚持与反腐败相结合，坚持与加强基层组织建设相结合，惩防并举、标本兼治。"},{"i":4,"n":"第四条","txt":"公安机关开展反有组织犯罪工作，应当符合法律、行政法规和本规章的规定，做到严格规范执法，尊重保障人权。"},{"i":5,"n":"第五条","txt":"公安机关应当不断加强反有组织犯罪工作的专业化、规范化、信息化建设，促进反有组织犯罪各项工作的科学、精准、高效开展。"},{"i":6,"n":"第六条","txt":"公安机关应当发挥职能作用，加强与相关部门信息共享、工作联动，充分调动各种资源，促进对有组织犯罪的源头治理。 各地公安机关、各警种部门之间应当加强协作、配合，依法履行反有组织犯罪各项工作职责。"},{"i":7,"n":"第七条","txt":"公安机关应当建立科学的反有组织犯罪工作考评机制，全面考察基础工作、力量建设、预防治理、查处违法犯罪等各方面情况，综合评价反有组织犯罪工作质效。"},{"i":8,"n":"第八条","txt":"公安机关应当结合公安工作职责，通过普法宣传、以案释法等方式，积极开展反有组织犯罪宣传教育，增强公民的反有组织犯罪意识和能力。"},{"i":9,"n":"第九条","txt":"公安机关应当积极配合教育行政部门、学校建立防范有组织犯罪侵害校园工作机制，加强反有组织犯罪宣传教育，增强学生对有组织犯罪的识别能力和防范意识，教育引导学生自觉抵制有组织犯罪，防范有组织犯罪的侵害。"},{"i":10,"n":"第十条","txt":"公安机关发现互联网上含有宣扬、诱导有组织犯罪内容的信息，应当及时责令电信业务经营者、互联网服务提供者停止传输、采取消除等处置措施，或者下架相关应用、关闭相关网站、关停相关服务，并保存相关记录，协助调查。"},{"i":11,"n":"第十一条","txt":"公安机关应当建立有组织犯罪监测评估体系，根据辖区内警情、线索、案件及社会评价等情况，定期对本辖区有组织犯罪态势进行评估，并将评估结果报送上级公安机关。"},{"i":12,"n":"第十二条","txt":"公安机关应当配合民政等有关部门，对村民委员会、居民委员会成员候选人资格依法进行审查，并及时处理有关有组织犯罪线索。"},{"i":13,"n":"第十三条","txt":"公安机关应当配合市场监管、金融监管、自然资源、交通运输等行业主管部门，建立健全行业有组织犯罪预防和治理长效机制。"},{"i":14,"n":"第十四条","txt":"公安机关在办理案件中发现相关行业主管部门有组织犯罪预防和治理工作存在问题，需要书面提出意见建议的，可以向相关行业主管部门发送公安提示函。 发函机关认为有必要的，可以抄送同级人民政府、人大、监察机关，或者被提示单位的上级机关。"},{"i":15,"n":"第十五条","txt":"制发公安提示函，应当立足公安职能，结合侦查工作，坚持准确及时、必要审慎、注重实效的原则。"},{"i":16,"n":"第十六条","txt":"公安机关可以直接向同级行业主管部门发送公安提示函。 需要向下级行业主管部门发送的，可以直接制发，也可以指令对应的下级公安机关制发。 需要向上级行业主管部门发送的，应当层报与其同级的公安机关转发，上级公安机关认为有必要的，也可以直接制发。 发现异地的行业主管部门有组织犯罪预防和治理工作存在问题的，应当书面通报其所在地同级公安机关处理。"},{"i":17,"n":"第十七条","txt":"公安提示函应当写明具体问题、发现途径、理由和依据、意见和建议、反馈要求等。"},{"i":18,"n":"第十八条","txt":"公安机关根据有组织犯罪态势评估结果、公安提示函反馈情况等，可以会同有关部门确定预防和治理的重点区域、行业领域或者场所。"},{"i":19,"n":"第十九条","txt":"对有组织犯罪预防和治理的重点区域、行业领域或者场所，当地公安机关应当根据职权加强治安行政管理、会同或者配合有关部门加大监督检查力度、开展专项整治。"},{"i":20,"n":"第二十条","txt":"对因组织、领导黑社会性质组织被判处刑罚的人员，其户籍地设区的市级公安机关可以决定其自刑罚执行完毕之日起向公安机关报告个人财产及日常活动，并制作责令报告个人财产及日常活动决定书。 前款规定的户籍地公安机关认为由原办案地公安机关作出决定更为适宜的，可以商请由其决定。协商不成的，由共同的上级公安机关指定。 认为无需报告的，应当报上一级公安机关同意；无需报告的情况发生变化，有报告必要的，依照本规定作出责令报告个人财产及日常活动决定。"},{"i":21,"n":"第二十一条","txt":"责令报告个人财产及日常活动决定书应当载明报告期限、首次报告时间、后续报告间隔期间，报告内容、方式，接受报告的公安机关及地址、联系方式，以及不如实报告的法律责任等。 首次报告时间不迟于刑罚执行完毕后一个月，两次报告间隔期间为二至六个月。 责令报告个人财产及日常活动决定书应当在其刑罚执行完毕之日前三个月内作出并送达和宣告，可以委托刑罚执行机关代为送达和宣告。 依据本规定第二十条第三款作出责令报告个人财产及日常活动决定的，不受第二款首次报告期限和前款期限限制。"},{"i":22,"n":"第二十二条","txt":"作出决定的公安机关负责接受个人财产及日常活动报告。必要时，也可以指定下一级公安机关接受报告。 报告期间，经报告义务人申请，接受报告的公安机关认为确有必要的，报决定机关批准，可以变更接受报告的公安机关。跨决定机关管辖区域变更的，层报共同的上级公安机关决定。 接受报告的公安机关变更的，应当做好工作交接。"},{"i":23,"n":"第二十三条","txt":"报告义务人应当按照责令报告个人财产及日常活动决定书的要求，到公安机关报告个人财产及日常活动情况。 在报告间隔期间，报告义务人的个人财产及日常活动情况可能出现较大变动或者存在重大错报、漏报等情况的，接受报告的公安机关可以通知报告义务人书面或者口头补充报告有关情况。 报告义务人住址、工作单位、通讯方式、出入境证件、重大财产发生变动的，应当在变动后的二十四小时内向公安机关报告。"},{"i":24,"n":"第二十四条","txt":"公安机关可以要求报告义务人报告下列个人财产及日常活动情况： （一）住址、工作单位、通讯方式； （二）动产、不动产、现金、存款、财产性权利等财产状况； （三）经商办企业，从事职业及薪酬，投资收益、经营收益等非职业性经济收入，大额支出等财产变动情况； （四）日常主要社会交往、婚姻状况，接触特定人员和出入特定场所情况，出境入境情况等； （五）受到行政、刑事调查及处罚的情况，涉及民事诉讼情况。 报告义务人对前款第二、三、五项规定的报告情况，应当提供证明材料。"},{"i":25,"n":"第二十五条","txt":"个人财产及日常活动报告期限不超过五年，期限届满或者报告义务人在报告期内死亡的，报告义务自动解除。"},{"i":26,"n":"第二十六条","txt":"公安机关在工作中发现境外的黑社会组织的人员可能入境渗透、发展、实施违法犯罪活动的，根据工作需要，可以通知移民管理、海关、海警等部门并提出处置建议。 移民管理、海关、海警等部门发现境外的黑社会组织的人员入境并通知公安机关的，公安机关应当及时依法处理。"},{"i":27,"n":"第二十七条","txt":"公安机关应当依法运用现代信息技术，建立有组织犯罪线索收集和研判机制，分级分类进行处置。 公安机关对有组织犯罪线索应当及时开展统计、分析、研判工作，依法组织核查；对不属于公安机关职责范围的事项，移送有关主管机关依法处理。"},{"i":28,"n":"第二十八条","txt":"有组织犯罪线索由县级公安机关负责核查，上级公安机关认为必要时可以提级核查或者指定其他公安机关核查。 上级公安机关应当加强对线索核查工作的监督指导，必要时可以组织抽查、复核。"},{"i":29,"n":"第二十九条","txt":"对有组织犯罪线索，经县级以上公安机关负责人批准后启动核查。 核查有组织犯罪线索，可以依照有关法律和规定采取询问、查询、勘验、检查、鉴定和调取证据材料等不限制被调查对象人身、财产权利的调查措施。 采取前款规定的调查措施，依照《公安机关办理刑事案件程序规定》的有关规定进行审批，制作法律文书。 公安机关向有关单位和个人收集、调取相关信息和材料时，应当告知其必须如实提供。"},{"i":30,"n":"第三十条","txt":"公安机关核查黑社会性质组织犯罪线索，发现涉案财产有灭失、转移的紧急风险的，经设区的市级以上公安机关负责人批准后，可以对有关涉案财产采取紧急止付或者临时冻结、临时扣押的紧急措施，期限不得超过四十八小时。 期限届满或者适用紧急措施的情形消失的，应当立即解除紧急措施；符合立案条件的，办案部门应当在紧急措施期限届满前依法立案侦查，并办理冻结、扣押手续。"},{"i":31,"n":"第三十一条","txt":"有组织犯罪线索核查结论，应当经核查的公安机关负责人批准后作出。有明确举报人、报案人或者控告人的，除无法告知或者可能影响后续侦查工作的以外，应当告知核查结论。 对有控告人的有组织犯罪线索，决定对所控告的事实不予立案的，公安机关应当在核查结论作出后制作不予立案通知书，在三日以内送达控告人。"},{"i":32,"n":"第三十二条","txt":"公安机关核查有组织犯罪线索，发现犯罪事实或者犯罪嫌疑人的，应当依照《中华人民共和国刑事诉讼法》的规定立案侦查。"},{"i":33,"n":"第三十三条","txt":"公安机关办理有组织犯罪案件，应当以事实为根据，以法律为准绳，依法全面收集证据，综合审查判断，准确认定有组织犯罪。"},{"i":34,"n":"第三十四条","txt":"对有组织犯罪的组织者、领导者和骨干成员取保候审的，由办案的公安机关主要负责人组织集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"为谋取非法利益或者形成非法影响，有组织地进行滋扰、纠缠、哄闹、聚众造势等，对他人形成心理强制，足以限制人身自由、危及人身财产安全，影响正常社会秩序、经济秩序的，可以认定为有组织犯罪的犯罪手段。"},{"i":36,"n":"第三十六条","txt":"对于利用信息网络实施的犯罪案件，符合有组织犯罪特征和认定标准的，应当按照有组织犯罪案件侦查、移送起诉。"},{"i":37,"n":"第三十七条","txt":"根据有组织犯罪案件侦查需要，公安机关可以商请人民检察院派员参加案件会商，听取其关于案件定性、证据收集、法律适用等方面的意见。"},{"i":38,"n":"第三十八条","txt":"公安机关办理有组织犯罪案件，可以依照《中华人民共和国出境入境管理法》的规定，决定对犯罪嫌疑人采取限制出境措施，按规定通知移民管理机构执行；对于不需要继续采取限制出境措施的，应当及时解除。"},{"i":39,"n":"第三十九条","txt":"根据办理案件及维护监管秩序的需要，可以对有组织犯罪案件的犯罪嫌疑人、被告人采取异地羁押、分别羁押或者单独羁押等措施。采取异地羁押措施的，应当依法通知犯罪嫌疑人、被告人的家属和辩护人。"},{"i":40,"n":"第四十条","txt":"公安机关在立案后，根据侦查犯罪的需要，依照《中华人民共和国刑事诉讼法》的规定，可以采取技术侦查措施、实施控制下交付或者由有关人员隐匿身份进行侦查。 公安机关实施控制下交付或者由有关人员隐匿身份进行侦查的，应当进行风险评估，制定预案，经县级以上公安机关负责人批准后实施。 采取技术侦查、控制下交付、隐匿身份侦查措施收集的与案件有关的材料，可以作为刑事诉讼证据使用。如果使用该证据可能危及有关人员的人身安全，或者可能产生其他严重后果的，应当采取不暴露有关人员身份和使用的技术设备、侦查方法等保护措施。无法采取保护措施或者采取保护措施不足以防止产生严重后果的，可以建议由审判人员在庭外对证据进行核实。"},{"i":41,"n":"第四十一条","txt":"公安机关侦查有组织犯罪案件，应当依法履行认罪认罚从宽告知、教育义务，敦促犯罪嫌疑人如实供述自己的罪行。 犯罪嫌疑人认罪认罚的，应当在起诉意见书中写明自愿认罪认罚的情况和从宽处理意见，并随案移送相关证据材料。"},{"i":42,"n":"第四十二条","txt":"公安机关对于罪行较轻、自愿认罪认罚、采用非羁押性强制措施足以防止发生《中华人民共和国刑事诉讼法》第八十一条第一款规定的社会危险性的犯罪嫌疑人，依法可不适用羁押性强制措施；已经被羁押的，可以依法变更强制措施。"},{"i":43,"n":"第四十三条","txt":"犯罪嫌疑人检举、揭发重大犯罪的其他共同犯罪人或者提供侦破重大案件的重要线索或者证据，同案处理可能导致其本人或者近亲属有人身危险，经县级以上公安机关负责人批准，可以分案处理。 公安机关决定分案处理的，应当就案件管辖等问题书面征求人民法院、人民检察院意见并达成一致，防止分案处理出现证据灭失、证据链脱节或者影响有组织犯罪认定等情况。"},{"i":44,"n":"第四十四条","txt":"犯罪嫌疑人、被告人有《中华人民共和国反有组织犯罪法》第三十三条第一款所列情形之一的，经县级以上公安机关主要负责人批准，公安机关可以向人民检察院提出从宽处理的意见，并说明理由。 对有组织犯罪的组织者、领导者，应当严格适用。"},{"i":45,"n":"第四十五条","txt":"公安机关根据办理有组织犯罪案件的需要，可以全面调查涉嫌有组织犯罪的组织及其成员财产的来源、性质、用途、权属及价值，依法采取查询、查封、扣押、冻结等措施。 全面调查的范围包括：有组织犯罪组织的财产；组织成员个人所有的财产；组织成员实际控制的财产；组织成员出资购买的财产；组织成员转移至他人名下的财产；组织成员涉嫌洗钱及掩饰、隐瞒犯罪所得、犯罪所得孳息、收益等犯罪涉及的财产；其他与有组织犯罪组织及其成员有关的财产。"},{"i":46,"n":"第四十六条","txt":"公安机关根据反有组织犯罪工作需要，可以向反洗钱行政主管部门查询与有组织犯罪相关的信息数据、提请协查与有组织犯罪相关的可疑交易活动。"},{"i":47,"n":"第四十七条","txt":"对下列财产，经县级以上公安机关主要负责人批准，可以依法先行处置，所得价款由扣押、冻结机关保管，并及时告知犯罪嫌疑人、被告人或者其近亲属： （一）易损毁、灭失、变质等不宜长期保存的物品； （二）有效期即将届满的汇票、本票、支票等； （三）债券、股票、基金份额等财产，经权利人申请，出售不损害国家利益、被害人利益，不影响诉讼正常进行的。"},{"i":48,"n":"第四十八条","txt":"有组织犯罪组织及其成员依法应当被追缴、没收的涉案财产无法找到、灭失或者与其他合法财产混合且不可分割的，公安机关应当积极调查、收集有关证据，并在起诉意见书中说明。"},{"i":49,"n":"第四十九条","txt":"有证据证明犯罪嫌疑人在犯罪期间获得的财产高度可能属于黑社会性质组织犯罪的违法所得及其孳息、收益，公安机关应当要求犯罪嫌疑人说明财产来源并予以查证，对犯罪嫌疑人不能说明合法来源的，应当随案移送审查起诉，并对高度可能性作出说明。"},{"i":50,"n":"第五十条","txt":"有组织犯罪案件移送审查起诉时，公安机关应当对涉案财产提出书面处理意见及理由、依据。 黑社会性质组织犯罪案件，一般应当对涉案财产材料单独立卷。"},{"i":51,"n":"第五十一条","txt":"黑社会性质组织犯罪案件的犯罪嫌疑人逃匿，在通缉一年后不能到案，或者犯罪嫌疑人死亡，依照《中华人民共和国刑法》规定应当追缴其违法所得及其他涉案财产的，依照《中华人民共和国刑事诉讼法》及《公安机关办理刑事案件程序规定》有关犯罪嫌疑人逃匿、死亡案件违法所得的没收程序的规定办理。"},{"i":52,"n":"第五十二条","txt":"对于不宜查封、扣押、冻结的经营性财产，经县级以上公安机关主要负责人批准，可以申请当地政府指定有关部门或者委托有关机构代管或者托管。 不宜查封、扣押、冻结情形消失的，公安机关可以依法对相关财产采取查封、扣押、冻结措施。"},{"i":53,"n":"第五十三条","txt":"利害关系人对查封、扣押、冻结、处置涉案财物提出异议的，公安机关应当及时予以核实，听取其意见，依法作出处理，并书面告知利害关系人。经查明确实与案件无关的财物，应当在三日以内解除相关措施，并予以退还。 公安机关对涉案财物作出处理后，利害关系人对处理不服的，可以提出申诉或者控告。受理申诉或者控告的公安机关应当及时进行调查核实，在收到申诉、控告之日起三十日以内作出处理决定并书面回复。"},{"i":54,"n":"第五十四条","txt":"公安机关在反有组织犯罪工作中，发现国家工作人员涉嫌《中华人民共和国反有组织犯罪法》第五十条第一款所列情形之一的，应当按照职权进行初步核查。 经核查，属于公安机关管辖的，应当全面调查，依法作出处理；不属于公安机关管辖的，应当及时移送主管机关。"},{"i":55,"n":"第五十五条","txt":"依法从事反有组织犯罪工作的民警，不得有下列行为： （一）接到报案、控告、举报不受理，发现犯罪信息、线索隐瞒不报、不如实报告，或者未经批准、授权擅自处置、不移送犯罪线索、涉案材料； （二）向违法犯罪人员通风报信，阻碍案件查处； （三）违反规定泄露国家秘密、商业秘密和个人隐私； （四）违背事实和法律处理案件； （五）违反规定查封、扣押、冻结、处置涉案财物； （六）其他滥用职权、玩忽职守、徇私舞弊的行为。 违反上述规定构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依规依纪依法给予处分。"},{"i":56,"n":"第五十六条","txt":"公安机关应当与监察机关、人民法院、人民检察院、司法行政机关加强协作配合，建立线索办理沟通机制。 对于重大疑难复杂的国家工作人员涉有组织犯罪案件，公安机关可以商监察机关、人民检察院同步立案、同步查处，根据案件办理需要，依法移送相关证据、共享有关信息，确保全面查清案件事实。"},{"i":57,"n":"第五十七条","txt":"公安机关接到对从事反有组织犯罪工作民警的举报后，应当审慎对待，依规依纪依法处理，防止犯罪嫌疑人、被告人等利用举报干扰办案、打击报复。 对利用举报等方式歪曲捏造事实、诬告陷害从事反有组织犯罪工作民警的，应当依规依纪依法追究责任；造成不良影响的，应当按照规定及时澄清事实，恢复民警名誉，消除不良影响。"},{"i":58,"n":"第五十八条","txt":"公安部根据中华人民共和国缔结或者参加的国际条约，或者按照平等互惠原则，开展与其他国家、地区、国际组织的反有组织犯罪合作。"},{"i":59,"n":"第五十九条","txt":"公安部根据国务院授权，代表中国政府与外国政府和有关国际组织开展反有组织犯罪情报信息交流和执法合作。 公安部依照有关法律规定，通过推动缔结条约、协定和签订警务合作文件等形式，加强跨境反有组织犯罪警务合作，推动与有关国家、地区、国际组织建立警务合作机制。 经公安部批准，边境地区公安机关可以与相邻国家或者地区执法机构建立跨境有组织犯罪情报信息交流和警务合作机制。"},{"i":60,"n":"第六十条","txt":"通过跨境反有组织犯罪刑事司法协助和警务合作取得的材料可以在行政处罚、刑事诉讼中作为证据使用，但依据条约规定或者我方承诺不作为证据使用的除外。"},{"i":61,"n":"第六十一条","txt":"公安机关开展跨境反有组织犯罪国际合作其他事宜及具体程序，依照有关法律和《公安机关办理刑事案件程序规定》等有关规定办理。"},{"i":62,"n":"第六十二条","txt":"公安机关应当为反有组织犯罪工作提供必要的组织保障、制度保障和物质保障。"},{"i":63,"n":"第六十三条","txt":"公安机关应当建立健全反有组织犯罪专业力量，加强骨干人才培养使用，设立常态化反有组织犯罪专门队伍和情报线索处置平台，确保各级公安机关具备数量充足、配备精良、业务过硬的专门队伍开展反有组织犯罪工作。"},{"i":64,"n":"第六十四条","txt":"公安机关应当加强反有组织犯罪专家人才队伍建设，建立健全选拔、培养、使用机制。 公安机关应当将反有组织犯罪专业训练工作纳入年度教育训练计划。"},{"i":65,"n":"第六十五条","txt":"各级公安机关应当将反有组织犯罪工作经费列入本单位年度预算予以保障。"},{"i":66,"n":"第六十六条","txt":"因举报、控告和制止有组织犯罪活动，在有组织犯罪案件中作证，本人或者其近亲属的人身安全面临危险的，公安机关应当按照有关规定，采取下列一项或者多项保护措施： （一）不公开真实姓名、住址和工作单位等个人信息； （二）禁止特定的人接触被保护人员； （三）对人身和住宅采取专门性保护措施； （四）变更被保护人员的身份，重新安排住所和工作单位； （五）其他必要的保护措施。 采取前款第四项规定的保护措施的，由公安部批准和组织实施。 案件移送审查起诉时，应当将采取保护措施的相关情况一并移交人民检察院。"},{"i":67,"n":"第六十七条","txt":"公安机关发现证人因作证，本人或者其近亲属的人身安全面临危险，或者证人向公安机关请求予以保护，公安机关经评估认为确有必要采取保护措施的，应当制作呈请证人保护报告书，报县级以上公安机关负责人批准实施。 人民法院、人民检察院决定对证人采取第六十六条第一款第二、三项保护措施的，由县级以上公安机关凭人民法院、人民检察院的决定文书执行，并将执行保护的情况及时通知决定机关。必要时，可以请人民法院、人民检察院协助执行。"},{"i":68,"n":"第六十八条","txt":"实施有组织犯罪的人员配合侦查、起诉、审判等工作，有《中华人民共和国反有组织犯罪法》第三十三条第一款所列情形之一，对侦破案件或者查明案件事实起到重要作用的，或者有其他重大立功表现的，可以参照证人保护的规定执行。"},{"i":69,"n":"第六十九条","txt":"对办理有组织犯罪案件的人民警察及其近亲属，可以采取人身保护、禁止特定的人接触等保护措施。"},{"i":70,"n":"第七十条","txt":"公安机关实施证人保护的其他事项，适用《公安机关办理刑事案件证人保护工作规定》。 各级公安机关可以结合本地实际，组建专门的证人保护力量、设置证人保护安全场所。"},{"i":71,"n":"第七十一条","txt":"公安机关开展反有组织犯罪工作，对有关组织和个人违反《中华人民共和国反有组织犯罪法》的行为，依法追究其相应的法律责任。"},{"i":72,"n":"第七十二条","txt":"实施《中华人民共和国反有组织犯罪法》第六十九条所列行为的，依照《公安机关办理行政案件程序规定》确定案件管辖。 实施《中华人民共和国反有组织犯罪法》第六十九条第一款第一项行为的，也可以由抓获地公安机关管辖。 相关违法行为系在侦查有组织犯罪过程中发现的，也可以由负责侦查有组织犯罪的公安机关管辖。"},{"i":73,"n":"第七十三条","txt":"《中华人民共和国反有组织犯罪法》第七十条规定的行政处罚，由接受报告的公安机关管辖。"},{"i":74,"n":"第七十四条","txt":"《中华人民共和国反有组织犯罪法》第七十一条规定的行政处罚，由金融机构等相关单位所在地公安机关管辖，也可以由负责侦查有组织犯罪的公安机关管辖。"},{"i":75,"n":"第七十五条","txt":"公安机关调查有组织犯罪，要求有关国家机关、行业主管部门予以配合相关工作或者提供相关证据，有关国家机关、行业主管部门没有正当理由不予配合的，层报相应的上级公安机关书面通报其上级机关。"},{"i":76,"n":"第七十六条","txt":"本规定自2022年10月1日起施行。"}],"gonganjiguanshishibaoanfuwuguanlitiaolibanfa":[{"i":1,"n":"第一条","txt":"为了规范公安机关对保安服务的监督管理工作，根据《保安服务管理条例》（以下简称《条例》）和有关法律、行政法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公安部负责全国保安服务活动的监督管理工作。地方各级公安机关应当按照属地管理、分级负责的原则，对保安服务活动依法进行监督管理。"},{"i":3,"n":"第三条","txt":"省级公安机关负责下列保安服务监督管理工作： （一）指导本省（自治区）公安机关对保安从业单位、保安培训单位、保安员和保安服务活动进行监督管理； （二）核发、吊销保安服务公司的保安服务许可证、保安培训单位的保安培训许可证； （三）审核保安服务公司法定代表人的变更情况； （四）接受承担保安员枪支使用培训工作的人民警察院校、人民警察培训机构的备案； （五）依法进行其他保安服务监督管理工作。 直辖市公安机关除行使省级公安机关的保安服务监督管理职能外，还可以直接受理设立保安服务公司或者保安培训单位的申请，核发保安员证，接受保安服务公司跨省、自治区、直辖市提供保安服务的备案。"},{"i":4,"n":"第四条","txt":"设区市的公安机关负责下列保安服务监督管理工作： （一）受理、审核设立保安服务公司、保安培训单位的申请材料； （二）接受保安服务公司设立分公司和跨省、自治区、直辖市开展保安服务活动，以及自行招用保安员单位的备案； （三）组织开展保安员考试，核发、吊销保安员证； （四）对保安服务活动进行监督检查； （五）依法进行其他保安服务监督管理工作。"},{"i":5,"n":"第五条","txt":"县级公安机关负责下列保安服务监督管理工作： （一）对保安服务活动进行监督检查； （二）协助进行自行招用保安员单位备案管理工作； （三）受理保安员考试报名、采集保安员指纹； （四）依法进行其他保安服务监督管理工作。 公安派出所负责对自行招用保安员单位保安服务活动的日常监督检查。"},{"i":6,"n":"第六条","txt":"各级公安机关应当明确保安服务主管机构，归口负责保安服务监督管理工作。 铁路、交通、民航公安机关和森林公安机关负责对其管辖范围内的保安服务进行日常监督检查。 新疆生产建设兵团公安机关负责对其管辖范围内的保安服务进行监督管理。"},{"i":7,"n":"第七条","txt":"保安服务行业协会在公安机关指导下依法开展提供服务、规范行为、反映诉求等保安服务行业自律工作。 全国性保安服务行业协会在公安部指导下开展推荐保安员服装式样、设计全国统一的保安服务标志、制定保安服务标准、开展保安服务企业资质认证以及协助组织保安员考试等工作。"},{"i":8,"n":"第八条","txt":"公安机关对在保护公共财产和人民群众生命财产安全、预防和制止违法犯罪活动中有突出贡献的保安从业单位和保安员，应当按照国家有关规定给予表彰奖励。 保安员因工伤亡的，依照国家有关工伤保险的规定享受工伤保险待遇，公安机关应当协助落实工伤保险待遇；保安员因公牺牲的，公安机关应当按照国家有关规定，做好烈士推荐工作。"},{"i":9,"n":"第九条","txt":"申请设立保安服务公司，应当向设区市的公安机关提交下列材料： （一）设立申请书（应当载明拟设立保安服务公司的名称、住所、注册资本、股东及出资额、经营范围等内容）； （二）拟任的保安服务公司法定代表人和总经理、副总经理等主要管理人员的有效身份证件、简历，保安师资格证书复印件， 5年以上军队、公安、安全、审判、检察、司法行政或者治安保卫、保安经营管理工作经验证明，县级公安机关开具的无被刑事处罚、劳动教养、收容教育、强制隔离戒毒证明； （三）拟设保安服务公司住所的所有权或者使用权的有效证明文件和提供保安服务所需的有关设备、交通工具等材料； （四）专业技术人员名单和法律、行政法规有资格要求的资格证明； （五）组织机构和保安服务管理制度、岗位责任制度、保安员管理制度材料； （六）工商行政管理部门核发的企业名称预先核准通知书。"},{"i":10,"n":"第十条","txt":"申请设立提供武装守护押运服务的保安服务公司，除向设区市的公安机关提交本办法第九条规定的材料外，还应当提交下列材料： （一）出资属国有独资或者国有资本占注册资本总额51%以上的有效证明文件； （二）符合《专职守护押运人员枪支使用管理条例》规定条件的守护押运人员的材料； （三）符合国家或者行业标准的专用运输车辆以及通信、报警设备的材料； （四）枪支安全管理制度和保管设施情况的材料。 保安服务公司申请增设武装守护押运业务的，无需提交本办法第九条规定的材料。"},{"i":11,"n":"第十一条","txt":"申请设立中外合资经营、中外合作经营或者外资独资经营的保安服务公司（以下统称外资保安服务公司），除了向公安机关提交本办法第九条、第十条规定的材料外，还应当提交下列材料： （一）中外合资、中外合作合同； （二）外方的资信证明和注册登记文件； （三）拟任的保安服务公司法定代表人和总经理、副总经理等主要管理人员为外国人的，须提供在所属国家或者地区无被刑事处罚记录证明（原居住地警察机构出具并经公证机关公证）、5年以上保安经营管理工作经验证明、在华取得的保安师资格证书复印件。 本办法施行前已经设立的保安服务公司重新申请保安服务许可证，拟任的法定代表人和总经理、副总经理等主要管理人员为外国人的，除需提交前款第三项规定的材料外，还应当提交外国人就业证复印件。"},{"i":12,"n":"第十二条","txt":"省级公安机关应当按照严格控制、防止垄断、适度竞争、确保安全的原则，提出武装守护押运服务公司的规划、布局方案，报公安部批准。"},{"i":13,"n":"第十三条","txt":"设区市的公安机关应当自收到设立保安服务公司申请材料之日起15个工作日内，对申请人提交的材料的真实性进行审核，确认是否属实，并将审核意见报所在地省级公安机关。对设立提供武装守护押运和安全技术防范报警监控运营服务的申请，应当对经营场所、设施建设等情况进行现场考察。 省级公安机关收到设立保安服务公司的申请材料和设区市的公安机关的审核意见后，应当在15个工作日内作出决定： （一）符合《条例》第八条、第十条和本办法第十二条规定的，决定核发保安服务许可证，或者在已有的保安服务许可证上增注武装守护押运服务； （二）不符合《条例》第八条、第十条和本办法第十二条规定的，应当作出不予许可的决定，书面通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"取得保安服务许可证的申请人应当在办理工商登记后30个工作日内将工商营业执照复印件报送核发保安服务许可证的省级公安机关。 取得保安服务许可证后超过6个月未办理工商登记的，保安服务许可证失效，发证公安机关应当收回保安服务许可证。"},{"i":15,"n":"第十五条","txt":"保安服务公司设立分公司的，应当自分公司设立之日起15个工作日内，向分公司所在地设区市的公安机关备案，并接受备案地公安机关监督管理。备案应当提交下列材料： （一）保安服务许可证、工商营业执照复印件； （二）保安服务公司法定代表人、分公司负责人和保安员基本情况； （三）拟开展的保安服务项目。"},{"i":16,"n":"第十六条","txt":"保安服务公司拟变更法定代表人的，应当向所在地设区市的公安机关提出申请。设区市的公安机关应当在收到申请后15个工作日内进行审核并报所在地省级公安机关。省级公安机关应当在收到申报材料后15个工作日内审核并予以回复。"},{"i":17,"n":"第十七条","txt":"省级公安机关许可设立提供武装守护押运服务的保安服务公司以及中外合资、中外合作或者外商独资经营的保安服务公司的，应当报公安部备案。"},{"i":18,"n":"第十八条","txt":"自行招用保安员从事本单位安全防范工作的机关、团体、企业、事业单位以及在物业管理区域内开展秩序维护等服务的物业服务企业，应当自开始保安服务之日起30个工作日内向所在地设区市的公安机关备案。备案应当提交下列材料： （一）单位法人资格证明； （二）法定代表人（主要负责人）、保安服务分管负责人和保安员的基本情况； （三）保安服务区域的基本情况； （四）建立保安服务管理制度、岗位责任制度、保安员管理制度的情况； (五)保安员在岗培训法律、保安专业知识和技能的情况。"},{"i":19,"n":"第十九条","txt":"申领保安员证应当符合下列条件： （一）年满18周岁的中国公民； （二）身体健康，品行良好； （三）初中以上学历； （四）参加保安员考试，成绩合格； （五）没有《条例》第十七条规定的情形。"},{"i":20,"n":"第二十条","txt":"参加保安员考试，由本人或者保安从业单位、保安培训单位组织到现住地县级公安机关报名，填报报名表（可以到当地公安机关政府网站上下载），并按照国家有关规定交纳考试费。报名应当提交下列材料： （一）有效身份证件； （二）县级以上医院出具的体检证明； （三）初中以上学历证明。 县级公安机关应当在接受报名时留取考试申请人的指纹，采集数码照片，并现场告知领取准考证时间。"},{"i":21,"n":"第二十一条","txt":"县级公安机关对申请人的报名材料进行审核，符合本办法第十九条第一项、第二项、第三项、第五项规定的，上报设区市的公安机关发给准考证，通知申请人领取。"},{"i":22,"n":"第二十二条","txt":"设区市的公安机关应当根据本地报考人数和保安服务市场需要，合理规划设置考点，提前公布考试方式（机考或者卷考）和时间，每年考试不得少于2次。 考试题目从公安部保安员考试题库中随机抽取。考生凭准考证和有效身份证件参加考试。"},{"i":23,"n":"第二十三条","txt":"申请人考试成绩合格的，设区市的公安机关核发保安员证，由县级公安机关通知申请人领取。"},{"i":24,"n":"第二十四条","txt":"保安从业单位直接从事保安服务的人员应当持有保安员证。 保安从业单位应当招用持有保安员证的人员从事保安服务工作，并与被招用的保安员依法签订劳动合同。"},{"i":25,"n":"第二十五条","txt":"保安服务公司签订保安服务合同前，应当按照《条例》第二十一条的规定，对下列事项进行核查： （一）客户单位是否依法设立； （二）被保护财物是否合法； （三）被保护人员的活动是否合法； （四）要求提供保安服务的活动依法需经批准的，是否已经批准； （五）维护秩序的区域是否经业主或者所属单位明确授权； （六）其他应当核查的事项。"},{"i":26,"n":"第二十六条","txt":"保安服务公司派出保安员提供保安服务，保安服务合同履行地与保安服务公司所在地不在同一省、自治区、直辖市的，应当依照《条例》第二十三条的规定，在开始提供保安服务之前30个工作日内向保安服务合同履行地设区市的公安机关备案，并接受备案地公安机关监督管理。备案应当提交下列材料： （一）保安服务许可证和工商营业执照复印件； （二）保安服务公司法定代表人、服务项目负责人有效身份证件和保安员的基本情况； （三）跨区域经营服务的保安服务合同； （四）其他需要提供的材料。"},{"i":27,"n":"第二十七条","txt":"经设区的市级以上地方人民政府确定的关系国家安全、涉及国家秘密等治安保卫重点单位不得聘请外资保安服务公司提供保安服务。 为上述单位提供保安服务的保安服务公司不得招用境外人员。"},{"i":28,"n":"第二十八条","txt":"保安服务中使用的技术防范产品，应当符合国家或者行业质量标准。 保安服务中安装报警监控设备应当遵守国家有关安全技术规范。"},{"i":29,"n":"第二十九条","txt":"保安员上岗服务应当穿着全国性保安服务行业协会推荐式样的保安员服装，佩带全国统一的保安服务标志。 提供随身护卫、安全技术防范和安全风险评估服务的保安员上岗服务可以穿着便服，但应当佩带全国统一的保安服务标志。"},{"i":30,"n":"第三十条","txt":"保安从业单位应当根据保安服务和保安员安全需要，为保安员配备保安服务岗位所需的防护、救生等器材和交通、通讯等装备。 保安服务岗位装备配备标准由公安部另行制定。"},{"i":31,"n":"第三十一条","txt":"申请设立保安培训单位，应当向设区市的公安机关提交下列材料： （一）设立申请书（应当载明申请人基本情况、拟设立培训单位名称、培训目标、培训规模、培训内容、培训条件和内部管理制度等）； （二）符合《条例》第三十二条规定条件的证明文件； （三）申请人、法定代表人的有效身份证件，主要管理人员和师资人员的相关资格证明文件。"},{"i":32,"n":"第三十二条","txt":"公安机关应当自收到申请材料之日起15个工作日内，对申请人提交的材料的真实性进行审核，对培训所需场所、设施等教学条件进行现场考察，并将审核意见报所在地省级公安机关。 省级公安机关收到申请材料和设区市的公安机关的审核意见后，应当在15个工作日内作出决定： （一）符合《条例》第三十二条规定的，核发保安培训许可证； （二）不符合《条例》第三十二条规定的，应当作出不予许可的决定，书面通知申请人并说明理由。"},{"i":33,"n":"第三十三条","txt":"人民警察院校、人民警察培训机构对从事武装守护押运服务保安员进行枪支使用培训的，应当在开展培训工作前30个工作日内，向所在地省级公安机关备案。备案应当提交下列材料： （一）法人资格证明或者批准成立文件； （二）法定代表人、分管负责人的基本情况； （三）与培训规模相适应的师资和教学设施情况； （四）枪支安全管理制度和保管设施建设情况。"},{"i":34,"n":"第三十四条","txt":"保安培训单位应当按照公安部审定的保安员培训教学大纲进行培训。 保安培训单位不得对外提供或者变相提供保安服务。"},{"i":35,"n":"第三十五条","txt":"公安机关应当加强对保安从业单位、保安培训单位的日常监督检查，督促落实各项管理制度。"},{"i":36,"n":"第三十六条","txt":"公安机关应当根据《条例》规定，建立保安服务监督管理信息系统和保安员指纹等人体生物信息管理制度。 保安服务监督管理信息系统建设标准由公安部另行制定。"},{"i":37,"n":"第三十七条","txt":"公安机关对保安服务公司应当检查下列内容： （一）保安服务公司基本情况； （二）设立分公司和跨省、自治区、直辖市开展保安服务经营活动情况； （三）保安服务合同和监控影像资料、报警记录留存制度落实情况； （四）保安服务中涉及的安全技术防范产品、设备安装、变更、使用情况； （五）保安服务管理制度、岗位责任制度、保安员管理制度和紧急情况应急预案建立落实情况； （六）从事武装守护押运服务的保安服务公司公务用枪安全管理制度和保管设施建设情况； （七）保安员及其服装、保安服务标志与装备管理情况； （八）保安员在岗培训和权益保障工作落实情况； （九）被投诉举报事项纠正情况； （十）其他需要检查的事项。"},{"i":38,"n":"第三十八条","txt":"公安机关对自行招用保安员单位应当检查下列内容： （一）备案情况； （二）监控影像资料、报警记录留存制度落实情况； （三）保安服务中涉及的安全技术防范产品、设备安装、变更、使用情况； （四）保安服务管理制度、岗位责任制度、保安员管理制度和紧急情况应急预案建立落实情况； （五）依法配备的公务用枪安全管理制度和保管设施建设情况； （六）自行招用的保安员及其服装、保安服务标志与装备管理情况； （七）保安员在岗培训和权益保障工作落实情况； （八）被投诉举报事项纠正情况； （九）其他需要检查的事项。"},{"i":39,"n":"第三十九条","txt":"公安机关对保安培训单位应当检查下列内容： （一）保安培训单位基本情况； （二）保安培训教学情况； （三）枪支使用培训单位备案情况和枪支安全管理制度与保管设施建设管理情况； （四）其他需要检查的事项。"},{"i":40,"n":"第四十条","txt":"公安机关有关工作人员对保安从业单位和保安培训单位实施监督检查时不得少于2人，并应当出示执法身份证件。 对监督检查情况和处理意见应当如实记录，并由公安机关检查人员和被检查单位的有关负责人签字；被检查单位负责人不在场或者拒绝签字的，公安机关工作人员应当在检查记录上注明。"},{"i":41,"n":"第四十一条","txt":"公安机关在监督检查时，发现依法应当责令限期改正的违法行为，应当制作责令限期改正通知书，送达被检查单位。责令限期改正通知书中应当注明改正期限。 公安机关应当在责令改正期限届满或者收到当事人的复查申请之日起3个工作日内进行复查。对逾期不改正的，依法予以行政处罚。"},{"i":42,"n":"第四十二条","txt":"公安机关应当在办公场所和政府网站上公布下列信息： （一）保安服务监督管理有关法律、行政法规、部门规章和地方性法规、政府规章等规范性文件； （二）保安服务许可证、保安培训许可证、保安员证的申领条件和程序； （三）保安服务公司设立分公司与跨省、自治区、直辖市经营服务、自行招用保安员单位、从事武装守护押运服务保安员枪支使用培训单位的备案材料和程序； （四）保安服务监督检查工作要求和程序； （五）举报投诉方式； （六）其他应当公开的信息。"},{"i":43,"n":"第四十三条","txt":"以欺骗、贿赂等不正当手段取得保安服务或者保安培训许可，公安机关及其工作人员滥用职权、玩忽职守、违反法定程序准予保安服务或者保安培训许可，或者对不具备申请资格、不符合法定条件的申请人准予保安服务或者保安培训许可的，发证公安机关经查证属实，应当撤销行政许可。撤销保安服务、保安培训许可的，应当按照下列程序实施： （一）经省、自治区、直辖市人民政府公安机关批准，制作撤销决定书送达当事人； （二）收缴许可证书； （三）公告许可证书作废。"},{"i":44,"n":"第四十四条","txt":"保安服务公司、保安培训单位依法破产、解散、终止的，发证公安机关应当依法及时办理许可注销手续，收回许可证件。"},{"i":45,"n":"第四十五条","txt":"保安服务公司有下列情形之一，造成严重后果的，除依照《条例》第四十三条规定处罚外，发证公安机关可以依据《中华人民共和国治安管理处罚法》第五十四条第三款的规定，吊销保安服务许可证： （一）泄露在保安服务中获知的国家秘密； （二）指使、纵容保安员阻碍依法执行公务、参与追索债务、采用暴力或者以暴力相威胁的手段处置纠纷； （三）其他严重违法犯罪行为。 保安培训单位以培训为名进行诈骗等违法犯罪活动，情节严重的，公安机关可以依前款规定，吊销保安培训许可证。"},{"i":46,"n":"第四十六条","txt":"设区的市级以上人民政府确定的关系国家安全、涉及国家秘密等治安保卫重点单位违反《条例》第二十二条规定的，依照《企业事业单位内部治安保卫条例》第十九条的规定处罚。 保安服务公司违反本办法第二十七条第二款规定的，依照前款规定处罚。"},{"i":47,"n":"第四十七条","txt":"保安培训单位以实习为名，派出学员变相开展保安服务的，依照《条例》第四十一条规定，依法给予治安管理处罚，并没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"公安机关工作人员在保安服务监督管理中有下列情形的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）明知不符合设立保安服务公司、保安培训单位的设立条件却许可的；符合《条例》和本办法规定，应当许可却不予许可的； （二）违反《条例》规定，应当接受保安从业单位、保安培训单位的备案而拒绝接受的； （三）接到举报投诉，不依法查处的； （四）发现保安从业单位和保安培训单位违反《条例》规定，不依法查处的； （五）利用职权指定安全技术防范产品的生产厂家、销售单位或者指定保安服务提供企业的； （六）接受被检查单位、个人财物或者其他不正当利益的； （七）参与或者变相参与保安服务公司经营活动的； （八）其他滥用职权、玩忽职守、徇私舞弊的行为。"},{"i":49,"n":"第四十九条","txt":"保安服务许可证和保安培训许可证包括正本和副本，正本应当悬挂在保安服务公司或者保安培训单位主要办公场所的醒目位置。 保安服务许可证、保安培训许可证、保安员证式样由公安部规定，省级公安机关制作；其他文书式样由省级公安机关自行制定。"},{"i":50,"n":"第五十条","txt":"对香港特别行政区、澳门特别行政区和台湾地区投资者设立合资、合作或者独资经营的保安服务公司的管理，参照适用外资保安服务公司的相关规定。"},{"i":51,"n":"第五十一条","txt":"本办法自发布之日起施行。"}],"gonganjiguanqiangzhigelijiedusuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强和规范公安机关强制隔离戒毒所的管理，保障强制隔离戒毒工作顺利进行，根据《中华人民共和国禁毒法》、《国务院戒毒条例》以及相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"强制隔离戒毒所是公安机关依法通过行政强制措施为戒毒人员提供科学规范的戒毒治疗、心理治疗、身体康复训练和卫生、道德、法制教育，开展职业技能培训的场所。"},{"i":3,"n":"第三条","txt":"强制隔离戒毒所应当坚持戒毒治疗与教育康复相结合的方针，遵循依法、严格、科学、文明管理的原则，实现管理规范化、治疗医院化、康复多样化、帮教社会化、建设标准化。"},{"i":4,"n":"第四条","txt":"强制隔离戒毒所应当建立警务公开制度，依法接受监督。"},{"i":5,"n":"第五条","txt":"强制隔离戒毒所由县级以上地方人民政府设置。 强制隔离戒毒所由公安机关提出设置意见，经本级人民政府和省级人民政府公安机关分别审核同意后，报省级人民政府批准，并报公安部备案。"},{"i":6,"n":"第六条","txt":"强制隔离戒毒所机构名称为XX省（自治区、直辖市）、XX市（县、区、旗）强制隔离戒毒所。 同级人民政府设置有司法行政部门管理的强制隔离戒毒所的，公安机关管理的强制隔离戒毒所名称为XX省（自治区、直辖市）、XX市（县、区、旗）第一强制隔离戒毒所。"},{"i":7,"n":"第七条","txt":"强制隔离戒毒所建设，应当符合国家有关建设规范。建设方案，应当经省级人民政府公安机关批准。"},{"i":8,"n":"第八条","txt":"强制隔离戒毒所设所长一人，副所长二至四人，必要时可设置政治委员或教导员。强制隔离戒毒所根据工作需要设置相应的机构，配备相应数量的管教、监控、巡视、医护、技术、财会等民警和工勤人员，落实岗位责任。 强制隔离戒毒所根据工作需要配备一定数量女民警。 公安机关可以聘用文职人员参与强制隔离戒毒所的戒毒治疗、劳动技能培训、法制教育等非执法工作，可以聘用工勤人员从事勤杂工作。"},{"i":9,"n":"第九条","txt":"强制隔离戒毒所管理人员、医务人员享受国家规定的工资福利待遇和职业保险。"},{"i":10,"n":"第十条","txt":"强制隔离戒毒所的基础建设经费、日常运行公用经费、办案（业务）经费、业务装备经费、戒毒人员监管给养经费，按照县级以上人民政府的财政预算予以保障。 各省、自治区、直辖市公安机关应当会同本地财政部门每年度对戒毒人员伙食费、医疗费等戒毒人员经费标准进行核算。"},{"i":11,"n":"第十一条","txt":"强制隔离戒毒所应当建立并严格执行财物管理制度，接受有关部门的检查和审计。"},{"i":12,"n":"第十二条","txt":"强制隔离戒毒所按照收戒规模设置相应的医疗机构，接受卫生行政部门对医疗工作的指导和监督。 强制隔离戒毒所按照卫生行政部门批准的医疗机构要求配备医务工作人员。 强制隔离戒毒所医务工作人员应当参加卫生行政部门组织的业务培训和职称评定考核。"},{"i":13,"n":"第十三条","txt":"强制隔离戒毒所凭《强制隔离戒毒决定书》，接收戒毒人员。"},{"i":14,"n":"第十四条","txt":"强制隔离戒毒所接收戒毒人员时，应当对戒毒人员进行必要的健康检查，确认是否受伤、患有传染病或者其他疾病，对女性戒毒人员还应当确认是否怀孕，并填写《戒毒人员健康检查表》。 办理入所手续后，强制隔离戒毒所民警应当向强制隔离戒毒决定机关出具收戒回执。"},{"i":15,"n":"第十五条","txt":"对怀孕或者正在哺乳自己不满一周岁婴儿的妇女，强制隔离戒毒所应当通知强制隔离戒毒决定机关依法变更为社区戒毒。 戒毒人员不满十六周岁且强制隔离戒毒可能影响其学业的，强制隔离戒毒所可以建议强制隔离戒毒决定机关依法变更为社区戒毒。 对身体有外伤的，强制隔离戒毒所应当予以记录，由送戒人员出具伤情说明并由戒毒人员本人签字确认。"},{"i":16,"n":"第十六条","txt":"强制隔离戒毒所办理戒毒人员入所手续，应当填写《戒毒人员入所登记表》，并在全国禁毒信息管理系统中录入相应信息，及时进行信息维护。 戒毒人员基本信息与《强制隔离戒毒决定书》相应信息不一致的，强制隔离戒毒所应当要求办案部门核查并出具相应说明。"},{"i":17,"n":"第十七条","txt":"强制隔离戒毒所应当对戒毒人员人身和随身携带的物品进行检查。除生活必需品外，其他物品由强制隔离戒毒所代为保管，并填写《戒毒人员财物保管登记表》一式二份，强制隔离戒毒所和戒毒人员各存一份。经戒毒人员签字同意，强制隔离戒毒所可以将代为保管物品移交戒毒人员近亲属保管。 对检查时发现的毒品以及其他依法应当没收的违禁品，强制隔离戒毒所应当逐件登记，并依照有关规定处理。与案件有关的物品应当移交强制隔离戒毒决定机关处理。 对女性戒毒人员的人身检查，应当由女性工作人员进行。"},{"i":18,"n":"第十八条","txt":"强制隔离戒毒所应当配合办案部门查清戒毒人员真实情况，对新入所戒毒人员信息应当与在逃人员、违法犯罪人员等信息系统进行比对，发现戒毒人员有其他违法犯罪行为或者为在逃人员的，按照相关规定移交有关部门处理。"},{"i":19,"n":"第十九条","txt":"强制隔离戒毒所应当根据戒毒人员性别、年龄、患病、吸毒种类等情况设置不同病区，分别收戒管理。 强制隔离戒毒所根据戒毒治疗的不同阶段和戒毒人员表现，实行逐步适应社会的分级管理。"},{"i":20,"n":"第二十条","txt":"强制隔离戒毒所应当建立新入所戒毒人员管理制度，对新入所戒毒人员实行不少于十五天的过渡管理和教育。"},{"i":21,"n":"第二十一条","txt":"强制隔离戒毒所应当在戒毒人员入所二十四小时内进行谈话教育，书面告知其应当遵守的管理规定和依法享有的权利及行使权利的途径，掌握其基本情况，疏导心理，引导其适应新环境。"},{"i":22,"n":"第二十二条","txt":"戒毒人员提出检举、揭发、控告，以及提起行政复议或者行政诉讼的，强制隔离戒毒所应当登记后及时将有关材料转送有关部门。"},{"i":23,"n":"第二十三条","txt":"强制隔离戒毒所应当保障戒毒人员通信自由和通信秘密。对强制隔离戒毒所以外的人员交给戒毒人员的物品和邮件，强制隔离戒毒所应当进行检查。检查时，应当有两名以上工作人员同时在场。 经强制隔离戒毒所批准，戒毒人员可以用指定的固定电话与其亲友、监护人或者所在单位、就读学校通话。"},{"i":24,"n":"第二十四条","txt":"强制隔离戒毒所建立探访制度，允许戒毒人员亲属、所在单位或者就读学校的工作人员探访。 探访人员应当接受强制隔离戒毒所身份证件检查，遵守探访规定。对违反规定的探访人员，强制隔离戒毒所可以提出警告或者责令其停止探访。"},{"i":25,"n":"第二十五条","txt":"戒毒人员具有以下情形之一的，强制隔离戒毒所可以批准其请假出所： （一）配偶、直系亲属病危或者有其他正当理由需离所探视的； （二）配偶、直系亲属死亡需要处理相应事务的； （三）办理婚姻登记等必须由本人实施的民事法律行为的。 戒毒人员应当提出请假出所的书面申请并提供相关证明材料，经强制隔离戒毒所所长批准，并报主管公安机关备案后，发给戒毒人员请假出所证明。 请假出所时间最长不得超过十天，离所和回所当日均计算在内。对请假出所不归的，视作脱逃行为处理。"},{"i":26,"n":"第二十六条","txt":"律师会见戒毒人员应当持律师执业证、律师事务所介绍信和委托书，在强制隔离戒毒所内指定地点进行。"},{"i":27,"n":"第二十七条","txt":"强制隔离戒毒所应当制定并严格执行戒毒人员伙食标准，保证戒毒人员饮食卫生、吃熟、吃热、吃够定量。 对少数民族戒毒人员，应当尊重其饮食习俗。"},{"i":28,"n":"第二十八条","txt":"强制隔离戒毒所应当建立戒毒人员代购物品管理制度，代购物品仅限日常生活用品和食品。"},{"i":29,"n":"第二十九条","txt":"强制隔离戒毒所应当建立戒毒人员一日生活制度。 强制隔离戒毒所应当督促戒毒人员遵守戒毒人员行为规范，并根据其现实表现分别予以奖励或者处罚。"},{"i":30,"n":"第三十条","txt":"强制隔离戒毒所应当建立出入所登记制度。 戒毒区实行封闭管理，非本所工作人员出入应经所领导批准。"},{"i":31,"n":"第三十一条","txt":"强制隔离戒毒所应当统一戒毒人员的着装、被服，衣被上应当设置本所标志。"},{"i":32,"n":"第三十二条","txt":"强制隔离戒毒所应当安装监控录像、应急报警、病室报告装置、门禁检查和违禁物品检测等技防系统。监控录像保存时间不得少于十五天。"},{"i":33,"n":"第三十三条","txt":"强制隔离戒毒所应当定期或者不定期进行安全检查，及时发现和消除安全隐患。"},{"i":34,"n":"第三十四条","txt":"强制隔离戒毒所应当建立突发事件处置预案，并定期进行演练。 遇有戒毒人员脱逃、暴力袭击他人的，强制隔离戒毒所可以依法使用警械予以制止。"},{"i":35,"n":"第三十五条","txt":"强制隔离戒毒所应当建立二十四小时值班巡视制度。 值班人员必须坚守岗位，履行职责，加强巡查，不得擅离职守，不得从事有碍值班的活动。 值班人员发现问题，应当果断采取有效措施，及时处置，并按规定向上级报告。"},{"i":36,"n":"第三十六条","txt":"对有下列情形之一的戒毒人员，应当根据不同情节分别给予警告、训诫、责令具结悔过或者禁闭；构成犯罪的，依法追究刑事责任： （一）违反戒毒人员行为规范、不遵守强制隔离戒毒所纪律，经教育不改正的； （二）私藏或者吸食、注射毒品，隐匿违禁物品的； （三）欺侮、殴打、虐待其他戒毒人员，占用他人财物等侵犯他人权利的； （四）交流吸毒信息、传授犯罪方法或者教唆他人违法犯罪的； （五）预谋或者实施自杀、脱逃、行凶的。 对戒毒人员处以警告、训诫和责令具结悔过，由管教民警决定并执行；处以禁闭，由管教民警提出意见，报强制隔离戒毒所所长批准。 对情节恶劣的，在诊断评估时应当作为建议延长其强制隔离戒毒期限的重要情节；构成犯罪的，交由侦查部门侦查，被决定刑事拘留或者逮捕的转看守所羁押。"},{"i":37,"n":"第三十七条","txt":"强制隔离戒毒所发生戒毒人员脱逃的，应当立即报告主管公安机关，并配合追回脱逃人员。被追回的戒毒人员应当继续执行强制隔离戒毒，脱逃期间不计入强制隔离戒毒期限。被追回的戒毒人员不得提前解除强制隔离戒毒，诊断评估时可以作为建议延长其强制隔离戒毒期限的情节。"},{"i":38,"n":"第三十八条","txt":"戒毒人员在强制隔离戒毒期间死亡的，强制隔离戒毒所应当立即向主管公安机关报告，同时通报强制隔离戒毒决定机关，通知其家属和同级人民检察院。主管公安机关应当组织相关部门对死亡原因进行调查。查清死亡原因后，尽快通知死者家属。 其他善后事宜依照国家有关规定处理。"},{"i":39,"n":"第三十九条","txt":"强制隔离戒毒所应当建立询问登记制度，配合办案部门的询问工作。"},{"i":40,"n":"第四十条","txt":"办案人员询问戒毒人员，应当持单位介绍信及有效工作证件，办理登记手续，在询问室进行。 因办案需要，经强制隔离戒毒所主管公安机关负责人批准，办案部门办理交接手续后可以将戒毒人员带离出所，出所期间的安全由办案部门负责。戒毒人员被带离出所以及送回所时，强制隔离戒毒所应对其进行体表检查，做好书面记录，由强制隔离戒毒所民警、办案人员和戒毒人员签字确认。"},{"i":41,"n":"第四十一条","txt":"强制隔离戒毒所戒毒治疗和护理操作规程按照国家有关规定进行。"},{"i":42,"n":"第四十二条","txt":"强制隔离戒毒所根据戒毒人员吸食、注射毒品的种类和成瘾程度等，进行有针对性的生理治疗、心理治疗和身体康复训练，并建立个人病历。"},{"i":43,"n":"第四十三条","txt":"强制隔离戒毒所实行医护人员二十四小时值班和定时查房制度，医护人员应当随时掌握分管戒毒人员的治疗和身体康复情况，并给予及时的治疗和看护。"},{"i":44,"n":"第四十四条","txt":"强制隔离戒毒所对患有传染病的戒毒人员，按照国家有关规定采取必要的隔离、治疗措施。"},{"i":45,"n":"第四十五条","txt":"强制隔离戒毒所对毒瘾发作或者出现精神障碍可能发生自伤、自残或者实施其他危险行为的戒毒人员，可以按照卫生行政部门制定的医疗规范采取保护性约束措施。 对被采取保护性约束措施的戒毒人员，民警和医护人员应当密切观察，可能发生自伤、自残或者实施其他危险行为的情形解除后及时解除保护性约束措施。"},{"i":46,"n":"第四十六条","txt":"戒毒人员患严重疾病，不出所治疗可能危及生命的，经强制隔离戒毒所主管公安机关批准，报强制隔离戒毒决定机关备案，强制隔离戒毒所可以允许其所外就医，并发给所外就医证明。所外就医的费用由戒毒人员本人承担。 所外就医期间，强制隔离戒毒期限连续计算。对于健康状况不再适宜回所执行强制隔离戒毒的，强制隔离戒毒所应当向强制隔离戒毒决定机关提出变更为社区戒毒的建议，强制隔离戒毒决定机关应当自收到建议之日起七日内，作出是否批准的决定。经批准变更为社区戒毒的，已执行的强制隔离戒毒期限折抵社区戒毒期限。"},{"i":47,"n":"第四十七条","txt":"强制隔离戒毒所使用麻醉药品和精神药品，应当按照规定向有关部门申请购买。需要对戒毒人员使用麻醉药品和精神药品的，由具有麻醉药品、精神药品处方权的执业医师按照有关技术规范开具处方，医护人员应当监督戒毒人员当面服药。 强制隔离戒毒所应当按照有关规定严格管理麻醉药品和精神药品，严禁违规使用，防止流入非法渠道。"},{"i":48,"n":"第四十八条","txt":"强制隔离戒毒所应当建立卫生防疫制度，设置供戒毒人员沐浴、理发和洗晒被服的设施。对戒毒病区应当定期消毒，防止传染疫情发生。"},{"i":49,"n":"第四十九条","txt":"强制隔离戒毒所可以与社会医疗机构开展多种形式的医疗合作，保证医疗质量。"},{"i":50,"n":"第五十条","txt":"强制隔离戒毒所应当设立教室、心理咨询室、谈话教育室、娱乐活动室、技能培训室等教育、康复活动的功能用房。"},{"i":51,"n":"第五十一条","txt":"强制隔离戒毒所应当建立民警与戒毒人员定期谈话制度。管教民警应当熟悉分管戒毒人员的基本情况，包括戒毒人员自然情况、社会关系、吸毒经历、思想动态和现实表现等。"},{"i":52,"n":"第五十二条","txt":"强制隔离戒毒所应当对戒毒人员经常开展法制、禁毒宣传、艾滋病性病预防宣传等主题教育活动。"},{"i":53,"n":"第五十三条","txt":"强制隔离戒毒所对戒毒人员的教育，可以采取集中授课、个别谈话、社会帮教、亲友规劝、现身说法等多种形式进行。强制隔离戒毒所可以邀请有关专家、学者、社会工作者以及戒毒成功人员协助开展教育工作。"},{"i":54,"n":"第五十四条","txt":"强制隔离戒毒所应当制定奖励制度，鼓励、引导戒毒人员坦白、检举违法犯罪行为。 强制隔离戒毒所应当及时将戒毒人员提供的违法犯罪线索转递给侦查办案部门。办案部门应当及时进行查证并反馈查证情况。 强制隔离戒毒所应当对查证属实、有立功表现的戒毒人员予以奖励，并作为诊断评估的重要依据。"},{"i":55,"n":"第五十五条","txt":"强制隔离戒毒所可以动员、劝导戒毒人员戒毒期满出所后进入戒毒康复场所康复，并提供便利条件。"},{"i":56,"n":"第五十六条","txt":"强制隔离戒毒所应当积极联系劳动保障、教育等有关部门，向戒毒人员提供职业技术、文化教育培训。"},{"i":57,"n":"第五十七条","txt":"强制隔离戒毒所应当组织戒毒人员开展文体活动，进行体能训练。一般情况下，每天进行不少于二小时的室外活动。"},{"i":58,"n":"第五十八条","txt":"强制隔离戒毒所应当采取多种形式对戒毒人员进行心理康复训练。"},{"i":59,"n":"第五十九条","txt":"强制隔离戒毒所可以根据戒毒需要和戒毒人员的身体状况组织戒毒人员参加康复劳动，康复劳动时间每天最长不得超过六小时。 强制隔离戒毒所不得强迫戒毒人员参加劳动。"},{"i":60,"n":"第六十条","txt":"强制隔离戒毒所康复劳动场所和康复劳动项目应当符合国家相关规定，不得开展有碍于安全管理和戒毒人员身体康复的项目。"},{"i":61,"n":"第六十一条","txt":"强制隔离戒毒所应当对戒毒人员康复劳动收入和支出建立专门账目，严格遵守财务制度，专款专用。戒毒人员康复劳动收入使用范围如下： （一）支付戒毒人员劳动报酬； （二）改善戒毒人员伙食及生活条件； （三）购置劳保用品； （四）其他必要开支。"},{"i":62,"n":"第六十二条","txt":"对需要转至司法行政部门强制隔离戒毒所继续执行强制隔离戒毒的人员，公安机关应当与司法行政部门办理移交手续。"},{"i":63,"n":"第六十三条","txt":"对外地戒毒人员，如其户籍地强制隔离戒毒所同意接收，强制隔离戒毒决定机关可以变更执行场所，将戒毒人员交付其户籍地强制隔离戒毒所执行并办理移交手续。"},{"i":64,"n":"第六十四条","txt":"强制隔离戒毒所应当建立戒毒诊断评估工作小组，按照有关规定对戒毒人员的戒毒康复、现实表现、适应社会能力等情况作出综合评估。对转至司法行政部门继续执行的，强制隔离戒毒所应当将戒毒人员戒毒康复、日常行为考核等情况一并移交司法行政部门强制隔离戒毒所，并通报强制隔离戒毒决定机关。"},{"i":65,"n":"第六十五条","txt":"戒毒人员被依法收监执行刑罚、采取强制性教育措施或者被依法拘留、逮捕的，强制隔离戒毒所应当根据有关法律文书，与相关部门办理移交手续，并通知强制隔离戒毒决定机关。监管场所、羁押场所应当给予必要的戒毒治疗。 刑罚执行完毕时、解除强制性教育措施时或者释放时强制隔离戒毒尚未期满的，继续执行强制隔离戒毒。"},{"i":66,"n":"第六十六条","txt":"强制隔离戒毒所应当将戒毒人员以下信息录入全国禁毒信息管理系统，进行相应的信息维护： （一）强制隔离戒毒期满出所的； （二）转至司法行政部门强制隔离戒毒所继续执行的； （三）转至司法行政部门强制隔离戒毒所不被接收的； （四）所外就医的； （五）变更为社区戒毒的； （六）脱逃或者请假出所不归的； （七）脱逃被追回后在其他强制隔离戒毒所执行的。"},{"i":67,"n":"第六十七条","txt":"强制隔离戒毒所应当建立并妥善保管戒毒人员档案。档案内容包括：强制隔离戒毒决定书副本、行政复议或者诉讼结果文书、戒毒人员登记表、健康检查表、财物保管登记表、病历、奖惩情况记录、办案机关或者律师询问记录、诊断评估结果、探访与请假出所记录、出所凭证等在强制隔离戒毒期间产生的有关文书及图片。 戒毒人员死亡的，强制隔离戒毒所应当将《戒毒人员死亡鉴定书》和《戒毒人员死亡通知书》归入其档案。 除法律明确规定外，强制隔离戒毒所不得对外提供戒毒人员档案。"},{"i":68,"n":"第六十八条","txt":"对被处以行政拘留的吸毒成瘾人员，本级公安机关没有设立拘留所或者拘留所不具备戒毒治疗条件的，强制隔离戒毒所可以代为执行。"},{"i":69,"n":"第六十九条","txt":"有条件的强制隔离戒毒所可以接收自愿戒毒人员。但应当建立专门的自愿戒毒区，并按照卫生行政部门关于自愿戒毒的规定管理自愿戒毒人员。 对自愿接受强制隔离戒毒的吸毒成瘾人员，强制隔离戒毒所应当与其就戒毒治疗期限、戒毒治疗措施等签订书面协议。"},{"i":70,"n":"第七十条","txt":"强制隔离戒毒所实行等级化管理，具体办法由公安部另行制定。"},{"i":71,"n":"第七十一条","txt":"本办法所称以上，均包括本数、本级。"},{"i":72,"n":"第七十二条","txt":"强制隔离戒毒所的文书格式，由公安部统一制定。"},{"i":73,"n":"第七十三条","txt":"本办法自公布之日起施行，公安部2000年4月17日发布施行的《强制戒毒所管理办法》同时废止。"}],"gonganjiguanzhifazhiliangkaohepingyiguiding":[{"i":1,"n":"第一条","txt":"为加强公安机关执法监督管理，落实执法责任，提高执法质量，促进公安机关及其人民警察严格规范公正文明执法，根据《中华人民共和国人民警察法》及其他有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"执法质量考核评议，是指上级公安机关对下级公安机关、各级公安机关对所属执法部门及其人民警察执法办案质量进行的考核评议。"},{"i":3,"n":"第三条","txt":"执法质量考核评议，应当坚持实事求是、公开公正、奖优罚劣、注重实效的原则。"},{"i":4,"n":"第四条","txt":"公安机关执法质量考核评议的主要内容包括： （一）接处警执法情况； （二）办理案件情况； （三）实施行政许可、登记备案等行政管理情况； （四）执法监督救济情况； （五）执法办案场所和监管场所建设与管理情况； （六）涉案财物管理和涉案人员随身财物代为保管以及证物保管情况； （七）执法安全情况； （八）执法办案信息系统应用管理情况； （九）其他需要考核评议的内容。"},{"i":5,"n":"第五条","txt":"接处警执法应当达到以下标准： （一）接警文明规范，出警及时； （二）着装、携带使用处警装备符合规定； （三）处置措施适度、规范； （四）现场取证及时、全面； （五）接处警记录完整、准确、规范； （六）按规定出具接报案回执。"},{"i":6,"n":"第六条","txt":"办理案件应当达到以下标准： （一）受案立案及时、合法、规范； （二）执法主体合法，并具备相应的执法资格； （三）案件管辖符合规定； （四）案件事实清楚，证据确实充分，程序合法； （五）调查取证合法、及时、客观、全面； （六）定性及适用法律、法规、规章准确，量处适当； （七）适用强制措施、侦查措施、作出行政处理决定符合规定； （八）执行刑罚、行政处理决定符合规定； （九）依法保护当事人的合法权益，保障律师执业权利； （十）案件信息公开符合规定； （十一）法律文书规范、完备，送达合法、及时，案卷装订、保管、移交规范。"},{"i":7,"n":"第七条","txt":"实施行政许可、登记备案等行政管理应当达到以下标准： （一）受理申请及时，履行通知告知义务符合规定； （二）依法及时履行审查、核查等职责，办理程序符合规定； （三）对从事行政许可等事项活动的监督检查符合规定； （四）撤销行政许可、注销相关证件符合规定； （五）工作记录、台账、法律文书、档案完备； （六）其他行政管理中无不作为、乱作为等情形。"},{"i":8,"n":"第八条","txt":"执法监督救济应当达到以下标准： （一）受理、查处涉警投诉及时、规范，办理涉法涉诉信访事项的程序合法，无拒不受理、违规受理或者推诿、拖延、敷衍办理等情形； （二）对符合法定受理条件的行政复议、刑事复议复核案件及时受理，办案程序合法、适用法律正确； （三）对行政诉讼案件依法出庭应诉，提出诉讼证据和答辩意见，及时执行生效判决； （四）办理国家赔偿案件程序合法、适用法律正确，无不依法赔偿或者违反规定采取补偿、救助等形式代替国家赔偿等情形； （五）对已发现的执法问题及时纠正，依法追究执法过错责任人的责任。"},{"i":9,"n":"第九条","txt":"执法办案场所和监管场所建设与管理应当达到以下标准： （一）执法办案和监管场所功能设置规范合理、设施设备运转正常，安全防护措施落实到位； （二）工作流程、岗位职责、应急处置工作预案等制度健全完善； （三）违法犯罪嫌疑人被带至公安机关后，直接带入办案区，无违反规定带出办案区讯问询问等情形； （四）违法犯罪嫌疑人进入办案区后，按照规定进行人身检查和信息采集； （五）违法犯罪嫌疑人在办案区内，有人负责看管； （六）在办案区内开展执法活动，有视频监控并记录，同步录音录像资料保管妥当； （七）办案区使用的记录、台账等完整、规范。"},{"i":10,"n":"第十条","txt":"涉案财物管理和涉案人员随身财物代为保管应当达到以下标准： （一）财物管理场所设置、保管财物的设备设施符合规定； （二）财物管理制度健全，办案与管理分离、统一管理的有关要求得到落实； （三）按照规定对财物登记、保管、处理，记录、台账清晰完备。 不属于涉案财物的证物的管理标准按照相关规定确定，没有具体规定的，参照上述标准执行。"},{"i":11,"n":"第十一条","txt":"执法安全应当达到以下标准： （一）无因违法使用警械、武器造成人员伤亡等情形； （二）无因故意或者过失致使被监管人员、涉案人员行凶、自杀、自伤、脱逃等情形； （三）无殴打、虐待或者唆使、放纵他人殴打、虐待被监管人员、涉案人员等情形； （四）无其他造成恶劣影响的执法安全事故。"},{"i":12,"n":"第十二条","txt":"执法办案信息系统应用管理应当达到以下标准： （一）接报案、受案立案信息系统使用符合规定，110接报警、群众上门报案、有关部门移送案件以及公安机关工作中发现的违法犯罪线索等信息录入及时、规范； （二）落实网上办案要求，除案件性质和事实涉及国家秘密的以外，实现各类案件信息、主要证据材料上传信息系统，审核审批考评网上进行，案件电子卷宗自动生成； （三）接报警信息与网上办案、监督考评、督察、办案场所管理、音视频资料管理、涉案财物管理等各类信息系统之间互联互通、数据共享； （四）自动生成执法办案单位及其民警的执法档案，准确记载执法办案的数量和质量； （五）无擅自更改或者删除执法办案信息系统中已经审核、审批通过的案件信息等情形； （六）指定专人担任系统管理员，执法办案信息系统正常运转。"},{"i":13,"n":"第十三条","txt":"在登记、统计、上报各类执法情况过程中，实事求是，严格遵守有关规定，无弄虚作假、隐瞒不报的情形。"},{"i":14,"n":"第十四条","txt":"各地执法质量考核评议项目和指标由省级公安机关统一确定，各级公安机关部门、警种不得以部门、警种名义下达执法质量考核评议项目和指标。 确定执法质量考核评议项目和指标，应当把执法质量与执法数量、执法效率、执法效果结合起来，激励民警又好又多地执法办案，但不得以不科学、不合理的罚没款数额、刑事拘留数、行政拘留数、发案数、退查率、破案率等作为考评指标。"},{"i":15,"n":"第十五条","txt":"年度执法质量考核评议实行百分制，根据考核评议的内容范围，确定考核评议各项内容所占比重。 考核评议结果以年度积分为准，分为优秀、达标、不达标三档。"},{"i":16,"n":"第十六条","txt":"各级公安机关应当把内部考评与外部评价有机结合起来，将警务评议、社会公众评价和执法相对人、案件当事人对执法工作的评价作为执法质量考核评议的重要依据。"},{"i":17,"n":"第十七条","txt":"具有下列情形之一的，不予扣分： （一）因法律法规、司法解释发生变化，改变案件定性、处理的； （二）因法律规定不明确、有关司法解释不一致，致使案件定性、处理存在争议的； （三）因不能预见或者无法抗拒的原因致使执法问题发生的； （四）对案件基本事实的判断存在争议或者疑问，根据证据规则能够予以合理说明的； （五）因出现新证据而改变原结论的； （六）原结论依据的法律文书被撤销或者变更的； （七）因执法相对人的过错致使执法过错发生的。"},{"i":18,"n":"第十八条","txt":"因执行上级公安机关决定、命令而发生执法过错的，不予扣分。 对超越法律、法规规定的人民警察职责范围的指令，下级公安机关有权拒绝执行，并同时向上级公安机关报告。没有报告造成执法问题的，应当扣分；已经报告的，可以减少扣分。"},{"i":19,"n":"第十九条","txt":"对执法问题自查自纠，并已依法追究执法过错责任的，可以减少扣分或者不予扣分。"},{"i":20,"n":"第二十条","txt":"具有下列情形之一的，年度执法质量考核评议结果应当确定为不达标： （一）发生错案，造成恶劣社会影响的； （二）刑讯逼供或者殴打、体罚、虐待被监管人员、涉案人员致其重伤、死亡的； （三）违法使用警械、武器致人重伤、死亡的； （四）因疏于管理、玩忽职守、滥用职权等原因造成被监管人员、涉案人员非正常死亡、脱逃的； （五）因黄、赌、毒或者涉黑涉恶违法犯罪现象严重，造成恶劣社会影响的； （六）领导班子成员因执法问题被追究刑事责任的。 被考核评议单位拒绝接受考核评议或者弄虚作假的，年度执法质量考核评议结果应当确定为不达标。"},{"i":21,"n":"第二十一条","txt":"上级公安机关对下一级公安机关应当定期开展执法质量考核评议，省级公安机关对下级公安机关每年度至少进行一次全面的执法质量考核评议。 对公安机关各执法部门和执法民警的执法质量考核评议，由所属公安机关组织实施。"},{"i":22,"n":"第二十二条","txt":"执法质量考核评议工作应当成立以公安机关行政首长任组长，有关部门参加的考核评议领导小组，统一组织实施考评工作。执法质量考核评议领导小组办公室设在法制部门，考核评议日常工作由法制部门负责组织实施。 公安机关部门、警种对日常工作中发现的执法问题，应当及时移送本级公安机关执法质量考核评议领导小组办公室。年度考核评议结果通报前，应当征求纪检监察、督察、审计、人事等部门的意见。 各级公安机关应当为开展执法质量考核评议工作提供必要的保障和支持。"},{"i":23,"n":"第二十三条","txt":"执法质量考核评议采取日常考评、阶段考评、专项考评、年终考评相结合的方法。日常考评成绩作为年度执法质量考核评议成绩的重要依据。 年度执法质量考核评议以本年1月1日至12月31日为一个考评年度。对执法问题的发现与处理在不同考评年度的，按照处理时间所在年度进行考评。"},{"i":24,"n":"第二十四条","txt":"各级公安机关应当为所属执法部门和执法民警建立网上执法档案，完整、准确、实时记载执法数量、执法质量、执法培训、考核结果、执法过错责任追究等情况。"},{"i":25,"n":"第二十五条","txt":"各级公安机关应当建立执法质量考核评议通报和报告制度。 上级公安机关对下级公安机关的执法质量考核评议情况应当在本辖区公安机关内部进行通报；各级公安机关对所属执法部门、执法民警的执法质量考核评议情况应当在本级公安机关内部通报。 下级公安机关开展年度执法质量考核评议情况应当在考评结束后一个月内报告上一级公安机关。"},{"i":26,"n":"第二十六条","txt":"考核评议结果应当及时告知被考核评议单位或者民警。对结果有异议的，可以及时向负责考核评议的公安机关提出书面申诉。负责考核评议的公安机关可以视情重新组织人员复查，并告知复查结果。"},{"i":27,"n":"第二十七条","txt":"执法质量考核评议结果作为衡量公安机关及其所属执法部门、执法民警工作实绩的重要依据，并作为衡量领导班子和领导干部工作实绩的重要内容。涉及公安机关领导、执法部门的干部任用，执法民警晋职晋级以及执法工作的评优评先，应当把执法质量考核评议结果作为考核工作实绩的重要依据。"},{"i":28,"n":"第二十八条","txt":"对年度执法质量考核评议结果为优秀的，应当对相关的单位和个人予以表彰奖励。 对不达标单位予以通报批评，责令限期整改，取消其当年评优受奖资格；连续两年不达标的，单位行政首长应当辞职，或者由上级公安机关商请有关部门对其予以免职。"},{"i":29,"n":"第二十九条","txt":"申报全国优秀公安局、全国公安机关执法示范单位的，近两个年度执法质量考核评议结果必须达到优秀。 申报省级以下优秀公安局、执法示范单位的，上年度执法质量考核评议结果必须达到优秀。 申报优秀基层单位的，参照前两款规定执行。"},{"i":30,"n":"第三十条","txt":"在执法质量考核评议过程中，发现已办结的案件或者执法活动确有错误、不适当的，应当及时纠正。需要追究有关领导或者直接责任人员执法过错责任的，应当依照《公安机关人民警察执法过错责任追究规定》等规定予以追究。 对违反本规定第十四条下达、设定考核评议指标以及不按照规定组织开展执法质量考核评议工作的，应当及时纠正，并依照有关规定予以追究责任。"},{"i":31,"n":"第三十一条","txt":"各省、自治区、直辖市公安厅局和新疆生产建设兵团公安局可以根据本规定，结合本地实际情况，制定实施细则。"},{"i":32,"n":"第三十二条","txt":"本规定自2016年3月1日起施行。2001年10月10日发布施行的《公安机关执法质量考核评议规定》（公安部令第60号）同时废止。"}],"gonganjiguanjiandujianchaqiyeshiyedanweineibuzhiand22b55":[{"i":1,"n":"第一条","txt":"为规范公安机关监督检查企业事业单位（以下简称单位）内部治安保卫工作行为，依据《企业事业单位内部治安保卫条例》（以下简称《条例》），制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上公安机关单位内部治安保卫工作主管部门和单位所在地公安派出所按照分工履行监督检查单位内部治安保卫工作职责。 铁路、交通、民航公安机关和国有林区森林公安机关负责监督检查本行业、本系统所属单位内部治安保卫工作。公安消防、交通管理部门依照有关规定，对单位内部消防、交通安全管理进行监督检查。"},{"i":3,"n":"第三条","txt":"公安机关监督检查单位内部治安保卫工作应当严格执行国家有关规定。对监督检查中涉及的国家秘密、商业秘密，应当予以保密。"},{"i":4,"n":"第四条","txt":"公安机关对单位内部治安保卫工作的下列事项进行监督检查： （一）单位按照《条例》规定制定和落实内部治安保卫制度情况； （二）单位主要负责人落实内部治安保卫工作责任制情况； （三）单位设置治安保卫机构和配备专职、兼职治安保卫人员情况； （四）单位落实出入登记、守卫看护、巡逻检查、重要部位重点保护、治安隐患排查处理等内部治安保卫措施情况； （五）单位治安防范设施的建设、使用和维护情况； （六）单位内部治安保卫机构、治安保卫人员依法履行职责情况； （七）单位管理范围内的人员遵守单位内部治安保卫制度情况； （八）单位内部治安保卫人员接受有关法律知识和治安保卫业务、技能以及相关专业知识培训、考核情况； （九）其他依法应当监督检查的内容。"},{"i":5,"n":"第五条","txt":"公安机关监督检查治安保卫重点单位，除执行本规定第四条规定外，还应当对下列事项进行监督检查： （一）治安保卫机构设置和人员配备报主管公安机关备案情况； （二）治安保卫重要部位确定情况； （三）按照国家有关标准对治安保卫重要部位设置必要的安全技术防范设施，并实施重点保护情况； （四）制定单位内部治安突发事件处置预案及组织演练情况； （五）其他依法应当监督检查的内容。"},{"i":6,"n":"第六条","txt":"公安机关监督检查单位内部治安保卫工作，可以采取以下方法： （一）要求单位治安保卫工作负责人和其他工作人员对检查事项作出说明； （二）查阅、调取、复制与治安保卫工作有关的文件、资料； （三）实地查看单位治安保卫制度、措施的制定和落实情况，查看单位物防、技防等治安防范设施的设置和运行情况； （四）利用监控设备检查单位内部治安保卫工作的落实情况； （五）根据需要采取的其他监督检查方法。 监督检查可以采取定期检查、临时检查、专项检查、随机抽查等方式进行，检查民警不得少于两人，并应当向被检查单位负责人或者其他有关人员出示工作证件。"},{"i":7,"n":"第七条","txt":"监督检查应当制作《检查笔录》，如实记录监督检查情况和发现的治安隐患，并交被检查单位负责人或者陪同检查人员核对签名。被检查单位负责人或者陪同检查人员对记录有异议的，应当允许其说明；拒绝签名的，检查民警应当在《检查笔录》上注明。"},{"i":8,"n":"第八条","txt":"单位违反《条例》规定，存在治安隐患的，公安机关应当责令限期整改，并处警告。 责令单价限期整改治安隐患时，应当制作《责令限期整改治安隐患通知书》，详细列明具体隐患及相应整改期限，整改期限最长不超过二个月。《责令限期整改治安隐患通知书》应当自检查完毕之日起三个工作日内送达被检查单位。 单位在整改治安隐患期间应当采取必要的防范措施，确保安全。"},{"i":9,"n":"第九条","txt":"单位认为有正当理由不能在整改期限内将治安隐患整改完毕的，应当在整改期限届满前向发出《责令限期整改治安隐患通知书》的公安机关提出书面延期整改申请。 公安机关应当自受理申请之日起三个工作日内对延期申请进行审查，作出是否同意延期的决定并送达《同意／不同意延期整改治安隐患通知书》。延期整改期限最长不超过一个月。"},{"i":10,"n":"第十条","txt":"对责令限期整改或者同意延期整改治安隐患的，公安机关应当自责令整改期限或者延期整改期限届满次日起三个工作日内对治安隐患整改情况进行复查，自复查之日起三个工作日内制作并送达《复查意见告知书》。 单位在规定整改期限届满前，认为已将公安机关责令限期整改或者同意延期整改的治安隐患提前整改完毕的，可以向公安机关提出提前复查治安隐患整改情况的申请，公安机关应当自收到单位申请次日起三个工作日内对整改情况进行复查，自复查之日起三个工作日内制作并送达《复查意见告知书》。 经复查，由于客观原因致使治安隐患整改情况难以达到规定要求，并严重威胁公民人身安全、公私财产安全或者公共安全的，公安机关应当及时报告当地人民政府或者通报单位上一级主管部门协调解决。对无正当理由致使整改情况未达到规定要求的，公安机关应当按逾期不整改治安隐患依法处理，并可根据需要在一定范围内予以通报，督促单位落实整改措施。"},{"i":11,"n":"第十一条","txt":"单位违反《条例》规定，存在下列治安隐患情形之一，经公安机关责令限期整改后逾期不整改，严重威胁公民人身安全、公私财产安全或者公共安全的，公安机关应当依据《条例》第十九条的规定，对单位处一万元以上二万元以下罚款，对单位主要负责人和其他直接责任人员分别处五百元以上一千元以下罚款；造成公民人身伤害、公私财产损失的，对单位处二万元以上五万元以下罚款，对单位主要负责人和其他直接责任人员分别处一千元以上三千元以下罚款： （一）未建立和落实主要负责人治安保卫工作责任制的； （二）未制定和落实内部治安保卫制度的； （三）未设置必要的治安防范设施的； （四）未根据单位内部治安保卫工作需要配备专职或者兼职治安保卫人员的； （五）内部治安保卫人员未接受有关法律知识和治安保卫业务、技能以及相关专业知识培训、考核的； （六）内部治安保卫机构、治安保卫人员未履行《条例》第十一条规定职责的。"},{"i":12,"n":"第十二条","txt":"单位违反《条例》规定，存在下列治安隐患情形之一，经公安机关责令限期整改后逾期不整改，严重威胁公民人身安全、公私财产安全或者公共安全的，公安机关应当依据《条例》第十九条的规定，对单位处二万元以上五万元以下罚款，对单位主要负责人和其他直接责任人员分别处一千元以上三千元以下罚款；造成公民人身伤害、公私财产损失的，对单位处五万元以上十万元以下罚款，对单位主要负责人和其他直接责任人员分别处三千元以上五千元以下罚款： （一）未制定和落实内部治安保卫措施的； （二）治安保卫重点单位未设置与治安保卫任务相适应的治安保卫机构，未配备专职治安保卫人员的； （三）治安保卫重点单位未确定本单位治安保卫重要部位，未按照国家有关标准对治安保卫重要部位设置必要的技术防范设施并实施重点保护的； （四）治安保卫重点单位未制定单位内部治安突发事件处置预案或者未定期组织演练的； （五）管理措施不落实，致使在单位管理范围内的"},{"i":13,"n":"第十三条","txt":"单位违反《条例》规定，存在本规定第十一条、第十二条所列治安隐患情形之一，经公安机关责令限期整改后逾期不整改，造成公民人身伤害、公私财产损失，或者严重威胁公民人身安全、公私财产安全或者公共安全的，除依据各该条规定给予处罚外，还可建议有关组织对单位主要负责人和其他直接责任人员依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"公安机关及其人民警察在监督检查工作中，有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任： （一）不按规定制作、送达法律文书，超过规定的时限复查单位整改情况和核查群众举报、投诉，或者有其他不依法履行监督检查职责的行为，经指出不改正，造成严重后果的； （二）对责令限期整改治安隐患的单位，未经复查或者经复查治安隐患未整改，作出复查合格决定，造成公民人身伤害、公私财产损失的； （三）对单位或者当事人故意刁难的； （四）在监督检查工作中弄虚作假的； （五）违法违规实施处罚的； （六）故意泄漏监督检查中涉及的国家秘密和单位商业秘密的； （七）有其他渎职行为的。"},{"i":15,"n":"第十五条","txt":"公安机关对机关、团体内部治安保工作的监督检查，参照本规定执行。"},{"i":16,"n":"第十六条","txt":"本规定自2007年10月1日起施行。"}],"gonganjiguanduchatiaolishishibanfa":[{"i":1,"n":"第一条","txt":"为了保证督察工作的顺利进行，根据《公安机关督察条例》(以下简称《督察条例》)，制定本办法。"},{"i":2,"n":"第二条","txt":"督察工作的基本任务是保障和监督公安机关及其人民警察依法履行职责、行使职权和遵守纪律。"},{"i":3,"n":"第三条","txt":"现场督察是指警务督察人员对公安机关及其人民警察在执法执勤活动中依法履行职责、行使职权和遵守纪律的情况进行的同步监督和检查。"},{"i":4,"n":"第四条","txt":"督察人员必须坚持以事实为根据，以法律、法规为准绳，依法履行职责、行使职权。"},{"i":5,"n":"第五条","txt":"各级公安机关及其人民警察应当自觉接受督察机构及其督察人员依法对其履行职责、行使职权和遵守纪律情况的监督。"},{"i":6,"n":"第六条","txt":"公安部督察委员会领导全国公安机关的督察工作，警务督察局承担公安部督察委员会办事机构职能。 县级以上地方各级人民政府公安机关督察机构负责本级公安机关督察工作并领导下级公安机关的督察工作，对上一级公安机关督察机构和本级公安机关行政首长负责。"},{"i":7,"n":"第七条","txt":"公安部督察委员会由督察长、副督察长和委员组成。 督察长、副督察长的人选由公安部部长提名，按照干部管理权限任免。 督察委员会委员的人选由督察长提名，报公安部部长批准。"},{"i":8,"n":"第八条","txt":"公安部督察委员会行使下列职权： (一)对公安部所属单位和下级公安机关及其人民警察依法履行职责、行使职权和遵守纪律的情况进行监督； (二)审定全国公安机关警务督察工作的部署； (三)发布有关公安机关警务督察工作的决定和命令； (四)审议和批准警务督察工作年度计划和执行情况报告； (五)定期听取警务督察局的工作汇报； (六)应当由督察委员会行使的其他职权。"},{"i":9,"n":"第九条","txt":"公安部督察委员会每季度召开一次工作会议，由督察长召集。必要时，督察长可以随时召开会议，部署警务督察工作。"},{"i":10,"n":"第十条","txt":"公安部督察委员会每半年向公安部部长报告全国公安机关警务督察工作的情况。 对重大事项的督察情况随时向公安部部长报告。"},{"i":11,"n":"第十一条","txt":"公安部警务督察局配备局长一名，副局长若干名，内设警务督察队和与督察工作相适应的处、室。"},{"i":12,"n":"第十二条","txt":"公安部警务督察局的职责是： (一)对公安部所属单位和下级公安机关及其人民警察依法履行职责、行使职权和遵守纪律的情况进行监督； (二)指导和协调全国公安机关的督察工作； (三)了解和掌握各级公安机关督察机构履行职责的情况； (四)制定警务督察工作的有关制度； (五)部署全国统一的专项督察任务，制定督察工作方案； (六)组织、指导全国公安机关督察人员的教育和培训； (七)协助本部人事部门做好对省、自治区、直辖市公安厅、局督察长、副督察长的管理工作； (八)履行《督察条例》和公安部督察委员会赋予的其他职责。"},{"i":13,"n":"第十三条","txt":"县级以上地方各级人民政府公安机关建立督察机构，其具体设置为： 省、自治区、直辖市公安厅、局配备督察长一名、副督察长二名，设警务督察处。 市(地、州、盟)公安局(处)配备督察长一名、副督察长二名，设警务督察室。 县(市、旗)公安局配备督察长一名，设警务督察队。 各级公安机关督察机构建立由专职人员组成的警务督察队。"},{"i":14,"n":"第十四条","txt":"县级以上地方各级人民政府公安机关的督察长、副督察长在提请任免之前，必须征求上一级公安机关的意见。"},{"i":15,"n":"第十五条","txt":"县级以上地方各级人民政府公安机关督察机构的职责是： (一)负责本级公安机关督察工作并领导下级公安机关的督察工作； (二)负责对本级公安机关所属单位和下级公安机关及其人民警察依法 履行职责、行使职权和遵守纪律情况的监督； (三)制定本地区督察工作的有关制度； (四)组织、实施对本级公安机关和下级公安机关督察人员的培训和考核； (五)协助人事部门做好对下一级公安机关督察长、副督察长的考察管理工作； (六)办理上级公安机关督察机构和本级公安机关行政首长交办的督察事项； (七)履行《督察条例》规定的其他职责。"},{"i":16,"n":"第十六条","txt":"各级公安机关必须按照《督察条例》规定的条件选配专职督察人员。 各级公安机关督察机构应当按照有关规定组织督察人员进行专门培训，合格后才准予上岗。"},{"i":17,"n":"第十七条","txt":"督察机构及其督察人员应当自觉接受公安机关及其人民警察和社会各界的监督，依法履行职责、行使职权。 督察人员违反本规定或在督察工作中违法违纪的，应当依照有关法律和纪律的规定追究责任。"},{"i":18,"n":"第十八条","txt":"督察人员的勤务津贴参照交警、巡警等一线公安民警的标准执行。"},{"i":19,"n":"第十九条","txt":"督察机构依据《督察条例》第四条规定的事项进行现场督察。"},{"i":20,"n":"第二十条","txt":"督察机构根据督察内容，可以采取随警督察、重点督察、专项督察等不同的督察方式。"},{"i":21,"n":"第二十一条","txt":"督察机构在执行督察任务时，通常情况下应当按照立项、审批、实施和处理等程序进行，由督察机构领导审核批准。 对重大事项的督察，必须经本级行政首长批准，由督察长组织实施，必要时报上一级督察机构备案。"},{"i":22,"n":"第二十二条","txt":"督察人员在执行现场督察任务时，不得少于二人。根据工作的需要，可以采取明察和暗访两种形式。 督察人员执行明察任务时，可以着警服或便装，同时必须佩带督察证件。进行暗访时，应当着便装，并严格按照批准的工作方案开展工作。"},{"i":23,"n":"第二十三条","txt":"根据督察工作任务的需要，经警务督察队队长以上领导批准，督察人员可以模拟设置警情，实地了解被督察对象工作的真实情况。督察任务结束后，督察人员应当及时撤销所设警情。 未经批准，任何人不得擅自模拟设置警情。"},{"i":24,"n":"第二十四条","txt":"在现场督察中，督察人员可以通过录音、摄影和摄像等手段，获取信息资料或证据。 必要时，督察机构可以邀请公安机关有关部门和专业人员配合督察工作。"},{"i":25,"n":"第二十五条","txt":"被督察的单位应当根据督察人员的要求，提供与督察事项有关的文件、资料和情况，如实回答提出的问题。 督察人员有权对督察事项有关的资料进行查阅或者复制。"},{"i":26,"n":"第二十六条","txt":"上级督察机构可以指令下级督察机构对专门事项进行督察，必要时，可以直接派员进行督察。 下级督察机构应当按照要求，认真、及时地完成交办事项的督察，并将督察结果报告上级督察机构。"},{"i":27,"n":"第二十七条","txt":"两个以上督察机构都有权管辖的督察事项，由最初受理的公安机关督察机构办理。 对管辖权不明或发生争议的，由其共同的上级公安机关督察机构指定办理。"},{"i":28,"n":"第二十八条","txt":"各级公安机关督察机构应当了解本级公安机关的重大警务活动部署，并且根据情况及时作出督察工作的安排。"},{"i":29,"n":"第二十九条","txt":"督察机构可以根据警务督察工作的需要，组织有关业务部门共同进行现场督察。"},{"i":30,"n":"第三十条","txt":"各级公安机关督察机构应当会同有关部门采取座谈、问卷调查等多种形式，每年定期、不定期地组织开展警务评议活动，广泛听取社会各界对公安机关及其人民警察履行职责、行使职权和遵守纪律情况的意见。 警务评议的结果应当及时向同级行政首长报告，并报上一级公安机关督察机构备案。"},{"i":31,"n":"第三十一条","txt":"各级公安机关督察机构对群众的投诉，应当如实登记、认真核实，及时反馈。 经督察机构核查证实反映问题不实、造成一定后果的，应当予以澄清，消除不良影响。 对于不属于督察机构督察范围的，督察机构应当立即转交有关部门处理，同时将情况反馈给检举人或控告人。"},{"i":32,"n":"第三十二条","txt":"督察人员在现场督察中发现公安机关的人民警察有下列违反警容风纪规定的行为，可以当场予以纠正： (一)不按规定穿着制式警服的； (二)警容不整的； (三)穿着警服在公共场所举止不端，有失警察形象的； (四)穿着警服在公共场所饮酒的； (五)其他违反警容风纪规定的行为。"},{"i":33,"n":"第三十三条","txt":"督察人员在现场督察中发现公安机关的人民警察有下列违反规定使用武器、警械的，可以当场予以扣留： (一)无持枪证而携带武器的； (二)违反规定携带武器、警械进入禁止区域、场所的； (三)违反规定配枪或持有警械的； (四)其他违反《枪支管理法》和《人民警察使用警械和武器条例》等法律、法规和规章规定的行为，必要时，可扣留其佩带的武器、警械。"},{"i":34,"n":"第三十四条","txt":"督察人员在现场督察中发现公安机关及其人民警察有下列违反规定使用警用车辆和警用标志的，可以当场予以扣留： (一)不按规定使用警车，滥用警灯、警报器，不按规定携带警车牌证或者挪用、转借警车牌证的； (二)私自喷涂警车外观标志，安装警灯、警报器以及伪造、涂改警车牌证的； (三)违反规定购买并使用不合格的警衔标志、警服专用标志的； (四)佩带与授予的警衔不相符的警衔标志； (五)转借或者赠予非警务人员警服或者警察专用标志； (六)其他违反《警车管理规定》以及警察专用标志等方面的法律、法规和规章规定的行为，必要时，可以扣留其使用的警车及标志。"},{"i":35,"n":"第三十五条","txt":"督察人员在现场督察中发现非人民警察有违反《中华人民共和国人民警察法》第三十六条规定的，可以当场予以扣留，并及时移交有关部门处理。"},{"i":36,"n":"第三十六条","txt":"督察人员在现场督察中扣留的违法使用的武器、警械、警用车辆和警用标志，应当分别填写现场处置记录和统一印制的扣留凭证。"},{"i":37,"n":"第三十七条","txt":"督察人员在现场督察中发现人民警察有下列行为之一的，必要时，可以带离现场： (一)正在发生的、在社会上造成恶劣影响的严重违法违纪行为； (二)拒绝、阻碍督察人员执行现场督察工作任务的。 对严重违法违纪的公安机关的人民警察，督察人员应当按照规定填写《公安督察通知书》，及时将督察情况通知违纪民警所在单位。 对不属于管辖范围的人民警察，被带离后，应当及时通知其所在单位。"},{"i":38,"n":"第三十八条","txt":"督察机构发现公安机关及其人民警察执行法律、法规不当或不履行法定职责时，应当予以纠正；对超越人民警察法定职责的行为，应当予以制止。"},{"i":39,"n":"第三十九条","txt":"对本级公安机关所属单位和下级公安机关拒不执行法律、法规和上级决定、命令的，督察机构可以责令执行。"},{"i":40,"n":"第四十条","txt":"督察机构发现本级公安机关的决定和命令与上级公安机关不相符的，应当及时向本级公安机关行政首长提出，同时报告上级公安机关督察机构。"},{"i":41,"n":"第四十一条","txt":"上级督察机构发现下级督察机构对督察事项处理不适当的，可以提出重新处理的建议。必要时，可以责令下级督察机构停止执行，并予以撤销或者变更。"},{"i":42,"n":"第四十二条","txt":"督察机构对违反纪律的公安机关的人民警察需要采取停止执行职务、禁闭措施的，按照《公安机关实施停止执行职务和禁闭措施的规定》办理。"},{"i":43,"n":"第四十三条","txt":"督察机构在督察工作中发现公安机关的人民警违反纪律，认为需要给予行政处分或者降低警衔、取消警衔的，可以向有关部门提出建议。"},{"i":44,"n":"第四十四条","txt":"督察机构在督察工作中发现公安机关的人民警察涉嫌犯罪的，移交司法机关依法处理。"},{"i":45,"n":"第四十五条","txt":"督察机构在现场督察中遇到公安机关及其人民警察违法违纪或失职行为的重大情况，应当立即报告。对需要采取紧急措施的案件、事件和事故，应当进行先期处置。 对需要查处的案件、事件和事故，应当及时移交公安机关主管部门处理。"},{"i":46,"n":"第四十六条","txt":"公安机关及其人民警察对督察机构作出的督察决定或提出的督察建议，应当在规定的时间内以书面形式向督察机构反馈落实情况。"},{"i":47,"n":"第四十七条","txt":"公安机关及其人民警察对督察机构作出的决定不服的，可在接到督察决定书之日起三日内提出申请，督察机构应当在十日内作出复核决定。 对复核决定仍不服的，可以在收到复核决定书之日起五日内向上一级公安机关督察机构提出申诉，上级督察机构应当在一个月内予以答复。 申请、申诉期间督察决定不停止执行。但是经过上级督察机构复核认为原督察决定确属不当或错误的，作出督察决定的机构应当立即变更或撤销，并在适当范围内消除影响。"},{"i":48,"n":"第四十八条","txt":"公安机关及其人民警察违反本办法，有下列行为之一的，追究单位或者个人的纪律责任： (一)拒绝督察机构及其督察人员依法进行督察的； (二)隐瞒事实真相，伪造或者隐匿、毁灭证据的； (三)包庇违法违纪人员的； (四)拒不执行督察决定、命令或者无正当理由拒不采纳督察建议的； (五)打击、报复检举、控告人和督察人员的； (六)其他妨碍督察工作正常进行的。"},{"i":49,"n":"第四十九条","txt":"各级公安机关必须保障督察工作所必需的经费，配备必要的交通、通讯工具及其他设备。"},{"i":50,"n":"第五十条","txt":"铁道部、交通部、民航总局公安局、国家林业局森林公安局和海关总署走私犯罪侦查局建立督察机构，负责本系统的警务督察工作。 公安部直属的出入境边防检查总站建立督察机构，负责本单位及其各分站的警务督察工作。"},{"i":51,"n":"第五十一条","txt":"公安边防、消防和警卫部队除执行《中国人民解放军军警备条令》的有关规定外，其警务督察工作依照本实施办法由公安部督察委员会统一领导。"},{"i":52,"n":"第五十二条","txt":"各省、自治区、直辖市公安厅、局督察机构负责管辖范围内的公安边防、消防、警卫部队的警务督察工作，并结合本地实际情况，制定具体实施办法。"},{"i":53,"n":"第五十三条","txt":"本实施办法自发布之日起施行。"}],"gonganjiguanweihuminjingzhifaquanweigongzuoguiding":[{"i":1,"n":"第一条","txt":"为保障公安民警依法履行职责、行使职权，维护国家法律尊严和民警执法权威，依据《中华人民共和国人民警察法》《公安机关督察条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关及其民警应当严格依法履行职责、行使职权，树立严格规范公正文明的执法形象，提升执法公信力和执法权威。"},{"i":3,"n":"第三条","txt":"公安民警依法履行职责、行使职权受法律保护，不受妨害、阻碍，民警及其近亲属的人身财产安全不因民警依法履行职责、行使职权行为受到威胁、侵犯，民警及其近亲属的人格尊严不因民警依法履行职责、行使职权行为受到侮辱、贬损。"},{"i":4,"n":"第四条","txt":"县级以上人民政府公安机关应当成立由督察长为主任，警务督察和法制、警令指挥、警务保障、政工人事、教育训练、新闻宣传及执法办案等部门为成员的维护民警执法权威工作委员会。 维护民警执法权威工作委员会办公室设在警务督察部门，具体负责协调督办侵犯民警执法权威案件，受理调查相关民警的申请申诉，为受到侵犯的民警提供救济、恢复名誉、挽回损失。"},{"i":5,"n":"第五条","txt":"公安机关应当与检察机关、审判机关、宣传部门等建立维护民警执法权威工作协调联动机制，加强工作沟通与协作。"},{"i":6,"n":"第六条","txt":"公安机关可以通过聘请法律顾问、专职律师等形式，为民警依法履行职责、行使职权提供法律服务，强化维护民警执法权威工作法律保障。"},{"i":7,"n":"第七条","txt":"公安机关应当建立完善维护民警执法权威新闻发布机制，由警务督察部门会同新闻宣传、法制等部门及时发布相关信息，回应社会关切，加强普法教育。"},{"i":8,"n":"第八条","txt":"民警在依法履行职责、行使职权过程中或者因依法履行职责、行使职权遇到以下情形的，公安机关应当积极维护民警执法权威： （一）受到暴力袭击的； （二）被车辆冲撞、碾轧、拖拽、剐蹭的； （三）被聚众哄闹、围堵拦截、冲击、阻碍的； （四）受到扣押、撕咬、拉扯、推搡等侵害的； （五）本人及其近亲属受到威胁、恐吓、侮辱、诽谤、骚扰的； （六）本人及其近亲属受到诬告陷害、打击报复的； （七）被恶意投诉、炒作的； （八）本人及其近亲属个人隐私被侵犯的； （九）被错误追究责任或者受到不公正处分、处理的； （十）执法权威受到侵犯的其他情形。"},{"i":9,"n":"第九条","txt":"行为人实施侵犯民警执法权威的行为，构成犯罪的，依法追究刑事责任；尚不构成犯罪，构成违反治安管理行为的，依法给予治安管理处罚。 民警由于行为人的行为遭受人身或者财产损失的，公安机关应当支持民警通过提起刑事附带民事诉讼或者民事诉讼等法律途径，维护自身合法权益。 公安机关办理侵犯民警执法权威的刑事案件、治安案件，适用《刑事诉讼法》《治安管理处罚法》《人民警察法》关于回避的规定。"},{"i":10,"n":"第十条","txt":"民警因依法履行职责、行使职权，本人或者其近亲属遭遇恐吓威胁、滋事骚扰、尾随跟踪，或者人身、财产受到侵害的，民警所在公安机关和有管辖权的公安机关应当及时采取保护措施，依法追究行为人的法律责任。"},{"i":11,"n":"第十一条","txt":"民警在执法执勤现场受到不法侵害的，民警及其所在部门应当依法采取措施制止侵害并立即向所属公安机关指挥部门报告。公安机关指挥部门应当迅速组织力量进行处置，同时通报警务督察部门。警务督察部门视情派员赴现场初步查明情况，协助控制事态，督促依法处置。"},{"i":12,"n":"第十二条","txt":"公安机关应当协调医疗卫生机构建立民警因公负伤紧急救治畅通机制，为负伤民警提供及时、有效的医疗救治。"},{"i":13,"n":"第十三条","txt":"公安机关办理侵犯民警执法权威的刑事案件、治安案件时，法制部门应当根据情况的复杂程度、造成后果的严重程度，视情提前介入，加强审核把关，对案件定性、取证、处理等进行指导，确保案件办理事实清楚、证据确凿、程序合法、法律适用准确。"},{"i":14,"n":"第十四条","txt":"民警按照法定条件和程序履行职责、行使职权，对公民、法人或者其他组织合法权益造成损害的，民警个人不承担法律责任，由其所属公安机关按照国家有关规定对造成的损害给予补偿。"},{"i":15,"n":"第十五条","txt":"公安机关应当严格依法依规开展执法过错责任追究工作。非因法定事由、非经法定程序，不得对民警采取停止执行职务、禁闭等措施，不得作出处分或者免职、降职、辞退等处理。 公安机关不应当受舆论炒作、信访投诉等人为因素影响，不当或者变相追究民警责任，加重对民警的处分、处理。"},{"i":16,"n":"第十六条","txt":"公安机关应当根据行为事实、情节、后果，综合考虑主客观因素，客观评价民警行为性质，区分执法过错、瑕疵、意外，依法依规作出责任认定。 对于民警依法履职尽责，受主观认知、客观条件、外来因素影响造成一定损失和负面影响的行为或者出现的失误，以及民警非因故意违法违规履职，及时发现并主动纠正错误，积极采取措施避免或者减轻危害后果与影响的，公安机关应当从轻、减轻或免于追究民警的责任，或者向检察机关、审判机关提出从轻、减轻或者免于追究民警刑事责任的建议。"},{"i":17,"n":"第十七条","txt":"对于民警行为是否属于依法履行职责、行使职权行为，以及执法是否存在过错等问题存在较大争议的，公安机关维护民警执法权威工作委员会应当组织相关专业人员成立专家组进行审查，出具书面论证意见，作为公安机关内部责任认定的重要参考依据。纪检监察机关、检察机关介入调查的，公安机关应当及时提供论证意见，加强沟通。"},{"i":18,"n":"第十八条","txt":"民警对因履行职责、行使职权行为受到记大过以上处分、辞退有异议并提出申诉的，民警所在公安机关维护民警执法权威工作委员会应当听取当事民警的陈述、申辩，对事实、理由、依据和程序进行全面复核，认为处分、处理决定不当的，应当向作出决定部门提供复核意见。不得因民警提出申诉而对其加重处分、处理，或者变相打击报复。"},{"i":19,"n":"第十九条","txt":"民警因履行职责、行使职权行为受到检察机关调查时或者其他必要情形下，公安法制部门和公安机关聘请的法律顾问、专职律师应当在职责范围内为事件的调查处理提供必要的法律配合。"},{"i":20,"n":"第二十条","txt":"民警认为因依法履行职责、行使职权受到侵害的，民警及其近亲属或者民警所在单位可以向所属公安机关警务督察部门提出维护执法权威申请，一般情况下应当通过书面形式提出，紧急情况下可以口头提出。 警务督察部门在工作中发现民警执法权威受到侵犯的情形、线索，应当主动启动相关工作程序。"},{"i":21,"n":"第二十一条","txt":"警务督察部门在办理维护民警执法权威事项过程中，认为应当由上一级公安机关警务督察部门协调处理的，可以提请上一级公安机关警务督察部门协调处理。 上一级公安机关警务督察部门可以指令下一级公安机关警务督察部门对专门事项进行调查，必要时可以直接开展调查。"},{"i":22,"n":"第二十二条","txt":"民警因依法履行职责、行使职权行为受到公安机关内部不公正处分、处理，经核查属实的，警务督察部门应当督促相关部门限期纠正。"},{"i":23,"n":"第二十三条","txt":"民警因履行职责、行使职权行为受到不实投诉、诬告诽谤、侮辱、恶意炒作，以及被错误审查调查、追究责任后，相关部门予以纠正的，警务督察部门应当通过公开的形式，在一定范围内澄清事实，消除影响。受到公安机关内部处分、处理的，公安机关应当及时撤销相关决定并恢复民警公职身份和原职务、职级。"},{"i":24,"n":"第二十四条","txt":"公安机关应当建立维护民警执法权威抚慰金制度，规范审批和管理使用。民警所属公安机关及其政工人事部门、警务督察部门负责人应当出面抚慰因依法履行职责、行使职权受到侵害的民警。"},{"i":25,"n":"第二十五条","txt":"公安机关应当聘请专业人员，在必要时对因依法履行职责、行使职权受到侵害的民警及其近亲属开展心理干预和治疗，缓解和疏导心理压力、负担。"},{"i":26,"n":"第二十六条","txt":"公安机关应当经常开展常用法律法规培训和安全防护理念教育，加强民警基础体能、基本技能、常见警情处置、现场警务指挥等警务技战术训练，规范现场执法执勤行为，提升安全防护能力和现场处置水平。"},{"i":27,"n":"第二十七条","txt":"公安机关应当加强对侵犯民警执法权威行为规律特点的分析研究，评估执法风险，加强安全指引和预警防范。"},{"i":28,"n":"第二十八条","txt":"有下列行为之一的，依照有关规定追究相关领导和责任人的责任： （一）因制度不落实、保障不到位、指挥错误导致民警执法权威受到侵犯的； （二）不按要求向上级公安机关报告有关情况的； （三）不及时采取善后救助措施的； （四）阻碍、干扰侵犯民警执法权威案件办理的； （五）因工作不力、推诿拖延对侵犯民警执法权威案件办理造成严重影响的； （六）违法违规不处理、降格处理侵犯民警执法权威行为人的。"},{"i":29,"n":"第二十九条","txt":"公安民警在非工作时间，遇到职责范围内的紧急情形，表明身份后，根据现场情况进行先期处置过程中，受到不法侵害的，公安机关依照本规定维护其执法权威。"},{"i":30,"n":"第三十条","txt":"本规定所称“近亲属”是指夫、妻、父、母、子、女、同胞兄弟姊妹。"},{"i":31,"n":"第三十一条","txt":"警务辅助人员在协助民警依法履行职责、行使职权过程中受到不法侵害的，参照本规定开展相关工作。"},{"i":32,"n":"第三十二条","txt":"各省、自治区、直辖市公安厅、局，新疆生产建设兵团公安局，各行业公安局，根据本规定制定实施办法。"},{"i":33,"n":"第三十三条","txt":"本规定自2019年2月1日起施行。本规定发布前公安部制定的有关规定与本规定不一致的，以本规定为准。"}],"gonganjiguanxingzhengxukegongzuoguiding":[{"i":1,"n":"第一条","txt":"为了贯彻实施《中华人民共和国行政许可法》（以下简称《行政许可法》），规范公安行政许可工作，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关实施行政许可及其监督管理，适用本规定。法律、法规授权实施行政许可的公安机关内设机构，适用本规定有关公安机关的规定。"},{"i":3,"n":"第三条","txt":"公安机关实施行政许可，应当遵循合法、公开、公平、公正、便民、高效等原则。"},{"i":4,"n":"第四条","txt":"公安机关依照《行政许可法》第三十条规定进行公示可以采取设置公告栏、触摸屏或者查阅本等方式进行。已经建立公共信息网站的公安机关还应当将该条规定的公示内容以及受理机关的地址、咨询电话在网站上公示。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织依法需要取得公安行政许可的，应当向公安机关提出申请。 申请人可以委托代理人提出行政许可申请，也可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出行政许可申请，但是依法应当由申请人到公安机关办公场所当面提出行政许可申请的除外。 对申请人委托代理人提出行政许可申请的，公安机关应当要求当事人出具授权委托书或者在申请表上委托栏中载明委托人和代理人的简要情况，并签名或者盖章，出示委托人身份证件。"},{"i":6,"n":"第六条","txt":"公安机关应当在办公场所便于公众知晓的位置公布受理行政许可的内设机构名称、地址、联系电话。 办公场所分散、行政许可工作量大的公安机关可以设立统一对外、集中受理公安行政许可申请的场所。"},{"i":7,"n":"第七条","txt":"同一行政许可需要公安机关多个内设机构办理的，由最先收到申请的机构或者本机关指定的机构统一受理，并负责统一送达行政许可决定。 接到申请的机构应当将行政许可申请转告有关机构分别提出意见后统一办理，或者组织有关机构联合办理。"},{"i":8,"n":"第八条","txt":"设区的市级以上公安机关可以将自己负责实施的行政许可，委托县、区公安机关受理。"},{"i":9,"n":"第九条","txt":"申请材料有更正痕迹的，受理机关应当要求申请人在更正处签名、盖章或者捺指印确认。"},{"i":10,"n":"第十条","txt":"受理机关接到行政许可申请后，应当就下列事项进行初步审查： （一）申请事项是否属于依法需要取得行政许可的事项； （二）申请事项是否属于本机关管辖； （三）申请材料是否齐全和符合法定形式，内容填写是否正确。"},{"i":11,"n":"第十一条","txt":"受理机关对申请人提出的行政许可申请，经初步审查，按照下列情形分别作出处理： （一）依法不需要取得行政许可的，应当即时口头告知申请人不予受理，并说明理由；申请人要求书面决定的，公安机关应当出具不予受理决定书； （二）申请事项依法不属于本机关职权范围的，应当口头告知申请人向有关行政机关申请；申请人要求书面决定的，公安机关应当出具不予受理决定书； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正，并由申请人签字或者捺指印确认； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容；逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于本机关职权范围，申请材料齐全、符合法定形式，或者申请人按照本机关的要求提交全部补正申请材料的，应当受理行政许可申请。"},{"i":12,"n":"第十二条","txt":"对申请人通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出申请的，公安机关应当自收到申请材料之日起五日内按照第十一条的规定分别情形作出处理，并通知申请人。逾期未通知的，视为受理。但因为申请人原因无法通知的除外。"},{"i":13,"n":"第十三条","txt":"公安机关受理行政许可申请的，应当出具受理行政许可申请凭证。受理凭证应当注明申请事项和办理时限、联系人、咨询电话和收到的申请材料的目录，加盖本机关专用章，并注明受理日期。公安机关当场作出行政许可决定的，无需出具受理凭证。 公安机关依据本规定第十一条第（一）项和第（二）项出具的不予受理行政许可申请决定书应当写明理由，告知申请人有申请行政复议或者提起行政诉讼的权利，加盖本机关专用章，并注明日期。"},{"i":14,"n":"第十四条","txt":"公安机关受理行政许可申请后，除依法可以当场作出许可决定外，应当指定工作人员负责对申请材料进行审查。审查人员审查后应当提出明确的书面审查意见并签名。"},{"i":15,"n":"第十五条","txt":"根据法定条件和程序，需要对申请材料的实质内容进行核实的，公安机关应当指派工作人员进行核查。 核查可以采取实地或者实物查看、检验、检测以及询问、调查等方式进行。核查应当制作核查记录，全面、客观地记载核查情况。核查记录应当由核查人员和被核查方签字确认。"},{"i":16,"n":"第十六条","txt":"公安机关在审查行政许可申请时，涉及专业知识或者技术问题的，可以委托专业机构或者专家进行评审，由专业机构或者专家出具评审意见，也可以召开专家评审会。 公安机关不得事先公开专家名单。专家评审会不公开举行，申请人不得参加专家评审会。 公安机关作出最终决定时应当参考专业机构或者专家评审意见。"},{"i":17,"n":"第十七条","txt":"公安机关对行政许可申请进行审查时，发现行政许可事项直接关系他人重大利益或者直接涉及申请人与他人之间重大利益关系的，应当告知利害关系人行政许可事项，并告知申请人、利害关系人有权进行陈述、申辩和要求听证。 对申请人或者利害关系人的陈述和申辩，公安机关应当记录在案，并纳入行政许可审查范围。 申请人或者利害关系人要求听证的，应当在被告知听证权利之日起五日内提出听证申请。公安机关应当在申请人或者利害关系人提出听证申请之日起二十日内组织听证。"},{"i":18,"n":"第十八条","txt":"法律、法规、规章规定实施行政许可应当举行听证的事项，或者公安机关认为需要听证的其他涉及公共安全等公共利益的重大行政许可事项，公安机关应当向社会公告，公告期为十日，并在公告期满后二十日内举行听证，公告期不计入公安机关办理行政许可的期限。 公民、法人或者其他组织在公告期内报名参加听证的，公安机关应当登记。公告期内无人报名参加听证的，公安机关应当在案卷中载明，不再举行听证。报名人数过多难以组织安排的，公安机关可从报名者中采取随机方式确定五至十人参加听证。"},{"i":19,"n":"第十九条","txt":"行政许可听证由负责审查该行政许可申请的工作人员以外的人员担任听证主持人。 申请人、利害关系人不承担组织听证的费用。 经过听证的行政许可，公安机关应当根据听证笔录，作出行政许可决定；未经听证的证据，不得作为行政许可决定的根据。"},{"i":20,"n":"第二十条","txt":"公安机关作出行政许可决定应当经公安机关负责人或者其授权的工作人员批准。"},{"i":21,"n":"第二十一条","txt":"公安机关拟作出的行政许可决定对申请人申请的行政许可范围、数量、期限、内容等事项有重大改变的，应当事先告知申请人，征得其同意，并在申请材料上注明。申请人不同意的，依法作出不予许可的决定。"},{"i":22,"n":"第二十二条","txt":"公安机关办理行政许可，必须遵循《行政许可法》规定的期限。法律、法规另有规定的，依照其规定。 依法应当先经下级公安机关审查后报上级公安机关决定的行政许可，下级公安机关应当自其受理行政许可申请之日起二十日内审查完毕，并将审查意见和全部申请材料报送上级公安机关，上级公安机关应当自收到下级公安机关报送的审查意见和申请材料之日起二十日内作出决定。"},{"i":23,"n":"第二十三条","txt":"公安机关依法收取行政许可费用，必须向交费人开具财政部门统一制发的票据。"},{"i":24,"n":"第二十四条","txt":"被许可人申请变更行政许可事项的，按照行政许可申请程序和期限办理。"},{"i":25,"n":"第二十五条","txt":"公安机关应当按照《行政许可法》第六章的规定加强对被许可人从事行政许可事项活动的监督检查。"},{"i":26,"n":"第二十六条","txt":"监督检查可以采取下列方式： （一）  实地检查； （二）  抽样检查、检验、检测； （三）  查阅从事行政许可事项活动的相关资料； （四）  其他法律、法规、规章规定的监督检查方式。"},{"i":27,"n":"第二十七条","txt":"公安机关监督检查人员公开对被许可事项进行监督检查时，应当向被许可人出示执法身份证件。对公共场所监督检查时，可以采用暗查方式。"},{"i":28,"n":"第二十八条","txt":"对直接关系公共安全、人身健康、生命财产安全的重要设备、设施，公安机关应当在其职责范围内依法督促设计、建造、安装和使用单位建立健全相应的自检制度。"},{"i":29,"n":"第二十九条","txt":"公安机关监督检查人员在监督检查时，发现直接关系公共安全、人身健康、生命财产安全的重要设备、设施存在安全隐患，能够当场改正的，应当责令设备、设施所属单位当场改正；不能当场改正，无法保证安全的，应当当场口头或者书面责令暂时停止建造、安装或者使用，并在二十四小时内向所属公安机关报告。公安机关应当在接到报告后二日内向建造、安装或者使用单位送达正式处理决定书，责令其限期整改。对属于其他行政机关管辖的，应当及时通知其他行政机关。 被许可单位存在安全隐患，拒不整改的，公安机关应当依法予以处罚或者采取强制措施督促其整改，并可以向社会公布其安全隐患情况，在隐患单位挂牌警示。"},{"i":30,"n":"第三十条","txt":"公安机关应当建立健全被许可人档案。 公安机关对被许可人的监督检查情况和处理结果，应当予以记录，并由监督检查人员签字后归档，保留期限为两年，法律、法规和其他规章另有规定的除外。"},{"i":31,"n":"第三十一条","txt":"被许可活动属于生产经营活动或者直接涉及公众利益的，公安机关可以公布对被许可人的监督检查情况和处理结果以及对被许可人从事许可活动的评价意见。 被许可活动涉及公共安全的，公安机关可以建立被许可单位的公共安全等级评定制度，并向社会公布被许可单位的公共安全等级。"},{"i":32,"n":"第三十二条","txt":"公安机关依照《行政许可法》第六十九条规定撤销行政许可时，应当作出书面决定，并告知被许可人撤销行政许可的法律依据和事实基础，同时责令当事人自行政许可撤销之日起停止从事行政许可事项活动。撤销行政许可应当收回许可证件。当事人拒绝交回的，公安机关应当予以注销，并予公告。"},{"i":33,"n":"第三十三条","txt":"公安机关鼓励个人和组织参与对行政许可事项活动的监督。 个人或者组织向公安机关举报违法从事行政许可事项活动，经查证属实的，公安机关可以给予适当奖励。"},{"i":34,"n":"第三十四条","txt":"对利害关系人根据《行政许可法》第六十九条规定提出的撤销行政许可请求，公安机关应当进行调查，并自收到撤销行政许可请求之日起一个月内作出处理决定，告知利害关系人。情况复杂，不能在规定期限内调查清楚，作出处理决定的，经公安机关负责人批准，可以延长时限。延长时限不超过一个月。 对在法定复议期限内向上一级公安机关提出撤销行政许可请求的，按照行政复议程序处理。"},{"i":35,"n":"第三十五条","txt":"公安机关依法变更或者撤回已经生效的行政许可，应当事前告知被许可人或者向社会公告，并说明理由。"},{"i":36,"n":"第三十六条","txt":"公民依法要求查阅行政许可决定或者监督检查记录的，应当出示身份证明。公安机关不能安排当时查阅的，应当向申请人作出解释，并在五日内安排查阅。 查阅人要求复制有关资料的，应当允许。复制费用由查阅人负担。 涉及国家秘密、商业秘密或者个人隐私的许可资料，不予公开。"},{"i":37,"n":"第三十七条","txt":"上级公安机关及其业务部门应当加强对下级公安机关及其业务部门实施行政许可的监督检查，并将其纳入执法质量考评范围，及时纠正行政许可实施中的违法行为。 公安机关警务督察部门应当加强对行政许可工作的现场督察。"},{"i":38,"n":"第三十八条","txt":"公安机关应当建立健全实施行政许可的举报和投诉制度，公布投诉电话或者信箱。对公民、法人或者其他组织的举报或者投诉，应当及时查处。"},{"i":39,"n":"第三十九条","txt":"公安机关从事行政许可工作的人员具有下列情形之一的，依法给予行政处分，并可以视情调离行政许可工作岗位；构成犯罪的，依法追究刑事责任： （一）索取或者收受他人财物或者其他利益的； （二）玩忽职守或者滥用职权的； （三）一年内受到二次以上投诉，且投诉属实，情节严重、影响恶劣的； （四）其他违法违纪情形。"},{"i":40,"n":"第四十条","txt":"公安机关从事行政许可的工作人员在实施行政许可工作中有执法过错的，按照《公安机关人民警察执法过错责任追究规定》追究责任；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"公安机关办理非行政许可审批项目，参照本规定执行。"},{"i":42,"n":"第四十二条","txt":"公安部其他规章对实施某项行政许可有特别规定的，依照特别规定执行。"},{"i":43,"n":"第四十三条","txt":"本规定自2005年12月1日起实行。"}],"gonganjiguanjingwuduchaduigongzuoguiding":[{"i":1,"n":"第一条","txt":"为了保障公安机关警务督察队依法履行职责、行使职权和遵守纪律，根据《公安机关督察条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上地方各级人民政府公安机关警务督察队在本级公安机关督察机构的领导下开展工作，向督察长负责。"},{"i":3,"n":"第三条","txt":"警务督察队在本级公安机关辖区内，对公安机关及其人民警察执法执勤活动的下列情况进行现场督察： （一）上级和本级公安机关各项警务部署、命令、规定执行的情况； （二）文明执勤、文明执法和遵守警容风纪规定的情况； （三）处置公民报警、求助和控告申诉的情况； （四）违反规定进入宾馆、旅店、歌舞厅等公共场所的情况； （五）使用武器、警械、警用车辆、警用标志等装备的情况； （六）《公安机关督察条例》规定的其他职责； （七）公安机关行政首长和上级督察机构交办的其他督察事项。"},{"i":4,"n":"第四条","txt":"警务督察队执行督察任务时，不得少于二人，采取着装督察或者便衣督察的方式。 督察人员在着装执行任务时，必须佩戴督察标志；必要时，出示督察证件；在着便衣执行任务过程中，需要当场纠正人民警察违纪行为时，必须出示督察证件。"},{"i":5,"n":"第五条","txt":"警务督察队执行督察任务时，发现人民警察违反警容风纪规定的，应当当场予以纠正。"},{"i":6,"n":"第六条","txt":"警务督察队对有违法违纪或者阻碍督察人员行使职权行为的人民警察，可以将其带离现场。"},{"i":7,"n":"第七条","txt":"警务督察队对人民警察违反法律规定携带、使用武器、警械以及警用车辆、警用标志的，应当予以制止或者纠正；必要时可以扣留，并移交公安机关主管部门处理。"},{"i":8,"n":"第八条","txt":"警务督察队对人民警察情节轻微的违纪行为，应当进行批评教育；必要时，应当书面通知其所在单位。 警务督察队对人民警察严重违法违纪行为，应当按照督察机构管辖权限处理或者移交公安机关主管部门处理。 公安机关主管部门对警务督察队移交处理的事项，应当及时处理并将处理情况通知警务督察队。"},{"i":9,"n":"第九条","txt":"警务督察队对现场督察的情况，应当如实记录，向督察长报告；对重要事项的督察情况，必须向同级公安机关行政首长和上级督察机构报告。"},{"i":10,"n":"第十条","txt":"警务督察队发现公安机关或者人民警察执行超越法律、法规规定的人民警察职责范围的指令时，应当予以制止，并向督察长和上级督察机构报告。"},{"i":11,"n":"第十一条","txt":"警务督察队对现场督察的情况需要通报有关部门的，可以使用《督察通知书》。"},{"i":12,"n":"第十二条","txt":"警务督察队在执行督察任务时，遇有公民非法携带、使用武器和警械或者非法使用警用车辆、警用标志、证件和穿着人民警察制式服装的，应当当场予以收缴，必要时移送公安机关主管部门处理。"},{"i":13,"n":"第十三条","txt":"警务督察队在执行督察任务时，遇有公民对公安机关人民警察检举、控告的，应当予以受理；对不属于督察机构职责范围的，在受理后应当及时移送公安机关主管部门。"},{"i":14,"n":"第十四条","txt":"警务督察队应当支持公安机关及其人民警察依法履行职责和行使职权，保护公安机关及其人民警察的合法权益。"},{"i":15,"n":"第十五条","txt":"公安机关及其人民警察应当支持督察人员依法履行职责、行使职权。人民警察在接受督察时，应当如实回答督察人员的询问。"},{"i":16,"n":"第十六条","txt":"警务督察队执行督察任务，必须自觉接受社会、公民和人民警察的监督。 公民或者人民警察发现督察人员在执行任务时有违法违纪行为的，有权检举和控告。"},{"i":17,"n":"第十七条","txt":"督察人员必须做到： （一）模范遵守国家法律、法规和人民警察的各项纪律； （二）服从命令，听从指挥，接受监督，不得滥用和超越职权； （三）严格执法，文明执勤，清正廉洁，不徇私情； （四）热情服务，语言文明，礼貌待人； （五）警容严整，着装规范，举止端庄。"},{"i":18,"n":"第十八条","txt":"各省、自治区、直辖市公安厅、局可以根据本规定制定具体实施办法。"},{"i":19,"n":"第十九条","txt":"本规定自公布之日起实施。"}],"gonganjiguanjingjiedaishiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范警戒带的使用和管理，保障公安机关依法有效履行职责，维护社会治安秩序，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称警戒带，是指公安机关按照规定装备，用于依法履行职责在特定场所设置禁止进入范围的专用标志物。"},{"i":3,"n":"第三条","txt":"公安机关及其人民警察在特定场所履行职责时，应当根据本办法的规定使用警戒带。其他任何单位和个人不得使用警戒带，但法律、法规另有规定的除外。"},{"i":4,"n":"第四条","txt":"公安机关使用警戒带，应当以既有利于履行职责，又有利于公民、单位的正常活动为原则。夜间使用警戒带应当配置警示灯或照明灯。使用警戒带的情形消失时，应当立即停止使用和拆除。"},{"i":5,"n":"第五条","txt":"公安机关及其人民警察履行职责时，可以根据现场需要经公安机关现场负责人批准，在下列场所使用警戒带： （一）警卫工作需要； （二）集会、游行、示威活动的场所； （三）治安事件的现场； （四）刑事案件的现场； （五）交通事故或交通管制的现场； （六）灾害事故的现场； （七）爆破或危险品实（试）验的现场； （八）重大的文体、商贸等活动的现场； （九）其他需要使用警戒带的场所。"},{"i":6,"n":"第六条","txt":"公安机关及其人民警察依法使用警戒带的行为，受法律保护。任何单位和个人不得阻碍、干扰公安机关及其人民警察依法使用警戒带。"},{"i":7,"n":"第七条","txt":"公安机关及其人民警察在使用警戒带设置警戒区时，在场人员应当服从人民警察的指令，无关人员应当及时退出警戒区；未经允许任何人不得跨越警戒带、进入警戒区。"},{"i":8,"n":"第八条","txt":"公安机关及其人民警察违反本规定使用警戒带造成严重后果的，依照有关法律和规定追究主管领导和直接责任人的法律、行政责任。"},{"i":9,"n":"第九条","txt":"对破坏、冲闯警戒带或擅自进入警戒区的，经警告无效，可以强制带离现场，并可依照《中华人民共和国治安管理处罚条例》的规定予以处罚。构成犯罪的，依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"对非法制造、贩卖、使用警戒带的，依照《中华人民共和国人民警察法》第三十六条的规定处罚。"},{"i":11,"n":"第十一条","txt":"县以上公安机关依照《中华人民共和国人民警察法》第三十六条的规定负责警戒带的使用管理工作。 警戒带的技术标准由公安部制定。"},{"i":12,"n":"第十二条","txt":"本办法自公布之日起实施。"}],"gonganjiguanshiyongjixupanwenguiding":[{"i":1,"n":"第一条","txt":"为了规范继续盘问工作，保证公安机关依法履行职责和行使权限，维护社会治安秩序，保护公民的合法权益，根据《中华人民共和国人民警察法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称继续盘问，是指公安机关的人民警察为了维护社会治安秩序，对有违法犯罪嫌疑的人员当场盘问、检查后，发现具有法定情形而将其带至公安机关继续进行盘问的措施。"},{"i":3,"n":"第三条","txt":"公安机关适用继续盘问，应当遵循依法、公正、及时、文明和确保安全的原则，做到适用对象准确、程序合法、处理适当。"},{"i":4,"n":"第四条","txt":"继续盘问工作由公安机关主管公安派出所工作的部门负责业务指导和归口管理。"},{"i":5,"n":"第五条","txt":"继续盘问工作由人民警察执行。严禁不具有人民警察身份的人员从事有关继续盘问的执法工作。"},{"i":6,"n":"第六条","txt":"公安机关适用继续盘问，依法接受人民检察院、行政监察机关以及社会和公民的监督。"},{"i":7,"n":"第七条","txt":"为维护社会治安秩序，公安机关的人民警察对有违法犯罪嫌疑的人员，经表明执法身份后，可以当场盘问、检查。 未穿着制式服装的人民警察在当场盘问、检查前，必须出示执法证件表明人民警察身份。"},{"i":8,"n":"第八条","txt":"对有违法犯罪嫌疑的人员当场盘问、检查后，不能排除其违法犯罪嫌疑，且具有下列情形之一的，人民警察可以将其带至公安机关继续盘问： （一）被害人、证人控告或者指认其有犯罪行为的； （二）有正在实施违反治安管理或者犯罪行为嫌疑的； （三）有违反治安管理或者犯罪嫌疑且身份不明的； （四）携带的物品可能是违反治安管理或者犯罪的赃物的。"},{"i":9,"n":"第九条","txt":"对具有下列情形之一的人员，不得适用继续盘问： （一）有违反治安管理或者犯罪嫌疑，但未经当场盘问、检查的； （二）经过当场盘问、检查，已经排除违反治安管理和犯罪嫌疑的； （三）涉嫌违反治安管理行为的法定最高处罚为警告、罚款或者其他非限制人身自由的行政处罚的； （四）从其住处、工作地点抓获以及其他应当依法直接适用传唤或者拘传的； （五）已经到公安机关投案自首的； （六）明知其所涉案件已经作为治安案件受理或者已经立为刑事案件的； （七）不属于公安机关管辖的案件或者事件当事人的； （八）患有精神病、急性传染病或者其他严重疾病的; （九）其他不符合本规定第八条所列条件的。"},{"i":10,"n":"第十条","txt":"对符合本规定第八条所列条件，同时具有下列情形之一的人员，可以适用继续盘问，但必须在带至公安机关之时起的四小时以内盘问完毕，且不得送入候问室： （一）怀孕或者正在哺乳自己不满一周岁婴儿的妇女； （二）不满十六周岁的未成年人； （三）已满七十周岁的老年人。 对前款规定的人员在晚上九点至次日早上七点之间释放的，应当通知其家属或者监护人领回；对身份不明或者没有家属和监护人而无法通知的，应当护送至其住地。"},{"i":11,"n":"第十一条","txt":"继续盘问的时限一般为十二小时；对在十二小时以内确实难以证实或者排除其违法犯罪嫌疑的，可以延长至二十四小时；对不讲真实姓名、住址、身份，且在二十四小时以内仍不能证实或者排除其违法犯罪嫌疑的，可以延长至四十八小时。 前款规定的时限自有违法犯罪嫌疑的人员被带至公安机关之时起，至被盘问人可以自由离开公安机关之时或者被决定刑事拘留、逮捕、行政拘留、强制戒毒而移交有关监管场所执行之时止，包括呈报和审批继续盘问、延长继续盘问时限、处理决定的时间。"},{"i":12,"n":"第十二条","txt":"公安机关应当严格依照本规定的适用范围和时限适用继续盘问，禁止实施下列行为： （一）超适用范围继续盘问； （二）超时限继续盘问； （三）适用继续盘问不履行审批、登记手续； （四）以继续盘问代替处罚； （五）将继续盘问作为催要罚款、收费的手段； （六）批准继续盘问后不立即对有违法犯罪嫌疑的人员继续进行盘问； （七）以连续继续盘问的方式变相拘禁他人。"},{"i":13,"n":"第十三条","txt":"公安派出所的人民警察对符合本规定第八条所列条件，确有必要继续盘问的有违法犯罪嫌疑的人员，可以立即带回，并制作《当场盘问、检查笔录》、填写《继续盘问审批表》报公安派出所负责人审批决定继续盘问十二小时。对批准继续盘问的，应当将《继续盘问审批表》复印、传真或者通过计算机网络报所属县、市、旗公安局或者城市公安分局主管公安派出所工作的部门备案。 县、市、旗公安局或者城市公安分局其他办案部门和设区的市级以上公安机关及其内设机构的人民警察对有违法犯罪嫌疑的人员，应当依法直接适用传唤、拘传、刑事拘留、逮捕、取保候审或者监视居住，不得适用继续盘问；对符合本规定第八条所列条件，确有必要继续盘问的有违法犯罪嫌疑的人员，可以带至就近的公安派出所，按照本规定适用继续盘问。"},{"i":14,"n":"第十四条","txt":"对有违法犯罪嫌疑的人员批准继续盘问的，公安派出所应当填写《继续盘问通知书》，送达被盘问人，并立即通知其家属或者单位；未批准继续盘问的，应当立即释放。 对被盘问人身份不明或者没有家属和单位而无法通知的，应当在《继续盘问通知书》上注明，并由被盘问人签名或者捺指印。但是，对因身份不明而无法通知的，在继续盘问期间查明身份后，应当依照前款的规定通知其家属或者单位。"},{"i":15,"n":"第十五条","txt":"被盘问人的家属为老年人、残疾人、精神病人、不满十六周岁的未成年人或者其他没有独立生活能力的人,因公安机关实施继续盘问而使被盘问人的家属无人照顾的,公安机关应当通知其亲友予以照顾或者采取其他适当办法妥善安排,并将安排情况及时告知被盘问人。"},{"i":16,"n":"第十六条","txt":"对有违法犯罪嫌疑的人员批准继续盘问后，应当立即结合当场盘问、检查的情况继续对其进行盘问，以证实或者排除其违法犯罪嫌疑。 对继续盘问的情况，应当制作《继续盘问笔录》，并载明被盘问人被带至公安机关的具体时间，由被盘问人核对无误后签名或者捺指印。对被盘问人拒绝签名和捺指印的，应当在笔录上注明。"},{"i":17,"n":"第十七条","txt":"对符合本规定第十一条所列条件，确有必要将继续盘问时限延长至二十四小时的，公安派出所应当填写《延长继续盘问时限审批表》，报县、市、旗公安局或者城市公安分局的值班负责人审批；确有必要将继续盘问时限从二十四小时延长至四十八小时的，公安派出所应当填写《延长继续盘问时限审批表》，报县、市、旗公安局或者城市公安分局的主管负责人审批。 县、市、旗公安局或者城市公安分局的值班或者主管负责人应当在继续盘问时限届满前作出是否延长继续盘问时限的决定，但不得决定将继续盘问时限直接从十二小时延长至四十八小时。"},{"i":18,"n":"第十八条","txt":"除具有《中华人民共和国人民警察使用警械和武器条例》规定的情形外，对被盘问人不得使用警械或者武器。"},{"i":19,"n":"第十九条","txt":"对具有下列情形之一的，应当立即终止继续盘问，并立即释放被盘问人或者依法作出处理决定： （一）继续盘问中发现具有本规定第九条所列情形之一的； （二）已经证实有违法犯罪行为的； （三）有证据证明有犯罪嫌疑的。 对经过继续盘问已经排除违法犯罪嫌疑，或者经过批准的继续盘问、延长继续盘问时限届满，尚不能证实其违法犯罪嫌疑的，应当立即释放被盘问人。"},{"i":20,"n":"第二十条","txt":"对终止继续盘问或者释放被盘问人的，应当在《继续盘问登记表》上载明终止继续盘问或者释放的具体时间、原因和处理结果，由被盘问人核对无误后签名或者捺指印。被盘问人拒绝签名和捺指印的，应当在《继续盘问登记表》上注明。"},{"i":21,"n":"第二十一条","txt":"在继续盘问期间对被盘问人依法作出刑事拘留、逮捕或者行政拘留、强制戒毒决定的，应当立即移交有关监管场所执行；依法作出取保候审、监视居住或者警告、罚款等行政处罚决定的，应当立即释放。"},{"i":22,"n":"第二十二条","txt":"在继续盘问期间，公安机关及其人民警察应当依法保障被盘问人的合法权益，严禁实施下列行为： （一）对被盘问人进行刑讯逼供； （二）殴打、体罚、虐待、侮辱被盘问人； （三）敲诈勒索或者索取、收受贿赂； （四）侵吞、挪用、损毁被盘问人的财物； （五）违反规定收费或者实施处罚； （六）其他侵犯被盘问人合法权益的行为。"},{"i":23,"n":"第二十三条","txt":"对在继续盘问期间突患疾病或者受伤的被盘问人，公安派出所应当立即采取措施予以救治，通知其家属或者单位，并向县、市、旗公安局或者城市公安分局负责人报告，做好详细记录。对被盘问人身份不明或者没有家属和单位而无法通知的，应当在《继续盘问登记表》上注明。 救治费由被盘问人或者其家属承担。但是，由于公安机关或者他人的过错导致被盘问人患病、受伤的，救治费由有过错的一方承担。"},{"i":24,"n":"第二十四条","txt":"被盘问人在继续盘问期间死亡的，公安派出所应当做好以下工作： （一） 保护好现场，保管好尸体； （二） 立即报告所属县、市、旗公安局或者城市公安分局的主管负责人或者值班负责人、警务督察部门和主管公安派出所工作的部门； （三） 立即通知被盘问人的家属或者单位。"},{"i":25,"n":"第二十五条","txt":"县、市、旗公安局或者城市公安分局接到被盘问人死亡的报告后，应当做好以下工作： （一）立即通报同级人民检察院； （二）在二十四小时以内委托具有鉴定资格的人员进行死因鉴定； （三）在作出鉴定结论后三日以内将鉴定结论送达被盘问人的家属或者单位。对被盘问人身份不明或者没有家属和单位而无法通知的，应当在鉴定结论上注明。 被盘问人的家属或者单位对鉴定结论不服的，可以在收到鉴定结论后的七日以内向上一级公安机关申请重新鉴定。上一级公安机关接到申请后，应当在三日以内另行委托具有鉴定资格的人员进行重新鉴定。"},{"i":26,"n":"第二十六条","txt":"县、市、旗公安局或者城市公安分局经报请设区的市级以上公安机关批准，可以在符合下列条件的公安派出所设置候问室： （一）确有维护社会治安秩序的工作需要； （二）警力配置上能够保证在使用候问室时由人民警察值班、看管和巡查。 县、市、旗公安局或者城市公安分局以上公安机关及其内设机构，不得设置候问室。"},{"i":27,"n":"第二十七条","txt":"候问室的建设必须达到以下标准： （一）房屋牢固、安全、通风、透光，单间使用面积不得少于六平方米，层高不低于二点五五米； （二）室内应当配备固定的坐具，并保持清洁、卫生； （三）室内不得有可能被直接用以行凶、自杀、自伤的物品； （四）看管被盘问人的值班室与候问室相通，并采用栏杆分隔，以便于观察室内情况。 对有违法犯罪嫌疑的人员继续盘问十二小时以上的，应当为其提供必要的卧具。 候问室应当标明名称，并在明显位置公布有关继续盘问的规定、被盘问人依法享有的权利和候问室管理规定。"},{"i":28,"n":"第二十八条","txt":"候问室必须经过设区的市级以上公安机关验收合格后,才能投入使用。"},{"i":29,"n":"第二十九条","txt":"候问室应当建立以下日常管理制度，依法严格、文明管理： （一）设立《继续盘问登记表》，载明被盘问人的姓名、性别、年龄、住址、单位，以及办案部门、承办人、批准人、继续盘问的原因、起止时间、处理结果等情况； （二）建立值班、看管和巡查制度，明确值班岗位责任，候问室有被盘问人时，应当由人民警察值班、看管和巡查，如实记录有关情况，并做好交接工作； （三）建立档案管理制度，对《继续盘问登记表》等有关资料按照档案管理的要求归案保存，以备查验。"},{"i":30,"n":"第三十条","txt":"除本规定第十条所列情形外，在继续盘问间隙期间，应当将被盘问人送入候问室；未设置候问室的，应当由人民警察在讯问室、办公室看管,或者送入就近公安派出所的候问室。 禁止将被盘问人送入看守所、拘役所、拘留所、强制戒毒所或者其他监管场所关押，以及将不同性别的被盘问人送入同一个候问室。"},{"i":31,"n":"第三十一条","txt":"被盘问人被送入候问室时，看管的人民警察应当问清其身体状况，并做好记录；发现被盘问人有外伤、有严重疾病发作的明显症状的，或者具有本规定第十条所列情形之一的，应当立即报告县、市、旗公安局或者城市公安分局警务督察部门和主管公安派出所工作的部门，并做好详细记录。"},{"i":32,"n":"第三十二条","txt":"将被盘问人送入候问室时，对其随身携带的物品，公安机关应当制作《暂存物品清单》，经被盘问人签名或者捺指印确认后妥为保管，不得侵吞、挪用或者损毁。 继续盘问结束后，被盘问人的物品中属于违法犯罪证据或者违禁品的，应当依法随案移交或者作出处理，并在《暂存物品清单》上注明；与案件无关的，应当立即返还被盘问人，并在《暂存物品清单》上注明，由被盘问人签名或者捺指印。"},{"i":33,"n":"第三十三条","txt":"候问室没有厕所和卫生用具的,人民警察带领被盘问人离开候问室如厕时,必须严加看管,防止发生事故。"},{"i":34,"n":"第三十四条","txt":"在继续盘问期间，公安机关应当为被盘问人提供基本的饮食。"},{"i":35,"n":"第三十五条","txt":"公安机关应当将适用继续盘问的情况纳入执法质量考核评议范围，建立和完善办案责任制度、执法过错责任追究制度及其他内部执法监督制度。"},{"i":36,"n":"第三十六条","txt":"除本规定第二十四条、第三十一条所列情形外，发生被盘问人重伤、逃跑、自杀、自伤等事故以及继续盘问超过批准时限的，公安派出所必须立即将有关情况报告县、市、旗公安局或者城市公安分局警务督察部门和主管公安派出所工作的部门，并做好详细记录。 县、市、旗公安局或者城市公安分局警务督察部门应当在接到报告后立即进行现场督察。"},{"i":37,"n":"第三十七条","txt":"警务督察部门负责对继续盘问的下列情况进行现场督察： （一）程序是否合法，法律手续是否齐全； （二）继续盘问是否符合法定的适用范围和时限； （三）候问室的设置和管理是否违反本规定； （四）有无刑讯逼供或者殴打、体罚、虐待、侮辱被盘问人的行为； （五）有无违法使用警械、武器的行为； （六）有无违反规定收费或者实施处罚的行为； （七）有无其他违法违纪行为。"},{"i":38,"n":"第三十八条","txt":"警务督察部门在现场督察时，发现办案部门或者人民警察在继续盘问中有违法违纪行为的，应当按照有关规定，采取当场制止、纠正、发督察法律文书、责令停止执行职务或者禁闭等督察措施进行处理；对需要给予处分或者追究刑事责任的，应当依法移送有关部门处理。"},{"i":39,"n":"第三十九条","txt":"对在适用继续盘问中有下列情形之一的，公安机关应当依照《公安机关督察条例》、《公安机关人民警察执法过错责任追究规定》追究有关责任人员的执法过错责任，并依照《中华人民共和国人民警察法》、《国家公务员暂行条例》和其他有关规定给予处分；构成犯罪的，依法追究直接负责的主管人员和其他直接责任人员的刑事责任： （一）违法使用警械、武器，或者实施本规定第十二条、第二十二条、第三十条第二款所列行为之一的； （二）未经批准设置候问室，或者将被盘问人送入未经验收合格的候问室的； （三）不按照本规定第十四条、第十五条的规定通知被盘问人家属或者单位、安排被盘问人无人照顾的家属的； （四）不按照本规定第十九条、第二十一条的规定终止继续盘问、释放被盘问人的； （五）不按照本规定第二十三条、第二十四条、第三十一条和第三十六条的规定报告情况的； （六）因疏于管理导致发生被盘问人伤亡、逃跑、自杀、自伤等事故的； （七）指"},{"i":40,"n":"第四十条","txt":"被盘问人认为公安机关及其人民警察违法实施继续盘问侵犯其合法权益造成损害，依法向公安机关申请国家赔偿的，公安机关应当依照国家赔偿法的规定办理。 公安机关依法赔偿损失后，应当责令有故意或者重大过失的人民警察承担部分或者全部赔偿费用，并对有故意或者重大过失的责任人员，按照本规定第三十九条追究其相应的责任。"},{"i":41,"n":"第四十一条","txt":"本规定所称“以上”、“以内”，均包含本数或者本级。"},{"i":42,"n":"第四十二条","txt":"本规定涉及的有关法律文书格式，由公安部统一制定。"},{"i":43,"n":"第四十三条","txt":"各省、自治区、直辖市公安厅、局和新疆生产建设兵团公安局可以根据本规定，制定具体操作规程、候问室建设标准和管理规定，报公安部备案审查后施行。"},{"i":44,"n":"第四十四条","txt":"本规定自二〇〇四年十月一日起施行。公安部以前制定的关于继续盘问或者留置的规定，凡与本规定不一致的同时废止。"}],"gonganjiguanjiandingrendengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范公安机关鉴定人资格登记管理工作，适应打击犯罪、保护人民、维护社会治安稳定和司法公正的需要，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和有关法律、法规，结合公安机关工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的公安机关鉴定人（以下简称鉴定人），是指经公安机关登记管理部门核准登记，取得鉴定人资格证书并从事鉴定工作的专业技术人员。"},{"i":3,"n":"第三条","txt":"本办法所称的鉴定，是指为解决案（事）件调查和诉讼活动中某些专门性问题，公安机关鉴定机构的鉴定人运用自然科学和社会科学的理论成果与技术方法，对人身、尸体、生物检材、痕迹、文件、证件、视听资料、电子数据及其它相关物品、物质等进行检验、鉴别、分析、判断，并出具鉴定意见或者检验结果的科学实证活动。"},{"i":4,"n":"第四条","txt":"鉴定人的登记管理工作应当根据国家有关法律法规和本办法的规定，遵循依法、公正、及时的原则，保证登记管理工作规范、有序、高效。"},{"i":5,"n":"第五条","txt":"公安部和各省、自治区、直辖市公安厅、局设立或者指定统一的登记管理部门，负责鉴定人资格的审核登记、年度审验、变更、注销、复议、名册编制与备案、监督管理与处罚等。"},{"i":6,"n":"第六条","txt":"公安部登记管理部门负责各省、自治区、直辖市公安厅、局，部属科研机构、院校和专业技术协会，国家移民管理局及其所属单位鉴定人的登记管理工作。 省、自治区、直辖市公安厅、局登记管理部门负责所属地市级、县级公安机关，以及省级公安机关所属院校、医院和专业技术协会的鉴定人的登记管理工作。"},{"i":7,"n":"第七条","txt":"登记管理部门不得收取鉴定资格登记申请人和鉴定人的任何登记管理费用。 登记管理部门的有关业务经费分别列入公安部和各省、自治区、直辖市公安厅、局的年度经费预算。 第三章资格登记"},{"i":8,"n":"第八条","txt":"鉴定人经登记管理部门核准登记，取得《鉴定人资格证书》，方可从事鉴定工作。《鉴定人资格证书》由所在鉴定机构统一管理。 《鉴定人资格证书》由公安部统一监制。"},{"i":9,"n":"第九条","txt":"个人申请鉴定人资格，应当具备下列条件： （一）在职或者退休的具有专门技术知识和技能的人民警察；公安机关聘用的具有行政编制或者事业编制的专业技术人员； （二）遵守国家法律、法规，具有人民警察职业道德； （三）具有与所申请从事鉴定项目相关的高级警务技术职 务任职资格或者高级专业技术职称，或者高等院校相关专业本科以上学历，从事相关工作或研究五年以上，或者具有与所申请从事鉴定项目相关工作十年以上经历和较强的专业技能； （四）所在机构已经取得或者正在申请《鉴定机构资格证书》； （五）身体状况良好，适应鉴定工作需要。"},{"i":10,"n":"第十条","txt":"个人申请鉴定人资格，应当向登记管理部门提交下列材料： （一）《鉴定人资格登记申请表》； （二）学历证明和专业技能培训《结业证书》复印件； （三）警务技术职务任职资格或者专业技术职称证明材料； （四）个人从事与申请鉴定项目有关的工作总结； （五）登记管理部门要求提交的其他材料。 个人申请鉴定人资格，由所在鉴定机构向登记管理部门提交申请登记材料。"},{"i":11,"n":"第十一条","txt":"登记管理部门收到申请登记材料后，应当在二十个工作日内作出是否授予鉴定资格的决定，情况特殊的，可以延长至三十个工作日。提交申请材料不全的，期限从补齐材料之日起计算。 登记管理部门对符合登记条件的，应当作出授予鉴定资格的决定，在十个工作日内颁发《鉴定人资格证书》；对不符合登记条件的，应当作出不授予鉴定资格的决定。"},{"i":12,"n":"第十二条","txt":"登记管理部门应当每年对鉴定人资格审验一次，并及时将审验结果通报至鉴定人所在鉴定机构。"},{"i":13,"n":"第十三条","txt":"鉴定人有下列情形之一的，年度审验不合格： （一）所审验年度内未从事鉴定工作的； （二）无正当理由不接受专业技能培训或者培训不合格的； （三）未经所在鉴定机构同意擅自受理鉴定的； （四）因违反技术规程出具错误鉴定意见的； （五）同一审验年度内被鉴定委托人正当投诉两次以上的。"},{"i":14,"n":"第十四条","txt":"对于年度审验不合格的鉴定人，登记管理部门应当责令其限期改正。鉴定人在改正期内不得出具鉴定文书。"},{"i":15,"n":"第十五条","txt":"鉴定人调换鉴定机构，以及增减登记鉴定项目，应当向登记管理部门申请变更登记。"},{"i":16,"n":"第十六条","txt":"鉴定人在本省、自治区、直辖市内跨鉴定机构调动工作的，应当填写《鉴定人变更登记申请表》，由调出鉴定机构将该申请表提交登记管理部门审核。 鉴定人跨省、自治区、直辖市调动工作的，应当在原登记管理部门申请注销，并在调入地登记管理部门重新申请鉴定人资格。"},{"i":17,"n":"第十七条","txt":"登记管理部门收到鉴定人变更登记申请后，应当在十五个工作日内作出是否准予变更登记的决定。 准予变更登记的，重新颁发《鉴定人资格证书》，原《鉴定人资格证书》由其所在鉴定机构加盖“注销”标识后保存；不准予变更登记的，应当向申请变更登记的鉴定人说明理由。"},{"i":18,"n":"第十八条","txt":"鉴定人有下列情形之一的，应当主动向登记管理部门申请注销资格，登记管理部门也可以直接注销其鉴定资格： （一）连续两年未从事鉴定工作的； （二）无正当理由，三年以上没有参加专业技能培训的； （三）年度审验不合格，在责令改正期限内没有改正的； （四）经人民法院依法通知，无正当理由拒绝出庭作证的； （五）提供虚假证明或者采取其他欺诈手段骗取登记的； （六）同一审验年度内出具错误鉴定意见两次以上的； （七）违反保密规定造成严重后果的； （八）登记管理部门书面警告后仍在其他鉴定机构兼职的； （九）限制行为能力或者丧失行为能力的。"},{"i":19,"n":"第十九条","txt":"鉴定人的鉴定资格注销后，登记管理部门应当向鉴定人所在单位发出《注销鉴定人资格通知书》。"},{"i":20,"n":"第二十条","txt":"因本办法第十八条第（一）、（二）、（三）、（四）款被注销鉴定资格的，具备登记条件或者改正后，可以重新申请鉴定人资格。 因本办法第十八条第（五）、（六）、（七）、（八）、（九）款被注销鉴定资格的，被注销鉴定资格之日起一年内不得申请鉴定人资格。"},{"i":21,"n":"第二十一条","txt":"个人对登记管理部门作出不授予鉴定资格、年度审验不合格、不予变更登记或者注销鉴定资格决定不服的，可以在收到相应通知后三十个工作日内向登记管理部门申请复议。"},{"i":22,"n":"第二十二条","txt":"登记管理部门收到有关复议申请后，应当以集体研究的方式进行复议，在十五个工作日内作出复议决定，并在十个工作日内将《复议决定通知书》送达申请复议人及其所在单位。"},{"i":23,"n":"第二十三条","txt":"登记管理部门应当按照登记管理权限，将核准登记的鉴定人编入本部门管理的公安机关鉴定人名册。"},{"i":24,"n":"第二十四条","txt":"登记管理部门应当按照有关规定，对核准登记的鉴定人进行备案登记。"},{"i":25,"n":"第二十五条","txt":"登记管理部门应当建立鉴定人档案。 鉴定人档案包括本办法第十条第（一）至（五）项，以及鉴定人资格的年度审验、变更、注销等资料。"},{"i":26,"n":"第二十六条","txt":"鉴定人应当在登记管理部门核准登记的鉴定范围内从事鉴定工作。 未取得《鉴定人资格证书》、未通过年度审验，以及鉴定资格被注销的人员，不得从事鉴定工作。"},{"i":27,"n":"第二十七条","txt":"登记管理部门对公民、法人和其他组织举报、投诉鉴定人的，应当及时进行调查，并根据调查结果依法进行处理。"},{"i":28,"n":"第二十八条","txt":"鉴定人违反本办法有关规定，情节轻微的，除适用第十三条外，登记管理部门还可以依法给予书面警告、责令改正的处罚。责令改正期限一般不得超过三个月。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，终身不授予鉴定资格： （一）故意出具虚假鉴定意见的； （二）严重违反规定，出具两次以上错误鉴定意见并导致冤假错案的； （三）受过开除公职处分的。"},{"i":30,"n":"第三十条","txt":"铁路、交通港航、民航、森林公安机关和海关缉私部门的鉴定人登记管理工作，依照本办法规定向所在地公安机关登记管理部门申请登记。"},{"i":31,"n":"第三十一条","txt":"本办法自2020年5月1日起施行。公安部2005年12月29日发布的《公安机关鉴定人登记管理办法》（公安部令第84号）同时废止。"}],"gonganjiguanjiandingjigoudengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范公安机关鉴定机构资格登记管理工作，适应打击犯罪、保护人民、维护社会治安稳定和司法公正的需要，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和有关法律、法规，结合公安机关工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称公安机关鉴定机构（以下简称鉴定机构），是指公安机关及其所属的科研机构、院校、医院和专业技术协会等依法设立并开展鉴定工作的组织。"},{"i":3,"n":"第三条","txt":"本办法所称的鉴定，是指为解决案（事）件调查和诉讼活动中某些专门性问题，公安机关鉴定机构的鉴定人运用自然科学和社会科学的理论成果与技术方法，对人身、尸体、生物检材、痕迹、文件、证件、视听资料、电子数据及其它相关物品、物质等进行检验、鉴别、分析、判断，并出具鉴定意见或者检验结果的科学实证活动。"},{"i":4,"n":"第四条","txt":"鉴定机构的登记管理工作应当根据国家有关法律法规和本办法的规定，遵循依法、公正、及时的原则，保证登记管理工作规范、有序、高效。"},{"i":5,"n":"第五条","txt":"公安部和各省、自治区、直辖市公安厅、局设立或者指定统一的登记管理部门，负责鉴定机构资格的审核登记、年度审验、变更、注销、复议、名册编制与备案、监督管理与处罚等。"},{"i":6,"n":"第六条","txt":"公安部登记管理部门负责各省、自治区、直辖市公安厅、局，部属科研机构、院校和专业技术协会，国家移民管理局及其所属单位鉴定机构的登记管理工作。 省、自治区、直辖市公安厅、局登记管理部门负责所属地市级、县级公安机关，以及省级公安机关所属院校、医院和专业技术协会的鉴定机构的登记管理工作。"},{"i":7,"n":"第七条","txt":"登记管理部门不得收取鉴定资格登记申请单位和鉴定机构的任何登记管理费用。 登记管理部门的有关业务经费分别列入公安部和各省、自治区、直辖市公安厅、局的年度经费预算。"},{"i":8,"n":"第八条","txt":"鉴定机构经登记管理部门核准登记，取得《鉴定机构资格证书》，方可进行鉴定工作。 《鉴定机构资格证书》由公安部统一监制，分为正本和副本，正本和副本具有同等的法律效力。《鉴定机构资格证书》正本悬挂于鉴定机构住所内醒目位置，副本主要供外出办理鉴定有关业务时使用。"},{"i":9,"n":"第九条","txt":"鉴定机构登记的事项包括：名称、住所、法定代表人或者主要负责人、鉴定人、鉴定项目、注册固定资产、使用的技术标准目录等。"},{"i":10,"n":"第十条","txt":"单位申请鉴定机构资格，应当具备下列条件： （一）有单位名称和固定住所； （二）有适合鉴定工作的办公和业务用房； （三）有明确的鉴定项目范围； （四）有在项目范围内进行鉴定必需的仪器、设备； （五）有在项目范围内进行鉴定必需的依法通过资质认定或者实验室认可的实验室； （六）有在项目范围内进行鉴定必需的资金保障； （七）有开展该鉴定项目的三名以上的鉴定人； （八）有完备的鉴定工作管理制度。"},{"i":11,"n":"第十一条","txt":"单位申请设立鉴定机构，应当向登记管理部门提交下列材料： （一）《鉴定机构资格登记申请表》； （二）所有鉴定人的名册； （三）所有鉴定人的警务技术职务任职资格或者专业技术职称证明材料、学历证书的复印件； （四）办公和业务用房的平面比例图； （五）仪器设备登记表； （六）鉴定采用的技术标准目录； （七）鉴定机构内部管理工作制度； （八）鉴定机构的法人代表证明，或者同级公安机关负责人关于保证鉴定人独立开展鉴定工作的书面承诺； （九）应当提交的其他材料。"},{"i":12,"n":"第十二条","txt":"公安机关的鉴定机构可以申报登记开展下列鉴定项目： （一）法医类鉴定，包括法医临床、法医病理、法医人类学和法医精神病鉴定； （二）DNA鉴定； （三）痕迹鉴定； （四）理化鉴定，包括毒物、毒品和微量物质的鉴定； （五）文件证件鉴定； （六）声像资料鉴定； （七）电子数据鉴定； （八）环境损害鉴定； （九）交通事故鉴定； （十）心理测试； （十一）警犬鉴别。 根据科学技术发展和公安工作需要，鉴定机构可以申请开展其他鉴定项目。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市公安厅、局，部属科研机构、院校和专业技术协会，国家移民管理局及其所属单位等申请设立鉴定机构，应当向公安部登记管理部门提交申请材料。 省、自治区、直辖市公安厅、局所属院校、医院和专业技术协会，以及地市级公安机关申请设立鉴定机构，应当向所在省、自治区、直辖市公安厅、局登记管理部门提交申请材料。 县级公安机关申请设立鉴定机构，应当由地市级公安机关向所在省、自治区、直辖市公安厅、局登记管理部门提交申请材料。"},{"i":14,"n":"第十四条","txt":"登记管理部门收到申请登记材料后，应当在二十个工作日内作出是否准予登记的决定，情况特殊的，可以延长至三十个工作日。提交申请材料不全的，期限从补齐材料之日起计算。 公安机关一个独立法人单位（含市辖区公安分局）只核准登记一个鉴定机构。因工作需要，可以设立分支机构。 登记管理部门对符合登记条件的，应当作出准予登记的决定，在期限内颁发《鉴定机构资格证书》；对不符合登记条件的，作出不予登记的决定。"},{"i":15,"n":"第十五条","txt":"登记管理部门应当每年对鉴定机构资格审验一次，并及时将审验结果通报至鉴定机构。"},{"i":16,"n":"第十六条","txt":"鉴定机构有下列情形之一的，年度审验不合格： （一）所属鉴定人人数达不到登记条件的； （二）因技术用房、仪器设备、资金保障、鉴定人能力的缺陷已无法保证鉴定质量的； （三）资质认定或者实验室认可资格被暂停或者取消的； （四）出具错误鉴定意见并导致发生重大责任事故的。"},{"i":17,"n":"第十七条","txt":"对于年度审验不合格的鉴定机构，登记管理部门应当责令其限期改正。鉴定机构应当在改正期内暂停相关鉴定项目。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，鉴定机构应当向原登记管理部门申请变更登记： （一）变更鉴定机构住所的； （二）变更鉴定机构主要负责人的； （三）变更鉴定机构鉴定项目的； （四）变更鉴定机构名称的。 鉴定机构申请变更登记，应当提交《公安机关鉴定机构资格变更登记申请表》。"},{"i":19,"n":"第十九条","txt":"登记管理部门收到鉴定机构变更登记申请后，应当在十五个工作日内作出是否准予变更登记的决定。准予变更登记的，重新颁发《鉴定机构资格证书》。"},{"i":20,"n":"第二十条","txt":"鉴定机构有下列情形之一的，应当主动向登记管理部门申请注销鉴定资格，登记管理部门也可以直接注销其鉴定资格： （一）年度审验不合格，在责令改正期限内没有改正的； （二）提供虚假申报材料骗取登记的； （三）因主管部门变化需要注销登记的； （四）法律、法规规定的其他情形。"},{"i":21,"n":"第二十一条","txt":"鉴定机构的鉴定资格注销后，登记管理部门应当向鉴定机构的主管部门发出《注销鉴定机构资格通知书》，收回《鉴定机构资格证书》。"},{"i":22,"n":"第二十二条","txt":"被注销鉴定资格的鉴定机构，经改正后符合登记条件的，可以重新申请登记。"},{"i":23,"n":"第二十三条","txt":"鉴定机构对登记管理部门作出不予登记、年度审验不合格、不予变更登记或者注销登记等决定不服的，可以在收到相应通知后三十个工作日内向登记管理部门申请复议。"},{"i":24,"n":"第二十四条","txt":"登记管理部门收到有关复议申请后，应当以集体研究的方式进行复议，在十五个工作日内作出复议决定，并在十个工作日内将《复议决定通知书》送达申请复议的单位。"},{"i":25,"n":"第二十五条","txt":"登记管理部门应当按照登记管理权限，将核准登记的鉴定机构编入本部门管理的公安机关鉴定机构名册。"},{"i":26,"n":"第二十六条","txt":"登记管理部门应当按照有关规定，对核准登记的鉴定机构进行备案登记。"},{"i":27,"n":"第二十七条","txt":"登记管理部门应当建立鉴定机构档案。 鉴定机构档案包括本办法第十一条第（一）至（九）项，以及资格的年度审验、变更、注销等资料。"},{"i":28,"n":"第二十八条","txt":"登记管理部门应当对鉴定机构进行监督管理。内容包括： （一）鉴定的基础设施和工作环境情况； （二）鉴定用仪器设备的配置、维护和使用情况； （三）鉴定工作业绩情况； （四）鉴定人技能培训情况； （五）鉴定文书档案和证物保管情况； （六）鉴定工作规章制度和执行情况； （七）遵守鉴定程序、技术标准和鉴定质量管理情况等。"},{"i":29,"n":"第二十九条","txt":"登记管理部门对公民、法人和其他组织举报、投诉鉴定机构的，应当及时进行调查，并根据调查结果依法进行处理。"},{"i":30,"n":"第三十条","txt":"登记管理部门对鉴定机构违反本办法的，可以下达《责令改正通知书》，责令其在三个月内改正。"},{"i":31,"n":"第三十一条","txt":"鉴定机构出具错误鉴定意见并导致发生重大责任事故的，应当在发现发生重大责任事故三个工作日内，向登记管理部门书面报告。 省级登记管理部门接到书面报告后，应当及时将情况上报公安部登记管理部门。"},{"i":32,"n":"第三十二条","txt":"鉴定机构有下列情形之一的，登记管理部门应当立即暂停其部分或者全部鉴定项目： （一）不能保证鉴定质量的； （二）无法完成所登记的鉴定项目的； （三）仪器设备不符合鉴定要求的； （四）未按规定办理变更登记手续的； （五）擅自增加鉴定项目或者扩大受理鉴定范围的。 被暂停的鉴定项目，鉴定机构不得出具鉴定意见。"},{"i":33,"n":"第三十三条","txt":"鉴定机构有下列情形之一的，登记管理部门应当予以通报批评： （一）出具错误鉴定意见的； （二）所属鉴定人因过错被注销鉴定资格的； （三）发现鉴定意见错误或者发生重大责任事故不及时报 告的； （四）登记管理部门限期改正逾期不改的； （五）擅自增加收费项目或者提高收费标准的。"},{"i":34,"n":"第三十四条","txt":"鉴定机构有下列情形之一的，登记管理部门将视情建议有关部门对有关责任人给予相应的处罚；构成犯罪的，依法追究其刑事责任： （一）弄虚作假，出具错误鉴定意见，造成严重后果，导致冤假错案的； （二）在应当知道具有危险、危害的情况下，强行要求鉴定人进行鉴定，造成人身伤害、财产损坏、环境污染等重大责任事故的。"},{"i":35,"n":"第三十五条","txt":"铁路、交通港航、民航、森林公安机关和海关缉私部门的鉴定机构登记管理工作，依照本办法规定向所在地公安机关登记管理部门申请登记。"},{"i":36,"n":"第三十六条","txt":"本办法自2020年5月1日起施行。公安部2005年12月29日发布的《公安机关鉴定机构登记管理办法》（公安部令第83号）同时废止。"}],"gongluxunluominjingduijingwugongzuoguifan":[{"i":1,"n":"第一条","txt":"为规范公路巡逻民警队警务工作，维护公路交通安全畅通和治安秩序，保障公路巡逻民警队依法履行职责，根据有关法律法规，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范适用于承担公路交通管理工作的交警大队、交警中队（含公路交警中队、乡镇交警中队）和高速公路交警大（中）队。"},{"i":3,"n":"第三条","txt":"公路巡逻民警队警务工作应当遵循依法、科学、高效、规范、公开和便民的原则。"},{"i":4,"n":"第四条","txt":"省级公安机关应当科学规划公路巡逻民警队的布局，按照所在地区交通安全状况、所管辖公路的通车里程等情况设置公路巡逻民警队，并根据公路通车里程、交通流量、人口、机动车和驾驶人数量、交通安全状况等综合因素配备警力。 具体配备标准由省级公安机关制定。"},{"i":5,"n":"第五条","txt":"公路巡逻民警队实行等级评定制度，具体办法由公安部另行制定。"},{"i":6,"n":"第六条","txt":"公路巡逻民警队可以根据需要配备交通协管员。 交通协管员的招录、培训、使用、考核等相关管理规定，由省级公安机关制定。"},{"i":7,"n":"第七条","txt":"公路巡逻民警队履行下列职责： （一）指挥疏导交通，维护公路交通秩序； （二）依法查处交通违法行为； （三）预防和处理交通事故； （四）依照有关规定办理或者受理机动车登记和驾驶证管理业务； （五）开展交通安全宣传教育； （六）排查公路交通安全隐患； （七）先期处置公路上发生的治安、刑事案件； （八）按照有关规定查缉违法犯罪嫌疑人员； （九）接受群众求助； （十）实施交通应急管理； （十一）法律、行政法规规定应当履行的其他职责。"},{"i":8,"n":"第八条","txt":"公路巡逻民警查处交通违法行为时，可以依法采取扣留车辆、扣留机动车驾驶证、拖移机动车、收缴物品以及检验机动车驾驶人体内酒精、国家管制的精神药品、麻醉药品含量等行政强制措施。"},{"i":9,"n":"第九条","txt":"公路巡逻民警因抢救事故受伤人员、处置突发事件等紧急需要，可以优先使用公路上通行的车辆，用后应当及时归还，并支付适当费用；造成损失的，应当赔偿。"},{"i":10,"n":"第十条","txt":"遇有自然灾害、恶劣天气或者交通事故等情形，严重影响交通安全的，公路巡逻民警队可以按照相关法律、法规规定和工作预案，实施交通管制。 实施交通管制，应当在现场设置警示标志、指示标志等，做好交通指挥疏导工作。"},{"i":11,"n":"第十一条","txt":"公路巡逻民警队应当接受治安、刑侦等部门的业务指导，并与治安、刑侦等部门在案件移交、处置治安和刑事案件、打击违法犯罪等方面建立协作配合机制。 治安、刑侦等部门对公路巡逻民警队按规定移交的案件，应当及时受理。"},{"i":12,"n":"第十二条","txt":"公路巡逻民警队实行巡逻执勤与定点执勤相结合的勤务方式，并可以依法使用交通技术监控设备对公路通行情况进行监控。"},{"i":13,"n":"第十三条","txt":"公路巡逻民警应当严格执行勤务制度，不得脱岗、漏岗，不得随意改变勤务路线和执勤时间。"},{"i":14,"n":"第十四条","txt":"相邻省、自治区、直辖市公安机关交通管理部门及公路巡逻民警队应当研究建立区域警务协作机制，实行联合勤务制度。"},{"i":15,"n":"第十五条","txt":"公路巡逻民警执勤执法时应当执行下列任务： （一）在驾驶警车巡逻执勤时，注意观察公路通行情况，检查交通信号灯、交通标志、交通标线、交通设施等是否完好； （二）指挥、疏导交通，维护公路通行秩序； （三）依法制止、纠正和处罚交通违法行为； （四）受理公民求助和报警，先期处置公路上发生的治安、刑事案件，救助人身财产安全受到侵害的群众； （五）控制被指控有犯罪行为或者现场作案嫌疑的人员，移交有管辖权的公安机关处理； （六）根据上级指令处理其他情况。 在盘查可疑人员、机动车或者在先期处置公路上发生的治安、刑事案件过程中执行询问、检查、抓捕任务时，应当至少由两名民警进行，并明确警戒和检查任务分工，做好警戒，确保安全。"},{"i":16,"n":"第十六条","txt":"公路巡逻民警驾驶警车巡逻执勤时，应当开启警灯，按规定保持车速和车距。执勤执法时应当穿着反光背心，遵守下列安全防护规定： （一）除执行堵截严重暴力犯罪嫌疑人等特殊任务外，定点执勤以及拦截、检查车辆或者处理交通违法行为时，应当根据通行条件和交通流量，选择不妨碍其他车辆通行和不影响自身安全的地点进行，并在来车方向放置发光或者反光警告标志、警示灯、锥筒等安全防护装备； （二）遇有机动车驾驶人拒绝停车的，应当通知前方执勤站点组织拦截，不得站在车辆前方强行拦截，或者攀扒车辆，强行责令机动车驾驶人停车； （三）对暴力犯罪嫌疑人、交通肇事逃逸驾驶人、被公安机关通缉的人员等危险人员乘坐、驾驶机动车逃逸，可能对公共安全和他人生命安全有严重威胁的，可以驾驶机动车追缉，并应当及时请求支援。"},{"i":17,"n":"第十七条","txt":"执行交通警卫任务时，公路巡逻民警队应当结合实际制定交通警卫工作方案，按照警卫级别采取相应警卫措施。"},{"i":18,"n":"第十八条","txt":"公路巡逻民警队可以在省际、市际、县际交界处设置交通安全执法服务站（点），开展交通安全宣传，提供便民利民服务。"},{"i":19,"n":"第十九条","txt":"公路巡逻民警队接到报警或者出警指令后，应当及时命令就近公路巡逻民警赶赴现场。接到事故报警后，交通事故处理岗位民警白天应当在5分钟内出警，夜间应当在10分钟内出警。"},{"i":20,"n":"第二十条","txt":"盘查可疑人员时，应当遵守下列规定： （一）与被盘查人保持1米以上的距离，尽量让其背对开阔面； （二）对有一定危险性的违法犯罪嫌疑人员，先将其控制再进行检查，确认无危险后方可实施盘查； （三）盘查时由一人主问，另一人负责警戒，防止被盘查人或者同伙的袭击； （四）盘查过程中应保持高度警惕，注意被盘查人的身份、体貌、衣着、行为、携带物品等可疑之处，随时做好应对突发情况的准备； （五）当盘查对象有异常举动时，民警应当及时发出警告，命令其停止动作并做好自身防范，可以依法视情使用警械予以制止。"},{"i":21,"n":"第二十一条","txt":"对可疑机动车进行检查时，应当遵守下列规定： （一）指挥驾驶人停车，责令机动车驾驶人熄灭发动机并打开车窗，拉紧手制动，开启危险报警闪光灯后将双手放在方向盘上，确认安全后责令其下车，必要时应当暂时收存车钥匙。如车上有其他人员，应当责令其下车等候； （二）对人员进行检查并予以控制； （三）查验身份证、机动车驾驶证、行驶证和号牌，并通过公安信息系统进行查询比对； （四）查验机动车外观、锁具、发动机和车架号码等； （五）检查车载货物和车内物品。 检查可疑机动车时，负责警戒的民警应当站在可以直接注视车内驾驶人和乘车人、保护负责检查的民警的位置，并保持高度警惕，密切注视驾驶人和乘车人，防范其突然袭击。 驾驶人逃逸的，应当立即向上级或者指挥中心报告，请求部署堵截、追缉。"},{"i":22,"n":"第二十二条","txt":"公路巡逻民警队应当建立健全勤务监督制度，确保各项勤务有效实施。"},{"i":23,"n":"第二十三条","txt":"高速公路交警大（中）队可以在高速公路收费站和服务区以及容易发生交通事故、交通拥堵的路段设置执勤岗位。 除依法执行紧急公务外，禁止在高速公路主线上采取摆放路障、锥筒、交通标志等方式，拦截正常行驶的车辆进行交通安全检查。"},{"i":24,"n":"第二十四条","txt":"公路巡逻民警队应当制定应对、处置自然灾害、恶劣天气、道路交通事故、交通拥堵、交通肇事逃逸、治安刑事案件以及盘查违法嫌疑人员、对可疑机动车进行检查等工作预案，定期组织民警开展培训和演练。"},{"i":25,"n":"第二十五条","txt":"因自然灾害、恶劣天气或者道路交通事故等突发事件造成交通中断时，公路巡逻民警队应当根据应急预案分级启动应急机制，进入应急状态，采取相应处置措施。"},{"i":26,"n":"第二十六条","txt":"公路巡逻民警队处置道路交通事故应当做到快速出警、快速施救、快速勘查现场、快速处理、快速恢复交通，事故现场必须按规定设置警示标志和现场防护设施。"},{"i":27,"n":"第二十七条","txt":"除发生大范围雾霾、道路长距离结冰以及其他不具备安全通行条件的情形外，不得因天气原因实施封闭高速公路的交通管制措施。 实施封闭高速公路交通管制措施的，应当采取警车带道、限速行驶等方式，引导车辆从最近的出口驶离高速公路。"},{"i":28,"n":"第二十八条","txt":"实施交通管制措施可能影响周边道路交通的，高速公路交警大（中）队应当及时向上级或者指挥中心报告，通报相邻公安机关交通管理部门和高速公路经营管理单位，并组织疏导、分流。"},{"i":29,"n":"第二十九条","txt":"公路巡逻民警执勤时应当携带警棍、催泪喷射器、手铐、警绳等驱逐、制服、约束性警用器械。按照上级指令执行查缉暴力犯罪嫌疑人及其驾驶、乘坐的车辆等任务时应当携带枪支、弹药等警用武器，并穿着防弹衣、佩戴防弹头盔。"},{"i":30,"n":"第三十条","txt":"对公路上发生的治安、刑事案件，应当视现场情况采取下列先期处置措施： （一）保护现场并设置警示标志，疏导交通，必要时使用警戒带划定警戒区域； （二）查验居民身份证、机动车驾驶证等有关证照； （三）检查有违法犯罪嫌疑的车辆、物品，配合组织追缉、堵截违法犯罪嫌疑人员； （四）组织抢救受伤人员，疏散群众； （五）对现行或者在逃的违法犯罪嫌疑人员，可以依法讯问或者采取强制措施； （六）向上级公安机关报告案情； （七）向治安、刑侦等部门或者案件发生地公安派出所移交涉嫌违法犯罪的人员和物品。"},{"i":31,"n":"第三十一条","txt":"公路巡逻民警在先期处置治安、刑事案件过程中应当遵守下列规定： （一）对违法犯罪嫌疑人员，应当先进行安全检查，发现管制刀具、武器、易燃易爆危险品的，应当立即予以扣押； （二）对违法犯罪嫌疑人员携带的物品进行检查时，应当在确保违法犯罪嫌疑人员得到有效控制后实施； （三）实施押解、讯问时，应当对违法犯罪嫌疑人员依法采取有效约束措施，防止其脱逃或者行凶。"},{"i":32,"n":"第三十二条","txt":"对堵塞交通等群体性事件，应当视现场情况采取以下处置措施： （一）迅速了解事件起因、规模及影响交通的程度，及时向上级或者指挥中心报告，同时劝告群众离开现场； （二）向群众宣传有关法律规定，配合有关部门开展劝说工作； （三）在现场外围设置警戒线，控制无关人员和车辆进入现场，必要时依法实行交通管制； （四）在处置过程中，应当坚持慎用警力、慎用武器警械和慎用强制措施，注意防止误伤他人，保护民警自身安全。"},{"i":33,"n":"第三十三条","txt":"对重特大道路交通事故，应当视现场情况采取以下先期处置措施： （一）设置警戒区和警示标志，在安全距离位置放置发光或者反光锥筒和警告标志，确定专人负责现场交通指挥和疏导，维护公路通行秩序。因道路交通事故导致交通中断或者现场处置、勘查需要实施封闭道路等交通管制措施的，还应当在事故现场来车方向提前组织分流，放置绕行提示标志，避免发生交通拥堵； （二）收集证据，寻找证人；对有人员伤亡、公路设施损坏的事故，应当立即向上级或者指挥中心报告，通知卫生行政、交通运输、安全监管以及公安消防等部门赶赴现场处置，及时实施封闭道路、疏散过往车辆、人员和控制现场等措施，并协助有关部门抢救受伤人员。因抢救伤员需要变动现场的，应当标明或者记录受伤人员的位置；受伤人员被送往医院的，应当记录医院名称、地址及受伤人员基本情况； （三）在交通事故处理岗位民警到达现场前，指挥疏导车辆、人员绕行； （四）控制交通肇事驾驶人，如有"},{"i":34,"n":"第三十四条","txt":"遇涉及易燃易爆化学物品以及毒害性、放射性、腐蚀性、传染病病原体等危险物品的事故，应当立即向上级或者指挥中心报告，通知卫生行政、交通运输、环境保护、安全监管以及公安消防等部门赶赴现场处置，实施封闭道路、疏散过往车辆、人员和控制现场等措施，禁止无关车辆、人员进入现场。在环境保护、安全监管以及公安消防等部门消除险情后，公路巡逻民警方可进入现场。"},{"i":35,"n":"第三十五条","txt":"对自然灾害事故及其他意外事件，应当视现场情况采取以下处置措施： （一）立即向上级或者指挥中心报告； （二）维护现场秩序，指挥救灾车辆优先通行； （三）抢救遇险群众，保护财产； （四）对造成道路交通中断的，指挥疏导车辆、人员绕行。"},{"i":36,"n":"第三十六条","txt":"公路巡逻民警队应当建立民警执法考核制度，综合考核民警的执勤执法工作量、执法质量、执法效果以及执法纪律遵守等情况。"},{"i":37,"n":"第三十七条","txt":"公路巡逻民警队应当配备专（兼）职法制员，审核案件、检查执法质量、评析执法效果，对发现的执法问题提出整改意见。"},{"i":38,"n":"第三十八条","txt":"有条件的公路巡逻民警队应当为民警装备音像记录设备，对民警的执勤执法全过程进行录音或者录像记录。"},{"i":39,"n":"第三十九条","txt":"公路巡逻民警队应当建立执法回访制度，定期回访交通事故当事人，听取意见和建议。"},{"i":40,"n":"第四十条","txt":"公路巡逻民警队应当设置警务公开栏，公开民警姓名、照片、警号、职务、岗位职责、办事程序、处罚依据、收费标准及有关法律法规规定。"},{"i":41,"n":"第四十一条","txt":"公路巡逻民警队应当定期开展警营开放活动，向公众介绍公安机关交通管理部门的工作，听取对公安交通管理工作的意见和建议。"},{"i":42,"n":"第四十二条","txt":"公路巡逻民警在执勤执法时，严禁下列行为： （一）擅离岗位； （二）违反规定扣留车辆、机动车行驶证、驾驶证和车辆号牌； （三）违反规定当场收缴罚款，当场收缴罚款不开具罚款收据、不开具简易程序处罚决定书或者不如实填写罚款单据； （四）利用职务便利索取、收受他人财物、谋取不正当利益、干扰执法办案或者强令违法办案； （五）不使用规范用语、态度蛮横、行为粗暴、故意刁难群众或者吃拿卡要； （六）不消除交通违法状态即放行车辆。 对违反上述规定的公路巡逻民警给予相应的行政处分。"},{"i":43,"n":"第四十三条","txt":"公路巡逻民警队及其上级公安机关，不得向民警下达或者变相下达罚款指标，不得隐瞒不报或者谎报应当上报的重特大道路交通事故、交通拥堵等情况。 违反上述规定的，对直接负责的主管人员和其他直接责任人员给予相应的行政处分。"},{"i":44,"n":"第四十四条","txt":"公路巡逻民警队及其民警认真履行法定职责，工作表现突出，有显著成绩和贡献或者有其他突出事迹的，应当予以表彰奖励。"},{"i":45,"n":"第四十五条","txt":"公路巡逻民警队应当建立社会监督机制，公布举报、投诉方式，聘请社会监督员，接受社会监督。"},{"i":46,"n":"第四十六条","txt":"县级公安机关应当提请政府成立交通安全领导机构、建立交通安全工作联席会议制度，组织领导本地区道路交通安全工作。"},{"i":47,"n":"第四十七条","txt":"公路巡逻民警队应当定期分析研判本地区交通安全形势，根据道路交通事故时间、地点、主要原因以及交通违法行为发生的规律特点，科学制定预防道路交通事故的对策、措施和意见。"},{"i":48,"n":"第四十八条","txt":"公路巡逻民警队应当协调本地区农村基层组织、机关、企事业单位建立健全内部交通安全宣传教育制度，开展交通安全宣传教育。"},{"i":49,"n":"第四十九条","txt":"高速公路交警大（中）队可以聘请高速公路经营管理单位的收费、养护职工为交通安全员，协助开展交通安全宣传，劝阻和举报交通违法行为。"},{"i":50,"n":"第五十条","txt":"公路巡逻民警队应当联合有关职能部门，定期排查本地区道路交通安全隐患，及时提出消除安全隐患、预防道路交通事故的建议。"},{"i":51,"n":"第五十一条","txt":"公路巡逻民警队应当配合有关职能部门，督促本地区企事业单位落实交通安全责任制，加强对客运车辆、危险化学品运输车辆、校车等机动车及其驾驶人的交通安全监管。"},{"i":52,"n":"第五十二条","txt":"省级公安机关交通管理部门应当在本地区公安信息化总体规划下，制定公路交通管理信息化建设的规划意见。"},{"i":53,"n":"第五十三条","txt":"公路巡逻民警队应当掌握本地区道路、人口、机动车、驾驶人数据和村庄、学校、运输企业分布以及交通违法、交通事故等情况，并及时录入有关信息系统。"},{"i":54,"n":"第五十四条","txt":"公路巡逻民警队应当建立交通信息发布制度，通过多种渠道发布道路交通管理信息，为公众提供交通出行信息服务。"},{"i":55,"n":"第五十五条","txt":"有条件的公路巡逻民警队应当通过公安网络实行网上办公，配备可以实时查询、处理交通违法信息的无线移动执法终端设备。"},{"i":56,"n":"第五十六条","txt":"在道路交通事故多发、交通安全隐患突出、交通违法行为多、机动车流量较大的路口、路段应当设置交通技术监控设备。"},{"i":57,"n":"第五十七条","txt":"对具有计量功能的交通技术监控设备应当定期进行检验。"},{"i":58,"n":"第五十八条","txt":"高速公路交警大（中）队应当与高速公路经营管理单位共享公路监控信息资源。 道路交通卡口监控信息应当与公安机关有关部门、警种共享。"},{"i":59,"n":"第五十九条","txt":"公路巡逻民警队的经费应当纳入财政预算全额保障，编制应当纳入公安机关编制保障计划。"},{"i":60,"n":"第六十条","txt":"公路巡逻民警队营房建设应当满足交通违法处理、道路交通事故处理、机动车和驾驶证管理、开展交通安全宣传等业务需要。"},{"i":61,"n":"第六十一条","txt":"公安机关应当按照标准为公路巡逻民警队配备必要的警用车辆、武器、警械、计算机、通信器材、反光背心、防护装备、交通事故现场勘查、测速仪、酒精检测仪等装备。 执勤警用汽车应当配备反光锥筒、警示灯、停车示意牌、警戒带、照相机、摄像机、灭火器、急救箱、牵引绳等装备；根据需要可以配备防弹衣、防弹头盔、简易破拆工具、防化服、拦车破胎器、酒精检测仪、测速仪等装备。"},{"i":62,"n":"第六十二条","txt":"公路巡逻民警队应当建立政治学习、值班备勤、装备管理、档案管理等工作制度。 公路巡逻民警队应当建立岗位练兵制度，定期组织开展交通管理业务、科技应用、警务技能的学习训练。"},{"i":63,"n":"第六十三条","txt":"公路巡逻民警队应当保持车辆车况良好、停放有序，装备齐全有效，通讯畅通。 非执行公务不得使用警用装备和警用车辆。 枪支、警械的管理、使用，按照有关规定执行。"},{"i":64,"n":"第六十四条","txt":"公路巡逻民警队应当按照规定制作、设置统一的外观标识。办公场所保持整洁、有序。"},{"i":65,"n":"第六十五条","txt":"各省、自治区、直辖市公安厅、局可以根据本规范，结合本地实际制定实施办法。"},{"i":66,"n":"第六十六条","txt":"本规范自2011年7月1日起施行，2001年5月23日发布的《公路巡逻民警中队警务规范》（公安部令第58号）同时废止。"}],"chujingrujinghangkongqizaiyunrenyuanxinxiyubaoyujia3ca9a":[{"i":1,"n":"第一条","txt":"为了规范出境入境航空器载运人员信息预报预检工作，维护国家安全、公共安全，便利航空器及其载运人员出境入境，根据《中华人民共和国出境入境管理法》《中华人民共和国反恐怖主义法》《中华人民共和国出境入境边防检查条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"出境入境航空器负责人或者其出境入境业务代理单位（以下简称航空器负责人或者代理单位），应当按照本办法完整、准确、及时地预报出境入境航空器拟载运的旅客、机组人员信息，包括旅客订座记录、登机旅客信息和登机机组人员信息。"},{"i":3,"n":"第三条","txt":"航空器负责人或者代理单位应当按照公安部出入境管理机构和国务院民用航空主管部门商定的格式，通过专用网络将预报信息发送至指定的地址。 预报信息由出入境边防检查机关和国务院民用航空主管部门共享。"},{"i":4,"n":"第四条","txt":"航空器负责人或者代理单位应当在航空器起飞前72小时、24小时、2小时、1小时和起飞后30分钟内分别报送旅客订座记录。 旅客订座记录采用国际标准电子报文格式，内容包括旅客姓名、国籍、性别、出生日期、出境入境证件号码、出境入境证件有效期截止日期、航段、团体情况、联系地址、出票情况等。"},{"i":5,"n":"第五条","txt":"航空器负责人或者代理单位应当在办理旅客值机手续时，逐一报送拟登机的旅客信息，并在飞机关闭舱门准备起飞前报送所有已登机旅客和机组人员信息。 登机旅客和机组人员信息的内容包括：姓名、国籍、性别、出生日期、出境入境证件号码、出境入境证件有效期截止日期、人员类别。"},{"i":6,"n":"第六条","txt":"出入境边防检查机关负责对航空器负责人或者代理单位报送的登机旅客信息进行预先核查，即时向航空器负责人或者代理单位反馈预检指令。 对于出入境边防检查机关反馈不准登机的旅客，航空器负责人或者代理单位应当不准其登机。"},{"i":7,"n":"第七条","txt":"航空器负责人或者代理单位按照规定预报信息的，出入境边防检查机关和国务院民用航空主管部门应当对该航空器及其载运的旅客、机组人员出境入境提供便利。"},{"i":8,"n":"第八条","txt":"航空器负责人或者代理单位未按本办法第四条、第五条规定预报信息的，出入境边防检查机关依据《中华人民共和国出境入境管理法》第八十三条第一款第二项的规定，对航空器负责人按以下标准罚款，对单个航班罚款总额不超过五万元： （一）未按规定时限报送旅客订座记录的，按每漏报一次处五千元罚款； （二）未按规定时限报送登机人员信息的，处一万元以上三万元以下罚款； （三）报送登机人员信息不准确的，单个航班不准确数量不超过十人的，处一万元罚款；单个航班不准确数量超过十人的，每多错报一人，增处一千元罚款； （四）漏报或多报登机人员信息的，每漏报或多报一人处五千元罚款； （五）未报送登机人员信息的，处五万元罚款。 航空器负责人或者代理单位未能按规定预报信息，有证据证明因网络故障等客观原因造成的，不予处罚；情节特别轻微的，可以不予处罚，但应当责令其改正。"},{"i":9,"n":"第九条","txt":"违反本办法第六条第二款规定，对出入境边防检查机关反馈不准登机的旅客，航空器负责人或者代理单位仍允许其登机并载运其出境入境的，出入境边防检查机关根据《中华人民共和国出境入境管理法》第八十三条第二款的规定，处每载运一人一万元罚款。"},{"i":10,"n":"第十条","txt":"航空器负责人或者代理单位未按照本办法规定报送出境入境航空器载运的旅客、机组人员信息的，出入境边防检查机关可以推迟或者阻止该航空器负责人或者代理单位运营管理的航空器出境入境；国务院民用航空主管部门可将有关情况记入守法信用信息记录，并按照有关规定进行公示。"},{"i":11,"n":"第十一条","txt":"本办法下列用语的含义： 航空器负责人，是指出境入境航空器运营人、所有人、机长等对航空器出境入境活动负责的单位、人员。 出境入境证件号码，是指旅客或机组人员持用的有效护照或者中华人民共和国法律、行政法规规定的有效出入境证件号码。 人员类别，是指旅客或者机组人员。"},{"i":12,"n":"第十二条","txt":"本办法自2018年8月1日起施行。《国际航班载运人员信息预报实施办法》（公安部第99号令）同时废止。"}],"juduhuaxuepingoumaihegongluyunshuxukezhengjianguan19763e":[{"i":1,"n":"第一条","txt":"为加强对剧毒化学品购买和公路运输的监督管理，保障国家财产和公民生命财产安全，根据《中华人民共和国道路交通安全法》、《危险化学品安全管理条例》等法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"除个人购买农药、灭鼠药、灭虫药以外，在中华人民共和国境内购买和通过公路运输剧毒化学品的，应当遵守本办法。 本办法所称剧毒化学品，按照国务院安全生产监督管理部门会同国务院公安、环保、卫生、质检、交通部门确定并公布的剧毒化学品目录执行。"},{"i":3,"n":"第三条","txt":"国家对购买和通过公路运输剧毒化学品行为实行许可管理制度。购买和通过公路运输剧毒化学品，应当依照本办法申请取得《剧毒化学品购买凭证》、《剧毒化学品准购证》和《剧毒化学品公路运输通行证》。未取得上述许可证件，任何单位和个人不得购买、通过公路运输剧毒化学品。 任何单位或者个人不得伪造、变造、买卖、出借或者以其他方式转让《剧毒化学品购买凭证》、《剧毒化学品准购证》和《剧毒化学品公路运输通行证》，不得使用作废的上述许可证件。"},{"i":4,"n":"第四条","txt":"公安机关应当坚持公开、公平、公正的原则，严格依照本办法审查核发剧毒化学品购买和公路运输许可证件，建立健全审查核发许可证件的管理档案，公开办理许可证件的公安机关主管部门的通信地址、联系电话、传真号码和电子信箱，并监督指导从业单位严格执行剧毒化学品购买和公路运输许可管理规定。 省级公安机关对核发的剧毒化学品购买凭证、准购证和公路运输通行证应当建立计算机数据库，包括证件编号、购买企业、运输企业、运输车辆、驾驶人、押运人员、剧毒化学品品名和数量、目的地、始发地、行驶路线等内容。数据库的项目和数据的格式应当全国统一。治安管理、交通管理部门应当建立信息共享或者通报制度。"},{"i":5,"n":"第五条","txt":"经常需要购买、使用剧毒化学品的，应当持销售单位生产或者经营剧毒化学品资质证明复印件，向购买单位所在地设区的市级人民政府公安机关治安管理部门提出申请。符合要求的，由设区的市级人民政府公安机关负责人审批后，将盖有公安机关印章的《剧毒化学品购买凭证》成册发给购买或者使用单位保管、填写。 （一）生产危险化学品的企业申领《剧毒化学品购买凭证》时，应当如实填写《剧毒化学品购买凭证申请表》，并提交危险化学品生产企业安全生产许可证或者批准书的复印件。 （二）经营剧毒化学品的企业申领《剧毒化学品购买凭证》时，应当如实填写《剧毒化学品购买凭证申请表》，并提交危险化学品经营许可证（甲种）的复印件。 （三）其他生产、科研、医疗等经常需要使用剧毒化学品的单位申领《剧毒化学品购买凭证》时，应当如实填写《剧毒化学品购买凭证申请表》，并提交使用、接触剧毒化学品从业人员的上岗资格证的复印件。使用剧毒化学品从事生产的单位"},{"i":6,"n":"第六条","txt":"临时需要购买、使用剧毒化学品的，应当持销售单位生产或者经营剧毒化学品资质证明复印件，向购买单位所在地设区的市级人民政府公安机关治安管理部门提出申请。符合要求的，由设区的市级人民政府公安机关负责人审批签发《剧毒化学品准购证》。 申领《剧毒化学品准购证》时，应当如实填写《剧毒化学品准购证申请表》，并提交注明品名、数量、用途的单位证明。"},{"i":7,"n":"第七条","txt":"对需要通过公路运输剧毒化学品的，以及单车运输气态、液态剧毒化学品超过五吨的，由签发《剧毒化学品购买凭证》、《剧毒化学品准购证》的公安机关治安管理部门将证件编号、发证机关、剧毒化学品品名、数量等有关信息，向运输目的地县级人民政府公安机关交通管理部门通报并录入剧毒化学品公路运输安全管理数据库。具体通报办法由省级人民政府公安机关制定。"},{"i":8,"n":"第八条","txt":"需要通过公路运输剧毒化学品的，应当向运输目的地县级人民政府公安机关交通管理部门申领《剧毒化学品公路运输通行证》。申领时，托运人应当如实填写《剧毒化学品公路运输通行证申请表》，同时提交下列证明文件和资料，并接受公安机关交通管理部门对运输车辆和驾驶人、押运人员的查验、审核： （一）《剧毒化学品购买凭证》或者《剧毒化学品准购证》。 运输进口或者出口剧毒化学品的，应当提交危险化学品进口或者出口登记证。 （二）承运单位从事危险货物道路运输的经营（运输）许可证（复印件）、机动车行驶证、运输车辆从事危险货物道路运输的道路运输证。 运输剧毒化学品的车辆必须设置安装剧毒化学品道路运输专用标识和安全标示牌。安全标示牌应当标明剧毒化学品品名、种类、罐体容积、载质量、施救方法、运输企业联系电话。 （三）驾驶人的机动车驾驶证，驾驶人、押运人员的身份证件以及从事危险货物道路运输的上岗资格证。 （四）随《剧毒化学品"},{"i":9,"n":"第九条","txt":"公安机关交通管理部门受理申请后，应当及时审核和查验以下事项： （一）审核证明文件的真实性，并与省级人民政府公安机关建立的剧毒化学品公路运输安全管理数据库进行比对，审核证明文件与运输单位、运输车辆、驾驶人和押运人员的同一性。 （二）审核驾驶人在一个记分周期内是否有交通违法记分满十二分，或者有两次以上驾驶剧毒化学品运输车辆超载、超速记录。 （三）审核申请的通行路线和时间是否可能对公共安全构成威胁。 （四）查验运输车辆是否设置安装了剧毒化学品道路运输专用标识和安全标示牌，是否配备了主管部门规定的应急处理器材和防护用品，是否有非法改装行为，轮胎花纹深度是否符合国家标准，车辆定期检验周期的时间是否在有效期内。 （五）审核单车运输的数量是否超过行驶证核定载质量。"},{"i":10,"n":"第十条","txt":"公安机关交通管理部门经过审核和查验后，应当按照下列情况分别处理： （一）对证明文件真实有效，运输单位、运输车辆、驾驶人和押运人员符合规定，通行路线和时间对公共安全不构成威胁的，报本级公安机关负责人批准签发《剧毒化学品公路运输通行证》，每次运输一车一证，有效期不超过十五天。 （二）对其他申请条件符合要求，但通行路线和时间有可能对公共安全构成威胁的，由公安机关交通管理部门变更通行路线和时间后，再予批准签发《剧毒化学品公路运输通行证》。 （三）对车辆定期检验合格标志已超过有效期或者在运输过程中将超过有效期的，没有设置专用标识、安全标示牌的，或者没有配备应急处理器材和防护用品，应当经过检验合格，补充有关设置，配齐有关器材和用品后，重新受理申请。 （四）对证明文件过期或者失效的，证明文件与计算机数据库记录比对结果不一致或者没有记录的，承运单位不具备运输危险化学品资质的，驾驶人、押运人员不具备上岗"},{"i":11,"n":"第十一条","txt":"签发通行证后，发证的公安机关交通管理部门应当及时将发证信息发送到省级人民政府公安机关建立的剧毒化学品公路运输安全管理数据库，并通过书面或者信息系统通报沿线公安机关交通管理部门。跨县（市、区、旗）运输的，由设区的市级人民政府公安机关交通管理部门通报，跨地（市、州、盟）和跨省（自治区、直辖市）运输的，由省级人民政府公安机关交通管理部门通报。 对气态、液态剧毒化学品单车运输超过五吨的，签发通行证的公安机关交通管理部门应当报上一级公安机关交通管理部门备案。 具体通报和备案办法由省级人民政府公安机关制定。"},{"i":12,"n":"第十二条","txt":"目的地、始发地和途经地公安机关交通管理部门应当通过信息系统或者采取其他方式及时了解剧毒化学品运输信息，加强对剧毒化学品运输车辆、驾驶人遵守道路交通安全法律规定情况的监督检查。"},{"i":13,"n":"第十三条","txt":"申领《剧毒化学品购买凭证》、《剧毒化学品准购证》的申请人或者申请人委托的代理人可以直接到公安机关提出书面申请，也可以通过信函、传真、电子邮件等形式提出申请。"},{"i":14,"n":"第十四条","txt":"公安机关对申领单位提交的申请材料，应当按照下列规定分别处理： （一）对符合申领条件的，应当当场受理并出具书面凭证。 （二）对申请材料不齐全或者不符合法定形式的，应当当场一次性告知需要补正的全部内容；申请材料存在的错误，可以当场更正的，应当允许申请人当场更正。 （三）对不属于本机关职权范围或者本办法所规定的许可事项的，应当即时作出不予受理的决定并出具书面凭证。"},{"i":15,"n":"第十五条","txt":"对已经受理的申请，公安机关应当及时进行审查，并在三个工作日内作出批准或者不予批准的决定；对申请跨省（自治区、直辖市）运输需要勘察核定行驶线路的，应当在十个工作日内作出批准或者不予批准的决定。对批准的，应当即时填发剧毒化学品购买和公路运输许可证件，并于当日送达或者通知申请人领取；对不予批准的，应当告知申请人不予批准的理由，并出具不予批准的书面凭证。"},{"i":16,"n":"第十六条","txt":"《剧毒化学品购买凭证》由发证公安机关成册核发给购买或者使用单位的，由该单位负责人按照制度规定审核签批使用。持证单位用完后应当及时将购买凭证的存根交回原发证公安机关核查存档。 已经领取《剧毒化学品购买凭证》的单位，应当建立规范的购买凭证保管、填写、审核、签批、使用制度，严格管理。因故不再需要使用时，应当及时将尚未使用的购买凭证连同已经使用的购买凭证的存根交回原发证公安机关核查存档。"},{"i":17,"n":"第十七条","txt":"销售单位销售剧毒化学品时，应当收验《剧毒化学品购买凭证》或者《剧毒化学品准购证》，按照购买凭证或者准购证许可的品名、数量销售，并如实填写《剧毒化学品购买凭证》或者《剧毒化学品准购证》回执第一联和回执第二联，由购买经办人签字确认。 回执第一联由购买单位带回，并在保管人员签注接收情况后的七日内交原发证公安机关核查存档；回执第二联由销售单位在销售后的七日内交所在地县级人民政府公安机关治安管理部门核查存档。"},{"i":18,"n":"第十八条","txt":"通过公路运输剧毒化学品的，应当遵守《中华人民共和国道路交通安全法》、《危险化学品安全管理条例》等法律、法规对剧毒化学品运输安全的管理规定，悬挂警示标志，采取必要的安全措施，并按照《剧毒化学品公路运输通行证》载明的运输车辆、驾驶人、押运人员、装载数量、有效期限、指定的路线、时间和速度运输，禁止超载、超速行驶；押运人员应当随车携带《剧毒化学品公路运输通行证》，以备查验。 运输车辆行驶速度在不超过限速标志的前提下，在高速公路上不低于每小时七十公里不高于每小时九十公里，在其他道路上不超过每小时六十公里。 剧毒化学品运达目的地后，收货单位应当在《剧毒化学品公路运输通行证》上签注接收情况，并在收到货物后的七日内将《剧毒化学品公路运输通行证》送目的地县级人民政府公安机关治安管理部门备案存查。"},{"i":19,"n":"第十九条","txt":"填写《剧毒化学品购买凭证》、《剧毒化学品准购证》或者《剧毒化学品公路运输通行证》发生错误时，应当注明作废并保留存档备查，不得涂改；填写错误的《剧毒化学品购买凭证》，由持证单位负责交回原发证公安机关核查存档。 填写《剧毒化学品购买凭证》或者《剧毒化学品准购证》回执第一联、回执第二联发生错误确需涂改的，应当在涂改处加盖销售单位印章予以确认。"},{"i":20,"n":"第二十条","txt":"未申领《剧毒化学品购买凭证》、《剧毒化学品准购证》、《剧毒化学品公路运输通行证》，擅自购买、通过公路运输剧毒化学品的，由公安机关依法采取措施予以制止，处以一万元以上三万元以下罚款；对已经购买了剧毒化学品的，责令退回原销售单位；对已经实施运输的，扣留运输车辆，责令购买、使用和承运单位共同派员接受处理；对发生重大事故，造成严重后果的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"提供虚假证明文件、采取其他欺骗手段或者贿赂等不正当手段，取得《剧毒化学品购买凭证》、《剧毒化学品准购证》、《剧毒化学品公路运输通行证》的，由发证的公安机关依法撤销许可证件，处以一千元以上一万元以下罚款。 对利用骗取的许可证件购买了剧毒化学品的，责令退回原销售单位。 利用骗取的许可证件通过公路运输剧毒化学品的，由公安机关依照《危险化学品安全管理条例》第六十七条第（一）项的规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"伪造、变造、买卖、出借或者以其他方式转让《剧毒化学品购买凭证》、《剧毒化学品准购证》和《剧毒化学品公路运输通行证》，或者使用作废的上述许可证件的，由公安机关依照《危险化学品安全管理条例》第六十四条的规定予以处罚。"},{"i":23,"n":"第二十三条","txt":"《剧毒化学品购买凭证》或者《剧毒化学品准购证》回执第一联、回执第二联填写错误时，未按规定在涂改处加盖销售单位印章予以确认的，由公安机关责令改正，处以五百元以上一千元以下罚款。 未按规定填写《剧毒化学品购买凭证》和《剧毒化学品准购证》回执记录剧毒化学品销售、购买信息的，由公安机关依照《危险化学品安全管理条例》第六十一条的规定予以处罚。"},{"i":24,"n":"第二十四条","txt":"通过公路运输剧毒化学品未随车携带《剧毒化学品公路运输通行证》的，由公安机关责令提供已依法领取《剧毒化学品公路运输通行证》的证明，处以五百元以上一千元以下罚款。 除不可抗力外，未按《剧毒化学品公路运输通行证》核准载明的运输车辆、驾驶人、押运人员、装载数量、有效期限、指定的路线、时间和速度运输剧毒化学品的，尚未造成严重后果的，由公安机关对单位处以一千元以上一万元以下罚款，对直接责任人员依法给予治安处罚；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法的规定，有下列行为之一的，由原发证公安机关责令改正，处以五百元以上一千元以下罚款： （一）除不可抗力外，未在规定时限内将《剧毒化学品购买凭证》、《剧毒化学品准购证》的回执交原发证公安机关或者销售单位所在地县级人民政府公安机关核查存档的； （二）除不可抗力外，未在规定时限内将《剧毒化学品公路运输通行证》交目的地县级人民政府公安机关备案存查的； （三）未按规定将已经使用的《剧毒化学品购买凭证》的存根或者因故不再需要使用的《剧毒化学品购买凭证》交回原发证公安机关核查存档的； （四）未按规定将填写错误的《剧毒化学品购买凭证》注明作废并保留交回原发证公安机关核查存档的。"},{"i":26,"n":"第二十六条","txt":"当事人对公安机关依照本办法作出的具体行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":27,"n":"第二十七条","txt":"公安机关及其人民警察在工作中，有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）为不符合申领条件的单位发证的； （二）除不可抗力外，不按本办法规定的时限办理许可证件的； （三）索取、收受当事人贿赂或者谋取其他利益的； （四）对违反本办法的行为不依法追究法律责任的； （五）违反法律、法规、本办法的规定实施处罚或者收取费用的； （六）其他滥用职权、玩忽职守、徇私舞弊的。"},{"i":28,"n":"第二十八条","txt":"本办法规定的《剧毒化学品购买凭证》、《剧毒化学品准购证》和《剧毒化学品公路运输通行证》由公安部统一印制；其他法律文书式样由公安部制定，各发证公安机关自行印制；各类申请书式样由公安部制定，申领单位根据需要自行印制。"},{"i":29,"n":"第二十九条","txt":"在中华人民共和国境内通过城市道路运输剧毒化学品的，参照本办法关于通过公路运输剧毒化学品的规定执行。"},{"i":30,"n":"第三十条","txt":"本办法自二○○五年八月一日起施行。"}],"taiwanyuchuantingbodianbianfangzhianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强台湾渔船停泊点的边防治安管理，促进两岸同胞交往，维护沿海、港口的治安秩序，根据国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"对台湾渔船及船员的边防治安管理，遵循确保安全、方便往来的原则。"},{"i":3,"n":"第三条","txt":"台湾渔船需要在祖国大陆（以下简称大陆）沿岸停靠的，应当在国务院主管部门批准的台湾渔船停泊点（以下简称停泊点）停泊。因遇台风等不可抗力的事由或者不可预见的紧急情况，台湾渔船可以就近在国家有关部门批准的台湾渔船避风点停泊。不可抗力的事由或者不可预见的紧急情况消除后，应当立即航离。"},{"i":4,"n":"第四条","txt":"凡在停泊点停泊的台湾渔船及随船人员，除法律、法规另有规定外，应当遵守本办法。"},{"i":5,"n":"第五条","txt":"台湾渔船及船员在大陆沿岸停靠期间的边防治安管理工作由公安边防部门负责。"},{"i":6,"n":"第六条","txt":"台湾渔船进人停泊点后，船长应当及时向停泊点边防工作站申报，出示船舶证书、船员证书或其他有效证件，说明来靠原因及泊港时间，接受边防执勤人员的检查。"},{"i":7,"n":"第七条","txt":"边防工作站对进港的台湾渔船，应查验其船舶证书、船员证书及其他有效证件，核对人数；台湾渔船泊港期间其船舶证书由边防工作站代为保管，离港时发还。 边防工作站对台湾渔船实施检查时，应当对船体及船上货物、行李物品进行重点检查，台湾渔船的船长应当在现场协助边防执勤人员进行检查。 边防执勤人员对台湾渔船实施检查时，应当出示其执勤证件。"},{"i":8,"n":"第八条","txt":"台湾渔船泊港期间，必须在指定的停泊区（段）锚泊，接受边防工作站的监护和管理。"},{"i":9,"n":"第九条","txt":"台湾渔船泊港期间，除遵守国家法律、法规外还应当遵守下列规定： （一）不得悬挂、显示有损一个中国原则和祖国统一的标志； （二）不得播放分裂祖国、破坏祖国统一内容的广播； （三）不得擅自启用电台； （四）不得传播、散发各种违禁物品及不利两岸正常往来的物品，不得携带违禁物品上岸； （五）不得擅自引带大陆居民登船； （六）不得擅自搭靠其他船舶； （七）不得从事其他有损两岸关系的活动。"},{"i":10,"n":"第十条","txt":"台湾渔船泊港期间，国家有关部门的工作人员需要登船执行公务的，应当事先通报边防工作站边防执勤人员凭其本人有效证件放行；其他人员需要登轮的须经边防工作站同意，并办理临时登轮手续后，方可登轮。 大陆船舶需要搭靠台湾渔船的应当由船长向边防工作站申请办理搭靠手续。"},{"i":11,"n":"第十一条","txt":"台湾渔船上的台湾居民需要登陆的，应当持船员证书或其他有效身份证件向边防工作站申请办理《台湾居民登陆证》，在港口所在的县（市、区）范围内活动，不得进人军事禁区和军事管理区。 《台湾居民登陆证》的有效期不超过本航次航行期限。登陆的台湾居民应当在证件有效期内返回登船，并从原上岸停泊点乘原船离港。特殊原因需要延期或改乘其他台湾船舶的，应当在证件有效期内向上岸停泊点所在地县（市）公安边防部门提出申请，经地（市）公安边防部门批准后，由上岸停泊点边防工作站核发证件。"},{"i":12,"n":"第十二条","txt":"台湾渔船上的人员有下列情形之一的，不予批准上岸： （一）无证件证明是台湾居民的； （二）提供假证件的； （三）依法被限制或者禁止入境的。"},{"i":13,"n":"第十三条","txt":"台湾渔船泊港期间需要从事小额贸易、招聘短期劳务人员、处理海事或渔事纠纷等事务的，由有关部门按照规定办理。"},{"i":14,"n":"第十四条","txt":"应聘到台湾渔船从事近海作业的大陆劳务人员必须持《对台劳务人员登轮作业证》。申办《对台劳务人员登轮作业证》必须具有《渔业船员专业培训合格证》、《外派劳务人员培训合格证》、《出海船民证》和本人身份证件。首次登台轮作业的须持常住户口所在地公安派出所出具没有本办法第十六条规定情形的证明。"},{"i":15,"n":"第十五条","txt":"大陆劳务人员申办《对台劳务人员登轮作业证》，应当由对外贸易经济合作部核准的经营公司凭地方外经贸主管部门的批文和与台湾渔业公司或船东、船长签订的合同及第十四条所规定的相关证件，到经营公司所在地县（市）公安边防部门办理。"},{"i":16,"n":"第十六条","txt":"大陆劳务人员有下列情形之一的，不予办理《对台劳务人员登轮作业证》： （一）刑事案件的被告人或者犯罪嫌疑人； （二）人民法院通知有未了结民事案件不能出海的； （三）被判处刑罚正在服刑的； （四）出海后有可能给国家安全造成危害或者对国家利益造成重大损失的； （五）身体和精神状况明显不适合登船作业的。"},{"i":17,"n":"第十七条","txt":"大陆劳务人员应当在指定的停泊点登、离台湾渔船，接受边防工作站的检查和管理。"},{"i":18,"n":"第十八条","txt":"台湾渔船的船长、船员对受聘大陆劳务人员不得歧视、体罚；不得擅自将大陆劳务人员带至台湾地区或者其他国家和地区的港口登岸；劳务合作期满，应当及时将大陆劳务人员送回原登轮港。"},{"i":19,"n":"第十九条","txt":"台湾渔船离港前应当向边防工作站提出申请，经边防执勤人员检查，核对证件、人员，交纳监护费，缴回《台湾居民登陆证》后，方可离港。已办理离港手续的，不得无故滞留。"},{"i":20,"n":"第二十条","txt":"台湾居民遗失《台湾居民登陆证》，大陆劳务人员遗失《对台劳务人员登轮作业证》，应当及时向原签发证件部门报失。经调查核实无误后，由原签发证件部门补发。"},{"i":21,"n":"第二十一条","txt":"应聘到台湾渔船从事近海作业的大陆劳务人员有下列行为之一的，对其处以人民币（或等值外币，以下同）500元以下的罚款： （一）申请《对台劳务人员登轮作业证》时编造虚假情况，提供假证明的； （二）涂改《对台劳务人员登轮作业证》或将证件转让他人使用的； （三）未在指定的停泊点登、离台湾渔船的； （四）携带违禁物品及国家机密资料，尚未构成犯罪的。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定有下列行为之一的，对台湾渔船船长和直接责任人处以警告，责令其改正，或处以人民币1000元以下的罚款。拒不改正的，不予停泊或强制航离： （一）擅自启用电台的； （二）在港内播放分裂祖国、破坏祖国统一内容的广播的； （三）停泊期间，悬挂、显示有损一个中国原则和祖国统一标志的； （四）从事其他有损两岸关系的活动的。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定有下列行为之一的，对台湾居民处以人民币1000元以下的罚款，同时，对船长处以人民币2000元以下的罚款： （一）擅自引带大陆居民登船的； （二）未经批准擅自上岸的； （三）涂改证件或者将证件转让他人使用的； （四）持《台湾居民登陆证》登陆人员，不按规定时间返回或者超出指定范围活动的； （五）在沿海、港口传播、散发违禁物品及不利两岸正常往来物品或携带违禁物品上岸的； （六）体罚、殴打大陆劳务人员，未造成轻微伤害的； （七）不服从管理，扰乱停泊点管理秩序的。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定有下列行为之一的，对台湾渔船船长处以人民币3000元以下的罚款： （一）未按规定办理进出港手续的； （二）泊港期间擅自搭靠其他船舶的； （三）擅自雇用大陆居民登船作业的； （四）擅自将大陆劳务人员带至台湾地区或者其他国家和地区港口登陆的； （五）未经边防部门检查擅自离港的； （六）办理离港手续后无故滞留的。"},{"i":25,"n":"第二十五条","txt":"台湾渔船无不可抗力的事由或者不可预见的紧急情况，不在指定的停泊点、避风点停泊的，对其船长处以人民币10000元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"对违反本办法的处罚，警告、人民币200元以下的罚款，由边防工作站（边防派出所）决定；人民币200元以上、3000元以下的罚款由县（市）公安边防部门决定；人民币3000元以上、10000元以下的罚款由地（市）公安边防部门决定。"},{"i":27,"n":"第二十七条","txt":"台湾渔船及随船人员在大陆沿岸停靠期间有其他违法犯罪行为的，由有关部门依照有关法律、法规处理。"},{"i":28,"n":"第二十八条","txt":"公安边防执法人员违反本办法规定，滥用职权、徇私舞弊或者有其他违法失职行为，情节轻微的，给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本办法所称“台湾渔船”，是指航靠大陆、在台湾地区注册具有台湾地区港籍与船籍的渔船、小额贸易船等船舶。"},{"i":30,"n":"第三十条","txt":"《台湾居民登陆证》、《对台劳务人员登轮作业证》由公安部统一制作。"},{"i":31,"n":"第三十一条","txt":"本办法中的“等值外币’，是指处罚裁决当日，按照国家外汇管理的规定，相同罚款数额的人民币可兑换的外国货币。"},{"i":32,"n":"第三十二条","txt":"本办法中的以下，包括本数在内。"},{"i":33,"n":"第三十三条","txt":"本办法自2002年3月1日起施行。"}],"xiduchengyinrendingbanfa":[{"i":1,"n":"第一条","txt":"为规范吸毒成瘾认定工作，科学认定吸毒成瘾人员，依法对吸毒成瘾人员采取戒毒措施和提供戒毒治疗，根据《中华人民共和国禁毒法》、《戒毒条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称吸毒成瘾，是指吸毒人员因反复使用毒品而导致的慢性复发性脑病，表现为不顾不良后果、强迫性寻求及使用毒品的行为，常伴有不同程度的个人健康及社会功能损害。"},{"i":3,"n":"第三条","txt":"本办法所称吸毒成瘾认定，是指公安机关或者其委托的戒毒医疗机构通过对吸毒人员进行人体生物样本检测、收集其吸毒证据或者根据生理、心理、精神的症状、体征等情况，判断其是否成瘾以及是否成瘾严重的工作。 本办法所称戒毒医疗机构，是指符合《戒毒医疗服务管理暂行办法》规定的专科戒毒医院和设有戒毒治疗科室的其他医疗机构。"},{"i":4,"n":"第四条","txt":"公安机关在执法活动中发现吸毒人员，应当进行吸毒成瘾认定；因技术原因认定有困难的，可以委托有资质的戒毒医疗机构进行认定。"},{"i":5,"n":"第五条","txt":"承担吸毒成瘾认定工作的戒毒医疗机构，由省级卫生计生行政部门会同同级公安机关指定。"},{"i":6,"n":"第六条","txt":"公安机关认定吸毒成瘾，应当由两名以上人民警察进行，并在作出人体生物样本检测结论的二十四小时内提出认定意见，由认定人员签名，经所在单位负责人审核，加盖所在单位印章。 有关证据材料，应当作为认定意见的组成部分。"},{"i":7,"n":"第七条","txt":"吸毒人员同时具备以下情形的，公安机关认定其吸毒成瘾： （一）经血液、尿液和唾液等人体生物样本检测证明其体内含有毒品成分； （二）有证据证明其有使用毒品行为； （三）有戒断症状或者有证据证明吸毒史，包括曾经因使用毒品被公安机关查处、曾经进行自愿戒毒、人体毛发样品检测出毒品成分等情形。 戒断症状的具体情形，参照卫生部制定的《阿片类药物依赖诊断治疗指导原则》和《苯丙胺类药物依赖诊断治疗指导原则》、《氯胺酮依赖诊断治疗指导原则》确定。"},{"i":8,"n":"第八条","txt":"吸毒成瘾人员具有下列情形之一的，公安机关认定其吸毒成瘾严重： （一）曾经被责令社区戒毒、强制隔离戒毒（含《禁毒法》实施以前被强制戒毒或者劳教戒毒）、社区康复或者参加过戒毒药物维持治疗，再次吸食、注射毒品的； （二）有证据证明其采取注射方式使用毒品或者至少三次使用累计涉及两类以上毒品的； （三）有证据证明其使用毒品后伴有聚众淫乱、自伤自残或者暴力侵犯他人人身、财产安全或者妨害公共安全等行为的。"},{"i":9,"n":"第九条","txt":"公安机关在吸毒成瘾认定过程中实施人体生物样本检测，依照公安部制定的《吸毒检测程序规定》的有关规定执行。"},{"i":10,"n":"第十条","txt":"公安机关承担吸毒成瘾认定工作的人民警察，应当同时具备以下条件： （一）具有二级警员以上警衔及两年以上相关执法工作经历； （二）经省级公安机关、卫生计生行政部门组织培训并考核合格。"},{"i":11,"n":"第十一条","txt":"公安机关委托戒毒医疗机构进行吸毒成瘾认定的，应当在吸毒人员末次吸毒的七十二小时内予以委托并提交委托函。超过七十二小时委托的，戒毒医疗机构可以不予受理。"},{"i":12,"n":"第十二条","txt":"承担吸毒成瘾认定工作的戒毒医疗机构及其医务人员，应当依照《戒毒医疗服务管理暂行办法》的有关规定进行吸毒成瘾认定工作。"},{"i":13,"n":"第十三条","txt":"戒毒医疗机构认定吸毒成瘾，应当由两名承担吸毒成瘾认定工作的医师进行。"},{"i":14,"n":"第十四条","txt":"承担吸毒成瘾认定工作的医师，应当同时具备以下条件： （一）符合《戒毒医疗服务管理暂行办法》的有关规定； （二）从事戒毒医疗工作不少于三年； （三）具有中级以上专业技术职务任职资格。"},{"i":15,"n":"第十五条","txt":"戒毒医疗机构对吸毒人员采集病史和体格检查时，委托认定的公安机关应当派有关人员在场协助。"},{"i":16,"n":"第十六条","txt":"戒毒医疗机构认为需要对吸毒人员进行人体生物样本检测的，委托认定的公安机关应当协助提供现场采集的检测样本。 戒毒医疗机构认为需要重新采集其他人体生物检测样本的，委托认定的公安机关应当予以协助。"},{"i":17,"n":"第十七条","txt":"戒毒医疗机构使用的检测试剂，应当是经国家食品药品监督管理局批准的产品，并避免与常见药物发生交叉反应。"},{"i":18,"n":"第十八条","txt":"戒毒医疗机构及其医务人员应当依照诊疗规范、常规和有关规定，结合吸毒人员的病史、精神症状检查、体格检查和人体生物样本检测结果等，对吸毒人员进行吸毒成瘾认定。"},{"i":19,"n":"第十九条","txt":"戒毒医疗机构应当自接受委托认定之日起三个工作日内出具吸毒成瘾认定报告，由认定人员签名并加盖戒毒医疗机构公章。认定报告一式二份，一份交委托认定的公安机关，一份留存备查。"},{"i":20,"n":"第二十条","txt":"委托戒毒医疗机构进行吸毒成瘾认定的费用由委托单位承担。"},{"i":21,"n":"第二十一条","txt":"各级公安机关、卫生计生行政部门应当加强对吸毒成瘾认定工作的指导和管理。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人不得违反规定泄露承担吸毒成瘾认定工作相关工作人员及被认定人员的信息。"},{"i":23,"n":"第二十三条","txt":"公安机关、戒毒医疗机构以及承担认定工作的相关人员违反本办法规定的，依照有关法律法规追究责任。"},{"i":24,"n":"第二十四条","txt":"本办法所称的两类及以上毒品是指阿片类（包括鸦片、吗啡、海洛因、杜冷丁等），苯丙胺类（包括各类苯丙胺衍生物），大麻类，可卡因类，以及氯胺酮等其他类毒品。"},{"i":25,"n":"第二十五条","txt":"本办法自2011年4月1日起施行。"}],"xidujiancechengxuguiding":[{"i":1,"n":"第一条","txt":"为规范公安机关吸毒检测工作，保护当事人的合法权益，根据《中华人民共和国禁毒法》、《戒毒条例》等有关法律规定，制定本规定。"},{"i":2,"n":"第二条","txt":"吸毒检测是运用科学技术手段对涉嫌吸毒的人员进行生物医学检测，为公安机关认定吸毒行为提供科学依据的活动。 吸毒检测的对象，包括涉嫌吸毒的人员，被决定执行强制隔离戒毒的人员，被公安机关责令接受社区戒毒和社区康复的人员，以及戒毒康复场所内的戒毒康复人员。"},{"i":3,"n":"第三条","txt":"吸毒检测分为现场检测、实验室检测、实验室复检。"},{"i":4,"n":"第四条","txt":"现场检测由县级以上公安机关或者其派出机构进行。 实验室检测由县级以上公安机关指定的取得检验鉴定机构资格的实验室或者有资质的医疗机构进行。 实验室复检由县级以上公安机关指定的取得检验鉴定机构资格的实验室进行。 实验室检测和实验室复检不得由同一检测机构进行。"},{"i":5,"n":"第五条","txt":"吸毒检测样本的采集应当使用专用器材。现场检测器材应当是国家主管部门批准生产或者进口的合格产品。"},{"i":6,"n":"第六条","txt":"检测样本为采集的被检测人员的尿液、血液、唾液或者毛发等生物样本。"},{"i":7,"n":"第七条","txt":"被检测人员拒绝接受检测的，经县级以上公安机关或者其派出机构负责人批准，可以对其进行强制检测。"},{"i":8,"n":"第八条","txt":"公安机关采集、送检、检测样本，应当由两名以上工作人员进行；采集女性被检测人尿液检测样本，应当由女性工作人员进行。 采集的检测样本经现场检测结果为阳性的，应当分别保存在A、B两个样本专用器材中并编号，由采集人和被采集人共同签字封存，采用检材适宜的条件予以保存，保存期不得少于六个月。"},{"i":9,"n":"第九条","txt":"现场检测应当出具检测报告，由检测人签名，并加盖检测的公安机关或者其派出机构的印章。 现场检测结果应当当场告知被检测人，并由被检测人在检测报告上签名。被检测人拒不签名的，公安民警应当在检测报告上注明。"},{"i":10,"n":"第十条","txt":"被检测人对现场检测结果有异议的，可以在被告知检测结果之日起的三日内，向现场检测的公安机关提出实验室检测申请。 公安机关应当在接到实验室检测申请后的三日内作出是否同意进行实验室检测的决定，并将结果告知被检测人。"},{"i":11,"n":"第十一条","txt":"公安机关决定进行实验室检测的，应当在作出实验室检测决定后的三日内，将保存的A样本送交县级以上公安机关指定的具有检验鉴定资格的实验室或者有资质的医疗机构。"},{"i":12,"n":"第十二条","txt":"接受委托的实验室或者医疗机构应当在接到检测样本后的三日内出具实验室检测报告，由检测人签名，并加盖检测机构公章后，送委托实验室检测的公安机关。公安机关收到检测报告后，应当在二十四小时内将检测结果告知被检测人。"},{"i":13,"n":"第十三条","txt":"被检测人对实验室检测结果有异议的，可以在被告知检测结果后的三日内，向现场检测的公安机关提出实验室复检申请。 公安机关应当在接到实验室复检申请后的三日内作出是否同意进行实验室复检的决定，并将结果告知被检测人。"},{"i":14,"n":"第十四条","txt":"公安机关决定进行实验室复检的，应当在作出实验室复检决定后的三日内，将保存的B样本送交县级以上公安机关指定的具有检验鉴定资格的实验室。"},{"i":15,"n":"第十五条","txt":"接受委托的实验室应当在接到检测样本后的三日内出具检测报告，由检测人签名，并加盖专用鉴定章后，送委托实验室复检的公安机关。公安机关收到检测报告后，应当在二十四小时内将检测结果告知被检测人。"},{"i":16,"n":"第十六条","txt":"接受委托的实验室检测机构或者实验室复检机构认为送检样本不符合检测条件的，应当报县级以上公安机关或者其派出机构负责人批准后，由公安机关根据检测机构的意见，重新采集检测样本。"},{"i":17,"n":"第十七条","txt":"被检测人是否申请实验室检测和实验室复检，不影响案件的正常办理。 公安机关认为必要时，可以直接决定进行实验室检测和实验室复检。"},{"i":18,"n":"第十八条","txt":"现场检测费用、实验室检测、实验室复检的费用由公安机关承担。"},{"i":19,"n":"第十九条","txt":"公安机关、鉴定机构或者其工作人员违反本规定，有下列情形之一的，应当依照有关规定，对相关责任人给予纪律处分或者行政处分；构成犯罪的，依法追究刑事责任： （一）因严重不负责任给当事人合法权益造成重大损害的； （二）故意提供虚假检测报告的； （三）法律、行政法规规定的其他情形。"},{"i":20,"n":"第二十条","txt":"吸毒检测的技术标准由公安部另行制定。"},{"i":21,"n":"第二十一条","txt":"本规定所称“以上”、“内”皆包含本级或者本数，“日”是指工作日。"},{"i":22,"n":"第二十二条","txt":"本规定自2010年1月1日起施行。"}],"chengshirenminjingchaxunluoguiding":[{"i":1,"n":"第一条","txt":"为保障城市人民警察在巡逻执勤中依法履行职责，维护公共安全和治安秩序，为公民提供救助服务，特制定本规定。"},{"i":2,"n":"第二条","txt":"人民警察巡逻执勤工作，由城市公安机关依照本规定，结合当地实际情况统一组织实施。"},{"i":3,"n":"第三条","txt":"人民警察巡逻执勤，采取徒步为主，自行车、机动车相结合的方式。 城市公安局可以根据实际情况划定巡逻警区。"},{"i":4,"n":"第四条","txt":"人民警察在巡逻执勤中履行以下职责： （一）维护警区内的治安秩序； （二）预防和制止违反治安管理的行为； （三）预防和制止犯罪行为； （四）警戒突发性治安事件现场，疏导群众，维持秩序； （五）参加处理非法集会、游行、示威活动； （六）参加处置灾害事故，维持秩序，抢救人员和财物； （七）维护交通秩序； （八）制止妨碍国家工作人员依法执行职务的行为； （九）接受公民报警； （十）劝解、制止在公共场所发生的民间纠纷； （十一）制止精神病人、醉酒人的肇事行为； （十二）为行人指路，救助突然受伤、患病、遇险等处于无援状态的人，帮助遇到困难的残疾人、老人和儿童； （十三）受理拾遗物品，设法送还失主或送交拾物招领部门； （十四）巡察警区安全防范情况，提示沿街有关单位、居民消除隐患； （十五）纠察人民警察警容风纪； （十六）执行法律、法规规定由人民警察执行的其他任务。"},{"i":5,"n":"第五条","txt":"人民警察在巡逻执勤中依法行使以下权力： （一）盘查有违法犯罪嫌疑的人员，检查涉嫌车辆、物品； （二）查验居民身份证； （三）对现行犯罪人员、重大犯罪嫌疑人员或者在逃的案犯，可以依法先行拘留或者采取其他强制措施； （四）纠正违反道路交通管理的行为； （五）对违反治安管理的人，可以依照《中华人民共和国治安管理处罚条例》的规定，执行处罚； （六）在追捕、救护、抢险等紧急情况下，经出示证件，可以优先使用机关、团体和企业、事业单位以及公民个人的交通、通讯工具。用后应当及时归还，并支付适当费用，造成损坏的应当赔偿； （七）行使法律、法规规定的其他职权。"},{"i":6,"n":"第六条","txt":"在巡逻执勤中遇有重要情况，应当立即报告。对需要采取紧急措施的案件、事件和事故，应当进行先期处置。 对需要查处的案件、事件和事故应当移交公安机关主管部门处理。"},{"i":7,"n":"第七条","txt":"人民警察巡逻执勤时必须做到： （一）穿着警服，系武装带，佩带枪支、警械和通讯工具； （二）恪尽职守，遵守法律和纪律； （三）严格执法，秉公办事，不得超越或滥用职权； （四）举止规范，文明执勤，礼貌待人。"},{"i":8,"n":"第八条","txt":"人民警察在巡逻执勤中应当接受公民的监督；公民发现人民警察在巡逻执勤中有违法违纪行为的，有权提出控告和检举。"},{"i":9,"n":"第九条","txt":"机关、团体和企业、事业单位以及公民应当支持巡逻警察的执勤，服从巡逻警察的管理，不得阻碍其依法执行职务。"},{"i":10,"n":"第十条","txt":"各省、自治区、直辖市公安厅、局可以根据本规定，结合当地的实际情况制定实施细则。"},{"i":11,"n":"第十一条","txt":"本规定自发布之日起施行。"}],"waiguorenzaizhongguoyongjiujuliushenpiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范外国人在中国永久居留审批管理工作，根据《中华人民共和国外国人入境出境管理法》及其实施细则的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"外国人在中国永久居留是指外国人在中国居留期限不受限制。"},{"i":3,"n":"第三条","txt":"《外国人永久居留证》是获得在中国永久居留资格的外国人在中国境内居留的合法身份证件，可以单独使用。"},{"i":4,"n":"第四条","txt":"获得在中国永久居留资格的外国人，凭有效护照和《外国人永久居留证》出入中国国境。"},{"i":5,"n":"第五条","txt":"受理外国人在中国永久居留申请的机关是设区的市级人民政府公安机关，直辖市公安分、县局；审核外国人在中国永久居留申请的机关是各省、自治区、直辖市公安厅、局；审批外国人在中国永久居留申请的机关是公安部。"},{"i":6,"n":"第六条","txt":"申请在中国永久居留的外国人应当遵守中国法律，身体健康，无犯罪记录，并符合下列条件之一： （一）在中国直接投资、连续三年投资情况稳定且纳税记录良好的； （二）在中国担任副总经理、副厂长等职务以上或者具有副教授、副研究员等副高级职称以上以及享受同等待遇，已连续任职满四年、四年内在中国居留累计不少于三年且纳税记录良好的； （三）对中国有重大、突出贡献以及国家特别需要的； （四）本款第一项、第二项、第三项所指人员的配偶及其未满18周岁的未婚子女； （五）中国公民或者在中国获得永久居留资格的外国人的配偶，婚姻关系存续满五年、已在中国连续居留满五年、每年在中国居留不少于九个月且有稳定生活保障和住所的； （六）未满18周岁未婚子女投靠父母的； （七）在境外无直系亲属，投靠境内直系亲属，且年满60周岁、已在中国连续居留满五年、每年在中国居留不少于九个月并有稳定生活保障和住所的。 本条所指年限均指申请之"},{"i":7,"n":"第七条","txt":"本办法第六条第一款第一项所指的外国人，其在中国投资实际缴付的注册资本金应当符合下列条件之一： （一）在国家颁布的《外商投资产业指导目录》鼓励类产业投资合计50万美元以上； （二）在中国西部地区和国家扶贫开发工作重点县投资合计50万美元以上； （三）在中国中部地区投资合计100万美元以上； （四）在中国投资合计200万美元以上。"},{"i":8,"n":"第八条","txt":"本办法第六条第一款第二项所指的外国人，其任职单位应当符合下列条件之一： （一）国务院各部门或者省级人民政府所属的机构； （二）重点高等学校； （三）执行国家重点工程项目或者重大科研项目的企业、事业单位； （四）高新技术企业、鼓励类外商投资企业、外商投资先进技术企业或者外商投资产品出口企业。"},{"i":9,"n":"第九条","txt":"申请人申请时需如实填写《外国人在中国永久居留申请表》，并提交下列材料： （一）有效的外国护照或者能够代替护照的证件； （二）中国政府指定的卫生检疫部门出具的或者经中国驻外使、领馆认证的外国卫生医疗机构签发的健康证明书； （三）经中国驻外使、领馆认证的国外无犯罪记录证明； （四）四张二英寸近期正面免冠彩色照片； （五）本办法规定的其他有关材料。"},{"i":10,"n":"第十条","txt":"本办法第六条第一款第一项所指人员申请时还需提交外商投资企业批准证书、登记证明以及联合年检证明、验资报告、个人完税证明。 鼓励类外商投资企业还应当提交国家鼓励发展的外商投资项目确认书。"},{"i":11,"n":"第十一条","txt":"本办法第六条第一款第二项所指人员申请时还需提交下列材料： （一）任职单位出具的本人职务或者职称证明； （二）《外国专家证》或者《外国人就业证》； （三）任职单位的登记证明以及年检证明、个人完税证明；任职单位是外商投资企业的，还需提交外商投资企业批准证书和联合年检证明； （四）在执行国家重点工程项目或者重大科研项目的企业、事业单位中任职的人员需提交省、部级政府主管部门出具的项目证明文件；在高新技术企业中任职的人员需提交高新技术企业证书；在鼓励类外商投资企业、外商投资先进技术企业或者外商投资产品出口企业中任职的人员需提交国家鼓励发展的外商投资项目确认书或者外商投资先进技术企业确认书或者外商投资产品出口企业确认书。"},{"i":12,"n":"第十二条","txt":"本办法第六条第一款第三项所指人员申请时还需提交中国政府主管部门出具的推荐函及有关证明。"},{"i":13,"n":"第十三条","txt":"本办法第六条第一款第四项所指人员申请时，属于配偶的，还需提交婚姻证明；属于未满18周岁未婚子女的，还需提交本人出生证明或者亲子关系证明；属收养关系的，还需提交收养证明。外国有关机构出具的上述证明需经中国驻该国使、领馆认证。"},{"i":14,"n":"第十四条","txt":"本办法第六条第一款第五项所指人员申请时还需提交其中国籍配偶的常住户籍证明或者其外国籍配偶的《外国人永久居留证》、婚姻证明、经公证的生活保障证明及房屋租赁或者产权证明。外国有关机构出具的上述证明需经中国驻该国使、领馆认证。"},{"i":15,"n":"第十五条","txt":"本办法第六条第一款第六项所指人员申请时还需提交其中国籍父母的常住户籍证明或者外国籍父母的《外国人永久居留证》、本人出生证明或者亲子关系证明；属收养关系的，还需提交收养证明。外国有关机构出具的上述证明需经中国驻该国使、领馆认证。"},{"i":16,"n":"第十六条","txt":"本办法第六条第一款第七项所指人员申请时还需提交被投靠的中国公民常住户籍证明或者外国人的《外国人永久居留证》、经公证的亲属关系证明以及投靠人国外无直系亲属关系证明、经公证的投靠人经济来源证明或者被投靠人经济担保证明、经公证的投靠人或者被投靠人的房屋租赁或者产权证明。外国有关机构出具的上述证明需经中国驻该国使、领馆认证。"},{"i":17,"n":"第十七条","txt":"外国人申请在中国永久居留，由本人或者未满18周岁未婚子女的父母或者被委托人向主要投资地或者长期居留地的设区的市级人民政府公安机关或者直辖市公安分、县局提出申请。 由被委托人代为申请的，需提交申请人出具的委托书。申请人在国外出具的委托书，需经中国驻该国使、领馆认证。"},{"i":18,"n":"第十八条","txt":"公安机关自受理外国人在中国永久居留的申请之日起六个月以内做出批准或者不批准的决定。"},{"i":19,"n":"第十九条","txt":"被批准在中国永久居留的外国人，由公安部签发《外国人永久居留证》；申请人在境外的，由公安部发给《外国人永久居留身份确认表》，申请人持《外国人永久居留身份确认表》到中国驻外使、领馆办理“D ”字签证，入境后30日以内向受理其申请的公安机关领取《外国人永久居留证》。"},{"i":20,"n":"第二十条","txt":"被批准在中国永久居留的外国人，每年在中国累计居留不得少于三个月。确因实际需要每年不能在中国累计居留满三个月的，需经长期居留地省、自治区、直辖市公安厅、局批准，但五年内在中国累计居留不得少于一年。"},{"i":21,"n":"第二十一条","txt":"《外国人永久居留证》的有效期为五年或者十年。 被批准在中国永久居留的未满十八周岁的外国人，发给有效期为五年的《外国人永久居留证》；被批准在中国永久居留的十八周岁以上的外国人， 发给有效期为十年的《外国人永久居留证》。"},{"i":22,"n":"第二十二条","txt":"《外国人永久居留证》有效期满、内容变更、损坏或者遗失的，持证人应当向其长期居留地的设区的市级人民政府公安机关或者直辖市公安分、县局申请换发或者补发。公安机关经审核对没有丧失在中国永久居留资格规定情形的，一个月以内换发或者补发证件。"},{"i":23,"n":"第二十三条","txt":"持有《外国人永久居留证》的外国人应当在证件有效期满前一个月以内申请换发；证件内容变更的，应当在情况变更后一个月以内申请换发；证件损坏或者遗失的，应当及时申请换发或者补发。"},{"i":24,"n":"第二十四条","txt":"具有在中国永久居留资格的外国人有下列情形之一的，公安部可以取消其在中国永久居留资格，同时收缴其所持《外国人永久居留证》或者宣布作废： （一） 可能对国家安全和利益造成危害的； （二）被人民法院判处驱逐出境的； （三）通过提供虚假材料等非法手段骗取在中国永久居留资格的； （四）未经批准每年在中国累计居留不满三个月或者五年内在中国累计居留不满一年的。"},{"i":25,"n":"第二十五条","txt":"本办法实施前被批准在中国永久居留的外国人，应当在本办法实施之日起六个月以内到原居留证件签发地或者长期居留地的设区的市级人民政府公安机关或者直辖市公安分、县局换领《外国人永久居留证》。"},{"i":26,"n":"第二十六条","txt":"申请在中国永久居留以及签发、换发、补发《外国人永久居留证》，有关收费项目和标准按照国务院价格和财政主管部门的规定执行。"},{"i":27,"n":"第二十七条","txt":"本办法中下列用语的含义： （一）“直系亲属”指父母（配偶的父母）、祖父母（外祖父母）、已满18周岁的成年子女及其配偶、已满18周岁的成年孙子女（外孙子女）及其配偶； （二）“以上”、“以内”皆包括本数。"},{"i":28,"n":"第二十八条","txt":"本办法由公安部、外交部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自发布之日起施行。"}],"yulechangsuozhianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强娱乐场所治安管理，维护娱乐场所经营者、消费者和从业人员的合法权益，维护社会治安秩序，保障公共安全，根据《中华人民共和国治安管理处罚法》、《娱乐场所管理条例》等法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"娱乐场所治安管理应当遵循公安机关治安部门归口管理和辖区公安派出所属地管理相结合，属地管理为主的原则。 公安机关对娱乐场所进行治安管理，应当严格、公正、文明、规范。"},{"i":3,"n":"第三条","txt":"娱乐场所法定代表人、主要负责人是维护本场所治安秩序的第一责任人。"},{"i":4,"n":"第四条","txt":"娱乐场所领取营业执照后，应当在15日内向所在地县（市）公安局、城市公安分局治安部门备案；县（市）公安局、城市公安分局治安部门受理备案后，应当在5日内将备案资料通报娱乐场所所在辖区公安派出所。 县（市）公安局、城市公安分局治安部门对备案的娱乐场所应当统一建立管理档案。"},{"i":5,"n":"第五条","txt":"娱乐场所备案项目包括： （一）名称； （二）经营地址、面积、范围； （三）地理位置图和内部结构平面示意图； （四）法定代表人和主要负责人姓名、身份证号码、联系方式； （五）与保安服务企业签订的保安服务合同及保安人员配备情况； （六）核定的消费人数； （七）娱乐经营许可证号、营业执照号及登记日期； （八）监控、安检设备安装部位平面图及检测验收报告。 设有电子游戏机的游艺娱乐场所备案时，除符合前款要求外，还应当提供电子游戏机机型及数量情况。"},{"i":6,"n":"第六条","txt":"娱乐场所备案时，应当提供娱乐经营许可证、营业执照及消防、卫生、环保等部门批准文件的复印件。"},{"i":7,"n":"第七条","txt":"娱乐场所备案项目发生变更的，应当自变更之日起15日内向原备案公安机关备案。"},{"i":8,"n":"第八条","txt":"歌舞娱乐场所包厢、包间内不得设置阻碍展现室内整体环境的屏风、隔扇、板壁等隔断，不得以任何名义设立任何形式的房中房（卫生间除外）。"},{"i":9,"n":"第九条","txt":"歌舞娱乐场所的包厢、包间内的吧台、餐桌等物品不得高于1.2米。 包厢、包间的门窗，距地面1.2米以上应当部分使用透明材质。透明材质的高度不小于0.4米，宽度不小于0.2米，能够展示室内消费者娱乐区域整体环境。 营业时间内，歌舞娱乐场所包厢、包间门窗透明部分不得遮挡。"},{"i":10,"n":"第十条","txt":"歌舞娱乐场所包厢、包间内不得安装门锁、插销等阻碍他人自由进出包厢、包间的装置。"},{"i":11,"n":"第十一条","txt":"歌舞娱乐场所营业大厅、包厢、包间内禁止设置可调试亮度的照明灯。照明灯在营业时间内不得关闭。"},{"i":12,"n":"第十二条","txt":"歌舞娱乐场所应当在营业场所出入口、消防安全疏散出入口、营业大厅通道、收款台前安装闭路电视监控设备。"},{"i":13,"n":"第十三条","txt":"歌舞娱乐场所安装的闭路电视监控设备应当符合视频安防监控系统相关国家或行业标准要求。 闭路电视监控设备的压缩格式为H.264或者MPEG-4,录像图像分辨率不低于4CIF（704×576）或者D1 (720×576）；保障视频录像实时（每秒不少于25帧），支持视频移动侦测功能；图像回放效果要求清晰、稳定、逼真，能够通过LAN、WAN或者互联网与计算机相连，实现远程监视、放像、备份及升级，回放图像水平分辨力不少于300TVL。"},{"i":14,"n":"第十四条","txt":"歌舞娱乐场所应当设置闭路电视监控设备监控室，由专人负责值守，保障设备在营业时间内正常运行，不得中断、删改或者挪作他用。"},{"i":15,"n":"第十五条","txt":"营业面积1000平方米以下的迪斯科舞厅应当配备手持式金属探测器，营业面积超过1000平方米以上的应当配备通过式金属探测门和微剂量X射线安全检查设备等安全检查设备。 手持式金属探测器、通过式金属探测门、微剂量X射线安全检查设备应当符合国家或者行业标准要求。"},{"i":16,"n":"第十六条","txt":"迪斯科舞厅应当配备专职安全检查人员，安全检查人员不得少于2名，其中女性安全检查人员不得少于1名。"},{"i":17,"n":"第十七条","txt":"娱乐场所应当在营业场所大厅、包厢、包间内的显著位置悬挂含有禁毒、禁赌、禁止卖淫嫖娼等内容的警示标志。标志应当注明公安机关的举报电话。 警示标志式样、规格、尺寸由省、自治区、直辖市公安厅、局统一制定。"},{"i":18,"n":"第十八条","txt":"娱乐场所不得设置具有赌博功能的电子游戏机机型、机种、电路板等游戏设施设备，不得从事带有赌博性质的游戏机经营活动。"},{"i":19,"n":"第十九条","txt":"娱乐场所对从业人员应当实行实名登记制度，建立从业人员名簿，统一建档管理。"},{"i":20,"n":"第二十条","txt":"从业人员名簿应当记录以下内容： （一）从业人员姓名、年龄、性别、出生日期及有效身份证件号码； （二）从业人员户籍所在地和暂住地地址； （三）从业人员具体工作岗位、职责。 外国人就业的，应当留存外国人就业许可证复印件。"},{"i":21,"n":"第二十一条","txt":"营业期间，娱乐场所从业人员应当统一着装，统一佩带工作标志。 着装应当大方得体，不得有伤风化。 工作标志应当载有从业人员照片、姓名、职务、统一编号等基本信息。"},{"i":22,"n":"第二十二条","txt":"娱乐场所应当建立营业日志，由各岗位负责人及时登记填写并签名，专人负责保管。 营业日志应当详细记载从业人员的工作职责、工作内容、工作时间、工作地点及遇到的治安问题。"},{"i":23,"n":"第二十三条","txt":"娱乐场所营业日志应当留存60日备查，不得删改。对确因记录错误需要删改的，应当写出说明，由经手人签字，加盖娱乐场所印章。"},{"i":24,"n":"第二十四条","txt":"娱乐场所应当安排保安人员负责安全巡查，营业时间内每2小时巡查一次，巡查区域应当涵盖整个娱乐场所，巡查情况应当写入营业日志。"},{"i":25,"n":"第二十五条","txt":"娱乐场所对发生在场所内的违法犯罪活动，应当立即向公安机关报告。"},{"i":26,"n":"第二十六条","txt":"娱乐场所应当按照国家有关信息化标准规定，配合公安机关建立娱乐场所治安管理信息系统，实时、如实将从业人员、营业日志、安全巡查等信息录入系统，传输报送公安机关。 本办法规定娱乐场所配合公安机关在治安管理方面所作的工作，能够通过娱乐场所治安管理信息系统录入传输完成的，应当通过系统完成。"},{"i":27,"n":"第二十七条","txt":"娱乐场所应当与经公安机关批准设立的保安服务企业签订服务合同，配备已取得资格证书的专业保安人员，并通报娱乐场所所在辖区公安派出所。 娱乐场所不得自行招录人员从事保安工作。"},{"i":28,"n":"第二十八条","txt":"娱乐场所保安人员应当履行下列职责： （一）维护娱乐场所治安秩序； （二）协助娱乐场所做好各项安全防范和巡查工作； （三）及时排查、发现并报告娱乐场所治安、安全隐患； （四）协助公安机关调查、处置娱乐场所内发生的违法犯罪活动。"},{"i":29,"n":"第二十九条","txt":"娱乐场所应当加强对保安人员的教育管理，不得要求保安人员从事与其职责无关的工作。对保安人员工作情况逐月通报辖区公安派出所和保安服务企业。"},{"i":30,"n":"第三十条","txt":"娱乐场所营业面积在200平方米以下的，配备的保安人员不得少于2名；营业面积每增加200平方米，应当相应增加保安人员1名。 迪斯科舞厅保安人员应当按照场所核定人数的5％配备。"},{"i":31,"n":"第三十一条","txt":"在娱乐场所执勤的保安人员应当统一着制式服装，佩带徽章、标记。 保安人员执勤时，应当仪表整洁、行为规范、举止文明。"},{"i":32,"n":"第三十二条","txt":"保安服务企业应当加强对派驻娱乐场所保安人员的教育培训，开展经常性督查，确保服务质量。"},{"i":33,"n":"第三十三条","txt":"公安机关及其工作人员对娱乐场所进行监督检查时应当出示人民警察证件，表明执法身份，不得从事与职务无关的活动。 公安机关及其工作人员对娱乐场所进行监督检查，应当记录在案，归档管理。"},{"i":34,"n":"第三十四条","txt":"监督检查记录应当以书面形式为主，必要时可以辅以录音、录像等形式。"},{"i":35,"n":"第三十五条","txt":"监督检查记录应当包括： （一）执行监督检查任务的人员姓名、单位、职务； （二）监督检查的时间、地点、场所名称、检查事项； （三）发现的问题及处理结果。"},{"i":36,"n":"第三十六条","txt":"监督检查记录一式两份，由监督检查人员签字，并经娱乐场所负责人签字确认。 娱乐场所负责人拒绝签字的，监督检查人员应当在记录中注明情况。"},{"i":37,"n":"第三十七条","txt":"公众有权查阅娱乐场所监督检查记录，公安机关应当为公众查阅提供便利。"},{"i":38,"n":"第三十八条","txt":"公安机关应当建立娱乐场所违法行为警示记录系统，并依据娱乐场所治安秩序状况进行分级管理。 娱乐场所分级管理标准，由各省、自治区、直辖市公安厅、局结合本地实际自行制定。"},{"i":39,"n":"第三十九条","txt":"公安机关对娱乐场所进行分级管理，应当按照公开、公平、公正的原则，定期考核，动态升降。"},{"i":40,"n":"第四十条","txt":"公安机关建立娱乐场所治安管理信息系统，对娱乐场所及其从业人员实行信息化监督管理。"},{"i":41,"n":"第四十一条","txt":"娱乐场所未按照本办法规定项目备案的，由受理备案的公安机关告知补齐；拒不补齐的，由受理备案的公安机关责令改正，给予警告。 违反本办法第七条规定的，由原备案公安机关责令改正，给予警告。"},{"i":42,"n":"第四十二条","txt":"娱乐场所违反本办法第八条至第十八条、第三十条规定的，由县级公安机关依照《娱乐场所管理条例》第四十三条的规定予以处罚。"},{"i":43,"n":"第四十三条","txt":"娱乐场所违反本办法第二十九条规定的，由县级公安机关责令改正，给予警告。 娱乐场所保安人员违反本办法第二十八条、三十一条规定的，依照有关规定予以处理。"},{"i":44,"n":"第四十四条","txt":"娱乐场所违反本办法第二十六条规定，不配合公安机关建立娱乐场所治安管理信息系统的，由县级公安机关治安管理部门责令改正，给予警告；经警告不予改正的，处5000元以上1万元以下罚款。"},{"i":45,"n":"第四十五条","txt":"公安机关工作人员违反本办法第三十三条规定或有其他失职、渎职行为的，对直接负责的主管人员和其他直接责任人员依法予以行政处分；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"娱乐场所及其从业人员违反本办法规定的其他行为，《娱乐场所管理条例》已有处罚规定的，依照规定处罚；违反治安管理的，依照《中华人民共和国治安管理处罚法》处罚；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"非娱乐场所经营单位兼营歌舞、游艺项目的，依照本办法执行。"},{"i":48,"n":"第四十八条","txt":"本办法自2008年10月1日起施行。"}],"juliusuotiaolishishibanfa":[{"i":1,"n":"第一条","txt":"为了规范拘留所的设置和管理，惩戒和教育被拘留人，保护被拘留人的合法权益，保障拘留的顺利执行，根据《拘留所条例》及有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公安部主管全国拘留所的管理工作。县级以上地方人民政府公安机关主管本行政区域拘留所的管理工作。铁路、交通、森林系统公安机关和公安边防部门主管本系统拘留所的管理工作。"},{"i":3,"n":"第三条","txt":"拘留所应当坚持依法、科学、文明管理，依法保障被拘留人的人身安全和合法权益，尊重被拘留人的人格，不得侮辱、体罚、虐待被拘留人，或者指使、纵容他人侮辱、体罚、虐待被拘留人。 被拘留人应当服从管理，接受教育。"},{"i":4,"n":"第四条","txt":"拘留所应当执法公开，接受社会监督。"},{"i":5,"n":"第五条","txt":"对下列人员的拘留在拘留所执行： （一）被公安机关、国家安全机关依法给予行政拘留处罚的人； （二）被人民法院依法决定拘留的人； （三）被公安机关依法给予现场行政强制措施性质拘留的人。 被公安机关依法决定拘留审查的人，以及被依法决定、判处驱逐出境或者被依法决定遣送出境但不能立即执行的人，可以在拘留所拘押。"},{"i":6,"n":"第六条","txt":"拘留所由县级以上地方人民政府根据需要按照政府机构序列设置。 拘留所的设置或者撤销，由县级以上地方人民政府公安机关提出意见，经同级人民政府机构编制管理部门和财政部门审核，报同级人民政府批准，并逐级上报省级人民政府公安机关备案；铁路、交通、森林系统公安机关和公安边防部门根据需要设置或者撤销拘留所时，按照规定的权限和程序审批。 地市级以上人民政府公安机关可以根据需要建议同级人民政府设置若干拘留所，集中收拘所辖区、县、市、旗的被拘留人。 省级人民政府公安机关对所辖区域内不具备执法条件的拘留所可以责令其停止收拘被拘留人。"},{"i":7,"n":"第七条","txt":"拘留所机构名称为XX省（自治区、直辖市）、市（地区、州、盟）、县（市、区、旗）拘留所。铁路、交通、森林系统公安机关设置的拘留所名称为XX铁路（交通、森林）公安局（处）拘留所，公安边防部门设置的拘留所名称为XX公安边防总队（支队）XX拘留所。"},{"i":8,"n":"第八条","txt":"拘留所设所长1名，副所长2名以上，并按照有关规定设置政治委员或者教导员。"},{"i":9,"n":"第九条","txt":"拘留所应当根据工作需要设置相应的内设机构，配备相应数量的收拘、管教、监控、巡视、技术、财会等民警，建立岗位责任制度。 公安机关可以聘用文职人员等参与、协助拘留所的综合文秘、教育培训、心理矫治、医疗卫生、监控技防、警务保障等非执法工作。 公安机关应当聘用一定数量的工勤人员从事拘留所勤杂工作。"},{"i":10,"n":"第十条","txt":"拘留所的建设应当符合国家有关建设标准，建设方案应当经省级人民政府公安机关审核批准。"},{"i":11,"n":"第十一条","txt":"拘留所应当依照有关规定配备武器、警械、交通、通信、信息、技术防范、教育、培训、文体活动、应急处置、心理矫治、生活卫生、医疗、消防等装备和设施。"},{"i":12,"n":"第十二条","txt":"拘留所的基础建设经费、修缮费、日常运行公用经费、办案（业务）经费、装备经费、被拘留人给养经费等由公安机关提请本级人民政府列入财政预算予以足额保障。 县级以上地方人民政府公安机关应当会同本级财政部门每年对被拘留人伙食费、医疗费等给养经费标准进行核定。"},{"i":13,"n":"第十三条","txt":"拘留所应当凭作出拘留、拘留审查、遣送出境、驱逐出境决定或者判决的机关（以下统称拘留决定机关）出具的行政处罚决定书、人民法院拘留决定书、拘留审查决定书、恢复执行拘留决定书、遣送出境决定书、驱逐出境决定书或者判决书等法律文书收拘被拘留人。 异地收拘的，拘留所应当凭拘留决定机关的拘留决定文书、需要异地收拘的书面说明和拘留所主管公安机关的批准手续收拘被拘留人。 拘留所收拘异地办案机关临时寄押被拘留人的，应当经拘留所主管公安机关批准，凭拘留决定机关的法律文书或者其他相关寄押证明收拘。临时寄押的时间一般不超过3天。 铁路公安机关决定行政拘留的人交由铁路公安机关所辖拘留所执行确有困难的，可以凭拘留决定机关的法律文书就近交铁路沿线地方公安机关所辖拘留所执行。"},{"i":14,"n":"第十四条","txt":"收拘时，拘留所应当查验送拘人员的工作证件和法律文书，核实被拘留人的身份。"},{"i":15,"n":"第十五条","txt":"拘留所收拘被拘留人，应当对其人身和携带的物品进行检查，严禁将违禁品带入拘室。 被拘留人的非生活必需品及现金由拘留所登记并统一保管。拘留所民警应当与被拘留人当面清点、核对后填写被拘留人暂存物品、现金收据（一式三份，一份由被拘留人收执，一份连同物品、现金存保管室，一份拘留所留作存根），注明物品、现金的名称、规格、数量、重量、特征等，由拘留所民警和被拘留人共同签名确认。 发现被拘留人携带违禁品或者其他与案件有关的物品的,拘留所应当填写被拘留人违禁品、涉案物品移交清单（一式三份，被拘留人、拘留所和拘留决定机关各一份），由送拘人员、拘留所民警和被拘留人共同签名确认，经拘留所领导批准后移交拘留决定机关依法处理。 拘留所收拘被拘留人应当由2名以上民警进行。对女性被拘留人的人身检查，应当由女性民警进行。"},{"i":16,"n":"第十六条","txt":"拘留所收拘被拘留人，应当由医生对其进行健康检查，并填写入所健康检查表。 发现被拘留人身体有伤或者情况异常的，拘留决定机关应当出具相关情况说明，拘留所详细登记伤情或者异常情况，并由送拘人员和被拘留人签名确认。"},{"i":17,"n":"第十七条","txt":"发现被拘留人可能被错误拘留的，拘留所应当出具可能错误拘留通知书，通知拘留决定机关，拘留决定机关应当在24小时以内作出处理决定并通知拘留所。"},{"i":18,"n":"第十八条","txt":"被拘留人有下列情形之一的，拘留所不予收拘，并出具不予收拘通知书，通知拘留决定机关： （一）   不满16周岁或者已满70周岁的； （二）   已满16周岁不满18周岁，初次违反治安管理的； （三）   怀孕或者哺乳自己不满一周岁婴儿的； （四）   被拘留审查的人患有严重疾病的； （五）   不宜适用拘留审查的其他情形。 收拘后发现被拘留人具有上述情形之一的，拘留所应当立即出具建议另行处理通知书，通知拘留决定机关。拘留决定机关应当立即处理并通知拘留所。"},{"i":19,"n":"第十九条","txt":"收拘时或者收拘后，拘留所发现被拘留人有下列情形之一的，应当出具建议停止执行拘留通知书，建议拘留决定机关作出停止执行拘留的决定： （一）患有精神病或者患有传染病需要隔离治疗的； （二）病情严重可能危及生命安全的； （三）生活不能自理的； （四）因病出所治疗，短期内无法治愈的。 拘留决定机关应当立即作出是否停止执行拘留的决定并通知拘留所。"},{"i":20,"n":"第二十条","txt":"发现被拘留人吸食、注射毒品成瘾的，拘留所应当提请拘留所的主管公安机关对被拘留人依法作出责令社区戒毒或者强制隔离戒毒的决定。 对被处以行政拘留的吸食、注射毒品成瘾人员，拘留所不具备戒毒治疗条件的，可以由公安机关管理的强制隔离戒毒所代为执行行政拘留。"},{"i":21,"n":"第二十一条","txt":"收拘被拘留人后，拘留所应当向拘留决定机关出具收拘回执。"},{"i":22,"n":"第二十二条","txt":"收拘被拘留人时，拘留所应当告知被拘留人在拘留期间依法享有的权利和应当遵守的规定。 收拘被拘留人后，拘留决定机关应当及时通知被拘留人家属。"},{"i":23,"n":"第二十三条","txt":"拘留所收拘被拘留人，应当填写被拘留人登记表，采集被拘留人基本情况、照片等信息，并录入拘留所管理信息系统。"},{"i":24,"n":"第二十四条","txt":"拘留所应当建立管理制度，落实各项管理措施。"},{"i":25,"n":"第二十五条","txt":"拘留所应当安装并使用监控录像等技术防范设备对被拘留人进行实时全方位安全监控。监控录像资料至少保存15天。被拘留人在拘留期间死亡、身体受到伤害，可能提起国家赔偿要求的，拘留所应当将相关监控录像资料予以刻录留存。"},{"i":26,"n":"第二十六条","txt":"拘留所应当建立出入所登记制度。非本所工作人员进入拘留区需经所领导批准，并由本所民警带领。"},{"i":27,"n":"第二十七条","txt":"拘留所应当建立所领导带班、2名以上民警值班巡视制度。值班人员应当严守岗位，加强巡视监控，发现问题及时报告、妥善处理并做好值班记录，不得擅离职守。"},{"i":28,"n":"第二十八条","txt":"拘留所应当建立交接班制度，交接班人员应当现场交清被拘留人数、拘室管理动态及需要注意的事项，并在值班记录上签名。"},{"i":29,"n":"第二十九条","txt":"拘留所应当根据被拘留人的性别、是否成年以及其他管理的需要，对被拘留人分别拘押和管理。 对被现场行政强制措施性质拘留、拘留审查、驱逐出境、遣送出境的人，应当与其他被拘留人分别拘押和管理。 对女性被拘留人的直接管理应当由女性民警进行。"},{"i":30,"n":"第三十条","txt":"拘留所应当根据被拘留人拘留期间的具体情况，实行分级管理。"},{"i":31,"n":"第三十一条","txt":"拘留所实行管教民警管理拘室责任制。每个拘室除配备主管民警外，还应当配备协管民警，承担对被拘留人管理、教育等工作。 管教民警应当熟知负责管理的被拘留人的基本情况、健康状况、简要案情、思想动态和所内表现。"},{"i":32,"n":"第三十二条","txt":"拘留所应当建立并落实被拘留人管理规定和生活制度，规范被拘留人行为，合理安排被拘留人生活、学习、文体等活动，并由民警组织实施，现场监管。"},{"i":33,"n":"第三十三条","txt":"拘留所应当建立被拘留人日常在所表现考核制度，考核结果作为对被拘留人奖励和惩罚的依据。"},{"i":34,"n":"第三十四条","txt":"被拘留人有下列行为之一的，拘留所应当予以表扬或者奖励： （一）遵守拘留所的管理规定表现突出的； （二）检举、揭发违法犯罪行为经查证属实的； （三）制止违法犯罪行为的。 表扬和奖励应当经拘留所领导批准，并记录在被拘留人管理档案。"},{"i":35,"n":"第三十五条","txt":"被拘留人有下列行为之一的，拘留所应当根据不同情节依法分别予以训诫、责令具结悔过： （一）起哄闹事，打架斗殴的； （二）殴打、体罚、虐待、欺侮他人的； （三）故意损毁拘留所财物或者侵犯他人财产权利的； （四）预谋或者实施脱逃、行凶、自杀、自伤、自残、吞食异物以及隐藏违禁品的； （五）传授违法犯罪方法或者教唆他人违法犯罪的； （六）袭击民警及其他工作人员的； （七）违反拘留所管理规定的其他行为。 对被拘留人的训诫和责令具结悔过，由管教民警决定并执行，并记录在被拘留人管理档案。"},{"i":36,"n":"第三十六条","txt":"被拘留人有下列情形之一的，拘留所可以依法对其使用警械： （一）因病出所治疗，可能脱逃、行凶、自杀、自残或者有其他危险行为的； （二）有本办法第三十五条规定行为之一且情节严重的。 对被拘留人使用警械，由管教民警提出，填写使用警械审批表，由拘留所所长批准。使用警械应当遵守有关法律、行政法规的规定。安全危险消除或者被拘留人服从管理、接受教育后应当立即停止使用警械。"},{"i":37,"n":"第三十七条","txt":"拘留所应当定期进行安全检查，及时发现和消除安全隐患。 拘室安全检查每日不少于1次，由主管或者协管拘室的民警负责。安全大检查每周不少于1次，由拘留所领导组织拘留所民警实施。"},{"i":38,"n":"第三十八条","txt":"拘留所应当定期对被拘留人思想动态进行分析、研判，查找安全隐患，及时采取安全防范措施。"},{"i":39,"n":"第三十九条","txt":"拘留所应当建立突发事件应急机制，制定处置预案并适时组织演练。遇有突发事件时，应当采取果断措施，及时依法处置。"},{"i":40,"n":"第四十条","txt":"被拘留人提出举报、控告，申请行政复议，请求国家赔偿，提起行政诉讼或者申请暂缓执行行政拘留的，拘留所登记后应当在24小时以内将有关材料转送有关机关，不得检查或者扣押。 被行政拘留的人申请暂缓执行行政拘留的，拘留决定机关收到申请后应当立即进行审查。拘留决定机关批准被拘留人暂缓执行行政拘留的，应当制作暂缓执行决定书送达拘留所。"},{"i":41,"n":"第四十一条","txt":"被拘留人在拘留期间有新的违法犯罪嫌疑的，拘留所应当报告主管公安机关处理。 拘留所发现被拘留人收拘前有其他违法犯罪嫌疑的，或者被拘留人检举、揭发他人违法犯罪嫌疑的，应当对获取的违法犯罪线索进行登记并制作违法犯罪线索转递函通知有关机关处理，案件主管机关应当及时查证并反馈拘留所。"},{"i":42,"n":"第四十二条","txt":"拘留所应当建立被拘留人管理档案，并由专人保管。 被拘留人管理档案内容包括：入出所相关法律文书、被拘留人登记表、入所健康检查表、奖惩情况记录、财物保管记录等应当保存的资料。 查阅被拘留人管理档案应当经拘留所所长批准。"},{"i":43,"n":"第四十三条","txt":"拘留所应当建立被拘留人财物管理制度，妥善保管被拘留人财物。为被拘留人代收、代管、代购物品应当做到明确登记、账目清楚。代购物品仅限于日常生活必需品和食品，物品价格不得高于当地市场价格。 拘留所对被拘留人亲友传送或者邮寄的财物应当进行检查、登记。生活必需品转交被拘留人，现金由拘留所统一保管，非生活必需品不予接收或者由拘留所统一保管。"},{"i":44,"n":"第四十四条","txt":"拘留所应当按照规定的标准为被拘留人提供饮食，并尊重其民族饮食习惯。"},{"i":45,"n":"第四十五条","txt":"拘留所应当保证被拘留人每天不少于2小时的拘室外活动时间。"},{"i":46,"n":"第四十六条","txt":"拘留所应当建立医疗卫生防疫制度，做好防病、防疫、巡诊、治疗工作。 拘留所对患病的被拘留人应当及时治疗。对需要出所治疗的，应当经拘留所领导批准，并派民警监管。 被拘留人毒瘾发作或者出现精神障碍可能发生自伤、自残或者其他危险行为的，拘留所应当及时予以治疗，并视情可以采取保护性约束措施。 被拘留人病情严重的，拘留所应当立即采取急救措施，并报告主管公安机关，同时通知拘留决定机关和被拘留人的亲属。"},{"i":47,"n":"第四十七条","txt":"被拘留人在拘留期间死亡的，拘留所应当立即报告主管公安机关并通知拘留决定机关、死者近亲属。拘留所的主管公安机关应当立即通知同级人民检察院，并做好被拘留人死因鉴定及善后处理等事宜。"},{"i":48,"n":"第四十八条","txt":"拘留所保障被拘留人在拘留期间的通信、会见权利。被拘留人应当遵守拘留所的通信、会见管理规定。"},{"i":49,"n":"第四十九条","txt":"被现场行政强制措施性质拘留、拘留审查、驱逐出境、遣送出境的人与他人的通信、通话、会见，应当经拘留决定机关批准。拘留决定机关应当在接到申请后12个小时以内予以回复。"},{"i":50,"n":"第五十条","txt":"被拘留人与他人的来往信件不受检查和扣押，由拘留所登记、收发。发现信件内有可能夹带违禁品的，拘留所民警可以责令被拘留人当面打开信件予以安全检查。"},{"i":51,"n":"第五十一条","txt":"被拘留人需要打电话的，应当向民警提出申请，经批准后，使用拘留所内固定电话进行通话，通话费用原则上自理。被拘留人打电话应当遵守拘留所的管理规定，一般不超过3次，每次不超过10分钟。"},{"i":52,"n":"第五十二条","txt":"会见被拘留人应当持有效身份证件。被拘留人委托的律师会见被拘留人还应当持律师执业证书、律师事务所证明和委托书或者法律援助公函。拘留所民警应当查验会见人员的有关证件、凭证，填写会见被拘留人登记表，及时予以安排。 会见被拘留人应当在拘留所规定的时间、区域进行，并遵守拘留所会见管理规定。被拘留人会见次数一般不超过2次，每次会见的人数不超过3人，会见时间不超过30分钟。有特殊情况要求在非会见日会见或者增加会见次数、人数和时间的，应当经拘留所领导批准。 被拘留人委托的律师会见被拘留人不受次数和时间的限制，但应当在正常工作时间进行。 对违反会见管理规定的，拘留所可以予以警告或者责令停止会见。 会见结束后，拘留所应当对被拘留人进行人身检查后送回拘室。 经被拘留人或者其亲友申请，有条件的拘留所可以安排被拘留人进行远程视频会见。"},{"i":53,"n":"第五十三条","txt":"外国驻华使领馆领事官员可以依照有关条约、公约会见本国籍被拘留人。"},{"i":54,"n":"第五十四条","txt":"被拘留人书面明示拒绝会见的，拘留所应当同意并告知要求会见人。"},{"i":55,"n":"第五十五条","txt":"办案人员询问被拘留人应当持办案单位的公函及办案人员的有效工作证件，填写询问被拘留人登记表，经拘留所领导批准后在所内询问室进行。 因侦查办案需要提解被拘留人出所的，提解人员应当持县级以上办案机关主要负责人的批准文书和提解人员的有效工作证件，经主管拘留所的公安机关批准后，填写提解被拘留人登记表，方可带出所外，并于当日送回。 询问、提解每名被拘留人，询问、提解人员不得少于2人。 询问、提解出所前以及询问、提解结束后，拘留所应当对被拘留人进行人身检查后带出或者送回拘室。拘留所发现被拘留人在询问、提解后情况异常的，应当要求办案单位作出说明。拘留所认为办案单位的说明与实际情况不符的，应当及时报告拘留所的主管公安机关进行调查。"},{"i":56,"n":"第五十六条","txt":"被拘留人遇有参加升学考试、子女出生或者近亲属病危、死亡等情形的，被拘留人或者其近亲属可以提出请假出所的申请，并提供相关证明材料。 拘留所接到被拘留人请假出所申请后，应当立即提出审核意见，填写被拘留人请假出所审批表，报拘留决定机关审批。拘留决定机关应当在被拘留人或者其近亲属提出申请的12小时以内作出是否准予请假出所的决定。 拘留决定机关批准请假出所的，拘留所发给被拘留人请假出所证明，安排被拘留人出所。 准假出所的时间一般不超过7天。被拘留人请假出所的时间不计入拘留期限。"},{"i":57,"n":"第五十七条","txt":"被拘留人或者其近亲属提出请假出所申请的，应当向拘留决定机关提出担保人，或者按剩余拘留期限每日200元的标准交纳保证金。 担保人应当符合下列条件： （一）与被拘留人案件无牵连； （二）享有政治权利，人身自由未受到限制； （三）在当地有常住户口和固定住所； （四）有能力履行担保义务。 担保人应当保证被担保人请假出所后按时返回拘留所。担保人不履行担保义务、致使被担保人请假出所不归或者不按时回所的，由公安机关对其处3000元以下罚款。 被拘留人请假出所后按时返回的，拘留决定机关应当将收取的保证金及时退还交纳人；被拘留人请假出所不归或者不按时回所的，保证金予以没收并上缴国库。"},{"i":58,"n":"第五十八条","txt":"被拘留人请假出所期满的，拘留所应当填写被拘留人请假出所期满通知书及时通知拘留决定机关。对请假出所不归的，由拘留决定机关负责将其带回拘留所继续执行拘留。"},{"i":59,"n":"第五十九条","txt":"拘留所应当建立教育制度，对被拘留人进行法律、道德、文化、时事、政策、所规、行为养成、技能培训、心理健康等教育。"},{"i":60,"n":"第六十条","txt":"对被拘留人的教育，可以采取集体教育、分类教育、个别教育、心理矫治、亲友规劝、社会帮教、现身说法等形式进行。 拘留所应当在被拘留人入所24小时以内进行第一次谈话教育，在解除拘留前进行一次谈话教育。 对被拘留人的集体教育每周不少于10个课时。"},{"i":61,"n":"第六十一条","txt":"拘留所应当每日组织被拘留人开展适当的文化、体育活动。"},{"i":62,"n":"第六十二条","txt":"拘留所应当开展所内文化建设活动，营造有益于被拘留人身心健康，促进被拘留人知错、认错、改错的文化环境和氛围。"},{"i":63,"n":"第六十三条","txt":"拘留所在确保安全和被拘留人自愿的前提下，可以组织被拘留人在所内开展适当的劳动教育或者职业技能培训。 拘留所不得强迫或者变相强迫被拘留人从事生产劳动。"},{"i":64,"n":"第六十四条","txt":"被拘留人拘留期满，拘留决定机关决定对其停止执行拘留的，或者拘留决定机关决定对其暂缓执行行政拘留的，拘留所应当核实其身份，查验有关法律文书，发给解除拘留证明书，按时解除拘留。"},{"i":65,"n":"第六十五条","txt":"被拘留人在解除拘留时有下列情形之一的，拘留所应当向办案单位移交被拘留人： （一）依法被决定驱逐出境、遣送出境或者执行驱逐出境、遣送出境的； （二）依法被决定执行刑事强制措施的； （三）依法被决定社区戒毒、强制隔离戒毒的； （四）依法被决定采取强制性教育矫治措施的。 移交时，拘留所民警应当核实被拘留人身份，查验办案单位工作人员的证件以及有关法律文书或者公函。办案单位工作人员应当在被拘留人基本情况登记表上注明被拘留人出所时间、原因、去向并签名后，拘留所移交被拘留人。 移交被拘留人应当在拘留所进行。"},{"i":66,"n":"第六十六条","txt":"异地收拘的被拘留人，拘留决定机关要求带回原地执行的，拘留所凭拘留决定机关的法律文书或者公函，按照本办法第六十五条的规定向拘留决定机关移交被拘留人。"},{"i":67,"n":"第六十七条","txt":"被拘留人解除拘留出所时，拘留所民警应当对其人身和随身携带的物品进行检查，并返还代为保管的财物。 拘留所民警在被拘留人登记表上登记被拘留人出所原因、时间及去向并签名，并录入拘留所管理信息系统。"},{"i":68,"n":"第六十八条","txt":"执行拘留的时间以日为单位计算，从收拘当日到第2日为1日。"},{"i":69,"n":"第六十九条","txt":"拘留所的执法和管理文书格式，由公安部统一制定。"},{"i":70,"n":"第七十条","txt":"拘留所实行等级化管理，具体办法由公安部另行制定。"},{"i":71,"n":"第七十一条","txt":"本办法所称以上、以下、以内，包括本数。"},{"i":72,"n":"第七十二条","txt":"各省、自治区、直辖市公安厅、局和新疆生产建设兵团公安局可以根据本办法制定实施细则。"},{"i":73,"n":"第七十三条","txt":"本办法自发布之日起施行。"}],"yizhiduhuaxuepingouxiaoheyunshuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强易制毒化学品管理，规范购销和运输易制毒化学品行为，防止易制毒化学品被用于制造毒品，维护经济和社会秩序，根据《易制毒化学品管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"公安部是全国易制毒化学品购销、运输管理和监督检查的主管部门。 县级以上地方人民政府公安机关负责本辖区内易制毒化学品购销、运输管理和监督检查工作。 各省、自治区、直辖市和设区的市级人民政府公安机关禁毒部门应当设立易制毒化学品管理专门机构，县级人民政府公安机关应当设专门人员，负责易制毒化学品的购买、运输许可或者备案和监督检查工作。"},{"i":3,"n":"第三条","txt":"购买第一类中的非药品类易制毒化学品的，应当向所在地省级人民政府公安机关申请购买许可证；购买第二类、第三类易制毒化学品的，应当向所在地县级人民政府公安机关备案。取得购买许可证或者购买备案证明后，方可购买易制毒化学品。"},{"i":4,"n":"第四条","txt":"个人不得购买第一类易制毒化学品和第二类易制毒化学品。 禁止使用现金或者实物进行易制毒化学品交易，但是个人合法购买第一类中的药品类易制毒化学品药品制剂和第三类易制毒化学品的除外。"},{"i":5,"n":"第五条","txt":"申请购买第一类中的非药品类易制毒化学品和第二类、第三类易制毒化学品的，应当提交下列申请材料： （一）经营企业的营业执照（副本和复印件），其他组织的登记证书或者成立批准文件（原件和复印件），或者个人的身份证明（原件和复印件）； （二）合法使用需要证明（原件）。 合法使用需要证明由购买单位或者个人出具，注明拟购买易制毒化学品的品种、数量和用途，并加盖购买单位印章或者个人签名。"},{"i":6,"n":"第六条","txt":"申请购买第一类中的非药品类易制毒化学品的，由申请人所在地的省级人民政府公安机关审批。负责审批的公安机关应当自收到申请之日起十日内，对申请人提交的申请材料进行审查。对符合规定的，发给购买许可证；不予许可的，应当书面说明理由。 负责审批的公安机关对购买许可证的申请能够当场予以办理的，应当当场办理；对材料不齐备需要补充的，应当一次告知申请人需补充的内容；对提供材料不符合规定不予受理的，应当书面说明理由。"},{"i":7,"n":"第七条","txt":"公安机关审查第一类易制毒化学品购买许可申请材料时，根据需要，可以进行实地核查。遇有下列情形之一的，应当进行实地核查： （一）购买单位第一次申请的； （二）购买单位提供的申请材料不符合要求的； （三）对购买单位提供的申请材料有疑问的。"},{"i":8,"n":"第八条","txt":"购买第二类、第三类易制毒化学品的，应当在购买前将所需购买的品种、数量，向所在地的县级人民政府公安机关备案。公安机关受理备案后，应当于当日出具购买备案证明。 自用一次性购买五公斤以下且年用量五十公斤以下高锰酸钾的，无须备案。"},{"i":9,"n":"第九条","txt":"易制毒化学品购买许可证一次使用有效，有效期一个月。 易制毒化学品购买备案证明一次使用有效，有效期一个月。对备案后一年内无违规行为的单位，可以发给多次使用有效的备案证明，有效期六个月。 对个人购买的，只办理一次使用有效的备案证明。"},{"i":10,"n":"第十条","txt":"经营单位销售第一类易制毒化学品时，应当查验购买许可证和经办人的身份证明。对委托代购的，还应当查验购买人持有的委托文书。 委托文书应当载明委托人与被委托人双方情况、委托购买的品种、数量等事项。 经营单位在查验无误、留存前两款规定的证明材料的复印件后，方可出售第一类易制毒化学品；发现可疑情况的，应当立即向当地公安机关报告。 经营单位在查验购买方提供的许可证和身份证明时，对不能确定其真实性的，可以请当地公安机关协助核查。公安机关应当当场予以核查，对于不能当场核实的，应当于三日内将核查结果告知经营单位。"},{"i":11,"n":"第十一条","txt":"经营单位应当建立易制毒化学品销售台账，如实记录销售的品种、数量、日期、购买方等情况。经营单位销售易制毒化学品时，还应当留存购买许可证或者购买备案证明以及购买经办人的身份证明的复印件。 销售台账和证明材料复印件应当保存二年备查。"},{"i":12,"n":"第十二条","txt":"经营单位应当将第一类易制毒化学品的销售情况于销售之日起五日内报当地县级人民政府公安机关备案，将第二类、第三类易制毒化学品的销售情况于三十日内报当地县级人民政府公安机关备案。 备案的销售情况应当包括销售单位、地址，销售易制毒化学品的种类、数量等，并同时提交留存的购买方的证明材料复印件。"},{"i":13,"n":"第十三条","txt":"第一类易制毒化学品的使用单位，应当建立使用台账，如实记录购进易制毒化学品的种类、数量、使用情况和库存等，并保存二年备查。"},{"i":14,"n":"第十四条","txt":"购买、销售和使用易制毒化学品的单位，应当在易制毒化学品的出入库登记、易制毒化学品管理岗位责任分工以及企业从业人员的易制毒化学品知识培训等方面建立单位内部管理制度。"},{"i":15,"n":"第十五条","txt":"运输易制毒化学品，有下列情形之一的，应当申请运输许可证或者进行备案： （一）跨设区的市级行政区域（直辖市为跨市界）运输的； （二）在禁毒形势严峻的重点地区跨县级行政区域运输的。禁毒形势严峻的重点地区由公安部确定和调整，名单另行公布。 运输第一类易制毒化学品的，应当向运出地的设区的市级人民政府公安机关申请运输许可证。 运输第二类易制毒化学品的，应当向运出地县级人民政府公安机关申请运输许可证。 运输第三类易制毒化学品的，应当向运出地县级人民政府公安机关备案。"},{"i":16,"n":"第十六条","txt":"运输供教学、科研使用的一百克以下的麻黄素样品和供医疗机构制剂配方使用的小包装麻黄素以及医疗机构或者麻醉药品经营企业购买麻黄素片剂六万片以下、注射剂一万五千支以下，货主或者承运人持有依法取得的购买许可证明或者麻醉药品调拨单的，无须申请易制毒化学品运输许可。"},{"i":17,"n":"第十七条","txt":"因治疗疾病需要，患者、患者近亲属或者患者委托的人凭医疗机构出具的医疗诊断书和本人的身份证明，可以随身携带第一类中的药品类易制毒化学品药品制剂，但是不得超过医用单张处方的最大剂量。"},{"i":18,"n":"第十八条","txt":"运输易制毒化学品，应当由货主向公安机关申请运输许可证或者进行备案。 申请易制毒化学品运输许可证或者进行备案，应当提交下列材料： （一）经营企业的营业执照（副本和复印件），其他组织的登记证书或者成立批准文件（原件和复印件），个人的身份证明（原件和复印件）； （二）易制毒化学品购销合同（复印件）； （三）经办人的身份证明（原件和复印件）。"},{"i":19,"n":"第十九条","txt":"负责审批的公安机关应当自收到第一类易制毒化学品运输许可申请之日起十日内，收到第二类易制毒化学品运输许可申请之日起三日内，对申请人提交的申请材料进行审查。对符合规定的，发给运输许可证；不予许可的，应当书面说明理由。 负责审批的公安机关对运输许可申请能够当场予以办理的，应当当场办理；对材料不齐备需要补充的，应当一次告知申请人需补充的内容；对提供材料不符合规定不予受理的，应当书面说明理由。 运输第三类易制毒化学品的，应当在运输前向运出地的县级人民政府公安机关备案。公安机关应当在收到备案材料的当日发给备案证明。"},{"i":20,"n":"第二十条","txt":"负责审批的公安机关对申请人提交的申请材料，应当核查其真实性和有效性，其中查验购销合同时，可以要求申请人出示购买许可证或者备案证明，核对是否相符；对营业执照和登记证书（或者成立批准文件），应当核查其生产范围、经营范围、使用范围、证照有效期等内容。 公安机关审查第一类易制毒化学品运输许可申请材料时，根据需要，可以进行实地核查。遇有下列情形之一的，应当进行实地核查： （一）申请人第一次申请的； （二）提供的申请材料不符合要求的； （三）对提供的申请材料有疑问的。"},{"i":21,"n":"第二十一条","txt":"对许可运输第一类易制毒化学品的，发给一次有效的运输许可证，有效期一个月。 对许可运输第二类易制毒化学品的，发给三个月多次使用有效的运输许可证；对第三类易制毒化学品运输备案的，发给三个月多次使用有效的备案证明；对于领取运输许可证或者运输备案证明后六个月内按照规定运输并保证运输安全的，可以发给有效期十二个月的运输许可证或者运输备案证明。"},{"i":22,"n":"第二十二条","txt":"承运人接受货主委托运输，对应当凭证运输的，应当查验货主提供的运输许可证或者备案证明，并查验所运货物与运输许可证或者备案证明载明的易制毒化学品的品种、数量等情况是否相符；不相符的，不得承运。 承运人查验货主提供的运输许可证或者备案证明时，对不能确定其真实性的，可以请当地人民政府公安机关协助核查。公安机关应当当场予以核查，对于不能当场核实的，应当于三日内将核查结果告知承运人。"},{"i":23,"n":"第二十三条","txt":"运输易制毒化学品时，运输车辆应当在明显部位张贴易制毒化学品标识；属于危险化学品的，应当由有危险化学品运输资质的单位运输；应当凭证运输的，运输人员应当自启运起全程携带运输许可证或者备案证明。承运单位应当派人押运或者采取其他有效措施，防止易制毒化学品丢失、被盗、被抢。 运输易制毒化学品时，还应当遵守国家有关货物运输的规定。"},{"i":24,"n":"第二十四条","txt":"公安机关在易制毒化学品运输过程中应当对运输情况与运输许可证或者备案证明所载内容是否相符等情况进行检查。交警、治安、禁毒、边防等部门应当在交通重点路段和边境地区等加强易制毒化学品运输的检查。"},{"i":25,"n":"第二十五条","txt":"易制毒化学品运出地与运入地公安机关应当建立情况通报制度。运出地负责审批或者备案的公安机关应当每季度末将办理的易制毒化学品运输许可或者备案情况通报运入地同级公安机关，运入地同级公安机关应当核查货物的实际运达情况后通报运出地公安机关。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府公安机关应当加强对易制毒化学品购销和运输等情况的监督检查，有关单位和个人应当积极配合。对发现非法购销和运输行为的，公安机关应当依法查处。 公安机关在进行易制毒化学品监督检查时，可以依法查看现场、查阅和复制有关资料、记录有关情况、扣押相关的证据材料和违法物品；必要时，可以临时查封有关场所。 被检查的单位或者个人应当如实提供有关情况和材料、物品，不得拒绝或者隐匿。"},{"i":27,"n":"第二十七条","txt":"公安机关应当对依法收缴、查获的易制毒化学品安全保管。对于可以回收的，应当予以回收；对于不能回收的，应当依照环境保护法律、行政法规的有关规定，交由有资质的单位予以销毁，防止造成环境污染和人身伤亡。对收缴、查获的第一类中的药品类易制毒化学品的，一律销毁。 保管和销毁费用由易制毒化学品违法单位或者个人承担。违法单位或者个人无力承担的，该费用在回收所得中开支，或者在公安机关的禁毒经费中列支。"},{"i":28,"n":"第二十八条","txt":"购买、销售和运输易制毒化学品的单位应当于每年三月三十一日前向所在地县级公安机关报告上年度的购买、销售和运输情况。公安机关发现可疑情况的，应当及时予以核对和检查，必要时可以进行实地核查。 有条件的购买、销售和运输单位，可以与当地公安机关建立计算机联网，及时通报有关情况。"},{"i":29,"n":"第二十九条","txt":"易制毒化学品丢失、被盗、被抢的，发案单位应当立即向当地公安机关报告。接到报案的公安机关应当及时立案查处，并向上级公安机关报告。"},{"i":30,"n":"第三十条","txt":"违反规定购买易制毒化学品，有下列情形之一的，公安机关应当没收非法购买的易制毒化学品，对购买方处非法购买易制毒化学品货值十倍以上二十倍以下的罚款，货值的二十倍不足一万元的，按一万元罚款；构成犯罪的，依法追究刑事责任： （一）未经许可或者备案擅自购买易制毒化学品的； （二）使用他人的或者伪造、变造、失效的许可证或者备案证明购买易制毒化学品的。"},{"i":31,"n":"第三十一条","txt":"违反规定销售易制毒化学品，有下列情形之一的，公安机关应当对销售单位处一万元以下罚款；有违法所得的，处三万元以下罚款，并对违法所得依法予以追缴；构成犯罪的，依法追究刑事责任： （一）向无购买许可证或者备案证明的单位或者个人销售易制毒化学品的； （二）超出购买许可证或者备案证明的品种、数量销售易制毒化学品的。"},{"i":32,"n":"第三十二条","txt":"货主违反规定运输易制毒化学品，有下列情形之一的，公安机关应当没收非法运输的易制毒化学品或者非法运输易制毒化学品的设备、工具；处非法运输易制毒化学品货值十倍以上二十倍以下罚款，货值的二十倍不足一万元的，按一万元罚款；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任： （一）未经许可或者备案擅自运输易制毒化学品的； （二）使用他人的或者伪造、变造、失效的许可证运输易制毒化学品的。"},{"i":33,"n":"第三十三条","txt":"承运人违反规定运输易制毒化学品，有下列情形之一的，公安机关应当责令停运整改，处五千元以上五万元以下罚款： （一）与易制毒化学品运输许可证或者备案证明载明的品种、数量、运入地、货主及收货人、承运人等情况不符的； （二）运输许可证种类不当的； （三）运输人员未全程携带运输许可证或者备案证明的。 个人携带易制毒化学品不符合品种、数量规定的，公安机关应当没收易制毒化学品，处一千元以上五千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"伪造申请材料骗取易制毒化学品购买、运输许可证或者备案证明的，公安机关应当处一万元罚款，并撤销许可证或者备案证明。 使用以伪造的申请材料骗取的易制毒化学品购买、运输许可证或者备案证明购买、运输易制毒化学品的，分别按照第三十条第一项和第三十二条第一项的规定处罚。"},{"i":35,"n":"第三十五条","txt":"对具有第三十条、第三十二条和第三十四条规定违法行为的单位或个人，自作出行政处罚决定之日起三年内，公安机关可以停止受理其易制毒化学品购买或者运输许可申请。"},{"i":36,"n":"第三十六条","txt":"违反易制毒化学品管理规定，有下列行为之一的，公安机关应当给予警告，责令限期改正，处一万元以上五万元以下罚款；对违反规定购买的易制毒化学品予以没收；逾期不改正的，责令限期停产停业整顿；逾期整顿不合格的，吊销相应的许可证： （一）将易制毒化学品购买或运输许可证或者备案证明转借他人使用的； （二）超出许可的品种、数量购买易制毒化学品的； （三）销售、购买易制毒化学品的单位不记录或者不如实记录交易情况、不按规定保存交易记录或者不如实、不及时向公安机关备案销售情况的； （四）易制毒化学品丢失、被盗、被抢后未及时报告，造成严重后果的； （五）除个人合法购买第一类中的药品类易制毒化学品药品制剂以及第三类易制毒化学品外，使用现金或者实物进行易制毒化学品交易的； （六）经营易制毒化学品的单位不如实或者不按时报告易制毒化学品年度经销和库存情况的。"},{"i":37,"n":"第三十七条","txt":"经营、购买、运输易制毒化学品的单位或者个人拒不接受公安机关监督检查的，公安机关应当责令其改正，对直接负责的主管人员以及其他直接责任人员给予警告；情节严重的，对单位处一万元以上五万元以下罚款，对直接负责的主管人员以及其他直接责任人员处一千元以上五千元以下罚款；有违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"公安机关易制毒化学品管理工作人员在管理工作中有应当许可而不许可、不应当许可而滥许可，不依法受理备案，以及其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"公安机关实施本章处罚，同时应当由其他行政主管机关实施处罚的，应当通报其他行政机关处理。"},{"i":40,"n":"第四十条","txt":"本办法所称“经营单位”，是指经营易制毒化学品的经销单位和经销自产易制毒化学品的生产单位。"},{"i":41,"n":"第四十一条","txt":"本办法所称“运输”，是指通过公路、铁路、水上和航空等各种运输途径，使用车、船、航空器等各种运输工具，以及人力、畜力携带、搬运等各种运输方式使易制毒化学品货物发生空间位置的移动。"},{"i":42,"n":"第四十二条","txt":"易制毒化学品购买许可证和备案证明、运输许可证和备案证明、易制毒化学品管理专用印章由公安部统一规定式样并监制。"},{"i":43,"n":"第四十三条","txt":"本办法自2006年10月1日起施行。《麻黄素运输许可证管理规定》（公安部令第52号）同时废止。 附表： 易制毒化学品的分类和品种目录 第一类 1、1-苯基-2-丙酮 2、3,4-亚甲基二氧苯基-2-丙酮 3、胡椒醛 4、黄樟素 5、黄樟油 6、异黄樟素 7、N-乙酰邻氨基苯酸 8、邻氨基苯甲酸 9、麦角酸 10、麦角胺 11、麦角新碱 12、麻黄素、伪麻黄素、消旋麻黄素、去甲麻黄素、甲基麻黄素、麻黄浸膏、麻黄浸膏粉等麻黄素类物质 第二类 1、苯乙酸 2、醋酸酐 3、三氯甲烷 4、乙醚 5、哌啶 第三类 1、甲苯 2、丙酮 3、甲基乙基酮 4、高锰酸钾 5、硫酸 6、盐酸 说明： 一、第一类、第二类所列物质可能存在的盐类，也纳入管制。 二、带有标记的品种为第一类中的药品类易制毒化学品，第一类中的药品类易制毒化学品包括原料药及其单方制剂。"}],"yizhibaoweixianhuaxuepinzhianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强易制爆危险化学品的治安管理，有效防范易制爆危险化学品治安风险，保障人民群众生命财产安全和公共安全，根据《中华人民共和国反恐怖主义法》《危险化学品安全管理条例》《企业事业单位内部治安保卫条例》等有关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"易制爆危险化学品生产、经营、储存、使用、运输和处置的治安管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称易制爆危险化学品，是指列入公安部确定、公布的易制爆危险化学品名录，可用于制造爆炸物品的化学品。"},{"i":4,"n":"第四条","txt":"本办法所称易制爆危险化学品从业单位，是指生产、经营、储存、使用、运输及处置易制爆危险化学品的单位。"},{"i":5,"n":"第五条","txt":"易制爆危险化学品治安管理，应当坚持安全第一、预防为主、依法治理、系统治理的原则，强化和落实从业单位的主体责任。 易制爆危险化学品从业单位的主要负责人是治安管理第一责任人，对本单位易制爆危险化学品治安管理工作全面负责。"},{"i":6,"n":"第六条","txt":"易制爆危险化学品从业单位应当建立易制爆危险化学品信息系统，并实现与公安机关的信息系统互联互通。 公安机关和易制爆危险化学品从业单位应当对易制爆危险化学品实行电子追踪标识管理，监控记录易制爆危险化学品流向、流量。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有权举报违反易制爆危险化学品治安管理规定的行为；接到举报的公安机关应当依法及时查处，并为举报人员保密，对举报有功人员给予奖励。"},{"i":8,"n":"第八条","txt":"易制爆危险化学品从业单位应当加强对治安管理工作的检查、考核和奖惩，及时发现、整改治安隐患，并保存检查、整改记录。"},{"i":9,"n":"第九条","txt":"公安机关接收同级应急管理部门通报的颁发危险化学品安全生产许可证、危险化学品安全使用许可证、危险化学品经营许可证、烟花爆竹安全生产许可证情况后，对属于易制爆危险化学品从业单位的，应当督促其建立信息系统。"},{"i":10,"n":"第十条","txt":"依法取得危险化学品安全生产许可证、危险化学品安全使用许可证、危险化学品经营许可证的企业，凭相应的许可证件购买易制爆危险化学品。民用爆炸物品生产企业凭民用爆炸物品生产许可证购买易制爆危险化学品。"},{"i":11,"n":"第十一条","txt":"本办法第十条以外的其他单位购买易制爆危险化学品的，应当向销售单位出具以下材料： （一）本单位《工商营业执照》《事业单位法人证书》等合法证明复印件、经办人身份证明复印件； （二）易制爆危险化学品合法用途说明，说明应当包含具体用途、品种、数量等内容。 严禁个人购买易制爆危险化学品。"},{"i":12,"n":"第十二条","txt":"危险化学品生产企业、经营企业销售易制爆危险化学品，应当查验本办法第十条或者第十一条规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位及任何个人销售易制爆危险化学品。"},{"i":13,"n":"第十三条","txt":"销售、购买、转让易制爆危险化学品应当通过本企业银行账户或者电子账户进行交易，不得使用现金或者实物进行交易。"},{"i":14,"n":"第十四条","txt":"危险化学品生产企业、经营企业销售易制爆危险化学品，应当如实记录购买单位的名称、地址、经办人姓名、身份证号码以及所购买的易制爆危险化学品的品种、数量、用途。销售记录以及相关许可证件复印件或者证明文件、经办人的身份证明复印件的保存期限不得少于一年。 易制爆危险化学品销售、购买单位应当在销售、购买后五日内，通过易制爆危险化学品信息系统，将所销售、购买的易制爆危险化学品的品种、数量以及流向信息报所在地县级公安机关备案。"},{"i":15,"n":"第十五条","txt":"易制爆危险化学品生产、进口和分装单位应当按照国家有关标准和规范要求，对易制爆危险化学品作出电子追踪标识，识读电子追踪标识可显示相应易制爆危险化学品品种、数量以及流向信息。"},{"i":16,"n":"第十六条","txt":"易制爆危险化学品从业单位应当如实登记易制爆危险化学品销售、购买、出入库、领取、使用、归还、处置等信息，并录入易制爆危险化学品信息系统。"},{"i":17,"n":"第十七条","txt":"易制爆危险化学品从业单位转产、停产、停业或者解散的，应当将生产装置、储存设施以及库存易制爆危险化学品的处置方案报主管部门和所在地县级公安机关备案。"},{"i":18,"n":"第十八条","txt":"易制爆危险化学品使用单位不得出借、转让其购买的易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本办法第十条或者第十一条规定的相关许可证件或者证明文件的单位转让。 双方应当在转让后五日内，将有关情况报告所在地县级公安机关。"},{"i":19,"n":"第十九条","txt":"运输易制爆危险化学品途中因住宿或者发生影响正常运输的情况，需要较长时间停车的，驾驶人员、押运人员应当采取相应的安全防范措施，并向公安机关报告。"},{"i":20,"n":"第二十条","txt":"易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向公安机关报告。公安机关接到报告后，应当根据实际情况立即向同级应急管理、生态环境、卫生健康等部门通报，采取必要的应急处置措施。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得交寄易制爆危险化学品或者在邮件、快递内夹带易制爆危险化学品，不得将易制爆危险化学品匿报或者谎报为普通物品交寄，不得将易制爆危险化学品交给不具有相应危险货物运输资质的企业托运。邮政企业、快递企业不得收寄易制爆危险化学品。运输企业、物流企业不得违反危险货物运输管理规定承运易制爆危险化学品。邮政企业、快递企业、运输企业、物流企业发现违反规定交寄或者托运易制爆危险化学品的，应当立即将有关情况报告公安机关和主管部门。"},{"i":22,"n":"第二十二条","txt":"易制爆危险化学品从业单位依法办理非经营性互联网信息服务备案手续后，可以在本单位网站发布易制爆危险化学品信息。 易制爆危险化学品从业单位应当在本单位网站主页显著位置标明可供查询的互联网信息服务备案编号。"},{"i":23,"n":"第二十三条","txt":"易制爆危险化学品从业单位不得在本单位网站以外的互联网应用服务中发布易制爆危险化学品信息及建立相关链接。 禁止易制爆危险化学品从业单位以外的其他单位在互联网发布易制爆危险化学品信息及建立相关链接。"},{"i":24,"n":"第二十四条","txt":"禁止个人在互联网上发布易制爆危险化学品生产、买卖、储存、使用信息。 禁止任何单位和个人在互联网上发布利用易制爆危险化学品制造爆炸物品方法的信息。"},{"i":25,"n":"第二十五条","txt":"易制爆危险化学品从业单位应当设置治安保卫机构，建立健全治安保卫制度，配备专职治安保卫人员负责易制爆危险化学品治安保卫工作，并将治安保卫机构的设置和人员的配备情况报所在地县级公安机关备案。治安保卫人员应当符合国家有关标准和规范要求，经培训后上岗。"},{"i":26,"n":"第二十六条","txt":"易制爆危险化学品应当按照国家有关标准和规范要求，储存在封闭式、半封闭式或者露天式危险化学品专用储存场所内，并根据危险品性能分区、分类、分库储存。 教学、科研、医疗、测试等易制爆危险化学品使用单位，可使用储存室或者储存柜储存易制爆危险化学品，单个储存室或者储存柜储存量应当在50公斤以下。"},{"i":27,"n":"第二十七条","txt":"易制爆危险化学品储存场所应当按照国家有关标准和规范要求，设置相应的人力防范、实体防范、技术防范等治安防范设施，防止易制爆危险化学品丢失、被盗、被抢。"},{"i":28,"n":"第二十八条","txt":"易制爆危险化学品从业单位应当建立易制爆危险化学品出入库检查、登记制度，定期核对易制爆危险化学品存放情况。 易制爆危险化学品丢失、被盗、被抢的，应当立即报告公安机关。"},{"i":29,"n":"第二十九条","txt":"易制爆危险化学品储存场所（储存室、储存柜除外）治安防范状况应当纳入单位安全评价的内容，经安全评价合格后方可使用。"},{"i":30,"n":"第三十条","txt":"构成重大危险源的易制爆危险化学品，应当在专用仓库内单独存放，并实行双人收发、双人保管制度。"},{"i":31,"n":"第三十一条","txt":"公安机关根据本地区工作实际，定期组织易制爆危险化学品从业单位监督检查；在重大节日、重大活动前或者期间组织监督抽查。 公安机关人民警察进行监督检查时应当出示人民警察证，表明执法身份，不得从事与职务无关的活动。"},{"i":32,"n":"第三十二条","txt":"监督检查内容包括： （一）易制爆危险化学品从业单位持有相关许可证件情况； （二）销售、购买、处置、使用、运输易制爆危险化学品是否符合有关规定； （三）易制爆危险化学品信息发布是否符合有关规定； （四）易制爆危险化学品流向登记是否符合有关规定； （五）易制爆危险化学品从业单位治安保卫机构、制度建设是否符合有关规定； （六）易制爆危险化学品从业单位及其储存场所治安防范设施是否符合有关规定； （七）法律、法规、规范和标准规定的其他内容。"},{"i":33,"n":"第三十三条","txt":"监督检查应当记录在案，归档管理。监督检查记录包括： （一）执行监督检查任务的人员姓名、单位、职务、警号； （二）监督检查的时间、地点、单位名称、检查事项； （三）发现的隐患问题及处理结果。"},{"i":34,"n":"第三十四条","txt":"监督检查记录一式两份，由监督检查人员、被检查单位管理人员签字确认；被检查单位管理人员对检查记录有异议或者拒绝签名的，检查人员应当在检查记录中注明。"},{"i":35,"n":"第三十五条","txt":"公安机关应当建立易制爆危险化学品从业单位风险评估、分级预警机制和与有关部门信息共享通报机制。"},{"i":36,"n":"第三十六条","txt":"违反本办法第六条第一款规定的，由公安机关责令限期改正，可以处一万元以下罚款；逾期不改正的，处违法所得三倍以下且不超过三万元罚款，没有违法所得的，处一万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法第十条、第十一条、第十八条第一款规定的，由公安机关依照《危险化学品安全管理条例》第八十四条第二款、第三款的规定处罚。"},{"i":38,"n":"第三十八条","txt":"违反本办法第十三条、第十五条规定的，由公安机关依照《中华人民共和国反恐怖主义法》第八十七条的规定处罚。"},{"i":39,"n":"第三十九条","txt":"违反本办法第十四条、第十六条、第十八条第二款、第二十八条第二款规定的，由公安机关依照《危险化学品安全管理条例》第八十一条的规定处罚。"},{"i":40,"n":"第四十条","txt":"违反本办法第十七条规定的，由公安机关依照《危险化学品安全管理条例》第八十二条第二款的规定处罚。"},{"i":41,"n":"第四十一条","txt":"违反本办法第十九条、第二十条规定的，由公安机关依照《危险化学品安全管理条例》第八十九条第三项、第四项的规定处罚。"},{"i":42,"n":"第四十二条","txt":"违反本办法第二十三条、第二十四条规定的，由公安机关责令改正，给予警告，对非经营活动处一千元以下罚款，对经营活动处违法所得三倍以下且不超过三万元罚款，没有违法所得的，处一万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"违反本办法第二十五条、第二十七条关于人力防范、实体防范规定，存在治安隐患的，由公安机关依照《企业事业单位内部治安保卫条例》第十九条的规定处罚。"},{"i":44,"n":"第四十四条","txt":"违反本办法第二十七条关于技术防范设施设置要求规定的，由公安机关依照《危险化学品安全管理条例》第七十八条第二款的规定处罚。"},{"i":45,"n":"第四十五条","txt":"任何单位和个人违反本办法规定，构成违反治安管理行为的，依照《中华人民共和国治安管理处罚法》的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"公安机关发现涉及其他主管部门的易制爆危险化学品违法违规行为，应当书面通报其他主管部门依法查处。"},{"i":47,"n":"第四十七条","txt":"公安机关人民警察在易制爆危险化学品治安管理中滥用职权、玩忽职守或者徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":48,"n":"第四十八条","txt":"含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品，其生产单位按照易制爆危险化学品使用单位管理，其成品的生产、销售、购买（含个人购买）、储存、使用、运输和处置等不适用本办法，分别执行《中华人民共和国食品安全法》《中华人民共和国药品管理法》《兽药管理条例》《消毒管理办法》等有关规定。"},{"i":49,"n":"第四十九条","txt":"易制爆危险化学品从业单位和相关场所、活动、设施等确定为防范恐怖袭击重点目标的，应当执行《中华人民共和国反恐怖主义法》的有关规定。"},{"i":50,"n":"第五十条","txt":"易制爆危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；进口的易制爆危险化学品的储存、使用、经营、运输、处置的安全管理，依照本办法的规定执行。"},{"i":51,"n":"第五十一条","txt":"本办法所称“以下”均包括本数。"},{"i":52,"n":"第五十二条","txt":"本办法自2019年8月10日起施行。"}],"jiguantuantiqiyeshiyedanweixiaofanganquanguanliguic172e1":[{"i":1,"n":"第一条","txt":"为了加强和规范机关、团体、企业、事业单位的消防安全管理，预防火灾和减少火灾危害，根据《中华人民共和国消防法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内的机关、团体、企业、事业单位(以下统称单位)自身的消防安全管理。 法律、法规另有规定的除外。"},{"i":3,"n":"第三条","txt":"单位应当遵守消防法律、法规、规章(以下统称消防法规)，贯彻预防为主、防消结合的消防工作方针，履行消防安全职责，保障消防安全。"},{"i":4,"n":"第四条","txt":"法人单位的法定代表人或者非法人单位的主要负责人是单位的消防安全责任人，对本单位的消防安全工作全面负责。"},{"i":5,"n":"第五条","txt":"单位应当落实逐级消防安全责任制和岗位消防安全责任制，明确逐级和岗位消防安全职责，确定各级、各岗位的消防安全责任人。"},{"i":6,"n":"第六条","txt":"单位的消防安全责任人应当履行下列消防安全职责： (一)贯彻执行消防法规，保障单位消防安全符合规定，掌握本单位的消防安全情况； (二)将消防工作与本单位的生产、科研、经营、管理等活动统筹安排，批准实施年度消防工作计划； (三)为本单位的消防安全提供必要的经费和组织保障； (四)确定逐级消防安全责任，批准实施消防安全制度和保障消防安全的操作规程； (五)组织防火检查，督促落实火灾隐患整改，及时处理涉及消防安全的重大问题； (六)根据消防法规的规定建立专职消防队、义务消防队; (七)组织制定符合本单位实际的灭火和应急疏散预案，并实施演练。"},{"i":7,"n":"第七条","txt":"单位可以根据需要确定本单位的消防安全管理人。消防安全管理人对单位的消防安全责任人负责，实施和组织落实下列消防安全管理工作： (一)拟订年度消防工作计划，组织实施日常消防安全管理工作； (二)组织制订消防安全制度和保障消防安全的操作规程并检查督促其落实； (三)拟订消防安全工作的资金投入和组织保障方案； (四)组织实施防火检查和火灾隐患整改工作； (五)组织实施对本单位消防设施、灭火器材和消防安全标志的维护保养，确保其完好有效，确保疏散通道和安全出口畅通； (六)组织管理专职消防队和义务消防队； (七)在员工中组织开展消防知识、技能的宣传教育和培训，组织灭火和应急疏散预案的实施和演练； (八)单位消防安全责任人委托的其他消防安全管理工作。 消防安全管理人应当定期向消防安全责任人报告消防安全情况，及时报告涉及消防安全的重大问题。未确定消防安全管理人的单位，前款规定的消防安全管理工作由单位消"},{"i":8,"n":"第八条","txt":"实行承包、租赁或者委托经营、管理时，产权单位应当提供符合消防安全要求的建筑物，当事人在订立的合同中依照有关规定明确各方的消防安全责任；消防车通道、涉及公共消防安全的疏散设施和其他建筑消防设施应当由产权单位或者委托管理的单位统一管理。 承包、承租或者受委托经营、管理的单位应当遵守本规定，在其使用、管理范围内履行消防安全职责。"},{"i":9,"n":"第九条","txt":"对于有两个以上产权单位和使用单位的建筑物，各产权单位、使用单位对消防车通道、涉及公共消防安全的疏散设施和其他建筑消防设施应当明确管理责任，可以委托统一管理。"},{"i":10,"n":"第十条","txt":"居民住宅区的物业管理单位应当在管理范围内履行下列消防安全职责： (一)制定消防安全制度，落实消防安全责任，开展消防安全宣传教育； (二)开展防火检查，消除火灾隐患； (三)保障疏散通道、安全出口、消防车通道畅通； (四)保障公共消防设施、器材以及消防安全标志完好有效。 其他物业管理单位应当对受委托管理范围内的公共消防安全管理工作负责。"},{"i":11,"n":"第十一条","txt":"举办集会、焰火晚会、灯会等具有火灾危险的大型活动的主办单位、承办单位以及提供场地的单位，应当在订立的合同中明确各方的消防安全责任。"},{"i":12,"n":"第十二条","txt":"建筑工程施工现场的消防安全由施工单位负责。实行施工总承包的，由总承包单位负责。分包单位向总承包单位负责，服从总承包单位对施工现场的消防安全管理。 对建筑物进行局部改建、扩建和装修的工程，建设单位应当与施工单位在订立的合同中明确各方对施工现场的消防安全责任。"},{"i":13,"n":"第十三条","txt":"下列范围的单位是消防安全重点单位，应当按照本规定的要求，实行严格管理： (一)商场(市场)、宾馆(饭店)、体育场(馆)、会堂、公共娱乐场所等公众聚集场所(以下统称公众聚集场所)； (二)医院、养老院和寄宿制的学校、托儿所、幼儿园； (三)国家机关； (四)广播电台、电视台和邮政、通信枢纽； (五)客运车站、码头、民用机场； (六)公共图书馆、展览馆、博物馆、档案馆以及具有火灾危险性的文物保护单位； (七)发电厂(站)和电网经营企业； (八)易燃易爆化学物品的生产、充装、储存、供应、销售单位； (九)服装、制鞋等劳动密集型生产、加工企业； (十)重要的科研单位； (十一)其他发生火灾可能性较大以及一旦发生火灾可能造成重大人身伤亡或者财产损失的单位。 高层办公楼(写字楼)、高层公寓楼等高层公共建筑，城市地下铁道、地下观光隧道等地下公共建筑和城市重要的交通隧道，粮、棉、木材、百货等物资集中的"},{"i":14,"n":"第十四条","txt":"消防安全重点单位及其消防安全责任人、消防安全管理人应当报当地公安消防机构备案。"},{"i":15,"n":"第十五条","txt":"消防安全重点单位应当设置或者确定消防工作的归口管理职能部门，并确定专职或者兼职的消防管理人员；其他单位应当确定专职或者兼职消防管理人员，可以确定消防工作的归口管理职能部门。归口管理职能部门和专兼职消防管理人员在消防安全责任人或者消防安全管理人的领导下开展消防安全管理工作。"},{"i":16,"n":"第十六条","txt":"公众聚集场所应当在具备下列消防安全条件后，向当地公安消防机构申报进行消防安全检查，经检查合格后方可开业使用： (一)依法办理建筑工程消防设计审核手续，并经消防验收合格； (二)建立健全消防安全组织，消防安全责任明确； (三)建立消防安全管理制度和保障消防安全的操作规程； (四)员工经过消防安全培训； (五)建筑消防设施齐全、完好有效； (六)制定灭火和应急疏散预案。"},{"i":17,"n":"第十七条","txt":"举办集会、焰火晚会、灯会等具有火灾危险的大型活动，主办或者承办单位应当在具备消防安全条件后，向公安消防机构申报对活动现场进行消防安全检查，经检查合格后方可举办。"},{"i":18,"n":"第十八条","txt":"单位应当按照国家有关规定，结合本单位的特点，建立健全各项消防安全制度和保障消防安全的操作规程，并公布执行。 单位消防安全制度主要包括以下内容：消防安全教育、培训；防火巡查、检查；安全疏散设施管理；消防(控制室)值班；消防设施、器材维护管理；火灾隐患整改；用火、用电安全管理；易燃易爆危险物品和场所防火防爆；专职和义务消防队的组织管理；灭火和应急疏散预案演练；燃气和电气设备的检查和管理(包括防雷、防静电)；消防安全工作考评和奖惩；其他必要的消防安全内容。"},{"i":19,"n":"第十九条","txt":"单位应当将容易发生火灾、一旦发生火灾可能严重危及人身和财产安全以及对消防安全有重大影响的部位确定为消防安全重点部位，设置明显的防火标志，实行严格管理。"},{"i":20,"n":"第二十条","txt":"单位应当对动用明火实行严格的消防安全管理。禁止在具有火灾、爆炸危险的场所使用明火；因特殊情况需要进行电、气焊等明火作业的，动火部门和人员应当按照单位的用火管理制度办理审批手续，落实现场监护人，在确认无火灾、爆炸危险后方可动火施工。动火施工人员应当遵守消防安全规定，并落实相应的消防安全措施。 公众聚集场所或者两个以上单位共同使用的建筑物局部施工需要使用明火时，施工单位和使用单位应当共同采取措施，将施工区和使用区进行防火分隔，清除动火区域的易燃、可燃物，配置消防器材，专人监护，保证施工及使用范围的消防安全。 公共娱乐场所在营业期间禁止动火施工。"},{"i":21,"n":"第二十一条","txt":"单位应当保障疏散通道、安全出口畅通，并设置符合国家规定的消防安全疏散指示标志和应急照明设施，保持防火门、防火卷帘、消防安全疏散指示标志、应急照明、机械排烟送风、火灾事故广播等设施处于正常状态。 严禁下列行为： (一)占用疏散通道； (二)在安全出口或者疏散通道上安装栅栏等影响疏散的障碍物； (三)在营业、生产、教学、工作等期间将安全出口上锁、遮挡或者将消防安全疏散指示标志遮挡、覆盖； (四)其他影响安全疏散的行为。"},{"i":22,"n":"第二十二条","txt":"单位应当遵守国家有关规定，对易燃易爆危险物品的生产、使用、储存、销售、运输或者销毁实行严格的消防安全管理。"},{"i":23,"n":"第二十三条","txt":"单位应当根据消防法规的有关规定，建立专职消防队、义务消防队，配备相应的消防装备、器材，并组织开展消防业务学习和灭火技能训练，提高预防和扑救火灾的能力。"},{"i":24,"n":"第二十四条","txt":"单位发生火灾时，应当立即实施灭火和应急疏散预案，务必做到及时报警,迅速扑救火灾，及时疏散人员。邻近单位应当给予支援。任何单位、人员都应当无偿为报火警提供便利，不得阻拦报警。 单位应当为公安消防机构抢救人员、扑救火灾提供便利和条件。 火灾扑灭后，起火单位应当保护现场，接受事故调查，如实提供火灾事故的情况，协助公安消防机构调查火灾原因，核定火灾损失，查明火灾事故责任。未经公安消防机构同意，不得擅自清理火灾现场。"},{"i":25,"n":"第二十五条","txt":"消防安全重点单位应当进行每日防火巡查，并确定巡查的人员、内容、部位和频次。其他单位可以根据需要组织防火巡查。巡查的内容应当包括： (一)用火、用电有无违章情况； (二)安全出口、疏散通道是否畅通，安全疏散指示标志、应急照明是否完好； (三)消防设施、器材和消防安全标志是否在位、完整； (四)常闭式防火门是否处于关闭状态，防火卷帘下是否堆放物品影响使用； (五)消防安全重点部位的人员在岗情况； (六)其他消防安全情况。 公众聚集场所在营业期间的防火巡查应当至少每二小时一次；营业结束时应当对营业现场进行检查，消除遗留火种。医院、养老院、寄宿制的学校、托儿所、幼儿园应当加强夜间防火巡查，其他消防安全重点单位可以结合实际组织夜间防火巡查。 防火巡查人员应当及时纠正违章行为，妥善处置火灾危险，无法当场处置的，应当立即报告。发现初起火灾应当立即报警并及时扑救。 防火巡查应当填写巡查记录，巡查人员及"},{"i":26,"n":"第二十六条","txt":"机关、团体、事业单位应当至少每季度进行一次防火检查，其他单位应当至少每月进行一次防火检查。检查的内容应当包括： (一)火灾隐患的整改情况以及防范措施的落实情况； (二)安全疏散通道、疏散指示标志、应急照明和安全出口情况； (三)消防车通道、消防水源情况； (四)灭火器材配置及有效情况； (五)用火、用电有无违章情况； (六)重点工种人员以及其他员工消防知识的掌握情况； (七)消防安全重点部位的管理情况； (八)易燃易爆危险物品和场所防火防爆措施的落实情况以及其他重要物资的防火安全情况； (九)消防(控制室)值班情况和设施运行、记录情况； (十)防火巡查情况； (十一)消防安全标志的设置情况和完好、有效情况； (十二)其他需要检查的内容。 防火检查应当填写检查记录。检查人员和被检查部门负责人应当在检查记录上签名。"},{"i":27,"n":"第二十七条","txt":"单位应当按照建筑消防设施检查维修保养有关规定的要求，对建筑消防设施的完好有效情况进行检查和维修保养。"},{"i":28,"n":"第二十八条","txt":"设有自动消防设施的单位，应当按照有关规定定期对其自动消防设施进行全面检查测试，并出具检测报告，存档备查。"},{"i":29,"n":"第二十九条","txt":"单位应当按照有关规定定期对灭火器进行维护保养和维修检查。对灭火器应当建立档案资料，记明配置类型、数量、设置位置、检查维修单位(人员)、更换药剂的时间等有关情况。"},{"i":30,"n":"第三十条","txt":"单位对存在的火灾隐患，应当及时予以消除。"},{"i":31,"n":"第三十一条","txt":"对下列违反消防安全规定的行为，单位应当责成有关人员当场改正并督促落实： (一)违章进入生产、储存易燃易爆危险物品场所的； (二)违章使用明火作业或者在具有火灾、爆炸危险的场所吸烟、使用明火等违反禁令的； (三)将安全出口上锁、遮挡，或者占用、堆放物品影响疏散通道畅通的； (四)消火栓、灭火器材被遮挡影响使用或者被挪作他用的； (五)常闭式防火门处于开启状态，防火卷帘下堆放物品影响使用的； (六)消防设施管理、值班人员和防火巡查人员脱岗的； (七)违章关闭消防设施、切断消防电源的； (八)其他可以当场改正的行为。 违反前款规定的情况以及改正情况应当有记录并存档备查。"},{"i":32,"n":"第三十二条","txt":"对不能当场改正的火灾隐患，消防工作归口管理职能部门或者专兼职消防管理人员应当根据本单位的管理分工，及时将存在的火灾隐患向单位的消防安全管理人或者消防安全责任人报告，提出整改方案。消防安全管理人或者消防安全责任人应当确定整改的措施、期限以及负责整改的部门、人员，并落实整改资金。 在火灾隐患未消除之前，单位应当落实防范措施，保障消防安全。不能确保消防安全，随时可能引发火灾或者一旦发生火灾将严重危及人身安全的，应当将危险部位停产停业整改。"},{"i":33,"n":"第三十三条","txt":"火灾隐患整改完毕，负责整改的部门或者人员应当将整改情况记录报送消防安全责任人或者消防安全管理人签字确认后存档备查。"},{"i":34,"n":"第三十四条","txt":"对于涉及城市规划布局而不能自身解决的重大火灾隐患，以及机关、团体、事业单位确无能力解决的重大火灾隐患，单位应当提出解决方案并及时向其上级主管部门或者当地人民政府报告。"},{"i":35,"n":"第三十五条","txt":"对公安消防机构责令限期改正的火灾隐患，单位应当在规定的期限内改正并写出火灾隐患整改复函，报送公安消防机构。"},{"i":36,"n":"第三十六条","txt":"单位应当通过多种形式开展经常性的消防安全宣传教育。消防安全重点单位对每名员工应当至少每年进行一次消防安全培训。宣传教育和培训内容应当包括： (一)有关消防法规、消防安全制度和保障消防安全的操作规程； (二)本单位、本岗位的火灾危险性和防火措施； (三)有关消防设施的性能、灭火器材的使用方法； (四)报火警、扑救初起火灾以及自救逃生的知识和技能。 公众聚集场所对员工的消防安全培训应当至少每半年进行一次，培训的内容还应当包括组织、引导在场群众疏散的知识和技能。 单位应当组织新上岗和进入新岗位的员工进行上岗前的消防安全培训。"},{"i":37,"n":"第三十七条","txt":"公众聚集场所在营业、活动期间，应当通过张贴图画、广播、闭路电视等向公众宣传防火、灭火、疏散逃生等常识。 学校、幼儿园应当通过寓教于乐等多种形式对学生和幼儿进行消防安全常识教育。"},{"i":38,"n":"第三十八条","txt":"下列人员应当接受消防安全专门培训： (一)单位的消防安全责任人、消防安全管理人； (二)专、兼职消防管理人员； (三)消防控制室的值班、操作人员； (四)其他依照规定应当接受消防安全专门培训的人员。 前款规定中的第(三)项人员应当持证上岗。"},{"i":39,"n":"第三十九条","txt":"消防安全重点单位制定的灭火和应急疏散预案应当包括下列内容： (一)组织机构，包括：灭火行动组、通讯联络组、疏散引导组、安全防护救护组； (二)报警和接警处置程序； (三)应急疏散的组织程序和措施； (四)扑救初起火灾的程序和措施； (五)通讯联络、安全防护救护的程序和措施。"},{"i":40,"n":"第四十条","txt":"消防安全重点单位应当按照灭火和应急疏散预案，至少每半年进行一次演练，并结合实际，不断完善预案。其他单位应当结合本单位实际，参照制定相应的应急方案，至少每年组织一次演练。 消防演练时，应当设置明显标识并事先告知演练范围内的人员。"},{"i":41,"n":"第四十一条","txt":"消防安全重点单位应当建立健全消防档案。消防档案应当包括消防安全基本情况和消防安全管理情况。消防档案应当详实，全面反映单位消防工作的基本情况，并附有必要的图表，根据情况变化及时更新。 单位应当对消防档案统一保管、备查。"},{"i":42,"n":"第四十二条","txt":"消防安全基本情况应当包括以下内容： (一)单位基本概况和消防安全重点部位情况； (二)建筑物或者场所施工、使用或者开业前的消防设计审核、消防验收以及消防安全检查的文件、资料； (三)消防管理组织机构和各级消防安全责任人； (四)消防安全制度； (五)消防设施、灭火器材情况； (六)专职消防队、义务消防队人员及其消防装备配备情况； (七)与消防安全有关的重点工种人员情况； (八)新增消防产品、防火材料的合格证明材料； (九)灭火和应急疏散预案。"},{"i":43,"n":"第四十三条","txt":"消防安全管理情况应当包括以下内容： (一)公安消防机构填发的各种法律文书； (二)消防设施定期检查记录、自动消防设施全面检查测试的报告以及维修保养的记录； (三)火灾隐患及其整改情况记录； (四)防火检查、巡查记录； (五)有关燃气、电气设备检测(包括防雷、防静电)等记录资料； (六)消防安全培训记录； (七)灭火和应急疏散预案的演练记录； (八)火灾情况记录； (九)消防奖惩情况记录。 前款规定中的第(二)、(三)、(四)、(五)项记录，应当记明检查的人员、时间、部位、内容、发现的火灾隐患以及处理措施等；第(六)项记录，应当记明培训的时间、参加人员、内容等；第(七)项记录，应当记明演练的时间、地点、内容、参加部门以及人员等。"},{"i":44,"n":"第四十四条","txt":"其他单位应当将本单位的基本概况、公安消防机构填发的各种法律文书、与消防工作有关的材料和记录等统一保管备查。"},{"i":45,"n":"第四十五条","txt":"单位应当将消防安全工作纳入内部检查、考核、评比内容。对在消防安全工作中成绩突出的部门(班组)和个人，单位应当给予表彰奖励。对未依法履行消防安全职责或者违反单位消防安全制度的行为，应当依照有关规定对责任人员给予行政纪律处分或者其他处理。"},{"i":46,"n":"第四十六条","txt":"违反本规定，依法应当给予行政处罚的，依照有关法律、法规予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"公安消防机构对本规定的执行情况依法实施监督，并对自身滥用职权、玩忽职守、徇私舞弊的行为承担法律责任。"},{"i":48,"n":"第四十八条","txt":"规定自2002年5月1日起施行。本规定施行以前公安部发布的规章中的有关规定与本规定不一致的，以本规定为准。"}],"jidongchexiuliyebaofeijidongchehuishouyezhianguanlce00e2":[{"i":1,"n":"第一条","txt":"为了加强对机动车修理业、报废机动车回收业的治安管理，保护合法经营，预防、打击违法犯罪活动，根据国家有关法律、法规制定本办法。"},{"i":2,"n":"第二条","txt":"机动车修理业、报废机动车回收业的治安管理，适用本办法。"},{"i":3,"n":"第三条","txt":"对机动车修理企业和个体工商户、报废机动车回收企业的治安管理，由所在地市、县公安局、城市公安分局负责。 公安机关应当对机动车修理企业和个体工商户、报废机动车回收企业的治安情况进行检查，对发现的治安问题及时处理。"},{"i":4,"n":"第四条","txt":"机动车修理企业和个体工商户、报废机动车回收企业的法定代表人或经营负责人是本单位的治安责任人，负责本单位的治安防范工作，并履行下列义务： （一）制定并落实各项治安防范制度； （二）发现可疑情况和盗窃、抢劫、销赃等违法犯罪线索及时报告公安机关； （三）监督做好查验、登记工作； （四）对公安机关检查发现的治安隐患及时改正。 治安责任人的责任，不得因承包、租赁经营等原因转移给他人。承包、租赁经营负责人在承包、租赁期间应同时承担前款规定的治安责任。"},{"i":5,"n":"第五条","txt":"严禁利用机动车修理业、报废机动车回收业进行走私、销赃等违法犯罪活动。"},{"i":6,"n":"第六条","txt":"机动车修理企业和个体工商户、报废机动车回收企业，必须建立承修登记、查验制度，并接受公安机关的检查。"},{"i":7,"n":"第七条","txt":"机动车修理企业和个体工商户承修机动车应如实登记下列项目： （一）按照机动车行驶证项目登记送修车辆的号牌、车型、发动机号码、车架号码、厂牌型号、车身颜色； （二）车主名称或姓名、送修人姓名和居民身份证号码或驾驶证号码； （三）修理项目（事故车辆应详细登记修理部位）； （四）送修时间、收车人姓名。"},{"i":8,"n":"第八条","txt":"报废机动车回收企业回收报废机动车应如实登记下列项目： （一）报废机动车车主名称或姓名、送车人姓名、居民身份证号码； （二）按照公安交通管理部门出具的机动车报废证明登记报废车车牌号码、车型、发动机号码、车架号码、车身颜色； （三）收车人姓名。"},{"i":9,"n":"第九条","txt":"机动车修理企业和个体工商户承修更换发动机或车身（架）、改装车型、改变车身颜色等项目的，必须查验公安交通管理部门出具的机动车变更、改装审批证明。 报废机动车回收企业回收报废机动车，必须查验公安交通管理部门出具的机动车报废证明。"},{"i":10,"n":"第十条","txt":"机动车修理企业和个体工商户承修车辆、报废机动车回收企业回收报废机动车时，发现下列可疑情况，应立即报告当地公安机关： （一）证明、证件有变造、伪造痕迹的； （二）送修车辆与机动车行驶证或回收车辆与报废证明不符的； （三）车辆发动机号码、车架号码有改动痕迹或车辆有其他明显改动、破坏痕迹的； （四）送修人要求更改发动机号码、车架号码的； （五）公安机关查控的机动车辆； （六）交通肇事逃逸嫌疑车辆及其他可疑情况。"},{"i":11,"n":"第十一条","txt":"公安机关在接到报告后，应在四十八小时内作出处理决定。对有赃物嫌疑的，公安机关应当予以扣留，并开具凭证。经查明确属赃物的，依照国家有关规定处理；不是赃物的，应及时退还。 公安机关在规定的期限内没有作出处理决定的，承修单位可以按正常业务办理。"},{"i":12,"n":"第十二条","txt":"机动车修理企业和个体工商户严禁从事下列活动： （一）明知是盗窃、抢劫所得机动车而予以改装、拼装、倒卖； （二）无公安交通管理部门出具的机动车变更、改装审批证明而更换发动机、车身（架）、改装车型、改变车身颜色； （三）更改发动机号码或车架号码； （四）回收报废机动车； （五）非法拼（组）装汽车、摩托车； （六）明知是交通肇事逃逸车辆未向公安机关报告而修理的。"},{"i":13,"n":"第十三条","txt":"报废机动车回收企业严禁从事下列活动： （一）明知是盗窃、抢劫所得机动车而予以拆解、改装、拼装、倒卖； （二）回收无公安交通管理部门出具的机动车报废证明的机动车的； （三）利用报废机动车拼装整车。"},{"i":14,"n":"第十四条","txt":"承修机动车或回收报废机动车不按规定如实登记的，对机动车修理企业和个体工商户处五百元以上三千元以下罚款；对报废机动车回收企业按照《废旧金属收购业治安管理办法》第十三条第五项规定处罚。 对前款机动车修理企业和报废机动车回收企业直接负责的主管人员和其他直接责任人员处警告或五百元以下罚款。"},{"i":15,"n":"第十五条","txt":"机动车修理企业和个体工商户、报废机动车回收企业明知是盗窃、抢劫所得机动车而予以拆解、改装、拼装、倒卖的，对其直接负责的主管人员和其他直接责任人员依照国家有关规定追究刑事责任；尚不构成犯罪的，依照《中华人民共和国治安管理处罚条例》予以处罚。"},{"i":16,"n":"第十六条","txt":"承修无公安交通管理部门出具的车辆变更、改装审批证明更换发动机、车身（架）、改装车型、改变车身颜色的车辆或明知是交通肇事逃逸车辆未向公安机关报告而修理的，对机动车修理企业和个体工商户处五千元以上三万元以下罚款；回收无报废证明的机动车的，对报废机动车回收企业处五千元以上三万元以下罚款。 对前款机动车修理企业和报废机动车回收企业直接负责的主管人员和其他直接责任人员处警告或二千元以下罚款。"},{"i":17,"n":"第十七条","txt":"对更改发动机号码、车架号码的机动车修理企业和个体工商户，处五千元以上三万元以下罚款；对机动车修理企业和报废机动车回收企业直接负责的主管人员和其他直接责任人员处警告或二千元以下罚款，构成犯罪的依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"对机动车修理企业和个体工商户回收报废机动车的，按照《废旧金属收购业治安管理办法》第十三条第一项规定没收非法回收的报废机动车及非法所得，可以并处五千元以上一万元以下罚款。"},{"i":19,"n":"第十九条","txt":"对非法拼（组）装汽车、摩托车的，按照国务院批准的《关于禁止非法拼（组）装汽车、摩托车的通告》的规定处理。"},{"i":20,"n":"第二十条","txt":"对机动车修理企业和个体工商户、报废机动车回收企业违反本办法有关规定，情节严重或屡次违反规定不予改正的，会同有关部门吊销有关证照。"},{"i":21,"n":"第二十一条","txt":"对执行本办法协助公安机关查获违法犯罪分子作出显著成绩的单位和个人，由公安机关给予表彰。"},{"i":22,"n":"第二十二条","txt":"本办法所称机动车修理业是指经营各种机动车辆修理和具有汽车喷漆、划痕修补等专项修理功能的企业、个体工商户以及经销机动车配件的商店。 本办法所称报废机动车回收业是指回收、拆解报废机动车的企业。"},{"i":23,"n":"第二十三条","txt":"本办法中所称以上、以下，都包括本数在内。"},{"i":24,"n":"第二十四条","txt":"本办法自公布之日起施行。"}],"jidongchedengjiguiding":[{"i":1,"n":"第一条","txt":"为了规范机动车登记，保障道路交通安全，保护公民、法人和其他组织的合法权益，根据《中华人民共和国道路交通安全法》及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定由公安机关交通管理部门负责实施。 省级公安机关交通管理部门负责本省（自治区、直辖市）机动车登记工作的指导、检查和监督。直辖市公安机关交通管理部门车辆管理所、设区的市或者相当于同级的公安机关交通管理部门车辆管理所负责办理本行政区域内机动车登记业务。 县级公安机关交通管理部门车辆管理所可以办理本行政区域内除危险货物运输车、校车、中型以上载客汽车登记以外的其他机动车登记业务。具体业务范围和办理条件由省级公安机关交通管理部门确定。 警用车辆登记业务按照有关规定办理。"},{"i":3,"n":"第三条","txt":"车辆管理所办理机动车登记业务，应当遵循依法、公开、公正、便民的原则。 车辆管理所办理机动车登记业务，应当依法受理申请人的申请，审查申请人提交的材料，按规定查验机动车。对符合条件的，按照规定的标准、程序和期限办理机动车登记。对申请材料不齐全或者不符合法定形式的，应当一次书面或者电子告知申请人需要补正的全部内容。对不符合规定的，应当书面或者电子告知不予受理、登记的理由。 车辆管理所应当将法律、行政法规和本规定的有关办理机动车登记的事项、条件、依据、程序、期限以及收费标准、需要提交的全部材料的目录和申请表示范文本等在办公场所公示。 省级、设区的市或者相当于同级的公安机关交通管理部门应当在互联网上发布信息，便于群众查阅办理机动车登记的有关规定，查询机动车登记、检验等情况，下载、使用有关表格。"},{"i":4,"n":"第四条","txt":"车辆管理所办理机动车登记业务时，应当按照减环节、减材料、减时限的要求，积极推行一次办结、限时办结等制度，为申请人提供规范、便利、高效的服务。 公安机关交通管理部门应当积极推进与有关部门信息互联互通，对实现信息共享、网上核查的，申请人免予提交相关证明凭证。 公安机关交通管理部门应当按照就近办理、便捷办理的原则，推进在机动车销售企业、二手车交易市场等地设置服务站点，方便申请人办理机动车登记业务，并在办公场所和互联网公示辖区内的业务办理网点、地址、联系电话、办公时间和业务范围。"},{"i":5,"n":"第五条","txt":"车辆管理所应当使用全国统一的计算机管理系统办理机动车登记、核发机动车登记证书、号牌、行驶证和检验合格标志。 计算机管理系统的数据库标准和软件全国统一，能够完整、准确地记录和存储机动车登记业务全过程和经办人员信息，并能够实时将有关信息传送到全国公安交通管理信息系统。"},{"i":6,"n":"第六条","txt":"车辆管理所应当使用互联网交通安全综合服务管理平台受理申请人网上提交的申请，验证申请人身份，按规定办理机动车登记业务。 互联网交通安全综合服务管理平台信息管理系统数据库标准和软件全国统一。"},{"i":7,"n":"第七条","txt":"申请办理机动车登记业务的，应当如实向车辆管理所提交规定的材料、交验机动车，如实申告规定的事项，并对其申请材料实质内容的真实性以及机动车的合法性负责。"},{"i":8,"n":"第八条","txt":"公安机关交通管理部门应当建立机动车登记业务监督制度，加强对机动车登记、牌证生产制作和发放等监督管理。"},{"i":9,"n":"第九条","txt":"车辆管理所办理机动车登记业务时可以依据相关法律法规认可、使用电子签名、电子印章、电子证照。"},{"i":10,"n":"第十条","txt":"初次申领机动车号牌、行驶证的，机动车所有人应当向住所地的车辆管理所申请注册登记。"},{"i":11,"n":"第十一条","txt":"机动车所有人应当到机动车安全技术检验机构对机动车进行安全技术检验，取得机动车安全技术检验合格证明后申请注册登记。但经海关进口的机动车和国务院机动车产品主管部门认定免予安全技术检验的机动车除外。 免予安全技术检验的机动车有下列情形之一的，应当进行安全技术检验： （一）国产机动车出厂后两年内未申请注册登记的； （二）经海关进口的机动车进口后两年内未申请注册登记的； （三）申请注册登记前发生交通事故的。 专用校车办理注册登记前，应当按照专用校车国家安全技术标准进行安全技术检验。"},{"i":12,"n":"第十二条","txt":"申请注册登记的，机动车所有人应当交验机动车，确认申请信息，并提交以下证明、凭证： （一）机动车所有人的身份证明； （二）购车发票等机动车来历证明； （三）机动车整车出厂合格证明或者进口机动车进口凭证； （四）机动车交通事故责任强制保险凭证； （五）车辆购置税、车船税完税证明或者免税凭证，但法律规定不属于征收范围的除外； （六）法律、行政法规规定应当在机动车注册登记时提交的其他证明、凭证。 不属于经海关进口的机动车和国务院机动车产品主管部门规定免予安全技术检验的机动车，还应当提交机动车安全技术检验合格证明。 车辆管理所应当自受理申请之日起二日内，查验机动车，采集、核对车辆识别代号拓印膜或者电子资料，审查提交的证明、凭证，核发机动车登记证书、号牌、行驶证和检验合格标志。 机动车安全技术检验、税务、保险等信息实现与有关部门或者机构联网核查的，申请人免予提交相关证明、凭证，车辆管理所核对相关电"},{"i":13,"n":"第十三条","txt":"车辆管理所办理消防车、救护车、工程救险车注册登记时，应当对车辆的使用性质、标志图案、标志灯具和警报器进行审查。 机动车所有人申请机动车使用性质登记为危险货物运输、公路客运、旅游客运的，应当具备相关道路运输许可；实现与有关部门联网核查道路运输许可信息、车辆使用性质信息的，车辆管理所应当核对相关电子信息。 申请危险货物运输车登记的，机动车所有人应当为单位。 车辆管理所办理注册登记时，应当对牵引车和挂车分别核发机动车登记证书、号牌、行驶证和检验合格标志。"},{"i":14,"n":"第十四条","txt":"车辆管理所实现与机动车制造厂新车出厂查验信息联网的，机动车所有人申请小型、微型非营运载客汽车注册登记时，免予交验机动车。 车辆管理所应当会同有关部门在具备条件的摩托车销售企业推行摩托车带牌销售，方便机动车所有人购置车辆、投保保险、缴纳税款、注册登记一站式办理。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不予办理注册登记： （一）机动车所有人提交的证明、凭证无效的； （二）机动车来历证明被涂改或者机动车来历证明记载的机动车所有人与身份证明不符的； （三）机动车所有人提交的证明、凭证与机动车不符的； （四）机动车未经国务院机动车产品主管部门许可生产或者未经国家进口机动车主管部门许可进口的； （五）机动车的型号或者有关技术参数与国务院机动车产品主管部门公告不符的； （六）机动车的车辆识别代号或者有关技术参数不符合国家安全技术标准的； （七）机动车达到国家规定的强制报废标准的； （八）机动车被监察机关、人民法院、人民检察院、行政执法部门依法查封、扣押的； （九）机动车属于被盗抢骗的； （十）其他不符合法律、行政法规规定的情形。"},{"i":16,"n":"第十六条","txt":"已注册登记的机动车有下列情形之一的，机动车所有人应当向登记地车辆管理所申请变更登记： （一）改变车身颜色的； （二）更换发动机的； （三）更换车身或者车架的； （四）因质量问题更换整车的； （五）机动车登记的使用性质改变的； （六）机动车所有人的住所迁出、迁入车辆管理所管辖区域的。 属于第一款第一项至第三项规定的变更事项的，机动车所有人应当在变更后十日内向车辆管理所申请变更登记。"},{"i":17,"n":"第十七条","txt":"申请变更登记的，机动车所有人应当交验机动车，确认申请信息，并提交以下证明、凭证： （一）机动车所有人的身份证明； （二）机动车登记证书； （三）机动车行驶证； （四）属于更换发动机、车身或者车架的，还应当提交机动车安全技术检验合格证明； （五）属于因质量问题更换整车的，还应当按照第十二条的规定提交相关证明、凭证。 车辆管理所应当自受理之日起一日内，查验机动车，审查提交的证明、凭证，在机动车登记证书上签注变更事项，收回行驶证，重新核发行驶证。属于第十六条第一款第三项、第四项、第六项规定的变更登记事项的，还应当采集、核对车辆识别代号拓印膜或者电子资料。属于机动车使用性质变更为公路客运、旅游客运，实现与有关部门联网核查道路运输许可信息、车辆使用性质信息的，还应当核对相关电子信息。属于需要重新核发机动车号牌的，收回号牌、行驶证，核发号牌、行驶证和检验合格标志。 小型、微型载客汽车因改变车身颜色"},{"i":18,"n":"第十八条","txt":"机动车所有人的住所迁出车辆管理所管辖区域的，转出地车辆管理所应当自受理之日起三日内，查验机动车，在机动车登记证书上签注变更事项，制作上传机动车电子档案资料。机动车所有人应当在三十日内到住所地车辆管理所申请机动车转入。属于小型、微型载客汽车或者摩托车机动车所有人的住所迁出车辆管理所管辖区域的，应当向转入地车辆管理所申请变更登记。 申请机动车转入的，机动车所有人应当确认申请信息，提交身份证明、机动车登记证书，并交验机动车。机动车在转入时已超过检验有效期的，应当按规定进行安全技术检验并提交机动车安全技术检验合格证明和交通事故责任强制保险凭证。车辆管理所应当自受理之日起三日内，查验机动车，采集、核对车辆识别代号拓印膜或者电子资料，审查相关证明、凭证和机动车电子档案资料，在机动车登记证书上签注转入信息，收回号牌、行驶证，确定新的机动车号牌号码，核发号牌、行驶证和检验合格标志。 机动车所有人申请转"},{"i":19,"n":"第十九条","txt":"机动车所有人为两人以上，需要将登记的所有人姓名变更为其他共同所有人姓名的，可以向登记地车辆管理所申请变更登记。申请时，机动车所有人应当共同提出申请，确认申请信息，提交机动车登记证书、行驶证、变更前和变更后机动车所有人的身份证明和共同所有的公证证明，但属于夫妻双方共同所有的，可以提供结婚证或者证明夫妻关系的居民户口簿。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，在机动车登记证书上签注变更事项，收回号牌、行驶证，确定新的机动车号牌号码，重新核发号牌、行驶证和检验合格标志。变更后机动车所有人的住所不在车辆管理所管辖区域内的，迁出地和迁入地车辆管理所应当按照第十八条的规定办理变更登记。"},{"i":20,"n":"第二十条","txt":"同一机动车所有人名下机动车的号牌号码需要互换，符合以下情形的，可以向登记地车辆管理所申请变更登记： （一）两辆机动车在同一辖区车辆管理所登记； （二）两辆机动车属于同一号牌种类； （三）两辆机动车使用性质为非营运。 机动车所有人应当确认申请信息，提交机动车所有人身份证明、两辆机动车的登记证书、行驶证、号牌。申请前，应当将两车的道路交通安全违法行为和交通事故处理完毕。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，在机动车登记证书上签注变更事项，收回两车的号牌、行驶证，重新核发号牌、行驶证和检验合格标志。 同一机动车一年内可以互换变更一次机动车号牌号码。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，不予办理变更登记： （一）改变机动车的品牌、型号和发动机型号的，但经国务院机动车产品主管部门许可选装的发动机除外； （二）改变已登记的机动车外形和有关技术参数的，但法律、法规和国家强制性标准另有规定的除外； （三）属于第十五条第一项、第七项、第八项、第九项规定情形的。 距机动车强制报废标准规定要求使用年限一年以内的机动车，不予办理第十六条第五项、第六项规定的变更事项。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一，在不影响安全和识别号牌的情况下，机动车所有人不需要办理变更登记： （一）增加机动车车内装饰； （二）小型、微型载客汽车加装出入口踏步件； （三）货运机动车加装防风罩、水箱、工具箱、备胎架等。 属于第一款第二项、第三项规定变更事项的，加装的部件不得超出车辆宽度。"},{"i":23,"n":"第二十三条","txt":"已注册登记的机动车有下列情形之一的，机动车所有人应当在信息或者事项变更后三十日内，向登记地车辆管理所申请变更备案： （一）机动车所有人住所在车辆管理所管辖区域内迁移、机动车所有人姓名（单位名称）变更的； （二）机动车所有人身份证明名称或者号码变更的； （三）机动车所有人联系方式变更的； （四）车辆识别代号因磨损、锈蚀、事故等原因辨认不清或者损坏的； （五）小型、微型自动挡载客汽车加装、拆除、更换肢体残疾人操纵辅助装置的； （六）载货汽车、挂车加装、拆除车用起重尾板的； （七）小型、微型载客汽车在不改变车身主体结构且保证安全的情况下加装车顶行李架，换装不同式样散热器面罩、保险杠、轮毂的；属于换装轮毂的，不得改变轮胎规格。"},{"i":24,"n":"第二十四条","txt":"申请变更备案的，机动车所有人应当确认申请信息，按照下列规定办理： （一）属于第二十三条第一项规定情形的，机动车所有人应当提交身份证明、机动车登记证书、行驶证。车辆管理所应当自受理之日起一日内，在机动车登记证书上签注备案事项，收回并重新核发行驶证； （二）属于第二十三条第二项规定情形的，机动车所有人应当提交身份证明、机动车登记证书；属于身份证明号码变更的，还应当提交相关变更证明。车辆管理所应当自受理之日起一日内，在机动车登记证书上签注备案事项； （三）属于第二十三条第三项规定情形的，机动车所有人应当提交身份证明。车辆管理所应当自受理之日起一日内办理备案； （四）属于第二十三条第四项规定情形的，机动车所有人应当提交身份证明、机动车登记证书、行驶证，交验机动车。车辆管理所应当自受理之日起一日内，查验机动车，监督重新打刻原车辆识别代号，采集、核对车辆识别代号拓印膜或者电子资料，在机动车登记证书"},{"i":25,"n":"第二十五条","txt":"已注册登记的机动车所有权发生转让的，现机动车所有人应当自机动车交付之日起三十日内向登记地车辆管理所申请转让登记。 机动车所有人申请转让登记前，应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。"},{"i":26,"n":"第二十六条","txt":"申请转让登记的，现机动车所有人应当交验机动车，确认申请信息，并提交以下证明、凭证： （一）现机动车所有人的身份证明； （二）机动车所有权转让的证明、凭证； （三）机动车登记证书； （四）机动车行驶证； （五）属于海关监管的机动车，还应当提交海关监管车辆解除监管证明书或者海关批准的转让证明； （六）属于超过检验有效期的机动车，还应当提交机动车安全技术检验合格证明和交通事故责任强制保险凭证。 车辆管理所应当自受理申请之日起一日内，查验机动车，核对车辆识别代号拓印膜或者电子资料，审查提交的证明、凭证，收回号牌、行驶证，确定新的机动车号牌号码，在机动车登记证书上签注转让事项，重新核发号牌、行驶证和检验合格标志。 在机动车抵押登记期间申请转让登记的，应当由原机动车所有人、现机动车所有人和抵押权人共同申请，车辆管理所一并办理新的抵押登记。 在机动车质押备案期间申请转让登记的，应当由原机动车所有人、"},{"i":27,"n":"第二十七条","txt":"车辆管理所办理转让登记时，现机动车所有人住所不在车辆管理所管辖区域内的，转出地车辆管理所应当自受理之日起三日内，查验机动车，核对车辆识别代号拓印膜或者电子资料，审查提交的证明、凭证，收回号牌、行驶证，在机动车登记证书上签注转让和变更事项，核发有效期为三十日的临时行驶车号牌，制作上传机动车电子档案资料。机动车所有人应当在临时行驶车号牌的有效期限内到转入地车辆管理所申请机动车转入。 申请机动车转入时，机动车所有人应当确认申请信息，提交身份证明、机动车登记证书，并交验机动车。机动车在转入时已超过检验有效期的，应当按规定进行安全技术检验并提交机动车安全技术检验合格证明和交通事故责任强制保险凭证。转入地车辆管理所应当自受理之日起三日内，查验机动车，采集、核对车辆识别代号拓印膜或者电子资料，审查相关证明、凭证和机动车电子档案资料，在机动车登记证书上签注转入信息，核发号牌、行驶证和检验合格标志。 小"},{"i":28,"n":"第二十八条","txt":"二手车出口企业收购机动车的，车辆管理所应当自受理之日起三日内，查验机动车，核对车辆识别代号拓印膜或者电子资料，审查提交的证明、凭证，在机动车登记证书上签注转让待出口事项，收回号牌、行驶证，核发有效期不超过六十日的临时行驶车号牌。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，不予办理转让登记： （一）机动车与该车档案记载内容不一致的； （二）属于海关监管的机动车，海关未解除监管或者批准转让的； （三）距机动车强制报废标准规定要求使用年限一年以内的机动车； （四）属于第十五条第一项、第二项、第七项、第八项、第九项规定情形的。"},{"i":30,"n":"第三十条","txt":"被监察机关、人民法院、人民检察院、行政执法部门依法没收并拍卖，或者被仲裁机构依法仲裁裁决，或者被监察机关依法处理，或者被人民法院调解、裁定、判决机动车所有权转让时，原机动车所有人未向现机动车所有人提供机动车登记证书、号牌或者行驶证的，现机动车所有人在办理转让登记时，应当提交监察机关或者人民法院出具的未得到机动车登记证书、号牌或者行驶证的协助执行通知书，或者人民检察院、行政执法部门出具的未得到机动车登记证书、号牌或者行驶证的证明。车辆管理所应当公告原机动车登记证书、号牌或者行驶证作废，并在办理转让登记的同时，补发机动车登记证书。"},{"i":31,"n":"第三十一条","txt":"机动车作为抵押物抵押的，机动车所有人和抵押权人应当向登记地车辆管理所申请抵押登记；抵押权消灭的，应当向登记地车辆管理所申请解除抵押登记。"},{"i":32,"n":"第三十二条","txt":"申请抵押登记的，由机动车所有人和抵押权人共同申请，确认申请信息，并提交下列证明、凭证： （一）机动车所有人和抵押权人的身份证明； （二）机动车登记证书； （三）机动车抵押合同。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，在机动车登记证书上签注抵押登记的内容和日期。 在机动车抵押登记期间，申请因质量问题更换整车变更登记、机动车迁出迁入、共同所有人变更或者补领、换领机动车登记证书的，应当由机动车所有人和抵押权人共同申请。"},{"i":33,"n":"第三十三条","txt":"申请解除抵押登记的，由机动车所有人和抵押权人共同申请，确认申请信息，并提交下列证明、凭证： （一）机动车所有人和抵押权人的身份证明； （二）机动车登记证书。 人民法院调解、裁定、判决解除抵押的，机动车所有人或者抵押权人应当确认申请信息，提交机动车登记证书、人民法院出具的已经生效的调解书、裁定书或者判决书，以及相应的协助执行通知书。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，在机动车登记证书上签注解除抵押登记的内容和日期。"},{"i":34,"n":"第三十四条","txt":"机动车作为质押物质押的，机动车所有人可以向登记地车辆管理所申请质押备案；质押权消灭的，应当向登记地车辆管理所申请解除质押备案。 申请办理机动车质押备案或者解除质押备案的，由机动车所有人和质权人共同申请，确认申请信息，并提交以下证明、凭证： （一）机动车所有人和质权人的身份证明； （二）机动车登记证书。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，在机动车登记证书上签注质押备案或者解除质押备案的内容和日期。"},{"i":35,"n":"第三十五条","txt":"机动车抵押、解除抵押信息实现与有关部门或者金融机构等联网核查的，申请人免予提交相关证明、凭证。 机动车抵押登记日期、解除抵押登记日期可以供公众查询。"},{"i":36,"n":"第三十六条","txt":"属于第十五条第一项、第七项、第八项、第九项或者第二十九条第二项规定情形的，不予办理抵押登记、质押备案。对机动车所有人、抵押权人、质权人提交的证明、凭证无效，或者机动车被监察机关、人民法院、人民检察院、行政执法部门依法查封、扣押的，不予办理解除抵押登记、质押备案。"},{"i":37,"n":"第三十七条","txt":"机动车有下列情形之一的，机动车所有人应当向登记地车辆管理所申请注销登记： （一）机动车已达到国家强制报废标准的； （二）机动车未达到国家强制报废标准，机动车所有人自愿报废的； （三）因自然灾害、失火、交通事故等造成机动车灭失的； （四）机动车因故不在我国境内使用的； （五）因质量问题退车的。 属于第一款第四项、第五项规定情形的，机动车所有人申请注销登记前，应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。 属于二手车出口符合第一款第四项规定情形的，二手车出口企业应当在机动车办理海关出口通关手续后二个月内申请注销登记。"},{"i":38,"n":"第三十八条","txt":"属于第三十七条第一款第一项、第二项规定情形，机动车所有人申请注销登记的，应当向报废机动车回收企业交售机动车，确认申请信息，提交机动车登记证书、号牌和行驶证。 报废机动车回收企业应当确认机动车，向机动车所有人出具报废机动车回收证明，七日内将申请表、机动车登记证书、号牌、行驶证和报废机动车回收证明副本提交车辆管理所。属于报废校车、大型客车、重型货车及其他营运车辆的，申请注销登记时，还应当提交车辆识别代号拓印膜、车辆解体的照片或者电子资料。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，收回机动车登记证书、号牌、行驶证，出具注销证明。 对车辆不在登记地的，机动车所有人可以向车辆所在地机动车回收企业交售报废机动车。报废机动车回收企业应当确认机动车，向机动车所有人出具报废机动车回收证明，七日内将申请表、机动车登记证书、号牌、行驶证、报废机动车回收证明副本以及车辆识别代号拓印膜或者电子资"},{"i":39,"n":"第三十九条","txt":"属于第三十七条第一款第三项、第四项、第五项规定情形，机动车所有人申请注销登记的，应当确认申请信息，并提交以下证明、凭证： （一）机动车所有人身份证明； （二）机动车登记证书； （三）机动车行驶证； （四）属于海关监管的机动车，因故不在我国境内使用的，还应当提交海关出具的海关监管车辆进（出）境领（销）牌照通知书； （五）属于因质量问题退车的，还应当提交机动车制造厂或者经销商出具的退车证明。 申请人因机动车灭失办理注销登记的，应当书面承诺因自然灾害、失火、交通事故等导致机动车灭失，并承担不实承诺的法律责任。 二手车出口企业因二手车出口办理注销登记的，应当提交机动车所有人身份证明、机动车登记证书和机动车出口证明。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，属于机动车因故不在我国境内使用的还应当核查机动车出境记录，收回机动车登记证书、号牌、行驶证，出具注销证明。"},{"i":40,"n":"第四十条","txt":"已注册登记的机动车有下列情形之一的，登记地车辆管理所应当办理机动车注销： （一）机动车登记被依法撤销的； （二）达到国家强制报废标准的机动车被依法收缴并强制报废的。"},{"i":41,"n":"第四十一条","txt":"已注册登记的机动车有下列情形之一的，车辆管理所应当公告机动车登记证书、号牌、行驶证作废： （一）达到国家强制报废标准，机动车所有人逾期不办理注销登记的； （二）机动车登记被依法撤销后，未收缴机动车登记证书、号牌、行驶证的； （三）达到国家强制报废标准的机动车被依法收缴并强制报废的； （四）机动车所有人办理注销登记时未交回机动车登记证书、号牌、行驶证的。"},{"i":42,"n":"第四十二条","txt":"属于第十五条第一项、第八项、第九项或者第二十九条第一项规定情形的，不予办理注销登记。机动车在抵押登记、质押备案期间的，不予办理注销登记。"},{"i":43,"n":"第四十三条","txt":"机动车所有人可以通过计算机随机选取或者按照选号规则自行编排的方式确定机动车号牌号码。 公安机关交通管理部门应当使用统一的机动车号牌选号系统发放号牌号码，号牌号码公开向社会发放。"},{"i":44,"n":"第四十四条","txt":"办理机动车变更登记、转让登记或者注销登记后，原机动车所有人申请机动车登记时，可以向车辆管理所申请使用原机动车号牌号码。 申请使用原机动车号牌号码应当符合下列条件： （一）在办理机动车迁出、共同所有人变更、转让登记或者注销登记后两年内提出申请； （二）机动车所有人拥有原机动车且使用原号牌号码一年以上； （三）涉及原机动车的道路交通安全违法行为和交通事故处理完毕。"},{"i":45,"n":"第四十五条","txt":"夫妻双方共同所有的机动车将登记的机动车所有人姓名变更为另一方姓名，婚姻关系存续期满一年且经夫妻双方共同申请的，可以使用原机动车号牌号码。"},{"i":46,"n":"第四十六条","txt":"机动车具有下列情形之一，需要临时上道路行驶的，机动车所有人应当向车辆管理所申领临时行驶车号牌： （一）未销售的； （二）购买、调拨、赠予等方式获得机动车后尚未注册登记的； （三）新车出口销售的； （四）进行科研、定型试验的； （五）因轴荷、总质量、外廓尺寸超出国家标准不予办理注册登记的特型机动车。"},{"i":47,"n":"第四十七条","txt":"机动车所有人申领临时行驶车号牌应当提交以下证明、凭证： （一）机动车所有人的身份证明； （二）机动车交通事故责任强制保险凭证； （三）属于第四十六条第一项、第五项规定情形的，还应当提交机动车整车出厂合格证明或者进口机动车进口凭证； （四）属于第四十六条第二项规定情形的，还应当提交机动车来历证明，以及机动车整车出厂合格证明或者进口机动车进口凭证； （五）属于第四十六条第三项规定情形的，还应当提交机动车制造厂出具的安全技术检验证明以及机动车出口证明； （六）属于第四十六条第四项规定情形的，还应当提交书面申请，以及机动车安全技术检验合格证明或者机动车制造厂出具的安全技术检验证明。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，属于第四十六条第一项、第二项、第三项规定情形，需要临时上道路行驶的，核发有效期不超过三十日的临时行驶车号牌。属于第四十六条第四项规定情形的，核发有效期不超过六"},{"i":48,"n":"第四十八条","txt":"对智能网联机动车进行道路测试、示范应用需要上道路行驶的，道路测试、示范应用单位应当向车辆管理所申领临时行驶车号牌，提交以下证明、凭证： （一）道路测试、示范应用单位的身份证明； （二）机动车交通事故责任强制保险凭证； （三）经主管部门确认的道路测试、示范应用凭证； （四）机动车安全技术检验合格证明。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，核发临时行驶车号牌。临时行驶车号牌有效期应当与准予道路测试、示范应用凭证上签注的期限保持一致，但最长不得超过六个月。"},{"i":49,"n":"第四十九条","txt":"对临时入境的机动车需要上道路行驶的，机动车所有人应当按规定向入境地或者始发地车辆管理所申领临时入境机动车号牌和行驶证。"},{"i":50,"n":"第五十条","txt":"公安机关交通管理部门应当使用统一的号牌管理信息系统制作、发放、收回、销毁机动车号牌和临时行驶车号牌。"},{"i":51,"n":"第五十一条","txt":"机动车号牌灭失、丢失或者损毁的，机动车所有人应当向登记地车辆管理所申请补领、换领。申请时，机动车所有人应当确认申请信息并提交身份证明。 车辆管理所应当审查提交的证明、凭证，收回未灭失、丢失或者损毁的号牌，自受理之日起十五日内补发、换发号牌，原机动车号牌号码不变。 补发、换发号牌期间，申请人可以申领有效期不超过十五日的临时行驶车号牌。 补领、换领机动车号牌的，原机动车号牌作废，不得继续使用。"},{"i":52,"n":"第五十二条","txt":"机动车登记证书、行驶证灭失、丢失或者损毁的，机动车所有人应当向登记地车辆管理所申请补领、换领。申请时，机动车所有人应当确认申请信息并提交身份证明。 车辆管理所应当审查提交的证明、凭证，收回损毁的登记证书、行驶证，自受理之日起一日内补发、换发登记证书、行驶证。 补领、换领机动车登记证书、行驶证的，原机动车登记证书、行驶证作废，不得继续使用。"},{"i":53,"n":"第五十三条","txt":"机动车所有人发现登记内容有错误的，应当及时要求车辆管理所更正。车辆管理所应当自受理之日起五日内予以确认。确属登记错误的，在机动车登记证书上更正相关内容，换发行驶证。需要改变机动车号牌号码的，应当收回号牌、行驶证，确定新的机动车号牌号码，重新核发号牌、行驶证和检验合格标志。"},{"i":54,"n":"第五十四条","txt":"机动车所有人可以在机动车检验有效期满前三个月内向车辆管理所申请检验合格标志。除大型载客汽车、校车以外的机动车因故不能在登记地检验的，机动车所有人可以向车辆所在地车辆管理所申请检验合格标志。 申请前，机动车所有人应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。申请时，机动车所有人应当确认申请信息并提交行驶证、机动车交通事故责任强制保险凭证、车船税纳税或者免税证明、机动车安全技术检验合格证明。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，核发检验合格标志。"},{"i":55,"n":"第五十五条","txt":"对免予到机动车安全技术检验机构检验的机动车，机动车所有人申请检验合格标志时，应当提交机动车所有人身份证明或者行驶证、机动车交通事故责任强制保险凭证、车船税纳税或者免税证明。 车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，核发检验合格标志。"},{"i":56,"n":"第五十六条","txt":"公安机关交通管理部门应当实行机动车检验合格标志电子化，在核发检验合格标志的同时，发放检验合格标志电子凭证。 检验合格标志电子凭证与纸质检验合格标志具有同等效力。"},{"i":57,"n":"第五十七条","txt":"机动车检验合格标志灭失、丢失或者损毁，机动车所有人需要补领、换领的，可以持机动车所有人身份证明或者行驶证向车辆管理所申请补领或者换领。对机动车交通事故责任强制保险在有效期内的，车辆管理所应当自受理之日起一日内补发或者换发。"},{"i":58,"n":"第五十八条","txt":"学校或者校车服务提供者申请校车使用许可，应当按照《校车安全管理条例》向县级或者设区的市级人民政府教育行政部门提出申请。公安机关交通管理部门收到教育行政部门送来的征求意见材料后，应当在一日内通知申请人交验机动车。"},{"i":59,"n":"第五十九条","txt":"县级或者设区的市级公安机关交通管理部门应当自申请人交验机动车之日起二日内确认机动车，查验校车标志灯、停车指示标志、卫星定位装置以及逃生锤、干粉灭火器、急救箱等安全设备，审核行驶线路、开行时间和停靠站点。属于专用校车的，还应当查验校车外观标识。审查以下证明、凭证： （一）机动车所有人的身份证明； （二）机动车行驶证； （三）校车安全技术检验合格证明； （四）包括行驶线路、开行时间和停靠站点的校车运行方案； （五）校车驾驶人的机动车驾驶证。 公安机关交通管理部门应当自收到教育行政部门征求意见材料之日起三日内向教育行政部门回复意见，但申请人未按规定交验机动车的除外。"},{"i":60,"n":"第六十条","txt":"学校或者校车服务提供者按照《校车安全管理条例》取得校车使用许可后，应当向县级或者设区的市级公安机关交通管理部门领取校车标牌。领取时应当确认表格信息，并提交以下证明、凭证： （一）机动车所有人的身份证明； （二）校车驾驶人的机动车驾驶证； （三）机动车行驶证； （四）县级或者设区的市级人民政府批准的校车使用许可； （五）县级或者设区的市级人民政府批准的包括行驶线路、开行时间和停靠站点的校车运行方案。 公安机关交通管理部门应当在收到领取表之日起三日内核发校车标牌。对属于专用校车的，应当核对行驶证上记载的校车类型和核载人数；对不属于专用校车的，应当在行驶证副页上签注校车类型和核载人数。"},{"i":61,"n":"第六十一条","txt":"校车标牌应当记载本车的号牌号码、机动车所有人、驾驶人、行驶线路、开行时间、停靠站点、发牌单位、有效期限等信息。校车标牌分前后两块，分别放置于前风窗玻璃右下角和后风窗玻璃适当位置。 校车标牌有效期的截止日期与校车安全技术检验有效期的截止日期一致，但不得超过校车使用许可有效期。"},{"i":62,"n":"第六十二条","txt":"专用校车应当自注册登记之日起每半年进行一次安全技术检验，非专用校车应当自取得校车标牌后每半年进行一次安全技术检验。 学校或者校车服务提供者应当在校车检验有效期满前一个月内向公安机关交通管理部门申请检验合格标志。 公安机关交通管理部门应当自受理之日起一日内，审查提交的证明、凭证，核发检验合格标志，换发校车标牌。"},{"i":63,"n":"第六十三条","txt":"已取得校车标牌的机动车达到报废标准或者不再作为校车使用的，学校或者校车服务提供者应当拆除校车标志灯、停车指示标志，消除校车外观标识，并将校车标牌交回核发的公安机关交通管理部门。 专用校车不得改变使用性质。 校车使用许可被吊销、注销或者撤销的，学校或者校车服务提供者应当拆除校车标志灯、停车指示标志，消除校车外观标识，并将校车标牌交回核发的公安机关交通管理部门。"},{"i":64,"n":"第六十四条","txt":"校车行驶线路、开行时间、停靠站点或者车辆、所有人、驾驶人发生变化的，经县级或者设区的市级人民政府批准后，应当按照本规定重新领取校车标牌。"},{"i":65,"n":"第六十五条","txt":"公安机关交通管理部门应当每月将校车标牌的发放、变更、收回等信息报本级人民政府备案，并通报教育行政部门。 学校或者校车服务提供者应当自取得校车标牌之日起，每月查询校车道路交通安全违法行为记录，及时到公安机关交通管理部门接受处理。核发校车标牌的公安机关交通管理部门应当每月汇总辖区内校车道路交通安全违法和交通事故等情况，通知学校或者校车服务提供者，并通报教育行政部门。"},{"i":66,"n":"第六十六条","txt":"校车标牌灭失、丢失或者损毁的，学校或者校车服务提供者应当向核发标牌的公安机关交通管理部门申请补领或者换领。申请时，应当提交机动车所有人的身份证明及机动车行驶证。公安机关交通管理部门应当自受理之日起三日内审核，补发或者换发校车标牌。"},{"i":67,"n":"第六十七条","txt":"公安机关交通管理部门应当建立业务监督管理中心，通过远程监控、数据分析、日常检查、档案抽查、业务回访等方式，对机动车登记及相关业务办理情况进行监督管理。 直辖市、设区的市或者相当于同级的公安机关交通管理部门应当通过监管系统每周对机动车登记及相关业务办理情况进行监控、分析，及时查处整改发现的问题。省级公安机关交通管理部门应当通过监管系统每月对机动车登记及相关业务办理情况进行监控、分析，及时查处、通报发现的问题。 车辆管理所存在严重违规办理机动车登记情形的，上级公安机关交通管理部门可以暂停该车辆管理所办理相关业务或者指派其他车辆管理所人员接管业务。"},{"i":68,"n":"第六十八条","txt":"县级公安机关交通管理部门办理机动车登记及相关业务的，办公场所、设施设备、人员资质和信息系统等应当满足业务办理需求，并符合相关规定和标准要求。 直辖市、设区的市公安机关交通管理部门应当加强对县级公安机关交通管理部门办理机动车登记及相关业务的指导、培训和监督管理。"},{"i":69,"n":"第六十九条","txt":"机动车销售企业、二手车交易市场、机动车安全技术检验机构、报废机动车回收企业和邮政、金融机构、保险机构等单位，经公安机关交通管理部门委托可以设立机动车登记服务站，在公安机关交通管理部门监督管理下协助办理机动车登记及相关业务。 机动车登记服务站应当规范设置名称和外观标识，公开业务范围、办理依据、办理程序、收费标准等事项。机动车登记服务站应当使用统一的计算机管理系统协助办理机动车登记及相关业务。 机动车登记服务站协助办理机动车登记的，可以提供办理保险和车辆购置税、机动车预查验、信息预录入等服务，便利机动车所有人一站式办理。"},{"i":70,"n":"第七十条","txt":"公安机关交通管理部门应当建立机动车登记服务站监督管理制度，明确设立条件、业务范围、办理要求、信息系统安全等规定，签订协议及责任书，通过业务抽查、网上巡查、实地检查、业务回访等方式加强对机动车登记服务站协助办理业务情况的监督管理。 机动车登记服务站存在违反规定办理机动车登记及相关业务、违反信息安全管理规定等情形的，公安机关交通管理部门应当暂停委托其业务办理，限期整改；有严重违规情形的，终止委托其业务办理。机动车登记服务站违反规定办理业务给当事人造成经济损失的，应当依法承担赔偿责任；构成犯罪的，依法追究相关责任人员刑事责任。"},{"i":71,"n":"第七十一条","txt":"公安机关交通管理部门应当建立号牌制作发放监管制度，加强对机动车号牌制作单位和号牌质量的监督管理。 机动车号牌制作单位存在违反规定制作和发放机动车号牌的，公安机关交通管理部门应当暂停其相关业务，限期整改；构成犯罪的，依法追究相关责任人员刑事责任。"},{"i":72,"n":"第七十二条","txt":"机动车安全技术检验机构应当按照国家机动车安全技术检验标准对机动车进行检验，对检验结果承担法律责任。 公安机关交通管理部门在核发机动车检验合格标志时，发现机动车安全技术检验机构存在为未经检验的机动车出具检验合格证明、伪造或者篡改检验数据等出具虚假检验结果行为的，停止认可其出具的检验合格证明，依法进行处罚，并通报市场监督管理部门；构成犯罪的，依法追究相关责任人员刑事责任。"},{"i":73,"n":"第七十三条","txt":"从事机动车查验工作的人员，应当持有公安机关交通管理部门颁发的资格证书。公安机关交通管理部门应当在公安民警、警务辅助人员中选拔足够数量的机动车查验员，从事查验工作。机动车登记服务站工作人员可以在车辆管理所监督下承担机动车查验工作。 机动车查验员应当严格遵守查验工作纪律，不得减少查验项目、降低查验标准，不得参与、协助、纵容为违规机动车办理登记。公安民警、警务辅助人员不得参与或者变相参与机动车安全技术检验机构经营活动，不得收取机动车安全技术检验机构、机动车销售企业、二手车交易市场、报废机动车回收企业等相关企业、申请人的财物。 车辆管理所应当对机动车查验过程进行全程录像，并实时监控查验过程，没有使用录像设备的，不得进行查验。机动车查验中，查验员应当使用执勤执法记录仪记录查验过程。车辆管理所应当建立机动车查验音视频档案，存储录像设备和执勤执法记录仪记录的音像资料。"},{"i":74,"n":"第七十四条","txt":"车辆管理所在办理机动车登记及相关业务过程中发现存在以下情形的，应当及时开展调查： （一）机动车涉嫌走私、被盗抢骗、非法生产销售、拼（组）装、非法改装的； （二）涉嫌提交虚假申请材料的； （三）涉嫌使用伪造、变造机动车牌证的； （四）涉嫌以欺骗、贿赂等不正当手段取得机动车登记的； （五）存在短期内频繁补换领牌证、转让登记、转出转入等异常情形的； （六）存在其他违法违规情形的。 车辆管理所发现申请人通过互联网办理机动车登记及相关业务存在第一款规定嫌疑情形的，应当转为现场办理，当场审查申请材料，及时开展调查。"},{"i":75,"n":"第七十五条","txt":"车辆管理所开展调查时，可以通知申请人协助调查，询问嫌疑情况，记录调查内容，并可以采取检验鉴定、实地检查等方式进行核查。 对经调查发现涉及行政案件或者刑事案件的，应当依法采取必要的强制措施或者其他处置措施，移交有管辖权的公安机关按照《公安机关办理行政案件程序规定》《公安机关办理刑事案件程序规定》等规定办理。 对办理机动车登记时发现机动车涉嫌走私的，公安机关交通管理部门应当将机动车及相关资料移交海关依法处理。"},{"i":76,"n":"第七十六条","txt":"已注册登记的机动车被盗抢骗的，车辆管理所应当根据刑侦部门提供的情况，在计算机登记系统内记录，停止办理该车的各项登记和业务。被盗抢骗机动车发还后，车辆管理所应当恢复办理该车的各项登记和业务。 机动车在被盗抢骗期间，发动机号码、车辆识别代号或者车身颜色被改变的，车辆管理所应当凭有关技术鉴定证明办理变更备案。"},{"i":77,"n":"第七十七条","txt":"公安机关交通管理部门及其交通警察、警务辅助人员办理机动车登记工作，应当接受监察机关、公安机关督察审计部门等依法实施的监督。 公安机关交通管理部门及其交通警察、警务辅助人员办理机动车登记工作，应当自觉接受社会和公民的监督。"},{"i":78,"n":"第七十八条","txt":"有下列情形之一的，由公安机关交通管理部门处警告或者二百元以下罚款： （一）重型、中型载货汽车、专项作业车、挂车及大型客车的车身或者车厢后部未按照规定喷涂放大的牌号或者放大的牌号不清晰的； （二）机动车喷涂、粘贴标识或者车身广告，影响安全驾驶的； （三）载货汽车、专项作业车及挂车未按照规定安装侧面及后下部防护装置、粘贴车身反光标识的； （四）机动车未按照规定期限进行安全技术检验的； （五）改变车身颜色、更换发动机、车身或者车架，未按照第十六条规定的时限办理变更登记的； （六）机动车所有权转让后，现机动车所有人未按照第二十五条规定的时限办理转让登记的； （七）机动车所有人办理变更登记、转让登记，未按照第十八条、第二十七条规定的时限到住所地车辆管理所申请机动车转入的； （八）机动车所有人未按照第二十三条规定申请变更备案的。"},{"i":79,"n":"第七十九条","txt":"除第十六条、第二十二条、第二十三条规定的情形外，擅自改变机动车外形和已登记的有关技术参数的，由公安机关交通管理部门责令恢复原状，并处警告或者五百元以下罚款。"},{"i":80,"n":"第八十条","txt":"隐瞒有关情况或者提供虚假材料申请机动车登记的，公安机关交通管理部门不予受理或者不予登记，处五百元以下罚款；申请人在一年内不得再次申请机动车登记。 对发现申请人通过机动车虚假交易、以合法形式掩盖非法目的等手段，在机动车登记业务中牟取不正当利益的，依照第一款的规定处理。"},{"i":81,"n":"第八十一条","txt":"以欺骗、贿赂等不正当手段取得机动车登记的，由公安机关交通管理部门收缴机动车登记证书、号牌、行驶证，撤销机动车登记，处二千元以下罚款；申请人在三年内不得再次申请机动车登记。 以欺骗、贿赂等不正当手段办理补、换领机动车登记证书、号牌、行驶证和检验合格标志等业务的，由公安机关交通管理部门收缴机动车登记证书、号牌、行驶证和检验合格标志，未收缴的，公告作废，处二千元以下罚款。 组织、参与实施第八十条、本条前两款行为之一牟取经济利益的，由公安机关交通管理部门处违法所得三倍以上五倍以下罚款，但最高不超过十万元。"},{"i":82,"n":"第八十二条","txt":"省、自治区、直辖市公安厅、局可以根据本地区的实际情况，在本规定的处罚幅度范围内，制定具体的执行标准。 对本规定的道路交通安全违法行为的处理程序按照《道路交通安全违法行为处理程序规定》执行。"},{"i":83,"n":"第八十三条","txt":"交通警察有下列情形之一的，按照有关规定给予处分；对聘用人员予以解聘。构成犯罪的，依法追究刑事责任： （一）违反规定为被盗抢骗、走私、非法拼（组）装、达到国家强制报废标准的机动车办理登记的； （二）不按照规定查验机动车和审查证明、凭证的； （三）故意刁难，拖延或者拒绝办理机动车登记的； （四）违反本规定增加机动车登记条件或者提交的证明、凭证的； （五）违反第四十三条的规定，采用其他方式确定机动车号牌号码的； （六）违反规定跨行政辖区办理机动车登记和业务的； （七）与非法中介串通牟取经济利益的； （八）超越职权进入计算机登记管理系统办理机动车登记和业务，或者不按规定使用计算机登记管理系统办理机动车登记和业务的； （九）违反规定侵入计算机登记管理系统，泄漏、篡改、买卖系统数据，或者泄漏系统密码的； （十）违反规定向他人出售或者提供机动车登记信息的； （十一）参与或者变相参与机动车安全技术检验"},{"i":84,"n":"第八十四条","txt":"公安机关交通管理部门有第八十三条所列行为之一的，按照有关规定对直接负责的主管人员和其他直接责任人员给予相应的处分。 公安机关交通管理部门及其工作人员有第八十三条所列行为之一，给当事人造成损失的，应当依法承担赔偿责任。"},{"i":85,"n":"第八十五条","txt":"机动车登记证书、号牌、行驶证、检验合格标志的式样由公安部统一制定并监制。 机动车登记证书、号牌、行驶证、检验合格标志的制作应当符合有关标准。"},{"i":86,"n":"第八十六条","txt":"机动车所有人可以委托代理人代理申请各项机动车登记和业务，但共同所有人变更、申请补领机动车登记证书、机动车灭失注销的除外；对机动车所有人因死亡、出境、重病、伤残或者不可抗力等原因不能到场的，可以凭相关证明委托代理人代理申请，或者由继承人申请。 代理人申请机动车登记和业务时，应当提交代理人的身份证明和机动车所有人的委托书。"},{"i":87,"n":"第八十七条","txt":"公安机关交通管理部门应当实行机动车登记档案电子化，机动车电子档案与纸质档案具有同等效力。车辆管理所对办理机动车登记时不需要留存原件的证明、凭证，应当以电子文件形式归档。"},{"i":88,"n":"第八十八条","txt":"本规定所称进口机动车以及进口机动车的进口凭证是指： （一）进口机动车： 1.经国家限定口岸海关进口的汽车； 2.经各口岸海关进口的其他机动车； 3.海关监管的机动车； 4.国家授权的执法部门没收的走私、无合法进口证明和利用进口关键件非法拼（组）装的机动车。 （二）进口机动车的进口凭证： 1.进口汽车的进口凭证，是国家限定口岸海关签发的货物进口证明书； 2.其他进口机动车的进口凭证，是各口岸海关签发的货物进口证明书； 3.海关监管的机动车的进口凭证，是监管地海关出具的海关监管车辆进（出）境领（销）牌照通知书； 4.国家授权的执法部门没收的走私、无进口证明和利用进口关键件非法拼（组）装的机动车的进口凭证，是该部门签发的没收走私汽车、摩托车证明书。"},{"i":89,"n":"第八十九条","txt":"本规定所称机动车所有人、身份证明以及住所是指： （一）机动车所有人包括拥有机动车的个人或者单位。 1.个人是指我国内地的居民和军人（含武警）以及香港、澳门特别行政区、台湾地区居民、定居国外的中国公民和外国人； 2.单位是指机关、企业、事业单位和社会团体以及外国驻华使馆、领馆和外国驻华办事机构、国际组织驻华代表机构。 （二）身份证明： 1.机关、企业、事业单位、社会团体的身份证明，是该单位的统一社会信用代码证书、营业执照或者社会团体法人登记证书，以及加盖单位公章的委托书和被委托人的身份证明。机动车所有人为单位的内设机构，本身不具备领取统一社会信用代码证书条件的，可以使用上级单位的统一社会信用代码证书作为机动车所有人的身份证明。上述单位已注销、撤销或者破产，其机动车需要办理变更登记、转让登记、解除抵押登记、注销登记、解除质押备案和补、换领机动车登记证书、号牌、行驶证的，已注销的企业的身份证"},{"i":90,"n":"第九十条","txt":"本规定所称机动车来历证明以及机动车整车出厂合格证明是指： （一）机动车来历证明： 1.在国内购买的机动车，其来历证明是机动车销售统一发票或者二手车交易发票。在国外购买的机动车，其来历证明是该车销售单位开具的销售发票及其翻译文本，但海关监管的机动车不需提供来历证明； 2.监察机关依法没收、追缴或者责令退赔的机动车，其来历证明是监察机关出具的法律文书，以及相应的协助执行通知书； 3.人民法院调解、裁定或者判决转让的机动车，其来历证明是人民法院出具的已经生效的调解书、裁定书或者判决书，以及相应的协助执行通知书； 4.仲裁机构仲裁裁决转让的机动车，其来历证明是仲裁裁决书和人民法院出具的协助执行通知书； 5.继承、赠予、中奖、协议离婚和协议抵偿债务的机动车，其来历证明是继承、赠予、中奖、协议离婚、协议抵偿债务的相关文书和公证机关出具的公证书； 6.资产重组或者资产整体买卖中包含的机动车，其来历证"},{"i":91,"n":"第九十一条","txt":"本规定所称二手车出口企业是指经商务主管部门认定具备二手车出口资质的企业。"},{"i":92,"n":"第九十二条","txt":"本规定所称“一日”、“二日”、“三日”、“五日”、“七日”、“十日”、“十五日”，是指工作日，不包括节假日。 临时行驶车号牌的最长有效期“十五日”、“三十日”、“六十日”、“九十日”、“六个月”，包括工作日和节假日。 本规定所称“以下”、“以上”、“以内”，包括本数。"},{"i":93,"n":"第九十三条","txt":"本规定自2022年5月1日起施行。2008年5月27日发布的《机动车登记规定》（公安部令第102号）和2012年9月12日发布的《公安部关于修改<机动车登记规定>的决定》（公安部令第124号）同时废止。本规定生效后，公安部以前制定的规定与本规定不一致的，以本规定为准。"}],"jidongchejiashizhengshenlingheshiyongguiding":[{"i":1,"n":"第一条","txt":"为了规范机动车驾驶证申领和使用，保障道路交通安全，保护公民、法人和其他组织的合法权益，根据《中华人民共和国道路交通安全法》及其实施条例、《中华人民共和国行政许可法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定由公安机关交通管理部门负责实施。 省级公安机关交通管理部门负责本省（自治区、直辖市）机动车驾驶证业务工作的指导、检查和监督。直辖市公安机关交通管理部门车辆管理所、设区的市或者相当于同级的公安机关交通管理部门车辆管理所负责办理本行政区域内机动车驾驶证业务。 县级公安机关交通管理部门车辆管理所可以办理本行政区域内除大型客车、重型牵引挂车、城市公交车、中型客车、大型货车场地驾驶技能、道路驾驶技能考试以外的其他机动车驾驶证业务。具体业务范围和办理条件由省级公安机关交通管理部门确定。"},{"i":3,"n":"第三条","txt":"车辆管理所办理机动车驾驶证业务，应当遵循依法、公开、公正、便民的原则。 车辆管理所办理机动车驾驶证业务，应当依法受理申请人的申请，审查申请人提交的材料。对符合条件的，按照规定的标准、程序和期限办理机动车驾驶证。对申请材料不齐全或者不符合法定形式的，应当一次书面或者电子告知申请人需要补正的全部内容。对不符合条件的，应当书面或者电子告知理由。 车辆管理所应当将法律、行政法规和本规定的有关办理机动车驾驶证的事项、条件、依据、程序、期限以及收费标准、需要提交的全部材料的目录和申请表示范文本等在办公场所公示。 省级、设区的市或者相当于同级的公安机关交通管理部门应当在互联网上发布信息，便于群众查阅办理机动车驾驶证的有关规定，查询驾驶证使用状态、交通违法及记分等情况，下载、使用有关表格。"},{"i":4,"n":"第四条","txt":"车辆管理所办理机动车驾驶证业务时，应当按照减环节、减材料、减时限的要求，积极推行一次办结、限时办结等制度，为申请人提供规范、便利、高效的服务。 公安机关交通管理部门应当积极推进与有关部门信息互联互通，对实现信息共享、网上核查的，申请人免予提交相关证明凭证。 公安机关交通管理部门应当按照就近办理、便捷办理的原则，推进在驾驶人考场、政务服务大厅等地设置服务站点，方便申请人办理机动车驾驶证业务，并在办公场所和互联网公示辖区内的业务办理网点、地址、联系电话、办公时间和业务范围。"},{"i":5,"n":"第五条","txt":"车辆管理所应当使用全国统一的计算机管理系统办理机动车驾驶证业务、核发机动车驾驶证。 计算机管理系统的数据库标准和软件全国统一，能够完整、准确地记录和存储机动车驾驶证业务办理、驾驶人考试等全过程和经办人员信息，并能够实时将有关信息传送到全国公安交通管理信息系统。"},{"i":6,"n":"第六条","txt":"车辆管理所应当使用互联网交通安全综合服务管理平台受理申请人网上提交的申请，验证申请人身份，按规定办理机动车驾驶证业务。 互联网交通安全综合服务管理平台信息管理系统数据库标准和软件全国统一。"},{"i":7,"n":"第七条","txt":"申请办理机动车驾驶证业务的，应当如实向车辆管理所提交规定的材料，如实申告规定的事项，并对其申请材料实质内容的真实性负责。"},{"i":8,"n":"第八条","txt":"公安机关交通管理部门应当建立机动车驾驶证业务监督制度，加强对驾驶人考试、驾驶证核发和使用的监督管理。"},{"i":9,"n":"第九条","txt":"车辆管理所办理机动车驾驶证业务时可以依据相关法律法规认可、使用电子签名、电子印章、电子证照。"},{"i":10,"n":"第十条","txt":"驾驶机动车，应当依法取得机动车驾驶证。"},{"i":11,"n":"第十一条","txt":"机动车驾驶人准予驾驶的车型顺序依次分为：大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车、轻型牵引挂车、普通三轮摩托车、普通二轮摩托车、轻便摩托车、轮式专用机械车、无轨电车和有轨电车（附件1）。"},{"i":12,"n":"第十二条","txt":"机动车驾驶证记载和签注以下内容： （一）机动车驾驶人信息：姓名、性别、出生日期、国籍、住址、身份证明号码（机动车驾驶证号码）、照片； （二）车辆管理所签注内容：初次领证日期、准驾车型代号、有效期限、核发机关印章、档案编号、准予驾驶机动车听力辅助条件。"},{"i":13,"n":"第十三条","txt":"机动车驾驶证有效期分为六年、十年和长期。"},{"i":14,"n":"第十四条","txt":"申请机动车驾驶证的人，应当符合下列规定： （一）年龄条件： 1. 申请小型汽车、小型自动挡汽车、残疾人专用小型自动挡载客汽车、轻便摩托车准驾车型的，在18周岁以上； 2. 申请低速载货汽车、三轮汽车、普通三轮摩托车、普通二轮摩托车或者轮式专用机械车准驾车型的，在18周岁以上，60周岁以下； 3. 申请城市公交车、中型客车、大型货车、轻型牵引挂车、无轨电车或者有轨电车准驾车型的，在20周岁以上，60周岁以下； 4. 申请大型客车、重型牵引挂车准驾车型的，在22周岁以上，60周岁以下； 5. 接受全日制驾驶职业教育的学生，申请大型客车、重型牵引挂车准驾车型的，在19周岁以上，60周岁以下。 （二）身体条件： 1. 身高：申请大型客车、重型牵引挂车、城市公交车、大型货车、无轨电车准驾车型的，身高为155厘米以上。申请中型客车准驾车型的，身高为150厘米以上； 2. 视力：申请大型客车、重型牵"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不得申请机动车驾驶证: （一）有器质性心脏病、癫痫病、美尼尔氏症、眩晕症、癔病、震颤麻痹、精神病、痴呆以及影响肢体活动的神经系统疾病等妨碍安全驾驶疾病的； （二）三年内有吸食、注射毒品行为或者解除强制隔离戒毒措施未满三年，以及长期服用依赖性精神药品成瘾尚未戒除的； （三）造成交通事故后逃逸构成犯罪的； （四）饮酒后或者醉酒驾驶机动车发生重大交通事故构成犯罪的； （五）醉酒驾驶机动车或者饮酒后驾驶营运机动车依法被吊销机动车驾驶证未满五年的； （六）醉酒驾驶营运机动车依法被吊销机动车驾驶证未满十年的； （七）驾驶机动车追逐竞驶、超员、超速、违反危险化学品安全管理规定运输危险化学品构成犯罪依法被吊销机动车驾驶证未满五年的； （八）因本款第四项以外的其他违反交通管理法律法规的行为发生重大交通事故构成犯罪依法被吊销机动车驾驶证未满十年的； （九）因其他情形依法被吊销机动车驾驶证"},{"i":16,"n":"第十六条","txt":"初次申领机动车驾驶证的，可以申请准驾车型为城市公交车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车、普通三轮摩托车、普通二轮摩托车、轻便摩托车、轮式专用机械车、无轨电车、有轨电车的机动车驾驶证。 已持有机动车驾驶证，申请增加准驾车型的，可以申请增加的准驾车型为大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、轻型牵引挂车、普通三轮摩托车、普通二轮摩托车、轻便摩托车、轮式专用机械车、无轨电车、有轨电车。"},{"i":17,"n":"第十七条","txt":"已持有机动车驾驶证，申请增加准驾车型的，应当在本记分周期和申请前最近一个记分周期内没有记满12分记录。申请增加轻型牵引挂车、中型客车、重型牵引挂车、大型客车准驾车型的，还应当符合下列规定： （一）申请增加轻型牵引挂车准驾车型的，已取得驾驶小型汽车、小型自动挡汽车准驾车型资格一年以上； （二）申请增加中型客车准驾车型的，已取得驾驶城市公交车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车或者三轮汽车准驾车型资格二年以上，并在申请前最近连续二个记分周期内没有记满12分记录； （三）申请增加重型牵引挂车准驾车型的，已取得驾驶中型客车或者大型货车准驾车型资格二年以上，或者取得驾驶大型客车准驾车型资格一年以上，并在申请前最近连续二个记分周期内没有记满12分记录； （四）申请增加大型客车准驾车型的，已取得驾驶城市公交车、中型客车准驾车型资格二年以上、已取得驾驶大型货车准驾车型资格三年以上，或者取"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，不得申请大型客车、重型牵引挂车、城市公交车、中型客车、大型货车准驾车型： （一）发生交通事故造成人员死亡，承担同等以上责任的； （二）醉酒后驾驶机动车的； （三）再次饮酒后驾驶机动车的； （四）有吸食、注射毒品后驾驶机动车行为的，或者有执行社区戒毒、强制隔离戒毒、社区康复措施记录的； （五）驾驶机动车追逐竞驶、超员、超速、违反危险化学品安全管理规定运输危险化学品构成犯罪的； （六）被吊销或者撤销机动车驾驶证未满十年的； （七）未取得机动车驾驶证驾驶机动车，发生负同等以上责任交通事故造成人员重伤或者死亡的。"},{"i":19,"n":"第十九条","txt":"持有军队、武装警察部队机动车驾驶证，符合本规定的申请条件，可以申请对应准驾车型的机动车驾驶证。"},{"i":20,"n":"第二十条","txt":"持有境外机动车驾驶证，符合本规定的申请条件，且取得该驾驶证时在核发国家或者地区一年内累计居留九十日以上的，可以申请对应准驾车型的机动车驾驶证。属于申请准驾车型为大型客车、重型牵引挂车、中型客车机动车驾驶证的，还应当取得境外相应准驾车型机动车驾驶证二年以上。"},{"i":21,"n":"第二十一条","txt":"持有境外机动车驾驶证，需要临时驾驶机动车的，应当按规定向车辆管理所申领临时机动车驾驶许可。 对入境短期停留的，可以申领有效期为三个月的临时机动车驾驶许可；停居留时间超过三个月的，有效期可以延长至一年。 临时入境机动车驾驶人的临时机动车驾驶许可在一个记分周期内累积记分达到12分，未按规定参加道路交通安全法律、法规和相关知识学习、考试的，不得申请机动车驾驶证或者再次申请临时机动车驾驶许可。"},{"i":22,"n":"第二十二条","txt":"申领机动车驾驶证的人，按照下列规定向车辆管理所提出申请： （一）在户籍所在地居住的，应当在户籍所在地提出申请； （二）在户籍所在地以外居住的，可以在居住地提出申请； （三）现役军人（含武警），应当在部队驻地提出申请； （四）境外人员，应当在居留地或者居住地提出申请； （五）申请增加准驾车型的，应当在所持机动车驾驶证核发地提出申请； （六）接受全日制驾驶职业教育，申请增加大型客车、重型牵引挂车准驾车型的，应当在接受教育地提出申请。"},{"i":23,"n":"第二十三条","txt":"申请机动车驾驶证，应当确认申请信息，并提交以下证明： （一）申请人的身份证明； （二）医疗机构出具的有关身体条件的证明。"},{"i":24,"n":"第二十四条","txt":"持军队、武装警察部队机动车驾驶证的人申请机动车驾驶证，应当确认申请信息，并提交以下证明、凭证： （一）申请人的身份证明。属于复员、转业、退伍的人员，还应当提交军队、武装警察部队核发的复员、转业、退伍证明； （二）医疗机构出具的有关身体条件的证明； （三）军队、武装警察部队机动车驾驶证。"},{"i":25,"n":"第二十五条","txt":"持境外机动车驾驶证的人申请机动车驾驶证，应当确认申请信息，并提交以下证明、凭证： （一）申请人的身份证明； （二）医疗机构出具的有关身体条件的证明； （三）所持机动车驾驶证。属于非中文表述的，还应当提供翻译机构出具或者公证机构公证的中文翻译文本。 属于外国驻华使馆、领馆人员及国际组织驻华代表机构人员申请的，按照外交对等原则执行。 属于内地居民申请的，还应当提交申请人的护照或者往来港澳通行证、往来台湾通行证。"},{"i":26,"n":"第二十六条","txt":"实行小型汽车、小型自动挡汽车驾驶证自学直考的地方，申请人可以使用加装安全辅助装置的自备机动车，在具备安全驾驶经历等条件的人员随车指导下，按照公安机关交通管理部门指定的路线、时间学习驾驶技能，按照第二十三条的规定申请相应准驾车型的驾驶证。 小型汽车、小型自动挡汽车驾驶证自学直考管理制度由公安部另行规定。"},{"i":27,"n":"第二十七条","txt":"申请机动车驾驶证的人，符合本规定要求的驾驶许可条件，有下列情形之一的，可以按照第十六条第一款和第二十三条的规定直接申请相应准驾车型的机动车驾驶证考试： （一）原机动车驾驶证因超过有效期未换证被注销的； （二）原机动车驾驶证因未提交身体条件证明被注销的； （三）原机动车驾驶证由本人申请注销的； （四）原机动车驾驶证因身体条件暂时不符合规定被注销的； （五）原机动车驾驶证或者准驾车型资格因其他原因被注销的，但机动车驾驶证被吊销或者被撤销的除外； （六）持有的军队、武装警察部队机动车驾驶证超过有效期的； （七）持有境外机动车驾驶证或者境外机动车驾驶证超过有效期的。 有前款第六项、第七项规定情形之一的，还应当提交机动车驾驶证。"},{"i":28,"n":"第二十八条","txt":"申请人提交的证明、凭证齐全、符合法定形式的，车辆管理所应当受理，并按规定审查申请人的机动车驾驶证申请条件。属于第二十五条规定情形的，还应当核查申请人的出入境记录；属于第二十七条第一款第一项至第五项规定情形之一的，还应当核查申请人的驾驶经历；属于正在接受全日制驾驶职业教育的学生，申请增加大型客车、重型牵引挂车准驾车型的，还应当核查申请人的学籍。 公安机关交通管理部门已经实现与医疗机构等单位联网核查的，申请人免予提交身体条件证明等证明、凭证。 对于符合申请条件的，车辆管理所应当按规定安排预约考试；不需要考试的，一日内核发机动车驾驶证。申请人属于复员、转业、退伍人员持军队、武装警察部队机动车驾驶证申请机动车驾驶证的，应当收回军队、武装警察部队机动车驾驶证。"},{"i":29,"n":"第二十九条","txt":"车辆管理所对申请人的申请条件及提交的材料、申告的事项有疑义的，可以对实质内容进行调查核实。 调查时，应当询问申请人并制作询问笔录，向证明、凭证的核发机关核查。 经调查，申请人不符合申请条件的，不予办理；有违法行为的，依法予以处理。"},{"i":30,"n":"第三十条","txt":"机动车驾驶人考试内容分为道路交通安全法律、法规和相关知识考试科目（以下简称“科目一”）、场地驾驶技能考试科目（以下简称“科目二”）、道路驾驶技能和安全文明驾驶常识考试科目（以下简称“科目三”）。 已持有小型自动挡汽车准驾车型驾驶证申请增加小型汽车准驾车型的，应当考试科目二和科目三。 已持有大型客车、城市公交车、中型客车、大型货车、小型汽车、小型自动挡汽车准驾车型驾驶证申请增加轻型牵引挂车准驾车型的，应当考试科目二和科目三安全文明驾驶常识。 已持有轻便摩托车准驾车型驾驶证申请增加普通三轮摩托车、普通二轮摩托车准驾车型的，或者持有普通二轮摩托车驾驶证申请增加普通三轮摩托车准驾车型的，应当考试科目二和科目三。 已持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、小型汽车、小型自动挡汽车准驾车型驾驶证的机动车驾驶人身体条件发生变化，不符合所持机动车驾驶证准驾车型的条件，但符合残疾人专"},{"i":31,"n":"第三十一条","txt":"考试内容和合格标准全国统一，根据不同准驾车型规定相应的考试项目。"},{"i":32,"n":"第三十二条","txt":"科目一考试内容包括：道路通行、交通信号、道路交通安全违法行为和交通事故处理、机动车驾驶证申领和使用、机动车登记等规定以及其他道路交通安全法律、法规和规章。"},{"i":33,"n":"第三十三条","txt":"科目二考试内容包括： （一）大型客车、重型牵引挂车、城市公交车、中型客车、大型货车考试桩考、坡道定点停车和起步、侧方停车、通过单边桥、曲线行驶、直角转弯、通过限宽门、窄路掉头，以及模拟高速公路、连续急弯山区路、隧道、雨（雾）天、湿滑路、紧急情况处置； （二）小型汽车、低速载货汽车考试倒车入库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯； （三）小型自动挡汽车、残疾人专用小型自动挡载客汽车考试倒车入库、侧方停车、曲线行驶、直角转弯； （四）轻型牵引挂车考试桩考、曲线行驶、直角转弯； （五）三轮汽车、普通三轮摩托车、普通二轮摩托车和轻便摩托车考试桩考、坡道定点停车和起步、通过单边桥； （六）轮式专用机械车、无轨电车、有轨电车的考试内容由省级公安机关交通管理部门确定。 对第一款第一项至第三项规定的准驾车型，省级公安机关交通管理部门可以根据实际增加考试内容。"},{"i":34,"n":"第三十四条","txt":"科目三道路驾驶技能考试内容包括：大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车和残疾人专用小型自动挡载客汽车考试上车准备、起步、直线行驶、加减挡位操作、变更车道、靠边停车、直行通过路口、路口左转弯、路口右转弯、通过人行横道线、通过学校区域、通过公共汽车站、会车、超车、掉头、夜间行驶；其他准驾车型的考试内容，由省级公安机关交通管理部门确定。 大型客车、重型牵引挂车、城市公交车、中型客车、大型货车考试里程不少于10公里，其中初次申领城市公交车、大型货车准驾车型的，白天考试里程不少于5公里，夜间考试里程不少于3公里。小型汽车、小型自动挡汽车、低速载货汽车、残疾人专用小型自动挡载客汽车考试里程不少于3公里。不进行夜间考试的，应当进行模拟夜间灯光考试。 对大型客车、重型牵引挂车、城市公交车、中型客车、大型货车准驾车型，省级公安机关交通管理部门应当根"},{"i":35,"n":"第三十五条","txt":"科目三安全文明驾驶常识考试内容包括：安全文明驾驶操作要求、恶劣气象和复杂道路条件下的安全驾驶知识、爆胎等紧急情况下的临危处置方法、防范次生事故处置知识、伤员急救知识等。"},{"i":36,"n":"第三十六条","txt":"持军队、武装警察部队机动车驾驶证的人申请大型客车、重型牵引挂车、城市公交车、中型客车、大型货车准驾车型机动车驾驶证的，应当考试科目一和科目三；申请其他准驾车型机动车驾驶证的，免予考试核发机动车驾驶证。"},{"i":37,"n":"第三十七条","txt":"持境外机动车驾驶证申请机动车驾驶证的，应当考试科目一。申请准驾车型为大型客车、重型牵引挂车、城市公交车、中型客车、大型货车机动车驾驶证的，应当考试科目一、科目二和科目三。 属于外国驻华使馆、领馆人员及国际组织驻华代表机构人员申请的，应当按照外交对等原则执行。"},{"i":38,"n":"第三十八条","txt":"各科目考试的合格标准为： （一）科目一考试满分为100分，成绩达到90分的为合格； （二）科目二考试满分为100分，考试大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、轻型牵引挂车准驾车型的，成绩达到90分的为合格，其他准驾车型的成绩达到80分的为合格； （三）科目三道路驾驶技能和安全文明驾驶常识考试满分分别为100分，成绩分别达到90分的为合格。"},{"i":39,"n":"第三十九条","txt":"车辆管理所应当按照预约的考场和时间安排考试。申请人科目一考试合格后，可以预约科目二或者科目三道路驾驶技能考试。有条件的地方，申请人可以同时预约科目二、科目三道路驾驶技能考试，预约成功后可以连续进行考试。科目二、科目三道路驾驶技能考试均合格后，申请人可以当日参加科目三安全文明驾驶常识考试。 申请人申请大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、轻型牵引挂车驾驶证，因当地尚未设立科目二考场的，可以选择省（自治区）内其他考场参加考试。 申请人申领小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车、轻型牵引挂车驾驶证期间，已通过部分科目考试后，居住地发生变更的，可以申请变更考试地，在现居住地预约其他科目考试。申请变更考试地不得超过三次。 车辆管理所应当使用全国统一的考试预约系统，采用互联网、电话、服务窗口等方式供申请人预约考试。"},{"i":40,"n":"第四十条","txt":"初次申请机动车驾驶证或者申请增加准驾车型的，科目一考试合格后，车辆管理所应当在一日内核发学习驾驶证明。 属于第三十条第二款至第四款规定申请增加准驾车型以及第五款规定申请变更准驾车型的，受理后直接核发学习驾驶证明。 属于自学直考的，车辆管理所还应当按规定发放学车专用标识（附件2）。"},{"i":41,"n":"第四十一条","txt":"申请人在场地和道路上学习驾驶，应当按规定取得学习驾驶证明。学习驾驶证明的有效期为三年，但有效期截止日期不得超过申请年龄条件上限。申请人应当在有效期内完成科目二和科目三考试。未在有效期内完成考试的，已考试合格的科目成绩作废。 学习驾驶证明可以采用纸质或者电子形式，纸质学习驾驶证明和电子学习驾驶证明具有同等效力。申请人可以通过互联网交通安全综合服务管理平台打印或者下载学习驾驶证明。"},{"i":42,"n":"第四十二条","txt":"申请人在道路上学习驾驶，应当随身携带学习驾驶证明，使用教练车或者学车专用标识签注的自学用车，在教练员或者学车专用标识签注的指导人员随车指导下，按照公安机关交通管理部门指定的路线、时间进行。 申请人为自学直考人员的，在道路上学习驾驶时，应当在自学用车上按规定放置、粘贴学车专用标识，自学用车不得搭载随车指导人员以外的其他人员。"},{"i":43,"n":"第四十三条","txt":"初次申请机动车驾驶证或者申请增加准驾车型的，申请人预约考试科目二，应当符合下列规定： （一）报考小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车、轮式专用机械车、无轨电车、有轨电车准驾车型的，在取得学习驾驶证明满十日后预约考试； （二）报考大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、轻型牵引挂车准驾车型的，在取得学习驾驶证明满二十日后预约考试。"},{"i":44,"n":"第四十四条","txt":"初次申请机动车驾驶证或者申请增加准驾车型的，申请人预约考试科目三，应当符合下列规定： （一）报考小型自动挡汽车、残疾人专用小型自动挡载客汽车、低速载货汽车、三轮汽车准驾车型的，在取得学习驾驶证明满二十日后预约考试； （二）报考小型汽车、轮式专用机械车、无轨电车、有轨电车准驾车型的，在取得学习驾驶证明满三十日后预约考试； （三）报考大型客车、重型牵引挂车、城市公交车、中型客车、大型货车准驾车型的，在取得学习驾驶证明满四十日后预约考试。属于已经持有汽车类驾驶证，申请增加准驾车型的，在取得学习驾驶证明满三十日后预约考试。"},{"i":45,"n":"第四十五条","txt":"持军队、武装警察部队或者境外机动车驾驶证申请机动车驾驶证的，应当自车辆管理所受理之日起三年内完成科目考试。"},{"i":46,"n":"第四十六条","txt":"申请人因故不能按照预约时间参加考试的，应当提前一日申请取消预约。对申请人未按照预约考试时间参加考试的，判定该次考试不合格。"},{"i":47,"n":"第四十七条","txt":"每个科目考试一次，考试不合格的，可以补考一次。不参加补考或者补考仍不合格的，本次考试终止，申请人应当重新预约考试，但科目二、科目三考试应当在十日后预约。科目三安全文明驾驶常识考试不合格的，已通过的道路驾驶技能考试成绩有效。 在学习驾驶证明有效期内，科目二和科目三道路驾驶技能考试预约考试的次数分别不得超过五次。第五次考试仍不合格的，已考试合格的其他科目成绩作废。"},{"i":48,"n":"第四十八条","txt":"车辆管理所组织考试前应当使用全国统一的计算机管理系统当日随机选配考试员，随机安排考生分组，随机选取考试路线。"},{"i":49,"n":"第四十九条","txt":"从事考试工作的人员，应当持有公安机关交通管理部门颁发的资格证书。公安机关交通管理部门应当在公安民警、警务辅助人员中选拔足够数量的考试员，从事考试工作。可以聘用运输企业驾驶人、警风警纪监督员等人员承担考试辅助工作和监督职责。 考试员应当认真履行考试职责，严格按照规定考试，接受社会监督。在考试前应当自我介绍，讲解考试要求，核实申请人身份；考试中应当严格执行考试程序，按照考试项目和考试标准评定考试成绩；考试后应当当场公布考试成绩，讲评考试不合格原因。 每个科目的考试成绩单应当有申请人和考试员的签名。未签名的不得核发机动车驾驶证。"},{"i":50,"n":"第五十条","txt":"考试员、考试辅助人员及考场工作人员应当严格遵守考试工作纪律，不得为不符合机动车驾驶许可条件、未经考试、考试不合格人员签注合格考试成绩，不得减少考试项目、降低评判标准或者参与、协助、纵容考试作弊，不得参与或者变相参与驾驶培训机构、社会考场经营活动，不得收取驾驶培训机构、社会考场、教练员、申请人的财物。"},{"i":51,"n":"第五十一条","txt":"直辖市、设区的市或者相当于同级的公安机关交通管理部门应当根据本地考试需求建设考场，配备足够数量的考试车辆。对考场布局、数量不能满足本地考试需求的，应当采取政府购买服务等方式使用社会考场，并按照公平竞争、择优选定的原则，依法通过公开招标等程序确定。对考试供给能力能够满足考试需求的，应当及时向社会公告，不再购买社会考场服务。 考试场地建设、路段设置、车辆配备、设施设备配置以及考试项目、评判要求应当符合相关标准。考试场地、考试设备和考试系统应当经省级公安机关交通管理部门验收合格后方可使用。公安机关交通管理部门应当加强对辖区考场的监督管理，定期开展考试场地、考试车辆、考试设备和考场管理情况的监督检查。"},{"i":52,"n":"第五十二条","txt":"车辆管理所应当在办事大厅、候考场所和互联网公开各考场的考试能力、预约计划、预约人数和约考结果等情况，公布考场布局、考试路线和流程。考试预约计划应当至少在考试前十日在互联网上公开。 车辆管理所应当在候考场所、办事大厅向群众直播考试视频，考生可以在考试结束后三日内查询自己的考试视频资料。"},{"i":53,"n":"第五十三条","txt":"车辆管理所应当严格比对、核验考生身份，对考试过程进行全程录音、录像，并实时监控考试过程，没有使用录音、录像设备的，不得组织考试。严肃考试纪律，规范考场秩序，对考场秩序混乱的，应当中止考试。考试过程中，考试员应当使用执法记录仪记录监考过程。 车辆管理所应当建立音视频信息档案，存储录音、录像设备和执法记录仪记录的音像资料。建立考试质量抽查制度，每日抽查音视频信息档案，发现存在违反考试纪律、考场秩序混乱以及音视频信息缺失或者不完整的，应当进行调查处理。 省级公安机关交通管理部门应当定期抽查音视频信息档案，及时通报、纠正、查处发现的问题。"},{"i":54,"n":"第五十四条","txt":"车辆管理所应当根据考试场地、考试设备、考试车辆、考试员数量等实际情况，核定每个考场、每个考试员每日最大考试量。 车辆管理所应当根据驾驶培训主管部门提供的信息对驾驶培训机构教练员、教练车、训练场地等情况进行备案。"},{"i":55,"n":"第五十五条","txt":"公安机关交通管理部门应当建立业务监督管理中心，通过远程监控、数据分析、日常检查、档案抽查、业务回访等方式，对机动车驾驶人考试和机动车驾驶证业务办理情况进行监督管理。 直辖市、设区的市或者相当于同级的公安机关交通管理部门应当通过监管系统每周对机动车驾驶人考试情况进行监控、分析，及时查处整改发现的问题。省级公安机关交通管理部门应当通过监管系统每月对机动车驾驶人考试情况进行监控、分析，及时查处、通报发现的问题。 车辆管理所存在为未经考试或者考试不合格人员核发机动车驾驶证等严重违规办理机动车驾驶证业务情形的，上级公安机关交通管理部门可以暂停该车辆管理所办理相关业务或者指派其他车辆管理所人员接管业务。"},{"i":56,"n":"第五十六条","txt":"县级公安机关交通管理部门办理机动车驾驶证业务的，办公场所、设施设备、人员资质和信息系统等应当满足业务办理需求，并符合相关规定和标准要求。 直辖市、设区的市公安机关交通管理部门应当加强对县级公安机关交通管理部门办理机动车驾驶证相关业务的指导、培训和监督管理。"},{"i":57,"n":"第五十七条","txt":"公安机关交通管理部门应当对社会考场的场地设施、考试系统、考试工作等进行统一管理。 社会考场的考试系统应当接入机动车驾驶人考试管理系统，实时上传考试过程录音录像、考试成绩等信息。"},{"i":58,"n":"第五十八条","txt":"直辖市、设区的市或者相当于同级的公安机关交通管理部门应当每月向社会公布车辆管理所考试员考试质量情况、三年内驾龄驾驶人交通违法率和交通肇事率等信息。 直辖市、设区的市或者相当于同级的公安机关交通管理部门应当每月向社会公布辖区内驾驶培训机构的考试合格率、三年内驾龄驾驶人交通违法率和交通肇事率等信息，按照考试合格率、三年内驾龄驾驶人交通违法率和交通肇事率对驾驶培训机构培训质量公开排名，并通报培训主管部门。"},{"i":59,"n":"第五十九条","txt":"对三年内驾龄驾驶人发生一次死亡3人以上交通事故且负主要以上责任的，省级公安机关交通管理部门应当倒查车辆管理所考试、发证情况，向社会公布倒查结果。对三年内驾龄驾驶人发生一次死亡1至2人的交通事故且负主要以上责任的，直辖市、设区的市或者相当于同级的公安机关交通管理部门应当组织责任倒查。 直辖市、设区的市或者相当于同级的公安机关交通管理部门发现驾驶培训机构及其教练员存在缩短培训学时、减少培训项目以及贿赂考试员、以承诺考试合格等名义向学员索取财物、参与违规办理驾驶证或者考试舞弊行为的，应当通报培训主管部门，并向社会公布。 公安机关交通管理部门发现考场、考试设备生产销售企业及其工作人员存在组织或者参与考试舞弊、伪造或者篡改考试系统数据的，不得继续使用该考场或者采购该企业考试设备；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"申请人考试合格后，应当接受不少于半小时的交通安全文明驾驶常识和交通事故案例警示教育，并参加领证宣誓仪式。 车辆管理所应当在申请人参加领证宣誓仪式的当日核发机动车驾驶证。"},{"i":61,"n":"第六十一条","txt":"公安机关交通管理部门应当实行机动车驾驶证电子化，机动车驾驶人可以通过互联网交通安全综合服务管理平台申请机动车驾驶证电子版。 机动车驾驶证电子版与纸质版具有同等效力。"},{"i":62,"n":"第六十二条","txt":"机动车驾驶人在机动车驾驶证的六年有效期内，每个记分周期均未记满12分的，换发十年有效期的机动车驾驶证；在机动车驾驶证的十年有效期内，每个记分周期均未记满12分的，换发长期有效的机动车驾驶证。"},{"i":63,"n":"第六十三条","txt":"机动车驾驶人应当于机动车驾驶证有效期满前九十日内，向机动车驾驶证核发地或者核发地以外的车辆管理所申请换证。申请时应当确认申请信息，并提交以下证明、凭证： （一）机动车驾驶人的身份证明； （二）医疗机构出具的有关身体条件的证明。"},{"i":64,"n":"第六十四条","txt":"机动车驾驶人户籍迁出原车辆管理所管辖区的，应当向迁入地车辆管理所申请换证。机动车驾驶人在核发地车辆管理所管辖区以外居住的，可以向居住地车辆管理所申请换证。申请时应当确认申请信息，提交机动车驾驶人的身份证明和机动车驾驶证，并申报身体条件情况。"},{"i":65,"n":"第六十五条","txt":"年龄在60周岁以上的，不得驾驶大型客车、重型牵引挂车、城市公交车、中型客车、大型货车、轮式专用机械车、无轨电车和有轨电车。持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证的，应当到机动车驾驶证核发地或者核发地以外的车辆管理所换领准驾车型为小型汽车或者小型自动挡汽车的机动车驾驶证，其中属于持有重型牵引挂车驾驶证的，还可以保留轻型牵引挂车准驾车型。 年龄在70周岁以上的，不得驾驶低速载货汽车、三轮汽车、轻型牵引挂车、普通三轮摩托车、普通二轮摩托车。持有普通三轮摩托车、普通二轮摩托车驾驶证的，应当到机动车驾驶证核发地或者核发地以外的车辆管理所换领准驾车型为轻便摩托车的机动车驾驶证；持有驾驶证包含轻型牵引挂车准驾车型的，应当到机动车驾驶证核发地或者核发地以外的车辆管理所换领准驾车型为小型汽车或者小型自动挡汽车的机动车驾驶证。 有前两款规定情形之一的，车辆管理所应当通知机动车驾驶"},{"i":66,"n":"第六十六条","txt":"有下列情形之一的，机动车驾驶人应当在三十日内到机动车驾驶证核发地或者核发地以外的车辆管理所申请换证： （一）在车辆管理所管辖区域内，机动车驾驶证记载的机动车驾驶人信息发生变化的； （二）机动车驾驶证损毁无法辨认的。 申请时应当确认申请信息，并提交机动车驾驶人的身份证明；属于第一款第一项的，还应当提交机动车驾驶证；属于身份证明号码变更的，还应当提交相关变更证明。"},{"i":67,"n":"第六十七条","txt":"机动车驾驶人身体条件发生变化，不符合所持机动车驾驶证准驾车型的条件，但符合准予驾驶的其他准驾车型条件的，应当在三十日内到机动车驾驶证核发地或者核发地以外的车辆管理所申请降低准驾车型。申请时应当确认申请信息，并提交机动车驾驶人的身份证明、医疗机构出具的有关身体条件的证明。 机动车驾驶人身体条件发生变化，不符合第十四条第二项规定或者具有第十五条规定情形之一，不适合驾驶机动车的，应当在三十日内到机动车驾驶证核发地车辆管理所申请注销。申请时应当确认申请信息，并提交机动车驾驶人的身份证明和机动车驾驶证。 机动车驾驶人身体条件不适合驾驶机动车的，不得驾驶机动车。"},{"i":68,"n":"第六十八条","txt":"车辆管理所对符合第六十三条至第六十六条、第六十七条第一款规定的，应当在一日内换发机动车驾驶证。对符合第六十七条第二款规定的，应当在一日内注销机动车驾驶证。其中，对符合第六十四条、第六十五条、第六十六条第一款第一项、第六十七条规定的，还应当收回原机动车驾驶证。"},{"i":69,"n":"第六十九条","txt":"机动车驾驶证遗失的，机动车驾驶人应当向机动车驾驶证核发地或者核发地以外的车辆管理所申请补发。申请时应当确认申请信息，并提交机动车驾驶人的身份证明。符合规定的，车辆管理所应当在一日内补发机动车驾驶证。 机动车驾驶人补领机动车驾驶证后，原机动车驾驶证作废，不得继续使用。 机动车驾驶证被依法扣押、扣留或者暂扣期间，机动车驾驶人不得申请补发。"},{"i":70,"n":"第七十条","txt":"机动车驾驶人向核发地以外的车辆管理所申请办理第六十三条、第六十五条、第六十六条、第六十七条第一款、第六十九条规定的换证、补证业务时，应当同时按照第六十四条规定办理。"},{"i":71,"n":"第七十一条","txt":"公安机关交通管理部门对机动车驾驶人的道路交通安全违法行为，除依法给予行政处罚外，实行道路交通安全违法行为累积记分制度，记分周期为12个月，满分为12分。 机动车驾驶人在一个记分周期内记分达到12分的，应当按规定参加学习、考试。"},{"i":72,"n":"第七十二条","txt":"机动车驾驶人应当按照法律、行政法规的规定，定期到公安机关交通管理部门接受审验。 机动车驾驶人按照本规定第六十三条、第六十四条换领机动车驾驶证时，应当接受公安机关交通管理部门的审验。 持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证的驾驶人，应当在每个记分周期结束后三十日内到公安机关交通管理部门接受审验。但在一个记分周期内没有记分记录的，免予本记分周期审验。 持有第三款规定以外准驾车型驾驶证的驾驶人，发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验。 年龄在70周岁以上的机动车驾驶人发生责任交通事故造成人员重伤或者死亡的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验。 机动车驾驶人可以在机动车驾驶证核发地或者核发地以外的地方参加审验、提交身体条件证明。"},{"i":73,"n":"第七十三条","txt":"机动车驾驶证审验内容包括： （一）道路交通安全违法行为、交通事故处理情况； （二）身体条件情况； （三）道路交通安全违法行为记分及记满12分后参加学习和考试情况。 持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证一个记分周期内有记分的，以及持有其他准驾车型驾驶证发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的驾驶人，审验时应当参加不少于三小时的道路交通安全法律法规、交通安全文明驾驶、应急处置等知识学习，并接受交通事故案例警示教育。 年龄在70周岁以上的机动车驾驶人审验时还应当按照规定进行记忆力、判断力、反应力等能力测试。 对道路交通安全违法行为或者交通事故未处理完毕的、身体条件不符合驾驶许可条件的、未按照规定参加学习、教育和考试的，不予通过审验。"},{"i":74,"n":"第七十四条","txt":"年龄在70周岁以上的机动车驾驶人，应当每年进行一次身体检查，在记分周期结束后三十日内，提交医疗机构出具的有关身体条件的证明。 持有残疾人专用小型自动挡载客汽车驾驶证的机动车驾驶人，应当每三年进行一次身体检查，在记分周期结束后三十日内，提交医疗机构出具的有关身体条件的证明。 机动车驾驶人按照本规定第七十二条第三款、第四款规定参加审验时，应当申报身体条件情况。"},{"i":75,"n":"第七十五条","txt":"机动车驾驶人因服兵役、出国（境）等原因，无法在规定时间内办理驾驶证期满换证、审验、提交身体条件证明的，可以在驾驶证有效期内或者有效期届满一年内向机动车驾驶证核发地车辆管理所申请延期办理。申请时应当确认申请信息，并提交机动车驾驶人的身份证明。 延期期限最长不超过三年。延期期间机动车驾驶人不得驾驶机动车。"},{"i":76,"n":"第七十六条","txt":"机动车驾驶人初次取得汽车类准驾车型或者初次取得摩托车类准驾车型后的12个月为实习期。 在实习期内驾驶机动车的，应当在车身后部粘贴或者悬挂统一式样的实习标志（附件3）。"},{"i":77,"n":"第七十七条","txt":"机动车驾驶人在实习期内不得驾驶公共汽车、营运客车或者执行任务的警车、消防车、救护车、工程救险车以及载有爆炸物品、易燃易爆化学物品、剧毒或者放射性等危险物品的机动车；驾驶的机动车不得牵引挂车。 驾驶人在实习期内驾驶机动车上高速公路行驶，应当由持相应或者包含其准驾车型驾驶证三年以上的驾驶人陪同。其中，驾驶残疾人专用小型自动挡载客汽车的，可以由持有小型自动挡载客汽车以上准驾车型驾驶证的驾驶人陪同。 在增加准驾车型后的实习期内，驾驶原准驾车型的机动车时不受上述限制。"},{"i":78,"n":"第七十八条","txt":"持有准驾车型为残疾人专用小型自动挡载客汽车的机动车驾驶人驾驶机动车时，应当按规定在车身设置残疾人机动车专用标志（附件4）。 有听力障碍的机动车驾驶人驾驶机动车时，应当佩戴助听设备。有视力矫正的机动车驾驶人驾驶机动车时，应当佩戴眼镜。"},{"i":79,"n":"第七十九条","txt":"机动车驾驶人有下列情形之一的，车辆管理所应当注销其机动车驾驶证： （一）死亡的； （二）提出注销申请的； （三）丧失民事行为能力，监护人提出注销申请的； （四）身体条件不适合驾驶机动车的； （五）有器质性心脏病、癫痫病、美尼尔氏症、眩晕症、癔病、震颤麻痹、精神病、痴呆以及影响肢体活动的神经系统疾病等妨碍安全驾驶疾病的； （六）被查获有吸食、注射毒品后驾驶机动车行为，依法被责令社区戒毒、社区康复或者决定强制隔离戒毒，或者长期服用依赖性精神药品成瘾尚未戒除的； （七）代替他人参加机动车驾驶人考试的； （八）超过机动车驾驶证有效期一年以上未换证的； （九）年龄在70周岁以上，在一个记分周期结束后一年内未提交身体条件证明的；或者持有残疾人专用小型自动挡载客汽车准驾车型，在三个记分周期结束后一年内未提交身体条件证明的； （十）年龄在60周岁以上，所持机动车驾驶证只具有轮式专用机械车、无轨电车或者"},{"i":80,"n":"第八十条","txt":"机动车驾驶人在实习期内发生的道路交通安全违法行为被记满12分的，注销其实习的准驾车型驾驶资格。"},{"i":81,"n":"第八十一条","txt":"机动车驾驶人联系电话、联系地址等信息发生变化的，应当在信息变更后三十日内，向驾驶证核发地车辆管理所备案。 持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证的驾驶人从业单位等信息发生变化的，应当在信息变更后三十日内，向从业单位所在地车辆管理所备案。"},{"i":82,"n":"第八十二条","txt":"道路运输企业应当定期将聘用的机动车驾驶人向所在地公安机关交通管理部门备案，督促及时处理道路交通安全违法行为、交通事故和参加机动车驾驶证审验。 公安机关交通管理部门应当每月向辖区内交通运输主管部门、运输企业通报机动车驾驶人的道路交通安全违法行为、记分和交通事故等情况。"},{"i":83,"n":"第八十三条","txt":"车辆管理所在办理驾驶证核发及相关业务过程中发现存在以下情形的，应当及时开展调查： （一）涉嫌提交虚假申请材料的； （二）涉嫌在考试过程中有贿赂、舞弊行为的； （三）涉嫌以欺骗、贿赂等不正当手段取得机动车驾驶证的； （四）涉嫌使用伪造、变造的机动车驾驶证的； （五）存在短期内频繁补换领、转出转入驾驶证等异常情形的； （六）存在其他违法违规情形的。 车辆管理所发现申请人通过互联网办理驾驶证补证、换证等业务存在前款规定嫌疑情形的，应当转为现场办理，当场审查申请材料，及时开展调查。"},{"i":84,"n":"第八十四条","txt":"车辆管理所开展调查时，可以通知申请人协助调查，询问嫌疑情况，记录调查内容，并可以采取实地检查、调取档案、调取考试视频监控等方式进行核查。 对经调查发现涉及行政案件或者刑事案件的，应当依法采取必要的强制措施或者其他处置措施，移交有管辖权的公安机关按照《公安机关办理行政案件程序规定》《公安机关办理刑事案件程序规定》等规定办理。"},{"i":85,"n":"第八十五条","txt":"办理残疾人专用小型自动挡载客汽车驾驶证业务时，提交的身体条件证明应当由经省级卫生健康行政部门认定的专门医疗机构出具。办理其他机动车驾驶证业务时，提交的身体条件证明应当由县级、部队团级以上医疗机构，或者经地市级以上卫生健康行政部门认定的具有健康体检资质的二级以上医院、乡镇卫生院、社区卫生服务中心、健康体检中心等医疗机构出具。 身体条件证明自出具之日起六个月内有效。 公安机关交通管理部门应当会同卫生健康行政部门在办公场所和互联网公示辖区内可以出具有关身体条件证明的医疗机构名称、地址及联系方式。"},{"i":86,"n":"第八十六条","txt":"医疗机构出具虚假身体条件证明的，公安机关交通管理部门应当停止认可该医疗机构出具的证明，并通报卫生健康行政部门。"},{"i":87,"n":"第八十七条","txt":"校车驾驶人应当依法取得校车驾驶资格。 取得校车驾驶资格应当符合下列条件： （一）取得相应准驾车型驾驶证并具有三年以上驾驶经历，年龄在25周岁以上、不超过60周岁； （二）最近连续三个记分周期内没有被记满12分记录； （三）无致人死亡或者重伤的交通事故责任记录； （四）无酒后驾驶或者醉酒驾驶机动车记录，最近一年内无驾驶客运车辆超员、超速等严重道路交通安全违法行为记录； （五）无犯罪记录； （六）身心健康，无传染性疾病，无癫痫病、精神病等可能危及行车安全的疾病病史，无酗酒、吸毒行为记录。"},{"i":88,"n":"第八十八条","txt":"机动车驾驶人申请取得校车驾驶资格，应当向县级或者设区的市级公安机关交通管理部门提出申请，确认申请信息，并提交以下证明、凭证： （一）申请人的身份证明； （二）机动车驾驶证； （三）医疗机构出具的有关身体条件的证明。"},{"i":89,"n":"第八十九条","txt":"公安机关交通管理部门自受理申请之日起五日内审查提交的证明、凭证，并向所在地县级公安机关核查，确认申请人无犯罪、吸毒行为记录。对符合条件的，在机动车驾驶证上签注准许驾驶校车及相应车型，并通报教育行政部门；不符合条件的，应当书面说明理由。"},{"i":90,"n":"第九十条","txt":"校车驾驶人应当在每个记分周期结束后三十日内到公安机关交通管理部门接受审验。审验时，应当提交医疗机构出具的有关身体条件的证明，参加不少于三小时的道路交通安全法律法规、交通安全文明驾驶、应急处置等知识学习，并接受交通事故案例警示教育。"},{"i":91,"n":"第九十一条","txt":"公安机关交通管理部门应当与教育行政部门和学校建立校车驾驶人的信息交换机制，每月通报校车驾驶人的交通违法、交通事故和审验等情况。"},{"i":92,"n":"第九十二条","txt":"校车驾驶人有下列情形之一的，公安机关交通管理部门应当注销其校车驾驶资格，通知机动车驾驶人换领机动车驾驶证，并通报教育行政部门和学校： （一）提出注销申请的； （二）年龄超过60周岁的； （三）在致人死亡或者重伤的交通事故负有责任的； （四）有酒后驾驶或者醉酒驾驶机动车，以及驾驶客运车辆超员、超速等严重道路交通安全违法行为的； （五）有记满12分或者犯罪记录的； （六）有传染性疾病，癫痫病、精神病等可能危及行车安全的疾病，有酗酒、吸毒行为记录的。 未收回签注校车驾驶许可的机动车驾驶证的，应当公告其校车驾驶资格作废。"},{"i":93,"n":"第九十三条","txt":"申请人隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，公安机关交通管理部门不予受理或者不予办理，处五百元以下罚款；申请人在一年内不得再次申领机动车驾驶证。 申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效，公安机关交通管理部门处二千元以下罚款；申请人在一年内不得再次申领机动车驾驶证。 申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可，处二千元以下罚款；申请人在三年内不得再次申领机动车驾驶证。 组织、参与实施前三款行为之一牟取经济利益的，由公安机关交通管理部门处违法所得三倍以上五倍以下罚款，但最高不超过十万元。 申请人隐瞒有关情况或者提供虚假材料申请校车驾驶资格的，公安机关交通管理部门不予受理或者不予办理，处五百元以下罚款；申请人在一年内不得再次申请校车驾驶资格。申请人以欺骗、贿赂等不正当手段取得"},{"i":94,"n":"第九十四条","txt":"申请人在教练员或者学车专用标识签注的指导人员随车指导下，使用符合规定的机动车学习驾驶中有道路交通安全违法行为或者发生交通事故的，按照《道路交通安全法实施条例》第二十条规定，由教练员或者随车指导人员承担责任。"},{"i":95,"n":"第九十五条","txt":"申请人在道路上学习驾驶时，有下列情形之一的，由公安机关交通管理部门对教练员或者随车指导人员处二十元以上二百元以下罚款： （一）未按照公安机关交通管理部门指定的路线、时间进行的； （二）未按照本规定第四十二条规定放置、粘贴学车专用标识的。"},{"i":96,"n":"第九十六条","txt":"申请人在道路上学习驾驶时，有下列情形之一的，由公安机关交通管理部门对教练员或者随车指导人员处二百元以上五百元以下罚款： （一）未使用符合规定的机动车的； （二）自学用车搭载随车指导人员以外的其他人员的。"},{"i":97,"n":"第九十七条","txt":"申请人在道路上学习驾驶时，有下列情形之一的，由公安机关交通管理部门按照《道路交通安全法》第九十九条第一款第一项规定予以处罚： （一）未取得学习驾驶证明的； （二）没有教练员或者随车指导人员的； （三）由不符合规定的人员随车指导的。 将机动车交由有前款规定情形之一的申请人驾驶的，由公安机关交通管理部门按照《道路交通安全法》第九十九条第一款第二项规定予以处罚。"},{"i":98,"n":"第九十八条","txt":"机动车驾驶人有下列行为之一的，由公安机关交通管理部门处二十元以上二百元以下罚款： （一）机动车驾驶人补换领机动车驾驶证后，继续使用原机动车驾驶证的； （二）在实习期内驾驶机动车不符合第七十七条规定的； （三）持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证的驾驶人，未按照第八十一条规定申报变更信息的。 有第一款第一项规定情形的，由公安机关交通管理部门收回原机动车驾驶证。"},{"i":99,"n":"第九十九条","txt":"机动车驾驶人有下列行为之一的，由公安机关交通管理部门处二百元以上五百元以下罚款： （一）机动车驾驶证被依法扣押、扣留或者暂扣期间，采用隐瞒、欺骗手段补领机动车驾驶证的； （二）机动车驾驶人身体条件发生变化不适合驾驶机动车，仍驾驶机动车的； （三）逾期不参加审验仍驾驶机动车的。 有第一款第一项、第二项规定情形之一的，由公安机关交通管理部门收回机动车驾驶证。"},{"i":100,"n":"第一百条","txt":"机动车驾驶人参加审验教育时在签注学习记录、学习过程中弄虚作假的，相应学习记录无效，重新参加审验学习，由公安机关交通管理部门处一千元以下罚款。 代替实际机动车驾驶人参加审验教育的，由公安机关交通管理部门处二千元以下罚款。 组织他人实施前两款行为之一，有违法所得的，由公安机关交通管理部门处违法所得三倍以下罚款，但最高不超过二万元；没有违法所得的，由公安机关交通管理部门处二万元以下罚款。"},{"i":101,"n":"第一百零一条","txt":"省、自治区、直辖市公安厅、局可以根据本地区的实际情况，在本规定的处罚幅度范围内，制定具体的执行标准。 对本规定的道路交通安全违法行为的处理程序按照《道路交通安全违法行为处理程序规定》执行。"},{"i":102,"n":"第一百零二条","txt":"公安机关交通管理部门及其交通警察、警务辅助人员办理机动车驾驶证业务、开展机动车驾驶人考试工作，应当接受监察机关、公安机关督察审计部门等依法实施的监督。 公安机关交通管理部门及其交通警察、警务辅助人员办理机动车驾驶证业务、开展机动车驾驶人考试工作，应当自觉接受社会和公民的监督。"},{"i":103,"n":"第一百零三条","txt":"交通警察有下列情形之一的，按照有关规定给予处分；聘用人员有下列情形之一的予以解聘。构成犯罪的，依法追究刑事责任： （一）为不符合机动车驾驶许可条件、未经考试、考试不合格人员签注合格考试成绩或者核发机动车驾驶证的； （二）减少考试项目、降低评判标准或者参与、协助、纵容考试作弊的； （三）为不符合规定的申请人发放学习驾驶证明、学车专用标识的； （四）与非法中介串通牟取经济利益的； （五）违反规定侵入机动车驾驶证管理系统，泄漏、篡改、买卖系统数据，或者泄漏系统密码的； （六）违反规定向他人出售或者提供机动车驾驶证信息的； （七）参与或者变相参与驾驶培训机构、社会考场、考试设备生产销售企业经营活动的； （八）利用职务上的便利索取、收受他人财物或者牟取其他利益的。 交通警察未按照第五十三条第一款规定使用执法记录仪的，根据情节轻重，按照有关规定给予处分。 公安机关交通管理部门有第一款所列行为之一的"},{"i":104,"n":"第一百零四条","txt":"国家之间对机动车驾驶证有互相认可协议的，按照协议办理。 国家之间签订有关协定涉及机动车驾驶证的，按照协定执行。"},{"i":105,"n":"第一百零五条","txt":"机动车驾驶人可以委托代理人代理换证、补证、提交身体条件证明、提交审验材料、延期办理和注销业务。代理人申请机动车驾驶证业务时，应当提交代理人的身份证明和机动车驾驶人的委托书。"},{"i":106,"n":"第一百零六条","txt":"公安机关交通管理部门应当实行驾驶人考试、驾驶证管理档案电子化。机动车驾驶证电子档案与纸质档案具有同等效力。"},{"i":107,"n":"第一百零七条","txt":"机动车驾驶证、临时机动车驾驶许可和学习驾驶证明的式样由公安部统一制定并监制。 机动车驾驶证、临时机动车驾驶许可和学习驾驶证明的制作应当按照中华人民共和国公共安全行业标准《中华人民共和国机动车驾驶证件》执行。"},{"i":108,"n":"第一百零八条","txt":"拖拉机驾驶证的申领和使用另行规定。拖拉机驾驶证式样、规格应当符合中华人民共和国公共安全行业标准《中华人民共和国机动车驾驶证件》的规定。"},{"i":109,"n":"第一百零九条","txt":"本规定下列用语的含义： （一）身份证明是指： 1. 居民的身份证明，是居民身份证或者临时居民身份证； 2. 现役军人（含武警）的身份证明，是居民身份证或者临时居民身份证。在未办理居民身份证前，是军队有关部门核发的军官证、文职干部证、士兵证、离休证、退休证等有效军人身份证件，以及其所在的团级以上单位出具的部队驻地住址证明； 3. 香港、澳门特别行政区居民的身份证明，是港澳居民居住证；或者是其所持有的港澳居民来往内地通行证或者外交部核发的中华人民共和国旅行证，以及公安机关出具的住宿登记证明； 4. 台湾地区居民的身份证明，是台湾居民居住证；或者是其所持有的公安机关核发的五年有效的台湾居民来往大陆通行证或者外交部核发的中华人民共和国旅行证，以及公安机关出具的住宿登记证明； 5. 定居国外的中国公民的身份证明，是中华人民共和国护照和公安机关出具的住宿登记证明； 6. 外国人的身份证明，是其所持"},{"i":110,"n":"第一百一十条","txt":"本规定所称“一日”、“三日”、 “五日”，是指工作日，不包括节假日。 本规定所称“以上”、“以下”，包括本数。"},{"i":111,"n":"第一百一十一条","txt":"本规定自2022年4月1日起施行。2012年9月12日发布的《机动车驾驶证申领和使用规定》（公安部令第123号）和2016年1月29日发布的《公安部关于修改<机动车驾驶证申领和使用规定>的决定》（公安部令第139号）同时废止。本规定生效后，公安部以前制定的规定与本规定不一致的，以本规定为准。       附件: 1、准驾车型及代号 2、学车专用标识式样 3、实习标志式样 4、残疾人机动车专用标志"}],"yanhaichuanbobianfangzhianguanliguiding":[{"i":1,"n":"第一条","txt":"为了维护我国沿海地区及海上治安秩序，加强沿海船舶的边防治安管理，促进沿海地区经济发展，保障船员和渔民的合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在我国领海海域内停泊、航行和从事生产作业的各类船舶。我国军用船舶、公务执法船舶及国家另有规定的除外。 国有航运企业船舶、外国籍船舶的管理，依照国家有关规定执行。"},{"i":3,"n":"第三条","txt":"公安边防部门是沿海船舶边防治安管理的主管部门。"},{"i":4,"n":"第四条","txt":"出海船舶除依照规定向主管部门领取有关证件外，应当向船籍港或者船舶所在地公安边防部门申请办理船舶户籍注册，领取《出海船舶户口簿》。 渔政渔港监督管理机关、海事行政主管部门依照国家有关规定不发给有关证书的其他小型沿海船舶，应当向公安边防部门申领《出海船舶边防登记簿》。 内地经营江海运输的个体所有的船舶，按协议到沿海地区从事运输的，应当由所在地县级以上公安机关出具证明，持有关船舶、船员等有效证件，到其协议从事运输的沿海县（市）级以上公安边防部门办理《出海船舶户口簿》《出海船民证》。"},{"i":5,"n":"第五条","txt":"年满十六周岁的未持有《中华人民共和国海员证》或者《船员服务簿》的人员、渔民出海，应当向船籍港或者船舶所在地公安边防部门申领《出海船民证》。临时出海作业的人员，持常住户口所在地公安机关出具的有效证明和《中华人民共和国居民身份证》，向其服务船舶所在地的公安边防部门申领《出海船民证》，发证机关应当注明有效时限。《出海船民证》与《中华人民共和国居民身份证》同时使用。"},{"i":6,"n":"第六条","txt":"公安边防部门对《出海船舶户口簿》、《出海船舶边防登记簿》和《出海船民证》实行年度审验制度。未经年度审验的证件无效。"},{"i":7,"n":"第七条","txt":"出海证件应当妥善保管，不得涂改、伪造、冒用、出借。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，公安边防部门不发给出海证件： （一）刑事案件的被告人和公安机关、国家安全机关、人民检察院、人民法院认定的犯罪嫌疑人； （二）被判处管制、有期徒刑缓刑、假释和保外就医的罪犯； （三）人民法院通知有未了结的经济、民事案件的； （四）出海后将对国家安全造成危害或者对国家利益造成重大损失的； （五）利用船舶进行过走私或者运送偷渡人员的； （六）其他不宜从事出海生产作业的。"},{"i":9,"n":"第九条","txt":"领取《出海船舶户口簿》的船舶更新改造、买卖、转让、租借、报废、灭失及船员的变更，除依照规定在船舶主管部门办理有关手续外，还应当到当地公安边防部门办理船舶户口以及《出海船民证》的变更、注销手续。 船员、渔民终止出海的，应当立即向原发证机关缴销出海证件。"},{"i":10,"n":"第十条","txt":"出海船舶及其渔民、船民应当随船携带有关出海证件，并接受公安边防部门的检查和管理。"},{"i":11,"n":"第十一条","txt":"各类船舶应当依照船舶主管部门的规定编刷船名、船号；未编刷船名、船号或者船名、船号模糊不清的，禁止出海。 船名、船号不得擅自拆换、遮盖、涂改、伪造。禁止悬挂活动船牌号。"},{"i":12,"n":"第十二条","txt":"出海船舶实行船长负责制。出海人员的管理工作由船长负责。"},{"i":13,"n":"第十三条","txt":"各类船舶进出港口时，除依照规定向渔港监督或者各级海事行政主管部门办理进出港签证手续外，还应当办理进出港边防签证手续。进出非本船籍港时，必须到当地公安边防部门或者其授权的船舶签证点，办理边防签证手续，接受检查。"},{"i":14,"n":"第十四条","txt":"出海的船舶，未经当地公安边防部门许可，不得容留非出海人员在船上作业、住宿。"},{"i":15,"n":"第十五条","txt":"沿海船舶集中停泊的地点，应当建立船舶治安保卫组织，在当地公安边防部门指导下进行船舶治安管理工作。"},{"i":16,"n":"第十六条","txt":"船舶失踪、被盗、被劫持，应当立即向就近的公安机关和原发证的公安边防部门报告。"},{"i":17,"n":"第十七条","txt":"出海船舶和人员不得擅自进入国家禁止或者限制进入的海域或岛屿，不得擅自搭靠外国籍或者香港、澳门特别行政区以及台湾地区的船舶。 因避险及其他不可抗力的原因发生前款情形的，应当在原因消除后立即离开，抵港后及时向公安边防部门报告。"},{"i":18,"n":"第十八条","txt":"出海船舶和人员不准携带违禁物品。在海上拣拾的违禁物品，必须上交公安边防部门，不得隐匿、留用或者擅自处理。"},{"i":19,"n":"第十九条","txt":"任何船舶或者人员不准非法拦截、强行靠登、冲撞或者偷开他人船舶。"},{"i":20,"n":"第二十条","txt":"发生海事、渔事纠纷，应当依法处理，任何一方不得扣押对方人员、船舶或者船上物品。"},{"i":21,"n":"第二十一条","txt":"任何船舶或者人员未经许可，不得将外国籍和香港、澳门特别行政区以及台湾地区的船舶引航到未对上述船舶开放的港口、锚地停靠。"},{"i":22,"n":"第二十二条","txt":"严禁利用船舶进行走私、贩毒、贩运枪支弹药或者接驳、运送他人偷越国（边）境以及其他违法犯罪活动。"},{"i":23,"n":"第二十三条","txt":"经省、自治区、直辖市人民政府和有关部门批准，与外国或者香港、澳门特别行政区合资或者合作生产经营，在我国领海海域作业，并悬挂中华人民共和国国旗的船舶，应当到船籍港公安边防部门申领《出海船舶边防登记簿》，在规定的海区作业，在指定的港口停泊、上下人员以及装卸货物，接受公安边防部门的检查、管理。 随船的外国籍和香港、澳门特别行政区的船员凭公安边防部门签发的《合资船船员登陆证》上岸，随船的中国籍大陆船员持公安边防部门签发的《合资船船员登轮证》登轮作业。"},{"i":24,"n":"第二十四条","txt":"航行于内地与香港、澳门特别行政区之间的小型船舶，应当向公安边防检查部门申办《航行港澳船舶证明书》和《航行港澳小型船舶查验簿》，在指定的港口停泊、上下人员以及装卸货物。"},{"i":25,"n":"第二十五条","txt":"具有广东省和香港、澳门特别行政区双重户籍的粤港、粤澳流动渔船，应当按照广东省指定的港口入户和停泊，在规定的海域生产作业。 粤港、粤澳流动渔船，可以就近进入广东省以外沿海港口避风、维修或者补给，但不得装卸货物。船员需要上岸时，必须经当地公安边防部门批准并办理登陆手续。"},{"i":26,"n":"第二十六条","txt":"违反本规定，有下列情形之一的，对船舶负责人及其直接责任人员处二百元以下罚款或者警告： （一）未随船携带公安边防部门签发的出海证件或者持未经年度审验的证件出海的； （二）领取《出海船舶户口簿》的船舶更新改造、买卖、转让、租借、报废、灭失或者船员变更，未到公安边防部门办理出海证件变更或者注销手续的； （三）未依照规定办理船舶进出港边防签证手续的； （四）擅自容留非出海人员在船上作业、住宿的。"},{"i":27,"n":"第二十七条","txt":"违反本规定，有下列情形之一的，对船舶负责人及其直接责任人员处五百元以下罚款： （一）未申领《出海船舶户口簿》、《出海船舶边防登记簿》或者《出海船民证》擅自出海的； （二）涂改、伪造、冒用、转借出海证件的； （三）未编刷船名船号，经通知不加改正或者擅自拆换、遮盖、涂改船名船号以及悬挂活动船牌号的； （四）未经许可，私自载运非出海人员出海的。"},{"i":28,"n":"第二十八条","txt":"违反本规定，有下列情形之一的，对船舶负责人及其有关责任人员处一千元以下罚款： （一）非法进入国家禁止或者限制进入的海域或者岛屿的； （二）未经许可，将外国籍或者香港、澳门特别行政区、台湾地区的船舶引航到未对上述船舶开放的港口、锚地的； （三）擅自搭靠外国籍或者香港、澳门特别行政区以及台湾地区船舶的，或者因避险及其他不可抗力的原因被迫搭靠，事后未及时向公安边防部门报告的； （四）航行于内地与香港、澳门特别行政区之间的小型船舶擅自在非指定的港口停泊、上下人员或者装卸货物的。"},{"i":29,"n":"第二十九条","txt":"违反本规定，有下列情形之一的，对船舶负责人及其直接责任人员处五百元以上一千元以下罚款： （一）携带、隐匿、留用或者擅自处理违禁物品的； （二）非法拦截、强行靠登、冲撞或者偷开他人船舶的； （三）非法扣押他人船舶或者船上物品的。"},{"i":30,"n":"第三十条","txt":"船舶无船名船号、无船籍港、无船舶证书擅自出海从事生产、经营等活动的，依照国务院有关规定没收船舶，并可以对船主处船价二倍以下的罚款。"},{"i":31,"n":"第三十一条","txt":"本规定的处罚权限如下： （一）公安边防派出所、边防工作站或者船舶公安检查站可以裁决警告、二百元以下罚款； （二）县级（含本级）以上公安边防部门可以裁决一千元以下罚款； （三）对依照本规定第三十条作出的处罚，由地（市）级（含本级）以上公安边防部门裁决。"},{"i":32,"n":"第三十二条","txt":"被处罚人对公安边防部门作出的处罚决定不服的， 可以依法申请行政复议或者提起行政诉讼。"},{"i":33,"n":"第三十三条","txt":"违反本规定构成违反治安管理行为的，依照《中华人民共和国治安管理处罚条例》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，公安边防部门及其他有关部门应当依照国家有关法律、法规及时查处；构成犯罪的，依法追究刑事责任； （一）非法买卖、运输、携带毒品、淫秽物品的； （二）参与或者帮助他人非法出入境的； （三）进行其他违法犯罪活动的。"},{"i":35,"n":"第三十五条","txt":"公安边防部门在执行职务中，发现船舶或者人员有违反海事管理、渔政管理等行为的，有权予以制止，并移交或者通知有关部门处理。"},{"i":36,"n":"第三十六条","txt":"公安边防部门及其执法人员应当严格执行本规定，秉公执法。对滥用职权、徇私舞弊、玩忽职守的，依照有关规定给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"对违反本规定的行为，应当将违法情况记入《出海船舶户口簿》或者《出海船舶边防登记簿》内，加盖处罚单位印章。"},{"i":38,"n":"第三十八条","txt":"对我国海域内沿海船舶的治安管理，除法律、法规另有规定外，执行本规定。"}],"zhucexiaofanggongchengshiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对注册消防工程师的管理，规范注册消防工程师的执业行为，保障消防安全技术服务与管理质量，根据《中华人民共和国消防法》，制定本规定。"},{"i":2,"n":"第二条","txt":"取得注册消防工程师资格证书人员的注册、执业和继续教育及其监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称注册消防工程师，是指取得相应级别注册消防工程师资格证书并依法注册后，从事消防设施维护保养检测、消防安全评估和消防安全管理等工作的专业技术人员。"},{"i":4,"n":"第四条","txt":"注册消防工程师实行注册执业管理制度。注册消防工程师分为一级注册消防工程师和二级注册消防工程师。"},{"i":5,"n":"第五条","txt":"公安部消防局对全国注册消防工程师的注册、执业和继续教育实施指导和监督管理。 县级以上地方公安机关消防机构对本行政区域内注册消防工程师的注册、执业和继续教育实施指导和监督管理。"},{"i":6,"n":"第六条","txt":"注册消防工程师应当严格遵守有关法律、法规和国家标准、行业标准，恪守职业道德和执业准则，增强服务意识和社会责任感，不断提高专业素质和业务水平。"},{"i":7,"n":"第七条","txt":"鼓励依托消防协会成立注册消防工程师行业协会。注册消防工程师行业协会应当依法登记和开展活动，加强行业自律管理，规范执业行为，促进行业健康发展。 注册消防工程师行业协会不得从事营利性社会消防技术服务活动，不得通过制定行业规则或者其他方式妨碍公平竞争，损害他人利益和社会公共利益。"},{"i":8,"n":"第八条","txt":"取得注册消防工程师资格证书的人员，必须经过注册，方能以相应级别注册消防工程师的名义执业。 未经注册，不得以注册消防工程师的名义开展执业活动。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市公安机关消防机构（以下简称省级公安机关消防机构）是一级、二级注册消防工程师的注册审批部门。"},{"i":10,"n":"第十条","txt":"注册消防工程师的注册分为初始注册、延续注册和变更注册。"},{"i":11,"n":"第十一条","txt":"申请注册的人员，应当同时具备以下条件： （一）依法取得注册消防工程师资格证书； （二）受聘于一个消防技术服务机构或者消防安全重点单位，并担任技术负责人、项目负责人或者消防安全管理人； （三）无本规定第二十三条所列情形。"},{"i":12,"n":"第十二条","txt":"申请注册的人员，应当通过聘用单位向单位所在地（企业工商注册地）的省级或者地市级公安机关消防机构提交注册申请材料。 申请注册的人员，拟在消防技术服务机构的分支机构所在地开展执业活动的，应当通过该分支机构向其所在地的省级或者地市级公安机关消防机构提交注册申请材料。"},{"i":13,"n":"第十三条","txt":"公安机关消防机构收到注册申请材料后，对申请材料齐全、符合法定形式的，应当出具受理凭证；不予受理的，应当出具不予受理凭证并载明理由。对申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。 地市级公安机关消防机构受理注册申请后，应当在三日内将申请材料送至省级公安机关消防机构。"},{"i":14,"n":"第十四条","txt":"省级公安机关消防机构应当自受理之日起二十日内对申请人条件和注册申请材料进行审查并作出注册决定。在规定的期限内不能作出注册决定的，经省级公安机关消防机构负责人批准，可以延长十日，并应当将延长期限的理由告知申请人。"},{"i":15,"n":"第十五条","txt":"省级公安机关消防机构应当自作出注册决定之日起十日内颁发相应级别的注册证、执业印章，并向社会公告；对作出不予注册决定的，应当出具不予注册决定书并载明理由。 注册消防工程师的注册证、执业印章式样由公安部消防局统一制定，省级公安机关消防机构组织制作。"},{"i":16,"n":"第十六条","txt":"注册证、执业印章的有效期为三年，自作出注册决定之日起计算。 申请人领取一级注册消防工程师注册证、执业印章时，已经取得二级注册消防工程师注册证、执业印章的, 应当同时将二级注册消防工程师注册证、执业印章交回。"},{"i":17,"n":"第十七条","txt":"申请初始注册的，应当自取得注册消防工程师资格证书之日起一年内提出。 本规定施行前已经取得注册消防工程师资格但尚未注册的，应当在本规定施行之日起一年内提出申请。 逾期未申请初始注册的，应当参加继续教育，并在达到继续教育的要求后方可申请初始注册。"},{"i":18,"n":"第十八条","txt":"申请初始注册应当提交下列材料： （一）初始注册申请表； （二）申请人身份证明材料、注册消防工程师资格证书等复印件； （三）聘用单位消防技术服务机构资质证书副本复印件或者消防安全重点单位证明材料； （四）与聘用单位签订的劳动合同或者聘用文件复印件，社会保险证明或者人事证明复印件。 聘用单位同时申请消防技术服务机构资质的，申请人无需提供前款第三项规定的材料。 逾期申请初始注册的，还应当提交达到继续教育要求的证明材料。"},{"i":19,"n":"第十九条","txt":"注册有效期满需继续执业的，应当在注册有效期届满三个月前，按照本规定第十二条的规定申请延续注册，并提交下列材料： （一）延续注册申请表； （二）原注册证、执业印章； （三）与聘用单位签订的劳动合同或者聘用文件复印件，社会保险证明或者人事证明复印件； （四）符合本规定第二十九条第二款规定的执业业绩证明材料； （五）继续教育的证明材料。"},{"i":20,"n":"第二十条","txt":"注册消防工程师在注册有效期内发生下列情形之一的，应当按照本规定第十二条的规定申请变更注册： （一）变更聘用单位的； （二）聘用单位名称变更的； （三）注册消防工程师姓名变更的。"},{"i":21,"n":"第二十一条","txt":"申请变更注册，应当提交变更注册申请表、原注册证和执业印章，以及下列变更事项证明材料： （一）注册消防工程师变更聘用单位的，提交新聘用单位的消防技术服务机构资质证书副本复印件或者消防安全重点单位证明材料，与新聘用单位签订的劳动合同或者聘用文件复印件，社会保险证明或者人事证明复印件，与原聘用单位解除（终止）工作关系证明； （二）注册消防工程师聘用单位名称变更的，提交变更后的单位工商营业执照等证明文件复印件； （三）注册消防工程师姓名变更的，提交户籍信息变更材料。 变更注册后，有效期仍延续原注册有效期。原注册有效期届满在半年以内的，可以同时提出延续注册申请；准予延续的，注册有效期重新计算。"},{"i":22,"n":"第二十二条","txt":"注册消防工程师在申请变更注册之日起，至注册审批部门准予其变更注册之前不得执业。"},{"i":23,"n":"第二十三条","txt":"申请人有下列情形之一的，不予注册： （一）不具有完全民事行为能力或者年龄超过70周岁的； （二）申请在非消防技术服务机构、非消防安全重点单位，或者两个以上消防技术服务机构、消防安全重点单位注册的； （三）刑事处罚尚未执行完毕，或者因违法执业行为受到刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满五年的； （四）未达到继续教育、执业业绩要求的； （五）因存在本规定第五十条违法行为被撤销注册，自撤销注册之日起至申请注册之日止不满三年的； （六）因存在本规定第五十五条第二项、第五十六条、第五十七条违法执业行为之一被注销注册，自注销注册之日起至申请注册之日止不满三年的； （七）因存在本规定第五十五条第一项、第三项违法执业行为之一被注销注册，自注销注册之日起至申请注册之日止不满一年的； （八）因违法执业行为受到公安机关消防机构行政处罚，未履行完毕的。"},{"i":24,"n":"第二十四条","txt":"注册消防工程师注册证、执业印章遗失的，应当及时向原注册审批部门备案。 注册消防工程师注册证或者执业印章遗失、污损需要补办、更换的，应当持聘用单位和本人共同出具的遗失说明，或者污损的原注册证、执业印章，向原注册审批部门申请补办、更换。原注册审批部门应当自受理之日起十日内办理完毕。补办、更换的注册证、执业印章有效期延续原注册有效期。"},{"i":25,"n":"第二十五条","txt":"注册证、执业印章是注册消防工程师的执业凭证，由注册消防工程师本人保管、使用。"},{"i":26,"n":"第二十六条","txt":"一级注册消防工程师可以在全国范围内执业；二级注册消防工程师可以在注册所在省、自治区、直辖市范围内执业。"},{"i":27,"n":"第二十七条","txt":"一级注册消防工程师的执业范围包括： （一）消防技术咨询与消防安全评估； （二）消防安全管理与消防技术培训； （三）消防设施维护保养检测（含灭火器维修）； （四）消防安全监测与检查； （五）火灾事故技术分析； （六）公安部或者省级公安机关规定的其他消防安全技术工作。"},{"i":28,"n":"第二十八条","txt":"二级注册消防工程师的执业范围包括： （一）除100米以上公共建筑、大型的人员密集场所、大型的危险化学品单位外的火灾高危单位消防安全评估； （二）除250米以上公共建筑、大型的危险化学品单位外的消防安全管理； （三）单体建筑面积4万平方米以下建筑的消防设施维护保养检测（含灭火器维修）； （四）消防安全监测与检查； （五）公安部或者省级公安机关规定的其他消防安全技术工作。 省级公安机关消防机构应当结合实际，根据上款规定确定本地区二级注册消防工程师的具体执业范围。"},{"i":29,"n":"第二十九条","txt":"注册消防工程师的执业范围应当与其聘用单位业务范围和本人注册级别相符合，本人的执业范围不得超越其聘用单位的业务范围。 受聘于消防技术服务机构的注册消防工程师，每个注册有效期应当至少参与完成3个消防技术服务项目；受聘于消防安全重点单位的注册消防工程师，一个年度内应当至少签署1个消防安全技术文件。 注册消防工程师的聘用单位应当加强对本单位注册消防工程师的管理，对其执业活动依法承担法律责任。"},{"i":30,"n":"第三十条","txt":"下列消防安全技术文件应当以注册消防工程师聘用单位的名义出具，并由担任技术负责人、项目负责人或者消防安全管理人的注册消防工程师签名，加盖执业印章： （一）消防技术咨询、消防安全评估、火灾事故技术分析等书面结论文件； （二）消防安全重点单位年度消防工作综合报告； （三）消防设施维护保养检测书面结论文件； （四）灭火器维修合格证； （五）法律、法规规定的其他消防安全技术文件。 修改经注册消防工程师签名盖章的消防安全技术文件，应当由原注册消防工程师进行；因特殊情况，原注册消防工程师不能进行修改的，应当由其他相应级别的注册消防工程师修改，并签名、加盖执业盖章，对修改部分承担相应的法律责任。"},{"i":31,"n":"第三十一条","txt":"注册消防工程师享有下列权利： （一）使用注册消防工程师称谓； （二）保管和使用注册证和执业印章； （三）在规定的范围内开展执业活动； （四）对违反相关法律、法规和国家标准、行业标准的行为提出劝告，拒绝签署违反国家标准、行业标准的消防安全技术文件； （五）参加继续教育； （六）依法维护本人的合法执业权利。"},{"i":32,"n":"第三十二条","txt":"注册消防工程师应当履行下列义务： （一）遵守和执行法律、法规和国家标准、行业标准； （二）接受继续教育，不断提高消防安全技术能力； （三）保证执业活动质量，承担相应的法律责任； （四）保守知悉的国家秘密和聘用单位的商业、技术秘密。"},{"i":33,"n":"第三十三条","txt":"注册消防工程师不得有下列行为： （一）同时在两个以上消防技术服务机构，或者消防安全重点单位执业; （二）以个人名义承接执业业务、开展执业活动； （三）在聘用单位出具的虚假、失实消防安全技术文件上签名、加盖执业印章； （四）变造、倒卖、出租、出借，或者以其他形式转让资格证书、注册证或者执业印章； （五）超出本人执业范围或者聘用单位业务范围开展执业活动； （六）不按照国家标准、行业标准开展执业活动，减少执业活动项目内容、数量，或者降低执业活动质量； （七）违反法律、法规规定的其他行为。"},{"i":34,"n":"第三十四条","txt":"注册消防工程师在每个注册有效期内应当达到继续教育要求。具有注册消防工程师资格证书的非注册人员，应当持续参加继续教育，并达到继续教育要求。"},{"i":35,"n":"第三十五条","txt":"公安部消防局统一管理全国注册消防工程师的继续教育工作，组织制定一级注册消防工程师的继续教育规划和计划。 省级公安机关消防机构负责本行政区域内一级、二级注册消防工程师继续教育的组织实施和管理，组织制定二级注册消防工程师的继续教育规划和计划。省级公安机关消防机构可以委托教育培训机构实施继续教育。"},{"i":36,"n":"第三十六条","txt":"注册消防工程师继续教育可以按照注册级别，采取集中面授、网络教学等多种形式进行。"},{"i":37,"n":"第三十七条","txt":"对达到继续教育要求的注册消防工程师，实施继续教育培训的机构应当出具证明材料。"},{"i":38,"n":"第三十八条","txt":"县级以上公安机关消防机构依照有关法律、法规和本规定，对本行政区域内注册消防工程师的执业活动实施监督管理。 注册消防工程师及其聘用单位对公安机关消防机构依法进行的监督管理应当协助与配合，不得拒绝或者阻挠。"},{"i":39,"n":"第三十九条","txt":"省级公安机关消防机构应当制定对注册消防工程师执业活动的监督抽查计划。县级以上地方公安机关消防机构应当根据监督抽查计划，结合日常消防监督检查工作，对注册消防工程师的执业活动实施监督抽查。 公安机关消防机构对注册消防工程师的执业活动实施监督抽查时，检查人员不得少于两人，并应当表明执法身份。"},{"i":40,"n":"第四十条","txt":"公安机关消防机构对发现的注册消防工程师违法执业行为，应当责令立即改正或者限期改正，并依法查处。 公安机关消防机构对注册消防工程师作出处理决定后，应当在作出处理决定之日起七日内将违法执业事实、处理结果或者处理建议抄告原注册审批部门。原注册审批部门收到抄告后，应当依法作出责令停止执业、注销注册或者吊销注册证等处理。"},{"i":41,"n":"第四十一条","txt":"公安机关消防机构工作人员滥用职权、玩忽职守作出准予注册决定的，作出决定的公安机关消防机构或者其上级公安机关消防机构可以撤销注册。"},{"i":42,"n":"第四十二条","txt":"注册消防工程师有下列情形之一的，注册审批部门应当予以注销注册，并将其注册证、执业印章收回或者公告作废： （一）不具有完全民事行为能力或者年龄超过70周岁的; （二）申请注销注册或者注册有效期满超过三个月未延续注册的； （三）被撤销注册、吊销注册证的； （四）在一个注册有效期内有本规定第五十五条第二项、第五十六条、第五十七条所列情形一次以上，或者第五十五条第一项、第三项所列情形两次以上的； （五）执业期间受到刑事处罚的； （六）聘用单位破产、解散、被撤销，或者被注销消防技术服务机构资质的； （七）与聘用单位解除（终止）工作关系超过三个月的； （八）法律、行政法规规定的其他情形。 被注销注册的人员在具备初始注册条件后，可以重新申请初始注册。"},{"i":43,"n":"第四十三条","txt":"公安机关消防机构实施监督检查时，有权采取下列措施： （一）查看注册消防工程师的注册证、执业印章、签署的消防安全技术文件和社会保险证明； （二）查阅注册消防工程师聘用单位、服务单位相关资料，询问有关事项； （三）实地抽查注册消防工程师执业活动情况，核查执业活动质量; （四）法律、行政法规规定的其他措施。"},{"i":44,"n":"第四十四条","txt":"公安机关消防机构实施监督检查时，应当重点抽查下列情形： （一）注册消防工程师聘用单位是否符合要求； （二）注册消防工程师是否具备注册证、执业印章； （三）是否存在违反本规定第三十条、第三十三条规定的情形。"},{"i":45,"n":"第四十五条","txt":"公安机关消防机构对注册消防工程师执业活动中的违法行为除给予行政处罚外，实行违法行为累积记分制度。 累积记分管理的具体办法，由公安部制定。"},{"i":46,"n":"第四十六条","txt":"注册消防工程师聘用单位应当建立本单位注册消防工程师的执业档案，并确保执业档案真实、准确、完整。"},{"i":47,"n":"第四十七条","txt":"任何单位和个人都有权对注册消防工程师执业活动中的违法行为和公安机关消防机构及其工作人员监督管理工作中的违法行为进行举报、投诉。 公安机关消防机构接到举报、投诉后，应当及时进行核查、处理。"},{"i":48,"n":"第四十八条","txt":"注册消防工程师及其聘用单位违反本规定的行为，法律、法规已经规定法律责任的，依照有关规定处理。"},{"i":49,"n":"第四十九条","txt":"隐瞒有关情况或者提供虚假材料申请注册的，公安机关消防机构不予受理或者不予许可，申请人在一年内不得再次申请注册；聘用单位为申请人提供虚假注册申请材料的，同时对聘用单位处一万元以上三万元以下罚款。"},{"i":50,"n":"第五十条","txt":"申请人以欺骗、贿赂等不正当手段取得注册消防工程师资格注册的，原注册审批部门应当撤销其注册，并处一万元以下罚款；申请人在三年内不得再次申请注册。"},{"i":51,"n":"第五十一条","txt":"未经注册擅自以注册消防工程师名义执业，或者被依法注销注册后继续执业的，责令停止违法活动，处一万元以上三万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"注册消防工程师有需要变更注册的情形，未经注册审批部门准予变更注册而继续执业的，责令改正，处一千元以上一万元以下罚款。"},{"i":53,"n":"第五十三条","txt":"注册消防工程师聘用单位出具的消防安全技术文件，未经注册消防工程师签名或者加盖执业印章的，责令改正，处一千元以上一万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"注册消防工程师未按照国家标准、行业标准开展执业活动，减少执业活动项目内容、数量，或者执业活动质量不符合国家标准、行业标准的，责令改正，处一千元以上一万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"注册消防工程师有下列行为之一的，责令改正，处一万元以上二万元以下罚款： （一）以个人名义承接执业业务、开展执业活动的； （二）变造、倒卖、出租、出借或者以其他形式转让资格证书、注册证、执业印章的； （三）超出本人执业范围或者聘用单位业务范围开展执业活动的。"},{"i":56,"n":"第五十六条","txt":"注册消防工程师同时在两个以上消防技术服务机构或者消防安全重点单位执业的，依据《社会消防技术服务管理规定》第四十七条第二款的规定处罚。"},{"i":57,"n":"第五十七条","txt":"注册消防工程师在聘用单位出具的虚假、失实消防安全技术文件上签名或者加盖执业印章的，依据《中华人民共和国消防法》第六十九条的规定处罚。"},{"i":58,"n":"第五十八条","txt":"本规定规定的行政处罚，除第五十条、第五十七条另有规定的外，由违法行为地的县级以上公安机关消防机构决定。"},{"i":59,"n":"第五十九条","txt":"注册消防工程师对公安机关消防机构在注册消防工程师监督管理中作出的具体行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":60,"n":"第六十条","txt":"公安机关消防机构工作人员有下列行为之一，尚不构成犯罪的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）超越法定职权、违反法定程序或者对不符合法定条件的申请人准予注册的； （二）对符合法定条件的申请人不予受理、注册或者拖延办理的； （三）利用职务上的便利，索取或者收受他人财物或者谋取不正当利益的； （四）不依法履行监督管理职责或者发现违法行为不依法处理的。"},{"i":61,"n":"第六十一条","txt":"本规定中的“日”是指工作日，不含法定节假日；“以上”、“以下”包括本数、本级。"},{"i":62,"n":"第六十二条","txt":"本规定自2017年10月1日起施行。"}],"xiaofangchanpinjianduguanliguiding-2":[{"i":1,"n":"第一条","txt":"为了加强消防产品监督管理，提高消防产品质量，依据《中华人民共和国消防法》、《中华人民共和国产品质量法》、《中华人民共和国认证认可条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售、使用消防产品，以及对消防产品质量实施监督管理，适用本规定。 本规定所称消防产品是指专门用于火灾预防、灭火救援和火灾防护、避难、逃生的产品。"},{"i":3,"n":"第三条","txt":"消防产品必须符合国家标准；没有国家标准的，必须符合行业标准。未制定国家标准、行业标准的，应当符合消防安全要求，并符合保障人体健康、人身财产安全的要求和企业标准。"},{"i":4,"n":"第四条","txt":"国家质量监督检验检疫总局、国家工商行政管理总局和公安部按照各自职责对生产、流通和使用领域的消防产品质量实施监督管理。 县级以上地方质量监督部门、工商行政管理部门和公安机关消防机构按照各自职责对本行政区域内生产、流通和使用领域的消防产品质量实施监督管理。"},{"i":5,"n":"第五条","txt":"依法实行强制性产品认证的消防产品，由具有法定资质的认证机构按照国家标准、行业标准的强制性要求认证合格后，方可生产、销售、使用。 消防产品认证机构应当将消防产品强制性认证有关信息报国家认证认可监督管理委员会和公安部消防局。 实行强制性产品认证的消防产品目录由国家质量监督检验检疫总局、国家认证认可监督管理委员会会同公安部制定并公布，消防产品认证基本规范、认证规则由国家认证认可监督管理委员会制定并公布。"},{"i":6,"n":"第六条","txt":"国家认证认可监督管理委员会应当按照《中华人民共和国认证认可条例》的有关规定，经评审并征求公安部消防局意见后，指定从事消防产品强制性产品认证活动的机构以及与认证有关的检查机构、实验室，并向社会公布。"},{"i":7,"n":"第七条","txt":"消防产品认证机构及其工作人员应当按照有关规定从事认证活动，客观公正地出具认证结论，对认证结果负责。不得增加、减少、遗漏或者变更认证基本规范、认证规则规定的程序。"},{"i":8,"n":"第八条","txt":"从事消防产品强制性产品认证活动的检查机构、实验室及其工作人员，应当确保检查、检测结果真实、准确，并对检查、检测结论负责。"},{"i":9,"n":"第九条","txt":"新研制的尚未制定国家标准、行业标准的消防产品，经消防产品技术鉴定机构技术鉴定符合消防安全要求的，方可生产、销售、使用。消防安全要求由公安部制定。 消防产品技术鉴定机构应当具备国家认证认可监督管理委员会依法认定的向社会出具具有证明作用的数据和结果的消防产品实验室资格或者从事消防产品合格评定活动的认证机构资格。消防产品技术鉴定机构名录由公安部公布。 公安机关消防机构和认证认可监督管理部门按照各自职责对消防产品技术鉴定机构进行监督。 公安部会同国家认证认可监督管理委员会参照消防产品认证机构和实验室管理工作规则，制定消防产品技术鉴定工作程序和规范。"},{"i":10,"n":"第十条","txt":"消防产品技术鉴定应当遵守以下程序： （一）委托人向消防产品技术鉴定机构提出书面委托，并提供有关文件资料； （二）消防产品技术鉴定机构依照有关规定对文件资料进行审核； （三）文件资料经审核符合要求的，消防产品技术鉴定机构按照消防安全要求和有关规定，组织实施消防产品型式检验和工厂检查； （四）经鉴定认为消防产品符合消防安全要求的，技术鉴定机构应当在接受委托之日起九十日内颁发消防产品技术鉴定证书，并将消防产品有关信息报公安部消防局；认为不符合消防安全要求的，应当书面通知委托人，并说明理由。 消防产品检验时间不计入技术鉴定时限。"},{"i":11,"n":"第十一条","txt":"消防产品技术鉴定机构及其工作人员应当按照有关规定开展技术鉴定工作，对技术鉴定结果负责。"},{"i":12,"n":"第十二条","txt":"消防产品技术鉴定证书有效期为三年。 有效期届满，生产者需要继续生产消防产品的，应当在有效期届满前的六个月内，依照本规定第十条的规定，重新申请消防产品技术鉴定证书。"},{"i":13,"n":"第十三条","txt":"在消防产品技术鉴定证书有效期内，消防产品的生产条件、检验手段、生产技术或者工艺发生变化，对性能产生重大影响的，生产者应当重新委托消防产品技术鉴定。"},{"i":14,"n":"第十四条","txt":"在消防产品技术鉴定证书有效期内，相关消防产品的国家标准、行业标准颁布施行的，生产者应当保证生产的消防产品符合国家标准、行业标准。 前款规定的消防产品被列入强制性产品认证目录的，应当按照本规定实施强制性产品认证。未列入强制性产品认证目录的，在技术鉴定证书有效期届满后，不再实行技术鉴定。"},{"i":15,"n":"第十五条","txt":"消防产品技术鉴定机构应当对其鉴定合格的产品实施有效的跟踪调查，鉴定合格的产品不能持续符合技术鉴定要求的，技术鉴定机构应当暂停其使用直至撤销鉴定证书，并予公布。"},{"i":16,"n":"第十六条","txt":"经强制性产品认证合格或者技术鉴定合格的消防产品，公安部消防局应当予以公布。"},{"i":17,"n":"第十七条","txt":"消防产品生产者应当对其生产的消防产品质量负责，建立有效的质量管理体系，保持消防产品的生产条件，保证产品质量、标志、标识符合相关法律法规和标准要求。不得生产应当获得而未获得市场准入资格的消防产品、不合格的消防产品或者国家明令淘汰的消防产品。 消防产品生产者应当建立消防产品销售流向登记制度，如实记录产品名称、批次、规格、数量、销售去向等内容。"},{"i":18,"n":"第十八条","txt":"消防产品销售者应当建立并执行进货检查验收制度，验明产品合格证明和其他标识，不得销售应当获得而未获得市场准入资格的消防产品、不合格的消防产品或者国家明令淘汰的消防产品。 销售者应当采取措施，保持销售产品的质量。"},{"i":19,"n":"第十九条","txt":"消防产品使用者应当查验产品合格证明、产品标识和有关证书，选用符合市场准入的、合格的消防产品。 建设工程设计单位在设计中选用的消防产品，应当注明产品规格、性能等技术指标，其质量要求应当符合国家标准、行业标准。当需要选用尚未制定国家标准、行业标准的消防产品时，应当选用经技术鉴定合格的消防产品。 建设工程施工企业应当按照工程设计要求、施工技术标准、合同的约定和消防产品有关技术标准，对进场的消防产品进行现场检查或者检验，如实记录进货来源、名称、批次、规格、数量等内容；现场检查或者检验不合格的，不得安装。现场检查记录或者检验报告应当存档备查。建设工程施工企业应当建立安装质量管理制度，严格执行有关标准、施工规范和相关要求，保证消防产品的安装质量。 工程监理单位应当依照法律、行政法规及有关技术标准、设计文件和建设工程承包合同对建设工程使用的消防产品的质量及其安装质量实施监督。 机关、团体、企业、事业"},{"i":20,"n":"第二十条","txt":"质量监督部门、工商行政管理部门依据《中华人民共和国产品质量法》以及相关规定对生产领域、流通领域的消防产品质量进行监督检查。"},{"i":21,"n":"第二十一条","txt":"公安机关消防机构对使用领域的消防产品质量进行监督检查，实行日常监督检查和监督抽查相结合的方式。"},{"i":22,"n":"第二十二条","txt":"公安机关消防机构在消防监督检查和建设工程消防监督管理工作中，对使用领域的消防产品质量进行日常监督检查，按照公安部《消防监督检查规定》、《建设工程消防监督管理规定》执行。"},{"i":23,"n":"第二十三条","txt":"公安机关消防机构对使用领域的消防产品质量进行专项监督抽查，由省级以上公安机关消防机构制定监督抽查计划，由县级以上地方公安机关消防机构具体实施。"},{"i":24,"n":"第二十四条","txt":"公安机关消防机构对使用领域的消防产品质量进行监督抽查，应当检查下列内容： （一）列入强制性产品认证目录的消防产品是否具备强制性产品认证证书，新研制的尚未制定国家标准、行业标准的消防产品是否具备技术鉴定证书； （二）按照强制性国家标准或者行业标准的规定，应当进行型式检验和出厂检验的消防产品，是否具备型式检验合格和出厂检验合格的证明文件； （三）消防产品的外观标志、规格型号、结构部件、材料、性能参数、生产厂名、厂址与产地等是否符合有关规定； （四）消防产品的关键性能是否符合消防产品现场检查判定规则的要求； （五）法律、行政法规规定的其他内容。"},{"i":25,"n":"第二十五条","txt":"公安机关消防机构实施消防产品质量监督抽查时，检查人员不得少于两人，并应当出示执法身份证件。 实施消防产品质量监督抽查应当填写检查记录，由检查人员、被检查单位管理人员签名；被检查单位管理人员对检查记录有异议或者拒绝签名的，检查人员应当在检查记录中注明。"},{"i":26,"n":"第二十六条","txt":"公安机关消防机构应当根据本规定和消防产品现场检查判定规则，实施现场检查判定。对现场检查判定为不合格的，应当在三日内将判定结论送达被检查人。被检查人对消防产品现场检查判定结论有异议的，公安机关消防机构应当在五日内依照有关规定将样品送符合法定条件的产品质量检验机构进行监督检验，并自收到检验结果之日起三日内，将检验结果告知被检查人。 检验抽取的样品由被检查人无偿供给，其数量不得超过检验的合理需要。检验费用在规定经费中列支，不得向被检查人收取。"},{"i":27,"n":"第二十七条","txt":"被检查人对公安机关消防机构抽样送检的产品检验结果有异议的，可以自收到检验结果之日起五日内向实施监督检查的公安机关消防机构提出书面复检申请。 公安机关消防机构受理复检申请，应当当场出具受理凭证。 公安机关消防机构受理复检申请后，应当在五日内将备用样品送检，自收到复检结果之日起三日内，将复检结果告知申请人。 复检申请以一次为限。复检合格的，费用列入监督抽查经费；不合格的，费用由申请人承担。"},{"i":28,"n":"第二十八条","txt":"质量监督部门、工商行政管理部门接到对消防产品质量问题的举报投诉，应当按职责及时依法处理。对不属于本部门职责范围的，应当及时移交或者书面通报有关部门。 公安机关消防机构接到对消防产品质量问题的举报投诉，应当及时受理、登记，并按照公安部《公安机关办理行政案件程序规定》的相关规定和本规定中消防产品质量监督检查程序处理。 公安机关消防机构对举报投诉的消防产品质量问题进行核查后，对消防安全违法行为应当依法处理。核查、处理情况应当在三日内告知举报投诉人；无法告知的，应当在受理登记中注明。"},{"i":29,"n":"第二十九条","txt":"公安机关消防机构发现使用依法应当获得市场准入资格而未获得准入资格的消防产品或者不合格的消防产品、国家明令淘汰的消防产品等使用领域消防产品质量违法行为，应当依法责令限期改正。 公安机关消防机构应当在收到当事人复查申请或者责令限期改正期限届满之日起三日内进行复查。复查应当填写记录。"},{"i":30,"n":"第三十条","txt":"公安机关消防机构对发现的使用领域消防产品质量违法行为，应当依法查处，并及时将有关情况书面通报同级质量监督部门、工商行政管理部门；质量监督部门、工商行政管理部门应当对生产者、销售者依法及时查处。"},{"i":31,"n":"第三十一条","txt":"质量监督部门、工商行政管理部门和公安机关消防机构应当按照有关规定，向社会公布消防产品质量监督检查情况、重大消防产品质量违法行为的行政处罚情况等信息。"},{"i":32,"n":"第三十二条","txt":"任何单位和个人在接受质量监督部门、工商行政管理部门和公安机关消防机构依法开展的消防产品质量监督检查时，应当如实提供有关情况和资料。 任何单位和个人不得擅自转移、变卖、隐匿或者损毁被采取强制措施的物品，不得拒绝依法进行的监督检查。"},{"i":33,"n":"第三十三条","txt":"生产、销售不合格的消防产品或者国家明令淘汰的消防产品的，由质量监督部门或者工商行政管理部门依照《中华人民共和国产品质量法》的规定从重处罚。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，由公安机关消防机构责令改正，依照《中华人民共和国消防法》第五十九条处罚： （一）建设单位要求建设工程施工企业使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的； （二）建设工程设计单位选用不符合市场准入的消防产品，或者国家明令淘汰的消防产品进行消防设计的； （三）建设工程施工企业安装不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的； （四）工程监理单位与建设单位或者建设工程施工企业串通，弄虚作假，安装、使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的。"},{"i":35,"n":"第三十五条","txt":"消防产品技术鉴定机构出具虚假文件的，由公安机关消防机构责令改正，依照《中华人民共和国消防法》第六十九条处罚。"},{"i":36,"n":"第三十六条","txt":"人员密集场所使用不符合市场准入的消防产品的，由公安机关消防机构责令限期改正；逾期不改正的，依照《中华人民共和国消防法》第六十五条第二款处罚。 非人员密集场所使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的，由公安机关消防机构责令限期改正；逾期不改正的，对非经营性场所处五百元以上一千元以下罚款，对经营性场所处五千元以上一万元以下罚款，并对直接负责的主管人员和其他直接责任人员处五百元以下罚款。"},{"i":37,"n":"第三十七条","txt":"公安机关消防机构及其工作人员进行消防产品监督执法，应当严格遵守廉政规定，坚持公正、文明执法，自觉接受单位和公民的监督。 公安机关及其工作人员不得指定消防产品的品牌、销售单位，不得参与或者干预建设工程消防产品的招投标活动，不得接受被检查单位、个人的财物或者其他不正当利益。"},{"i":38,"n":"第三十八条","txt":"质量监督部门、工商行政管理部门、公安机关消防机构工作人员在消防产品监督管理中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":39,"n":"第三十九条","txt":"违反本规定，构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"消防产品目录由公安部消防局制定并公布。"},{"i":41,"n":"第四十一条","txt":"消防产品进出口检验监管，由出入境检验检疫部门按照有关规定执行。 消防产品属于《中华人民共和国特种设备安全监察条例》规定的特种设备的，还应当遵守特种设备安全监察有关规定。"},{"i":42,"n":"第四十二条","txt":"本规定中的“三日”、“五日”是指工作日，不含法定节假日。"},{"i":43,"n":"第四十三条","txt":"公安机关消防机构执行本规定所需要的法律文书式样，由公安部制定。"},{"i":44,"n":"第四十四条","txt":"本规定自2013年1月1日起施行。"}],"xiaofangchanpinjianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强消防产品监督管理，提高消防产品质量，依据《中华人民共和国消防法》、《中华人民共和国产品质量法》、《中华人民共和国认证认可条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售、使用消防产品，以及对消防产品质量实施监督管理，适用本规定。 本规定所称消防产品是指专门用于火灾预防、灭火救援和火灾防护、避难、逃生的产品。"},{"i":3,"n":"第三条","txt":"消防产品必须符合国家标准；没有国家标准的，必须符合行业标准。未制定国家标准、行业标准的，应当符合消防安全要求，并符合保障人体健康、人身财产安全的要求和企业标准。"},{"i":4,"n":"第四条","txt":"国家质量监督检验检疫总局、国家工商行政管理总局和公安部按照各自职责对生产、流通和使用领域的消防产品质量实施监督管理。 县级以上地方质量监督部门、工商行政管理部门和公安机关消防机构按照各自职责对本行政区域内生产、流通和使用领域的消防产品质量实施监督管理。"},{"i":5,"n":"第五条","txt":"依法实行强制性产品认证的消防产品，由具有法定资质的认证机构按照国家标准、行业标准的强制性要求认证合格后，方可生产、销售、使用。 消防产品认证机构应当将消防产品强制性认证有关信息报国家认证认可监督管理委员会和公安部消防局。 实行强制性产品认证的消防产品目录由国家质量监督检验检疫总局、国家认证认可监督管理委员会会同公安部制定并公布，消防产品认证基本规范、认证规则由国家认证认可监督管理委员会制定并公布。"},{"i":6,"n":"第六条","txt":"国家认证认可监督管理委员会应当按照《中华人民共和国认证认可条例》的有关规定，经评审并征求公安部消防局意见后，指定从事消防产品强制性产品认证活动的机构以及与认证有关的检查机构、实验室，并向社会公布。"},{"i":7,"n":"第七条","txt":"消防产品认证机构及其工作人员应当按照有关规定从事认证活动，客观公正地出具认证结论，对认证结果负责。不得增加、减少、遗漏或者变更认证基本规范、认证规则规定的程序。"},{"i":8,"n":"第八条","txt":"从事消防产品强制性产品认证活动的检查机构、实验室及其工作人员，应当确保检查、检测结果真实、准确，并对检查、检测结论负责。"},{"i":9,"n":"第九条","txt":"新研制的尚未制定国家标准、行业标准的消防产品，经消防产品技术鉴定机构技术鉴定符合消防安全要求的，方可生产、销售、使用。消防安全要求由公安部制定。 消防产品技术鉴定机构应当具备国家认证认可监督管理委员会依法认定的向社会出具具有证明作用的数据和结果的消防产品实验室资格或者从事消防产品合格评定活动的认证机构资格。消防产品技术鉴定机构名录由公安部公布。 公安机关消防机构和认证认可监督管理部门按照各自职责对消防产品技术鉴定机构进行监督。 公安部会同国家认证认可监督管理委员会参照消防产品认证机构和实验室管理工作规则，制定消防产品技术鉴定工作程序和规范。"},{"i":10,"n":"第十条","txt":"消防产品技术鉴定应当遵守以下程序： （一）委托人向消防产品技术鉴定机构提出书面委托，并提供有关文件资料； （二）消防产品技术鉴定机构依照有关规定对文件资料进行审核； （三）文件资料经审核符合要求的，消防产品技术鉴定机构按照消防安全要求和有关规定，组织实施消防产品型式检验和工厂检查； （四）经鉴定认为消防产品符合消防安全要求的，技术鉴定机构应当在接受委托之日起九十日内颁发消防产品技术鉴定证书，并将消防产品有关信息报公安部消防局；认为不符合消防安全要求的，应当书面通知委托人，并说明理由。 消防产品检验时间不计入技术鉴定时限。"},{"i":11,"n":"第十一条","txt":"消防产品技术鉴定机构及其工作人员应当按照有关规定开展技术鉴定工作，对技术鉴定结果负责。"},{"i":12,"n":"第十二条","txt":"消防产品技术鉴定证书有效期为三年。 有效期届满，生产者需要继续生产消防产品的，应当在有效期届满前的六个月内，依照本规定第十条的规定，重新申请消防产品技术鉴定证书。"},{"i":13,"n":"第十三条","txt":"在消防产品技术鉴定证书有效期内，消防产品的生产条件、检验手段、生产技术或者工艺发生变化，对性能产生重大影响的，生产者应当重新委托消防产品技术鉴定。"},{"i":14,"n":"第十四条","txt":"在消防产品技术鉴定证书有效期内，相关消防产品的国家标准、行业标准颁布施行的，生产者应当保证生产的消防产品符合国家标准、行业标准。 前款规定的消防产品被列入强制性产品认证目录的，应当按照本规定实施强制性产品认证。未列入强制性产品认证目录的，在技术鉴定证书有效期届满后，不再实行技术鉴定。"},{"i":15,"n":"第十五条","txt":"消防产品技术鉴定机构应当对其鉴定合格的产品实施有效的跟踪调查，鉴定合格的产品不能持续符合技术鉴定要求的，技术鉴定机构应当暂停其使用直至撤销鉴定证书，并予公布。"},{"i":16,"n":"第十六条","txt":"经强制性产品认证合格或者技术鉴定合格的消防产品，公安部消防局应当予以公布。"},{"i":17,"n":"第十七条","txt":"消防产品生产者应当对其生产的消防产品质量负责，建立有效的质量管理体系，保持消防产品的生产条件，保证产品质量、标志、标识符合相关法律法规和标准要求。不得生产应当获得而未获得市场准入资格的消防产品、不合格的消防产品或者国家明令淘汰的消防产品。 消防产品生产者应当建立消防产品销售流向登记制度，如实记录产品名称、批次、规格、数量、销售去向等内容。"},{"i":18,"n":"第十八条","txt":"消防产品销售者应当建立并执行进货检查验收制度，验明产品合格证明和其他标识，不得销售应当获得而未获得市场准入资格的消防产品、不合格的消防产品或者国家明令淘汰的消防产品。 销售者应当采取措施，保持销售产品的质量。"},{"i":19,"n":"第十九条","txt":"消防产品使用者应当查验产品合格证明、产品标识和有关证书，选用符合市场准入的、合格的消防产品。 建设工程设计单位在设计中选用的消防产品，应当注明产品规格、性能等技术指标，其质量要求应当符合国家标准、行业标准。当需要选用尚未制定国家标准、行业标准的消防产品时，应当选用经技术鉴定合格的消防产品。 建设工程施工企业应当按照工程设计要求、施工技术标准、合同的约定和消防产品有关技术标准，对进场的消防产品进行现场检查或者检验，如实记录进货来源、名称、批次、规格、数量等内容；现场检查或者检验不合格的，不得安装。现场检查记录或者检验报告应当存档备查。建设工程施工企业应当建立安装质量管理制度，严格执行有关标准、施工规范和相关要求，保证消防产品的安装质量。 工程监理单位应当依照法律、行政法规及有关技术标准、设计文件和建设工程承包合同对建设工程使用的消防产品的质量及其安装质量实施监督。 机关、团体、企业、事业"},{"i":20,"n":"第二十条","txt":"质量监督部门、工商行政管理部门依据《中华人民共和国产品质量法》以及相关规定对生产领域、流通领域的消防产品质量进行监督检查。"},{"i":21,"n":"第二十一条","txt":"公安机关消防机构对使用领域的消防产品质量进行监督检查，实行日常监督检查和监督抽查相结合的方式。"},{"i":22,"n":"第二十二条","txt":"公安机关消防机构在消防监督检查和建设工程消防监督管理工作中，对使用领域的消防产品质量进行日常监督检查，按照公安部《消防监督检查规定》、《建设工程消防监督管理规定》执行。"},{"i":23,"n":"第二十三条","txt":"公安机关消防机构对使用领域的消防产品质量进行专项监督抽查，由省级以上公安机关消防机构制定监督抽查计划，由县级以上地方公安机关消防机构具体实施。"},{"i":24,"n":"第二十四条","txt":"公安机关消防机构对使用领域的消防产品质量进行监督抽查，应当检查下列内容： （一）列入强制性产品认证目录的消防产品是否具备强制性产品认证证书，新研制的尚未制定国家标准、行业标准的消防产品是否具备技术鉴定证书； （二）按照强制性国家标准或者行业标准的规定，应当进行型式检验和出厂检验的消防产品，是否具备型式检验合格和出厂检验合格的证明文件； （三）消防产品的外观标志、规格型号、结构部件、材料、性能参数、生产厂名、厂址与产地等是否符合有关规定； （四）消防产品的关键性能是否符合消防产品现场检查判定规则的要求； （五）法律、行政法规规定的其他内容。"},{"i":25,"n":"第二十五条","txt":"公安机关消防机构实施消防产品质量监督抽查时，检查人员不得少于两人，并应当出示执法身份证件。 实施消防产品质量监督抽查应当填写检查记录，由检查人员、被检查单位管理人员签名；被检查单位管理人员对检查记录有异议或者拒绝签名的，检查人员应当在检查记录中注明。"},{"i":26,"n":"第二十六条","txt":"公安机关消防机构应当根据本规定和消防产品现场检查判定规则，实施现场检查判定。对现场检查判定为不合格的，应当在三日内将判定结论送达被检查人。被检查人对消防产品现场检查判定结论有异议的，公安机关消防机构应当在五日内依照有关规定将样品送符合法定条件的产品质量检验机构进行监督检验，并自收到检验结果之日起三日内，将检验结果告知被检查人。 检验抽取的样品由被检查人无偿供给，其数量不得超过检验的合理需要。检验费用在规定经费中列支，不得向被检查人收取。"},{"i":27,"n":"第二十七条","txt":"被检查人对公安机关消防机构抽样送检的产品检验结果有异议的，可以自收到检验结果之日起五日内向实施监督检查的公安机关消防机构提出书面复检申请。 公安机关消防机构受理复检申请，应当当场出具受理凭证。 公安机关消防机构受理复检申请后，应当在五日内将备用样品送检，自收到复检结果之日起三日内，将复检结果告知申请人。 复检申请以一次为限。复检合格的，费用列入监督抽查经费；不合格的，费用由申请人承担。"},{"i":28,"n":"第二十八条","txt":"质量监督部门、工商行政管理部门接到对消防产品质量问题的举报投诉，应当按职责及时依法处理。对不属于本部门职责范围的，应当及时移交或者书面通报有关部门。 公安机关消防机构接到对消防产品质量问题的举报投诉，应当及时受理、登记，并按照公安部《公安机关办理行政案件程序规定》的相关规定和本规定中消防产品质量监督检查程序处理。 公安机关消防机构对举报投诉的消防产品质量问题进行核查后，对消防安全违法行为应当依法处理。核查、处理情况应当在三日内告知举报投诉人；无法告知的，应当在受理登记中注明。"},{"i":29,"n":"第二十九条","txt":"公安机关消防机构发现使用依法应当获得市场准入资格而未获得准入资格的消防产品或者不合格的消防产品、国家明令淘汰的消防产品等使用领域消防产品质量违法行为，应当依法责令限期改正。 公安机关消防机构应当在收到当事人复查申请或者责令限期改正期限届满之日起三日内进行复查。复查应当填写记录。"},{"i":30,"n":"第三十条","txt":"公安机关消防机构对发现的使用领域消防产品质量违法行为，应当依法查处，并及时将有关情况书面通报同级质量监督部门、工商行政管理部门；质量监督部门、工商行政管理部门应当对生产者、销售者依法及时查处。"},{"i":31,"n":"第三十一条","txt":"质量监督部门、工商行政管理部门和公安机关消防机构应当按照有关规定，向社会公布消防产品质量监督检查情况、重大消防产品质量违法行为的行政处罚情况等信息。"},{"i":32,"n":"第三十二条","txt":"任何单位和个人在接受质量监督部门、工商行政管理部门和公安机关消防机构依法开展的消防产品质量监督检查时，应当如实提供有关情况和资料。 任何单位和个人不得擅自转移、变卖、隐匿或者损毁被采取强制措施的物品，不得拒绝依法进行的监督检查。"},{"i":33,"n":"第三十三条","txt":"生产、销售不合格的消防产品或者国家明令淘汰的消防产品的，由质量监督部门或者工商行政管理部门依照《中华人民共和国产品质量法》的规定从重处罚。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，由公安机关消防机构责令改正，依照《中华人民共和国消防法》第五十九条处罚： （一）建设单位要求建设工程施工企业使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的； （二）建设工程设计单位选用不符合市场准入的消防产品，或者国家明令淘汰的消防产品进行消防设计的； （三）建设工程施工企业安装不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的； （四）工程监理单位与建设单位或者建设工程施工企业串通，弄虚作假，安装、使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的。"},{"i":35,"n":"第三十五条","txt":"消防产品技术鉴定机构出具虚假文件的，由公安机关消防机构责令改正，依照《中华人民共和国消防法》第六十九条处罚。"},{"i":36,"n":"第三十六条","txt":"人员密集场所使用不符合市场准入的消防产品的，由公安机关消防机构责令限期改正；逾期不改正的，依照《中华人民共和国消防法》第六十五条第二款处罚。 非人员密集场所使用不符合市场准入的消防产品、不合格的消防产品或者国家明令淘汰的消防产品的，由公安机关消防机构责令限期改正；逾期不改正的，对非经营性场所处五百元以上一千元以下罚款，对经营性场所处五千元以上一万元以下罚款，并对直接负责的主管人员和其他直接责任人员处五百元以下罚款。"},{"i":37,"n":"第三十七条","txt":"公安机关消防机构及其工作人员进行消防产品监督执法，应当严格遵守廉政规定，坚持公正、文明执法，自觉接受单位和公民的监督。 公安机关及其工作人员不得指定消防产品的品牌、销售单位，不得参与或者干预建设工程消防产品的招投标活动，不得接受被检查单位、个人的财物或者其他不正当利益。"},{"i":38,"n":"第三十八条","txt":"质量监督部门、工商行政管理部门、公安机关消防机构工作人员在消防产品监督管理中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":39,"n":"第三十九条","txt":"违反本规定，构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"消防产品目录由公安部消防局制定并公布。"},{"i":41,"n":"第四十一条","txt":"消防产品进出口检验监管，由出入境检验检疫部门按照有关规定执行。 消防产品属于《中华人民共和国特种设备安全监察条例》规定的特种设备的，还应当遵守特种设备安全监察有关规定。"},{"i":42,"n":"第四十二条","txt":"本规定中的“三日”、“五日”是指工作日，不含法定节假日。"},{"i":43,"n":"第四十三条","txt":"公安机关消防机构执行本规定所需要的法律文书式样，由公安部制定。"},{"i":44,"n":"第四十四条","txt":"本规定自2013年1月1日起施行。"}],"xiaofangjiandujianchaguiding":[{"i":1,"n":"第一条","txt":"为了加强和规范消防监督检查工作，督促机关、团体、企业、事业等单位（以下简称单位）履行消防安全职责，依据《中华人民共和国消防法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于公安机关消防机构和公安派出所依法对单位遵守消防法律、法规情况进行消防监督检查。"},{"i":3,"n":"第三条","txt":"直辖市、市（地区、州、盟）、县（市辖区、县级市、旗）公安机关消防机构具体实施消防监督检查，确定本辖区内的消防安全重点单位并由所属公安机关报本级人民政府备案。 公安派出所可以对居民住宅区的物业服务企业、居民委员会、村民委员会履行消防安全职责的情况和上级公安机关确定的单位实施日常消防监督检查。 公安派出所日常消防监督检查的单位范围由省级公安机关消防机构、公安派出所工作主管部门共同研究拟定，报省级公安机关确定。"},{"i":4,"n":"第四条","txt":"上级公安机关消防机构应当对下级公安机关消防机构实施消防监督检查的情况进行指导和监督。 公安机关消防机构应当与公安派出所共同做好辖区消防监督工作，并对公安派出所开展日常消防监督检查工作进行指导，定期对公安派出所民警进行消防监督业务培训。"},{"i":5,"n":"第五条","txt":"对消防监督检查的结果，公安机关消防机构可以通过适当方式向社会公告；对检查发现的影响公共安全的火灾隐患应当定期公布，提示公众注意消防安全。"},{"i":6,"n":"第六条","txt":"消防监督检查的形式有： （一）对公众聚集场所在投入使用、营业前的消防安全检查； （二）对单位履行法定消防安全职责情况的监督抽查； （三）对举报投诉的消防安全违法行为的核查； （四）对大型群众性活动举办前的消防安全检查； （五）根据需要进行的其他消防监督检查。"},{"i":7,"n":"第七条","txt":"公安机关消防机构根据本地区火灾规律、特点等消防安全需要组织监督抽查；在火灾多发季节，重大节日、重大活动前或者期间，应当组织监督抽查。 消防安全重点单位应当作为监督抽查的重点，非消防安全重点单位必须在监督抽查的单位数量中占有一定比例。对属于人员密集场所的消防安全重点单位每年至少监督检查一次。"},{"i":8,"n":"第八条","txt":"公众聚集场所在投入使用、营业前，建设单位或者使用单位应当向场所所在地的县级以上人民政府公安机关消防机构申请消防安全检查，并提交下列材料： （一）消防安全检查申报表； （二）营业执照复印件或者工商行政管理机关出具的企业名称预先核准通知书； （三）依法取得的建设工程消防验收或者进行竣工验收消防备案的法律文件复印件； （四）消防安全制度、灭火和应急疏散预案、场所平面布置图； （五）员工岗前消防安全教育培训记录和自动消防系统操作人员取得的消防行业特有工种职业资格证书复印件； （六）法律、行政法规规定的其他材料。 依照《建设工程消防监督管理规定》不需要进行竣工验收消防备案的公众聚集场所申请消防安全检查的，还应当提交场所室内装修消防设计施工图、消防产品质量合格证明文件，以及装修材料防火性能符合消防技术标准的证明文件、出厂合格证。 公安机关消防机构对消防安全检查的申请，应当按照行政许可有关规定受理。"},{"i":9,"n":"第九条","txt":"对公众聚集场所投入使用、营业前进行消防安全检查，应当检查下列内容： （一）建筑物或者场所是否依法通过消防验收合格或者进行竣工验收消防备案抽查合格；依法进行竣工验收消防备案但没有进行备案抽查的建筑物或者场所是否符合消防技术标准； （二）消防安全制度、灭火和应急疏散预案是否制定； （三）自动消防系统操作人员是否持证上岗，员工是否经过岗前消防安全培训； （四）消防设施、器材是否符合消防技术标准并完好有效； （五）疏散通道、安全出口和消防车通道是否畅通； （六）室内装修材料是否符合消防技术标准； （七）外墙门窗上是否设置影响逃生和灭火救援的障碍物。"},{"i":10,"n":"第十条","txt":"对单位履行法定消防安全职责情况的监督抽查，应当根据单位的实际情况检查下列内容： （一）建筑物或者场所是否依法通过消防验收或者进行竣工验收消防备案，公众聚集场所是否通过投入使用、营业前的消防安全检查； （二）建筑物或者场所的使用情况是否与消防验收或者进行竣工验收消防备案时确定的使用性质相符； （三）消防安全制度、灭火和应急疏散预案是否制定； （四）消防设施、器材和消防安全标志是否定期组织维修保养，是否完好有效； （五）电器线路、燃气管路是否定期维护保养、检测； （六）疏散通道、安全出口、消防车通道是否畅通，防火分区是否改变，防火间距是否被占用； （七）是否组织防火检查、消防演练和员工消防安全教育培训，自动消防系统操作人员是否持证上岗； （八）生产、储存、经营易燃易爆危险品的场所是否与居住场所设置在同一建筑物内； （九）生产、储存、经营其他物品的场所与居住场所设置在同一建筑物内的，是否符合"},{"i":11,"n":"第十一条","txt":"对消防安全重点单位履行法定消防安全职责情况的监督抽查，除检查本规定第十条规定的内容外，还应当检查下列内容： （一）是否确定消防安全管理人； （二）是否开展每日防火巡查并建立巡查记录； （三）是否定期组织消防安全培训和消防演练； （四）是否建立消防档案、确定消防安全重点部位。 对属于人员密集场所的消防安全重点单位，还应当检查单位灭火和应急疏散预案中承担灭火和组织疏散任务的人员是否确定。"},{"i":12,"n":"第十二条","txt":"在大型群众性活动举办前对活动现场进行消防安全检查，应当重点检查下列内容： （一）室内活动使用的建筑物（场所）是否依法通过消防验收或者进行竣工验收消防备案，公众聚集场所是否通过使用、营业前的消防安全检查； （二）临时搭建的建筑物是否符合消防安全要求； （三）是否制定灭火和应急疏散预案并组织演练； （四）是否明确消防安全责任分工并确定消防安全管理人员； （五）活动现场消防设施、器材是否配备齐全并完好有效； （六）活动现场的疏散通道、安全出口和消防车通道是否畅通； （七）活动现场的疏散指示标志和应急照明是否符合消防技术标准并完好有效。"},{"i":13,"n":"第十三条","txt":"对大型的人员密集场所和其他特殊建设工程的施工现场进行消防监督检查，应当重点检查施工单位履行下列消防安全职责的情况： （一）是否明确施工现场消防安全管理人员，是否制定施工现场消防安全制度、灭火和应急疏散预案； （二）在建工程内是否设置人员住宿、可燃材料及易燃易爆危险品储存等场所； （三）是否设置临时消防给水系统、临时消防应急照明，是否配备消防器材，并确保完好有效； （四）是否设有消防车通道并畅通； （五）是否组织员工消防安全教育培训和消防演练； （六）施工现场人员宿舍、办公用房的建筑构件燃烧性能、安全疏散是否符合消防技术标准。"},{"i":14,"n":"第十四条","txt":"公安机关消防机构实施消防监督检查时，检查人员不得少于两人，并出示执法身份证件。 消防监督检查应当填写检查记录，如实记录检查情况。"},{"i":15,"n":"第十五条","txt":"对公众聚集场所投入使用、营业前的消防安全检查，公安机关消防机构应当自受理申请之日起十个工作日内进行检查，自检查之日起三个工作日内作出同意或者不同意投入使用或者营业的决定，并送达申请人。"},{"i":16,"n":"第十六条","txt":"对大型群众性活动现场在举办前进行的消防安全检查，公安机关消防机构应当在接到本级公安机关治安部门书面通知之日起三个工作日内进行检查，并将检查记录移交本级公安机关治安部门。"},{"i":17,"n":"第十七条","txt":"公安机关消防机构接到对消防安全违法行为的举报投诉，应当及时受理、登记，并按照《公安机关办理行政案件程序规定》的相关规定处理。"},{"i":18,"n":"第十八条","txt":"公安机关消防机构应当按照下列时限，对举报投诉的消防安全违法行为进行实地核查： （一）对举报投诉占用、堵塞、封闭疏散通道、安全出口或者其他妨碍安全疏散行为，以及擅自停用消防设施的，应当在接到举报投诉后二十四小时内进行核查； （二）对举报投诉本款第一项以外的消防安全违法行为，应当在接到举报投诉之日起三个工作日内进行核查。 核查后，对消防安全违法行为应当依法处理。处理情况应当及时告知举报投诉人；无法告知的，应当在受理登记中注明。"},{"i":19,"n":"第十九条","txt":"在消防监督检查中，公安机关消防机构对发现的依法应当责令立即改正的消防安全违法行为，应当当场制作、送达责令立即改正通知书，并依法予以处罚；对依法应当责令限期改正的，应当自检查之日起三个工作日内制作、送达责令限期改正通知书，并依法予以处罚。 对违法行为轻微并当场改正完毕，依法可以不予行政处罚的，可以口头责令改正，并在检查记录上注明。"},{"i":20,"n":"第二十条","txt":"对依法责令限期改正的，应当根据改正违法行为的难易程度合理确定改正期限。 公安机关消防机构应当在责令限期改正期限届满或者收到当事人的复查申请之日起三个工作日内进行复查。对逾期不改正的，依法予以处罚。"},{"i":21,"n":"第二十一条","txt":"在消防监督检查中，发现城乡消防安全布局、公共消防设施不符合消防安全要求，或者发现本地区存在影响公共安全的重大火灾隐患的，公安机关消防机构应当组织集体研究确定，自检查之日起七个工作日内提出处理意见，由所属公安机关书面报告本级人民政府解决；对影响公共安全的重大火灾隐患，还应当在确定之日起三个工作日内制作、送达重大火灾隐患整改通知书。 重大火灾隐患判定涉及复杂或者疑难技术问题的，公安机关消防机构应当在确定前组织专家论证。组织专家论证的，前款规定的期限可以延长十个工作日。"},{"i":22,"n":"第二十二条","txt":"公安机关消防机构在消防监督检查中发现火灾隐患，应当通知有关单位或者个人立即采取措施消除；对具有下列情形之一，不及时消除可能严重威胁公共安全的，应当对危险部位或者场所予以临时查封： （一）疏散通道、安全出口数量不足或者严重堵塞，已不具备安全疏散条件的； （二）建筑消防设施严重损坏，不再具备防火灭火功能的； （三）人员密集场所违反消防安全规定，使用、储存易燃易爆危险品的； （四）公众聚集场所违反消防技术标准，采用易燃、可燃材料装修，可能导致重大人员伤亡的； （五）其他可能严重威胁公共安全的火灾隐患。 临时查封期限不得超过三十日。临时查封期限届满后，当事人仍未消除火灾隐患的，公安机关消防机构可以再次依法予以临时查封。"},{"i":23,"n":"第二十三条","txt":"临时查封应当由公安机关消防机构负责人组织集体研究决定。决定临时查封的，应当研究确定查封危险部位或者场所的范围、期限和实施方法，并自检查之日起三个工作日内制作、送达临时查封决定书。 情况紧急、不当场查封可能严重威胁公共安全的，消防监督检查人员可以在口头报请公安机关消防机构负责人同意后当场对危险部位或者场所实施临时查封，并在临时查封后二十四小时内由公安机关消防机构负责人组织集体研究，制作、送达临时查封决定书。经集体研究认为不应当采取临时查封措施的，应当立即解除。"},{"i":24,"n":"第二十四条","txt":"临时查封由公安机关消防机构负责人组织实施。需要公安机关其他部门或者公安派出所配合的，公安机关消防机构应当报请所属公安机关组织实施。 实施临时查封应当遵守下列规定： （一）实施临时查封时，通知当事人到场，当场告知当事人采取临时查封的理由、依据以及当事人依法享有的权利、救济途径，听取当事人的陈述和申辩； （二）当事人不到场的，邀请见证人到场，由见证人和消防监督检查人员在现场笔录上签名或者盖章； （三）在危险部位或者场所及其有关设施、设备上加贴封条或者采取其他措施，使危险部位或者场所停止生产、经营或者使用； （四）对实施临时查封情况制作现场笔录，必要时，可以进行现场照相或者录音录像。 实施临时查封后，当事人请求进入被查封的危险部位或者场所整改火灾隐患的，应当允许。但不得在被查封的危险部位或者场所生产、经营或者使用。"},{"i":25,"n":"第二十五条","txt":"火灾隐患消除后，当事人应当向作出临时查封决定的公安机关消防机构申请解除临时查封。公安机关消防机构应当自收到申请之日起三个工作日内进行检查，自检查之日起三个工作日内作出是否同意解除临时查封的决定，并送达当事人。 对检查确认火灾隐患已消除的，应当作出解除临时查封的决定。"},{"i":26,"n":"第二十六条","txt":"对当事人有《中华人民共和国消防法》第六十条第一款第三项、第四项、第五项、第六项规定的消防安全违法行为，经责令改正拒不改正的，公安机关消防机构应当按照《中华人民共和国行政强制法》第五十一条、第五十二条的规定组织强制清除或者拆除相关障碍物、妨碍物，所需费用由违法行为人承担。"},{"i":27,"n":"第二十七条","txt":"当事人不执行公安机关消防机构作出的停产停业、停止使用、停止施工决定的，作出决定的公安机关消防机构应当自履行期限届满之日起三个工作日内催告当事人履行义务。当事人收到催告书后有权进行陈述和申辩。公安机关消防机构应当充分听取当事人的意见，记录、复核当事人提出的事实、理由和证据。当事人提出的事实、理由或者证据成立的，应当采纳。 经催告，当事人逾期仍不履行义务且无正当理由的，公安机关消防机构负责人应当组织集体研究强制执行方案，确定执行的方式和时间。强制执行决定书应当自决定之日起三个工作日内制作、送达当事人。"},{"i":28,"n":"第二十八条","txt":"强制执行由作出决定的公安机关消防机构负责人组织实施。需要公安机关其他部门或者公安派出所配合的，公安机关消防机构应当报请所属公安机关组织实施；需要其他行政部门配合的，公安机关消防机构应当提出意见，并由所属公安机关报请本级人民政府组织实施。 实施强制执行应当遵守下列规定： （一）实施强制执行时，通知当事人到场，当场向当事人宣读强制执行决定，听取当事人的陈述和申辩； （二）当事人不到场的，邀请见证人到场，由见证人和消防监督检查人员在现场笔录上签名或者盖章； （三）对实施强制执行过程制作现场笔录，必要时，可以进行现场照相或者录音录像； （四）除情况紧急外，不得在夜间或者法定节假日实施强制执行； （五）不得对居民生活采取停止供水、供电、供热、供燃气等方式迫使当事人履行义务。 有《中华人民共和国行政强制法》第三十九条、第四十条规定的情形之一的，中止执行或者终结执行。"},{"i":29,"n":"第二十九条","txt":"对被责令停止施工、停止使用、停产停业处罚的当事人申请恢复施工、使用、生产、经营的，公安机关消防机构应当自收到书面申请之日起三个工作日内进行检查，自检查之日起三个工作日内作出决定，送达当事人。 对当事人已改正消防安全违法行为、具备消防安全条件的，公安机关消防机构应当同意恢复施工、使用、生产、经营；对违法行为尚未改正、不具备消防安全条件的，应当不同意恢复施工、使用、生产、经营，并说明理由。"},{"i":30,"n":"第三十条","txt":"公安派出所对其日常监督检查范围的单位，应当每年至少进行一次日常消防监督检查。 公安派出所对群众举报投诉的消防安全违法行为，应当及时受理，依法处理；对属于公安机关消防机构管辖的，应当依照《公安机关办理行政案件程序规定》在受理后及时移送公安机关消防机构处理。"},{"i":31,"n":"第三十一条","txt":"公安派出所对单位进行日常消防监督检查，应当检查下列内容： （一）建筑物或者场所是否依法通过消防验收或者进行竣工验收消防备案，公众聚集场所是否依法通过投入使用、营业前的消防安全检查； （二）是否制定消防安全制度； （三）是否组织防火检查、消防安全宣传教育培训、灭火和应急疏散演练； （四）消防车通道、疏散通道、安全出口是否畅通，室内消火栓、疏散指示标志、应急照明、灭火器是否完好有效； （五）生产、储存、经营易燃易爆危险品的场所是否与居住场所设置在同一建筑物内。 对设有建筑消防设施的单位，公安派出所还应当检查单位是否对建筑消防设施定期组织维修保养。 对居民住宅区的物业服务企业进行日常消防监督检查，公安派出所除检查本条第一款第（二）至（四）项内容外，还应当检查物业服务企业对管理区域内共用消防设施是否进行维护管理。"},{"i":32,"n":"第三十二条","txt":"公安派出所对居民委员会、村民委员会进行日常消防监督检查，应当检查下列内容： （一）消防安全管理人是否确定； （二）消防安全工作制度、村（居）民防火安全公约是否制定； （三）是否开展消防宣传教育、防火安全检查； （四）是否对社区、村庄消防水源（消火栓）、消防车通道、消防器材进行维护管理； （五）是否建立志愿消防队等多种形式消防组织。"},{"i":33,"n":"第三十三条","txt":"公安派出所民警在日常消防监督检查时，发现被检查单位有下列行为之一的，应当责令依法改正： （一）未制定消防安全制度、未组织防火检查和消防安全教育培训、消防演练的； （二）占用、堵塞、封闭疏散通道、安全出口的； （三）占用、堵塞、封闭消防车通道，妨碍消防车通行的； （四）埋压、圈占、遮挡消火栓或者占用防火间距的； （五）室内消火栓、灭火器、疏散指示标志和应急照明未保持完好有效的； （六）人员密集场所在外墙门窗上设置影响逃生和灭火救援的障碍物的； （七）违反消防安全规定进入生产、储存易燃易爆危险品场所的； （八）违反规定使用明火作业或者在具有火灾、爆炸危险的场所吸烟、使用明火的； （九）生产、储存和经营易燃易爆危险品的场所与居住场所设置在同一建筑物内的； （十）未对建筑消防设施定期组织维修保养的。 公安派出所发现被检查单位的建筑物未依法通过消防验收，或者进行竣工验收消防备案，擅自投入使用的；"},{"i":34,"n":"第三十四条","txt":"公安派出所在日常消防监督检查中，发现存在严重威胁公共安全的火灾隐患，应当在责令改正的同时书面报告乡镇人民政府或者街道办事处和公安机关消防机构。"},{"i":35,"n":"第三十五条","txt":"公安机关消防机构应当健全消防监督检查工作制度，建立执法档案，定期进行执法质量考评，落实执法过错责任追究。 公安机关消防机构及其工作人员进行消防监督检查，应当自觉接受单位和公民的监督。"},{"i":36,"n":"第三十六条","txt":"公安机关消防机构及其工作人员在消防监督检查中有下列情形的，对直接负责的主管人员和其他直接责任人员应当依法给予处分；构成犯罪的，依法追究刑事责任： （一）不按规定制作、送达法律文书，不按照本规定履行消防监督检查职责，拒不改正的； （二）对不符合消防安全条件的公众聚集场所准予消防安全检查合格的； （三）无故拖延消防安全检查，不在法定期限内履行职责的； （四）未按照本规定组织开展消防监督抽查的； （五）发现火灾隐患不及时通知有关单位或者个人整改的； （六）利用消防监督检查职权为用户指定消防产品的品牌、销售单位或者指定消防技术服务机构、消防设施施工、维修保养单位的； （七）接受被检查单位、个人财物或者其他不正当利益的； （八）其他滥用职权、玩忽职守、徇私舞弊的行为。"},{"i":37,"n":"第三十七条","txt":"公安机关消防机构工作人员的近亲属严禁在其管辖的区域或者业务范围内经营消防公司、承揽消防工程、推销消防产品。 违反前款规定的，按照有关规定对公安机关消防机构工作人员予以处分。"},{"i":38,"n":"第三十八条","txt":"具有下列情形之一的，应当确定为火灾隐患： （一）影响人员安全疏散或者灭火救援行动，不能立即改正的； （二）消防设施未保持完好有效，影响防火灭火功能的； （三）擅自改变防火分区，容易导致火势蔓延、扩大的； （四）在人员密集场所违反消防安全规定，使用、储存易燃易爆危险品，不能立即改正的； （五）不符合城市消防安全布局要求，影响公共安全的； （六）其他可能增加火灾实质危险性或者危害性的情形。 重大火灾隐患按照国家有关标准认定。"},{"i":39,"n":"第三十九条","txt":"有固定生产经营场所且具有一定规模的个体工商户，应当纳入消防监督检查范围。具体标准由省、自治区、直辖市公安机关消防机构确定并公告。"},{"i":40,"n":"第四十条","txt":"铁路、港航、民航公安机关和国有林区的森林公安机关在管辖范围内实施消防监督检查参照本规定执行。"},{"i":41,"n":"第四十一条","txt":"执行本规定所需要的法律文书式样，由公安部制定。"},{"i":42,"n":"第四十二条","txt":"本规定自2009年5月1日起施行。2004年6月9日发布的《消防监督检查规定》（公安部令第73号）同时废止。"}],"kanshousuoliusuozhixingxingfazuifanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范看守所对留所执行刑罚罪犯的管理，做好罪犯改造工作，根据《中华人民共和国刑事诉讼法》、《中华人民共和国监狱法》、《中华人民共和国看守所条例》等有关法律、法规，结合看守所执行刑罚的实际，制定本办法。"},{"i":2,"n":"第二条","txt":"被判处有期徒刑的成年和未成年罪犯，在被交付执行前，剩余刑期在三个月以下的，由看守所代为执行刑罚。 被判处拘役的成年和未成年罪犯，由看守所执行刑罚。"},{"i":3,"n":"第三条","txt":"看守所应当设置专门监区或者监室监管罪犯。监区和监室应当设在看守所警戒围墙内。"},{"i":4,"n":"第四条","txt":"看守所管理罪犯应当坚持惩罚与改造相结合、教育和劳动相结合的原则，将罪犯改造成为守法公民。"},{"i":5,"n":"第五条","txt":"罪犯的人格不受侮辱，人身安全和合法财产不受侵犯，罪犯享有辩护、申诉、控告、检举以及其他未被依法剥夺或者限制的权利。 罪犯应当遵守法律、法规和看守所管理规定，服从管理，接受教育，按照规定参加劳动。"},{"i":6,"n":"第六条","txt":"看守所应当保障罪犯的合法权益，为罪犯行使权利提供必要的条件。"},{"i":7,"n":"第七条","txt":"看守所对提请罪犯减刑、假释，或者办理罪犯暂予监外执行，可能存在利用权力、钱财影响公正执法因素的，要依法从严审核、审批。"},{"i":8,"n":"第八条","txt":"看守所对罪犯执行刑罚的活动依法接受人民检察院的法律监督。"},{"i":9,"n":"第九条","txt":"看守所在收到交付执行的人民法院送达的人民检察院起诉书副本和人民法院判决书、裁定书、执行通知书、结案登记表的当日，应当办理罪犯收押手续，填写收押登记表，载明罪犯基本情况、收押日期等，并由民警签字后，将罪犯转入罪犯监区或者监室。"},{"i":10,"n":"第十条","txt":"对于判决前未被羁押，判决后需要羁押执行刑罚的罪犯，看守所应当凭本办法第九条所列文书收押，并采集罪犯十指指纹信息。"},{"i":11,"n":"第十一条","txt":"按照本办法第十条收押罪犯时，看守所应当进行健康和人身、物品安全检查。对罪犯的非生活必需品，应当登记，通知其家属领回或者由看守所代为保管；对违禁品，应当予以没收。 对女性罪犯的人身检查，由女性人民警察进行。"},{"i":12,"n":"第十二条","txt":"办理罪犯收押手续时应当建立罪犯档案。羁押服刑过程中的法律文书和管理材料存入档案。罪犯档案一人一档，分为正档和副档。正档包括收押凭证、暂予监外执行决定书、减刑、假释裁定书、释放证明书等法律文书；副档包括收押登记、谈话教育、罪犯考核、奖惩、疾病治疗、财物保管登记等管理记录。"},{"i":13,"n":"第十三条","txt":"收押罪犯后，看守所应当在五日内向罪犯家属或者监护人发出罪犯执行刑罚地点通知书。对收押的外国籍罪犯，应当在二十四小时内报告所属公安机关。"},{"i":14,"n":"第十四条","txt":"罪犯对已经发生法律效力的判决、裁定不服，提出申诉的，看守所应当及时将申诉材料转递给人民检察院和作出生效判决的人民法院。罪犯也可以委托其法定代理人、近亲属提出申诉。"},{"i":15,"n":"第十五条","txt":"罪犯有权控告、检举违法犯罪行为。 看守所应当设置控告、检举信箱，接受罪犯的控告、检举材料。罪犯也可以直接向民警控告、检举。"},{"i":16,"n":"第十六条","txt":"对罪犯向看守所提交的控告、检举材料，看守所应当自收到材料之日起十五日内作出处理；对罪犯向人民法院、人民检察院提交的控告、检举材料，看守所应当自收到材料之日起五日内予以转送。 看守所对控告、检举作出处理或者转送有关部门处理的，应当及时将有关情况或者处理结果通知具名控告、检举的罪犯。"},{"i":17,"n":"第十七条","txt":"看守所在执行刑罚过程中，发现判决可能有错误的，应当提请人民检察院或者人民法院处理。"},{"i":18,"n":"第十八条","txt":"罪犯符合《中华人民共和国刑事诉讼法》规定的暂予监外执行条件的，本人及其法定代理人、近亲属可以向看守所提出书面申请，管教民警或者看守所医生也可以提出书面意见。"},{"i":19,"n":"第十九条","txt":"看守所接到暂予监外执行申请或者意见后，应当召开所务会研究，初审同意后根据不同情形对罪犯进行病情鉴定、生活不能自理鉴定或者妊娠检查，未通过初审的，应当向提出书面申请或者书面意见的人员告知原因。 所务会应当有书面记录，并由与会人员签名。"},{"i":20,"n":"第二十条","txt":"对暂予监外执行罪犯的病情鉴定，应当到省级人民政府指定的医院进行；妊娠检查，应当到医院进行；生活不能自理鉴定，由看守所分管所领导、管教民警、看守所医生、驻所检察人员等组成鉴定小组进行；对正在哺乳自己婴儿的妇女，看守所应当通知罪犯户籍所在地或者居住地的公安机关出具相关证明。 生活不能自理，是指因病、伤残或者年老体弱致使日常生活中起床、用餐、行走、如厕等不能自行进行，必须在他人协助下才能完成。 对适用保外就医可能有社会危险性的罪犯，或者自伤自残的罪犯，不得保外就医。"},{"i":21,"n":"第二十一条","txt":"罪犯需要保外就医的，应当由罪犯或者罪犯家属提出保证人。保证人由看守所审查确定。"},{"i":22,"n":"第二十二条","txt":"保证人应当具备下列条件： （一）愿意承担保证人义务，具有完全民事行为能力； （二）人身自由未受到限制，享有政治权利； （三）有固定的住所和收入，有条件履行保证人义务； （四）与被保证人共同居住或者居住在同一县级公安机关辖区。"},{"i":23,"n":"第二十三条","txt":"保证人应当签署保外就医保证书。"},{"i":24,"n":"第二十四条","txt":"罪犯保外就医期间，保证人应当履行下列义务： （一）协助社区矫正机构监督被保证人遵守法律和有关规定； （二）发现被保证人擅自离开居住的市、县，变更居住地，有违法犯罪行为，保外就医情形消失，或者被保证人死亡的，立即向社区矫正机构报告； （三）为被保证人的治疗、护理、复查以及正常生活提供帮助； （四）督促和协助被保证人按照规定定期复查病情和向执行机关报告。"},{"i":25,"n":"第二十五条","txt":"对需要暂予监外执行的罪犯，看守所应当填写暂予监外执行审批表，并附病情鉴定、妊娠检查证明、生活不能自理鉴定，或者哺乳自己婴儿证明；需要保外就医的，应当同时附保外就医保证书。县级看守所应当将有关材料报经所属公安机关审核同意后，报设区的市一级以上公安机关批准；设区的市一级以上看守所应当将有关材料报所属公安机关审批。 看守所在报送审批材料的同时，应当将暂予监外执行审批表副本、病情鉴定或者妊娠检查诊断证明、生活不能自理鉴定、哺乳自己婴儿证明、保外就医保证书等有关材料的复印件抄送人民检察院驻所检察室。 批准暂予监外执行的公安机关接到人民检察院认为暂予监外执行不当的意见后，应当对暂予监外执行的决定进行重新核查。"},{"i":26,"n":"第二十六条","txt":"看守所收到批准、决定机关暂予监外执行决定书后，应当办理罪犯出所手续，发给暂予监外执行决定书，并告知罪犯应当遵守的规定。"},{"i":27,"n":"第二十七条","txt":"暂予监外执行罪犯服刑地和居住地不在同一省级或者设区的市一级以上公安机关辖区，需要回居住地暂予监外执行的，服刑地的省级公安机关监管部门或者设区的市一级以上公安机关监管部门应当书面通知居住地的同级公安机关监管部门，由居住地的公安机关监管部门指定看守所接收罪犯档案、负责办理收监或者刑满释放等手续。"},{"i":28,"n":"第二十八条","txt":"看守所应当将暂予监外执行罪犯送交罪犯居住地，与县级司法行政机关办理交接手续。"},{"i":29,"n":"第二十九条","txt":"公安机关对暂予监外执行罪犯决定收监执行的，由罪犯居住地看守所将罪犯收监执行。 看守所对人民法院决定暂予监外执行罪犯收监执行的，应当是交付执行刑罚前剩余刑期在三个月以下的罪犯。"},{"i":30,"n":"第三十条","txt":"罪犯在暂予监外执行期间刑期届满的，看守所应当为其办理刑满释放手续。"},{"i":31,"n":"第三十一条","txt":"罪犯暂予监外执行期间死亡的，看守所应当将执行机关的书面通知归入罪犯档案，并在登记表中注明。"},{"i":32,"n":"第三十二条","txt":"罪犯符合减刑、假释条件的，由管教民警提出建议，报看守所所务会研究决定。所务会应当有书面记录，并由与会人员签名。"},{"i":33,"n":"第三十三条","txt":"看守所所务会研究同意后，应当将拟提请减刑、假释的罪犯名单以及减刑、假释意见在看守所内公示。公示期限为三个工作日。公示期内，如有民警或者罪犯对公示内容提出异议，看守所应当重新召开所务会复核，并告知复核结果。"},{"i":34,"n":"第三十四条","txt":"公示完毕，看守所所长应当在罪犯减刑、假释审批表上签署意见，加盖看守所公章，制作提请减刑、假释建议书，经设区的市一级以上公安机关审查同意后，连同有关材料一起提请所在地中级以上人民法院裁定，并将建议书副本和相关材料抄送人民检察院。"},{"i":35,"n":"第三十五条","txt":"看守所提请人民法院审理减刑、假释案件时，应当送交下列材料： （一）提请减刑、假释建议书； （二）终审人民法院的裁判文书、执行通知书、历次减刑裁定书的复制件； （三）证明罪犯确有悔改、立功或者重大立功表现具体事实的书面材料； （四）罪犯评审鉴定表、奖惩审批表等有关材料； （五）根据案件情况需要移送的其他材料。"},{"i":36,"n":"第三十六条","txt":"在人民法院作出减刑、假释裁定前，看守所发现罪犯不符合减刑、假释条件的，应当书面撤回提请减刑、假释建议书；在减刑、假释裁定生效后，看守所发现罪犯不符合减刑、假释条件的，应当书面向作出裁定的人民法院提出撤销裁定建议。"},{"i":37,"n":"第三十七条","txt":"看守所收到人民法院假释裁定书后，应当办理罪犯出所手续，发给假释证明书，并于三日内将罪犯的有关材料寄送罪犯居住地的县级司法行政机关。"},{"i":38,"n":"第三十八条","txt":"被假释的罪犯被人民法院裁定撤销假释的，看守所应当在收到撤销假释裁定后将罪犯收监。"},{"i":39,"n":"第三十九条","txt":"罪犯在假释期间死亡的，看守所应当将执行机关的书面通知归入罪犯档案，并在登记表中注明。"},{"i":40,"n":"第四十条","txt":"看守所应当在罪犯服刑期满前一个月内，将其在所内表现、综合评估意见、帮教建议等送至其户籍所在地县级公安机关和司法行政机关（安置帮教工作协调小组办公室）。"},{"i":41,"n":"第四十一条","txt":"罪犯服刑期满，看守所应当按期释放，发给刑满释放证明书，并告知其在规定期限内，持刑满释放证明书到原户籍所在地的公安派出所办理户籍登记手续；有代管钱物的，看守所应当如数发还。 刑满释放人员患有重病的，看守所应当通知其家属接回。"},{"i":42,"n":"第四十二条","txt":"外国籍罪犯被判处附加驱逐出境的，看守所应当在罪犯服刑期满前十日通知所属公安机关出入境管理部门。"},{"i":43,"n":"第四十三条","txt":"看守所应当将男性和女性罪犯、成年和未成年罪犯分别关押和管理。 有条件的看守所，可以根据罪犯的犯罪类型、刑罚种类、性格特征、心理状况、健康状况、改造表现等，对罪犯实行分别关押和管理。"},{"i":44,"n":"第四十四条","txt":"看守所应当根据罪犯的改造表现，对罪犯实行宽严有别的分级处遇。对罪犯适用分级处遇，按照有关规定，依据对罪犯改造表现的考核结果确定，并应当根据情况变化适时调整。 对不同处遇等级的罪犯，看守所应当在其活动范围、会见通讯、接收物品、文体活动、奖励等方面，分别实施相应的处遇。"},{"i":45,"n":"第四十五条","txt":"罪犯可以与其亲属或者监护人每月会见一至二次，每次不超过一小时。每次前来会见罪犯的人员不超过三人。因特殊情况需要延长会见时间，增加会见人数，或者其亲属、监护人以外的人要求会见的，应当经看守所领导批准。"},{"i":46,"n":"第四十六条","txt":"罪犯与受委托的律师会见，由律师向看守所提出申请，看守所应当查验授权委托书、律师事务所介绍信和律师执业证，并在四十八小时内予以安排。"},{"i":47,"n":"第四十七条","txt":"依据我国参加的国际公约和缔结的领事条约的有关规定，外国驻华使（领）馆官员要求探视其本国籍罪犯，或者外国籍罪犯亲属、监护人首次要求会见的，应当向省级公安机关提出书面申请。看守所根据省级公安机关的书面通知予以安排。外国籍罪犯亲属或者监护人再次要求会见的，可以直接向看守所提出申请。 外国籍罪犯拒绝其所属国驻华使（领）馆官员或者其亲属、监护人探视的，看守所不予安排，但罪犯应当出具本人签名的书面声明。"},{"i":48,"n":"第四十八条","txt":"经看守所领导批准，罪犯可以用指定的固定电话与其亲友、监护人通话；外国籍罪犯还可以与其所属国驻华使（领）馆通话。通话费用由罪犯本人承担。"},{"i":49,"n":"第四十九条","txt":"少数民族罪犯可以使用其本民族语言文字会见、通讯；外国籍罪犯可以使用其本国语言文字会见、通讯。"},{"i":50,"n":"第五十条","txt":"会见应当在看守所会见室进行。 罪犯近亲属、监护人不便到看守所会见，经其申请，看守所可以安排视频会见。 会见、通讯应当遵守看守所的有关规定。对违反规定的，看守所可以中止本次会见、通讯。"},{"i":51,"n":"第五十一条","txt":"罪犯可以与其亲友或者监护人通信。看守所应当对罪犯的来往信件进行检查，发现有碍罪犯改造内容的信件可以扣留。 罪犯写给看守所的上级机关和司法机关的信件，不受检查。"},{"i":52,"n":"第五十二条","txt":"办案机关因办案需要向罪犯了解有关情况的，应当出具办案机关证明和办案人员工作证，并经看守所领导批准后在看守所内进行。"},{"i":53,"n":"第五十三条","txt":"因起赃、辨认、出庭作证、接受审判等需要将罪犯提出看守所的，办案机关应当出具公函，经看守所领导批准后提出，并当日送回。 侦查机关因办理其他案件需要将罪犯临时寄押到异地看守所取证，并持有侦查机关所在的设区的市一级以上公安机关公函的，看守所应当允许提出，并办理相关手续。 人民法院因再审开庭需要将罪犯提出看守所，并持有人民法院刑事再审决定书或者刑事裁定书，或者人民检察院抗诉书的，看守所应当允许提出，并办理相关手续。"},{"i":54,"n":"第五十四条","txt":"被判处拘役的罪犯每月可以回家一至二日，由罪犯本人提出申请，管教民警签署意见，经看守所所长审核后，报所属公安机关批准。"},{"i":55,"n":"第五十五条","txt":"被判处拘役的外国籍罪犯提出探亲申请的，看守所应当报设区的市一级以上公安机关审批。设区的市一级以上公安机关作出批准决定的，应当报上一级公安机关备案。 被判处拘役的外国籍罪犯探亲时，不得出境。"},{"i":56,"n":"第五十六条","txt":"对于准许回家的拘役罪犯，看守所应当发给回家证明，并告知应当遵守的相关规定。 罪犯回家时间不能集中使用，不得将刑期末期作为回家时间，变相提前释放罪犯。"},{"i":57,"n":"第五十七条","txt":"罪犯需要办理婚姻登记等必须由本人实施的民事法律行为的，应当向看守所提出书面申请，经看守所领导批准后出所办理，由二名以上民警押解，并于当日返回。"},{"i":58,"n":"第五十八条","txt":"罪犯进行民事诉讼需要出庭时，应当委托诉讼代理人代为出庭。对于涉及人身关系的诉讼等必须由罪犯本人出庭的，凭人民法院出庭通知书办理临时离所手续，由人民法院司法警察负责押解看管，并于当日返回。 罪犯因特殊情况不宜离所出庭的，看守所可以与人民法院协商，根据《中华人民共和国民事诉讼法》第一百二十一条的规定，由人民法院到看守所开庭审理。"},{"i":59,"n":"第五十九条","txt":"罪犯遇有配偶、父母、子女病危或者死亡，确需本人回家处理的，由当地公安派出所出具证明，经看守所所属公安机关领导批准，可以暂时离所，由二名以上民警押解，并于当日返回。"},{"i":60,"n":"第六十条","txt":"罪犯伙食按照国务院财政部门、公安部门制定的实物量标准执行。"},{"i":61,"n":"第六十一条","txt":"罪犯应当着囚服。"},{"i":62,"n":"第六十二条","txt":"对少数民族罪犯，应当尊重其生活、饮食习惯。罪犯患病治疗期间，看守所应当适当提高伙食标准。"},{"i":63,"n":"第六十三条","txt":"看守所对罪犯收受的物品应当进行检查，非日常生活用品由看守所登记保管。罪犯收受的钱款，由看守所代为保管，并开具记账卡交与罪犯。 看守所检查、接收送给罪犯的物品、钱款后，应当开具回执交与送物人、送款人。 罪犯可以依照有关规定使用物品和支出钱款。罪犯刑满释放时，钱款余额和本人物品由其本人领回。"},{"i":64,"n":"第六十四条","txt":"对患病的罪犯，看守所应当及时治疗；对患有传染病需要隔离治疗的，应当及时隔离治疗。"},{"i":65,"n":"第六十五条","txt":"罪犯在服刑期间死亡的，看守所应当立即报告所属公安机关，并通知罪犯家属和人民检察院、原判人民法院。外国籍罪犯死亡的，应当立即层报至省级公安机关。 罪犯死亡的，由看守所所属公安机关或者医院对死亡原因作出鉴定。罪犯家属有异议的，可以向人民检察院提出。"},{"i":66,"n":"第六十六条","txt":"看守所应当依照公开、公平、公正的原则，对罪犯改造表现实行量化考核。考核情况由管教民警填写。考核以罪犯认罪服法、遵守监规、接受教育、参加劳动等情况为主要内容。 考核结果作为对罪犯分级处遇、奖惩和提请减刑、假释的依据。"},{"i":67,"n":"第六十七条","txt":"罪犯有下列情形之一的，看守所可以给予表扬、物质奖励或者记功： （一）遵守管理规定，努力学习，积极劳动，有认罪服法表现的； （二）阻止违法犯罪活动的； （三）爱护公物或者在劳动中节约原材料，有成绩的； （四）进行技术革新或者传授生产技术，有一定成效的； （五）在防止或者消除灾害事故中作出一定贡献的； （六）对国家和社会有其他贡献的。 对罪犯的物质奖励或者记功意见由管教民警提出，物质奖励由看守所领导批准，记功由看守所所务会研究决定。被判处有期徒刑的罪犯有前款所列情形之一，在服刑期间一贯表现好，离开看守所不致再危害社会的，看守所可以根据情况准其离所探亲。"},{"i":68,"n":"第六十八条","txt":"罪犯申请离所探亲的，应当由其家属担保，经看守所所务会研究同意后，报所属公安机关领导批准。探亲时间不含路途时间，为三至七日。罪犯在探亲期间不得离开其亲属居住地，不得出境。 看守所所务会应当有书面记录，并由与会人员签名。 不得将罪犯离所探亲时间安排在罪犯刑期末期，变相提前释放罪犯。"},{"i":69,"n":"第六十九条","txt":"对离所探亲的罪犯，看守所应当发给离所探亲证明书。罪犯应当在抵家的当日携带离所探亲证明书到当地公安派出所报到。返回看守所时，由该公安派出所将其离所探亲期间的表现在离所探亲证明书上注明。"},{"i":70,"n":"第七十条","txt":"罪犯有下列破坏监管秩序情形之一，情节较轻的，予以警告；情节较重的，予以记过；情节严重的，予以禁闭；构成犯罪的，依法追究刑事责任： （一）聚众哄闹，扰乱正常监管秩序的； （二）辱骂或者殴打民警的； （三）欺压其他罪犯的； （四）盗窃、赌博、打架斗殴、寻衅滋事的； （五）有劳动能力拒不参加劳动或者消极怠工，经教育不改的； （六）以自伤、自残手段逃避劳动的； （七）在生产劳动中故意违反操作规程，或者有意损坏生产工具的； （八）有违反看守所管理规定的其他行为的。 对罪犯的记过、禁闭由管教民警提出意见，报看守所领导批准。禁闭时间为五至十日，禁闭期间暂停会见、通讯。"},{"i":71,"n":"第七十一条","txt":"看守所对被禁闭的罪犯，应当指定专人进行教育帮助。对确已悔悟的，可以提前解除禁闭，由管教民警提出书面意见，报看守所领导批准；禁闭期满的，应当立即解除禁闭。"},{"i":72,"n":"第七十二条","txt":"看守所应当建立对罪犯的教育改造制度，对罪犯进行法制、道德、文化、技能等教育。"},{"i":73,"n":"第七十三条","txt":"对罪犯的教育应当根据罪犯的犯罪类型、犯罪原因、恶性程度及其思想、行为、心理特征，坚持因人施教、以理服人、注重实效的原则，采取集体教育与个别教育相结合，所内教育与所外教育相结合的方法。"},{"i":74,"n":"第七十四条","txt":"有条件的看守所应当设立教室、谈话室、文体活动室、图书室、阅览室、电化教育室、心理咨询室等教育改造场所，并配备必要的设施。"},{"i":75,"n":"第七十五条","txt":"看守所应当结合时事、政治、重大事件等，适时对罪犯进行集体教育。"},{"i":76,"n":"第七十六条","txt":"看守所应当根据每一名罪犯的具体情况，适时进行有针对性的教育。"},{"i":77,"n":"第七十七条","txt":"看守所应当积极争取社会支持，配合看守所开展社会帮教活动。看守所可以组织罪犯到社会上参观学习，接受教育。"},{"i":78,"n":"第七十八条","txt":"看守所应当根据不同情况，对罪犯进行文化教育，鼓励罪犯自学。 罪犯可以参加国家举办的高等教育自学考试，看守所应当为罪犯学习和考试提供方便。"},{"i":79,"n":"第七十九条","txt":"看守所应当加强监区文化建设，组织罪犯开展适当的文体活动，创造有益于罪犯身心健康和发展的改造环境。"},{"i":80,"n":"第八十条","txt":"看守所应当组织罪犯参加劳动，培养劳动技能，积极创造条件，组织罪犯参加各类职业技术教育培训。"},{"i":81,"n":"第八十一条","txt":"看守所对罪犯的劳动时间，参照国家有关劳动工时的规定执行。 罪犯有在法定节日和休息日休息的权利。"},{"i":82,"n":"第八十二条","txt":"看守所对于参加劳动的罪犯，可以酌量发给报酬并执行国家有关劳动保护的规定。"},{"i":83,"n":"第八十三条","txt":"罪犯在劳动中致伤、致残或者死亡的，由看守所参照国家劳动保险的有关规定处理。"},{"i":84,"n":"第八十四条","txt":"罪犯在看守所内又犯新罪的，由所属公安机关侦查。"},{"i":85,"n":"第八十五条","txt":"看守所发现罪犯有判决前尚未发现的犯罪行为的，应当书面报告所属公安机关。"},{"i":86,"n":"第八十六条","txt":"设区的市一级以上公安机关可以根据实际情况设置集中关押留所执行刑罚罪犯的看守所。"},{"i":87,"n":"第八十七条","txt":"各省、自治区、直辖市公安厅、局和新疆生产建设兵团公安局可以依据本办法制定实施细则。"},{"i":88,"n":"第八十八条","txt":"本办法自2013年11月23日起施行。2008年2月29日发布的《看守所留所执行刑罚罪犯管理办法》（公安部令第98号）同时废止。"}],"shehuixiaofanganquanjiaoyupeixunguiding-2":[{"i":1,"n":"第一条","txt":"为了加强社会消防安全教育培训工作，提高公民消防安全素质，有效预防火灾，减少火灾危害，根据《中华人民共和国消防法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"机关、团体、企业、事业等单位（以下统称单位）、社区居民委员会、村民委员会依照本规定开展消防安全教育培训工作。"},{"i":3,"n":"第三条","txt":"公安、教育、民政、人力资源和社会保障、住房和城乡建设、文化、广电、安全监管、旅游、文物等部门应当按照各自职能，依法组织和监督管理消防安全教育培训工作，并纳入相关工作检查、考评。 各部门应当建立协作机制，定期研究、共同做好消防安全教育培训工作。"},{"i":4,"n":"第四条","txt":"消防安全教育培训的内容应当符合全国统一的消防安全教育培训大纲的要求，主要包括： （一）国家消防工作方针、政策； （二）消防法律法规； （三）火灾预防知识； （四）火灾扑救、人员疏散逃生和自救互救知识； （五）其他应当教育培训的内容。"},{"i":5,"n":"第五条","txt":"公安机关应当履行下列职责，并由公安机关消防机构具体实施： （一）掌握本地区消防安全教育培训工作情况，向本级人民政府及相关部门提出工作建议； （二）协调有关部门指导和监督社会消防安全教育培训工作； （三）会同教育行政部门、人力资源和社会保障部门对消防安全专业培训机构实施监督管理； （四）定期对社区居民委员会、村民委员会的负责人和专（兼）职消防队、志愿消防队的负责人开展消防安全培训。"},{"i":6,"n":"第六条","txt":"教育行政部门应当履行下列职责： （一）将学校消防安全教育培训工作纳入教育培训规划，并进行教育督导和工作考核； （二）指导和监督学校将消防安全知识纳入教学内容； （三）将消防安全知识纳入学校管理人员和教师在职培训内容； （四）依法在职责范围内对消防安全专业培训机构进行审批和监督管理。"},{"i":7,"n":"第七条","txt":"民政部门应当履行下列职责： （一）将消防安全教育培训工作纳入减灾规划并组织实施，结合救灾、扶贫济困和社会优抚安置、慈善等工作开展消防安全教育； （二）指导社区居民委员会、村民委员会和各类福利机构开展消防安全教育培训工作； （三）负责消防安全专业培训机构的登记，并实施监督管理。"},{"i":8,"n":"第八条","txt":"人力资源和社会保障部门应当履行下列职责： （一）指导和监督机关、企业和事业单位将消防安全知识纳入干部、职工教育、培训内容； （二）依法在职责范围内对消防安全专业培训机构进行审批和监督管理。"},{"i":9,"n":"第九条","txt":"住房和城乡建设行政部门应当指导和监督勘察设计单位、施工单位、工程监理单位、施工图审查机构、城市燃气企业、物业服务企业、风景名胜区经营管理单位和城市公园绿地管理单位等开展消防安全教育培训工作，将消防法律法规和工程建设消防技术标准纳入建设行业相关执业人员的继续教育和从业人员的岗位培训及考核内容。"},{"i":10,"n":"第十条","txt":"文化、文物行政部门应当积极引导创作优秀消防安全文化产品，指导和监督文物保护单位、公共娱乐场所和公共图书馆、博物馆、文化馆、文化站等文化单位开展消防安全教育培训工作。"},{"i":11,"n":"第十一条","txt":"广播影视行政部门应当指导和协调广播影视制作机构和广播电视播出机构，制作、播出相关消防安全节目，开展公益性消防安全宣传教育，指导和监督电影院开展消防安全教育培训工作。"},{"i":12,"n":"第十二条","txt":"安全生产监督管理部门应当履行下列职责： （一）指导、监督矿山、危险化学品、烟花爆竹等生产经营单位开展消防安全教育培训工作； （二）将消防安全知识纳入安全生产监管监察人员和矿山、危险化学品、烟花爆竹等生产经营单位主要负责人、安全生产管理人员以及特种作业人员培训考核内容； （三）将消防法律法规和有关消防技术标准纳入注册安全工程师培训及执业资格考试内容。"},{"i":13,"n":"第十三条","txt":"旅游行政部门应当指导和监督相关旅游企业开展消防安全教育培训工作，督促旅行社加强对游客的消防安全教育，并将消防安全条件纳入旅游饭店、旅游景区等相关行业标准，将消防安全知识纳入旅游从业人员的岗位培训及考核内容。"},{"i":14,"n":"第十四条","txt":"单位应当根据本单位的特点，建立健全消防安全教育培训制度，明确机构和人员，保障教育培训工作经费，按照下列规定对职工进行消防安全教育培训： （一）定期开展形式多样的消防安全宣传教育； （二）对新上岗和进入新岗位的职工进行上岗前消防安全培训； （三）对在岗的职工每年至少进行一次消防安全培训； （四）消防安全重点单位每半年至少组织一次、其他单位每年至少组织一次灭火和应急疏散演练。 单位对职工的消防安全教育培训应当将本单位的火灾危险性、防火灭火措施、消防设施及灭火器材的操作使用方法、人员疏散逃生知识等作为培训的重点。"},{"i":15,"n":"第十五条","txt":"各级各类学校应当开展下列消防安全教育工作： （一）将消防安全知识纳入教学内容； （二）在开学初、放寒（暑）假前、学生军训期间，对学生普遍开展专题消防安全教育； （三）结合不同课程实验课的特点和要求，对学生进行有针对性的消防安全教育； （四）组织学生到当地消防站参观体验； （五）每学年至少组织学生开展一次应急疏散演练； （六）对寄宿学生开展经常性的安全用火用电教育和应急疏散演练。 各级各类学校应当至少确定一名熟悉消防安全知识的教师担任消防安全课教员，并选聘消防专业人员担任学校的兼职消防辅导员。"},{"i":16,"n":"第十六条","txt":"中小学校和学前教育机构应当针对不同年龄阶段学生认知特点，保证课时或者采取学科渗透、专题教育的方式，每学期对学生开展消防安全教育。 小学阶段应当重点开展火灾危险及危害性、消防安全标志标识、日常生活防火、火灾报警、火场自救逃生常识等方面的教育。 初中和高中阶段应当重点开展消防法律法规、防火灭火基本知识和灭火器材使用等方面的教育。 学前教育机构应当采取游戏、儿歌等寓教于乐的方式，对幼儿开展消防安全常识教育。"},{"i":17,"n":"第十七条","txt":"高等学校应当每学年至少举办一次消防安全专题讲座，在校园网络、广播、校内报刊等开设消防安全教育栏目，对学生进行消防法律法规、防火灭火知识、火灾自救他救知识和火灾案例教育。"},{"i":18,"n":"第十八条","txt":"国家支持和鼓励有条件的普通高等学校和中等职业学校根据经济社会发展需要，设置消防类专业或者开设消防类课程，培养消防专业人才，并依法面向社会开展消防安全培训。 人民警察训练学校应当根据教育培训对象的特点，科学安排培训内容，开设消防基础理论和消防管理课程，并列入学生必修课程。 师范院校应当将消防安全知识列入学生必修内容。"},{"i":19,"n":"第十九条","txt":"社区居民委员会、村民委员会应当开展下列消防安全教育工作： （一）组织制定防火安全公约； （二）在社区、村庄的公共活动场所设置消防宣传栏，利用文化活动站、学习室等场所，对居民、村民开展经常性的消防安全宣传教育； （三）组织志愿消防队、治安联防队和灾害信息员、保安人员等开展消防安全宣传教育； （四）利用社区、乡村广播、视频设备定时播放消防安全常识，在火灾多发季节、农业收获季节、重大节日和乡村民俗活动期间，有针对性地开展消防安全宣传教育。 社区居民委员会、村民委员会应当确定至少一名专（兼）职消防安全员，具体负责消防安全宣传教育工作。"},{"i":20,"n":"第二十条","txt":"物业服务企业应当在物业服务工作范围内，根据实际情况积极开展经常性消防安全宣传教育，每年至少组织一次本单位员工和居民参加的灭火和应急疏散演练。"},{"i":21,"n":"第二十一条","txt":"由两个以上单位管理或者使用的同一建筑物，负责公共消防安全管理的单位应当对建筑物内的单位和职工进行消防安全宣传教育，每年至少组织一次灭火和应急疏散演练。"},{"i":22,"n":"第二十二条","txt":"歌舞厅、影剧院、宾馆、饭店、商场、集贸市场、体育场馆、会堂、医院、客运车站、客运码头、民用机场、公共图书馆和公共展览馆等公共场所应当按照下列要求对公众开展消防安全宣传教育： （一）在安全出口、疏散通道和消防设施等处的醒目位置设置消防安全标志、标识等； （二）根据需要编印场所消防安全宣传资料供公众取阅； （三）利用单位广播、视频设备播放消防安全知识。 养老院、福利院、救助站等单位，应当对服务对象开展经常性的用火用电和火场自救逃生安全教育。"},{"i":23,"n":"第二十三条","txt":"旅游景区、城市公园绿地的经营管理单位、大型群众性活动主办单位应当在景区、公园绿地、活动场所醒目位置设置疏散路线、消防设施示意图和消防安全警示标识，利用广播、视频设备、宣传栏等开展消防安全宣传教育。 导游人员、旅游景区工作人员应当向游客介绍景区消防安全常识和管理要求。"},{"i":24,"n":"第二十四条","txt":"在建工程的施工单位应当开展下列消防安全教育工作： （一）建设工程施工前应当对施工人员进行消防安全教育； （二）在建设工地醒目位置、施工人员集中住宿场所设置消防安全宣传栏，悬挂消防安全挂图和消防安全警示标识； （三）对明火作业人员进行经常性的消防安全教育； （四）组织灭火和应急疏散演练。 在建工程的建设单位应当配合施工单位做好上述消防安全教育工作。"},{"i":25,"n":"第二十五条","txt":"新闻、广播、电视等单位应当积极开设消防安全教育栏目，制作节目，对公众开展公益性消防安全宣传教育。"},{"i":26,"n":"第二十六条","txt":"公安、教育、民政、人力资源和社会保障、住房和城乡建设、安全监管、旅游部门管理的培训机构，应当根据教育培训对象特点和实际需要进行消防安全教育培训。"},{"i":27,"n":"第二十七条","txt":"国家机构以外的社会组织或者个人利用非国家财政性经费，举办消防安全专业培训机构，面向社会从事消防安全专业培训的，应当经省级教育行政部门或者人力资源和社会保障部门依法批准，并到省级民政部门申请民办非企业单位登记。"},{"i":28,"n":"第二十八条","txt":"成立消防安全专业培训机构应当符合下列条件： （一）具有法人条件，有规范的名称和必要的组织机构； （二）注册资金或者开办费一百万元以上； （三）有健全的组织章程和培训、考试制度； （四）具有与培训规模和培训专业相适应的专（兼）职教员队伍； （五）有同时培训二百人以上规模的固定教学场所、训练场地，具有满足技能培训需要的消防设施、设备和器材； （六）消防安全专业培训需要的其他条件。 前款第（四）项所指专（兼）职教员队伍中，专职教员应当不少于教员总数的二分之一；具有建筑、消防等相关专业中级以上职称，并有五年以上消防相关工作经历的教员不少于十人；消防安全管理、自动消防设施、灭火救援等专业课程应当分别配备理论教员和实习操作教员不少于两人。"},{"i":29,"n":"第二十九条","txt":"申请成立消防安全专业培训机构，依照国家有关法律法规，应当向省级教育行政部门或者人力资源和社会保障部门申请。 省级教育行政部门或者人力资源和社会保障部门受理申请后，可以征求同级公安机关消防机构的意见。 省级公安机关消防机构收到省级教育行政部门或者人力资源和社会保障部门移送的申请材料后，应当配合对申请成立消防安全培训专业机构的师资条件、场地和设施、设备、器材等进行核查，并出具书面意见。 教育行政部门或者人力资源和社会保障部门根据有关民办职业培训机构的规定，并综合公安机关消防机构出具的书面意见进行评定，符合条件的予以批准，并向社会公告。"},{"i":30,"n":"第三十条","txt":"消防安全专业培训机构应当按照有关法律法规、规章和章程规定，开展消防安全专业培训，保证培训质量。 消防安全专业培训机构开展消防安全专业培训，应当将消防安全管理、建筑防火和自动消防设施施工、操作、检测、维护技能作为培训的重点，对经理论和技能操作考核合格的人员，颁发培训证书。 消防安全专业培训的收费标准，应当符合国家有关规定，并向社会公布。"},{"i":31,"n":"第三十一条","txt":"省级教育行政部门或者人力资源和社会保障部门应当依法对消防安全专业培训机构进行管理，监督、指导消防安全专业培训机构依法开展活动。 省级教育行政部门或者人力资源和社会保障部门应当对消防安全专业培训机构定期组织质量评估，并向社会公布监督评估情况。省级教育行政部门或者人力资源和社会保障部门在对消防安全专业培训机构进行质量评估时，可以邀请公安机关消防机构专业人员参加。"},{"i":32,"n":"第三十二条","txt":"地方各级人民政府及有关部门对在消防安全教育培训工作中有突出贡献或者成绩显著的单位和个人，应当给予表彰奖励。 单位对消防安全教育培训工作成绩突出的职工，应当给予表彰奖励。"},{"i":33,"n":"第三十三条","txt":"地方各级人民政府公安、教育、民政、人力资源和社会保障、住房和城乡建设、文化、广电、安全监管、旅游、文物等部门不依法履行消防安全教育培训工作职责的，上级部门应当给予批评；对直接责任人员由上级部门和所在单位视情节轻重，根据权限依法给予批评教育或者建议有权部门给予处分。 公安机关消防机构工作人员在协助审查消防安全专业培训机构的工作中疏于职守的，由上级机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":34,"n":"第三十四条","txt":"学校未按照本规定第十五条、第十六条、第十七条、第十八条规定开展消防安全教育工作的，教育、公安、人力资源和社会保障等主管部门应当按照职责分工责令其改正，并视情对学校负责人和其他直接责任人员给予处分。"},{"i":35,"n":"第三十五条","txt":"单位违反本规定，构成违反消防管理行为的，由公安机关消防机构依照《中华人民共和国消防法》予以处罚。"},{"i":36,"n":"第三十六条","txt":"社会组织或者个人未经批准擅自举办消防安全专业培训机构的，或者消防安全专业培训机构在培训活动中有违法违规行为的，由教育、人力资源和社会保障、民政等部门依据各自职责依法予以处理。"},{"i":37,"n":"第三十七条","txt":"全国统一的消防安全教育培训大纲由公安部会同教育部、人力资源和社会保障部共同制定。"}],"zulinfangwuzhianguanliguiding":[{"i":1,"n":"第一条","txt":"为加强租赁房屋的治安管理，做好安全防范，保护租赁双方的合法权益，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的租赁房屋，是指旅馆业以外以营利为目的，公民私有和单位所有出租用于他人居住的房屋。"},{"i":3,"n":"第三条","txt":"公安机关对租赁房屋实行治安管理，建立登记、安全检查等管理制度。"},{"i":4,"n":"第四条","txt":"城镇街道居民委员会、村民委员会及其治安保卫委员会，应当协助公安机关做好租赁房屋的安全防范、法制宣传教育和治安管理工作。"},{"i":5,"n":"第五条","txt":"出租的房屋，其建筑、消防设备、出入口和通道等，必须符合消防安全和治安管理规定；危险和违章建筑的房屋，不准出租。"},{"i":6,"n":"第六条","txt":"私有房屋出租的，出租人须持房屋所有权证或者其他合法证明、居民身份证、户口簿，向房屋所在地公安派出所申请登记；单位房屋出租的，出租人须持房屋所有权证、单位介绍信，到房屋所在地公安派出所申请登记，经审核符合本规定出租条件的，由出租人向公安派出所签订治安责任保证书。"},{"i":7,"n":"第七条","txt":"房屋出租人的治安责任： （一）不准将房屋出租给无合法有效证件的承租人； （二）与承租人签订租赁合同，承租人是外来暂住人员的，应当带领其到公安派出所申报暂住户口登记，并办理暂住证； （三）对承租人的姓名、性别、年龄、常住户口所在地、职业或者主要经济来源、服务处所等基本情况进行登记并向公安派出所备案； （四）发现承租人有违法犯罪活动或者有违法犯罪嫌疑的，应当及时报告公安机关； （五）对出租的房屋经常进行安全检查，及时发现和排除不安全隐患，保障承租人的居住安全； （六）房屋停止租赁的，应当到公安派出所办理注销手续； （七）房屋出租单位或者个人委托代理人管理出租房屋的，代理人必须遵守有关规定，承担相应责任。"},{"i":8,"n":"第八条","txt":"房屋承租人的治安责任： （一）必须持有本人居民身份证或者其他合法身份证件； （二）租赁房屋住宿的外来暂住人员，必须按户口管理规定，在三日内到公安派出所申请暂住户口登记； （三）将承租房屋转租或者转借他人的，应当向当地公安派出所申报备案； （四）安全使用出租房屋，发现承租房屋有不安全隐患，应当及时告知出租人予以消除； （五）承租的房屋不准用于生产、储存、经营易燃、易爆、有毒等危险物品； （六）集体承租或者单位承租房屋的，应当建立安全管理制度。"},{"i":9,"n":"第九条","txt":"违反本规定的行为，由县（市）公安局或者城市公安分局予以处罚： （一）出租人未向公安机关办理登记手续或者未签定治安责任保证书出租房屋的，责令限期补办手续并没收非法所得，情节严重的可以并处月租金五倍以下的罚款； （二）出租人将房屋出租给无合法有效证件承租人的，处以警告、月租金三倍以下的罚款； （三）出租人不履行治安责任，发现承租人利用所租房屋进行违法犯罪活动或者有违法犯罪嫌疑不制止、不报告，或者发生案件、治安灾害事故的，责令停止出租，可以并处月租金十倍以下的罚款； （四）承租人将承租房屋转租、转借他人未按规定报告公安机关的，处以警告，没收非法所得； （五）承租人利用出租房屋非法生产、储存、经营易燃、易爆、有毒等危险物品的，没收物品，处月租金十倍以下罚款。"},{"i":10,"n":"第十条","txt":"对出租或承租的单位违反规定的，依照本规定第九条由县（市）公安局或者城市公安分局予以处罚，同时对单位的主管负责人或者直接责任人处以月工资两倍以下的罚款。"},{"i":11,"n":"第十一条","txt":"违反本规定构成违反治安管理行为的，依照《中华人民共和国治安管理处罚条例》有关规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"被处罚人和单位对依照本规定作出的处罚决定不服的，可以依照《行政复议条例》的有关规定向上一级公安机关申请复议。复议期间，不停止处罚决定的执行。"},{"i":13,"n":"第十三条","txt":"各省、自治区、直辖市公安厅、局可以依据本规定制定实施办法。"},{"i":14,"n":"第十四条","txt":"本规定自发布之日起施行。"}],"jingcheguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对警车使用的管理，保障公安机关、国家安全机关、监狱、劳动教养管理机关的人民警察和人民法院、人民检察院的司法警察依法执行紧急职务，根据《中华人民共和国人民警察法》、《中华人民共和国道路交通安全法》及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称警车，是指公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院用于执行紧急职务的机动车辆。警车包括： （一）公安机关用于执行侦查、警卫、治安、交通管理的巡逻车、勘察车、护卫车、囚车以及其他执行职务的车辆； （二）国家安全机关用于执行侦查任务和其他特殊职务的车辆； （三）监狱、劳动教养管理机关用于押解罪犯、运送劳教人员的囚车和追缉逃犯的车辆； （四）人民法院用于押解犯罪嫌疑人和罪犯的囚车、刑场指挥车、法医勘察车和死刑执行车； （五）人民检察院用于侦查刑事犯罪案件的现场勘察车和押解犯罪嫌疑人的囚车。"},{"i":3,"n":"第三条","txt":"警车车型由公安部统一确定。汽车为大、中、小、微型客车和执行紧急救援、现场处置等专门用途的车辆；摩托车为二轮摩托车和侧三轮摩托车。"},{"i":4,"n":"第四条","txt":"警车应当采用全国统一的外观制式。 警车外观制式采用白底，由专用的图形、车徽、编号、汉字“警察”和部门的汉字简称以及英文“POLICE”等要素构成。各要素的形状、颜色、规格、位置、字体、字号、材质等应当符合警车外观制式涂装规范和涂装用定色漆等行业标准。 公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院的部门汉字简称分别为“公安”、“国安”、“司法”和“法院”、“检察”。"},{"i":5,"n":"第五条","txt":"警车应当安装固定式警用标志灯具。汽车的标志灯具安装在驾驶室顶部；摩托车的标志灯具安装在后轮右侧。警用标志灯具及安装应当符合特种车辆标志灯具的国家标准。"},{"i":6,"n":"第六条","txt":"警车应当安装警用警报器。警车警报器应当符合车用电子警报器的国家标准。"},{"i":7,"n":"第七条","txt":"警车号牌分为汽车、摩托车两种。均为铝质材，底色为白底反光。号牌应当符合《警车号牌式样》和机动车号牌的行业标准。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市公安厅、局对警车实行定编管理，统一确定警车的编号，并建立管理档案。"},{"i":9,"n":"第九条","txt":"公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院申请办理警车注册登记，应当填写《警车号牌审批表》，提交法定证明、凭证，由本部门所在的设区的市或者相当于同级的主管机关汇总后送当地同级公安机关审查后，报省、自治区、直辖市公安厅、局审批。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市公安厅、局交通管理部门负责办理警车登记业务，核发警车号牌、行驶证和登记证书。警车的登记信息应当进入全国公安交通管理信息系统。 领取警车牌证前，已有民用机动车牌证的，应当将民用机动车牌证交回原发证机关。"},{"i":11,"n":"第十一条","txt":"警车号牌的安装应当符合民用机动车号牌的安装要求。其中，汽车号牌应当在车身前、后部各安装一面；摩托车号牌应当在车身后部安装一面。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市公安厅、局交通管理部门办理警车注册登记时，应当对申请警车号牌的机动车进行审查。审查内容除按民用机动车要求外，还应当审查警车车型、外观制式、标志灯具和警报器是否符合有关规范和标准。"},{"i":13,"n":"第十三条","txt":"警车应当按照法律、法规规定进行机动车安全技术检验。省、自治区公安机关交通管理部门可以委托设区的市公安机关交通管理部门核发机动车检验合格标志。"},{"i":14,"n":"第十四条","txt":"公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院应当严格管理本部门的警车。警车除执行本规定第二条所列任务外，不得挪作他用。 警车应当由警车所属单位的人民警察驾驶，驾驶警车时应当按照规定着制式警服（驾驶汽车可不戴警帽，驾驶摩托车应当戴制式警用安全头盔），持有机动车驾驶证和人民警察证。驾驶实习期内的人民警察不得驾驶警车。 人民警察驾驶警车到异地执行职务的，应当遵守有关办案协作的规定。"},{"i":15,"n":"第十五条","txt":"警车在道路上行驶应当遵守《中华人民共和国道路交通安全法》及其实施条例和其他有关法规的规定，服从交通警察的指挥和检查。"},{"i":16,"n":"第十六条","txt":"警车执行下列任务时可以使用警用标志灯具、警报器： （一）赶赴刑事案件、治安案件、交通事故及其他突发事件现场； （二）追捕犯罪嫌疑人和在逃的罪犯、劳教人员； （三）追缉交通肇事逃逸车辆和人员； （四）押解犯罪嫌疑人、罪犯和劳教人员； （五）执行警卫、警戒和治安、交通巡逻等任务。"},{"i":17,"n":"第十七条","txt":"除护卫国宾车队、追捕现行犯罪嫌疑人、赶赴突发事件现场外，驾驶警车的人民警察在使用警用标志灯具、警报器时，应当遵守下列规定： （一）一般情况下，只使用警用标志灯具；通过车辆、人员繁杂的路段、路口或者警告其他车辆让行时，可以断续使用警报器； （二）两辆以上警车列队行驶时，前车如使用警报器，后车不得再使用警报器； （三）在公安机关明令禁止鸣警报器的道路或者区域内不得使用警报器。"},{"i":18,"n":"第十八条","txt":"警车执行紧急任务使用警用标志灯具、警报器时，享有优先通行权；警车及其护卫的车队，在确保安全的原则下，可以不受行驶路线、行驶方向、行驶速度和交通信号灯、交通标志标线的限制。 遇使用警用标志灯具、警报器的警车及其护卫的车队，其他车辆和人员应当立即避让；交通警察在保证交通安全的前提下，应当提供优先通行的便利。"},{"i":19,"n":"第十九条","txt":"警车牌证遗失或者损坏的，应当及时按申办途径报告原发牌机关，申请补发。 警车转为民用机动车的，应当拆除警用标志灯具和警报器，清除车身警用外观制式，收回警车号牌，并办理相关变更、转移登记手续。 警车达到国家规定的强制报废标准的，应当按照法律、法规规定报废。"},{"i":20,"n":"第二十条","txt":"严禁转借警车，严禁伪造、涂改、冒领、挪用警车牌证。"},{"i":21,"n":"第二十一条","txt":"公安机关、国家安全机关、监狱、劳动教养管理机关和人民法院、人民检察院应当制定本部门警车的使用管理规定，并对本部门警车的管理和使用情况进行监督检查。 公安机关警务督察部门应当对公安机关警车的管理和使用情况进行监督检查。 公安机关交通管理部门在执勤执法、核发机动车检验合格标志等工作中，应当对警车外观制式的完整性进行检查，并对违反警车管理和使用规定的行为向有关部门报告。"},{"i":22,"n":"第二十二条","txt":"对非法涂装警车外观制式，非法安装警用标志灯具、警报器，非法生产、买卖、使用以及伪造、涂改、冒领警车牌证的，依据《中华人民共和国人民警察法》、《中华人民共和国道路交通安全法》和《中华人民共和国治安管理处罚法》的有关规定处罚，强制拆除、收缴警用标志灯具、警报器和警车牌证，并予以治安处罚；构成犯罪的，依法追究当事人的刑事责任。"},{"i":23,"n":"第二十三条","txt":"违反本规定，有下列情形之一的，依据《中华人民共和国人民警察法》和《中华人民共和国道路交通安全法》及相关规定，对有关人员给予处分： （一）不按规定审批和核发警车牌证的； （二）不按规定涂装全国统一的警车外观制式的； （三）驾驶警车时不按规定着装、携带机动车驾驶证、人民警察证的； （四）滥用警用标志灯具、警报器的； （五）不按规定使用警车或者转借警车的； （六）不按规定办理警车变更、转移登记手续的； （七）挪用、转借警车牌证的； （八）其他违反本规定的行为。"},{"i":24,"n":"第二十四条","txt":"本规定自发布之日起施行。公安部 1995年6月29日 发布的《警车管理规定》（公安部令第27号）同时废止。公安部此前发布的其他规定与本规定不一致的，以本规定为准。 附件1  警车号牌审批表 附件2  警车号牌式样  一、警用汽车号牌  警用汽车号牌为单排结构，尺寸为 440mm × 140mm ，分为前、后两块号牌。颜色为白底（反光）黑字。号牌的登记编号由七位字符构成：第一位为省、自治区、直辖市简称；第二位为字母表示地区；第三位为A、B、C、D和阿拉伯数字，分别表示法院、检察院、国家安全机关、监狱、劳动教养管理机关、公安机关；第四位至第六位为注册编号；第七位为红色反光“警”。第一与第二位之间为间隔符，前号牌间隔符为圆点（警车号牌专用准产标记），后号牌间隔符为横杠。数码和间隔符横杠为黑色。 二、警用摩托车号牌为双排结构，尺寸为 220mm × 140mm 。第一位至第二位在上排，第三位至"}],"jisuanjibingdufangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对计算机病毒的预防和治理，保护计算机信息系统安全，保障计算机的应用与发展，根据《中华人民共和国计算机信息系统安全保护条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的计算机病毒，是指编制或者在计算机程序中插入的破坏计算机功能或者毁坏数据，影响计算机使用，并能自我复制的一组计算机指令或者程序代码。"},{"i":3,"n":"第三条","txt":"中华人民共和国境内的计算机信息系统以及未联网计算机的计算机病毒防治管理工作，适用本办法。"},{"i":4,"n":"第四条","txt":"公安部公共信息网络安全监察部门主管全国的计算机病毒防治管理工作。 地方各级公安机关具体负责本行政区域内的计算机病毒防治管理工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人不得制作计算机病毒。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得有下列传播计算机病毒的行为： （一）故意输入计算机病毒，危害计算机信息系统安全； （二）向他人提供含有计算机病毒的文件、软件、媒体； （三）销售、出租、附赠含有计算机病毒的媒体； （四）其他传播计算机病毒的行为。"},{"i":7,"n":"第七条","txt":"任何单位和个人不得向社会发布虚假的计算机病毒疫情。"},{"i":8,"n":"第八条","txt":"从事计算机病毒防治产品生产的单位，应当及时向公安部公共信息网络安全监察部门批准的计算机病毒防治产品检测机构提交病毒样本。"},{"i":9,"n":"第九条","txt":"计算机病毒防治产品检测机构应当对提交的病毒样本及时进行分析、确认，并将确认结果上报公安部公共信息网络安全监察部门。"},{"i":10,"n":"第十条","txt":"对计算机病毒的认定工作，由公安部公共信息网络安全监察部门批准的机构承担。"},{"i":11,"n":"第十一条","txt":"计算机信息系统的使用单位在计算机病毒防治工作中应当履行下列职责： （一）建立本单位的计算机病毒防治管理制度； （二）采取计算机病毒安全技术防治措施； （三）对本单位计算机信息系统使用人员进行计算机病毒防治教育和培训； （四）及时检测、清除计算机信息系统中的计算机病毒，并备有检测、清除的记录； （五）使用具有计算机信息系统安全专用产品销售许可证的计算机病毒防治产品； （六）对因计算机病毒引起的计算机信息系统瘫痪、程序和数据严重破坏等重大事故及时向公安机关报告，并保护现场。"},{"i":12,"n":"第十二条","txt":"任何单位和个人在从计算机信息网络上下载程序、数据或者购置、维修、借入计算机设备时，应当进行计算机病毒检测。"},{"i":13,"n":"第十三条","txt":"任何单位和个人销售、附赠的计算机病毒防治产品，应当具有计算机信息系统安全专用产品销售许可证，并贴有“销售许可”标记。"},{"i":14,"n":"第十四条","txt":"从事计算机设备或者媒体生产、销售、出租、维修行业的单位和个人，应当对计算机设备或者媒体进行计算机病毒检测、清除工作，并备有检测、清除的记录。"},{"i":15,"n":"第十五条","txt":"任何单位和个人应当接受公安机关对计算机病毒防治工作的监督、检查和指导。"},{"i":16,"n":"第十六条","txt":"在非经营活动中有违反本办法第五条、第六条第二、三、四项规定行为之一的，由公安机关处以一千元以下罚款。 在经营活动中有违反本办法第五条、第六条第二、三、四项规定行为之一，没有违法所得的，由公安机关对单位处以一万元以下罚款，对个人处以五千元以下罚款；有违法所得的，处以违法所得三倍以下罚款，但是最高不得超过三万元。 违反本办法第六条第一项规定的，依照《中华人民共和国计算机信息系统安全保护条例》第二十三条的规定处罚。"},{"i":17,"n":"第十七条","txt":"违反本办法第七条、第八条规定行为之一的，由公安机关对单位处以一千元以下罚款，对单位直接负责的主管人员和直接责任人员处以五百元以下罚款；对个人处以五百元以下罚款。"},{"i":18,"n":"第十八条","txt":"违反本办法第九条规定的，由公安机关处以警告，并责令其限期改正；逾期不改正的，取消其计算机病毒防治产品检测机构的检测资格。"},{"i":19,"n":"第十九条","txt":"计算机信息系统的使用单位有下列行为之一的，由公安机关处以警告，并根据情况责令其限期改正；逾期不改正的，对单位处以一千元以下罚款，对单位直接负责的主管人员和直接责任人员处以五百元以下罚款： （一）未建立本单位计算机病毒防治管理制度的； （二）未采取计算机病毒安全技术防治措施的； （三）未对本单位计算机信息系统使用人员进行计算机病毒防治教育和培训的； （四）未及时检测、清除计算机信息系统中的计算机病毒，对计算机信息系统造成危害的； （五）未使用具有计算机信息系统安全专用产品销售许可证的计算机病毒防治产品，对计算机信息系统造成危害的。"},{"i":20,"n":"第二十条","txt":"违反本办法第十四条规定，没有违法所得的，由公安机关对单位处以一万元以下罚款，对个人处以五千元以下罚款；有违法所得的，处以违法所得三倍以下罚款，但是最高不得超过三万元。"},{"i":21,"n":"第二十一条","txt":"本办法所称计算机病毒疫情，是指某种计算机病毒爆发、流行的时间、范围、破坏特点、破坏后果等情况的报告或者预报。 本办法所称媒体，是指计算机软盘、硬盘、磁带、光盘等。"},{"i":22,"n":"第二十二条","txt":"办法自发布之日起施行。"}],"daolujiaotongshiguchulichengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范道路交通事故处理程序，保障公安机关交通管理部门依法履行职责，保护道路交通事故当事人的合法权益，根据《中华人民共和国道路交通安全法》及其实施条例等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"处理道路交通事故，应当遵循合法、公正、公开、便民、效率的原则，尊重和保障人权，保护公民的人格尊严。"},{"i":3,"n":"第三条","txt":"道路交通事故分为财产损失事故、伤人事故和死亡事故。 财产损失事故是指造成财产损失，尚未造成人员伤亡的道路交通事故。 伤人事故是指造成人员受伤，尚未造成人员死亡的道路交通事故。 死亡事故是指造成人员死亡的道路交通事故。"},{"i":4,"n":"第四条","txt":"道路交通事故的调查处理应当由公安机关交通管理部门负责。 财产损失事故可以由当事人自行协商处理，但法律法规及本规定另有规定的除外。"},{"i":5,"n":"第五条","txt":"交通警察经过培训并考试合格，可以处理适用简易程序的道路交通事故。 处理伤人事故，应当由具有道路交通事故处理初级以上资格的交通警察主办。 处理死亡事故，应当由具有道路交通事故处理中级以上资格的交通警察主办。"},{"i":6,"n":"第六条","txt":"公安机关交通管理部门处理道路交通事故应当使用全国统一的交通管理信息系统。 鼓励应用先进的科技装备和先进技术处理道路交通事故。"},{"i":7,"n":"第七条","txt":"交通警察处理道路交通事故，应当按照规定使用执法记录设备。"},{"i":8,"n":"第八条","txt":"公安机关交通管理部门应当建立与司法机关、保险机构等有关部门间的数据信息共享机制，提高道路交通事故处理工作信息化水平。"},{"i":9,"n":"第九条","txt":"道路交通事故由事故发生地的县级公安机关交通管理部门管辖。未设立县级公安机关交通管理部门的，由设区的市公安机关交通管理部门管辖。"},{"i":10,"n":"第十条","txt":"道路交通事故发生在两个以上管辖区域的，由事故起始点所在地公安机关交通管理部门管辖。 对管辖权有争议的，由共同的上一级公安机关交通管理部门指定管辖。指定管辖前，最先发现或者最先接到报警的公安机关交通管理部门应当先行处理。"},{"i":11,"n":"第十一条","txt":"上级公安机关交通管理部门在必要的时候，可以处理下级公安机关交通管理部门管辖的道路交通事故，或者指定下级公安机关交通管理部门限时将案件移送其他下级公安机关交通管理部门处理。 案件管辖权发生转移的，处理时限从案件接收之日起计算。"},{"i":12,"n":"第十二条","txt":"中国人民解放军、中国人民武装警察部队人员、车辆发生道路交通事故的，按照本规定处理。依法应当吊销、注销中国人民解放军、中国人民武装警察部队核发的机动车驾驶证以及对现役军人实施行政拘留或者追究刑事责任的，移送中国人民解放军、中国人民武装警察部队有关部门处理。 上道路行驶的拖拉机发生道路交通事故的，按照本规定处理。公安机关交通管理部门对拖拉机驾驶人依法暂扣、吊销、注销驾驶证或者记分处理的，应当将决定书和记分情况通报有关的农业（农业机械）主管部门。吊销、注销驾驶证的，还应当将驾驶证送交有关的农业（农业机械）主管部门。"},{"i":13,"n":"第十三条","txt":"发生死亡事故、伤人事故的，或者发生财产损失事故且有下列情形之一的，当事人应当保护现场并立即报警： （一）驾驶人无有效机动车驾驶证或者驾驶的机动车与驾驶证载明的准驾车型不符的； （二）驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的； （三）驾驶人有从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶嫌疑的； （四）机动车无号牌或者使用伪造、变造的号牌的； （五）当事人不能自行移动车辆的; （六）一方当事人离开现场的； （七）有证据证明事故是由一方故意造成的。 驾驶人必须在确保安全的原则下，立即组织车上人员疏散到路外安全地点，避免发生次生事故。驾驶人已因道路交通事故死亡或者受伤无法行动的，车上其他人员应当自行组织疏散。"},{"i":14,"n":"第十四条","txt":"发生财产损失事故且有下列情形之一，车辆可以移动的，当事人应当组织车上人员疏散到路外安全地点，在确保安全的原则下，采取现场拍照或者标划事故车辆现场位置等方式固定证据，将车辆移至不妨碍交通的地点后报警： （一）机动车无检验合格标志或者无保险标志的； （二）碰撞建筑物、公共设施或者其他设施的。"},{"i":15,"n":"第十五条","txt":"载运爆炸性、易燃性、毒害性、放射性、腐蚀性、传染病病原体等危险物品车辆发生事故的，当事人应当立即报警，危险物品车辆驾驶人、押运人应当按照危险物品安全管理法律、法规、规章以及有关操作规程的规定，采取相应的应急处置措施。"},{"i":16,"n":"第十六条","txt":"公安机关及其交通管理部门接到报警的，应当受理，制作受案登记表并记录下列内容： （一）报警方式、时间，报警人姓名、联系方式，电话报警的，还应当记录报警电话； （二）发生或者发现道路交通事故的时间、地点； （三）人员伤亡情况； （四）车辆类型、车辆号牌号码，是否载有危险物品以及危险物品的种类、是否发生泄漏等； （五）涉嫌交通肇事逃逸的，还应当询问并记录肇事车辆的车型、颜色、特征及其逃逸方向、逃逸驾驶人的体貌特征等有关情况。 报警人不报姓名的，应当记录在案。报警人不愿意公开姓名的，应当为其保密。"},{"i":17,"n":"第十七条","txt":"接到道路交通事故报警后，需要派员到现场处置,或者接到出警指令的，公安机关交通管理部门应当立即派交通警察赶赴现场。"},{"i":18,"n":"第十八条","txt":"发生道路交通事故后当事人未报警，在事故现场撤除后，当事人又报警请求公安机关交通管理部门处理的，公安机关交通管理部门应当按照本规定第十六条规定的记录内容予以记录，并在三日内作出是否接受案件的决定。 经核查道路交通事故事实存在的，公安机关交通管理部门应当受理，制作受案登记表；经核查无法证明道路交通事故事实存在，或者不属于公安机关交通管理部门管辖的，应当书面告知当事人，并说明理由。"},{"i":19,"n":"第十九条","txt":"机动车与机动车、机动车与非机动车发生财产损失事故，当事人应当在确保安全的原则下，采取现场拍照或者标划事故车辆现场位置等方式固定证据后，立即撤离现场，将车辆移至不妨碍交通的地点，再协商处理损害赔偿事宜，但有本规定第十三条第一款情形的除外。 非机动车与非机动车或者行人发生财产损失事故，当事人应当先撤离现场，再协商处理损害赔偿事宜。 对应当自行撤离现场而未撤离的，交通警察应当责令当事人撤离现场；造成交通堵塞的，对驾驶人处以200元罚款。"},{"i":20,"n":"第二十条","txt":"发生可以自行协商处理的财产损失事故，当事人可以通过互联网在线自行协商处理；当事人对事实及成因有争议的，可以通过互联网共同申请公安机关交通管理部门在线确定当事人的责任。 当事人报警的，交通警察、警务辅助人员可以指导当事人自行协商处理。当事人要求交通警察到场处理的，应当指派交通警察到现场调查处理。"},{"i":21,"n":"第二十一条","txt":"当事人自行协商达成协议的，制作道路交通事故自行协商协议书，并共同签名。道路交通事故自行协商协议书应当载明事故发生的时间、地点、天气、当事人姓名、驾驶证号或者身份证号、联系方式、机动车种类和号牌号码、保险公司、保险凭证号、事故形态、碰撞部位、当事人的责任等内容。"},{"i":22,"n":"第二十二条","txt":"当事人自行协商达成协议的，可以按照下列方式履行道路交通事故损害赔偿： （一）当事人自行赔偿； （二）到投保的保险公司或者道路交通事故保险理赔服务场所办理损害赔偿事宜。 当事人自行协商达成协议后未履行的，可以申请人民调解委员会调解或者向人民法院提起民事诉讼。"},{"i":23,"n":"第二十三条","txt":"公安机关交通管理部门可以适用简易程序处理以下道路交通事故，但有交通肇事、危险驾驶犯罪嫌疑的除外： （一）财产损失事故； （二）受伤当事人伤势轻微，各方当事人一致同意适用简易程序处理的伤人事故。 适用简易程序的，可以由一名交通警察处理。"},{"i":24,"n":"第二十四条","txt":"交通警察适用简易程序处理道路交通事故时，应当在固定现场证据后，责令当事人撤离现场，恢复交通。拒不撤离现场的，予以强制撤离。当事人无法及时移动车辆影响通行和交通安全的，交通警察应当将车辆移至不妨碍交通的地点。具有本规定第十三条第一款第一项、第二项情形之一的，按照《中华人民共和国道路交通安全法实施条例》第一百零四条规定处理。 撤离现场后，交通警察应当根据现场固定的证据和当事人、证人陈述等，认定并记录道路交通事故发生的时间、地点、天气、当事人姓名、驾驶证号或者身份证号、联系方式、机动车种类和号牌号码、保险公司、保险凭证号、道路交通事故形态、碰撞部位等，并根据本规定第六十条确定当事人的责任，当场制作道路交通事故认定书。不具备当场制作条件的，交通警察应当在三日内制作道路交通事故认定书。 道路交通事故认定书应当由当事人签名，并现场送达当事人。当事人拒绝签名或者接收的，交通警察应当在道路交通事故认定"},{"i":25,"n":"第二十五条","txt":"当事人共同请求调解的，交通警察应当当场进行调解，并在道路交通事故认定书上记录调解结果，由当事人签名，送达当事人。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，不适用调解，交通警察可以在道路交通事故认定书上载明有关情况后，将道路交通事故认定书送达当事人： （一）当事人对道路交通事故认定有异议的； （二）当事人拒绝在道路交通事故认定书上签名的； （三）当事人不同意调解的。"},{"i":27,"n":"第二十七条","txt":"除简易程序外，公安机关交通管理部门对道路交通事故进行调查时，交通警察不得少于二人。 交通警察调查时应当向被调查人员出示《人民警察证》，告知被调查人依法享有的权利和义务，向当事人发送联系卡。联系卡载明交通警察姓名、办公地址、联系方式、监督电话等内容。"},{"i":28,"n":"第二十八条","txt":"交通警察调查道路交通事故时，应当合法、及时、客观、全面地收集证据。"},{"i":29,"n":"第二十九条","txt":"对发生一次死亡三人以上道路交通事故的，公安机关交通管理部门应当开展深度调查；对造成其他严重后果或者存在严重安全问题的道路交通事故，可以开展深度调查。具体程序另行规定。"},{"i":30,"n":"第三十条","txt":"交通警察到达事故现场后，应当立即进行下列工作： （一）按照事故现场安全防护有关标准和规范的要求划定警戒区域，在安全距离位置放置发光或者反光锥筒和警告标志，确定专人负责现场交通指挥和疏导。因道路交通事故导致交通中断或者现场处置、勘查需要采取封闭道路等交通管制措施的，还应当视情在事故现场来车方向提前组织分流，放置绕行提示标志； （二）组织抢救受伤人员； （三）指挥救护、勘查等车辆停放在安全和便于抢救、勘查的位置，开启警灯，夜间还应当开启危险报警闪光灯和示廓灯； （四）查找道路交通事故当事人和证人，控制肇事嫌疑人； （五）其他需要立即开展的工作。"},{"i":31,"n":"第三十一条","txt":"道路交通事故造成人员死亡的，应当经急救、医疗人员或者法医确认，并由具备资质的医疗机构出具死亡证明。尸体应当存放在殡葬服务单位或者医疗机构等有停尸条件的场所。"},{"i":32,"n":"第三十二条","txt":"交通警察应当对事故现场开展下列调查工作： （一）勘查事故现场，查明事故车辆、当事人、道路及其空间关系和事故发生时的天气情况； （二）固定、提取或者保全现场证据材料； （三）询问当事人、证人并制作询问笔录；现场不具备制作询问笔录条件的，可以通过录音、录像记录询问过程； （四）其他调查工作。"},{"i":33,"n":"第三十三条","txt":"交通警察勘查道路交通事故现场，应当按照有关法规和标准的规定，拍摄现场照片，绘制现场图，及时提取、采集与案件有关的痕迹、物证等，制作现场勘查笔录。现场勘查过程中发现当事人涉嫌利用交通工具实施其他犯罪的，应当妥善保护犯罪现场和证据，控制犯罪嫌疑人，并立即报告公安机关主管部门。 发生一次死亡三人以上事故的，应当进行现场摄像，必要时可以聘请具有专门知识的人参加现场勘验、检查。 现场图、现场勘查笔录应当由参加勘查的交通警察、当事人和见证人签名。当事人、见证人拒绝签名或者无法签名以及无见证人的，应当记录在案。"},{"i":34,"n":"第三十四条","txt":"痕迹、物证等证据可能因时间、地点、气象等原因导致改变、毁损、灭失的，交通警察应当及时固定、提取或者保全。 对涉嫌饮酒或者服用国家管制的精神药品、麻醉药品驾驶车辆的人员，公安机关交通管理部门应当按照《道路交通安全违法行为处理程序规定》及时抽血或者提取尿样等检材，送交有检验鉴定资质的机构进行检验。 车辆驾驶人员当场死亡的，应当及时抽血检验。不具备抽血条件的，应当由医疗机构或者鉴定机构出具证明。"},{"i":35,"n":"第三十五条","txt":"交通警察应当核查当事人的身份证件、机动车驾驶证、机动车行驶证、检验合格标志、保险标志等。 对交通肇事嫌疑人可以依法传唤。对在现场发现的交通肇事嫌疑人，经出示《人民警察证》，可以口头传唤，并在询问笔录中注明嫌疑人到案经过、到案时间和离开时间。"},{"i":36,"n":"第三十六条","txt":"勘查事故现场完毕后，交通警察应当清点并登记现场遗留物品，迅速组织清理现场，尽快恢复交通。 现场遗留物品能够当场发还的，应当当场发还并做记录；当场无法确定所有人的，应当登记，并妥善保管，待所有人确定后，及时发还。"},{"i":37,"n":"第三十七条","txt":"因调查需要，公安机关交通管理部门可以向有关单位、个人调取汽车行驶记录仪、卫星定位装置、技术监控设备的记录资料以及其他与事故有关的证据材料。"},{"i":38,"n":"第三十八条","txt":"因调查需要，公安机关交通管理部门可以组织道路交通事故当事人、证人对肇事嫌疑人、嫌疑车辆等进行辨认。 辨认应当在交通警察的主持下进行。主持辨认的交通警察不得少于二人。多名辨认人对同一辨认对象进行辨认时，应当由辨认人个别进行。 辨认时，应当将辨认对象混杂在特征相类似的其他对象中，不得给辨认人任何暗示。辨认肇事嫌疑人时，被辨认的人数不得少于七人；对肇事嫌疑人照片进行辨认的，不得少于十人的照片。辨认嫌疑车辆时，同类车辆不得少于五辆；对肇事嫌疑车辆照片进行辨认时，不得少于十辆的照片。 对尸体等特定辨认对象进行辨认，或者辨认人能够准确描述肇事嫌疑人、嫌疑车辆独有特征的，不受数量的限制。 对肇事嫌疑人的辨认，辨认人不愿意公开进行时，可以在不暴露辨认人的情况下进行，并应当为其保守秘密。 对辨认经过和结果，应当制作辨认笔录，由交通警察、辨认人、见证人签名。必要时，应当对辨认过程进行录音或者录像。"},{"i":39,"n":"第三十九条","txt":"因收集证据的需要，公安机关交通管理部门可以扣留事故车辆，并开具行政强制措施凭证。扣留的车辆应当妥善保管。 公安机关交通管理部门不得扣留事故车辆所载货物。对所载货物在核实重量、体积及货物损失后，通知机动车驾驶人或者货物所有人自行处理。无法通知当事人或者当事人不自行处理的，按照《公安机关办理行政案件程序规定》的有关规定办理。 严禁公安机关交通管理部门指定停车场停放扣留的事故车辆。"},{"i":40,"n":"第四十条","txt":"当事人涉嫌犯罪的，因收集证据的需要，公安机关交通管理部门可以依据《中华人民共和国刑事诉讼法》《公安机关办理刑事案件程序规定》，扣押机动车驾驶证等与事故有关的物品、证件，并按照规定出具扣押法律文书。扣押的物品应当妥善保管。 对扣押的机动车驾驶证等物品、证件，作为证据使用的，应当随案移送，并制作随案移送清单一式两份，一份留存，一份交人民检察院。对于实物不宜移送的，应当将其清单、照片或者其他证明文件随案移送。待人民法院作出生效判决后，按照人民法院的通知，依法作出处理。"},{"i":41,"n":"第四十一条","txt":"经过调查，不属于公安机关交通管理部门管辖的，应当将案件移送有关部门并书面通知当事人，或者告知当事人处理途径。 公安机关交通管理部门在调查过程中，发现当事人涉嫌交通肇事、危险驾驶犯罪的，应当按照《中华人民共和国刑事诉讼法》《公安机关办理刑事案件程序规定》立案侦查。发现当事人有其他违法犯罪嫌疑的，应当及时移送有关部门，移送不影响事故的调查和处理。"},{"i":42,"n":"第四十二条","txt":"投保机动车交通事故责任强制保险的车辆发生道路交通事故，因抢救受伤人员需要保险公司支付抢救费用的，公安机关交通管理部门应当书面通知保险公司。 抢救受伤人员需要道路交通事故社会救助基金垫付费用的，公安机关交通管理部门应当书面通知道路交通事故社会救助基金管理机构。 道路交通事故造成人员死亡需要救助基金垫付丧葬费用的，公安机关交通管理部门应当在送达尸体处理通知书的同时，告知受害人亲属向道路交通事故社会救助基金管理机构提出书面垫付申请。"},{"i":43,"n":"第四十三条","txt":"公安机关交通管理部门应当根据管辖区域和道路情况，制定交通肇事逃逸案件查缉预案，并组织专门力量办理交通肇事逃逸案件。 发生交通肇事逃逸案件后，公安机关交通管理部门应当立即启动查缉预案，布置警力堵截，并通过全国机动车缉查布控系统查缉。"},{"i":44,"n":"第四十四条","txt":"案发地公安机关交通管理部门可以通过发协查通报、向社会公告等方式要求协查、举报交通肇事逃逸车辆或者侦破线索。发出协查通报或者向社会公告时，应当提供交通肇事逃逸案件基本事实、交通肇事逃逸车辆情况、特征及逃逸方向等有关情况。 中国人民解放军和中国人民武装警察部队车辆涉嫌交通肇事逃逸的，公安机关交通管理部门应当通报中国人民解放军、中国人民武装警察部队有关部门。"},{"i":45,"n":"第四十五条","txt":"接到协查通报的公安机关交通管理部门，应当立即布置堵截或者排查。发现交通肇事逃逸车辆或者嫌疑车辆的，应当予以扣留，依法传唤交通肇事逃逸人或者与协查通报相符的嫌疑人，并及时将有关情况通知案发地公安机关交通管理部门。案发地公安机关交通管理部门应当立即派交通警察前往办理移交。"},{"i":46,"n":"第四十六条","txt":"公安机关交通管理部门查获交通肇事逃逸车辆或者交通肇事逃逸嫌疑人后，应当按原范围撤销协查通报，并通过全国机动车缉查布控系统撤销布控。"},{"i":47,"n":"第四十七条","txt":"公安机关交通管理部门侦办交通肇事逃逸案件期间，交通肇事逃逸案件的受害人及其家属向公安机关交通管理部门询问案件侦办情况的，除依法不应当公开的内容外，公安机关交通管理部门应当告知并做好记录。"},{"i":48,"n":"第四十八条","txt":"道路交通事故社会救助基金管理机构已经为受害人垫付抢救费用或者丧葬费用的，公安机关交通管理部门应当在交通肇事逃逸案件侦破后及时书面告知道路交通事故社会救助基金管理机构交通肇事逃逸驾驶人的有关情况。"},{"i":49,"n":"第四十九条","txt":"需要进行检验、鉴定的，公安机关交通管理部门应当按照有关规定，自事故现场调查结束之日起三日内委托具备资质的鉴定机构进行检验、鉴定。 尸体检验应当在死亡之日起三日内委托。对交通肇事逃逸车辆的检验、鉴定自查获肇事嫌疑车辆之日起三日内委托。 对现场调查结束之日起三日后需要检验、鉴定的，应当报经上一级公安机关交通管理部门批准。 对精神疾病的鉴定，由具有精神病鉴定资质的鉴定机构进行。"},{"i":50,"n":"第五十条","txt":"检验、鉴定费用由公安机关交通管理部门承担，但法律法规另有规定或者当事人自行委托伤残评定、财产损失评估的除外。"},{"i":51,"n":"第五十一条","txt":"公安机关交通管理部门应当与鉴定机构确定检验、鉴定完成的期限，确定的期限不得超过三十日。超过三十日的，应当报经上一级公安机关交通管理部门批准，但最长不得超过六十日。"},{"i":52,"n":"第五十二条","txt":"尸体检验不得在公众场合进行。为了确定死因需要解剖尸体的，应当征得死者家属同意。死者家属不同意解剖尸体的，经县级以上公安机关或者上一级公安机关交通管理部门负责人批准，可以解剖尸体，并且通知死者家属到场，由其在解剖尸体通知书上签名。 死者家属无正当理由拒不到场或者拒绝签名的，交通警察应当在解剖尸体通知书上注明。对身份不明的尸体，无法通知死者家属的，应当记录在案。"},{"i":53,"n":"第五十三条","txt":"尸体检验报告确定后，应当书面通知死者家属在十日内办理丧葬事宜。无正当理由逾期不办理的应记录在案，并经县级以上公安机关或者上一级公安机关交通管理部门负责人批准，由公安机关或者上一级公安机关交通管理部门处理尸体，逾期存放的费用由死者家属承担。 对于没有家属、家属不明或者因自然灾害等不可抗力导致无法通知或者通知后家属拒绝领回的，经县级以上公安机关或者上一级公安机关交通管理部门负责人批准，可以及时处理。 对身份不明的尸体，由法医提取人身识别检材，并对尸体拍照、采集相关信息后，由公安机关交通管理部门填写身份不明尸体信息登记表，并在设区的市级以上报纸刊登认尸启事。登报后三十日仍无人认领的，经县级以上公安机关或者上一级公安机关交通管理部门负责人批准，可以及时处理。 因宗教习俗等原因对尸体处理期限有特殊需要的，经县级以上公安机关或者上一级公安机关交通管理部门负责人批准，可以紧急处理。"},{"i":54,"n":"第五十四条","txt":"鉴定机构应当在规定的期限内完成检验、鉴定，并出具书面检验报告、鉴定意见，由鉴定人签名，鉴定意见还应当加盖机构印章。检验报告、鉴定意见应当载明以下事项： （一）委托人； （二）委托日期和事项； （三）提交的相关材料； （四）检验、鉴定的时间； （五）依据和结论性意见，通过分析得出结论性意见的，应当有分析证明过程。 检验报告、鉴定意见应当附有鉴定机构、鉴定人的资质证明或者其他证明文件。"},{"i":55,"n":"第五十五条","txt":"公安机关交通管理部门应当对检验报告、鉴定意见进行审核，并在收到检验报告、鉴定意见之日起五日内，将检验报告、鉴定意见复印件送达当事人，但有下列情形之一的除外： （一）检验、鉴定程序违法或者违反相关专业技术要求，可能影响检验报告、鉴定意见公正、客观的； （二）鉴定机构、鉴定人不具备鉴定资质和条件的; （三）检验报告、鉴定意见明显依据不足的； （四）故意作虚假鉴定的； （五）鉴定人应当回避而没有回避的； （六）检材虚假或者检材被损坏、不具备鉴定条件的； （七）其他可能影响检验报告、鉴定意见公正、客观的情形。 检验报告、鉴定意见有前款规定情形之一的，经县级以上公安机关交通管理部门负责人批准，应当在收到检验报告、鉴定意见之日起三日内重新委托检验、鉴定。"},{"i":56,"n":"第五十六条","txt":"当事人对检验报告、鉴定意见有异议，申请重新检验、鉴定的，应当自公安机关交通管理部门送达之日起三日内提出书面申请，经县级以上公安机关交通管理部门负责人批准，原办案单位应当重新委托检验、鉴定。检验报告、鉴定意见不具有本规定第五十五条第一款情形的，经县级以上公安机关交通管理部门负责人批准，由原办案单位作出不准予重新检验、鉴定的决定，并在作出决定之日起三日内书面通知申请人。 同一交通事故的同一检验、鉴定事项，重新检验、鉴定以一次为限。"},{"i":57,"n":"第五十七条","txt":"重新检验、鉴定应当另行委托鉴定机构。"},{"i":58,"n":"第五十八条","txt":"自检验报告、鉴定意见确定之日起五日内，公安机关交通管理部门应当通知当事人领取扣留的事故车辆。 因扣留车辆发生的费用由作出决定的公安机关交通管理部门承担，但公安机关交通管理部门通知当事人领取，当事人逾期未领取产生的停车费用由当事人自行承担。 经通知当事人三十日后不领取的车辆，经公告三个月仍不领取的，对扣留的车辆依法处理。"},{"i":59,"n":"第五十九条","txt":"道路交通事故认定应当做到事实清楚、证据确实充分、适用法律正确、责任划分公正、程序合法。"},{"i":60,"n":"第六十条","txt":"公安机关交通管理部门应当根据当事人的行为对发生道路交通事故所起的作用以及过错的严重程度，确定当事人的责任。 （一）因一方当事人的过错导致道路交通事故的，承担全部责任； （二）因两方或者两方以上当事人的过错发生道路交通事故的，根据其行为对事故发生的作用以及过错的严重程度，分别承担主要责任、同等责任和次要责任； （三）各方均无导致道路交通事故的过错，属于交通意外事故的，各方均无责任。 一方当事人故意造成道路交通事故的，他方无责任。"},{"i":61,"n":"第六十一条","txt":"当事人有下列情形之一的，承担全部责任： （一）发生道路交通事故后逃逸的； （二）故意破坏、伪造现场、毁灭证据的。 为逃避法律责任追究，当事人弃车逃逸以及潜逃藏匿的，如有证据证明其他当事人也有过错，可以适当减轻责任，但同时有证据证明逃逸当事人有第一款第二项情形的，不予减轻。"},{"i":62,"n":"第六十二条","txt":"公安机关交通管理部门应当自现场调查之日起十日内制作道路交通事故认定书。交通肇事逃逸案件在查获交通肇事车辆和驾驶人后十日内制作道路交通事故认定书。对需要进行检验、鉴定的，应当在检验报告、鉴定意见确定之日起五日内制作道路交通事故认定书。 有条件的地方公安机关交通管理部门可以试行在互联网公布道路交通事故认定书，但对涉及的国家秘密、商业秘密或者个人隐私，应当保密。"},{"i":63,"n":"第六十三条","txt":"发生死亡事故以及复杂、疑难的伤人事故后，公安机关交通管理部门应当在制作道路交通事故认定书或者道路交通事故证明前，召集各方当事人到场，公开调查取得的证据。 证人要求保密或者涉及国家秘密、商业秘密以及个人隐私的，按照有关法律法规的规定执行。 当事人不到场的，公安机关交通管理部门应当予以记录。"},{"i":64,"n":"第六十四条","txt":"道路交通事故认定书应当载明以下内容： （一）道路交通事故当事人、车辆、道路和交通环境等基本情况； （二）道路交通事故发生经过； （三）道路交通事故证据及事故形成原因分析； （四）当事人导致道路交通事故的过错及责任或者意外原因; （五）作出道路交通事故认定的公安机关交通管理部门名称和日期。 道路交通事故认定书应当由交通警察签名或者盖章，加盖公安机关交通管理部门道路交通事故处理专用章。"},{"i":65,"n":"第六十五条","txt":"道路交通事故认定书应当在制作后三日内分别送达当事人，并告知申请复核、调解和提起民事诉讼的权利、期限。 当事人收到道路交通事故认定书后，可以查阅、复制、摘录公安机关交通管理部门处理道路交通事故的证据材料，但证人要求保密或者涉及国家秘密、商业秘密以及个人隐私的，按照有关法律法规的规定执行。公安机关交通管理部门对当事人复制的证据材料应当加盖公安机关交通管理部门事故处理专用章。"},{"i":66,"n":"第六十六条","txt":"交通肇事逃逸案件尚未侦破，受害一方当事人要求出具道路交通事故认定书的，公安机关交通管理部门应当在接到当事人书面申请后十日内，根据本规定第六十一条确定各方当事人责任，制作道路交通事故认定书，并送达受害方当事人。道路交通事故认定书应当载明事故发生的时间、地点、受害人情况及调查得到的事实，以及受害方当事人的责任。 交通肇事逃逸案件侦破后，已经按照前款规定制作道路交通事故认定书的，应当按照本规定第六十一条重新确定责任，制作道路交通事故认定书，分别送达当事人。重新制作的道路交通事故认定书除应当载明本规定第六十四条规定的内容外，还应当注明撤销原道路交通事故认定书。"},{"i":67,"n":"第六十七条","txt":"道路交通事故基本事实无法查清、成因无法判定的，公安机关交通管理部门应当出具道路交通事故证明，载明道路交通事故发生的时间、地点、当事人情况及调查得到的事实，分别送达当事人，并告知申请复核、调解和提起民事诉讼的权利、期限。"},{"i":68,"n":"第六十八条","txt":"由于事故当事人、关键证人处于抢救状态或者因其他客观原因导致无法及时取证，现有证据不足以认定案件基本事实的，经上一级公安机关交通管理部门批准，道路交通事故认定的时限可中止计算，并书面告知各方当事人或者其代理人，但中止的时间最长不得超过六十日。 当中止认定的原因消失，或者中止期满受伤人员仍然无法接受调查的，公安机关交通管理部门应当在五日内，根据已经调查取得的证据制作道路交通事故认定书或者出具道路交通事故证明。"},{"i":69,"n":"第六十九条","txt":"伤人事故符合下列条件，各方当事人一致书面申请快速处理的，经县级以上公安机关交通管理部门负责人批准，可以根据已经取得的证据，自当事人申请之日起五日内制作道路交通事故认定书： （一）当事人不涉嫌交通肇事、危险驾驶犯罪的； （二）道路交通事故基本事实及成因清楚，当事人无异议的。"},{"i":70,"n":"第七十条","txt":"对尚未查明身份的当事人，公安机关交通管理部门应当在道路交通事故认定书或者道路交通事故证明中予以注明，待身份信息查明以后，制作书面补充说明送达各方当事人。"},{"i":71,"n":"第七十一条","txt":"当事人对道路交通事故认定或者出具道路交通事故证明有异议的，可以自道路交通事故认定书或者道路交通事故证明送达之日起三日内提出书面复核申请。当事人逾期提交复核申请的，不予受理，并书面通知申请人。 复核申请应当载明复核请求及其理由和主要证据。同一事故的复核以一次为限。"},{"i":72,"n":"第七十二条","txt":"复核申请人通过作出道路交通事故认定的公安机关交通管理部门提出复核申请的，作出道路交通事故认定的公安机关交通管理部门应当自收到复核申请之日起二日内将复核申请连同道路交通事故有关材料移送上一级公安机关交通管理部门。 复核申请人直接向上一级公安机关交通管理部门提出复核申请的，上一级公安机关交通管理部门应当通知作出道路交通事故认定的公安机关交通管理部门自收到通知之日起五日内提交案卷材料。"},{"i":73,"n":"第七十三条","txt":"除当事人逾期提交复核申请的情形外，上一级公安机关交通管理部门收到复核申请之日即为受理之日。"},{"i":74,"n":"第七十四条","txt":"上一级公安机关交通管理部门自受理复核申请之日起三十日内，对下列内容进行审查，并作出复核结论： （一）道路交通事故认定的事实是否清楚、证据是否确实充分、适用法律是否正确、责任划分是否公正； （二）道路交通事故调查及认定程序是否合法； （三）出具道路交通事故证明是否符合规定。 复核原则上采取书面审查的形式，但当事人提出要求或者公安机关交通管理部门认为有必要时，可以召集各方当事人到场，听取各方意见。 办理复核案件的交通警察不得少于二人。"},{"i":75,"n":"第七十五条","txt":"复核审查期间，申请人提出撤销复核申请的，公安机关交通管理部门应当终止复核，并书面通知各方当事人。 受理复核申请后，任何一方当事人就该事故向人民法院提起诉讼并经人民法院受理的，公安机关交通管理部门应当将受理当事人复核申请的有关情况告知相关人民法院。 受理复核申请后，人民检察院对交通肇事犯罪嫌疑人作出批准逮捕决定的，公安机关交通管理部门应当将受理当事人复核申请的有关情况告知相关人民检察院。"},{"i":76,"n":"第七十六条","txt":"上一级公安机关交通管理部门认为原道路交通事故认定事实清楚、证据确实充分、适用法律正确、责任划分公正、程序合法的，应当作出维持原道路交通事故认定的复核结论。 上一级公安机关交通管理部门认为调查及认定程序存在瑕疵，但不影响道路交通事故认定的，在责令原办案单位补正或者作出合理解释后，可以作出维持原道路交通事故认定的复核结论。 上一级公安机关交通管理部门认为原道路交通事故认定有下列情形之一的，应当作出责令原办案单位重新调查、认定的复核结论： （一）事实不清的； （二）主要证据不足的； （三）适用法律错误的； （四）责任划分不公正的； （五）调查及认定违反法定程序可能影响道路交通事故认定的。"},{"i":77,"n":"第七十七条","txt":"上一级公安机关交通管理部门审查原道路交通事故证明后，按下列规定处理： （一）认为事故成因确属无法查清，应当作出维持原道路交通事故证明的复核结论； （二）认为事故成因仍需进一步调查的，应当作出责令原办案单位重新调查、认定的复核结论。"},{"i":78,"n":"第七十八条","txt":"上一级公安机关交通管理部门应当在作出复核结论后三日内将复核结论送达各方当事人。公安机关交通管理部门认为必要的，应当召集各方当事人，当场宣布复核结论。"},{"i":79,"n":"第七十九条","txt":"上一级公安机关交通管理部门作出责令重新调查、认定的复核结论后，原办案单位应当在十日内依照本规定重新调查，重新作出道路交通事故认定，撤销原道路交通事故认定书或者原道路交通事故证明。 重新调查需要检验、鉴定的，原办案单位应当在检验报告、鉴定意见确定之日起五日内，重新作出道路交通事故认定。 重新作出道路交通事故认定的，原办案单位应当送达各方当事人，并报上一级公安机关交通管理部门备案。"},{"i":80,"n":"第八十条","txt":"上一级公安机关交通管理部门可以设立道路交通事故复核委员会，由办理复核案件的交通警察会同相关行业代表、社会专家学者等人员共同组成，负责案件复核，并以上一级公安机关交通管理部门的名义作出复核结论。"},{"i":81,"n":"第八十一条","txt":"公安机关交通管理部门应当按照《道路交通安全违法行为处理程序规定》，对当事人的道路交通安全违法行为依法作出处罚。"},{"i":82,"n":"第八十二条","txt":"对发生道路交通事故构成犯罪，依法应当吊销驾驶人机动车驾驶证的，应当在人民法院作出有罪判决后，由设区的市公安机关交通管理部门依法吊销机动车驾驶证。同时具有逃逸情形的，公安机关交通管理部门应当同时依法作出终生不得重新取得机动车驾驶证的决定。"},{"i":83,"n":"第八十三条","txt":"专业运输单位六个月内两次发生一次死亡三人以上事故，且单位或者车辆驾驶人对事故承担全部责任或者主要责任的，专业运输单位所在地的公安机关交通管理部门应当报经设区的市公安机关交通管理部门批准后，作出责令限期消除安全隐患的决定，禁止未消除安全隐患的机动车上道路行驶，并通报道路交通事故发生地及运输单位所在地的人民政府有关行政管理部门。"},{"i":84,"n":"第八十四条","txt":"当事人可以采取以下方式解决道路交通事故损害赔偿争议： （一）申请人民调解委员会调解； （二）申请公安机关交通管理部门调解； （三）向人民法院提起民事诉讼。"},{"i":85,"n":"第八十五条","txt":"当事人申请人民调解委员会调解，达成调解协议后，双方当事人认为有必要的，可以根据《中华人民共和国人民调解法》共同向人民法院申请司法确认。 当事人申请人民调解委员会调解，调解未达成协议的，当事人可以直接向人民法院提起民事诉讼，或者自人民调解委员会作出终止调解之日起三日内，一致书面申请公安机关交通管理部门进行调解。"},{"i":86,"n":"第八十六条","txt":"当事人申请公安机关交通管理部门调解的，应当在收到道路交通事故认定书、道路交通事故证明或者上一级公安机关交通管理部门维持原道路交通事故认定的复核结论之日起十日内一致书面申请。 当事人申请公安机关交通管理部门调解，调解未达成协议的，当事人可以依法向人民法院提起民事诉讼，或者申请人民调解委员会进行调解。"},{"i":87,"n":"第八十七条","txt":"公安机关交通管理部门应当按照合法、公正、自愿、及时的原则进行道路交通事故损害赔偿调解。 道路交通事故损害赔偿调解应当公开进行，但当事人申请不予公开的除外。"},{"i":88,"n":"第八十八条","txt":"公安机关交通管理部门应当与当事人约定调解的时间、地点，并于调解时间三日前通知当事人。口头通知的，应当记入调解记录。 调解参加人因故不能按期参加调解的，应当在预定调解时间一日前通知承办的交通警察，请求变更调解时间。"},{"i":89,"n":"第八十九条","txt":"参加损害赔偿调解的人员包括： （一）道路交通事故当事人及其代理人； （二）道路交通事故车辆所有人或者管理人； （三）承保机动车保险的保险公司人员； （四）公安机关交通管理部门认为有必要参加的其他人员。 委托代理人应当出具由委托人签名或者盖章的授权委托书。授权委托书应当载明委托事项和权限。 参加损害赔偿调解的人员每方不得超过三人。"},{"i":90,"n":"第九十条","txt":"公安机关交通管理部门受理调解申请后，应当按照下列规定日期开始调解： （一）造成人员死亡的，从规定的办理丧葬事宜时间结束之日起； （二）造成人员受伤的，从治疗终结之日起； （三）因伤致残的，从定残之日起； （四）造成财产损失的，从确定损失之日起。 公安机关交通管理部门受理调解申请时已超过前款规定的时间，调解自受理调解申请之日起开始。 公安机关交通管理部门应当自调解开始之日起十日内制作道路交通事故损害赔偿调解书或者道路交通事故损害赔偿调解终结书。"},{"i":91,"n":"第九十一条","txt":"交通警察调解道路交通事故损害赔偿，按照下列程序实施： （一）告知各方当事人权利、义务； （二）听取各方当事人的请求及理由； （三）根据道路交通事故认定书认定的事实以及《中华人民共和国道路交通安全法》第七十六条的规定，确定当事人承担的损害赔偿责任； （四）计算损害赔偿的数额，确定各方当事人承担的比例，人身损害赔偿的标准按照《中华人民共和国侵权责任法》《最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释》《最高人民法院关于审理道路交通事故损害赔偿案件适用法律若干问题的解释》等有关规定执行，财产损失的修复费用、折价赔偿费用按照实际价值或者评估机构的评估结论计算； （五）确定赔偿履行方式及期限。"},{"i":92,"n":"第九十二条","txt":"因确定损害赔偿的数额，需要进行伤残评定、财产损失评估的，由各方当事人协商确定有资质的机构进行，但财产损失数额巨大涉嫌刑事犯罪的，由公安机关交通管理部门委托。 当事人委托伤残评定、财产损失评估的费用，由当事人承担。"},{"i":93,"n":"第九十三条","txt":"经调解达成协议的，公安机关交通管理部门应当当场制作道路交通事故损害赔偿调解书，由各方当事人签字，分别送达各方当事人。 调解书应当载明以下内容： （一）调解依据； （二）道路交通事故认定书认定的基本事实和损失情况； （三）损害赔偿的项目和数额； （四）各方的损害赔偿责任及比例； （五）赔偿履行方式和期限； （六）调解日期。 经调解各方当事人未达成协议的，公安机关交通管理部门应当终止调解，制作道路交通事故损害赔偿调解终结书，送达各方当事人。"},{"i":94,"n":"第九十四条","txt":"有下列情形之一的，公安机关交通管理部门应当终止调解，并记录在案： （一）调解期间有一方当事人向人民法院提起民事诉讼的； （二）一方当事人无正当理由不参加调解的； （三）一方当事人调解过程中退出调解的。"},{"i":95,"n":"第九十五条","txt":"有条件的地方公安机关交通管理部门可以联合有关部门，设置道路交通事故保险理赔服务场所。"},{"i":96,"n":"第九十六条","txt":"外国人在中华人民共和国境内发生道路交通事故的，除按照本规定执行外，还应当按照办理涉外案件的有关法律、法规、规章的规定执行。 公安机关交通管理部门处理外国人发生的道路交通事故，应当告知当事人我国法律、法规、规章规定的当事人在处理道路交通事故中的权利和义务。"},{"i":97,"n":"第九十七条","txt":"外国人发生道路交通事故有下列情形之一的，不准其出境： （一）涉嫌犯罪的； （二）有未了结的道路交通事故损害赔偿案件，人民法院决定不准出境的； （三）法律、行政法规规定不准出境的其他情形。"},{"i":98,"n":"第九十八条","txt":"外国人发生道路交通事故并承担全部责任或者主要责任的，公安机关交通管理部门应当告知道路交通事故损害赔偿权利人可以向人民法院提出采取诉前保全措施的请求。"},{"i":99,"n":"第九十九条","txt":"公安机关交通管理部门在处理道路交通事故过程中，使用中华人民共和国通用的语言文字。对不通晓我国语言文字的，应当为其提供翻译；当事人通晓我国语言文字而不需要他人翻译的，应当出具书面声明。 经公安机关交通管理部门批准，外国人可以自行聘请翻译，翻译费由当事人承担。"},{"i":100,"n":"第一百条","txt":"享有外交特权与豁免的人员发生道路交通事故时，应当主动出示有效身份证件，交通警察认为应当给予暂扣或者吊销机动车驾驶证处罚的，可以扣留其机动车驾驶证。需要对享有外交特权与豁免的人员进行调查的，可以约谈，谈话时仅限于与道路交通事故有关的内容。需要检验、鉴定车辆的，公安机关交通管理部门应当征得其同意，并在检验、鉴定后立即发还。 公安机关交通管理部门应当根据收集的证据，制作道路交通事故认定书送达当事人，当事人拒绝接收的，送达至其所在机构；没有所在机构或者所在机构不明确的，由当事人所属国家的驻华使领馆转交送达。 享有外交特权与豁免的人员应当配合公安机关交通管理部门的调查和检验、鉴定。对于经核查确实享有外交特权与豁免但不同意接受调查或者检验、鉴定的，公安机关交通管理部门应当将有关情况记录在案，损害赔偿事宜通过外交途径解决。"},{"i":101,"n":"第一百零一条","txt":"公安机关交通管理部门处理享有外交特权与豁免的外国人发生人员死亡事故的，应当将其身份、证件及事故经过、损害后果等基本情况记录在案，并将有关情况迅速通报省级人民政府外事部门和该外国人所属国家的驻华使馆或者领馆。"},{"i":102,"n":"第一百零二条","txt":"外国驻华领事机构、国际组织、国际组织驻华代表机构享有特权与豁免的人员发生道路交通事故的，公安机关交通管理部门参照本规定第一百条、第一百零一条规定办理，但《中华人民共和国领事特权与豁免条例》、中国已参加的国际公约以及我国与有关国家或者国际组织缔结的协议有不同规定的除外。"},{"i":103,"n":"第一百零三条","txt":"公安机关警务督察部门可以依法对公安机关交通管理部门及其交通警察处理道路交通事故工作进行现场督察，查处违纪违法行为。 上级公安机关交通管理部门对下级公安机关交通管理部门处理道路交通事故工作进行监督，发现错误应当及时纠正，造成严重后果的，依纪依法追究有关人员的责任。"},{"i":104,"n":"第一百零四条","txt":"公安机关交通管理部门及其交通警察处理道路交通事故，应当公开办事制度、办事程序，建立警风警纪监督员制度，并自觉接受社会和群众的监督。 任何单位和个人都有权对公安机关交通管理部门及其交通警察不依法严格公正处理道路交通事故、利用职务上的便利收受他人财物或者谋取其他利益、徇私舞弊、滥用职权、玩忽职守以及其他违纪违法行为进行检举、控告。收到检举、控告的机关，应当依据职责及时查处。"},{"i":105,"n":"第一百零五条","txt":"在调查处理道路交通事故时，交通警察或者公安机关检验、鉴定人员有下列情形之一的，应当回避： （一）是本案的当事人或者是当事人的近亲属的； （二）本人或者其近亲属与本案有利害关系的； （三）与本案当事人有其他关系，可能影响案件公正处理的。 交通警察或者公安机关检验、鉴定人员需要回避的，由本级公安机关交通管理部门负责人或者检验、鉴定人员所属的公安机关决定。公安机关交通管理部门负责人需要回避的，由公安机关或者上一级公安机关交通管理部门负责人决定。 对当事人提出的回避申请，公安机关交通管理部门应当在二日内作出决定，并通知申请人。"},{"i":106,"n":"第一百零六条","txt":"人民法院、人民检察院审理、审查道路交通事故案件，需要公安机关交通管理部门提供有关证据的，公安机关交通管理部门应当在接到调卷公函之日起三日内，或者按照其时限要求，将道路交通事故案件调查材料正本移送人民法院或者人民检察院。"},{"i":107,"n":"第一百零七条","txt":"公安机关交通管理部门对查获交通肇事逃逸车辆及人员提供有效线索或者协助的人员、单位，应当给予表彰和奖励。 公安机关交通管理部门及其交通警察接到协查通报不配合协查并造成严重后果的，由公安机关或者上级公安机关交通管理部门追究有关人员和单位主管领导的责任。"},{"i":108,"n":"第一百零八条","txt":"道路交通事故处理资格等级管理规定由公安部另行制定，资格证书式样全国统一。"},{"i":109,"n":"第一百零九条","txt":"公安机关交通管理部门应当在邻省、市（地）、县交界的国、省、县道上，以及辖区内交通流量集中的路段，设置标有管辖地公安机关交通管理部门名称及道路交通事故报警电话号码的提示牌。"},{"i":110,"n":"第一百一十条","txt":"车辆在道路以外通行时发生的事故，公安机关交通管理部门接到报案的，参照本规定处理。涉嫌犯罪的，及时移送有关部门。"},{"i":111,"n":"第一百一十一条","txt":"执行本规定所需要的法律文书式样，由公安部制定。公安部没有制定式样，执法工作中需要的其他法律文书，省级公安机关可以制定式样。 当事人自行协商处理损害赔偿事宜的，可以自行制作协议书，但应当符合本规定第二十一条关于协议书内容的规定。"},{"i":112,"n":"第一百一十二条","txt":"本规定中下列用语的含义是： （一）“交通肇事逃逸”，是指发生道路交通事故后，当事人为逃避法律责任，驾驶或者遗弃车辆逃离道路交通事故现场以及潜逃藏匿的行为。 （二）“深度调查”，是指以有效防范道路交通事故为目的，对道路交通事故发生的深层次原因以及道路交通安全相关因素开展延伸调查，分析查找安全隐患及管理漏洞，并提出从源头解决问题的意见和建议的活动。 （三）“检验报告、鉴定意见确定”，是指检验报告、鉴定意见复印件送达当事人之日起三日内，当事人未申请重新检验、鉴定的，以及公安机关交通管理部门批准重新检验、鉴定，鉴定机构出具检验报告、鉴定意见的。 （四）“外国人”，是指不具有中国国籍的人。 （五）本规定所称的“一日”、“二日”、“三日”、“五日”、“十日”，是指工作日，不包括节假日。 （六）本规定所称的“以上”、“以下”均包括本数在内。 （七）“县级以上公安机关交通管理部门”，是指县级以上人民政"},{"i":113,"n":"第一百一十三条","txt":"本规定没有规定的道路交通事故案件办理程序，依照《公安机关办理行政案件程序规定》《公安机关办理刑事案件程序规定》的有关规定执行。"},{"i":114,"n":"第一百一十四条","txt":"本规定自2018年5月1日起施行。2008年8月17日发布的《道路交通事故处理程序规定》（公安部令第104号）同时废止。"}],"daolujiaotonganquanweifaxingweichulichengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范道路交通安全违法行为处理程序，保障公安机关交通管理部门正确履行职责，保护公民、法人和其他组织的合法权益，根据《中华人民共和国道路交通安全法》及其实施条例等法律、行政法规制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关交通管理部门及其交通警察对道路交通安全违法行为（以下简称违法行为）的处理程序，在法定职权范围内依照本规定实施。"},{"i":3,"n":"第三条","txt":"对违法行为的处理应当遵循合法、公正、文明、公开、及时的原则，尊重和保障人权，保护公民的人格尊严。 对违法行为的处理应当坚持教育与处罚相结合的原则，教育公民、法人和其他组织自觉遵守道路交通安全法律法规。 对违法行为的处理，应当以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。"},{"i":4,"n":"第四条","txt":"交通警察执勤执法中发现的违法行为由违法行为发生地的公安机关交通管理部门管辖。 对管辖权发生争议的，报请共同的上一级公安机关交通管理部门指定管辖。上一级公安机关交通管理部门应当及时确定管辖主体，并通知争议各方。"},{"i":5,"n":"第五条","txt":"违法行为人可以在违法行为发生地、机动车登记地或者其他任意地公安机关交通管理部门处理交通技术监控设备记录的违法行为。 违法行为人在违法行为发生地以外的地方（以下简称处理地）处理交通技术监控设备记录的违法行为的，处理地公安机关交通管理部门可以协助违法行为发生地公安机关交通管理部门调查违法事实、代为送达法律文书、代为履行处罚告知程序，由违法行为发生地公安机关交通管理部门按照发生地标准作出处罚决定。 违法行为人或者机动车所有人、管理人对交通技术监控设备记录的违法行为事实有异议的，可以通过公安机关交通管理部门互联网站、移动互联网应用程序或者违法行为处理窗口向公安机关交通管理部门提出。处理地公安机关交通管理部门应当在收到当事人申请后当日，通过道路交通违法信息管理系统通知违法行为发生地公安机关交通管理部门。违法行为发生地公安机关交通管理部门应当在五日内予以审查，异议成立的，予以消除；异议不成立的，告"},{"i":6,"n":"第六条","txt":"对违法行为人处以警告、罚款或者暂扣机动车驾驶证处罚的，由县级以上公安机关交通管理部门作出处罚决定。 对违法行为人处以吊销机动车驾驶证处罚的，由设区的市公安机关交通管理部门作出处罚决定。 对违法行为人处以行政拘留处罚的，由县、市公安局、公安分局或者相当于县一级的公安机关作出处罚决定。"},{"i":7,"n":"第七条","txt":"交通警察调查违法行为时，应当表明执法身份。 交通警察执勤执法应当严格执行安全防护规定，注意自身安全，在公路上执勤执法不得少于两人。"},{"i":8,"n":"第八条","txt":"交通警察应当全面、及时、合法收集能够证实违法行为是否存在、违法情节轻重的证据。"},{"i":9,"n":"第九条","txt":"交通警察调查违法行为时，应当查验机动车驾驶证、行驶证、机动车号牌、检验合格标志、保险标志等牌证以及机动车和驾驶人违法信息。对运载爆炸物品、易燃易爆化学物品以及剧毒、放射性等危险物品车辆驾驶人违法行为调查的，还应当查验其他相关证件及信息。"},{"i":10,"n":"第十条","txt":"交通警察查验机动车驾驶证时，应当询问驾驶人姓名、住址、出生年月并与驾驶证上记录的内容进行核对；对持证人的相貌与驾驶证上的照片进行核对。必要时，可以要求驾驶人出示居民身份证进行核对。"},{"i":11,"n":"第十一条","txt":"调查中需要采取行政强制措施的，依照法律、法规、本规定及国家其他有关规定实施。"},{"i":12,"n":"第十二条","txt":"交通警察对机动车驾驶人不在现场的违法停放机动车行为，应当在机动车侧门玻璃或者摩托车座位上粘贴违法停车告知单，并采取拍照或者录像方式固定相关证据。"},{"i":13,"n":"第十三条","txt":"调查中发现违法行为人有其他违法行为的，在依法对其道路交通安全违法行为作出处理决定的同时，按照有关规定移送有管辖权的单位处理。涉嫌构成犯罪的，转为刑事案件办理或者移送有权处理的主管机关、部门办理。"},{"i":14,"n":"第十四条","txt":"公安机关交通管理部门对于控告、举报的违法行为以及其他行政主管部门移送的案件应当接受，并按规定处理。"},{"i":15,"n":"第十五条","txt":"公安机关交通管理部门可以利用交通技术监控设备、执法记录设备收集、固定违法行为证据。 交通技术监控设备、执法记录设备应当符合国家标准或者行业标准，需要认定、检定的交通技术监控设备应当经认定、检定合格后，方可用于收集、固定违法行为证据。 交通技术监控设备应当定期维护、保养、检测，保持功能完好。"},{"i":16,"n":"第十六条","txt":"交通技术监控设备的设置应当遵循科学、规范、合理的原则，设置的地点应当有明确规范相应交通行为的交通信号。 固定式交通技术监控设备设置地点应当向社会公布。"},{"i":17,"n":"第十七条","txt":"使用固定式交通技术监控设备测速的路段，应当设置测速警告标志。 使用移动测速设备测速的，应当由交通警察操作。使用车载移动测速设备的，还应当使用制式警车。"},{"i":18,"n":"第十八条","txt":"作为处理依据的交通技术监控设备收集的违法行为记录资料，应当清晰、准确地反映机动车类型、号牌、外观等特征以及违法时间、地点、事实。"},{"i":19,"n":"第十九条","txt":"交通技术监控设备收集违法行为记录资料后五日内，违法行为发生地公安机关交通管理部门应当对记录内容进行审核，经审核无误后录入道路交通违法信息管理系统，作为处罚违法行为的证据。"},{"i":20,"n":"第二十条","txt":"交通技术监控设备记录的违法行为信息录入道路交通违法信息管理系统后当日，违法行为发生地和机动车登记地公安机关交通管理部门应当向社会提供查询。违法行为发生地公安机关交通管理部门应当在违法行为信息录入道路交通违法信息管理系统后五日内，按照机动车备案信息中的联系方式，通过移动互联网应用程序、手机短信或者邮寄等方式将违法时间、地点、事实通知违法行为人或者机动车所有人、管理人，并告知其在三十日内接受处理。 公安机关交通管理部门应当在违法行为人或者机动车所有人、管理人处理违法行为和交通事故、办理机动车或者驾驶证业务时，书面确认违法行为人或者机动车所有人、管理人的联系方式和法律文书送达方式，并告知其可以通过公安机关交通管理部门互联网站、移动互联网应用程序等方式备案或者变更联系方式、法律文书送达方式。"},{"i":21,"n":"第二十一条","txt":"对交通技术监控设备记录的违法行为信息，经核查能够确定实际驾驶人的，公安机关交通管理部门可以在道路交通违法信息管理系统中将其记录为实际驾驶人的违法行为信息。"},{"i":22,"n":"第二十二条","txt":"交通技术监控设备记录或者录入道路交通违法信息管理系统的违法行为信息，有下列情形之一并经核实的，违法行为发生地或者机动车登记地公安机关交通管理部门应当自核实之日起三日内予以消除： （一）警车、消防救援车辆、救护车、工程救险车执行紧急任务期间交通技术监控设备记录的违法行为； （二）机动车所有人或者管理人提供报案记录证明机动车被盗抢期间、机动车号牌被他人冒用期间交通技术监控设备记录的违法行为； （三）违法行为人或者机动车所有人、管理人提供证据证明机动车因救助危难或者紧急避险造成的违法行为； （四）已经在现场被交通警察处理的交通技术监控设备记录的违法行为； （五）因交通信号指示不一致造成的违法行为； （六）作为处理依据的交通技术监控设备收集的违法行为记录资料，不能清晰、准确地反映机动车类型、号牌、外观等特征以及违法时间、地点、事实的； （七）经比对交通技术监控设备记录的违法行为照片、道路交通违"},{"i":23,"n":"第二十三条","txt":"经查证属实，单位或者个人提供的违法行为照片或者视频等资料可以作为处罚的证据。 对群众举报的违法行为照片或者视频资料的审核录入要求，参照本规定执行。"},{"i":24,"n":"第二十四条","txt":"公安机关交通管理部门及其交通警察在执法过程中，依法可以采取下列行政强制措施： （一）扣留车辆； （二）扣留机动车驾驶证； （三）拖移机动车； （四）检验体内酒精、国家管制的精神药品、麻醉药品含量； （五）收缴物品； （六）法律、法规规定的其他行政强制措施。"},{"i":25,"n":"第二十五条","txt":"采取本规定第二十四条第（一）、（二）、（四）、（五）项行政强制措施，应当按照下列程序实施： （一）口头告知违法行为人或者机动车所有人、管理人违法行为的基本事实、拟作出行政强制措施的种类、依据及其依法享有的权利； （二）听取当事人的陈述和申辩，当事人提出的事实、理由或者证据成立的，应当采纳； （三）制作行政强制措施凭证，并告知当事人在十五日内到指定地点接受处理； （四）行政强制措施凭证应当由当事人签名、交通警察签名或者盖章，并加盖公安机关交通管理部门印章；当事人拒绝签名的，交通警察应当在行政强制措施凭证上注明； （五）行政强制措施凭证应当当场交付当事人；当事人拒收的，由交通警察在行政强制措施凭证上注明，即为送达。 现场采取行政强制措施的，交通警察应当在二十四小时内向所属公安机关交通管理部门负责人报告，并补办批准手续。公安机关交通管理部门负责人认为不应当采取行政强制措施的，应当立即解除。"},{"i":26,"n":"第二十六条","txt":"行政强制措施凭证应当载明当事人的基本情况、车辆牌号、车辆类型、违法事实、采取行政强制措施种类和依据、接受处理的具体地点和期限、决定机关名称及当事人依法享有的行政复议、行政诉讼权利等内容。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，依法扣留车辆： （一）上道路行驶的机动车未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未随车携带机动车行驶证、驾驶证的； （二）有伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、保险标志、驾驶证或者使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志嫌疑的； （三）未按照国家规定投保机动车交通事故责任强制保险的； （四）公路客运车辆或者货运机动车超载的； （五）机动车有被盗抢嫌疑的； （六）机动车有拼装或者达到报废标准嫌疑的； （七）未申领《剧毒化学品公路运输通行证》通过公路运输剧毒化学品的； （八）非机动车驾驶人拒绝接受罚款处罚的。 对发生道路交通事故，因收集证据需要的，可以依法扣留事故车辆。"},{"i":28,"n":"第二十八条","txt":"交通警察应当在扣留车辆后二十四小时内，将被扣留车辆交所属公安机关交通管理部门。 公安机关交通管理部门扣留车辆的，不得扣留车辆所载货物。对车辆所载货物应当通知当事人自行处理，当事人无法自行处理或者不自行处理的，应当登记并妥善保管，对容易腐烂、损毁、灭失或者其他不具备保管条件的物品，经县级以上公安机关交通管理部门负责人批准，可以在拍照或者录像后变卖或者拍卖，变卖、拍卖所得按照有关规定处理。"},{"i":29,"n":"第二十九条","txt":"对公路客运车辆载客超过核定乘员、货运机动车超过核定载质量的，公安机关交通管理部门应当按照下列规定消除违法状态： （一）违法行为人可以自行消除违法状态的，应当在公安机关交通管理部门的监督下，自行将超载的乘车人转运、将超载的货物卸载； （二）违法行为人无法自行消除违法状态的，对超载的乘车人，公安机关交通管理部门应当及时通知有关部门联系转运；对超载的货物，应当在指定的场地卸载，并由违法行为人与指定场地的保管方签订卸载货物的保管合同。 消除违法状态的费用由违法行为人承担。违法状态消除后，应当立即退还被扣留的机动车。"},{"i":30,"n":"第三十条","txt":"对扣留的车辆，当事人接受处理或者提供、补办的相关证明或者手续经核实后，公安机关交通管理部门应当依法及时退还。 公安机关交通管理部门核实的时间不得超过十日；需要延长的，经县级以上公安机关交通管理部门负责人批准，可以延长至十五日。核实时间自车辆驾驶人或者所有人、管理人提供被扣留车辆合法来历证明，补办相应手续，或者接受处理之日起计算。 发生道路交通事故因收集证据需要扣留车辆的，扣留车辆时间依照《道路交通事故处理程序规定》有关规定执行。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，依法扣留机动车驾驶证： （一）饮酒后驾驶机动车的； （二）将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的； （三）机动车行驶超过规定时速百分之五十的； （四）驾驶有拼装或者达到报废标准嫌疑的机动车上道路行驶的； （五）在一个记分周期内累积记分达到十二分的。"},{"i":32,"n":"第三十二条","txt":"交通警察应当在扣留机动车驾驶证后二十四小时内，将被扣留机动车驾驶证交所属公安机关交通管理部门。 具有本规定第三十一条第（一）、（二）、（三）、（四）项所列情形之一的，扣留机动车驾驶证至作出处罚决定之日；处罚决定生效前先予扣留机动车驾驶证的，扣留一日折抵暂扣期限一日。只对违法行为人作出罚款处罚的，缴纳罚款完毕后，应当立即发还机动车驾驶证。具有本规定第三十一条第（五）项情形的，扣留机动车驾驶证至考试合格之日。"},{"i":33,"n":"第三十三条","txt":"违反机动车停放、临时停车规定，驾驶人不在现场或者虽在现场但拒绝立即驶离，妨碍其他车辆、行人通行的，公安机关交通管理部门及其交通警察可以将机动车拖移至不妨碍交通的地点或者公安机关交通管理部门指定的地点。 拖移机动车的，现场交通警察应当通过拍照、录像等方式固定违法事实和证据。"},{"i":34,"n":"第三十四条","txt":"公安机关交通管理部门应当公开拖移机动车查询电话，并通过设置拖移机动车专用标志牌明示或者以其他方式告知当事人。当事人可以通过电话查询接受处理的地点、期限和被拖移机动车的停放地点。"},{"i":35,"n":"第三十五条","txt":"车辆驾驶人有下列情形之一的，应当对其检验体内酒精含量： （一）对酒精呼气测试等方法测试的酒精含量结果有异议并当场提出的； （二）涉嫌饮酒驾驶车辆发生交通事故的； （三）涉嫌醉酒驾驶的； （四）拒绝配合酒精呼气测试等方法测试的。 车辆驾驶人对酒精呼气测试结果无异议的，应当签字确认。事后提出异议的，不予采纳。 车辆驾驶人涉嫌吸食、注射毒品或者服用国家管制的精神药品、麻醉药品后驾驶车辆的，应当按照《吸毒检测程序规定》对车辆驾驶人进行吸毒检测，并通知其家属，但无法通知的除外。 对酒后、吸毒后行为失控或者拒绝配合检验、检测的，可以使用约束带或者警绳等约束性警械。"},{"i":36,"n":"第三十六条","txt":"对车辆驾驶人进行体内酒精含量检验的，应当按照下列程序实施： （一）由两名交通警察或者由一名交通警察带领警务辅助人员将车辆驾驶人带到医疗机构提取血样，或者现场由法医等具有相应资质的人员提取血样； （二）公安机关交通管理部门应当在提取血样后五日内将血样送交有检验资格的单位或者机构进行检验，并在收到检验结果后五日内书面告知车辆驾驶人。 检验车辆驾驶人体内酒精含量的，应当通知其家属，但无法通知的除外。 车辆驾驶人对检验结果有异议的，可以在收到检验结果之日起三日内申请重新检验。 具有下列情形之一的，应当进行重新检验： （一）检验程序违法或者违反相关专业技术要求，可能影响检验结果正确性的； （二）检验单位或者机构、检验人不具备相应资质和条件的; （三）检验结果明显依据不足的； （四）检验人故意作虚假检验的； （五）检验人应当回避而没有回避的； （六）检材虚假或者被污染的； （七）其他应当重新检验的"},{"i":37,"n":"第三十七条","txt":"对非法安装警报器、标志灯具或者自行车、三轮车加装动力装置的，公安机关交通管理部门应当强制拆除，予以收缴，并依法予以处罚。 交通警察现场收缴非法装置的，应当在二十四小时内，将收缴的物品交所属公安机关交通管理部门。 对收缴的物品，除作为证据保存外，经县级以上公安机关交通管理部门批准后，依法予以销毁。"},{"i":38,"n":"第三十八条","txt":"公安机关交通管理部门对扣留的拼装或者已达到报废标准的机动车，经县级以上公安机关交通管理部门批准后，予以收缴，强制报废。"},{"i":39,"n":"第三十九条","txt":"对伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、保险标志、驾驶证的，应当予以收缴，依法处罚后予以销毁。 对使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，应当予以收缴，依法处罚后转至机动车登记地车辆管理所。"},{"i":40,"n":"第四十条","txt":"对在道路两侧及隔离带上种植树木、其他植物或者设置广告牌、管线等，遮挡路灯、交通信号灯、交通标志，妨碍安全视距的，公安机关交通管理部门应当向违法行为人送达排除妨碍通知书，告知履行期限和不履行的后果。违法行为人在规定期限内拒不履行的，依法予以处罚并强制排除妨碍。"},{"i":41,"n":"第四十一条","txt":"强制排除妨碍，公安机关交通管理部门及其交通警察可以当场实施。无法当场实施的，应当按照下列程序实施： （一）经县级以上公安机关交通管理部门负责人批准，可以委托或者组织没有利害关系的单位予以强制排除妨碍； （二）执行强制排除妨碍时，公安机关交通管理部门应当派员到场监督。"},{"i":42,"n":"第四十二条","txt":"交通警察对于当场发现的违法行为，认为情节轻微、未影响道路通行和安全的，口头告知其违法行为的基本事实、依据，向违法行为人提出口头警告，纠正违法行为后放行。 各省、自治区、直辖市公安机关交通管理部门可以根据实际确定适用口头警告的具体范围和实施办法。"},{"i":43,"n":"第四十三条","txt":"对违法行为人处以警告或者二百元以下罚款的，可以适用简易程序。 对违法行为人处以二百元（不含）以上罚款、暂扣或者吊销机动车驾驶证的，应当适用一般程序。不需要采取行政强制措施的，现场交通警察应当收集、固定相关证据，并制作违法行为处理通知书。其中，对违法行为人单处二百元（不含）以上罚款的，可以通过简化取证方式和审核审批手续等措施快速办理。 对违法行为人处以行政拘留处罚的，按照《公安机关办理行政案件程序规定》实施。"},{"i":44,"n":"第四十四条","txt":"适用简易程序处罚的，可以由一名交通警察作出，并应当按照下列程序实施: （一）口头告知违法行为人违法行为的基本事实、拟作出的行政处罚、依据及其依法享有的权利； （二）听取违法行为人的陈述和申辩，违法行为人提出的事实、理由或者证据成立的，应当采纳； （三）制作简易程序处罚决定书； （四）处罚决定书应当由被处罚人签名、交通警察签名或者盖章，并加盖公安机关交通管理部门印章；被处罚人拒绝签名的，交通警察应当在处罚决定书上注明； （五）处罚决定书应当当场交付被处罚人；被处罚人拒收的，由交通警察在处罚决定书上注明，即为送达。 交通警察应当在二日内将简易程序处罚决定书报所属公安机关交通管理部门备案。"},{"i":45,"n":"第四十五条","txt":"简易程序处罚决定书应当载明被处罚人的基本情况、车辆牌号、车辆类型、违法事实、处罚的依据、处罚的内容、履行方式、期限、处罚机关名称及被处罚人依法享有的行政复议、行政诉讼权利等内容。"},{"i":46,"n":"第四十六条","txt":"制发违法行为处理通知书应当按照下列程序实施： （一）口头告知违法行为人违法行为的基本事实； （二）听取违法行为人的陈述和申辩，违法行为人提出的事实、理由或者证据成立的，应当采纳； （三）制作违法行为处理通知书，并通知当事人在十五日内接受处理； （四）违法行为处理通知书应当由违法行为人签名、交通警察签名或者盖章，并加盖公安机关交通管理部门印章；当事人拒绝签名的，交通警察应当在违法行为处理通知书上注明； （五）违法行为处理通知书应当当场交付当事人；当事人拒收的，由交通警察在违法行为处理通知书上注明，即为送达。 交通警察应当在二十四小时内将违法行为处理通知书报所属公安机关交通管理部门备案。"},{"i":47,"n":"第四十七条","txt":"违法行为处理通知书应当载明当事人的基本情况、车辆牌号、车辆类型、违法事实、接受处理的具体地点和时限、通知机关名称等内容。"},{"i":48,"n":"第四十八条","txt":"适用一般程序作出处罚决定，应当由两名以上交通警察按照下列程序实施: （一）对违法事实进行调查，询问当事人违法行为的基本情况，并制作笔录；当事人拒绝接受询问、签名或者盖章的，交通警察应当在询问笔录上注明； （二）采用书面形式或者笔录形式告知当事人拟作出的行政处罚的事实、理由及依据，并告知其依法享有的权利； （三）对当事人陈述、申辩进行复核，复核结果应当在笔录中注明； （四）制作行政处罚决定书； （五）行政处罚决定书应当由被处罚人签名，并加盖公安机关交通管理部门印章；被处罚人拒绝签名的，交通警察应当在处罚决定书上注明； （六）行政处罚决定书应当当场交付被处罚人；被处罚人拒收的，由交通警察在处罚决定书上注明，即为送达；被处罚人不在场的，应当依照《公安机关办理行政案件程序规定》的有关规定送达。"},{"i":49,"n":"第四十九条","txt":"行政处罚决定书应当载明被处罚人的基本情况、车辆牌号、车辆类型、违法事实和证据、处罚的依据、处罚的内容、履行方式、期限、处罚机关名称及被处罚人依法享有的行政复议、行政诉讼权利等内容。"},{"i":50,"n":"第五十条","txt":"一人有两种以上违法行为，分别裁决，合并执行，可以制作一份行政处罚决定书。 一人只有一种违法行为，依法应当并处两个以上处罚种类且涉及两个处罚主体的，应当分别制作行政处罚决定书。"},{"i":51,"n":"第五十一条","txt":"对违法行为事实清楚，需要按照一般程序处以罚款的，应当自违法行为人接受处理之时起二十四小时内作出处罚决定；处以暂扣机动车驾驶证的，应当自违法行为人接受处理之日起三日内作出处罚决定；处以吊销机动车驾驶证的，应当自违法行为人接受处理或者听证程序结束之日起七日内作出处罚决定，交通肇事构成犯罪的，应当在人民法院判决后及时作出处罚决定。"},{"i":52,"n":"第五十二条","txt":"对交通技术监控设备记录的违法行为，当事人应当及时到公安机关交通管理部门接受处理，处以警告或者二百元以下罚款的，可以适用简易程序；处以二百元（不含）以上罚款、吊销机动车驾驶证的，应当适用一般程序。"},{"i":53,"n":"第五十三条","txt":"违法行为人或者机动车所有人、管理人收到道路交通安全违法行为通知后，应当及时到公安机关交通管理部门接受处理。机动车所有人、管理人将机动车交由他人驾驶的，应当通知机动车驾驶人按照本规定第二十条规定期限接受处理。 违法行为人或者机动车所有人、管理人无法在三十日内接受处理的，可以申请延期处理。延长的期限最长不得超过三个月。"},{"i":54,"n":"第五十四条","txt":"机动车有五起以上未处理的违法行为记录，违法行为人或者机动车所有人、管理人未在三十日内接受处理且未申请延期处理的，违法行为发生地公安机关交通管理部门应当按照备案信息中的联系方式，通过移动互联网应用程序、手机短信或者邮寄等方式将拟作出的行政处罚决定的事实、理由、依据以及依法享有的权利，告知违法行为人或者机动车所有人、管理人。违法行为人或者机动车所有人、管理人未在告知后三十日内接受处理的，可以采取公告方式告知拟作出的行政处罚决定的事实、理由、依据、依法享有的权利以及公告期届满后将依法作出行政处罚决定。公告期为七日。 违法行为人或者机动车所有人、管理人提出申辩或者接受处理的，应当按照本规定第四十四条或者第四十八条办理；违法行为人或者机动车所有人、管理人未提出申辩的，公安机关交通管理部门可以依法作出行政处罚决定，并制作行政处罚决定书。"},{"i":55,"n":"第五十五条","txt":"行政处罚决定书可以邮寄或者电子送达。邮寄或者电子送达不成功的，公安机关交通管理部门可以公告送达，公告期为六十日。"},{"i":56,"n":"第五十六条","txt":"电子送达可以采用移动互联网应用程序、电子邮件、移动通信等能够确认受送达人收悉的特定系统作为送达媒介。送达日期为公安机关交通管理部门对应系统显示发送成功的日期。受送达人证明到达其特定系统的日期与公安机关交通管理部门对应系统显示发送成功的日期不一致的，以受送达人证明到达其特定系统的日期为准。 公告应当通过互联网交通安全综合服务管理平台、移动互联网应用程序等方式进行。公告期满，即为送达。 公告内容应当避免泄漏个人隐私。"},{"i":57,"n":"第五十七条","txt":"交通警察在道路执勤执法时，发现违法行为人或者机动车所有人、管理人有交通技术监控设备记录的违法行为逾期未处理的，应当以口头或者书面方式告知违法行为人或者机动车所有人、管理人。"},{"i":58,"n":"第五十八条","txt":"违法行为人可以通过公安机关交通管理部门自助处理平台自助处理违法行为。"},{"i":59,"n":"第五十九条","txt":"对行人、乘车人、非机动车驾驶人处以罚款，交通警察当场收缴的，交通警察应当在简易程序处罚决定书上注明，由被处罚人签名确认。被处罚人拒绝签名的，交通警察应当在处罚决定书上注明。 交通警察依法当场收缴罚款的，应当开具省、自治区、直辖市财政部门统一制发的罚款收据；不开具省、自治区、直辖市财政部门统一制发的罚款收据的，当事人有权拒绝缴纳罚款。"},{"i":60,"n":"第六十条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚决定的公安机关交通管理部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款总额不得超出罚款数额； （二）申请人民法院强制执行。"},{"i":61,"n":"第六十一条","txt":"公安机关交通管理部门对非本辖区机动车驾驶人给予暂扣、吊销机动车驾驶证处罚的，应当在作出处罚决定之日起十五日内，将机动车驾驶证转至核发地公安机关交通管理部门。 违法行为人申请不将暂扣的机动车驾驶证转至核发地公安机关交通管理部门的，应当准许，并在行政处罚决定书上注明。"},{"i":62,"n":"第六十二条","txt":"对违法行为人决定行政拘留并处罚款的，公安机关交通管理部门应当告知违法行为人可以委托他人代缴罚款。"},{"i":63,"n":"第六十三条","txt":"交通警察执勤执法时，应当按照规定着装，佩戴人民警察标志，随身携带人民警察证件，保持警容严整，举止端庄，指挥规范。 交通警察查处违法行为时应当使用规范、文明的执法用语。"},{"i":64,"n":"第六十四条","txt":"公安机关交通管理部门所属的交警队、车管所及重点业务岗位应当建立值日警官和法制员制度，防止和纠正执法中的错误和不当行为。"},{"i":65,"n":"第六十五条","txt":"各级公安机关交通管理部门应当加强执法监督，建立本单位及其所属民警的执法档案，实施执法质量考评、执法责任制和执法过错追究。 执法档案可以是电子档案或者纸质档案。"},{"i":66,"n":"第六十六条","txt":"公安机关交通管理部门应当依法建立交通民警执勤执法考核评价标准，不得下达或者变相下达罚款指标，不得以处罚数量作为考核民警执法效果的依据。"},{"i":67,"n":"第六十七条","txt":"当事人对公安机关交通管理部门采取的行政强制措施或者作出的行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":68,"n":"第六十八条","txt":"公安机关交通管理部门应当使用道路交通违法信息管理系统对违法行为信息进行管理。对记录和处理的交通违法行为信息应当及时录入道路交通违法信息管理系统。"},{"i":69,"n":"第六十九条","txt":"公安机关交通管理部门对非本辖区机动车有违法行为记录的，应当在违法行为信息录入道路交通违法信息管理系统后，在规定时限内将违法行为信息转至机动车登记地公安机关交通管理部门。"},{"i":70,"n":"第七十条","txt":"公安机关交通管理部门对非本辖区机动车驾驶人的违法行为给予记分或者暂扣、吊销机动车驾驶证以及扣留机动车驾驶证的，应当在违法行为信息录入道路交通违法信息管理系统后，在规定时限内将违法行为信息转至驾驶证核发地公安机关交通管理部门。"},{"i":71,"n":"第七十一条","txt":"公安机关交通管理部门可以与保险监管机构建立违法行为与机动车交通事故责任强制保险费率联系浮动制度。"},{"i":72,"n":"第七十二条","txt":"机动车所有人为单位的，公安机关交通管理部门可以将严重影响道路交通安全的违法行为通报机动车所有人。"},{"i":73,"n":"第七十三条","txt":"对非本辖区机动车驾驶人申请在违法行为发生地、处理地参加满分学习、考试的，公安机关交通管理部门应当准许，考试合格后发还扣留的机动车驾驶证，并将考试合格的信息转至驾驶证核发地公安机关交通管理部门。 驾驶证核发地公安机关交通管理部门应当根据转递信息清除机动车驾驶人的累积记分。"},{"i":74,"n":"第七十四条","txt":"以欺骗、贿赂等不正当手段取得机动车登记的，应当收缴机动车登记证书、号牌、行驶证，由机动车登记地公安机关交通管理部门撤销机动车登记。 以欺骗、贿赂等不正当手段取得驾驶许可的，应当收缴机动车驾驶证，由驾驶证核发地公安机关交通管理部门撤销机动车驾驶许可。 非本辖区机动车登记或者机动车驾驶许可需要撤销的，公安机关交通管理部门应当将收缴的机动车登记证书、号牌、行驶证或者机动车驾驶证以及相关证据材料，及时转至机动车登记地或者驾驶证核发地公安机关交通管理部门。"},{"i":75,"n":"第七十五条","txt":"撤销机动车登记或者机动车驾驶许可的，应当按照下列程序实施： （一）经设区的市公安机关交通管理部门负责人批准，制作撤销决定书送达当事人； （二）将收缴的机动车登记证书、号牌、行驶证或者机动车驾驶证以及撤销决定书转至机动车登记地或者驾驶证核发地车辆管理所予以注销； （三）无法收缴的，公告作废。"},{"i":76,"n":"第七十六条","txt":"简易程序案卷应当包括简易程序处罚决定书。一般程序案卷应当包括行政强制措施凭证或者违法行为处理通知书、证据材料、公安交通管理行政处罚决定书。 在处理违法行为过程中形成的其他文书应当一并存入案卷。"},{"i":77,"n":"第七十七条","txt":"本规定中下列用语的含义： （一）“违法行为人”，是指违反道路交通安全法律、行政法规规定的公民、法人及其他组织。 （二）“县级以上公安机关交通管理部门”，是指县级以上人民政府公安机关交通管理部门或者相当于同级的公安机关交通管理部门。“设区的市公安机关交通管理部门”，是指设区的市人民政府公安机关交通管理部门或者相当于同级的公安机关交通管理部门。"},{"i":78,"n":"第七十八条","txt":"交通技术监控设备记录的非机动车、行人违法行为参照本规定关于机动车违法行为处理程序处理。"},{"i":79,"n":"第七十九条","txt":"公安机关交通管理部门可以以电子案卷形式保存违法处理案卷。"},{"i":80,"n":"第八十条","txt":"本规定未规定的违法行为处理程序，依照《公安机关办理行政案件程序规定》执行。"},{"i":81,"n":"第八十一条","txt":"本规定所称“以上”“以下”，除特别注明的外，包括本数在内。 本规定所称的“二日”“三日”“五日”“七日”“十日”“十五日”，是指工作日，不包括节假日。"},{"i":82,"n":"第八十二条","txt":"执行本规定所需要的法律文书式样，由公安部制定。公安部没有制定式样，执法工作中需要的其他法律文书，各省、自治区、直辖市公安机关交通管理部门可以制定式样。"},{"i":83,"n":"第八十三条","txt":"本规定自2009年4月1日起施行。2004年4月30日发布的《道路交通安全违法行为处理程序规定》（公安部第69号令）同时废止。本规定生效后，以前有关规定与本规定不一致的，以本规定为准。"}],"daolujiaotonganquanweifaxingweijifenguanlibanfa":[{"i":1,"n":"第一条","txt":"为充分发挥记分制度的管理、教育、引导功能，提升机动车驾驶人交通安全意识，减少道路交通安全违法行为（以下简称交通违法行为），预防和减少道路交通事故，根据《中华人民共和国道路交通安全法》及其实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"公安机关交通管理部门对机动车驾驶人的交通违法行为，除依法给予行政处罚外，实行累积记分制度。"},{"i":3,"n":"第三条","txt":"记分周期为十二个月，满分为12分。记分周期自机动车驾驶人初次领取机动车驾驶证之日起连续计算，或者自初次取得临时机动车驾驶许可之日起累积计算。"},{"i":4,"n":"第四条","txt":"记分达到满分的，机动车驾驶人应当按照本办法规定参加满分学习、考试。"},{"i":5,"n":"第五条","txt":"在记分达到满分前，符合条件的机动车驾驶人可以按照本办法规定减免部分记分。"},{"i":6,"n":"第六条","txt":"公安机关交通管理部门应当通过互联网、公安机关交通管理部门业务窗口提供交通违法行为记录及记分查询。"},{"i":7,"n":"第七条","txt":"根据交通违法行为的严重程度，一次记分的分值为12分、9分、6分、3分、1分。"},{"i":8,"n":"第八条","txt":"机动车驾驶人有下列交通违法行为之一，一次记12分： （一）饮酒后驾驶机动车的； （二）造成致人轻伤以上或者死亡的交通事故后逃逸，尚不构成犯罪的； （三）使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的； （四）驾驶校车、公路客运汽车、旅游客运汽车载人超过核定人数百分之二十以上，或者驾驶其他载客汽车载人超过核定人数百分之百以上的； （五）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速百分之二十以上，或者驾驶其他机动车在高速公路、城市快速路上行驶超过规定时速百分之五十以上的； （六）驾驶机动车在高速公路、城市快速路上倒车、逆行、穿越中央分隔带掉头的； （七）代替实际机动车驾驶人接受交通违法行为处罚和记分牟取经济利益的。"},{"i":9,"n":"第九条","txt":"机动车驾驶人有下列交通违法行为之一，一次记9分： （一）驾驶7座以上载客汽车载人超过核定人数百分之五十以上未达到百分之百的； （二）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路以外的道路上行驶超过规定时速百分之五十以上的； （三）驾驶机动车在高速公路或者城市快速路上违法停车的； （四）驾驶未悬挂机动车号牌或者故意遮挡、污损机动车号牌的机动车上道路行驶的； （五）驾驶与准驾车型不符的机动车的； （六）未取得校车驾驶资格驾驶校车的； （七）连续驾驶中型以上载客汽车、危险物品运输车辆超过4小时未停车休息或者停车休息时间少于20分钟的。"},{"i":10,"n":"第十条","txt":"机动车驾驶人有下列交通违法行为之一，一次记6分： （一）驾驶校车、公路客运汽车、旅游客运汽车载人超过核定人数未达到百分之二十，或者驾驶7座以上载客汽车载人超过核定人数百分之二十以上未达到百分之五十，或者驾驶其他载客汽车载人超过核定人数百分之五十以上未达到百分之百的； （二）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速未达到百分之二十，或者在高速公路、城市快速路以外的道路上行驶超过规定时速百分之二十以上未达到百分之五十的； （三）驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路、城市快速路上行驶超过规定时速百分之二十以上未达到百分之五十，或者在高速公路、城市快速路以外的道路上行驶超过规定时速百分之五十以上的； （四）驾驶载货汽车载物超过最大允许总质量百分之五十以上的； （五）驾驶机动车载运爆炸物品、易燃易爆化学物品以及剧毒"},{"i":11,"n":"第十一条","txt":"机动车驾驶人有下列交通违法行为之一，一次记3分： （一）驾驶校车、公路客运汽车、旅游客运汽车、7座以上载客汽车以外的其他载客汽车载人超过核定人数百分之二十以上未达到百分之五十的； （二）驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路、城市快速路以外的道路上行驶超过规定时速百分之二十以上未达到百分之五十的； （三）驾驶机动车在高速公路或者城市快速路上不按规定车道行驶的； （四）驾驶机动车不按规定超车、让行，或者在高速公路、城市快速路以外的道路上逆行的； （五）驾驶机动车遇前方机动车停车排队或者缓慢行驶时，借道超车或者占用对面车道、穿插等候车辆的； （六）驾驶机动车有拨打、接听手持电话等妨碍安全驾驶的行为的； （七）驾驶机动车行经人行横道不按规定减速、停车、避让行人的； （八）驾驶机动车不按规定避让校车的； （九）驾驶载货汽车载物超过最大允许总质量百分之三十以上未达"},{"i":12,"n":"第十二条","txt":"机动车驾驶人有下列交通违法行为之一，一次记1分： （一）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路以外的道路上行驶超过规定时速百分之十以上未达到百分之二十的； （二）驾驶机动车不按规定会车，或者在高速公路、城市快速路以外的道路上不按规定倒车、掉头的； （三）驾驶机动车不按规定使用灯光的； （四）驾驶机动车违反禁令标志、禁止标线指示的； （五）驾驶机动车载货长度、宽度、高度超过规定的； （六）驾驶载货汽车载物超过最大允许总质量未达到百分之三十的； （七）驾驶未按规定定期进行安全技术检验的公路客运汽车、旅游客运汽车、危险物品运输车辆以外的机动车上道路行驶的； （八）驾驶擅自改变已登记的结构、构造或者特征的载货汽车上道路行驶的； （九）驾驶机动车在道路上行驶时，机动车驾驶人未按规定系安全带的； （十）驾驶摩托车，不戴安全头盔的。"},{"i":13,"n":"第十三条","txt":"公安机关交通管理部门对机动车驾驶人的交通违法行为，在作出行政处罚决定的同时予以记分。 对机动车驾驶人作出处罚前，应当在告知拟作出的行政处罚决定的同时，告知该交通违法行为的记分分值，并在处罚决定书上载明。"},{"i":14,"n":"第十四条","txt":"机动车驾驶人有二起以上交通违法行为应当予以记分的，记分分值累积计算。 机动车驾驶人可以一次性处理完毕同一辆机动车的多起交通违法行为记录，记分分值累积计算。累积记分未满12分的，可以处理其驾驶的其他机动车的交通违法行为记录；累积记分满12分的，不得再处理其他机动车的交通违法行为记录。"},{"i":15,"n":"第十五条","txt":"机动车驾驶人在一个记分周期期限届满，累积记分未满12分的，该记分周期内的记分予以清除；累积记分虽未满12分，但有罚款逾期未缴纳的，该记分周期内尚未缴纳罚款的交通违法行为记分分值转入下一记分周期。"},{"i":16,"n":"第十六条","txt":"行政处罚决定被依法变更或者撤销的，相应记分应当变更或者撤销。"},{"i":17,"n":"第十七条","txt":"机动车驾驶人在一个记分周期内累积记分满12分的，公安机关交通管理部门应当扣留其机动车驾驶证，开具强制措施凭证，并送达满分教育通知书，通知机动车驾驶人参加满分学习、考试。 临时入境的机动车驾驶人在一个记分周期内累积记分满12分的，公安机关交通管理部门应当注销其临时机动车驾驶许可，并送达满分教育通知书。"},{"i":18,"n":"第十八条","txt":"机动车驾驶人在一个记分周期内累积记分满12分的，应当参加为期七天的道路交通安全法律、法规和相关知识学习。其中，大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人应当参加为期三十天的道路交通安全法律、法规和相关知识学习。 机动车驾驶人在一个记分周期内参加满分教育的次数每增加一次或者累积记分每增加12分，道路交通安全法律、法规和相关知识的学习时间增加七天，每次满分学习的天数最多六十天。其中，大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人在一个记分周期内参加满分教育的次数每增加一次或者累积记分每增加12分，道路交通安全法律、法规和相关知识的学习时间增加三十天，每次满分学习的天数最多一百二十天。"},{"i":19,"n":"第十九条","txt":"道路交通安全法律、法规和相关知识学习包括现场学习、网络学习和自主学习。网络学习应当通过公安机关交通管理部门互联网学习教育平台进行。 机动车驾驶人参加现场学习、网络学习的天数累计不得少于五天，其中，现场学习的天数不得少于二天。大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人参加现场学习、网络学习的天数累计不得少于十天，其中，现场学习的天数不得少于五天。满分学习的剩余天数通过自主学习完成。 机动车驾驶人单日连续参加现场学习超过三小时或者参加网络学习时间累计超过三小时的，按照一天计入累计学习天数。同日既参加现场学习又参加网络学习的，学习天数不累积计算。"},{"i":20,"n":"第二十条","txt":"机动车驾驶人可以在机动车驾驶证核发地或者交通违法行为发生地、处理地参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识学习，并在学习地参加考试。"},{"i":21,"n":"第二十一条","txt":"机动车驾驶人在一个记分周期内累积记分满12分，符合本办法第十八条、第十九条第一款、第二款规定的，可以预约参加道路交通安全法律、法规和相关知识考试。考试不合格的，十日后预约重新考试。"},{"i":22,"n":"第二十二条","txt":"机动车驾驶人在一个记分周期内二次累积记分满12分或者累积记分满24分未满36分的，应当在道路交通安全法律、法规和相关知识考试合格后，按照《机动车驾驶证申领和使用规定》第四十四条的规定预约参加道路驾驶技能考试。考试不合格的，十日后预约重新考试。 机动车驾驶人在一个记分周期内三次以上累积记分满12分或者累积记分满36分的，应当在道路交通安全法律、法规和相关知识考试合格后，按照《机动车驾驶证申领和使用规定》第四十三条和第四十四条的规定预约参加场地驾驶技能和道路驾驶技能考试。考试不合格的，十日后预约重新考试。"},{"i":23,"n":"第二十三条","txt":"机动车驾驶人经满分学习、考试合格且罚款已缴纳的，记分予以清除，发还机动车驾驶证。机动车驾驶人同时被处以暂扣机动车驾驶证的，在暂扣期限届满后发还机动车驾驶证。"},{"i":24,"n":"第二十四条","txt":"满分学习、考试内容应当按照机动车驾驶证载明的准驾车型确定。"},{"i":25,"n":"第二十五条","txt":"机动车驾驶人处理完交通违法行为记录后累积记分未满12分，参加公安机关交通管理部门组织的交通安全教育并达到规定要求的，可以申请在机动车驾驶人现有累积记分分值中扣减记分。在一个记分周期内累计最高扣减6分。"},{"i":26,"n":"第二十六条","txt":"机动车驾驶人申请接受交通安全教育扣减交通违法行为记分的，公安机关交通管理部门应当受理。但有以下情形之一的，不予受理： （一）在本记分周期内或者上一个记分周期内，机动车驾驶人有二次以上参加满分教育记录的； （二）在最近三个记分周期内，机动车驾驶人因造成交通事故后逃逸，或者饮酒后驾驶机动车，或者使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌，或者使用其他机动车号牌、行驶证，或者买分卖分受到过处罚的； （三）机动车驾驶证在实习期内，或者机动车驾驶证逾期未审验，或者机动车驾驶证被扣留、暂扣期间的； （四）机动车驾驶人名下有安全技术检验超过有效期或者未按规定办理注销登记的机动车的； （五）在最近三个记分周期内，机动车驾驶人参加接受交通安全教育扣减交通违法行为记分或者机动车驾驶人满分教育、审验教育时，有弄虚作假、冒名顶替记录的。"},{"i":27,"n":"第二十七条","txt":"参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识网上学习三日内累计满三十分钟且考试合格的，一次扣减1分。 参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识现场学习满一小时且考试合格的，一次扣减2分。 参加公安机关交通管理部门组织的交通安全公益活动的，满一小时为一次，一次扣减1分。"},{"i":28,"n":"第二十八条","txt":"交通违法行为情节轻微，给予警告处罚的，免予记分。"},{"i":29,"n":"第二十九条","txt":"机动车驾驶人在一个记分周期内累积记分满12分，机动车驾驶证未被依法扣留或者收到满分教育通知书后三十日内拒不参加公安机关交通管理部门通知的满分学习、考试的，由公安机关交通管理部门公告其机动车驾驶证停止使用。"},{"i":30,"n":"第三十条","txt":"机动车驾驶人请他人代为接受交通违法行为处罚和记分并支付经济利益的，由公安机关交通管理部门处所支付经济利益三倍以下罚款，但最高不超过五万元；同时，依法对原交通违法行为作出处罚。 代替实际机动车驾驶人接受交通违法行为处罚和记分牟取经济利益的，由公安机关交通管理部门处违法所得三倍以下罚款，但最高不超过五万元；同时，依法撤销原行政处罚决定。 组织他人实施前两款行为之一牟取经济利益的，由公安机关交通管理部门处违法所得五倍以下罚款，但最高不超过十万元；有扰乱单位秩序等行为，构成违反治安管理行为的，依法予以治安管理处罚。"},{"i":31,"n":"第三十一条","txt":"机动车驾驶人参加满分教育时在签注学习记录、满分学习考试中弄虚作假的，相应学习记录、考试成绩无效，由公安机关交通管理部门处一千元以下罚款。 机动车驾驶人在参加接受交通安全教育扣减交通违法行为记分中弄虚作假的，由公安机关交通管理部门撤销相应记分扣减记录，恢复相应记分，处一千元以下罚款。 代替实际机动车驾驶人参加满分教育签注学习记录、满分学习考试或者接受交通安全教育扣减交通违法行为记分的，由公安机关交通管理部门处二千元以下罚款。 组织他人实施前三款行为之一，有违法所得的，由公安机关交通管理部门处违法所得三倍以下罚款，但最高不超过二万元；没有违法所得的，由公安机关交通管理部门处二万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"公安机关交通管理部门及其交通警察开展交通违法行为记分管理工作，应当接受监察机关、公安机关督察审计部门等依法实施的监督。 公安机关交通管理部门及其交通警察开展交通违法行为记分管理工作，应当自觉接受社会和公民的监督。"},{"i":33,"n":"第三十三条","txt":"交通警察有下列情形之一的，按照有关规定给予处分；警务辅助人员有下列情形之一的，予以解聘；构成犯罪的，依法追究刑事责任： （一）当事人对实施处罚和记分提出异议拒不核实，或者经核实属实但不纠正、整改的； （二）为未经满分学习考试、考试不合格人员签注学习记录、合格考试成绩的； （三）在满分考试时，减少考试项目、降低评判标准或者参与、协助、纵容考试舞弊的； （四）为不符合记分扣减条件的机动车驾驶人扣减记分的； （五）串通他人代替实际机动车驾驶人接受交通违法行为处罚和记分的； （六）弄虚作假，将记分分值高的交通违法行为变更为记分分值低或者不记分的交通违法行为的； （七）故意泄露、篡改系统记分数据的； （八）根据交通技术监控设备记录资料处理交通违法行为时，未严格审核当事人提供的证据材料，导致他人代替实际机动车驾驶人接受交通违法行为处罚和记分，情节严重的。"},{"i":34,"n":"第三十四条","txt":"公安机关交通管理部门对拖拉机驾驶人予以记分的，应当定期将记分情况通报农业农村主管部门。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市公安厅、局可以根据本地区的实际情况，在本办法规定的处罚幅度范围内，制定具体的执行标准。 对本办法规定的交通违法行为的处理程序按照《道路交通安全违法行为处理程序规定》执行。"},{"i":36,"n":"第三十六条","txt":"本办法所称“三日”“十日”“三十日”，是指自然日。期间的最后一日为节假日的，以节假日期满后的第一个工作日为期间届满的日期。"},{"i":37,"n":"第三十七条","txt":"本办法自2022年4月1日起施行。"}],"jinrongjigouyingyechangsuohejinkuanquanfangfanshes0def9d":[{"i":1,"n":"第一条","txt":"为了保障银行和其他金融机构营业场所、金库的安全，规范公安机关的相关许可工作，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》等有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内新建、改建金融机构营业场所、金库的，实行安全防范设施建设许可制度。 本办法所称金融机构营业场所，是指银行和其他金融机构办理现金出纳、有价证券、会计结算等业务的物理区域，包括自助服务银行营业场所和自动柜员机。 本办法所称金库，是指银行和其他金融机构存放现金、有价证券、重要凭证、金银等贵重物品的库房，包括保安押运公司自建金库。"},{"i":3,"n":"第三条","txt":"各级人民政府公安机关治安管理部门具体负责组织实施本办法。"},{"i":4,"n":"第四条","txt":"金融机构营业场所、金库安全防范设施建设方案审批和工程验收实行“属地管理、分级审批”的原则，由县级以上人民政府公安机关负责实施。 各省、自治区、直辖市人民政府公安厅、局可以根据金融机构营业场所、金库的风险等级和防护级别等情况，结合本地区实际，确定本行政区域具体负责实施的公安机关，报公安部备案，并向社会公布。"},{"i":5,"n":"第五条","txt":"公安机关治安管理部门应当组织专家组，依据《银行营业场所风险等级和防护级别的规定》（GA38-2004）、《银行金库》（JR/T0003-2000）、《安全技术规范》（GB50348-2004）、《安全工程程序与要求》（GA/T75）等标准开展审批和验收工作。 各省、自治区、直辖市公安厅、局治安管理部门应当建立由公安机关治安、内保、科技民警和金融机构的保卫、业务干部以及安全防范技术、计算机、电子等行业具有国家认可的专业资格的专家组成的专家库，参与本地区公安机关实施的审批和验收工作。 专家组应当由5名或者7名专家组成，组长由公安机关治安管理部门指定。专家组成员对所提出的审批验收意见负责。"},{"i":6,"n":"第六条","txt":"申请金融机构营业场所、金库安全防范设施建设许可的，应当向公安机关书面提出。申请人可以到公安机关提出申请，也可以通过信函、传真、电子邮件等形式提出申请。 具体负责审批的公安机关应当公布申请渠道，为申请人领取或者下载申请金融机构营业场所、金库安全防范设施建设许可的审批表格提供方便条件。"},{"i":7,"n":"第七条","txt":"新建、改建金融机构营业场所、金库前，申请人应当填写《新建、改建金融机构营业场所/金库安全防范设施建设方案审批表》，并附以下材料： （一）金融监管机构和金融机构上级主管部门有关金融机构营业场所、金库建设的批准文件； （二）安全防范设施建设工程设计方案或者任务书； （三）技防设施安装平面图、管线敷设图、监控室布置图、物防设施设计结构图； （四）安全防范工程设计施工单位营业执照和相关资质证明； （五）安全产品检验报告、国家强制性产品认证证书或者安全技术产品生产登记批准书； （六）金库、保管箱库设计、施工人员身份证件复印件及其所从事工种的说明； （七）运钞车停靠位置和营业场所、金库周边环境平面图； （八）房产租赁或者产权合同复印件和租赁双方签订的安全协议书复印件。"},{"i":8,"n":"第八条","txt":"公安机关治安管理部门应当在收到申请后的10个工作日内组织专家组，对安全防范设施建设方案进行论证和审查，确定风险等级和相应的防护级别。 专家组应当按照少数服从多数的原则提出意见，并由参与论证和审查的专家签名后，报公安机关治安管理部门审核。 公安机关治安管理部门应当在收到专家组意见后的5日内提出审核意见，报本级公安机关负责人审批。本级公安机关负责人应当在5日内提出审批意见。"},{"i":9,"n":"第九条","txt":"公安机关对符合条件的，应当批准，并书面通知申请人准予施工；对不符合条件的，不予批准，并书面向申请人说明理由。 对不予批准的，申请人整改后，可以按照本办法重新提出申请。"},{"i":10,"n":"第十条","txt":"新建、改建金融机构营业场所、金库工程竣工后，申请人应当向原审批安全防范设施建设方案的公安机关书面提出验收申请，填写《金融机构营业场所/金库安全防范设施建设工程验收审批表》。"},{"i":11,"n":"第十一条","txt":"公安机关治安管理部门应当在收到验收申请后的10个工作日内组织专家组完成验收工作。专家组应当按照少数服从多数的原则提出意见，并由参与验收的专家签名后，报公安机关治安管理部门审核。 公安机关治安管理部门应当在收到专家组意见后的5日内提出审核意见，报本级公安机关负责人审批。本级公安机关负责人应当在5日内提出审批意见。"},{"i":12,"n":"第十二条","txt":"公安机关对验收合格的，应当批准，并发给《安全防范设施合格证》；对验收不合格的，不予批准，并书面向申请人说明理由。 对验收不合格的，申请人整改后，可以按照本办法重新申请验收。"},{"i":13,"n":"第十三条","txt":"公安机关应当坚持公开、公平、公正的原则，严格依照本办法的规定，对金融机构营业场所、金库的安全防范设施建设方案进行审批和工程验收，并建立审批和发证管理档案。"},{"i":14,"n":"第十四条","txt":"公安机关应当监督、指导金融机构严格执行安全防范设施建设的有关规定，督促金融机构营业场所、金库安全防范设施的建设和使用单位建立相应的自检制度。"},{"i":15,"n":"第十五条","txt":"公安机关应当加强对金融机构安全防范设施的日常安全检查工作，发现金融机构安全防范设施建设、使用存在治安隐患的，应当立即责令限期整改，并依照《企业事业单位内部治安保卫条例》第十九条的规定予以处罚。"},{"i":16,"n":"第十六条","txt":"违反本办法的规定，金融机构营业场所、金库安全防范设施建设方案未经批准而擅自施工的，公安机关应当责令其停止施工并按照本办法报批，同时对单位处5000元以上2万元以下罚款，对直接负责的主管人员和其他直接责任人员处200元以上1000元以下罚款。"},{"i":17,"n":"第十七条","txt":"违反本办法的规定，在金融机构营业场所、金库安全防范设施建设工程未经验收即投入使用的，公安机关应当责令金融机构按照本办法报批，并对单位处1万元以上3万元以下罚款，对直接负责的主管人员和其他直接责任人员处200元以上1000元以下罚款。同时，可以建议其上级主管部门对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"公安机关及其人民警察在办理审批和验收工作中，有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对明知是不符合标准的金融机构营业场所、金库安全防范设施建设方案予以批准，或者擅自发放《安全防范设施合格证》的； （二）除不可抗力外，不按照本办法规定的时限办理审批和验收的； （三）利用职权故意刁难申请人、施工单位，索取、收受贿赂或者谋取其他利益的； （四）实施其他滥用职权、玩忽职守、徇私舞弊行为的。"},{"i":19,"n":"第十九条","txt":"本办法规定的《安全防范设施合格证》和其他文书式样由公安部制定，各省、自治区、直辖市公安厅、局自行印制。 《安全防范设施合格证》分为牌匾和纸质证书两种。牌匾应当悬挂在金融机构营业场所显著位置，纸质证书由金融机构保存。"},{"i":20,"n":"第二十条","txt":"本办法自2006年2月1日起施行。"}]};
